// Ngân hàng toàn bộ câu hỏi MLN111, MLN122, HCM202 dùng cho tra cứu nhanh và Modal xem câu hỏi
(function() {
  const root = (typeof window !== 'undefined') ? window : global;
  root.CARDS_DB = {
    mln111: [{"id":1,"question":"Xanh-ximông là đại biểu của trường phải nào?","options":["A. Chủ nghĩa xã hội không tưởng Pháp","B. Chủ nghĩa xã hội không tưởng Đức","C. Triết học cổ điển Đức","D. Kinh tế chính trị học Anh"],"answerLetter":"A","answerText":"A. Chủ nghĩa xã hội không tưởng Pháp","notes":""},{"id":2,"question":"Quan hệ giữa người với người trong quá trình sản xuất được gọi là gì?","options":["A. Quan hệ xã hội","B. Quan hệ tổ chức quản lý","C. Quan hệ điều tiết"],"answerLetter":"C","answerText":"C. Quan hệ điều tiết","notes":""},{"id":3,"question":"Một sinh viên tóm tắt nội dung quy luật về sự phủ hợp giữa quan hệ sản xuất với trình độ của như sau. Đáp án nào sau đây là đúng?","options":["A. Quy luật này vạch rõ sự phụ thuộc khách quan của lực lượng sản xuất vào quan hệ sản xuất","B. Sự hình thành, biến đổi và phát triển của quan hệ sản xuất được quyết định bởi lực lượng","C. Lực lượng sản xuất và quan hệ sản xuất là hai mặt của phương thức sản xuất, chúng tồn tại","D. Quy luật này chỉ tồn tại trong một vài xã hội"],"answerLetter":"B","answerText":"B. Sự hình thành, biến đổi và phát triển của quan hệ sản xuất được quyết định bởi lực lượng","notes":""},{"id":4,"question":"Tri thức nào sau đây nảy sinh một cách trực tiếp từ thực tiễn lao động sản xuất?","options":["A. Tri thức kinh nghiệm","B. Tri thức lý luận","C. Tri thức lý luận khoa học","D. Tri thức lý luận thực tiễn"],"answerLetter":"A","answerText":"A. Tri thức kinh nghiệm","notes":""},{"id":5,"question":"Theo V.I.Lênin. Quan điểm về đời sống, về thực tiễn phải là...của lý luận nhận thức:","options":["A. Điểm thứ nhất","B. Quan điểm đầu tiên","C. Quan điểm thứ nhất và cơ bản","D. Điều quan trọng"],"answerLetter":"C","answerText":"C. Quan điểm thứ nhất và cơ bản","notes":""},{"id":6,"question":"Công lao của C.Mác và Ph.Ăngghen với nhận thức là gì?","options":["A. Phát hiện ra thế giới khách quan","B. Đưa phương pháp luận vào nhận thức","C. Đưa thực tiễn vào triết học","D. Đề ra tư tưởng đấu tranh chống lại giai cấp tư sản"],"answerLetter":"C","answerText":"C. Đưa thực tiễn vào triết học","notes":""},{"id":7,"question":"Nhận thức cảm tính được thực hiện dưới những hình thức nào?","options":["A. Tri giác, phán đoán và suy luận","B. Cảm giác, tri giác và khái niệm","C. Cảm giác, tri giác và biểu tượng","D. Khái niệm và phán đoán"],"answerLetter":"C","answerText":"C. Cảm giác, tri giác và biểu tượng","notes":""},{"id":8,"question":"Đứng im, cân bằng chi xảy ra trong một số quan hệ nhất định chứ không phải trong mọi quan hệ là:","options":["A. Thực tế","B. Tuyệt đối","C. Tương đối","D. Thường xuyên"],"answerLetter":"C","answerText":"C. Tương đối","notes":""},{"id":9,"question":"A là một sinh viên có học lực kém, nên gia đình và Thầy/Cô đã khuyên A nên cố gắng nhiều thấy được vấn đề, A đã ra sức học tập để tích lũy kiến thức, trải qua một khoảng thời gian bạn thành một học sinh giỏi mà còn đạt được học bổng do Đại học FPT cung cấp. Căn cứ vào kiến thức ở môn Triết học, Anh/Chị hãy cho biết trường hợp bạn A thuộc 1 trong 3 quy luật nào sau đây","options":["A. Quy luật từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","B. Quy luật thống nhất và đấu tranh giữa các mặt đối lập","C. Quy luật phủ định của phủ định","D. Quy luật phát triển"],"answerLetter":"A","answerText":"A. Quy luật từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","notes":"(Kiểu hỏi khác: Tính chất nào của đứng im khi nói đứng im, cân bằng chi xảy ra trong một số quan hệ nhất định chữ không phải trong mọi quan hệ?)"},{"id":10,"question":"Đâu là một phát minh vĩ đại của C.Mác đã đem lại một cuộc cách mạng trong triết học về xã hội","options":["A. Chủ nghĩa duy vật lịch sử","B. Chủ nghĩa duy tâm khách quan","C. Chủ nghĩa duy tâm chủ quan","D. Chủ nghĩa duy vật chất phát"],"answerLetter":"A","answerText":"A. Chủ nghĩa duy vật lịch sử","notes":""},{"id":11,"question":"Sự khác biệt cơ bản nhất giữa các giai cấp là địa vị của họ trong","options":["A. Quyền lực chính trị","B. Quyền lực nhà nước","C. Quyền lực quản lý kinh tế","D. Quyền lực sở hữu tư liệu sản xuất"],"answerLetter":"D","answerText":"D. Quyền lực sở hữu tư liệu sản xuất","notes":""},{"id":12,"question":"Thuyết có thể biết còn gọi là gì?","options":["A. Thuyết nhận biết","B. Thuyết khả tri","C. Thuyết khả tri luận","D. Thuyết nhận biết luận"],"answerLetter":"C","answerText":"C. Thuyết khả tri luận","notes":"(Hoặc còn gọi là khả tri-&gt;Không thể biết là bất khả tri luận)"},{"id":13,"question":"Nhân tố quyết định xu hướng phát triển của các hình thái kinh tế - xã hội là","options":["A. Ý thức của gia cấp nắm quyền lực nhà nước","B. Ý trí của nhân dân","C. Quy luật khách quan","D. Điều kiện khách quan và chủ quan của mỗi xã hội"],"answerLetter":"C","answerText":"C. Quy luật khách quan","notes":""},{"id":14,"question":"Khi quan hệ sản xuất được xem là phù hợp với tính chất và trình độ phát triển của lực lượng sản xuất?","options":["A. Thúc đẩy lực lượng sản xuất phát triển","B. Cải thiện đời sống nhân dân","C. Tạo điều kiện thực hiện công bằng xã hội","D. Yêu cầu phải thay thế lực lượng sản xuất mới"],"answerLetter":"A","answerText":"A. Thúc đẩy lực lượng sản xuất phát triển","notes":""},{"id":15,"question":"Theo cách phân chia các hình thức vận động của Ph.Ăngghen, hình thức vận động nào là thấp nhất, đơn giản nhất?","options":["A. Hình thức vận động cơ học","B. Hình thức vận động vật lý","C. Hình thức vận động hoá học","D. Hình thức vận động xã hội"],"answerLetter":"A","answerText":"A. Hình thức vận động cơ học","notes":"(Kiểu hỏi khác: Khi nào quan hệ sản xuất được xem là phù hợp với tính chất và trình độ phát triên của lực lượng sản xuất thì điều gì sẽ xày ra?)"},{"id":16,"question":"Luận điểm sau thuộc lập trường triết học nào: Quy luật trong các khoa học là sự sáng tạo chủ quan của con người và được áp dụng vào tự nhiên và xã hội.","options":["A. Chủ nghĩa duy vật siêu hình","B. Chủ nghĩa duy tâm khách quan","C. Chủ nghĩa duy vật biện chứng","D. Chủ nghĩa duy tâm chủ quan"],"answerLetter":"D","answerText":"D. Chủ nghĩa duy tâm chủ quan","notes":""},{"id":17,"question":"Theo quan điểm duy vật lịch sử, sự ra đời của nhà nước là để giải quyết các mâu thuẫn trong xã hội vì:","options":["A. Xã hội có mâu thuẫn thì cần phải có lực lượng đại diện cho xã hội để giải quyết nó","B. Kinh nghiệm thực tế cho thấy đúng như vậy","C. Nếu mâu thuẫn có thể giải quyết được thì không cần đến sự ra đời của nhà nước, sự ra đời của nó chỉ chứng tỏ rằng mâu thuẫn đã phát triễn đến chỗ không thể giải quyết được nên cần đến sự ra đời của nhà nước.","D. Tất yếu của lịch sử nhân loại"],"answerLetter":"C","answerText":"C. Nếu mâu thuẫn có thể giải quyết được thì không cần đến sự ra đời của nhà nước, sự ra đời của nó chỉ chứng tỏ rằng mâu thuẫn đã phát triễn đến chỗ không thể giải quyết được nên cần đến sự ra đời của nhà nước.","notes":""},{"id":18,"question":"Chủ nghĩa duy vật lịch sử cho rằng, ý thức lý luận đạt trình độ cao và mang tính hệ thống tạo thành các:","options":["A. Hệ tư tưởng","B. Hệ kiến thức","C. Tri thức tổng hợp","D. Hệ thống tri thức"],"answerLetter":"A","answerText":"A. Hệ tư tưởng","notes":""},{"id":19,"question":"Chọn câu trả lời sai: Trong một hình thái kinh tế xã hội, quan hệ sản xuất có vai trò sau đây.","options":["A. Là quan hệ cơ bản, quyết định tất cả các quan hệ xã hội khác","B. Là cơ sở kinh tế của các hiện tượng xã hội","C. Thể hiện tính liên tục trong sự phát triển của xã hội loài người","D. Tiêu biểu cho bộ mặt xã hội ở mỗi giai đoạn phát triển nhất định"],"answerLetter":"C","answerText":"C. Thể hiện tính liên tục trong sự phát triển của xã hội loài người","notes":""},{"id":20,"question":"Triết học có mấy vấn đề? Trong vấn đề có mấy mặt?","options":["A. 1 mặt, 2 vấn đề","B. 1 vấn đề, 1 mặt","C. 1 vấn đề, 2 mặt","D. 2 mặt, 2 vấn đề"],"answerLetter":"C","answerText":"C. 1 vấn đề, 2 mặt","notes":""},{"id":21,"question":"Nguyên nhân là phạm trù triết học chỉ","options":["A. Tác động qua lại giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật khia tạo ra những biến đổi nhất định","B. Quan hệ giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật kia tạo nhất định","C. Sự chuyển hóa giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật k biến đổi nhất định"],"answerLetter":"A","answerText":"A. Tác động qua lại giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật khia tạo ra những biến đổi nhất định","notes":""},{"id":22,"question":"Điều khẳng định nào sau đây đúng về mối quan hệ giữa lý luận và kinh nghiệm?","options":["A. Lý luận được hình thành từ kinh nghiệm trên cơ sở kinh nghiệm","B. Kinh nghiệm nhiều tự phát dẫn đến sự ra đời của lý luận","C. Mọi lý luận đều được xuất phát từ kinh nghiệm","D. Lý luận đi trước kinh nghiệm"],"answerLetter":"A","answerText":"A. Lý luận được hình thành từ kinh nghiệm trên cơ sở kinh nghiệm","notes":""},{"id":23,"question":"Điều kiện cơ bản để ý thức xã hội tác động trở lại tồn tại xã hội là","options":["A. Ý thức xã hội phải vượt trước tồn tại xã hội","B. Ý thức xã hội phải phù hợp với tồn tại xã hội","C. Phải có hoạt động thực tiễn của con người","D. Phải có điều kiện vật chất bảo đảm"],"answerLetter":"C","answerText":"C. Phải có hoạt động thực tiễn của con người","notes":""},{"id":24,"question":"Ai là người khẳng định \"cái sự hiển nhiên là trước hết con người cần phải ăn, uống, ở và mặ động, trước khi có thể đấu tranh để giành quyền thống trị, trước khi có thể hoạt động chính tr học...\".","options":["A. C.Mác","B. Ph.Ăngghen","C. Platon","D. Immanuel Kant"],"answerLetter":"B","answerText":"B. Ph.Ăngghen","notes":""},{"id":25,"question":"Quan điểm của chủ nghĩa Mác-Lênin về lãnh tụ là","options":["A. Tất cả các đáp án đều đúng","B. Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân","C. Những cá nhân kiệt xuất được quần chúng tín nhiệm","D. Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân"],"answerLetter":"A","answerText":"A. Tất cả các đáp án đều đúng","notes":""},{"id":26,"question":"Trên mạng xã hội hiện nay như Facebook, TikTok... đã xuất hiện nhiều nhân vật không có ch khi phát ngôn, lối sống của họ đã bị chi phối bởi những điều tiêu cực và trở nên lệch chuẩn, thuần phong mỹ tục, truyền thống văn hóa của dân tộc Việt Nam để câu View, câu like. Theo Anh/chị là hiện tượng gì đã đề cập trong nội dung môn triết học mà Anh/Chị đã học và nghiên cứu qua","options":["A. Hiện tượng câu Like, câu View trên mạng xã hội","B. Hiện tượng xem thường người khác","C. Hiện tượng tha hóa con người","D. Hiện tượng xã hội"],"answerLetter":"C","answerText":"C. Hiện tượng tha hóa con người","notes":""},{"id":27,"question":"Trong quá trình nhận thức và hoạt động thực tiễn, chúng ta cần","options":["A. Phủ nhận, gạt bỏ cái ngẫu nhiên","B. Cơ bản là phải căn cứ vào cái ngẫu nhiên nhưng đồng thời phải tính tới cái tất nhiên","C. Căn cứ vào cái tất nhiên và ngẫu nhiên","D. Cơ bản là phải căn cứ vào cái tất nhiên nhưng đồng thời phải tính tới cái ngẫu nhiên"],"answerLetter":"D","answerText":"D. Cơ bản là phải căn cứ vào cái tất nhiên nhưng đồng thời phải tính tới cái ngẫu nhiên","notes":""},{"id":28,"question":"Theo quan điểm của triết học Mác - Lênin, \"tồn tại xã hội\" bao gồm:","options":["A. Dân số, ý thức xã hội, kiến trúc thượng tầng","B. Lực lượng sản xuất, dân số, phương thức sản xuất, ý thức xã hội","C. Môi trường tự nhiên, quan hệ sản xuất, tâm lý xã hội, hệ tư tưởng","D. Môi trường tự nhiên, dân số, phương thức sản xuất"],"answerLetter":"D","answerText":"D. Môi trường tự nhiên, dân số, phương thức sản xuất","notes":"(Kiểu hỏi khác: Trong các đáp án dưới đây, đáp án nào là một yêu cầu trong quá trình nhận thức và thực tiễn?)"},{"id":29,"question":"Đâu là một trong những trường phái của triết học duy tâm?","options":["A. Duy tâm khách quan","B. Duy tâm duy lý","C. Duy tâm biện chứng","D. Duy tâm tôn giáo"],"answerLetter":"A","answerText":"A. Duy tâm khách quan","notes":""},{"id":30,"question":"Một trong những nguồn gốc ra đời của Triết học là","options":["A. Tự nhiên","B. Lao động","C. Ngôn ngữ","D. Xã hội"],"answerLetter":"D","answerText":"D. Xã hội","notes":""},{"id":31,"question":"Một trong những nguyên nhân ra đời của triết học là:","options":["A. Tâm lý.","B. Tư tưởng.","C. Nhận thức","D. Tự nhiên."],"answerLetter":"C","answerText":"C. Nhận thức","notes":""},{"id":32,"question":"Hạt nhân cơ bản trong quần chúng nhân dân là ai?","options":["A. Những người lao động sản xuất ra của cải vật chất","B. Những bộ phận dân cư chống lại giai cấp thống trị áp bức bóc lột, đối kháng với nhân dân","C. Những tầng lớp xã hội khác nhau thúc đẩy sự tiến bộ của xã hội","D. Những tầng lớp dân cư lao động"],"answerLetter":"A","answerText":"A. Những người lao động sản xuất ra của cải vật chất","notes":""},{"id":33,"question":"Ý thức được gọi là hình ảnh chủ quan của","options":["A. Hiện thực khách quan","B. Thế giới khách quan","C. Thế giới chủ quan","D. Thế giới vật chất"],"answerLetter":"B","answerText":"B. Thế giới khách quan","notes":""},{"id":34,"question":"Chân lý là gì?","options":["A. Ý kiến của những người có kinh nghiệm","B. Sự phù hợp giữa tri thức với hiện thực khách quan và được thực tiễn kiểm nghiệm","C. Những quan điểm thuộc về đa số","D. Là những thứ đúng đắn trong khoa học"],"answerLetter":"B","answerText":"B. Sự phù hợp giữa tri thức với hiện thực khách quan và được thực tiễn kiểm nghiệm","notes":""},{"id":35,"question":"Triết học Mác-Lênin ra đời một phần là kết quả kế thừa trực tiếp từ","options":["A. Thế giới quan duy vật của Hêghen và phép biện chứng của Phoiobắc","B. Thế giới quan duy vật của Phơ bách và phép biện chứng của Hêghen","C. Thế giới quan duy vật và phép biện chúng của cả Hêghen và Phơ bách","D. Chủ nghĩa duy tâm của Hồn bách và biện chứng pháp của Aristốt"],"answerLetter":"B","answerText":"B. Thế giới quan duy vật của Phơ bách và phép biện chứng của Hêghen","notes":"(Kiểu hỏi khác: Chân lý là A. Sự thật mà ai cũng biết. B. Lẽ phải ai cũng thừa nhận. C. Tri thức phù hợp với logic suy luận. D. Tri thức có nội dung chân thực và đã được thực tiễn kiểm nghiệm.)"},{"id":36,"question":"Khái niệm cơ sở hạ tầng là dùng để chỉ","options":["A. Quan hệ kinh kế của xã hội","B. Kết cấu vật chất - kỹ thuật làm cơ sở để phát triển kinh tế","C. Quan hệ sản xuất của xã hội","D. Quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội"],"answerLetter":"D","answerText":"D. Quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội","notes":""},{"id":37,"question":"Điền cụm từ thích hợp vào chỗ (..): \"Không thể đem lại cho hai khái niệm ... này một định nghĩa cách chỉ rõ rằng trong hai khái niệm đó, cãi nào được coi là có trước\".","options":["A. Nhận thức luận","B. Bản thể luận","C. Nhất nguyên luận","D. Nhị nguyên luận"],"answerLetter":"A","answerText":"A. Nhận thức luận","notes":""},{"id":38,"question":"Theo quan điểm của triết học Mác - Lênin, luận điểm nào sau đây chưa chính xác khi đề cập giữa tồn tại xã hội và ý thức xã hội?","options":["A. Một bộ phận ý thức xã hội có thể vượt trước tồn tại xã hội","B. Ý thức xã hội mang tính kế thừa","C. Ý thức xã hội luôn thay đổi ngay lập tức khi tồn tại xã hội thay đổi","D. Ý thức xã hội thường lạc hậu, bảo thủ so với tồn tại xã hội"],"answerLetter":"C","answerText":"C. Ý thức xã hội luôn thay đổi ngay lập tức khi tồn tại xã hội thay đổi","notes":""},{"id":39,"question":"Thales, Heraclitus, Anaximenes là những đại biểu thuộc trường phải nào?","options":["A. Chủ nghĩa duy tâm chủ quan","B. Chủ nghĩa duy vật chất phác","C. Chủ nghĩa duy tâm khách quan","D. Chủ nghĩa duy vật biện chứng trước Mác"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy vật chất phác","notes":""},{"id":40,"question":"Trong lực lượng sản xuất, đâu là yếu tố động nhất, cách mạng nhất?","options":["A. Công cụ lao động","B. Bộ óc con người","C. Con người lao động","D. Tư liệu sản xuất"],"answerLetter":"A","answerText":"A. Công cụ lao động","notes":""},{"id":41,"question":"Triết học nghiên cứu thế giới như thế nào?","options":["A. Như một đối tượng vật chất cụ thể","B. Như một hệ đối tượng vật chất nhất định","C. Như một chỉnh thể thống nhất"],"answerLetter":"C","answerText":"C. Như một chỉnh thể thống nhất","notes":""},{"id":42,"question":"Quan điểm nào sau đây cho rằng các sự vật, hiện tượng, các quá trình khác nhau vừa tồn tại định, tác động qua lại, chuyển hóa lẫn nhau?","options":["A. Quan điểm siêu hình","B. Quan điểm biện chứng","C. Quan điểm duy tâm","D. Quan điểm duy vật"],"answerLetter":"B","answerText":"B. Quan điểm biện chứng","notes":""},{"id":43,"question":"Chức năng, nhiệm vụ của nhà nước xã hội chủ nghĩa biểu hiện tập trung ở việc quản lý xã hộ lĩnh vực bằng.","options":["A. Khoa học","B. Công cụ tiền","C. Pháp luật","D. Kế hoạch"],"answerLetter":"C","answerText":"C. Pháp luật","notes":"(Kiểu hỏi khác: Theo quan điểm duy vật biện chứng, nguyên nhân và kết quả có thể... A. chuyễn hóa lẫn nhau. B. tồn tại độc lập với nhau. C. xuất hiện đồng thời. D. không có mỗi liên hệ qua lại.)"},{"id":44,"question":"Triết học phổ biến ở Tây Âu thời Trung cổ là Triết học gì?","options":["A. Triết học tự nhiên","B. Triết học kinh viện","C. Triết học khoa học xã hội","D. Triết học chính trị"],"answerLetter":"B","answerText":"B. Triết học kinh viện","notes":""},{"id":45,"question":"Theo quan điểm của duy vật về lịch sử, nhân tố quyết định trong lịch sử xét đến cùng là gì?","options":["A. Lao động, tái sản xuất ra con người","B. Sở hữu về tư liệu sản xuất, phân phối sản phẩm","C. Kết cấu xã hội, giai cấp","D. Sự sản xuất và tái sản xuất ra đời sống hiện thực"],"answerLetter":"D","answerText":"D. Sự sản xuất và tái sản xuất ra đời sống hiện thực","notes":""},{"id":46,"question":"Thuyết bất khả tri còn gọi là gì?","options":["A. Thuyết không thể biết","B. Thuyết khả tri","C. Thuyết khả tri luận","D. Thuyết nhận biết luận"],"answerLetter":"A","answerText":"A. Thuyết không thể biết","notes":""},{"id":47,"question":"Điền vào dấu \"...là tổng hợp những mặt, những yếu tố trong quá trình tạo nên sự vật\":","options":["A. Khả năng","B. Hiện thực","C. Nội dung","D. Hình thức"],"answerLetter":"C","answerText":"C. Nội dung","notes":""},{"id":48,"question":"Yếu tố chủ thể của lực lượng sản xuất là","options":["A. Con người với kỹ năng, kỹ xảo và tri thức được tích luỹ lại","B. Tư liệu sản xuất hiện đại","C. Khoa học công nghệ tiên tiến","D. Các phương án trả lời đều đúng"],"answerLetter":"A","answerText":"A. Con người với kỹ năng, kỹ xảo và tri thức được tích luỹ lại","notes":""},{"id":49,"question":"Nội dung trước tiên của cách mạng xã hội chủ nghĩa là phải giành chính quyền về tay giai cấp công nhân, nhân dân lao động, đưa những người lao động","options":["A. Thành người lao động tập thể","B. Làm chủ tư liệu sản xuất","C. Thành người quản lý xã hội","D. Lên địa vị làm chủ xã hội"],"answerLetter":"D","answerText":"D. Lên địa vị làm chủ xã hội","notes":""},{"id":50,"question":"Chủ nghĩa duy vật lịch sử cho rằng sự ra đời, tồn tại của nhà nước là để duy trì trật tự xã hội mâu thuẫn giai cấp như thế nào?","options":["A. Đi đến giải quyết","B. Phải được giải quyết","C. Có thể giải quyết","D. Không thể điều hòa được"],"answerLetter":"D","answerText":"D. Không thể điều hòa được","notes":""},{"id":51,"question":"Hạt nhân lý luận của thế giới quan khoa học là chủ nghĩ","options":["A. A. Duy vật","B. Mác","C. Duy vật biện chứng","D. Lênin"],"answerLetter":"C","answerText":"C. Duy vật biện chứng","notes":""},{"id":52,"question":"Chủ nghĩa Mác-Lênin ra đời dựa trên bao nhiêu tiền đề?","options":["A. Ba tiền đề","B. Bốn tiền đề","C. Năm tiền đề","D. Sáu tiền đề"],"answerLetter":"A","answerText":"A. Ba tiền đề","notes":""},{"id":53,"question":"Điều kiện cần và đủ để sinh ra ý thức là gì?. Chọn 3 đáp án đúng.","options":["A. Nghiên cứu khoa học","B. Lao động, ngôn ngữ","C. Bộ óc người","D. Các sự vật, hiện tượng trong thế giới khách quan"],"answerLetter":"BCD","answerText":"B. Lao động, ngôn ngữ\nC. Bộ óc người\nD. Các sự vật, hiện tượng trong thế giới khách quan","notes":""},{"id":54,"question":"Theo Lênin, khách quan là cái đang tồn tại","options":["A. Phụ thuộc nhận thức con người","B. Trong thế giới con người","C. Trong thế giới tự nhiên","D. Độc lập, không phụ thuộc vào ý thức"],"answerLetter":"D","answerText":"D. Độc lập, không phụ thuộc vào ý thức","notes":""},{"id":55,"question":"Sự phân chia giai cấp trong xã hội bắt đầu từ hình thái kinh tế - xã hội nào?","options":["A. Cộng sản nguyên thủy","B. Tư bản chủ nghĩa","C. Phong kiến","D. Chiếm hữu nô lệ"],"answerLetter":"D","answerText":"D. Chiếm hữu nô lệ","notes":""},{"id":56,"question":"Xét đến cùng, mục đích của sự sản xuất xã hội là để làm gì?","options":["A. Sản xuất ra của cải vật chất","B. Sản xuất và tái sản xuất ra đời sống hiện thực","C. Sản xuất ra con người, nuôi sống con người","D. Sản xuất ra con người"],"answerLetter":"B","answerText":"B. Sản xuất và tái sản xuất ra đời sống hiện thực","notes":""},{"id":57,"question":"Nguyên lý về sự phát triển là cơ sở khoa học để định hướng cho nhận thức và cải tạo thế giới. Theo đó, trong hoạt động nhận thức và hoạt động thực tiễn con người phải đặt sự vật, hiện tượng theo khuynh hướng:","options":["A. Đi thẳng","B. Đi lên của nó","C. Không tụt lùi","D. Vận động"],"answerLetter":"B","answerText":"B. Đi lên của nó","notes":""},{"id":58,"question":"Vai trò của lãnh tụ đối với phong trào của quần chúng nhân dân?","options":["A. Thúc đẩy hoặc kìm hãm sự tiến bộ của xã hội","B. Là người sáng lập ra các tổ chức chính trị, xã hội và là linh hồn của các tổ chức đó","C. Lãnh tụ của mỗi thời đại chỉ có thể hoàn thành những nhiệm vụ đặt ra của thời đại đó","D. Tất cả các đáp án đều đúng"],"answerLetter":"D","answerText":"D. Tất cả các đáp án đều đúng","notes":""},{"id":59,"question":"Cái ngẫu nhiên là cái","options":["A. Diễn ra hoàn toàn không chịu sự chi phối của quy luật nào","B. Hoàn toàn diễn ra theo quy luật","C. Biểu hiện của quy luật","D. Không biểu hiện của bất cứ quy luật nào"],"answerLetter":"C","answerText":"C. Biểu hiện của quy luật","notes":"(Kiểu hỏi khác: Vai trò nào sau đây không phải vai trò lãnh tụ đối với phong trào của quần chúng nhân dân? A. Thúc đẩy hoặc kìm hãm sự tiến bộ của xã hội B. Là người sáng lập ra các tố chức chính trị, xã hội và là linh hỗn của các tố chức đó C. Lãnh tụ của mỗi thời đại chi có thể hoàn thành những nhiệm vụ đặt ra của thời đại đó D. Phát minh ra công cụ lãnh đạo quần chúng)"},{"id":60,"question":"Cái riêng là một phạm trù dùng để chỉ","options":["A. Những mặt, những thuộc tính chung của nhiều sự vật","B. Một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định","C. Những nét, những thuộc tính chỉ có ở một sự vật","D. Các yếu tố cấu thành một hệ thống"],"answerLetter":"B","answerText":"B. Một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định","notes":""},{"id":61,"question":"Theo quan điểm của chủ nghĩa Mác-Lênin, khái niệm nào dùng để chỉ lực lượng sản xuất cơ bản của xã hội, trực tiếp sản xuất ra của cải vật chất, là cơ sở của sự tồn tại và phát triển của xã hội. Là động lực cơ bản của mọi cuộc cách mạng xã hội và là người sáng tạo ra những giá trị văn hóa tinh thần cho xã hội?","options":["A. Quần chúng nhân dân","B. Tất cả các đáp án đều đúng","C. Lãnh tụ","D. Vĩ nhân"],"answerLetter":"A","answerText":"A. Quần chúng nhân dân","notes":""},{"id":62,"question":"Ai là người đã đưa ra định nghĩa về giai cấp sau đây: \"Người ta gọi là giai cấp là những tập đoàn người to lớn, khác nhau về địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử, khác nhau về quan hệ của họ (thường thì những quan hệ này được pháp luật quy định và thừa nhận) đối với tư liệu sản xuất và phân công lao động, về vai trò của họ trong những tổ chức lao động xã hội, và như vậy là khác nhau về cách thức hưởng thụ và về phần của cải ít hoặc nhiều mà họ được hưởng. Giai cấp là những tập đoàn người, mà tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác, do chỗ các tập đoàn đó có địa vị khác nhau trong một chế độ kinh tế xã hội nhất định.\".","options":["A. Heraclit","B. Khổng Tử","C. V.ILênin","D. Chủ tịch Hồ Chí Minh"],"answerLetter":"C","answerText":"C. V.ILênin","notes":""},{"id":63,"question":"Trong các yếu tố sau, yếu tố nào thuộc về kiến trúc thượng tầng?","options":["A. Cơ sở kinh tế","B. Cơ sở vật chất kỹ thuật","C. Công nghệ thông tin","D. Các học thuyết, tư tưởng"],"answerLetter":"D","answerText":"D. Các học thuyết, tư tưởng","notes":""},{"id":64,"question":"Tâm lý, tính cách tiểu nông của người Việt Nam truyền thống căn bản là do những yếu tố nào quyết định? (Chọn 3)A. Bản tính cố hữu của người Việt NamB. Bị phong kiến, đế quốc nhiều thế kỷ áp bức thống trịC. Phương thức sản xuất tiểu nông, lạc hậu tồn tại lâu dài trong lịch sửD. Điều kiện tổ chức dân cư khép kín của các làng xã","options":["B. CD(Nếu chọn 1 thì chọn C)","Sản xuất vật chất có vai trò gì đối với xã hội?(073-356-8678)","A. Quyết định sự tồn tại và phát triển xã hội","B. Quyết định sự vận động của xã hội","C. Quyết định tính chất và nội dung của xã hội"],"answerLetter":"A","answerText":"A. Quyết định sự tồn tại và phát triển xã hội","notes":""},{"id":65,"question":"Phủ định biện chứng có đặc trưng cơ bản nào?","options":["A. Tính khách quan và tính mâu thuẫn","B. Tính mâu thuẫn và tính kế thừa","C. Tất cả các đáp án đều sai","D. Tính khách quan và tính kế thừa"],"answerLetter":"D","answerText":"D. Tính khách quan và tính kế thừa","notes":""},{"id":66,"question":"Sự phản ánh có tính chủ động lựa chọn thông tin, xử lý thông tin là hình thức phản ánh:","options":["A. Tâm lý","B. Năng động, sáng tạo","C. Tiên tiến","D. Không thụ động"],"answerLetter":"B","answerText":"B. Năng động, sáng tạo","notes":""},{"id":67,"question":"Theo quan niệm của chủ nghĩa duy vật biện chứng về lịch sử thì trong xã hội có giai cấp, hệ tư tưởng thống trị xã hội bao giờ cũng là hệ tư tưởng của giai cấp.","options":["A. Tiên tiến nhất","B. Lãnh đạo xã hội","C. Thống trị xã hội","D. Đứng đầu xã hội"],"answerLetter":"C","answerText":"C. Thống trị xã hội","notes":""},{"id":68,"question":"Thế nào là phương pháp siêu hình?","options":["A. Xem xét các sự vật trong mối liên hệ tác động qua lại lẫn nhau, nhưng không vận động, không phát triển","B. Xem xét các sự vật trong trạng thái cô lập, tách rời nhau, và không vận động, không phát triển","C. Xem xét các sự vật trong mối liên hệ tác động qua lại lẫn nhau, và luôn vận động, luôn phát triển","D. Xem xét các sự vật trong trạng thái cô lập, tách rời nhau, nhưng luôn vận động, luôn phát triển"],"answerLetter":"B","answerText":"B. Xem xét các sự vật trong trạng thái cô lập, tách rời nhau, và không vận động, không phát triển","notes":""},{"id":69,"question":"Ở xã hội Việt Nam hiện nay","options":["A. Còn đấu tranh giai cấp","B. Không còn đấu tranh giai cấp","C. Các phương án trả lời đều sai","D. Đấu tranh giai cấp gay gắt"],"answerLetter":"A","answerText":"A. Còn đấu tranh giai cấp","notes":"(Vấn đề giai cấp ở Việt Nam hiện nay như thế nào?)"},{"id":70,"question":"Trong chủ nghĩa Mác - Lênin thì","options":["A. Triết học là cơ sở nền tảng của kinh tế chính trị và chủ nghĩa xã hội khoa học","B. Kinh tế chính trị học là cơ sở nền tảng của triết học và chủ nghĩa xã hội khoa học","C. Chủ nghĩa xã hội khoa học là cơ sở của kinh tế chính trị và triết học"],"answerLetter":"A","answerText":"A. Triết học là cơ sở nền tảng của kinh tế chính trị và chủ nghĩa xã hội khoa học","notes":""},{"id":71,"question":"Theo chủ nghĩa duy vật lịch sử, các chính sách và pháp luật của nhà nước suy đến cùng chi là phản ánh nhu cầu thống trị về kinh tế của giai cấp nắm giữ yếu tố nào của xã hội?","options":["A. Lực lượng sản xuất chủ yếu của xã hội","B. Quyền tổ chức-quản lý xã hội","C. Nhà nước","D. Quyền sở hữu các tư liệu sản xuất chủ yếu"],"answerLetter":"D","answerText":"D. Quyền sở hữu các tư liệu sản xuất chủ yếu","notes":""},{"id":72,"question":"Cơ sở, động lực, mục đích của nhận thức là","options":["A. Lý luận","B. Thực tiễn","C. Triết học","D. Tinh thần"],"answerLetter":"B","answerText":"B. Thực tiễn","notes":""},{"id":73,"question":"Định nghĩa phạm trù vật chất phụ thuộc chủ yếu vào","options":["A. Sự phát triển khoa học kỹ thuật","B. Sự phát triển của logic hình thức","C. Sự phát triển của logic biện chứng","D. Tất cả các đáp án đều đúng"],"answerLetter":"A","answerText":"A. Sự phát triển khoa học kỹ thuật","notes":""},{"id":74,"question":"Theo quan điểm của triết học Mác - Lênin, mối quan hệ giữa tồn tại xã hội và ý thức xã hội thể hiện như thế nào?","options":["A. Ý thức xã hội quyết định tồn tại xã hội; tồn tại xã hội có tính độc lập tương đối, tác động trở lại ý thức xã hội","B. Tồn tại xã hội quyết định ý thức xã hội; ý thức xã hội có tính độc lập tương đối, tác động trở lại tồn tại xã hội","C. Tồn tại xã hội và ý thức xã hội tồn tại độc lập, không liên quan gì đến nhau","D. Tồn tại xã hội quyết định tồn tại xã hội, ý thức xã hội quyết định ý thức xã hội"],"answerLetter":"B","answerText":"B. Tồn tại xã hội quyết định ý thức xã hội; ý thức xã hội có tính độc lập tương đối, tác động trở lại tồn tại xã hội","notes":""},{"id":75,"question":"Theo chủ nghĩa duy vật lịch sử, quan hệ sản xuất có thể tác động tới lực lượng sản xuất theo hướng.","options":["A. Thúc đẩy hoặc kìm hãm sự phát triển","B. Thúc đẩy","C. Hỗ trợ","D. Tạo điều kiện"],"answerLetter":"A","answerText":"A. Thúc đẩy hoặc kìm hãm sự phát triển","notes":""},{"id":76,"question":"Một sinh viên định nghĩa bệnh chủ quan duy ý chí bằng các biểu hiện đặc trưng sau đây. Hãy chỉ ra một biểu hiện không thuộc chủ quan duy ý chí.","options":["A. Suy nghĩ và hành động nóng vội","B. Chạy theo nguyện vọng chủ quan","C. Quyết tâm thực hiện mục tiêu","D. Không tính tới điều kiện và khả năng thực tế"],"answerLetter":"C","answerText":"C. Quyết tâm thực hiện mục tiêu","notes":""},{"id":77,"question":"Triết học ra đời từ đâu?","options":["A. Từ thực tiễn, do nhu cầu của thực tiễn","B. Tử sự tư duy của con người về bản thân mình","C. Từ sự vận động của ý muốn chủ quan của con người","D. Từ thực tiễn, do sự phát triển của khoa học kỹ thuật"],"answerLetter":"A","answerText":"A. Từ thực tiễn, do nhu cầu của thực tiễn","notes":"(Cách hỏi khác: Đâu không phải là biểu hiện của chủ quan duy ý chí?)"},{"id":78,"question":"Đứng im được hiểu là trạng thái như thế nào?","options":["A. Tuyệt đối","B. Tương đối","C. Vừa tuyệt đối vừa tương đối","D. Không có đáp án đúng"],"answerLetter":"B","answerText":"B. Tương đối","notes":""},{"id":79,"question":"Sự ra đời và tồn tại của nhà nước","options":["A. Là hiện tượng mang tính khách quan, bị quyết định bởi quá trình phát triển của xã hội","B. Là hiện tượng mang tính chủ quan, phụ thuộc vào nguyện vọng của giai cấp cầm quyền","C. Là hiện tượng mang tính chủ quan phụ thuộc vào nguyện vọng của mỗi quốc gia, mỗi dân tộc"],"answerLetter":"A","answerText":"A. Là hiện tượng mang tính khách quan, bị quyết định bởi quá trình phát triển của xã hội","notes":""},{"id":80,"question":"Theo quan điểm của phép biện chứng duy vật thì trong những điều kiện xác định cái đơn nhất và cái gì có thể chuyển hóa lẫn nhau?","options":["A. Cái đặc thủ","B. Cái cái riêng","C. Cái chung","D. Quy luật"],"answerLetter":"C","answerText":"C. Cái chung","notes":""},{"id":81,"question":"Theo quan niệm duy vật biện chứng về lịch sử thì đỉnh cao của sự phát triển đấu tranh giai cấp là đấu tranh trong lĩnh vực nào?","options":["A. Chính trị","B. Võ trang","C. Kinh tế","D. Giải phóng"],"answerLetter":"A","answerText":"A. Chính trị","notes":""},{"id":82,"question":"Quan điểm tiến bộ và cách mạng nhất của chủ nghĩa Mác-Lênin về vấn đề con người là:","options":["A. Giải thích được nguồn gốc tự nhiên và xã hội của con người dưới ánh sáng khoa học","B. Mô tả được quá trình hoạt động sống và lao động sản xuất của con người theo tinh thần của chủ nghĩa duy vật","C. Đưa ra được học thuyết cách mạng và triệt để về đấu tranh giải phóng con người","D. Giải thích được một cách khoa học nguồn gốc của ý thức của con người"],"answerLetter":"C","answerText":"C. Đưa ra được học thuyết cách mạng và triệt để về đấu tranh giải phóng con người","notes":"(Kiểu hỏi khác: Theo quan niệm của chủ nghĩa duy vật lịch sử thì đỉnh cao của sự phát triển đấu tranh giai cấp là đấu tranh trong lĩnh vực nào?)"},{"id":83,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng thì thông qua vận động mà các dạng cụ thể của vật chất","options":["A. Tạo ra ý thức","B. Không tồn tại","C. Mất dẫn đi","D. Biểu hiện"],"answerLetter":"D","answerText":"D. Biểu hiện","notes":""},{"id":84,"question":"Bản chất của nhà nước là","options":["A. Cơ quan phúc lợi chung của toàn xã hội","B. Cơ quan trọng tài thực hiện chức năng phân xử và hòa giải các xung đột xã hội","C. Công cụ của giai cấp thống trị xã hội"],"answerLetter":"C","answerText":"C. Công cụ của giai cấp thống trị xã hội","notes":""},{"id":85,"question":"Khi chất mới của sự vật ra đời có thể làm thay đổi những gì của sự vận động và phát triển của sự vật?","options":["A. Bản chất, hình thức","B. Kết cấu, quy mô","C. Hình thức kết cấu","D. Hình thức vận động"],"answerLetter":"B","answerText":"B. Kết cấu, quy mô","notes":""},{"id":86,"question":"Chất và lượng có mối quan hệ với nhau như thế nào?","options":["A. Không có mối quan hệ gì với nhau","B. Chi có mối quan hệ giữa chất với lượng","C. Chỉ có mỗi quan hệ giữa lượng với chất","D. Có mối quan hệ biện chứng với nhau"],"answerLetter":"D","answerText":"D. Có mối quan hệ biện chứng với nhau","notes":""},{"id":87,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, trong xã hội khi xuất hiện mâu thuẫn gay gắt giữa lực lượng sản xuất và quan hệ sản xuất thì","options":["A. Quan hệ sản xuất sẽ tự động thay đổi cho phù hợp với lực lượng sản xuất","B. Quan hệ sản xuất không thể thay đổi được vì nó được bảo vệ bằng quyền lực nhà nước","C. Lực lượng sản xuất phải tự điều chỉnh cho phù hợp với quan hệ sản xuất","D. Quan hệ sản xuất được thay đổi thông qua những cuộc cải cách và các cuộc cách mạng xã hội"],"answerLetter":"D","answerText":"D. Quan hệ sản xuất được thay đổi thông qua những cuộc cải cách và các cuộc cách mạng xã hội","notes":""},{"id":88,"question":"Lực lượng sản xuất được hiểu là khái niệm dùng để chỉ","options":["A. Quan hệ giữa con người với tự nhiên trong quá trình sản xuất","B. Quan hệ giữa người với xã hội trong quá trình sản xuất","C. Quan hệ giữa người sản xuất trong quá trình sản xuất","D. Quan hệ giữa những người lao động trong quá trình tác động vào giới tự nhiên"],"answerLetter":"A","answerText":"A. Quan hệ giữa con người với tự nhiên trong quá trình sản xuất","notes":""},{"id":89,"question":"Kiến trúc thượng tầng là gì?","options":["A. Các quan hệ sản xuất hiện có trong xã hội","B. Hệ tư tưởng của giai cấp thống trị","C. Cơ sở kinh tế của xã hội","D. Những quan điểm, tư tưởng và các thiết chế của xã hội tương ứng được hình thành trên cơ sở hạ tầng"],"answerLetter":"D","answerText":"D. Những quan điểm, tư tưởng và các thiết chế của xã hội tương ứng được hình thành trên cơ sở hạ tầng","notes":""},{"id":90,"question":"Điền vào dấu (...): \"Quan điểm nhất quán từ xưa đến nay của các nhà triết học duy vật là thừa nhận sự tồn tại .... lấy bản thân giới tự nhiên để giải thích tự nhiên\".","options":["A. Chủ quan của thế giới vật chất","B. Song song với thế giới vật chất","C. Khách quan của thế giới vật chất","D. Có tính trật tự, nguyên tắc của thế giới vật chất"],"answerLetter":"C","answerText":"C. Khách quan của thế giới vật chất","notes":""},{"id":91,"question":"Chủ nghĩa Mác-Lênin gồm ba bộ phận cấu thành đó là(073-356-8678)","options":["A. Triết học, Kinh tế chính trị học và Chủ nghĩa xã hội khoa học","B. Triết học, Kinh tế chính trị học và Chính trị học","C. Triết học, Kinh tế học và Chủ nghĩa xã hội khoa học"],"answerLetter":"A","answerText":"A. Triết học, Kinh tế chính trị học và Chủ nghĩa xã hội khoa học","notes":""},{"id":92,"question":"Hãy chỉ ra sai lầm của các nhà triết học thế kỷ XVII-XVIII trong quan niệm về vật chất (3 đáp án)","options":["A. Vật chất biểu hiện qua không gian và thời gian","B. Đồng nhất vật chất với vật thể","C. Đề cập đến vai trò của vật thể","D. Đồng nhất vật chất với một số tính chất phổ biến của vật thể"],"answerLetter":"BCD","answerText":"B. Đồng nhất vật chất với vật thể\nC. Đề cập đến vai trò của vật thể\nD. Đồng nhất vật chất với một số tính chất phổ biến của vật thể","notes":"(Cách hỏi khác: Chủ nghĩa Mác-Lênin có những bộ phần cấu thành nào?)"},{"id":93,"question":"Theo quan điểm duy vật lịch sử, quan hệ cơ bản nhất, quyết định mọi mối quan hệ xã hội là","options":["A. Quan hệ quyền lực nhà nước","B. Quan hệ văn hóa","C. Quan hệ kinh tế","D. Quan hệ tôn giáo"],"answerLetter":"C","answerText":"C. Quan hệ kinh tế","notes":""},{"id":94,"question":"Theo quan điểm triết học Mácxít, khẳng định nào sau đây sai?","options":["A. Thế giới là một chỉnh thể trong sự liên hệ, ràng buộc lẫn nhau","B. Con người không thể tách khỏi các mối quan hệ với tự nhiên","C. Giữa các loài luôn có những khâu trung gian nổi chúng với nhau","D. Thế giới tinh thần và thế giới vật chất tồn tại độc lập nhau"],"answerLetter":"D","answerText":"D. Thế giới tinh thần và thế giới vật chất tồn tại độc lập nhau","notes":""},{"id":95,"question":"Hình thức nhận thức nào cần có sự tác động trực tiếp của vật vào cơ quan giác quan của con người?","options":["A. Tri giác","B. Khái niệm.","C. Suy luận.","D. Phán đoán."],"answerLetter":"A","answerText":"A. Tri giác","notes":""},{"id":96,"question":"Quan hệ biện chứng giữa \"cái riêng\" và \"cái chung\" thì cái chung tồn tại:","options":["A. Ngoài cái riêng.","B. Cùng cái riêng.","C. Trong cái riêng.","D. Bên cái riêng."],"answerLetter":"C","answerText":"C. Trong cái riêng.","notes":"(Câu trả lời khác: Cảm giác Kiểu hỏi khác: Hình thức nhận thức nào là khi sự vật trực tiếp tác động đến giác quan của con người? A. Cảm giác B. Tri giác C. Biểu tượng D. Khái niệm)"},{"id":97,"question":"\"Cân bằng động\" trong sự phù hợp giữa lực lượng sản xuất và quan hệ sản xuất là gì?","options":["A. Lực lượng sản xuất và quan hệ sản xuất phù hợp trong suốt quá trình phát triển của con người","B. Lực lượng sản xuất thay đổi, quan hệ sản xuất không cần thay đổi","C. Sự phù hợp cụ thể nào đó giữa quan hệ sản xuất và lực lượng sản xuất luôn bị phá vỡ để thay bằng một sự phù hợp khác cao hơn","D. Khi lực lượng sản xuất đã đến lúc cần thay đổi thì nhất định là quan hệ sản xuất cũng sẽ","E. Lực lượng sản xuất không cần thay đổi, quan hệ sản xuất thay đổi"],"answerLetter":"C","answerText":"C. Sự phù hợp cụ thể nào đó giữa quan hệ sản xuất và lực lượng sản xuất luôn bị phá vỡ để thay bằng một sự phù hợp khác cao hơn","notes":"(Kiểu hỏi khác: Theo quan điểm của phép biện chứng duy vật thì quan hệ biện chứng giữa \"cái riêng\" và \"cái chung\" thì cái chung tồn tại như thế nào so với cái riêng?)"},{"id":98,"question":"Triết học duy tâm khách quan và duy tâm chủ quan đều có điểm chung là","options":["A. Đề cao lĩnh vực tinh thần của con người","B. Đề cao lĩnh vực vật chất và tinh thần của con người","C. Đề cao đời sống tâm linh của con người"],"answerLetter":"A","answerText":"A. Đề cao lĩnh vực tinh thần của con người","notes":""},{"id":99,"question":"Chân lý bao gồm các tính chất sau. (4 đáp án)","options":["A. Tính phong phú, đa dạng","B. Tính khách quan","C. Tính tương đối","D. Tính cụ thể","E. Tính tuyệt đối"],"answerLetter":"BCDE","answerText":"B. Tính khách quan\nC. Tính tương đối\nD. Tính cụ thể\nE. Tính tuyệt đối","notes":"(Kiểu hỏi khác: Giá trị của triết học duy tâm là A. Đề cao lĩnh vực tinh thần của con người B. Đánh giá đúng lĩnh vực tinh thần của con người C. Đề cao tư duy của con người)"},{"id":100,"question":"Nhân tố đảm bảo cho sự thắng lợi cuối cùng của một chế độ xã hội là","options":["A. Có nền khoa học tiên tiến","B. Có nhân tố chính trị tiến bộ","C. Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc","D. Có thể tạo ra năng suất lao động cao hơn"],"answerLetter":"D","answerText":"D. Có thể tạo ra năng suất lao động cao hơn","notes":""},{"id":101,"question":"Trong thực tế chúng ta phải dựa vào","options":["A. Hiện thực và dự đoán các khả năng","B. Cả khả năng và hiện thực","C. Hiện thực vì khả năng là cái chưa tồn tại","D. Khả năng vì khả năng có thể chứa hiện thực"],"answerLetter":"A","answerText":"A. Hiện thực và dự đoán các khả năng","notes":""},{"id":102,"question":"Thế giới quan được hiểu là gì?","options":["A. Quan niệm của con người về thế giới","B. Hệ thống quan niệm của con người về thế giới","C. Hệ thống quan niệm, quan điểm lý luận của con người về thế giới","D. Hệ thống quan niệm, quan điểm chung nhất của con người về thế giới"],"answerLetter":"D","answerText":"D. Hệ thống quan niệm, quan điểm chung nhất của con người về thế giới","notes":""},{"id":103,"question":"Chủ nghĩa duy vật lịch sử cho rằng giai cấp nắm được yếu tố nào thì cũng chiếm được địa vị chính trị, có khả năng khách quan thành giai cấp thống trị xã hội?","options":["A. Tư liệu sản xuất chủ yếu","B. Quan hệ sản xuất thống trị","C. Lực lượng sản xuất","D. Lực lượng sản xuất mới"],"answerLetter":"A","answerText":"A. Tư liệu sản xuất chủ yếu","notes":""},{"id":104,"question":"Trong xã hội có giai cấp, tính chất kế thừa của ý thức xã hội có gắn với tính chất giai cấp của","options":["A. Tùy trường hợp cụ thể","B. Không kế thừa","C. Có kế thừa"],"answerLetter":"C","answerText":"C. Có kế thừa","notes":""},{"id":105,"question":"Theo chủ nghĩa duy vật lịch sử, khái niệm \"cách mạng xã hội\" dùng để chỉ yếu tố nào?","options":["A. Sự tiến bộ, tiền hóa mọi lĩnh vực trong một xã hội nhất định","B. Sự thay thế chế độ xã hội này bằng một chế độ xã hội khác","C. Sự thay thế thể chế kinh tế này bằng một thể chế kinh tế khác","D. Sự thay thế hình thái kinh tế - xã hội này bằng hình thái kinh tế - xã hội khác cao hơn"],"answerLetter":"D","answerText":"D. Sự thay thế hình thái kinh tế - xã hội này bằng hình thái kinh tế - xã hội khác cao hơn","notes":""},{"id":106,"question":"Không phải mọi sự thay đổi về lượng đều","options":["A. Có khả năng dẫn đến thay đổi về chất","B. Ngay lập thức thay đổi về chất","C. Không thể lập tức làm thay đổi về chất","D. Không làm thay đổi về chất"],"answerLetter":"A","answerText":"A. Có khả năng dẫn đến thay đổi về chất","notes":""},{"id":107,"question":"Chọn phương án đúng để điền vào chỗ trống: \" Điểm xuất phát củ","options":["A. .. là sự khẳng định những sự vật hiện tượng của tự nhiên đều bao hàm những mâu thuẫn vốn có của chúng\"A. Phép siêu hình","B. Phép biện chứng","C. Phép biện chứng duy tâm","D. Chủ nghĩa duy vật"],"answerLetter":"B","answerText":"B. Phép biện chứng","notes":""},{"id":108,"question":"Theo C.Mác, con người muốn sống thì trước hết cần có thức ăn, đồ mặc v.v. Như vậy, hành vi lịch sử đầu tiên là sản xuất r","options":["A. A. Tư liệu sinh hoạt","B. Tư liệu sản xuất","C. Của cải","D. Tư liệu lao động"],"answerLetter":"A","answerText":"A. A. Tư liệu sinh hoạt","notes":""},{"id":109,"question":"Chọn phương án đúng theo quan điểm duy tâm về lịch sử.Trong mối quan hệ giữa tồn tại xã hội và ý thức xã hội.","options":["A. Suy đến cùng, tồn tại xã hội quyết định ý thức xã hội","B. Suy đến cùng, ý thức xã hội quyết định tồn tại xã hội","C. Tồn tại trong mối quan hệ phụ thuộc vào nhau, không cái nào quyết định cái nào","D. Tùy từng điều mà xem xét cái nào quyết định cái nào"],"answerLetter":"B","answerText":"B. Suy đến cùng, ý thức xã hội quyết định tồn tại xã hội","notes":""},{"id":110,"question":"Hình thái ý thức xã hội nào phản ánh bản chất và tính quy luật của thế giới khách quan?","options":["A. Ý thức chính trị","B. Ý thức pháp quyền","C. Ý thức khoa học","D. Ý thức đạo đức"],"answerLetter":"C","answerText":"C. Ý thức khoa học","notes":"(Kiểu hỏi khác: Quan điểm nào mang tính duy tâm khi bàn về mỗi quan hệ giữa tồn tại xã hội và ý thức xã hội?)"},{"id":111,"question":"Trong 3 đặc trưng của giai cấp thì đặc trưng nào giữ vai trò chi phối các đặc trưng khác ?","options":["A. Khác nhau về vai trò trong tổ chức lao động xã hội","B. Khác nhau về địa vị trong hệ thống tổ chức xã hội","C. Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội","D. Tập đoàn này có thể chiếm hữu đoạt lao động của tập đoàn khác"],"answerLetter":"C","answerText":"C. Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội","notes":""},{"id":112,"question":"Triết học Mác là thế giới quan khoa học của giai cấp nào?","options":["A. Giai cấp tư sản tiến bộ","B. Giai cấp công nhân","C. Tầng lớp trí thức","D. Giai cấp lao động"],"answerLetter":"B","answerText":"B. Giai cấp công nhân","notes":"(Kiểu hỏi khác: Trong 3 đặc trưng của giai cấp, đặc trưng nào giữ vai trò chi phối các đặc trưng khác?A. Tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác B. Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội C. Khác nhau về vai trò trong tổ chức lao động xã hội D. Khác nhau về địa vị trong hệ thống tổ chức xã hội)"},{"id":113,"question":"Theo quan điểm của triết học Mác-Lênin, tiêu chí cơ bản để đánh giá phẩm chất của mỗi cá nhân","options":["A. Địa vị xã hội của cá nhân","B. Thái độ, hành vi đạo đức của cá nhân","C. Sự thực hiện khả năng làm chủ đối với hoàn cảnh và hành động thực tiễn của cá nhân","D. Tất cả đều đúng"],"answerLetter":"C","answerText":"C. Sự thực hiện khả năng làm chủ đối với hoàn cảnh và hành động thực tiễn của cá nhân","notes":""},{"id":114,"question":"Đâu là nguồn gốc lý luận của chủ nghĩa Mác?","options":["A. Tư tưởng xã hội phương Đông cổ đại","B. Triết học cổ điển Đức, kinh tế chính trị cổ điển Anh và chủ nghĩa xã hội không tưởng Pháp","C. Chủ nghĩa duy vật siêu hình thế kỷ XVII - XVIII ở Tây Âu","D. Học thuyết tiến hoá"],"answerLetter":"B","answerText":"B. Triết học cổ điển Đức, kinh tế chính trị cổ điển Anh và chủ nghĩa xã hội không tưởng Pháp","notes":""},{"id":115,"question":"Ý thức tôn giáo là niềm tin của bộ phận nhân dân, thường là yếu tố bền vững nhất trong đời sống mỗi con người, mỗi xã hội. Vậy, nguyên nhân sự tồn tại bền vững của ý thức tôn giáo là gì?","options":["A. Nhận thức","B. Trình độ","C. Văn hóa","D. Tâm lý"],"answerLetter":"D","answerText":"D. Tâm lý","notes":""},{"id":116,"question":"Một sinh viên chuẩn bị bài seminar trong 1 tuần theo cách thức: ngày đầu phác thảo đề cương sơ lược sau đó hằng ngày dành 15 phút sửa chữa và bổ sung bài chuẩn bị đó cả kết cấu, nội dung. Đúng vào buổi seminar, sinh viên đó đã có một bản chuẩn bị hoàn chỉnh. Công việc trên diễn ra theo nguyên lí, quy luật nào?","options":["A. Quy luật mâu thuẫn","B. Quy luật lượng - chất","C. Quy luật phủ định của phủ định","D. Nguyên lý về mối liên hệ phổ biến"],"answerLetter":"B","answerText":"B. Quy luật lượng - chất","notes":""},{"id":117,"question":"Định nghĩa của V.I.Lênin về giai cấp là những tập đoàn người to lớn có sự phân biệt về:","options":["A. Địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử","B. Địa vị của họ trong quá trình quản lý và phân phối của cải xã hội","C. Địa vị của họ trong quản lý chính trị, văn hóa và xã hội","D. Địa vị của họ trong việc nắm quyền lực nhà nước"],"answerLetter":"A","answerText":"A. Địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử","notes":""},{"id":118,"question":"Trong tư liệu lao động, bộ phận nào cần được phát triển đi trước một bước so với đầu tư sản xuất trực tiếp?","options":["A. Kết cấu hạ tầng sản xuất","B. Công cụ sản xuất","C. Các bộ phận chứa đựng, bảo quản","D. Các phương án trả lời đều đúng"],"answerLetter":"A","answerText":"A. Kết cấu hạ tầng sản xuất","notes":""},{"id":119,"question":"Theo quan điểm của phép biện chứng duy vật thì phạm trù chi một sự vật, một hiện tượng, một quá trình nhất định là","options":["A. Đặc thù","B. Bản chất","C. Cái riêng","D. Hiện tượng"],"answerLetter":"C","answerText":"C. Cái riêng","notes":""},{"id":120,"question":"Theo Ph. Ăngghen, tính thống nhất của vật chất được chứng minh bởi:","options":["A. Thực tiễn lịch sử","B. Thực tiễn cách mạng","C. Sự phát triển lâu dài của khoa học","D. Sự phát triển lâu dài và khó khăn của triết học và khoa học tự nhiên"],"answerLetter":"D","answerText":"D. Sự phát triển lâu dài và khó khăn của triết học và khoa học tự nhiên","notes":""},{"id":121,"question":"Theo V.I. Lênin \"Chủ nghĩa Mác đã mở đường cho việc nghiên cứu rộng rãi và toàn diện quá trình phát sinh, phát triển và suy tàn củ","options":["A. ..\"A. Hệ thống vật chất trong giới tự nhiên","B. Các quá trình kinh tế và chính trị - xã hội","C. Các sự vật, hiện tượng trong thế giới tự nhiên, xã hội và tư duy","D. Các hình thái kinh tế - xã hội"],"answerLetter":"D","answerText":"D. Các hình thái kinh tế - xã hội","notes":""},{"id":122,"question":"Theo quan niệm duy vật biện chứng về lịch sử thì do khác nhau và đối lập nhau về yếu tố nào tạo ra khả năng khách quan dẫn đến tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác?","options":["A. Quyền lực","B. Sở hữu","C. Địa vị","D. Tài sản"],"answerLetter":"C","answerText":"C. Địa vị","notes":""},{"id":123,"question":"Theo quan điểm của phép biện chứng duy vật thì chất là sự thống nhất hữu cơ của các thuộc tính cấu thành nó và là phạm trù dùng để chi tính quy định gì của sự vật, hiện tượng?","options":["A. Có tổ chức","B. Khách quan vốn có","C. Về kết cấu","D. Về kết quả"],"answerLetter":"B","answerText":"B. Khách quan vốn có","notes":""},{"id":124,"question":"Trong mối quan hệ giữa \"lực lượng sản xất và quan hệ sản xuất\", yếu tố nào là nội dung, yếu tố nào là hình thức?","options":["A. Lực lượng sản xuất là nội dung - quan hệ sản xuất là hình thức","B. Quan hệ sản xuất là nội dung- lực lượng sản xuất là hình thức","C. Lực lượng sản xuất và quan hệ sản xuất đều là nội dung","D. Lực lượng sản xuất và quan hệ sản xuất đều là hình thức"],"answerLetter":"A","answerText":"A. Lực lượng sản xuất là nội dung - quan hệ sản xuất là hình thức","notes":""},{"id":125,"question":"Trong lý luận nhận thức, cần nhìn nhận sự vật trong trạng thái vận động và phát triển. Điều đó dựa trên cơ sở lý luận của nguyên lý nào?","options":["A. Nguyên lý về mối liên hệ phổ biến","B. Nguyên lý về sự phát triển","C. Nguyên lý về tính thống nhất vật chất của thế giới"],"answerLetter":"B","answerText":"B. Nguyên lý về sự phát triển","notes":""},{"id":126,"question":"Tiêu chí nào là quan trọng nhất để phân biệt các hình thái kinh tế xã hội","options":["A. Lực lượng sản xuất","B. Quan hệ sản xuất","C. Tồn tại xã hội","D. Kiến trúc thượng tầng"],"answerLetter":"B","answerText":"B. Quan hệ sản xuất","notes":"(Kiểu hỏi khác: Trong hoạt động nhận thức, ....)"},{"id":127,"question":"Nguyên tác thống nhất giữa lý luận và thực tiễn là nguyên tắc được rút ra (trực tiếp) từ mối quan hệ nào?","options":["A. Mối quan hệ giữa vật chất và ý thức.","B. Lý luận và nhận thứ","C. C. Quan hệ giữa khả năng và hiện thực","D. Phán đoán suy luận"],"answerLetter":"B","answerText":"B. Lý luận và nhận thứ","notes":""},{"id":128,"question":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra nguồn gốc của sự phát triển cơ bản phổ biến của sự vận động và phát triển","options":["A. Quy luật thống nhất và đấu tranh của các mặt đối lập","B. Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","C. Quy luật phủ định của phủ định","D. Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"answerLetter":"A","answerText":"A. Quy luật thống nhất và đấu tranh của các mặt đối lập","notes":""},{"id":129,"question":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra cách thức / hình thức của sự phát triển cơ bản phổ biến của sự vận động và phát triển","options":["A. Quy luật thống nhất và đấu tranh của các mặt đối lập","B. Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại (Quy luật lượng - chất)","C. Quy luật phủ định của phủ định","D. Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"answerLetter":"B","answerText":"B. Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại (Quy luật lượng - chất)","notes":""},{"id":130,"question":"Triết học của các nhà tư tưởng thời kỳ Phục Hưng có đặc điểm gì?","options":["A. Có tính chất duy vật tự phát","B. Có tính chất duy tâm khách quan","C. Còn pha trộn giữa các yếu tố duy vật và duy tâm","D. Còn pha trộn giữa các yếu tố duy tâm thần bí và siêu hình"],"answerLetter":"C","answerText":"C. Còn pha trộn giữa các yếu tố duy vật và duy tâm","notes":""},{"id":131,"question":"Một trong các nội dung định nghĩa của Lênin về vật chất đó là, vật chất được cảm giác của chúng ta chép lại, chụp lại, phản ánh và tồn tại.","options":["A. Lệ thuộc vào cảm giác","B. Không lệ thuộc vào cảm giác","C. Tuỳ thuộc vào nhận thức","D. Tuỳ theo ý thức"],"answerLetter":"B","answerText":"B. Không lệ thuộc vào cảm giác","notes":""},{"id":132,"question":"Theo Lênin, vật chất dưới hình thức thế nào thì là cái có thể gây nên cảm giác của con người khi nó trực tiếp hay gián tiếp tác động đến giác quan của con người?","options":["A. Những dạng cụ thể","B. Tồn tại khách quan","C. Khái quát của nó","D. Tự nhiên của nó"],"answerLetter":"A","answerText":"A. Những dạng cụ thể","notes":""},{"id":133,"question":"Chủ nghĩa duy vật lịch sử cho rằng, cuộc đấu tranh giữa những người lao động làm thuê, những người nô lệ bị áp bức về chính trị - xã hội và bị bóc lột về kinh tế chống lại bọn áp bức và bóc lột nó là thực chất","options":["A. Đấu tranh giai cấp","B. Ra đời giai cấp","C. Cách mạng","D. Ra đời nhà nước"],"answerLetter":"A","answerText":"A. Đấu tranh giai cấp","notes":"(Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật lịch sử, cuộc đấu tranh giữa những người lao động làm thuê, những người nô lệ bị áp búc vẽ chính trị - xã hội và bị bóc lột vẽ kinh tế chống lại bọn áp bức và bóc lột thực chất là gi?)"},{"id":134,"question":"Chủ nghĩa duy vật lịch sử cho rằng, tồn tại xã hội là khái niệm dùng để chỉ phương diện sinh hoạt vật chất và những điều kiện gì của xã hội?","options":["A. Văn hoá tinh thần","B. Sinh hoạt tinh thần","C. Sinh hoạt vật chất","D. Kinh tế"],"answerLetter":"C","answerText":"C. Sinh hoạt vật chất","notes":""},{"id":135,"question":"Tồn tại xã hội là gì?","options":["A. Sinh hoạt vật chất và những điêu kiện sinh hoạt vật chất của xã hội","B. Toàn bộ các giá trị tinh thần của xã hội","C. Toàn bộ các điều kiện sinh hoạt của xã hội","D. Toàn bộ hệ tư tưởng về sự tồn tại cùa xã hội"],"answerLetter":"A","answerText":"A. Sinh hoạt vật chất và những điêu kiện sinh hoạt vật chất của xã hội","notes":""},{"id":136,"question":"Chủ nghĩa xã hội không tưởng đề cao yếu tố gì?","options":["A. Tinh thần nhân đạo","B. Xã hội đại đồng","C. Sư bình đẳng","D. Một xã hội không còn sự bóc lột"],"answerLetter":"A","answerText":"A. Tinh thần nhân đạo","notes":""},{"id":137,"question":"Vị trí của quy luật phủ định của phủ định trong phép biện chứng duy vật","options":["A. Chỉ ra cách thức của sự phát triển","B. Chỉ ra nguồn gốc của sự phát triển","C. Chỉ ra nguyên nhân của sự phát triển","D. Chỉ ra khuynh hướng của sự phát triển"],"answerLetter":"D","answerText":"D. Chỉ ra khuynh hướng của sự phát triển","notes":""},{"id":138,"question":"Hệ thống những quan điểm lý luận chung nhất về thế giới và về vị trí của con người trong thế giới đó là:","options":["A. Quan điểm biện chứng","B. Chủ nghĩa duy vật","C. Chủ nghĩa duy vật biện chứng","D. Triết học"],"answerLetter":"D","answerText":"D. Triết học","notes":""},{"id":139,"question":"Quan điểm ủng hộ cái mới tiến bộ, từ đó chống lại cái cũ, cái lỗi thời kìm hãm sự phát triển là quan điểm được rút ra trực tiếp từ:","options":["A. Quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại","B. Quy luật thống nhất và quy luật đấu tranh của các mặt đối lập","C. Quy luật phủ định của phủ định"],"answerLetter":"C","answerText":"C. Quy luật phủ định của phủ định","notes":""},{"id":140,"question":"Học thuyết Hình thái kinh tế - xã hội là nội dung của","options":["A. Phép biện chứng","B. Tất cả các đáp án đều đúng","C. Chủ nghĩa duy vật biện chứng","D. Chủ nghĩa duy vật lịch sử"],"answerLetter":"D","answerText":"D. Chủ nghĩa duy vật lịch sử","notes":""},{"id":141,"question":"Cách thức mà con người dùng để tiến hành quá trình sản xuất của xã hội ở những giai đoạn lịch sử nhất định gọi là:","options":["A. Phương thức sản xuất","B. Nghệ thuật sản xuất","C. Kỹ thuật sản xuất","D. Công nghệ sản xuất"],"answerLetter":"A","answerText":"A. Phương thức sản xuất","notes":""},{"id":142,"question":"Đâu là nhận định sai về Triết học Mác ?","options":["A. Triết học Mác cho rằng triết học là khoa học của mọi khoa học","B. Theo quan điểm của triết học Mác triết học không thay thế được các khoa học cụ thể","C. Theo quan điểm của triết học Mác thì sự phát triển của triết học quan hệ chặt chẽ với sự phát triển của khoa học tự nhiên","D. Triết học Mác là sự tổng hợp của các trường phái triết học trong lịch sử"],"answerLetter":"A","answerText":"A. Triết học Mác cho rằng triết học là khoa học của mọi khoa học","notes":""},{"id":143,"question":"Từ thế kỉ VIII trước công nguyên với nhà nước đầu tiên trong lịch sử, giai cấp tư hữu đã dùng pháp luật và bộ máy thống trị của mình để chiếm mất quyền lực của đông đảo quần chúng nhân dân lao động là những...","options":["A. Nông dân","B. Người tự do","C. Người nô lệ","D. Nông nô"],"answerLetter":"C","answerText":"C. Người nô lệ","notes":""},{"id":144,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng lịch sử, xã hội loài người đã trải qua bao nhiêu hình thái kinh tế xã hội?","options":["A. Bốn hình thái kinh tế xã hội","B. Ba hình thái kinh tế xã hội","C. Năm hình thái kinh tế xã hội"],"answerLetter":"C","answerText":"C. Năm hình thái kinh tế xã hội","notes":""},{"id":145,"question":"Hãy xác định luận điểm nào sai khi đề cập đến \"mối quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng\"?","options":["A. Sự phát triển của lực lượng sản xuất trực tiếp làm thay đổi quan hệ sản xuất, và thông qua đó làm thay đổi kiến trúc thượng tầng","B. Cơ sở hạ tầng thay đổi thì sớm muộn gì kiến trúc thượng tầng cũng thay đổi theo","C. Trong xã hội có giai cấp, giai cấp nào thống trị về kinh tế thì sẽ thống trị về chính trị, tư tưởng","D. Các mâu thuẫn trong chính trị, tư tưởng xét đến cùng quyết định các mâu thuẫn trong lĩnh vực kinh tế"],"answerLetter":"D","answerText":"D. Các mâu thuẫn trong chính trị, tư tưởng xét đến cùng quyết định các mâu thuẫn trong lĩnh vực kinh tế","notes":"[Giải thích: Công xã nguyên thủy, Chiếm hữu nô lệ, Phong kiến,Tư bản chủ nghĩa, Cộng sản chủ nghĩa (giai đoạn đầu là chủ nghĩa xã hội)] (Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật lịch sử, loài người đã và đang trải qua bao nhiêu hình thái kinh tế - xã hội?)"},{"id":146,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng, trong thực tế chúng ta phải dựa vào điều gì?","options":["A. Dựa vào tất nhiên, đề phòng ngẫu nhiên","B. Dựa vào ngẫu nhiên, đề phòng tất nhiên","C. Dựa vào cả tất nhiên và ngẫu nhiên","D. Không dựa vào các yếu tố nào mang tính tất nhiên, ngẫu nhiên"],"answerLetter":"A","answerText":"A. Dựa vào tất nhiên, đề phòng ngẫu nhiên","notes":""},{"id":147,"question":"Đấu tranh giai cấp có vai trò gì đối với sự phát triển của xã hội?","options":["A. Kìm hãm sự phát triển của xã hội","B. Tất cả đều sai","C. Không có vai trò gì","D. Là động lực thúc đẩy"],"answerLetter":"D","answerText":"D. Là động lực thúc đẩy","notes":"(Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật biện chứng về mỗi quan hệ giữa tất nhiên và ngẫu nhiên, trong hoạt động thực tiễn, cần dựa vào điều gì? A. Dựa vào ngẫu nhiên, dự phòng tất nhiên. B. Dựa vào ngẫu nhiên, đề phòng tất nhiên C. Dựa vào cả tất nhiên và ngẩu nhiên D. Không dựa vào các yếu tố nào mang tính tất nhiên, ngẫu nhiên)"},{"id":148,"question":"Cơ sở trực tiếp và chủ yếu nhất để hình thành khái niệm là","options":["A. Thế giới tự nhiên","B. Thực tiễn","C. Cảm giác","D. Tri gác và biểu tượng"],"answerLetter":"B","answerText":"B. Thực tiễn","notes":""},{"id":149,"question":"Trong chủ nghĩa Mác - Lênin, bộ phận lý luận nào có chức năng làm sáng tỏ bản chất và những quy luật chung nhất của mọi sự vận động, phát triển của thế giới?","options":["A. Triết học Mác - Lênin","B. Kinh tế chính trị Mác - Lênin","C. Chủ nghĩa xã hội khoa học","D. Không có bộ phận nào giữ chức năng đó vì chủ nghĩa Mác - Lênin thuộc khoa học xã hội"],"answerLetter":"A","answerText":"A. Triết học Mác - Lênin","notes":""},{"id":150,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, yếu tố cơ bản nhất tạo thành điều kiện sinh hoạt vật chất của xã hội là các yếu tố thuộc về","options":["A. Điều kiện tự nhiên","B. Điều kiện dân cư","C. Phương thức sản xuất ra của cải vật chất","D. Không có yếu tố nào là cơ bản nhất mà tùy thuộc các điều kiện lịch sử cụ thể khác nhau"],"answerLetter":"C","answerText":"C. Phương thức sản xuất ra của cải vật chất","notes":""},{"id":151,"question":"Chủ nghĩa Mác - Lênin sẽ phát triển đạt đến đâu?","options":["A. Đã phát triển đến mức hoàn toàn đầy đủ","B. Trong đó mọi vấn đề được giải quyết triệt để, chỉ cần nghiên cứu và vận dụng trong thực tiễn","C. Có thể thay thế cho mọi khoa học","D. Không ngừng phát triển trên cơ sở tổng kết những thành tựu mới của sự phát triển các khoa học và thực tiễn"],"answerLetter":"D","answerText":"D. Không ngừng phát triển trên cơ sở tổng kết những thành tựu mới của sự phát triển các khoa học và thực tiễn","notes":""},{"id":152,"question":"Theo quan điểm duy tâm, lực lượng sáng tạo ra lịch sử là :","options":["A. Quần chúng nhân dân lao động","B. Giai cấp thống trị xã hội","C. Các vĩ nhân, những cá nhân kiệt xuất","D. Giai cấp bị trị xã hội"],"answerLetter":"C","answerText":"C. Các vĩ nhân, những cá nhân kiệt xuất","notes":""},{"id":153,"question":"Chủ nghĩa nào mà sự tồn tại phát triển của nó thường gắn với lợi ích giai cấp và các lực lượng tiến bộ trong lịch sử?","options":["A. Duy vật thô sơ","B. Duy vật","C. Duy tâm khách quan","D. Chiết trung"],"answerLetter":"B","answerText":"B. Duy vật","notes":"(Cách hỏi khác: Theo quan điểm của chủ nghĩa duy tâm chủ quan, lực lượng sáng tạo ra lịch sử là lực lượng nào?)"},{"id":154,"question":"Hình thức hoạt động thực tiễn cơ bản nhất quy định các hình thức hoạt động khác là hình thức nào sau đây?","options":["A. Hoạt động chính trị xã hội","B. Hoạt động quan sát và thực nghiệm khoa học","C. Hoạt động sản xuất vật chất","D. Hoạt động kinh tế"],"answerLetter":"C","answerText":"C. Hoạt động sản xuất vật chất","notes":""},{"id":155,"question":"Theo quan điểm duy vật lịch sử thì xã hội có các loại hình sản xuất cơ bản nào?","options":["A. Sản xuất ra của cải vật chất, đời sống tinh thần và nghệ thuật","B. Sản xuất ra văn hóa, con người và đời sống tinh thần","C. Sản xuất ra của cải vật chất, tinh thần và văn hóa","D. Sản xuất ra của cải vật chất, tinh thần và con người"],"answerLetter":"D","answerText":"D. Sản xuất ra của cải vật chất, tinh thần và con người","notes":""},{"id":156,"question":"Theo quan điểm duy vật lịch sử, nguồn gốc sâu xa của các cuộc cách mạng là do đâu?","options":["A. Mâu thuẫn gay gắt giữa lực lượng sản xuất và quan hệ sản xuất","B. Giai cấp cầm quyền bị khủng hoảng về đường lối cai trị","C. Quần chúng lao động bị áp bức","D. Quần chúng lao động bị áp bức nặng nề"],"answerLetter":"A","answerText":"A. Mâu thuẫn gay gắt giữa lực lượng sản xuất và quan hệ sản xuất","notes":""},{"id":157,"question":"Chọn phương án đúng về đấu tranh giai cấp?","options":["A. Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp","B. Đấu tranh giai cấp là động lực mạnh mẽ nhất làm thay đổi xã hội","C. Đấu tranh giai cấp là một trong những động lực phát triển của xã hội","D. Đấu tranh giai cấp là động lực phát triển của xã hội"],"answerLetter":"A","answerText":"A. Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp","notes":""},{"id":158,"question":"\"Những thời đại kinh tế khác nhau không phải ở chỗ chúng sản xuất ra cái gì, mà là ở chỗ chúng sản xuất bằng cách nào, với những tư liệu lao động nào\". Câu nói trên là của ai?","options":["A. Ph.Ăng ghen","B. D. Ricardo","C. Mác"],"answerLetter":"C","answerText":"C. Mác","notes":""},{"id":159,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:","options":["Quá trình \"lịch sử tự nhiên\" của sự phát triển các hình thái kinh tế xã hội là quá trình phát triển theo(NHUNG HOÀNG)","A. Ý niệm tuyệt đối","B. Quy luật khách quan của xã hội","C. Quy luật của tự nhiên","D. Ý muốn chủ quan của con người"],"answerLetter":"B","answerText":"B. Quy luật khách quan của xã hội","notes":""},{"id":160,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:Chủ thể sáng tạo chân chính ra lịch sử là:","options":["A. Quần chúng nhân dân","B. Các cá nhân kiệt xuất, các vĩ nhân","C. Giai cấp thống trị","D. Tầng lớp tri thức trong xã hội"],"answerLetter":"A","answerText":"A. Quần chúng nhân dân","notes":""},{"id":161,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:Mỗi phương thức sản xuất đều được tạo nên bởi hai mặt:","options":["A. Kỹ thuật và công nghệ","B. Kỹ thuật và lao động","C. Kỹ thuật và kinh tế","D. Kỹ thuật và tổ chức"],"answerLetter":"C","answerText":"C. Kỹ thuật và kinh tế","notes":""},{"id":162,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:Thực chất của quá trình sản xuất vật chất là quá trình:","options":["A. Con người thực hiện sự cải biến giới tự nhiên","B. Con người nhận thức thế giới và bản thân mình","C. Con người thực hiện sáng tạo trong tư duy","D. Con người thực hiện lợi ích của mình"],"answerLetter":"A","answerText":"A. Con người thực hiện sự cải biến giới tự nhiên","notes":""},{"id":163,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:Nhân tố quyết định trong lực lượng sản xuât là nhân tố:","options":["A. Tư liệu sản xuất","B. Người lao động","C. Công cụ lao động"],"answerLetter":"B","answerText":"B. Người lao động","notes":""},{"id":164,"question":"Chọn câu trả lời đúng, đầy đủ nhất theo quan niệm duy vật lịch sử: Cách mạng xã hội giữ vai trò là","options":["A. Nguồn gốc và động lực tiến bộ của xã hội","B. Động lực phát triển của mọi xã hội","C. Một trong những phương thức, động lực phát triển xã hội","D. Phương thức, động lực cơ bản nhất của sự phát triển xã hội trong điều kiện xã hội có sự phân hóa thành đối kháng giai cấp"],"answerLetter":"D","answerText":"D. Phương thức, động lực cơ bản nhất của sự phát triển xã hội trong điều kiện xã hội có sự phân hóa thành đối kháng giai cấp","notes":""},{"id":165,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nguồn gốc, động lực cơ bản nhất của mọi quá trình phát triển xã hội là gì?","options":["A. Sự phát triển của khoa học","B. Sự vận động của mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất","C. Sự phát triển của khoa học công nghệ","D. Đấu tranh giai cấp"],"answerLetter":"B","answerText":"B. Sự vận động của mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất","notes":"(Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật lịch sử, cách mạng xã hội giữa vai trò gi?)"},{"id":166,"question":"Xét đến cùng, nhân tố quan trọng nhất quyết định sự thắng lợi của một trật tự xã hội mới là","options":["A. Năng suất lao động","B. Luật pháp","C. Chính trị","D. Kinh tế"],"answerLetter":"A","answerText":"A. Năng suất lao động","notes":""},{"id":167,"question":"Quan hệ sản xuất là phạm trù dùng để chi","options":["A. Quan hệ giữa con người sản xuất với người tiêu dùng trong quá trình sản xuất","B. Quan hệ giữa người với người trong quá trình sản xuất","C. Quan hệ giữa con người với tự nhiên trong quá trình sản xuất"],"answerLetter":"B","answerText":"B. Quan hệ giữa người với người trong quá trình sản xuất","notes":""},{"id":168,"question":"Chọn câu trả lời đúng.Lực lượng sản xuất bao gồm:","options":["A. Tư liệu sản xuất và người lao động","B. Người lao động và công cụ lao động","C. Người lai động và trình độ lao động của họ","D. Tư liệu sản xuất và các nguồn lực tự nhiên"],"answerLetter":"A","answerText":"A. Tư liệu sản xuất và người lao động","notes":""},{"id":169,"question":"Quan niệm cho rằng \"suy nghĩ của những người sống trong túp lều tranh luôn luôn khác với suy nghĩ của những kẻ sống trong cung điện\" là quan điểm của","options":["A. Chủ nghĩa duy tâm","B. Chủ nghĩa duy vật siêu hình","C. Chủ nghĩa duy vật lịch sử","D. Chủ nghĩa duy vật"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy vật siêu hình","notes":""},{"id":170,"question":"Bản chất của con người được quyết định bởi","options":["A. Các quan hệ xã hội","B. Giáo dục gia đình","C. Sự nỗ lực của cá nhân","D. Giáo dục nhà trường"],"answerLetter":"A","answerText":"A. Các quan hệ xã hội","notes":""},{"id":171,"question":"Một sinh viên chuẩn bị bài thuyết trình trong một tháng theo cách thức:Tuần đầu phác thảo đề cương và hàng ngày dành 30 phút sửa chữa bổ sung hoàn thiện.Vào buổi thuyết trình sinh viên đã có một bản thảo hoàn chỉnh.Công việc trên đã diễn ra theo quy luật, nguyên lý nào?","options":[],"answerLetter":"Quy luật lượng chất","answerText":"Quy luật lượng chất","notes":""},{"id":172,"question":"Đặc trưng chủ yếu của cách mạng xã hội là gì?","options":["A. Sự thay đổi về hệ tư tưởng nói riêng và toàn bộ đời sống tinh thần của xã hội nói chung","B. Sự thay đổi về cơ cấu, tổ chức hoạt động sản xuất ra của cải vật chất trong xã hội","C. Sự thay đổi chính quyền nhà nước từ tay giai cấp thống trị đã lỗi thời sang tay giai cấp cách mạng.","D. Sự thay đổi về thế lực cầm quyền trong cùng một giai cấp"],"answerLetter":"C","answerText":"C. Sự thay đổi chính quyền nhà nước từ tay giai cấp thống trị đã lỗi thời sang tay giai cấp cách mạng.","notes":""},{"id":173,"question":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra khuynh hướng cơ bản phổ biến của sự vận động và phát triển","options":["A. Quy luật thống nhất và đấu tranh của các mặt đối lập","B. Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","C. Quy luật phủ định của phủ định","D. Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"answerLetter":"C","answerText":"C. Quy luật phủ định của phủ định","notes":""},{"id":174,"question":"Khái niệm nào chỉ sự quy định, sự tác động qua lại, sự chuyển hoá lẫn nhau giữa các sự vật, hiện tượng hay giữa các mặt, các yếu tố trong một sự vật, hiện tượng?","options":["A. Mối liên hệ","B. Sự phát triển","C. Sự thay đổi","D. Sự biến đổi"],"answerLetter":"A","answerText":"A. Mối liên hệ","notes":""},{"id":175,"question":"Khái niệm quan hệ sản xuất được hiểu là","options":["A. Mối quan hệ giữa người với người trong quá trình sản xuất","B. Mối quan hệ giữa người với người trong quá trình tiêu dùng","C. Mối quan hệ giữa người với người trong quá trình phân phối","D. Mối quan hệ giữa người với người trong quá trình hoạch định"],"answerLetter":"A","answerText":"A. Mối quan hệ giữa người với người trong quá trình sản xuất","notes":""},{"id":176,"question":"Khái niệm lực lượng sản xuất được hiểu là","options":["A. Toàn bộ những năng lực thực tiễn dùng trong sản xuất của xã hội","B. Toàn bộ những năng lực thực tiễn dùng trong tiêu dùng của xã hội","C. Toàn bộ những năng lực thực tiễn dùng trong phân phối của xã hội","D. Toàn bộ những năng lực thực tiễn dùng trong hoạch định của xã hội"],"answerLetter":"A","answerText":"A. Toàn bộ những năng lực thực tiễn dùng trong sản xuất của xã hội","notes":""},{"id":177,"question":"Mối quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng là mối quan hệ:","options":["A. Luôn luôn thống nhất với nhau","B. Luôn luôn đối lập nhau","C. Thống nhất và đấu tranh giữa hai mặt đối lập","D. Thống nhất là căn bản, còn đấu tranh giữa chúng chỉ là tạm thời"],"answerLetter":"C","answerText":"C. Thống nhất và đấu tranh giữa hai mặt đối lập","notes":""},{"id":178,"question":"V.I. Lênin cho rằng: Tính....không thể tách rời tính phổ biến.","options":["A. Nhân quả","B. Tất nhiên","C. Đơn nhất","D. Hiện thực"],"answerLetter":"B","answerText":"B. Tất nhiên","notes":""},{"id":179,"question":"Thế giới quan là gì?","options":["A. Quan điểm, cách nhìn về XH","B. Quan điểm, cách nhìn về thế giới tự nhiên","C. Quan điểm, niềm tin, nhìn nhận về các sự vật cụ thể","D. Toàn bộ quan điểm và niềm tin định hướng hoạt động con người trong cuộc sống"],"answerLetter":"D","answerText":"D. Toàn bộ quan điểm và niềm tin định hướng hoạt động con người trong cuộc sống","notes":""},{"id":180,"question":"Ý thức tôn giáo là niềm tin của một bộ phận nhân dân, thường là yếu tố bền vững nhất trong đời sống tinh thần của mỗi con người, của xã hội là nguyên nhân gì (?) của sự tồn tại tôn giáo?","options":["A. Nhận thức.","B. Văn hóa.","C. Trình độ.","D. Tâm lý."],"answerLetter":"D","answerText":"D. Tâm lý.","notes":""},{"id":181,"question":"Nguồn gốc vận động và phát triển của các hình thái kinh tế - xã hội là gì?Chọn một câu trả lời đúng:","options":["A. Sự tăng lên không ngừng của năng xuất lao động.","B. Mâu thuẫn giai - tầng trong xã hội, sự thay đổi của quan hệ sản xuất.","C. Do việc giải quyết mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất, mâu thuẫn giữa cơ sở hạ tầng với kiến trúc thượng tầng.","D. Quần chúng nhân dân không ngừng nổi dậy đấu tranh chống các thế lực phản động trong xã hội."],"answerLetter":"C","answerText":"C. Do việc giải quyết mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất, mâu thuẫn giữa cơ sở hạ tầng với kiến trúc thượng tầng.","notes":""},{"id":182,"question":"Câu trả lời sau đây, câu nào diễn đạt chưa chuẩn xác:","options":["A. Chủ nghĩa Mác là học thuyết do C.Mác sáng lập.","B. Chủ nghĩa Mác là học thuyết về sự nghiệp giải phóng giai cấp vô sản và nhân dân lao động.","C. Chủ nghĩa Mác là thế giới quan và phương pháp luận chung của mọi nhận thức và thực tiễn.","D. Chủ nghĩa mác là học thuyết được xây dựng trên cơ sở kế thừa những tinh hoa của lịch sử tư tưởng nhân loại và thực tiễn cách mạng"],"answerLetter":"C","answerText":"C. Chủ nghĩa Mác là thế giới quan và phương pháp luận chung của mọi nhận thức và thực tiễn.","notes":""},{"id":183,"question":"Trong chỉ đạo thực tiễn cần căn cứ vào đâu để đề ra chủ trương, phương hướng hành động?","options":["A. Cái tất nhiên, bản chất, nội dung.","B. Cái ngẫu nhiên, hình thức, hiện tượng","C. Các phương án trả lời đều sai"],"answerLetter":"A","answerText":"A. Cái tất nhiên, bản chất, nội dung.","notes":""},{"id":184,"question":"Trong tác phẩm kinh điển nào sau đây, tác phẩm nào thể hiện tập trung việc V.I. Lênin đã kế thừa và phát triển quan niệm của chủ nghĩa Mác về vật chất, về mối quan hệ giữa vật chất và ý thức, tồn tại xã hội và ý thức xã hội:","options":["A. Làm gì.","B. Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán.","C. Ba nguồn gốc và ba bộ phận cấu thành chủ nghĩa Mác.","D. Bút ký triết học."],"answerLetter":"B","answerText":"B. Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán.","notes":""},{"id":185,"question":"Nội dung mặt thứ nhất của vấn đề cơ bản của triết học là:","options":["A. Quan hệ giữa vật chất với ý thức.","B. Quan hệ giữa ý thức với vật chất.","C. Khả năng nhận thức thế giới của con người.","D. Bản chất của thế giới là vật chất hay ý thức."],"answerLetter":"D","answerText":"D. Bản chất của thế giới là vật chất hay ý thức.","notes":"(Kiểu hỏi khác: Trong tác phẩm kinh điển nào sau đây, tác phẩm nào thể hiện tập trung việc V.I. Lênin đã kế thừa và phát triển tư tưởng biện chứng trong triết học của G.W.Ph. Hêghen? A. Làm gì? B. Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán. C. Ba nguồn gốc và ba bộ phận cấu thành chủ nghĩa Mác. D. Bút ký triết học.)"},{"id":186,"question":"Theo Ph. Ăngghen, chia vận động thành:","options":["A. Bốn hình thức vận động cơ bản","B. Năm hình thức vận động cơ bản","C. Sáu hình thức vận động cơ bản","D. Ba hình thức vận động cơ bản"],"answerLetter":"B","answerText":"B. Năm hình thức vận động cơ bản","notes":""},{"id":187,"question":"Phương thức sản xuất bao gồm:","options":["A. Lực lượng sản xuất và quan hệ sản xuất.","B. Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng.","C. Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng, kiến trúc thượng tầng"],"answerLetter":"A","answerText":"A. Lực lượng sản xuất và quan hệ sản xuất.","notes":""},{"id":188,"question":"Ý nghĩa định nghĩa vật chất của Lênin được thể hiện:","options":["A. Khẳng định tính thứ nhất của vật chất.","B. Cho phép xác định cái gì là vật chất trong lĩnh vực xã hội.","C. Các phương án trả lời đều đúng."],"answerLetter":"C","answerText":"C. Các phương án trả lời đều đúng.","notes":""},{"id":189,"question":"Chân lý có những tính chất gì?","options":["A. Tính khách quan, tính tuyệt đối, tính tương đối, tính hoàn chỉnh","B. Tính khách quan, tính tuyệt đối, tính tương đối, tính cụ thể","C. Tính khách quan, tính tuyệt đối, tính tương đối, tính phổ biến"],"answerLetter":"B","answerText":"B. Tính khách quan, tính tuyệt đối, tính tương đối, tính cụ thể","notes":""},{"id":190,"question":"Tư tưởng nôn nóng, đốt cháy giai đoạn phản ánh trực tiếp việc:","options":["A. Không vận dụng quy luật phủ định của phủ định","B. Không vận dụng đúng quy luật thống nhất và đấu tranh của các mặt đối lập","C. Không vận dụng đúng quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại"],"answerLetter":"C","answerText":"C. Không vận dụng đúng quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại","notes":""},{"id":191,"question":"Thực tiễn là:","options":["A. Hoạt động vật chất có mục đích mang tính lịch sử-xã hội của con người","B. Hoạt động tinh thần nhằm tạo ra các giá trị thẩm mỹ","C. Một số hoạt động vật chất và một số hoạt động tinh thần"],"answerLetter":"A","answerText":"A. Hoạt động vật chất có mục đích mang tính lịch sử-xã hội của con người","notes":""},{"id":192,"question":"Những hình thức nhận thức: Khái niệm, phán đoán, suy luận thuộc giai đoạn nhận thức nào?","options":["A. Nhận thức cảm tính","B. Nhận thức lý tính","C. Nhận thức thông thường","D. Nhận thức khoa học"],"answerLetter":"B","answerText":"B. Nhận thức lý tính","notes":""},{"id":193,"question":"Theo quan điểm của triết học Mác-Lênin, tiêu chuẩn của chân lý là gì?","options":["A. Tri thức do các thế hệ trước để lại","B. Tri thức được nhiều người công nhận","C. Thực tiễn","D. Lời nói của các vĩ nhân"],"answerLetter":"C","answerText":"C. Thực tiễn","notes":""},{"id":194,"question":"V.l. Lenin khẳng định: Chủ nghĩa Mác dựa vào... chứ không phải dựa vào... để vạch ra đương lối chính trị của mình.","options":["A. Khả năng/ Hiện thực.","B. Hiện thực/ Ngẫu nhiên.","C. Hiện thực/ Khả năng.","D. Tất yếu/ Ngẫu nhiên."],"answerLetter":"C","answerText":"C. Hiện thực/ Khả năng.","notes":""},{"id":195,"question":"V.I.Lênin cho rằng: nhận thức đi từ...đến..., từ bản chất ít sâu sắc đến bản chất sâu sắc hơn.","options":["A. Hình thức/ nội dung","B. Nội dung/ hình thức","C. Bản chất/ hiện tượng","D. Hiện tượng/ bản chất"],"answerLetter":"D","answerText":"D. Hiện tượng/ bản chất","notes":""},{"id":196,"question":"\"Bản chất chỉ là tên gọi trống rỗng mà con người tưởng tượng ra, nó không tồn tại trên thực tế\". Đây là quan niệm của trường phái triết học nào?","options":["A. Duy tâm khách quan","B. Bất khả vi","C. Duy vật biện chứng","D. Duy tâm chủ quan"],"answerLetter":"D","answerText":"D. Duy tâm chủ quan","notes":""},{"id":197,"question":"Trong quá trình vận động, phát triển của sự vật,... giữ vai trò quyết định...","options":["A. Hình thức/Nội dung","B. Nội dung/Hình thức","C. Hiện tượng/Bản chất","D. Ngẫu nhiên/Tất nhiên"],"answerLetter":"B","answerText":"B. Nội dung/Hình thức","notes":""},{"id":198,"question":"Trong các cụm từ dưới đây, cụm từ nào được xem là \"hình thức\" trong cặp phạm trù \"nội dung - hình thức\" mà phép biện chứng duy vật nghiên cứu: \" truyện kiều là...\"","options":["A. Tác phẩm của Nguyễn Du","B. Tác phẩm thơ lục bát","C. Tác phẩm có bìa màu xanh","D. Tác phẩm ra đời vào thế kỷ XVIII"],"answerLetter":"B","answerText":"B. Tác phẩm thơ lục bát","notes":""},{"id":199,"question":"C.Mác và Ph.Ăngghen cho rằng: Cái mà người ta quả quyết cho là...thì lại hoàn toàn do những cái...cấu thành và cái được coi là...lại là hình thức trong đó ẩn nấp...","options":["A. Tất yếu/ Ngẫu nhiên; Ngẫu nhiên/ Tất yếu.","B. Ngẫu nhiên/ Tất yếu; Tất yếu/ Ngẫu nhiên","C. Tất yếu/ Ngẫu nhiên; Tất yếu/ Ngẫu nhiên.","D. Ngẫu nhiên/ Tất yếu; Ngẫu nhiên/ Tất yếu"],"answerLetter":"A","answerText":"A. Tất yếu/ Ngẫu nhiên; Ngẫu nhiên/ Tất yếu.","notes":""},{"id":200,"question":"\"Đói nghèo\" và \"dốt nát\", hiện tượng nào là nguyên nhân, hiện tượng nào là kết quả?","options":["A. Đói nghèo là nguyên nhân, dốt nát là kết quả.","B. Dốt nát là nguyên nhân, đói nghèo là kết quả.","C. Cả hai đều là nguyên nhân.","D. Hiện tượng này vừa là nguyên nhân vừa là kết quả của hiện tượng kia."],"answerLetter":"D","answerText":"D. Hiện tượng này vừa là nguyên nhân vừa là kết quả của hiện tượng kia.","notes":""},{"id":201,"question":"Trong các cặp khái niệm dưới đây, cặp nào có quan hệ nhân quả?","options":["A. Đông - Tây","B. Nghèo - Dốt","C. Xuân - Hạ","D. Ngày - Đêm"],"answerLetter":"B","answerText":"B. Nghèo - Dốt","notes":""},{"id":202,"question":"Sai lầm của các nhà triết học cổ đại trong quan niệm về vật chất?","options":["A. Đồng nhất vật chất với một số dạng vật thể cụ thể, cảm tính.","B. Vật chất là tất cả cái tồn tại khách quan.","C. Vật chất là có thể nhận thức được.","D. Vật chất tự thân vận động."],"answerLetter":"A","answerText":"A. Đồng nhất vật chất với một số dạng vật thể cụ thể, cảm tính.","notes":""},{"id":203,"question":"Khái niệm trung tâm mà V.I. Lênin sử dụng để định nghĩa về vật chất là?","options":["A. Phạm trù triết học.","B. Thực tại khách quan.","C. Cảm giác.","D. Phản ánh."],"answerLetter":"B","answerText":"B. Thực tại khách quan.","notes":""},{"id":204,"question":"\"Tất cả cái gì đang vận động, đều vận động nhờ một cái khác nào đó\". Nhận định này gắn liền với hệ thống triết học nào? Hãy chọn phương án sai?","options":["A. Triết học duy vật.","B. Triết học duy tâm.","C. Triết học duy tâm khách quan.","D. Triết học duy tâm chủ quan."],"answerLetter":"A","answerText":"A. Triết học duy vật.","notes":""},{"id":205,"question":"Phép biện chứng của triết học Hêghen là:","options":["A. Phép biện chứng duy tâm chủ quan.","B. Phép biện chứng duy vật hiện đại.","C. Phép biện chứng ngây thơ, chất phác.","D. Phép biện chứng duy tâm khách quan."],"answerLetter":"D","answerText":"D. Phép biện chứng duy tâm khách quan.","notes":""},{"id":206,"question":"Chọn luận điểm thể hiện lập trường triết học duy tâm lịch sử:","options":["A. Quan hệ sản xuất mang tính vật chất.","B. Yếu tố kinh tế quyết định lịch sử.","C. Sự vận động và phát triển của xã hội, suy cho cùng là do tư tưởng của con người quyết định.","D. Kiến trúc thương tầng chỉ đóng vai trò thụ động trong lịch sử."],"answerLetter":"C","answerText":"C. Sự vận động và phát triển của xã hội, suy cho cùng là do tư tưởng của con người quyết định.","notes":"(Kiểu hỏi khác: Phép biện chứng của Hêghen là phép biện chứng gì?)"},{"id":207,"question":"Triết học trong xã hội có giai cấp được hiếu như thế nào?","options":["A. Cũng có tính giai cấp","B. Không có tính giai cấp","C. Chi triết học phương Tây mới có tính giai cấp","D. Chỉ có triết học phương Đông mới có tính giai cấp"],"answerLetter":"A","answerText":"A. Cũng có tính giai cấp","notes":""},{"id":208,"question":"Động lực của cách mạng xã hội là","options":["A. Giai cấp chân chính","B. Giai cấp tiến tiến","C. Giai cấp chiếm số đông"],"answerLetter":"B","answerText":"B. Giai cấp tiến tiến","notes":""},{"id":209,"question":"Trong thực tế chúng ta phải dựa vào khả năng hay hiện thực","options":["A. Khả năng","B. Hiện thực","C. Các phương án trả lời đều sai"],"answerLetter":"B","answerText":"B. Hiện thực","notes":""},{"id":210,"question":"Đặc điểm lớn nhất của thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta là","options":["A. Có nhiều thành phần kinh tế đan xen nhau","B. Từ một nền sản xuất nhỏ là phổ biến quá độ lên chủ nghĩa xã hội không qua chế độ tư bản chủ nghĩa","C. Năng suất lao động thấp"],"answerLetter":"B","answerText":"B. Từ một nền sản xuất nhỏ là phổ biến quá độ lên chủ nghĩa xã hội không qua chế độ tư bản chủ nghĩa","notes":""},{"id":211,"question":"Kết cấu của tồn tại xã hội bao gồm?","options":["A. Phương thức sản xuất, điều kiện dân số, điều kiện tự nhiên địa lý","B. Phương thức sản xuất, phương thức tiêu dùng, phương thức trao đổi hàng hóa","C. Phương thức sản xuất, điều kiện dân số, cơ sở hạ tầng xã hội"],"answerLetter":"A","answerText":"A. Phương thức sản xuất, điều kiện dân số, điều kiện tự nhiên địa lý","notes":""},{"id":212,"question":"Thêm cụm từ thích hợp vào chỗ trống của câu sau để được luận điểm của chủ nghĩa duy vật biện chứng về tính chất của các phạm trù: Nội dung của phạm trù có tính ..(1) ..., hình thức của phạm trù có tính...(2)...","options":["A. 1- chủ quan, 2- khách quan","B. 1- chủ quan, 2- chủ quan.","C. 1- khách quan, 2- chủ quan.","D. 1- khách quan, 2- khách quan"],"answerLetter":"C","answerText":"C. 1- khách quan, 2- chủ quan.","notes":""},{"id":213,"question":"Vật chất với tư cách là phạm trù triết học đã có lịch sử phát triển khoảng bao nhiêu năm","options":["A. 2500 năm","B. 3000 năm","C. 3500 năm","D. 4000 năm"],"answerLetter":"A","answerText":"A. 2500 năm","notes":""},{"id":214,"question":"Khái niệm \"bước nhảy\"?","options":["A. Sự đột biến","B. Chuyển dần về chất","C. Hoàn thiện chất","D. Quá trình biến đổi về chất diễn ra tại điểm nút"],"answerLetter":"D","answerText":"D. Quá trình biến đổi về chất diễn ra tại điểm nút","notes":""},{"id":215,"question":"Cuộc cách mạng xã hội chủ nghĩa đầu tiên trên thế giới là","options":["A. Cách mạng tháng Tám","B. Cách mạng tháng Mười Nga","C. Cách mạng Tân Hợi"],"answerLetter":"B","answerText":"B. Cách mạng tháng Mười Nga","notes":""},{"id":216,"question":"Lượng giá trị của đơn vị hàng hoá thay đổi","options":["A. Tỷ lệ nghịch với năng suất lao động, không phụ thuộc vào cường độ lao động.","B. Tỷ lệ thuận với năng suất lao động","C. Tỷ lệ nghịch với cường độ lao động"],"answerLetter":"A","answerText":"A. Tỷ lệ nghịch với năng suất lao động, không phụ thuộc vào cường độ lao động.","notes":""},{"id":217,"question":"Giá trị cá biệt của hàng hoá do","options":["A. Hao phí lao động cá biệt của người sản xuất quyết định","B. Hao phí lao động cá biệt của người sản xuất nhiều hàng hoá quyết định","C. Hao phí lao động của ngành quyết định"],"answerLetter":"A","answerText":"A. Hao phí lao động cá biệt của người sản xuất quyết định","notes":""},{"id":218,"question":"Thuật ngữ giai cấp công nhân và giai cấp vô sản","options":["A. Đồng nghĩa","B. Khác nghĩa","C. Không liên quan về nghĩa"],"answerLetter":"A","answerText":"A. Đồng nghĩa","notes":""},{"id":219,"question":"Biện chứng là phương pháp","options":["A. Thấy cái chung mà không thấy cái riêng","B. Thấy cái riêng mà không thấy cái chung","C. Vừa thấy cái chung và cái riêng","D. Vừa thấy cái chung, vừa thấy cái riêng và cái đơn nhất"],"answerLetter":"D","answerText":"D. Vừa thấy cái chung, vừa thấy cái riêng và cái đơn nhất","notes":""},{"id":220,"question":"Đặc điểm của quy luật triết học mang tính","options":["A. Chung nhất, khái quát nhất về thế giới","B. Cụ thể nhất, chi tiết nhất về thế giới","C. Toàn diện nhất, sâu sắc nhất về thế giới"],"answerLetter":"A","answerText":"A. Chung nhất, khái quát nhất về thế giới","notes":""},{"id":221,"question":"Phân công lao động xã hội","options":["A. Là một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền","B. Không dẫn đến sự hình thành tư bản độc quyền","C. Nguyên nhân hình thành chủ nghĩa tư bản","D. Là một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền nhà nước"],"answerLetter":"A","answerText":"A. Là một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền","notes":""},{"id":222,"question":"Triết học bao gồm những quan điểm chung nhất, những sự lý giải có luận chứng cho các câu hỏi chung của con người, nên triết học bao gồm toàn bộ tri thức của nhân loạiKết luận trên ứng với triết học thời kỳ nào?Chọn câu trả lời đúng.","options":["A. Triết học cổ đại","B. Triết học phục hưng","C. Triết học Trung cổ - Tây âu","D. Triết học Mác - Lênin"],"answerLetter":"A","answerText":"A. Triết học cổ đại","notes":""},{"id":223,"question":"Thời gian chu chuyển của tư bản được hiểu.","options":["A. Thời gian sản xuất + thời gian bán hàng.","B. Thời gian sản xuất + thời gian lưu thông.","C. Thời gian dự trữ sản xuất + thời gian lưu thông.","D. Thời gian sản xuất + thời gian tiếp thị."],"answerLetter":"B","answerText":"B. Thời gian sản xuất + thời gian lưu thông.","notes":""},{"id":224,"question":"Loại tái sản xuất nào làm tăng sản phẩm chủ yếu do tăng năng suất lao động và hiệu quả sử dụng các nguồn luc?","options":["A. Tái sản xuất mở rộng theo chiều rộng","B. Tái sản xuất mở rộng","C. Tái sản xuất mở rộng theo chiều sâu"],"answerLetter":"C","answerText":"C. Tái sản xuất mở rộng theo chiều sâu","notes":""},{"id":225,"question":"Ph.Ăngghen cho rằng: đối với ai phủ nhận..thì mọi quy luật tự nhiên đều là giả thuyết.","options":["A. Vấn đề nội dung hình thức","B. Phạm trù khả năng - hiện thực","C. Tính nhận quà","D. Tính biện chứng"],"answerLetter":"C","answerText":"C. Tính nhận quà","notes":""},{"id":226,"question":"Khi nghiên cứu phương thức sản xuất TBCN, C.Mác bắt đầu từ","options":["A. Sản xuất hàng hoá giản đơn và hàng hoá","B. Lưu thông hàng hoá","C. Sản xuất giá trị thặng dư"],"answerLetter":"A","answerText":"A. Sản xuất hàng hoá giản đơn và hàng hoá","notes":""},{"id":227,"question":"Coi vận động của vật chất chi là biểu hiện của vận động cơ học, đó là quan điểm về vận động và vật chất của ai","options":["A. Các nhà triết học thời kỳ cổ đại","B. Các nhà triết học siêu hình","C. Các nhà triết học duy vật biện chứng hiện đại","D. Các nhà triết học duy vật thời kỳ cổ đại"],"answerLetter":"B","answerText":"B. Các nhà triết học siêu hình","notes":""},{"id":228,"question":"Chon quan niệm đúng về con người theo quan điểm toàn diện của chủ nghĩa duy vật lịch sử. Con người là","options":["A. Thực thể vật chất tự nhiên","B. Thực thể chính trị và đạo đức","C. Thực thể chính trị, có tư duy và văn hóa","D. Thực thể tự nhiên và xã hội"],"answerLetter":"D","answerText":"D. Thực thể tự nhiên và xã hội","notes":""},{"id":229,"question":"Khẳng định nào sau đây là sai","options":["A. Triết học Mác là sự kết hợp phép biện chứng của Hêghen và chủ nghĩa duy tâm của Phoi - ơ - bắc","B. Triết học Mác có sự thống nhất giữa phương pháp biện chứng và thế giới quan duy vật","C. Triết học Mác kế thừa và cải tạo phép biện chứng của Hêghen trên cơ sở duy vật"],"answerLetter":"A","answerText":"A. Triết học Mác là sự kết hợp phép biện chứng của Hêghen và chủ nghĩa duy tâm của Phoi - ơ - bắc","notes":""},{"id":230,"question":"Chọn quan điểm đúng nhất trong các quan điểm sau đây.","options":["A. Vận động là phương thức tồn tại của vật chất","B. Không gian, thời gian là những phương thức tồn tại của vật chất","C. Vận động phương thức, không gian, thời gian là những hình thức tồn tại của vật chất"],"answerLetter":"A","answerText":"A. Vận động là phương thức tồn tại của vật chất","notes":""},{"id":231,"question":"Nội dung công cuộc đại phân công lao động xã hội lần thứ ba là:","options":["A. Đại công nghiệp tách khỏi nông nghiệp","B. Trồng trọt tách khỏi chăn nuôi","C. Ngành thương nghiệp ra đời","D. Thủ công nghiệp tách khỏi nông nghiệp"],"answerLetter":"C","answerText":"C. Ngành thương nghiệp ra đời","notes":"(Kiểu hỏi khác: Theo Triết học Mác - Lênin, yếu tố nào sau đây đóng vai trò là phương thức tôn tại của vật chất? A. Đứng im B. Vận động C. Không gian D. Thời gian)"},{"id":232,"question":"Định nghĩa giai cấp của Lênin dựa vào cơ sở nào sau đây","options":["A. Xã hội","B. Kinh tế","C. Chính trị"],"answerLetter":"B","answerText":"B. Kinh tế","notes":""},{"id":233,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng ở động vật bậc cao có thể đạt đến hình thức phản ánh nào","options":["A. Phản ánh ý thức","B. Phản ánh tâm lý động vật","C. Tỉnh kích thích","D. Phản ánh sinh học"],"answerLetter":"B","answerText":"B. Phản ánh tâm lý động vật","notes":""},{"id":234,"question":"Theo quan điểm của KTCT, trong tư liệu lao động bộ phận nào quyết định đến năng suất lao động?","options":["A. Công cụ lao động","B. Nguyên vật liệu cho sản xuất","C. Các vật chứa đựng, bảo quản","D. Kết cấu hạ tầng sản xuất"],"answerLetter":"A","answerText":"A. Công cụ lao động","notes":""},{"id":235,"question":"Quan điểm nào sau đây phản ánh đầy đủ nội dung khái niệm tồn tại xã hội","options":["A. Tồn tại xã hội là phạm trù dùng chỉ toàn bộ điều kiện vật chất của xã hội","B. Tồn tại xã hội là phạm trù dùng chi toàn bộ các giá trị tinh thần của xã hội","C. Tồn tại xã hội là phạm trù dùng chỉ toàn bộ các điều kiện sinh hoạt của xã hội"],"answerLetter":"A","answerText":"A. Tồn tại xã hội là phạm trù dùng chỉ toàn bộ điều kiện vật chất của xã hội","notes":"(Cách hỏi khác: Tư liệu lao động gồm có:)"},{"id":236,"question":"Phương pháp rút ra kết quả riêng từ những kết luận chung, không tính đến sự tồn tại thực tế của sự vật, được gọi là?","options":["A. Phương pháp quy nạp","B. Phương pháp diễn dịch","C. Phương pháp kinh nghiệm","D. Phương pháp kinh viện"],"answerLetter":"D","answerText":"D. Phương pháp kinh viện","notes":""},{"id":237,"question":"Cái do nguyên nhân cơ bản bên trong của kết cấu vật chất quyết định và trong những điều kiện nhất định nó phải xảy ra như thể chứ không thể khác được gọi là?","options":["A. Tất nhiên","B. Ngẫu nhiên","C. Hệ quả","D. Bản chất"],"answerLetter":"A","answerText":"A. Tất nhiên","notes":""},{"id":238,"question":"Trong chủ nghĩa tư bản, ... quan hệ giữa giai cấp tư sản và giai cấp công nhân là quan hệ bóc lột.","options":["A. Hình thức","B. Nội dung","C. Bản chất","D. Hiện tượng"],"answerLetter":"C","answerText":"C. Bản chất","notes":""},{"id":239,"question":"Để làm rõ vai trò của các bộ phận tư bản trong việc tạo ra giá trị thặng dư, tư bản được chia thành","options":["A. Tư bản độc quyền và tư bản nhà nước","B. Tư bản bất biến và tư bản khả biến","C. Tư bản cố định và tư bản lưu động"],"answerLetter":"B","answerText":"B. Tư bản bất biến và tư bản khả biến","notes":""},{"id":240,"question":"Trong xã hội phân chia giai cấp","options":["A. Đấu tranh giai cấp là nguồn gốc và động lực vận động và phát triển xã hội","B. Đấu tranh giai cấp là nguyên nhân chủ yếu của vận động và phát triển xã hội","C. Đấu tranh giai cấp là động lực chủ yếu dẫn đến sự vận động và phát triển xã hội"],"answerLetter":"A","answerText":"A. Đấu tranh giai cấp là nguồn gốc và động lực vận động và phát triển xã hội","notes":""},{"id":241,"question":"Các tổ chức độc quyền sử dụng giá cả độc quyền để","options":["A. Củng cố vai trò tổ chức độc quyền","B. Chiếm đoạt giá trị thặng dư của người khác","C. Gây thiệt hại cho các đối thủ cạnh tranh"],"answerLetter":"B","answerText":"B. Chiếm đoạt giá trị thặng dư của người khác","notes":""},{"id":242,"question":"Chọn câu trả lời đúng theo quan điểm của chủ nghĩa duy vật lịch sử:Trong mối quan hệ giữa lực lượng sản xuất và quan hệ sản xuất","options":["A. Lực lượng sản xuất là yếu tố thường xuyên biến đổi, phát triển","B. Quan hệ sản xuất là yếu tố thường xuyên biến đổi, phát triển","C. Cả hai đều là những yếu tố thường xuyên biến đổi, phát triển","D. Không có yếu tố nào thường xuyên biến đổi, phát triển"],"answerLetter":"A","answerText":"A. Lực lượng sản xuất là yếu tố thường xuyên biến đổi, phát triển","notes":""},{"id":243,"question":"Tư bản cố định và tư bản lưu động thuộc phạm trù tư bản nào?","options":["A. Tư bản sản xuất.","B. Tư bản tiền tệ.","C. Tư bản bất biến."],"answerLetter":"A","answerText":"A. Tư bản sản xuất.","notes":""},{"id":244,"question":"Theo quan điểm Mác-Lênin, chủ nghĩa cộng sản chia làm mấy giai đoạn","options":["A. 2 giai đoạn","B. 3 giai đoạn","C. 4 giai đoạn"],"answerLetter":"A","answerText":"A. 2 giai đoạn","notes":""},{"id":245,"question":"Cơ chế kinh tế của CNTB độc quyền nhà nước gồm:","options":["A. Cơ chế thị trường, độc quyền tư nhân và sự can thiệp của nhà nước","B. Cơ chế thị trường, các nhà tài phiệt và sự điều tiết của nhà nước","C. Cơ chế thị trường và độc quyền tư nhân"],"answerLetter":"A","answerText":"A. Cơ chế thị trường, độc quyền tư nhân và sự can thiệp của nhà nước","notes":""},{"id":246,"question":"Đâu là nội dung nguyên lý của phép biện chứng duy vật về mối liên hệ phổ biến của các sự vật và hiện tượng","options":["A. Các sự vật và hiện tượng trong thế giới tồn tại tách rời nhau, giữa chúng không có sự phụ thuộc, ràng buộc lẫn nhau.","B. Các sự vật có sự liên hệ tác động nhau nhưng không có sự chuyển hóa lẫn nhau","C. Sự vật khác nhau ở vẻ bề ngoài, do chủ quan con người quy định, bản chất sự vật không có gì khác nhau","D. Thế giới là một chính thể thống nhất bao gồm các sự vật, các quá trình vừa tách biệt nhau, vừa có mối liên hệ qua lại với nhau, vừa thâm nhập và chuyển hóa cho nhau"],"answerLetter":"D","answerText":"D. Thế giới là một chính thể thống nhất bao gồm các sự vật, các quá trình vừa tách biệt nhau, vừa có mối liên hệ qua lại với nhau, vừa thâm nhập và chuyển hóa cho nhau","notes":""},{"id":247,"question":"Giai cấp công nhân hình thành và phát triển mạnh trong xã hội nào.","options":["A. Xã hội chiếm hữu nô lệ","B. Xã hội phong kiến","C. Xã hội tư bản chủ nghĩa","D. Xã hội xã hội chủ nghĩa"],"answerLetter":"C","answerText":"C. Xã hội tư bản chủ nghĩa","notes":""},{"id":248,"question":"Công cuộc đổi mới xã hội chủ nghĩa diễn ra ở nước nào sau đây","options":["A. Trung Quốc","B. Việt Nam","C. Cu Ba"],"answerLetter":"B","answerText":"B. Việt Nam","notes":""},{"id":249,"question":"Hai khái niệm triết học cùng với thế giới quan...","options":["A. Là trùng nhau vì đều là hệ thống quan điểm chung về thế giới","B. Triết học không phải là toàn bộ thế giới quan mà chỉ là hạt nhân lý luận chung nhất của thế giới quan","C. Không phải mọi triết học đều là hạt nhân lý luận của thế giới quan mà chỉ có triết học Mác - Lênin mới là hạt nhân lý luận của thế giới quan","D. Là hoàn toàn khác nhau"],"answerLetter":"B","answerText":"B. Triết học không phải là toàn bộ thế giới quan mà chỉ là hạt nhân lý luận chung nhất của thế giới quan","notes":""},{"id":250,"question":"Nhà nước xã hội chủ nghĩa","options":["A. Tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc","B. Không tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc","C. Không can thiệp vào vấn đề dân tộc"],"answerLetter":"A","answerText":"A. Tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc","notes":""},{"id":251,"question":"Cạnh tranh kinh tế được hiểu là","options":["A. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành chi phí tối đa cho mình.","B. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành lợi ích tối đa cho mình.","C. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành thị phần tối đa cho mình.","D. Sự đấu tranh ở giữa các chủ thể kinh tế."],"answerLetter":"B","answerText":"B. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành lợi ích tối đa cho mình.","notes":""},{"id":252,"question":"Trong nền sản xuất lớn hiện đại, yếu tố nào giữ vai trò quyết định của quá trình lao động sản xuất?","options":["A. Sức lao động","B. Tư liệu sản xuất hiện đại","C. Công cụ sản xuất tiên tiến","D. Đối tượng lao động"],"answerLetter":"A","answerText":"A. Sức lao động","notes":""},{"id":253,"question":"Ngày lao động của công nhân bao gồm?","options":["A. Thời gian lao động giản đơn, thời gian lao động thặng dư.","B. Thời gian lao động phức tạp, thời gian lao động thặng dư.","C. Thời gian lao động cần thiết, thời gian lao động thặng dư.","D. Tất cả phương án trên"],"answerLetter":"C","answerText":"C. Thời gian lao động cần thiết, thời gian lao động thặng dư.","notes":""},{"id":254,"question":"Tích lũy tư bản dẫn đến","options":["A. Hình thành chủ nghĩa tư bản độc quyền","B. Hình thành chủ nghĩa tư bản độc quyền nhà nước","C. Hình thành chủ nghĩa tư bản"],"answerLetter":"A","answerText":"A. Hình thành chủ nghĩa tư bản độc quyền","notes":""},{"id":255,"question":"Cái chung chỉ tồn tại trong","options":["A. Cái riêng","B. Cái đơn nhất","C. Cái cụ thể"],"answerLetter":"A","answerText":"A. Cái riêng","notes":""},{"id":256,"question":"Luận điểm \"Mối liên hệ nhân quả là do cảm giác con người quy định\" thuộc lập trường triết học nào?","options":["A. Chủ nghĩa duy tâm khách quan","B. Chủ nghĩa duy tâm chủ quan","C. Chủ nghĩa duy vật biện chứng","D. Chủ nghĩa duy vật siêu hình"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy tâm chủ quan","notes":""},{"id":257,"question":"Theo quan điểm chủ nghĩa duy vật biện chứng thì đứng im là một trạng thái đặc biệt của vận động.","options":["A. Tuyệt đối","B. Trong cân bằng","C. Tại chỗ","D. Tỉnh tại"],"answerLetter":"B","answerText":"B. Trong cân bằng","notes":""},{"id":258,"question":"Theo chủ nghĩa Mác - Lênin, triết học khác với các khoa học khác ở chỗ nào?","options":["A. Tính đặc thù của hệ thống tri thức khoa học và phương pháp nghiên cứu","B. Tính đặc thù của hệ thống tri thức và phương pháp nghiên cứu khoa học","C. Tính đặc thù của khoa học và phương pháp nghiên cứu đặc thù","D. Tính biện chứng và siêu hình"],"answerLetter":"A","answerText":"A. Tính đặc thù của hệ thống tri thức khoa học và phương pháp nghiên cứu","notes":""},{"id":259,"question":"Về cấu trúc, tư liệu sản xuất thuộc mặt nào trong lực lượng sản xuất?","options":["A. Kinh tế - kỹ thuật","B. Người lao động","C. Nhà xưởng, máy móc","D. Phương tiện thanh toán"],"answerLetter":"A","answerText":"A. Kinh tế - kỹ thuật","notes":""},{"id":260,"question":"Nội dung cơ bản của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là gì?","options":["A. Thực hiện thắng lợi mục tiêu độc lập dân tộc","B. Xây dựng một xã hội phát triển toàn diện","C. Đảm bảo sự phát triển toàn diện cho mọi người dân","D. Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội, xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh"],"answerLetter":"D","answerText":"D. Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội, xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh","notes":""},{"id":261,"question":"Nếu quá đề cao triết học duy tâm sẽ dẫn đến","options":["A. Xa rời thực tế","B. Cực đoan","C. Thực dụng"],"answerLetter":"A","answerText":"A. Xa rời thực tế","notes":""},{"id":262,"question":"Phát triển là quá trình","options":["A. Tiến lên theo đường vòng khép kín","B. Tiến lên theo đường quanh co khúc khuỷu, thăng trầm, phức tạp","C. Quá trình tiến lên theo đường thẳng tắp"],"answerLetter":"B","answerText":"B. Tiến lên theo đường quanh co khúc khuỷu, thăng trầm, phức tạp","notes":""},{"id":263,"question":"Khẳng định mối liên hệ giữa các sự vật, hiện tượng do sự quy định của các lực lượng siêu nhiên là quan điểm của","options":["A. Chủ nghĩa duy tâm chủ quan","B. Chủ nghĩa duy tâm khách quan","C. Chủ nghĩa duy vật siêu hình"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy tâm khách quan","notes":""},{"id":264,"question":"Vấn đề cơ bản của triết học gồm hai mặt đó là","options":["A. Bản thể luận và nhận thức luận","B. Lý luận và thực tiễn","C. Tri thức và chân lý"],"answerLetter":"A","answerText":"A. Bản thể luận và nhận thức luận","notes":""},{"id":265,"question":"Phương pháp luận là lý luận chung về","options":["A. Phương pháp","B. Giải pháp","C. Phương châm"],"answerLetter":"A","answerText":"A. Phương pháp","notes":""},{"id":266,"question":"Tác phẩm nào được xem là đánh dấu cho sự chín muồi về tư tưởng xã hội chủ nghĩa của C.Mác và Ăng-ghen","options":["A. Gia đình thần thánh (1842)","B. Hệ tư tưởng Đức (1842)","C. Tuyên ngôn của Đảng cộng sản (1848)"],"answerLetter":"C","answerText":"C. Tuyên ngôn của Đảng cộng sản (1848)","notes":""},{"id":267,"question":"Triết học duy vật biện chứng là sự thống nhất giữa","options":["A. Thế giới quan duy vật và phương pháp luận biện chứng","B. Nhân sinh quan duy vật và phương pháp luận biện chứng","C. Thế giới quan duy vật và phương pháp luận siêu hình"],"answerLetter":"A","answerText":"A. Thế giới quan duy vật và phương pháp luận biện chứng","notes":"(Kiểu hỏi khác: Tác phẩm nào sau đây được đánh giá là văn kiện đầu tiên có tính cương lĩnh của chủ nghĩa Mác, thể hiện sự chín muối về mặt thế giới quan mới của C. Mác và Ăngghen?)"},{"id":268,"question":"Biện chứng là phương pháp của khoa học nào sau đây","options":["A. Triết học","B. Đạo đức học","C. Chính trị học"],"answerLetter":"A","answerText":"A. Triết học","notes":""},{"id":269,"question":"Giữa phạm trù triết học và phạm trù của các khoa học khác có mối quan hệ biện chứng với nhau. Mối quan hệ đó là","options":["A. Quan hệ giữa bản chất và hiện tượng","B. Quan hệ giữa cái chung và cái riêng","C. Quan hệ giữa nội dung và hình thức"],"answerLetter":"B","answerText":"B. Quan hệ giữa cái chung và cái riêng","notes":""},{"id":270,"question":"Sự vật mới ra đời bao giờ cũng trên cơ sở những cái đã có của sự vật cũ, qua đó tiến hành chọn lọc những cái tích cực, tiến bộ, phù hợp để tiếp tục phát triển. Điều này thể hiện tính chất gì của sự phát triển","options":["A. Tính kế thừa","B. Tính lặp đi lặp lại","C. Tính tiến lên"],"answerLetter":"A","answerText":"A. Tính kế thừa","notes":""},{"id":271,"question":"Mác đã kế thừa \"hạt nhân hợp lý\" trong triết học của ông để xây dựng phép biện chứng duy vật. Ông là ai?","options":["A. Phơ bách","B. Platon","C. Hê ghen"],"answerLetter":"C","answerText":"C. Hê ghen","notes":""},{"id":272,"question":"Theo sự phát triển của xã hội, thứ tự phát triển của các hình thức cộng đồng trong lịch sử là","options":["A. Thị tộc - Bộ lạc - Bộ tộc - Dân tộc","B. Thị tộc - Bộ tộc - Bộ lạc - Dân tộc","C. Dân tộc - Thị tộc - Bộ lạc - Bộ tộc"],"answerLetter":"A","answerText":"A. Thị tộc - Bộ lạc - Bộ tộc - Dân tộc","notes":"(Học hiểu câu hỏi để trả lời câu: Hạt nhân hợp lý của thế giới quan khoa học là chủ nghĩa nào? A. Duy vật B. Mác C. Duy vật biện chúng D. Lênin)"},{"id":273,"question":"Theo quan điểm của Triết học Mác-Lênin, có thể định nghĩa về vật chất như sau:","options":["A. Vật chất là những chất tạo nên vũ trụ","B. Vật chất là tồn tại khách quan","C. Vật chất là thực tại khách quan"],"answerLetter":"C","answerText":"C. Vật chất là thực tại khách quan","notes":""},{"id":274,"question":"Vật chất là tất cả những gì","options":["A. Tồn tại một cách cụ thể, có thể nhìn thấy","B. Tồn tại vô hình, thần bí ở bên ngoài thế giới khách quan","C. Tồn tại ở bên ngoài ý thức, được ý thức con người phản ánh","D. Tồn tại vô hình, không thể nhìn thấy"],"answerLetter":"C","answerText":"C. Tồn tại ở bên ngoài ý thức, được ý thức con người phản ánh","notes":""},{"id":275,"question":"Vấn đề cơ bản của triết học là","options":["A. Quan hệ giữa vật chất và ý thức","B. Quan hệ giữa khách quan và chủ quan","C. Quan hệ giữa thực tiễn và lí luận"],"answerLetter":"A","answerText":"A. Quan hệ giữa vật chất và ý thức","notes":""},{"id":276,"question":"Kết cấu của ý thức theo chiều dọc thì bao gồm","options":["A. Tự ý thức, tiềm thức, vô thức","B. Tự ý thức, tri thức, tiềm thức, vô thức","C. Các phương án trả lời đều sai"],"answerLetter":"A","answerText":"A. Tự ý thức, tiềm thức, vô thức","notes":""},{"id":277,"question":"Định nghĩa vật chất của Lênin được viết trong tác phẩm:","options":["A. Bút ký triết học","B. Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán","C. Chủ nghĩa đế quốc - giai đoạn tột cùng của chủ nghĩa tư bản","D. Làm gì?"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán","notes":""},{"id":278,"question":"Nền tảng lý luận của chủ nghĩa Mác-Lênin là","options":["A. Triết học","B. Kinh tế chính trị học","C. Chủ nghĩa xã hội khoa học"],"answerLetter":"A","answerText":"A. Triết học","notes":""},{"id":279,"question":"Bản chất của triết học duy tâm như thế nào","options":["A. Đi ngược lại với khoa học","B. Không hoàn toàn phản khoa học","C. Rất khoa học"],"answerLetter":"B","answerText":"B. Không hoàn toàn phản khoa học","notes":""},{"id":280,"question":"Quan điểm nào sau đây đúng nhất","options":["A. Phạm trù là những thực thể ý niệm, tồn tại bên ngoài và độc lập với ý thức.","B. Phạm trù là những từ trống rỗng, do con người tưởng tượng ra, không biểu hiện một cái gì của hiện thực.","C. Phạm trù là kết quả của quá trình nhận thức, là hình ảnh chủ quan của thế giới khách quan."],"answerLetter":"C","answerText":"C. Phạm trù là kết quả của quá trình nhận thức, là hình ảnh chủ quan của thế giới khách quan.","notes":""},{"id":281,"question":"Tất nhiên là phạm trù triết học dùng để chỉ","options":["A. Những gì đang tồn tại và phát triển","B. Những gì sẽ xuất hiện do nguyên nhân bên trong quyết định","C. Những gì sẽ xuất hiện trong thực tế"],"answerLetter":"B","answerText":"B. Những gì sẽ xuất hiện do nguyên nhân bên trong quyết định","notes":""},{"id":282,"question":"Quan điểm nào cho rằng sự phát triển chỉ là sự tăng, giảm đơn thuần về mặt lượng, không có sự thay đổi về chất","options":["A. Quan điểm duy vật","B. Quan điểm duy tâm","C. Quan điểm siêu hình"],"answerLetter":"C","answerText":"C. Quan điểm siêu hình","notes":""},{"id":283,"question":"Thuộc tính cơ bản được Lênin rút ra trong định nghĩa phạm trù vật chất là","options":["A. Thực tại khách quan","B. Thực tế khách quan","C. Tồn tại khách quan"],"answerLetter":"A","answerText":"A. Thực tại khách quan","notes":""},{"id":284,"question":"Chủ nghĩa Mác-Lênin ra đời vào khoảng thời gian nào","options":["A. Giữa thế kỷ XIX","B. Đầu thế kỷ XIX","C. Đầu thế kỷ XX","D. Cuối thế kỷ XIX"],"answerLetter":"A","answerText":"A. Giữa thế kỷ XIX","notes":""},{"id":285,"question":"Cặp phạm trù nguyên nhân, kết quả chỉ ra(073-356-8678)","options":["A. Một kết quả có thể được tạo ra bởi nhiều nguyên nhân khác nhau","B. Một kết quả chỉ được tạo ra bởi một nguyên nhân cơ bản","C. Các phương án trả lời đều sai"],"answerLetter":"A","answerText":"A. Một kết quả có thể được tạo ra bởi nhiều nguyên nhân khác nhau","notes":""},{"id":286,"question":"Theo Ăng-ghen, có thể chia vận động thành:","options":["A. Bốn hình thức vận động cơ bản","B. Năm hình thức vận động cơ bản","C. Sáu hình thức vận động cơ bản"],"answerLetter":"B","answerText":"B. Năm hình thức vận động cơ bản","notes":"(Kiểu hỏi khác: Tính chất phong phú, đa dạng trong quan hệ nhân quả thể hiện ở chỗ một kết quả có thể do: A. Một nguyên nhân sinh ra B. Nhiều nguyên nhân khác nhau sinh ra C. Các phương án trà lời đêu sai)"},{"id":287,"question":"Mối liên hệ nhân quả có các tính chất cơ bản nào sau đây","options":["A. Tính khách quan, tính phổ biến, tính đa dạng.","B. Tính khách quan, tính phổ biến, kế thừa.","C. Tính khách quan, tính phổ biến, tính tất yếu."],"answerLetter":"C","answerText":"C. Tính khách quan, tính phổ biến, tính tất yếu.","notes":""},{"id":288,"question":"Phạm trù triết học nào dùng để chỉ tính quy định khách quan vốn có của sự vật và hiện tượng, sự thống nhất hữu cơ của các thuộc tính làm cho nó là nó mà không phải là cái khác","options":["A. Bước nhảy","B. Lượng","C. Chất"],"answerLetter":"C","answerText":"C. Chất","notes":""},{"id":289,"question":"Khẳng định nào sau đây là đúng?","options":["A. Mỗi sự vật cụ thể được đặc trưng bằng nhiều hình thức vận động","B. Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","C. Có sự vật không vận động","D. Có thể quy hình thức vận động cao về hình thức vận động thấp và ngược lại"],"answerLetter":"B","answerText":"B. Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","notes":""},{"id":290,"question":"Chọn phương án phản ánh quan điểm Mác-Lênin","options":["A. Trong giới hạn của độ, lượng của sự vật thay đổi nhưng chất của sự vật chưa thay đổi cơ bản","B. Trong giới hạn của độ, sự thay đổi về lượng hoàn toàn không làm ảnh hưởng tới sự thay đổi chất của sự vật","C. Bước nhảy là sự thay đổi về lượng của sự vật","D. Sự thay đổi về lượng sẽ làm thay đổi ngay lập tức chất của sự vật"],"answerLetter":"A","answerText":"A. Trong giới hạn của độ, lượng của sự vật thay đổi nhưng chất của sự vật chưa thay đổi cơ bản","notes":""},{"id":291,"question":"Quan điểm toàn diện yêu cầu","options":["A. Phải xem xét tất cả các mối liên hệ, đồng thời phân loại được vị trí, vai trò của các mối liên hệ.","B. Xem xét tất cả các mối liên hệ, lấy mối liên hệ thứ yếu làm mối liên hệ chủ yếu, không cơ bản làm cơ bản.","C. Xem xét tất cả các mối liên hệ và coi vị trí, vai trò của các mối liên hệ đó là như nhau.","D. Chỉ xem xét những mối liên hệ đóng vai trò quyết định sự tồn tại và phát triển của sự vật."],"answerLetter":"A","answerText":"A. Phải xem xét tất cả các mối liên hệ, đồng thời phân loại được vị trí, vai trò của các mối liên hệ.","notes":""},{"id":292,"question":"Vật chất là tất cả những gì","options":["A. Chỉ có một thế giới duy nhất là thế giới vật chất","B. Mọi bộ phận của thế giới vật chất đều liên hệ chuyển hóa lẫn nhau","C. Thế giới vật chất tồn tại vĩnh viễn, khách quan, vô hạn, vô tận, không do ai sinh ra và không mất đi","D. Thế giới vật chất bao gồm những bộ phận riêng biệt nhau"],"answerLetter":"C","answerText":"C. Thế giới vật chất tồn tại vĩnh viễn, khách quan, vô hạn, vô tận, không do ai sinh ra và không mất đi","notes":""},{"id":293,"question":"Chọn phương án đúng theo quan điểm của triết học Mác Lênin","options":["A. Mâu thuẫn biện chứng là sự liên hệ, tác động qua lại giữa các mặt đối lập","B. Trong tư duy không có mâu thuẫn biện chứng","C. Cứ hai mặt đối lập là tạo thành một mâu thuẫn biện chứng","D. Mâu thuẫn biện chứng trong tư duy độc lập với mâu thuẫn trong hiện thực"],"answerLetter":"A","answerText":"A. Mâu thuẫn biện chứng là sự liên hệ, tác động qua lại giữa các mặt đối lập","notes":""},{"id":294,"question":"Chọn phương án đúng theo quan điểm triết học Mác- Lênin","options":["A. Lượng của sự vật luôn được diễn tả bằng những con số chính xác","B. Có những lượng không biểu thị yếu tố nào của sự vật","C. Mỗi sự vật chỉ có một lượng","D. Có những lượng biểu thị yếu tố quy định kết cấu bên trong sự vật"],"answerLetter":"D","answerText":"D. Có những lượng biểu thị yếu tố quy định kết cấu bên trong sự vật","notes":""},{"id":295,"question":"Quy luật bao giờ cũng mang tính:","options":["A. Khách quan","B. Chủ quan","C. Cả khách quan và chủ quan","D. Phụ thuộc vào ý thức con người"],"answerLetter":"A","answerText":"A. Khách quan","notes":""},{"id":296,"question":"Luận điểm nào sau đây là đúng?","options":["A. Chất mới của sự vật ra đời không tác động trở lại lượng của sự vật","B. Chất mới ra đời chỉ làm thay đổi kết cấu nhưng không làm thay đổi quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật","C. Chất mới ra đời có thể làm thay đổi kết cấu, quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật","D. Chất mới ra đời chỉ làm thay đổi quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật nhưng không làm thay đổi kết cấu của sự vật"],"answerLetter":"C","answerText":"C. Chất mới ra đời có thể làm thay đổi kết cấu, quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật","notes":""},{"id":297,"question":"Tính quy định nói lên quy mô, trình độ phát triển của sự vật gọi là gì?","options":["A. Bước nhảy","B. Độ","C. Lượng","D. Chất"],"answerLetter":"C","answerText":"C. Lượng","notes":""},{"id":298,"question":"Yếu tố cách mạng nhất trong lực lượng sản xuất là:","options":["A. Phương tiện lao động","B. Người lao động","C. Đối tượng lao động","D. Công cụ lao động"],"answerLetter":"D","answerText":"D. Công cụ lao động","notes":""},{"id":299,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử:Sản xuất ra của cải vật chất giữ vai trò là:","options":["A. Nền tảng của xã hội","B. Nền tảng vật chất của xã hội","C. Nền tảng tinh thần của xã hội","D. Nền tảng kỹ thuật, công nghệ của xã hội"],"answerLetter":"B","answerText":"B. Nền tảng vật chất của xã hội","notes":""},{"id":300,"question":"Cách thức của sự phát triển là","options":["A. Đấu tranh của các mặt đối lập để giải quyết mâu thuẫn","B. Sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","C. Hai lần phủ định"],"answerLetter":"B","answerText":"B. Sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","notes":""},{"id":301,"question":"Quy luật xã hội nào giữ vai trò quyết định nhất đối với sự vận động, phát triển của xã hội?","options":["A. Quy luật tồn tại xã hội quyết định ý thức xã hội","B. Quy luật về sự phù hợp của quan hệ sản xuất với trình độ phát triển của lực lượng sản xuất","C. Quy luật đấu tranh giai cấp","D. Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng"],"answerLetter":"B","answerText":"B. Quy luật về sự phù hợp của quan hệ sản xuất với trình độ phát triển của lực lượng sản xuất","notes":""},{"id":302,"question":"Nguồn gốc lý luận trực tiếp của triết học Mác là","options":["A. Triết học Hy Lạp cổ đại","B. Triết học cổ điển Đức","C. Triết học tây Âu trung cổ"],"answerLetter":"B","answerText":"B. Triết học cổ điển Đức","notes":""},{"id":303,"question":"Theo triết học Mác-Lênin, khẳng định nào sau đây là đúng?","options":["A. Ý thức là sự phản ánh hiện thực khách quan theo nhu cầu nhận thức của con người","B. Ý thức là hình ảnh chủ quan của thế giới khách quan, là tinh thần so với thế giới vật chất.","C. Ý thức con người mang tính năng động sáng tạo lại hiện thực theo nhu cầu của nhận thức.","D. Ý thức là quá trình phản ánh hiện thực khách quan vào trong bộ óc con người một cách đơn giản, nguyên xi"],"answerLetter":"B","answerText":"B. Ý thức là hình ảnh chủ quan của thế giới khách quan, là tinh thần so với thế giới vật chất.","notes":""},{"id":304,"question":"Luận điểm nào sau đây là đúng?","options":["A. Nguyên nhân giống nhau tác động trong những điều kiện giống nhau cũng có thể đưa đến kết quả khác nhau","B. Nguyên nhân khác nhau tác động trong những điều kiện như nhau luôn đưa đến kết quả như nhau","C. Nguyên nhân tác động trong những điều kiện và hoàn cảnh càng ít khác nhau bao nhiêu thì kết quả do chúng gây ra càng giống nhau bấy nhiêu","D. Nguyên nhân giống nhau tác động trong những điều kiện khác nhau có thể đưa đến kết quả như nhau"],"answerLetter":"C","answerText":"C. Nguyên nhân tác động trong những điều kiện và hoàn cảnh càng ít khác nhau bao nhiêu thì kết quả do chúng gây ra càng giống nhau bấy nhiêu","notes":"(Kiểu hỏi khác: Theo quan điểm của Triết học Mác-Lênin, ý thức là hình ảnh chủ quan của yếu tố nào sau đây? A. Tinh thần tuyệt đối B. Thế giới khách quan C. Bộ óc con người D. Y niệm tuyệt đối)"},{"id":305,"question":"Chọn phương án phản ánh quan điểm của chủ nghĩa duy tâm","options":["A. Ý thức là thực thể độc lập, sáng tạo ra vật chất","B. Ý thức là sự phản ánh nguyên xi hiện thực khách quan vào bộ óc con người.","C. Ý thức là sự phản ánh năng động, sáng tạo hiện thực khách quan vào bộ óc con người","D. Ýthức là sự phản ánh thụ động hiện thực khách quan vào bộ óc con người."],"answerLetter":"A","answerText":"A. Ý thức là thực thể độc lập, sáng tạo ra vật chất","notes":""},{"id":306,"question":"Khẳng định nào sau đây là đúng?","options":["A. Có sự vật không vận động","B. Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","C. Mỗi sự vật cụ thể được đặc trưng bằng nhiều hình thức vận động","D. Có thể quy hình thức vận động cao về hình thức vận động thấp và ngược lại"],"answerLetter":"B","answerText":"B. Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","notes":""},{"id":307,"question":"Luận điểm nào không phải là câu trả lời của chủ nghĩa Mác-lênin về tính thống nhất vật chất của thế giới?","options":["A. Mọi bộ phận của thế giới vật chất đều liên hệ chuyển hóa lẫn nhau","B. Chỉ có một thế giới duy nhất là thế giới vật chất","C. Thế giới vật chất tồn tại vĩnh viễn, khách quan, vô hạn, vô tận, không do ai sinh ra và không mất đi","D. Thế giới vật chất bao gồm những bộ phận riêng biệt nhau"],"answerLetter":"D","answerText":"D. Thế giới vật chất bao gồm những bộ phận riêng biệt nhau","notes":""},{"id":308,"question":"\"Cái cối xay quay bằng tay đưa lại xã hội có lãnh chúa phong kiến, cái cối xay chạy bằng máy hơi nước đưa xã hội có nhà tư bản công nghiệp\". Thí dụ có hình ảnh trên nhằm nêu bật vai trò quyết định, xét đến cùng, trị sự phát triển là yếu tố nào?","options":["A. Đối tượng lao động","B. Lực lượng sản xuất","C. Tư liệu sản xuất","D. Công cụ lao động"],"answerLetter":"D","answerText":"D. Công cụ lao động","notes":""},{"id":309,"question":"Mỗi sự vật trong điều kiện xác định.","options":["A. Chỉ có một thuộc tính xác định","B. Có một số thuộc tỉnh xác định","C. Có vô văn thuộc tỉnh xác định","D. Có một hoặc một số thuộc tỉnh xác định"],"answerLetter":"D","answerText":"D. Có một hoặc một số thuộc tỉnh xác định","notes":""},{"id":310,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, ý kiến sau đây đúng hay sai? Vì sao?\"Điều kiện sinh hoạt vật chất của xã hội biến đổi đến đâu thì ngay lập tức tâm lý xã hội và hệ tư tưởng xã hội cũng lập tức biến đổi đến đó\"","options":["A. Đúng. Vì tồn tại xã hội nào thì ý thức xã hội đó","B. Đúng. Vì ý thức xã hội chỉ là sự phản ánh tồn tại xã hội","C. Sai. Vì ý thức xã hội phụ thuộc vào tồn tại xã hội nhưng nó có tính độc lập tương đối của nó","D. Sai. Vì thực tế lịch sử cho thấy không phải như vậy"],"answerLetter":"C","answerText":"C. Sai. Vì ý thức xã hội phụ thuộc vào tồn tại xã hội nhưng nó có tính độc lập tương đối của nó","notes":""},{"id":311,"question":"\"Phải giải thích ý thức xã hội bằng những mâu thuẫn, những sự xung đột hiện có giữa các lực lượng sản xuất những quan hệ sản xuất của xã hội\". Luận điểm này nhấn mạnh điểm nào trong quan niệm của chủ nghĩa di vật lịch sử?","options":["A. Vai trò chi phối của phương thức sản xuất đối với ý thức xã hội","B. Vai trò của cơ sở hạ tầng đối với kiến trúc thượng tầng","C. Vai trò quyết định của ý thức xã hội đối với tồn tại xã hội","D. Vai trò quyết định của tồn tại xã hội đối với ý thức xã hội"],"answerLetter":"D","answerText":"D. Vai trò quyết định của tồn tại xã hội đối với ý thức xã hội","notes":""},{"id":312,"question":"Triết học trở thành \"nữ tì\" của thần học khi nào?","options":["A. Khi quyền lực của Nhà thờ, kinh viện bao trùm mọi lĩnh vực đời sống xã hội","B. Khi quyền lực của Thánh chủ bao trùm mọi lĩnh vực đời sống xã hội","C. Khi quyền lực của Giáo hội bao trùm mọi lĩnh vực đời sống xã hội","D. Khi quyền lực của nhà vua kém quyền lực giáo phái"],"answerLetter":"C","answerText":"C. Khi quyền lực của Giáo hội bao trùm mọi lĩnh vực đời sống xã hội","notes":""},{"id":313,"question":"Theo quan niệm của chủ nghĩa duy vật lịch sử, yếu tố nào giữ vai trò đặc trưng cho chế độ kinh tế của một xã hội nhất định?","options":["A. Quan hệ sản xuất mới","B. Quan hệ sản xuất thống trị","C. Quan hệ sản xuất mạnh nhất","D. Quan hệ sản xuất đương thời"],"answerLetter":"B","answerText":"B. Quan hệ sản xuất thống trị","notes":""},{"id":314,"question":"Vận dụng Triết học vào thực tế phải dựa trên quan điểm:","options":["A. Lịch sử cụ thể","B. Phát triển","C. Kế thừa","D. Tất cả các đáp án đều đúng"],"answerLetter":"A","answerText":"A. Lịch sử cụ thể","notes":""},{"id":315,"question":"Từ định nghĩa con người của Ph.Ăngghen, đặc điểm nào sau đây cho thấy con người khác với động vật?","options":["A. Biết tư duy","B. Biết ứng xử theo các quy phạm đạo đức","C. Chính trị","D. Biết chế tạo và sử dụng công cụ lao động"],"answerLetter":"D","answerText":"D. Biết chế tạo và sử dụng công cụ lao động","notes":""},{"id":316,"question":"Triết học coi vật chất và tinh thần cùng quyết định nguồn gốc và sự tồn tại của thế giới như nhau gọi là","options":["A. Triết học duy vật","B. Triết học duy tâm","C. Triết học nhị nguyên"],"answerLetter":"C","answerText":"C. Triết học nhị nguyên","notes":""},{"id":317,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử thì","options":["A. Con người là chủ thể tùy ý sáng tạo ra lịch sử","B. Lịch sử sáng tạo ra con người, con người không thể sáng tạo ra lịch sử","C. Con người không thể sáng tạo ra lịch sử mà chỉ có thể thích ứng với những điều kiện có sẵn","D. Con người sáng tạo ra lịch sử trong phạm vi những điều kiện khách quan mà chính lịch sử trước đó đã tạo nên cho nó"],"answerLetter":"D","answerText":"D. Con người sáng tạo ra lịch sử trong phạm vi những điều kiện khách quan mà chính lịch sử trước đó đã tạo nên cho nó","notes":""},{"id":318,"question":"Vai trò của cách mạng xã hội đối với tiến hóa xã hội gì?","options":["A. Cách mạng xã hội làm gián đoạn quá trình tiến hóa xã hội","B. Cách mạng xã hội phủ định tiến hóa xã hội","C. Cách mạng xã hội không có quan hệ với tiến hóa xã hội","D. Cách mạng xã hội mở đường cho quá trình tiến hoá xã hội lên giai đoạn cao hơn."],"answerLetter":"D","answerText":"D. Cách mạng xã hội mở đường cho quá trình tiến hoá xã hội lên giai đoạn cao hơn.","notes":""},{"id":319,"question":"Khái niệm \"những nguyên lý cơ bản của chủ nghĩa Mác - Lênin\" là chỉ","options":["A. Những quan điểm cơ bản của chủ nghĩa Mác - Lênin","B. Những quan điểm cơ bản, nền tảng của chủ nghĩa Mác - Lênin","C. Những quan điểm mang tính chất chân lý bền vững của chủ nghĩa Mác - Lênin","D. Những quan điểm cơ bản, nền tảng và có tính chất chân lý bền vững của chủ nghĩa Mác - Lênin"],"answerLetter":"D","answerText":"D. Những quan điểm cơ bản, nền tảng và có tính chất chân lý bền vững của chủ nghĩa Mác - Lênin","notes":""},{"id":320,"question":"Về cấu trúc, người lao động thuộc mặt nào trong một phương thức sản xuất?","options":["A. Kinh tế - giai cấp","B. Lực lượng sản xuất","C. Tư liệu sản xuất","D. Kiến trúc thượng tầng"],"answerLetter":"B","answerText":"B. Lực lượng sản xuất","notes":""},{"id":321,"question":"Theo C. Mác, vấn đề tìm hiểu xem tư duy của con người có thể đạt được chân lý khách quan toàn không phải là vấn đề lý luận mà là vấn đề gì?","options":["A. Thực tế","B. Hiện thực","C. Thực tiễn","D. Khoa học"],"answerLetter":"C","answerText":"C. Thực tiễn","notes":""},{"id":322,"question":"Nguồn gốc kinh tế của sự vận động và phát triển của hình thái kinh tế- xã hội là gì?","options":["A. Mâu thuẫn giai cấp gay gắt trong xã hội có giai cấp","B. Sự tăng lên không ngừng của năng suất lao động","C. Mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất","D. Sự phát triển mạnh mẽ, đột phá của khoa học kỹ thuật công nghệ"],"answerLetter":"C","answerText":"C. Mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất","notes":""},{"id":323,"question":"Nguồn gốc trực tiếp của sự ra đời giai cấp trong xã hội?","options":["A. Do sự phát triển lực lượng sản xuất làm xuất hiện \"của dư\" tương đối","B. Do sự chênh lệch về khả năng giữa các tập đoàn người","C. Do sự phân hóa giữa giàu và nghèo trong xã hội","D. Do sự xuất hiện chế độ tư hữu về tư liệu sản xuất"],"answerLetter":"D","answerText":"D. Do sự xuất hiện chế độ tư hữu về tư liệu sản xuất","notes":""},{"id":324,"question":"Sai lầm của các nhà duy vật chất phác thời cổ đại là gì?","options":["A. Đồng nhất vật chất với vật thể","B. Đồng nhất vật thể với bản thân nó","C. Đồng nhất vật chất duy vật và thế giới duy tâm","D. Không có đáp án nào đúng"],"answerLetter":"A","answerText":"A. Đồng nhất vật chất với vật thể","notes":""},{"id":325,"question":"Ý thức xã hội là phạm trù triết học dùng để chỉ","options":["A. Toàn bộ đời sống tinh thần của xã hội","B. Toàn bộ điều kiện vật chất của xã hội","C. Toàn bộ điều kiện tinh thần của xã hội","D. Toàn bộ đời sống nói chung của xã hội"],"answerLetter":"A","answerText":"A. Toàn bộ đời sống tinh thần của xã hội","notes":""},{"id":326,"question":"Theo quan điểm của chủ nghĩa Mác - Lênin, \"Bộ tộc\" được định nghĩa là gì?","options":["A. Bộ tộc là hình thức cộng đồng người hình thành khi xã hội có sự phân chia thành giai cấp. Các bộ tộc được hình thành từ sự liên kết của nhiều bộ lạc sống trên một lãnh thổ nhất định","B. Những tộc người sống lưu vong","C. Nhiều bộ lạc hợp lại","D. Những người có chung lãnh thổ, ngôn ngữ, văn hóa, kinh tế"],"answerLetter":"A","answerText":"A. Bộ tộc là hình thức cộng đồng người hình thành khi xã hội có sự phân chia thành giai cấp. Các bộ tộc được hình thành từ sự liên kết của nhiều bộ lạc sống trên một lãnh thổ nhất định","notes":""},{"id":327,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhà nước là yếu tố cơ bản trong kiến trúc thượng tầng của xã hội, nó:","options":["A. Luôn luôn có tác động tích cực đối với cơ sở hạ tầng","B. Luôn luôn có tác động tiêu cực đối với cơ sở hạ tầng","C. Có thể tác động tích cực hoặc tiêu cực, tùy theo từng điều kiện nhất định","D. Không có tắc dụng gì tối cơ sở hạ tăng kinh tế mà chi có tác dụng tối các yêu tố khắc trong bản thân hệ thông kiên trức thượng tầng"],"answerLetter":"C","answerText":"C. Có thể tác động tích cực hoặc tiêu cực, tùy theo từng điều kiện nhất định","notes":""},{"id":328,"question":"Phạm trù triết học phản ánh thời kỳ hình thành đối tượng, khi nó mới chi tồn tại dưới dạng tiền đề hay với tư cách là xu hướng gọi là gì?","options":["A. Nguyên nhân","B. Kết quả","C. Khả năng","D. Hiện thực"],"answerLetter":"C","answerText":"C. Khả năng","notes":""},{"id":329,"question":"Đâu là một trong những tác phẩm của Lênin?","options":["A. Chủ nghĩa xã hội không tưởng Pháp","B. Chủ nghĩa Duy vật và chủ nghĩa kinh viện phê phán","C. Chủ nghĩa Duy vật và chủ nghĩa kinh nghiệm phê phán","D. Đường Kách Mệnh"],"answerLetter":"C","answerText":"C. Chủ nghĩa Duy vật và chủ nghĩa kinh nghiệm phê phán","notes":""},{"id":330,"question":"Theo triết học Mác, con người là gì?","options":["A. Thực thể sinh học - xã hội","B. Thực thể tự nhiên - sinh học","C. Kết hợp con vật và con người","D. Là thực thể do thánh thần tạo ra"],"answerLetter":"A","answerText":"A. Thực thể sinh học - xã hội","notes":""},{"id":331,"question":"Khi xem xét, đánh giá con người trong mối quan hệ với gia đình, bạn bè, đồng nghiệp và các mối quan hệ xã hội được gọi là cách nhìn nhận gì?","options":["A. Biện chứng","B. Toàn diện","C. Lịch sử, cụ thể","D. Phiến diện"],"answerLetter":"B","answerText":"B. Toàn diện","notes":""},{"id":332,"question":"Yếu tố nào không thuộc lực lượng sản xuất?","options":["A. Người lao động","B. Nhà xưởng, công trường","C. Đối tượng lao động","D. Kinh tế thượng tầng"],"answerLetter":"D","answerText":"D. Kinh tế thượng tầng","notes":""},{"id":333,"question":"Giải quyết mặt thứ nhất trong trong vấn đề cơ bản của triết học đã chia nó thành hai trường phái triết học lớn trong lịch sử, đó là các chủ nghĩa","options":["A. Duy vật và duy tâm","B. Duy vật và siêu hình","C. Duy vật biện chủng và duy tâm","D. Duy vật máy móc và duy tâm"],"answerLetter":"A","answerText":"A. Duy vật và duy tâm","notes":""},{"id":334,"question":"Nguồn gốc xã hội dẫn đến sự ra đời của Triết học là?","options":["A. Do sự phát triển của lực lượng sản xuất","B. Cách mạng nổ ra, những tộc người tan rã","C. Lao động trí óc đã tách khỏi lao động chân tay","D. Phân tích đúng tình hình trên toàn thế giới, sản xuất phát triển"],"answerLetter":"C","answerText":"C. Lao động trí óc đã tách khỏi lao động chân tay","notes":""},{"id":335,"question":"Theo quan điểm của chủ nghĩa Mác - Lênin, \"Bộ lạc\" được định nghĩa là gì?","options":["A. Là cộng đồng bao gồm những bộ lạc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau","B. Là cộng đồng bao gồm những thị tộc có quan hệ hôn nhân liên kết với nhau","C. Là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau","D. Là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống"],"answerLetter":"C","answerText":"C. Là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau","notes":""},{"id":336,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng, sự vật khi mới ra đời chúng tồn tại dưới dạng.","options":["A. Cái đơn nhất","B. Cái cụ thể","C. Cái chung"],"answerLetter":"A","answerText":"A. Cái đơn nhất","notes":""},{"id":337,"question":"Hoạt động sản xuất vật chất cơ sở hình thành nên quan hệ gì?","options":["A. Quan hệ kinh tế giữa người với người","B. Quan hệ vật chất giữa người với người","C. Quan hệ kinh tế - vật chất giữa người với vật","D. Quan hệ kinh tế - vật chất giữa người với người"],"answerLetter":"D","answerText":"D. Quan hệ kinh tế - vật chất giữa người với người","notes":""},{"id":338,"question":"Đâu là một trong những hình thức cộng đồng người trước khi hình thành dân tộc?","options":["A. Thị tộc","B. Chủng tộc","C. Sắc tộc","D. Dân tộc"],"answerLetter":"A","answerText":"A. Thị tộc","notes":"(Kiểu hỏi khác: Đâu là cơ sở hình thành nên quan hệ kinh tế - vật chất giữa người với người? A. Hoạt động thực nghiệm khoa học B. Hoạt động chính trị, xã hôi C. Hoạt động thực nghiệm khoa học D. Hoạt động sản xuất vật chất)"},{"id":339,"question":"Khi một sự vật, một hiện tượng mới được nảy sinh thì yếu tố nào sẽ xuất hiện đầu tiên?","options":["A. Cái chung","B. Cái riêng","C. Cái đơn nhất","D. Cái phổ biến"],"answerLetter":"C","answerText":"C. Cái đơn nhất","notes":""},{"id":340,"question":"Một trong ba hình thức cơ bản của chủ nghĩa duy vật là gì?","options":["A. Chủ nghĩa duy vật chất phác thời cổ đại","B. Chủ nghĩa duy vật trung đại","C. Chủ nghĩa duy vật Mác thời cận đại","D. Chủ nghĩa Sôphanh thời hiện đại"],"answerLetter":"A","answerText":"A. Chủ nghĩa duy vật chất phác thời cổ đại","notes":""},{"id":341,"question":"Khẳng định nào sau đây về thế giới vật chất là đúng?","options":["A. Chỉ có một thế giới duy nhất là thế giới vật chất","B. Chỉ có một thế giới duy nhất là thế giới tinh thần","C. Có nhiều thế giới vật chất","D. Có nhiều thế giới tinh thần"],"answerLetter":"A","answerText":"A. Chỉ có một thế giới duy nhất là thế giới vật chất","notes":""},{"id":342,"question":"Cái ...là cái toàn bộ, phong phú hơn cái...","options":["A. Chung/Riêng.","B. Riêng/Chung.","C. Chung/Đơn nhất.","D. Đơn nhất/Riêng."],"answerLetter":"B","answerText":"B. Riêng/Chung.","notes":""},{"id":343,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","options":["A. Có tất nhiên thuần tuý tồn tại khách quan","B. Có ngẫu nhiên thuần tuý tồn tại khách quan","C. Không có cái tất nhiên và ngẫu nhiên thuần tuý tồn tại bên ngoài nhau","D. Tất nhiên và ngẫu nhiên cùng tồn tại song song với nhau trong tư duy"],"answerLetter":"C","answerText":"C. Không có cái tất nhiên và ngẫu nhiên thuần tuý tồn tại bên ngoài nhau","notes":""},{"id":344,"question":"Điền vào chỗ trống: Chủ nghĩa duy vật biện chứng đã định nghĩa nhận thức là một quá trình phản ánh ... thế giới khách quan vào bộ óc của con người. (Chọn 3 đáp án)","options":["A. Tự giác","B. Tích cực","C. Sáng tạo","D. Chủ quan"],"answerLetter":"ABC","answerText":"A. Tự giác\nB. Tích cực\nC. Sáng tạo","notes":"(Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng? A. Nguyên nhân là cái sản sinh ra kết quả B. Mọi sự kế tiếp nhau về mặt thời gian đều là quan hệ nhân quả C. Nguyên nhân tác động đến kết quả D. Cái xuất hiện trước luôn là nguyên nhân của cái xuất hiện sau)"},{"id":345,"question":"Toàn bộ những quan hệ sản xuất của một xã hội trong sự vận động hiện thực của chúng hợp thành cơ cấu kinh tế của xã hội đó được là gì?","options":["A. Cơ sở hạ tầng","B. Cơ sở thượng tầng","C. Quan hệ sản xuất","D. Quan hệ phân phối"],"answerLetter":"A","answerText":"A. Cơ sở hạ tầng","notes":""},{"id":346,"question":"Trong hoạt động thực tiễn, sai lầm của sự trì trệ bảo thủ là do không tôn trọng quy luật nào?","options":["A. Quy luật mâu thuẫn","B. Quy luật lượng chất","C. Quy luật tự nhiên","D. Quy luật xã hội"],"answerLetter":"B","answerText":"B. Quy luật lượng chất","notes":""},{"id":347,"question":"Bản thân cây Sầu riêng luôn tồn tại hai quá trình quang hợp và hô hấp. Quá trình quang hợp giúp cây Sầu riêng hấp thụ nước và khí Cacbonic cùng với ánh sáng mặt trời để tạo ra các hợp chất hữu cơ và thải ra Oxi. Còn quá trình hô hấp là quá trình hấp thụ Oxi, chuyển đổi các chất hữu cơ, và giải phóng năng lượng, thải ra khí Cacbonic. Với kiến thức về Triết học đã được học, Anh/Chị hãy cho biết quá trình quang hợp và hô hấp của cây Sâu riêng nằm trong quy luật nào trong các quy luật sau đây ?","options":["A. Quy luật từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","B. Quy luật thống nhất và đấu tranh giữa các mặt đối lập","C. Quy luật phủ định của phủ định","D. Quy luật phát triển"],"answerLetter":"B","answerText":"B. Quy luật thống nhất và đấu tranh giữa các mặt đối lập","notes":""},{"id":348,"question":"Cách mạng xã hội được khái quát bởi","options":["A. Thay đổi thể chế chính trị xã hội này bằng thể chế chính trị khác","B. Thay đổi thể chế kinh tế này bằng một thể chế kinh tế khác cao hơn","C. Thay đổi căn bản, toàn diện và triệt để một hình thái kinh tế - xã hội này bằng một hình thái kinh tế - xã hội khác cao hơn","D. Thay đổi hệ tư tưởng quản lý này bằng hệ tư tưởng quản lý khác"],"answerLetter":"C","answerText":"C. Thay đổi căn bản, toàn diện và triệt để một hình thái kinh tế - xã hội này bằng một hình thái kinh tế - xã hội khác cao hơn","notes":"(Kiểu hỏi khác: Đâu là một khái quát của cách mạng xã hội?)"},{"id":349,"question":"Định nghĩa đúng triết học Mác - Lênin là","options":["A. Hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy","B. Khoa học làm cầu nối giữa các khoa học","C. Chính trị","D. Một thứ tôn giáo"],"answerLetter":"A","answerText":"A. Hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy","notes":""},{"id":350,"question":"Theo Triết học Mác, vật chất tồn tại thế nào?","options":["A. Chủ quan","B. Phụ thuộc và con người","C. Khách quan","D. Theo ý muốn của thần linh"],"answerLetter":"C","answerText":"C. Khách quan","notes":""},{"id":351,"question":"Theo Triết học Mác - Lênin cái bàn, cái ghế có phải vật chất không?","options":["A. Có. Vì nó là dạng của vật chất trong không gian.","B. Không. Vì nó không có vật chất trong không gian.","C. Có. Vì nó có tồn tại cụ thể, có kích thước và tồn tại cùng thời gian.","D. Không. Vì nó chỉ là một dạng cụ thể của vật chất."],"answerLetter":"A","answerText":"A. Có. Vì nó là dạng của vật chất trong không gian.","notes":""},{"id":352,"question":"Những sự vật, hiện tượng nếu có cùng nguyên nhân, trong những điều kiện giống nhau thì sẽ tạo nên kết quả như nhau. Điều này thể hiện tính chất gì trong mối liên hệ nhân quả?","options":["A. Tỉnh khách quan","B. Tính phổ biến","C. Tính tất yếu","D. Tính biện chứng"],"answerLetter":"C","answerText":"C. Tính tất yếu","notes":"(Kiểu hỏi khác: Cái bàn, cái ghế có phải là vật chất với tư cách là một phạm trù triết học hay không?)"},{"id":353,"question":"Ai đã tìm ra tia phóng xạ?","options":["A. Ronghen","B. Nicolai copazir","C. Béccoren","D. Jorb Bruno"],"answerLetter":"C","answerText":"C. Béccoren","notes":""},{"id":354,"question":"Chọn cụm từ thích hợp điền vào chỗ trống sau để hình thành khái niệm về \"Cơ sở hạ tầng\" theo quan điểm của triết học Mác - Lênin: Cơ sở hạ tầng là tổng hợp các quan hệ sản xuất hợp thành..... của xã hội.","options":["A. Cơ sở vật chất - kỹ thuật","B. Hệ thống điện, đường, trường, trạm","C. Cơ cấu kinh tế","D. Đời sống vật chất"],"answerLetter":"C","answerText":"C. Cơ cấu kinh tế","notes":""},{"id":355,"question":"Triết học duy vật biện chứng cho rằng:","options":["A. Vật chất quyết định ý thức, ý thức tác động trở lại vật chất","B. Ý thức quyết định vật chất, vật chất tác động trở lại ý thức","C. Vật chất quyết định ý thức, ý thức không thể tác động đến vật chất","D. Vật chất và ý thức đều có vai trò quyết định"],"answerLetter":"A","answerText":"A. Vật chất quyết định ý thức, ý thức tác động trở lại vật chất","notes":""},{"id":356,"question":"Anh A có tri thức, năng lực, trình độ, kinh nghiệm và kỹ năng lao động. Vậy có thể gọi A là?","options":["A. Trí thức","B. Người lao động","C. Lao động trí thức","D. Năng lực lao động"],"answerLetter":"C","answerText":"C. Lao động trí thức","notes":"(Kiểu hỏi khác: Đâu là một quan điểm của chủ nghĩa duy vật biện chứng?)"},{"id":357,"question":"Sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng tạo thành :","options":["A. hình thái kinh tế - xã hội","B. phương thức sản xuất","C. cơ sở hạ tầng","D. kiến trúc thượng tầng"],"answerLetter":"B","answerText":"B. phương thức sản xuất","notes":""},{"id":358,"question":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Lực lượng cơ bản nhất trong quần chúng nhân dân là:","options":["A. Giai cấp thống trị xã hội.","B. Tầng lớp trí thức.","C. Người lao động.","D. Công nhân và nông dân."],"answerLetter":"C","answerText":"C. Người lao động.","notes":""},{"id":359,"question":"Chỉ có một thế giới duy nhất là thế giới vật chất là thể hiện tính chất gì của thế giới vật chất?","options":["A. Đồng nhất","B. Thống nhất","C. Thuần nhất","D. Duy nhất"],"answerLetter":"B","answerText":"B. Thống nhất","notes":"(Cách hỏi khác: Theo quan điểm chủ nghĩa duy vật lịch sử, lực lượng cơ bản nhất trong quần chúng nhân dân là gì?)"},{"id":360,"question":"Theo C. Mác và Ph. Ăngghen, để tồn tại và phát triển, con người cần phải thực hiện hoạt động gì?","options":["A. Vận động","B. Sản xuất","C. Làm giàu","D. Kinh doanh"],"answerLetter":"B","answerText":"B. Sản xuất","notes":""},{"id":361,"question":"Các nhà triết học duy tâm được chia thành mấy trường phái?","options":["A. 2","B. 3","C. 4","D. 5"],"answerLetter":"A","answerText":"A. 2","notes":""},{"id":362,"question":"Cơ sở của sự tồn tại và phát triển của xã hội là sản xuất:","options":["A. Hàng hóa, dịch vụ","B. Tư liệu sản xuất","C. Tư liệu tiêu dùng","D. Sản xuất vật chất"],"answerLetter":"D","answerText":"D. Sản xuất vật chất","notes":""},{"id":363,"question":"Trong xã hội có giai cấp, nội dung và hình thức phát triển của ý thức xã hội khác nhau do dâu?","options":["A. Những điều kiện sinh hoạt vật chất, lợi ích và địa vị của các giai cấp khác nhau","B. Thôi quen khác nhau","C. Sở thích khác nhau","D. Những điều kiện sinh hoạt tinh thần, địa vị, thói quen của các giai cấp khác nhau"],"answerLetter":"A","answerText":"A. Những điều kiện sinh hoạt vật chất, lợi ích và địa vị của các giai cấp khác nhau","notes":""},{"id":364,"question":"Vấn đề cơ bản của triết học có hai mặt. Mặt thứ hai phải trà lời câu hỏi con người có khả năng hay không trong:","options":["A. Nhận thức được bản thân","B. Hòa hợp với tự nhiên","C. Chinh phục được thế giới","D. Nhận thức được thế giới"],"answerLetter":"D","answerText":"D. Nhận thức được thế giới","notes":""},{"id":365,"question":"Theo C.Mắc, các nên kinh tế căn bản phân biệt với nhau bởi:","options":["A. Phương thức sản xuất ra của cải vật chất","B. Mục đích của quá trình sản xuất ra của cài vật chất","C. Mục đích tự nhiên của quá trình sản xuất ra của cải vật chất","D. Mục đích xã hội của quá trình sản xuất ra của cải vật chất"],"answerLetter":"A","answerText":"A. Phương thức sản xuất ra của cải vật chất","notes":""},{"id":366,"question":"Luận điểm sau đây thuộc lập trường triết học nào: \"Cái mới ra đời trên cơ sở phá hủy hoàn toàn cái cũ\"?","options":["A. Quan điểm siêu hình","B. Quan điểm duy tâm","C. Quan đểm phát triển","D. Quan điểm biện chứng duy vật"],"answerLetter":"A","answerText":"A. Quan điểm siêu hình","notes":""},{"id":367,"question":"Những ý thức lạc hậu tiêu cực không mất đi một cách dễ dàng, là do:","options":["A. Thói quen tập quán lâu đời","B. Ý thức xã hội không phản ánh kịp tôi tại xã hội","C. Thói quen tập quán lâu đời và ý thức xã hội không phần ánh kịp tồi tại xã hội","D. Ý thức xã hội phản ánh tồi tại xã hội và thói quen tập quán"],"answerLetter":"C","answerText":"C. Thói quen tập quán lâu đời và ý thức xã hội không phần ánh kịp tồi tại xã hội","notes":""},{"id":368,"question":"Thời gian phát hiện ra tia Rơnghen là khi nào?","options":["A. Năm 1895","B. Năm 1896","C. Năm 1897","D. Năm 1898"],"answerLetter":"A","answerText":"A. Năm 1895","notes":""},{"id":369,"question":"Trong xã hội Ấn Độ cổ đại, triết học được hiểu là:","options":["A. Con đường suy ngẫm để dẫn dắt con người tới lẽ phải","B. Con đường tu tập","C. Con đường giài thoát","D. Con đường giác ngộ"],"answerLetter":"A","answerText":"A. Con đường suy ngẫm để dẫn dắt con người tới lẽ phải","notes":""},{"id":370,"question":"Theo triết học Mác, hình thái kinh tế - xã hội cuối cùng là?","options":["A. Phong kiến","B. Tư bản chủ nghĩa","C. Xã hội chủ nghĩa","D. Cộng sản chủ nghĩa"],"answerLetter":"D","answerText":"D. Cộng sản chủ nghĩa","notes":""},{"id":371,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, trong kiến trúc thượng tầng của xã hội có giai cấp, yếu tố cơ bản nhất, có tác động trực tiếp và mạnh mẽ nhất tối cơ sở hạ tầng là yếu tố:","options":["A. Tổ chức chính đảng","B. Tổ chức nhà nước","C. Tổ chức tôn giáo","D. Các tổ chức văn hóa - xã hội"],"answerLetter":"B","answerText":"B. Tổ chức nhà nước","notes":""},{"id":372,"question":"Theo quan điểm của chủ nghĩa duy vật biện chứng khẳng định nào sau đây là đúng?","options":["A. Cái ngẫu nhiên không có nguyên nhân","B. Chi có cái tất yếu mi có nguyên nhân","C. Không phải cái gì con người chưa nhận thức được nguyên nhân là cái ngẫu nhiên","D. Cái ngẫu nhiên luôn trở thành cái tất nhiên"],"answerLetter":"C","answerText":"C. Không phải cái gì con người chưa nhận thức được nguyên nhân là cái ngẫu nhiên","notes":""},{"id":373,"question":"\"Góp gió thành bão\" giúp anh/chị liên hệ tới quy luật nào trong triết học?","options":["A. Lượng - chất","B. Mâu thuẫn","C. Phủ định của phú định","D. Không có phương án nào đúng"],"answerLetter":"A","answerText":"A. Lượng - chất","notes":""},{"id":374,"question":"Theo quan điểm của triết học Mác - Lênin thì sự thay đổi quan hệ sản xuất phụ thuộc vào:","options":["A. Trình độ của công cụ sản xuất","B. Trình độ kỹ thuật sản xuất","C. Trình độ phân công lao động xã hội","D. Trình độ phát triển của lực lượng sản xuất"],"answerLetter":"D","answerText":"D. Trình độ phát triển của lực lượng sản xuất","notes":""},{"id":375,"question":"Bản chất của nhà nước là gì?","options":["A. Mang bản chất của giai cấp thống trị","B. Mang bản chất của giai cấp bị trị","C. Mang bản chất của tất cà các giai cấp","D. Mang bản chất của xã hội"],"answerLetter":"A","answerText":"A. Mang bản chất của giai cấp thống trị","notes":""},{"id":376,"question":"Khi sự vật không trực tiếp tác động vào giác quan của con người, là hình thức nhận thức nào sau đây?","options":["A. Cảm giác","B. Tri giác","C. Biểu tượng","D. Khái niệm"],"answerLetter":"D","answerText":"D. Khái niệm","notes":""},{"id":377,"question":"Galilê là nhà triết học thuộc trường phái triết học nào?","options":["A. Chủ nghĩa duy vật biện chứng","B. Chủ nghĩa duy vật siêu hình","C. Chủ nghĩa duy tâm siêu hình","D. Chủ nghĩa duy tâm máy móc"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy vật siêu hình","notes":"(Kiểu hỏi khác: Hình thức nhận thức nào sau đây không cần có sự tác động của vật vào cơ quan giác quan của con người? A. Cảm giác B. Tri giác C. Biểu tượng D. Khái niệm)"},{"id":378,"question":"Xác định mệnh đề sai:","options":["A. Vật thể là dạng cụ thế của vật chất","B. Vật chất tồn tại thông qua những dạng cụ thế của nó","C. Vật chất là một dạng tồn tại của vật thể","D. Vật thế không đồng nghĩa với vật chất"],"answerLetter":"C","answerText":"C. Vật chất là một dạng tồn tại của vật thể","notes":""},{"id":379,"question":"Theo C. Mác, trong tính hiện thực của nó, bản chất con người là tổng hò","options":["A. A. Các phẩm chất xã hội","B. Quan hệ lợi ích","C. Các quan hệ xã hội","D. Quan hệ hiện thực"],"answerLetter":"C","answerText":"C. Các quan hệ xã hội","notes":""},{"id":380,"question":"Ý thức xã hội có tính chất nào sau đây?","options":["A. Tính độc lập tương đối","B. Tính độc lập tuyệt đối","C. Tính sáng tạo","D. Tính bất biến"],"answerLetter":"A","answerText":"A. Tính độc lập tương đối","notes":""},{"id":381,"question":"Ở Trung Quốc thời cổ đại có Triết học không?","options":["A. Có","B. Không","C. Chi có hệ tư tưởng chứ không có triết học","D. Không có hệ tư tưởng và triết học"],"answerLetter":"A","answerText":"A. Có","notes":"(Kiểu hỏi khác: -Tính chất kế thừa của ý thức xã hội làm cho nó có tính chất nào sau đây? -Trong mỗi quan hệ với tồn tại xã hội, ý thức xã hội có tính chất nào sau đây?)"},{"id":382,"question":"Mối quan hệ giữa lĩnh vực kinh tế và lĩnh vực chính trị của xã hội được khái quát trong quy luật nào?","options":["A. Quy luật về mỗi quan hệ biện chững giữa cơ sở hạ tầng và kiến trúc thượng tầng","B. Quy luật đấu tranh giai cấp","C. Quy luật tôn tại xã hội quyết định ý thức xã hội","D. Tất cả đều sai"],"answerLetter":"A","answerText":"A. Quy luật về mỗi quan hệ biện chững giữa cơ sở hạ tầng và kiến trúc thượng tầng","notes":""},{"id":383,"question":"Lơxíp và Đêmôcrít có điểm chung là gì?","options":["A. Cà hai ông đều cho rằng, vật chất là nước","B. Cả hai ông đều cho rằng, vật chất là lữa","C. Cả hai ông đều cho răng, vật chất là không khí","D. Cá hai ông đều cho rằng, vật chất là nguyên tử"],"answerLetter":"D","answerText":"D. Cá hai ông đều cho rằng, vật chất là nguyên tử","notes":"(Kiểu hỏi khác: Đâu được coi là quy luật cơ bản nhất quy định sự vận động và phát triển của xã hội?)"},{"id":384,"question":"Hiện tượng là:","options":["A. Một bộ phận của bản chất","B. Luôn đông nhất với bản chất","C. Biểu hiện bên ngoài của bản chất","D. Kết quà của bản chất"],"answerLetter":"C","answerText":"C. Biểu hiện bên ngoài của bản chất","notes":""},{"id":385,"question":"Về cơ bản, nhà nước có mấy chức năng?","options":["A. 2","B. 3","C. 4","D. 5"],"answerLetter":"A","answerText":"A. 2","notes":""},{"id":386,"question":"Thời đại kinh tế ngày nay được gọi là gì?","options":["A. Nền kinh tế 4.0","B. Nền kinh tế tri thức","C. Nền kinh tế thị trường","D. Nền kinh tế hàng hóa nhiều thành phần"],"answerLetter":"B","answerText":"B. Nền kinh tế tri thức","notes":""},{"id":387,"question":"Trước khi chủ nghĩa duy vật biện chững ra đời, nhìn chung các nhà triết học duy vật quan niệm vật chất là gì?","options":["A. Một hay một số chất tự có, đầu tiên","B. Toàn bộ vật chất","C. Vũ trụ quan","D. Giới tự nhiên","E. Ý thức"],"answerLetter":"A","answerText":"A. Một hay một số chất tự có, đầu tiên","notes":""},{"id":388,"question":"\"Cái đơn nhất\" là phạm trù triết học dùng để chỉ:","options":["A. Thuộc tính tồn tại duy nhất ở một sự vật","B. Thuộc tính tồn tại trong nhiều sự vật hiện tượng","C. Những sự vật hiện tượng khách quan"],"answerLetter":"A","answerText":"A. Thuộc tính tồn tại duy nhất ở một sự vật","notes":""},{"id":389,"question":"Khi đánh giá một con người, quan điểm toàn diện đòi hỏi điều gì?","options":["A. Phải đặc biệt nhãn mạnh một mặt nào đó, bỏ qua những mặt còn lại","B. Phải đặt họ vào những điều kiện, thời đại của minh mà đánh giá","C. Phải đặt họ trong những mỗi quan hệ với những người khác, với những việc khác có thế ảnh hưởng đến sự phát triển của họ mà đánh giá","D. Phải xuất phát từ mục đích và lợi ích của họ mà đánh giá"],"answerLetter":"C","answerText":"C. Phải đặt họ trong những mỗi quan hệ với những người khác, với những việc khác có thế ảnh hưởng đến sự phát triển của họ mà đánh giá","notes":""},{"id":390,"question":"Trong các yếu tố cầu thành cơ sở hạ tầng của xã hội, yếu tố nào đóng vai trò quyết định?","options":["A. Quan hệ sản xuất tàn dư của xã hội cũ","B. Quan hệ sản xuất mầm mỗng của xã hội tương lai","C. Quan hệ sản xuất thống trị","D. Quan hệ sản xuất chủ đạo"],"answerLetter":"C","answerText":"C. Quan hệ sản xuất thống trị","notes":""},{"id":391,"question":"Theo quan điểm của triết học Mác - Lênin, thuộc tính phản ánh là thuộc tính:","options":["A. Riêng có ở con người","B. Chi có ở các cơ thế sống","C. Chi có ở các chất vô cơ","D. Phố biến ở mọi tố chức vật chất"],"answerLetter":"D","answerText":"D. Phố biến ở mọi tố chức vật chất","notes":""},{"id":392,"question":"Định nghĩa vật chất của Lênin bao gồm mấy nội dung cơ bản?","options":["A. 2","B. 3","C. 4","D. 5"],"answerLetter":"B","answerText":"B. 3","notes":""},{"id":393,"question":"Hiện tượng, quá trình khác nhau đều có những mỗi liên hệ cụ thể khác nhau, là biểu hiện của tính chất nào trong mỗi liên hệ?","options":["A. Đa dạng, phong phú","B. Khách quan","C. Phố biến","D. Chung nhất"],"answerLetter":"A","answerText":"A. Đa dạng, phong phú","notes":""},{"id":394,"question":"Hiện thực là phạm trù triết học dùng để chỉ những gì:","options":["A. Sẽ tồn tại khi có đủ điều kiện","B. Đang tồn tại trong thực tế","C. Sẽ xuất hiện khi hội đủ mọi điều kiện"],"answerLetter":"B","answerText":"B. Đang tồn tại trong thực tế","notes":""},{"id":395,"question":"Toàn bộ những chính sách, quan điểm, tư tường, đường lối chỉ đạo của nhà nước được gọi là gì?","options":["A. Cơ sở hạ tầng","B. Cơ sở thượng tầng","C. Quan hệ sản xuất","D. Kiến trúc thượng tầng"],"answerLetter":"D","answerText":"D. Kiến trúc thượng tầng","notes":""},{"id":396,"question":"Đâu là hình thức thế giới quan tôn tại trước thế giới quan triết học?","options":["A. Thế giới quan tiền tệ","B. Thế giới quan tôn giáo","C. Thế giới quan nhân sinh","D. Thế giới quan pháp luật"],"answerLetter":"B","answerText":"B. Thế giới quan tôn giáo","notes":""},{"id":397,"question":"Trong tư liệu sản xuất thì cái gì phản ánh rõ nhất trình độ phát triển của lực lượng sản xuất?","options":["A. Công cụ lao động","B. Máy móc","C. Đối tượng lao động","D. Công cụ tin học"],"answerLetter":"A","answerText":"A. Công cụ lao động","notes":""},{"id":398,"question":"Đâu là tác phẩm của Ph. Ángghen?","options":["A. \"Biện chứng của thiên nhiên\"","B. \"Biện chứng của tự nhiên\"","C. \"Biện chứng của tự do\"","D. \"Tự nhiên của biện chúng\""],"answerLetter":"B","answerText":"B. \"Biện chứng của tự nhiên\"","notes":""},{"id":399,"question":"Vị trí, vai trò của Triết học Mác - Lênin trong đời sống xã hội và trong sự nghiệp đối mới ở Việt Nam hiện nay? (073-356-8678)","options":["A. Thúc đấy","B. Đối lập","C. Mâu thuẫn","D. Quan trọng, là nên tảng tư tưởng, kim chỉ nam cho hành động"],"answerLetter":"D","answerText":"D. Quan trọng, là nên tảng tư tưởng, kim chỉ nam cho hành động","notes":""},{"id":400,"question":"Theo triết học Mác, sự chuyển dịch từ hình thái kinh tế chiếm hữu nô lệ, sang phong kiến rồi đến xã hội chủ nghĩa thuộc loại vận động nào?","options":["A. Vận động vật lý","B. Vận động hóa học","C. Vận động sinh học","D. Vận động xã hội"],"answerLetter":"D","answerText":"D. Vận động xã hội","notes":""},{"id":401,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, lực lượng chủ thể sáng tạo ra lịch sử là:","options":["A. Quần chúng nhân dân","B. Vĩ nhân, lãnh tụ","C. Tầng lớp trí thức","D. Trí thức, vĩ nhân"],"answerLetter":"A","answerText":"A. Quần chúng nhân dân","notes":""},{"id":402,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhà nước là gì?","options":["A. Tổ chức phi chính phủ","B. Tổ chúc quyền lực phi giai cấp","C. Tổ chức quyền lực mang bản chất của giai cấp sở hữu tư liệu sản xuất chủ yếu của xã hội","D. Tổ chức quyền lực mang bàn chất của mọi giai cấp trong xã hội"],"answerLetter":"C","answerText":"C. Tổ chức quyền lực mang bản chất của giai cấp sở hữu tư liệu sản xuất chủ yếu của xã hội","notes":""},{"id":403,"question":"Theo quan niệm duy vật biện chứng về lịch sử thì những quan hệ sản xuất cũ được thay thế bằng quan hệ sản xuất mới, phù hợp trình độ phát triển của lực lượng sản xuất đã phát triển nhờ điều gì?","options":["A. Cải cách triệt để","B. Cách mạng vô sản","C. Cách mạng xã hội","D. Đảo chính"],"answerLetter":"C","answerText":"C. Cách mạng xã hội","notes":""},{"id":404,"question":"Triết học do C.Mác và Ph.Ang-ghen thực hiện là bước ngoặt cách mạng trong sự phát triển của triết học. Biểu hiện vĩ đại nhất của bước ngoặt cách mạng đó là:","options":["A. Thay đổi căn bản tính chất của triết học, thay đổi căn bản đối tượng của nó và mỗi quan hệ đối với các khoa học khác","B. Gắn bó chặt chẽ giữa triết học với phong trào cách mạng của giai cấp vô sản và quần chúng lao động","C. Sáng tạo ra chủ nghĩa duy vật lịch sử làm thay đổi quan niệm của con người về xã hội","D. Làm cho triết học trở nên phổ biến trong cuộc sống"],"answerLetter":"C","answerText":"C. Sáng tạo ra chủ nghĩa duy vật lịch sử làm thay đổi quan niệm của con người về xã hội","notes":""},{"id":405,"question":"Các hình thức cơ bản của chủ nghĩa duy tâm:","options":["A. Duy tâm chủ quan và duy tâm khách quan","B. Duy tâm biện chứng và duy tâm siêu hình","C. Duy tâm trung cổ cận đại và duy tâm cổ điển Đức","D. Duy tâm khách quan và duy tâm cổ đại"],"answerLetter":"A","answerText":"A. Duy tâm chủ quan và duy tâm khách quan","notes":""},{"id":406,"question":"Sự sinh ra, lớn lên, già đi thuộc hình thức vận động nào trong triết học?","options":["A. Vận động cơ học","B. Vận động sinh học","C. Vận động vật lý","D. Vận động hóa học"],"answerLetter":"B","answerText":"B. Vận động sinh học","notes":""},{"id":407,"question":"Cấu trúc của phương thức sản xuất gồm những yếu tố nào sau đây?","options":["A. Công cụ lao động, đối tượng lao động","B. Trình độ lao động, quan hệ sản xuất","C. Lực lượng sản xuất, quan hệ sản xuất","D. Tư liệu sàn xuất và con người"],"answerLetter":"C","answerText":"C. Lực lượng sản xuất, quan hệ sản xuất","notes":""},{"id":408,"question":"Chỉ tính quy định, mỗi liên hệ thống nhất giữa chất và lượng, là khoảng giới hạn mà trong đó sự thay đổi về lượng của sự vật chưa làm thay đổi căn bản chất của nó gọi là:","options":["A. Độ","B. Giối hạn","C. Điểm nút","D. Tích vẽ lượng"],"answerLetter":"A","answerText":"A. Độ","notes":""},{"id":409,"question":"Các hình thức tồn tại của các dạng cụ thế của vật chất ở một vị trí nhất định, có một quảng tinh nhất định và tồn tại trong mối tương quan nhất định với các dạng cụ thế khác của vật chất được goi là","options":["A. Tồn tại của vật chất","B. Thời gian","C. Không gian","D. Sư tồn tại"],"answerLetter":"C","answerText":"C. Không gian","notes":"(Kiểu hỏi khác: Khái niệm nào dùng để chi khoảng giới hạn trong đó sự thay đổi về lượng chưa dẫn đến sự thay đổi căn bản chất của sự vật ấy? A. Chất B. Lượng C. Độ D. Điểm nút)"},{"id":410,"question":"Chủ nghĩa duy tâm có nguồn gốc nhận thức và nguồn gốc xã hội là trong quá trình nhân thức nó xem xét phiến diện, tuyệt đổi hóá, thần thánh hóa cái gì của quá trình nhận thức?","options":["A. Một đối tượng","B. Những đặc tính nào đó","C. Một số mặt nào đó","D. Một mặt, một đặc tính nào đó"],"answerLetter":"D","answerText":"D. Một mặt, một đặc tính nào đó","notes":""},{"id":411,"question":"Giả sứ khái niệm Việt Nam là một \"cái riêng\" thì yếu tố nảo sau đây là cái đơn nhất?","options":["A. Con người","B. Quốc gia","C. Văn hóa","D. Hà Nội"],"answerLetter":"D","answerText":"D. Hà Nội","notes":""},{"id":412,"question":"Nhận thức lý tính được thực hiện dưới hình thức nào?","options":["A. Cảm giác, tri giác và phán đoán","B. Khái niệm, phán đoán và suy lý","C. Cảm giác, khái niệm, suy lý","D. Cảm giác, tri giác, biểu tượng"],"answerLetter":"B","answerText":"B. Khái niệm, phán đoán và suy lý","notes":""},{"id":413,"question":"Ý thức xã hội phản ánh tồn tại xã hội với hai trình đô khác nhau đó là hai trình độ nào?","options":["A. Tâm lý xã hội và hệ tư tưởng xã hội","B. Tâm lý con người và hệ tư tưởng","C. Tinh thần xã hội và hệ tư tưởng","D. Nên tảng vật chất và giá trị tinh thần"],"answerLetter":"A","answerText":"A. Tâm lý xã hội và hệ tư tưởng xã hội","notes":""},{"id":414,"question":"Cái tất nhiên là cái do:","options":["A. Những nguyên nhân cơ bản bên trong sự vật quy định","B. Những nguyên nhân bên ngoài sự vật qui định","C. Cả nguyên nhân bên trong và nguyên nhân bên ngoài sự vật qui định","D. Những nguyên nhân bản chất bên trong qui định"],"answerLetter":"A","answerText":"A. Những nguyên nhân cơ bản bên trong sự vật quy định","notes":""},{"id":415,"question":"Cơ sở khách quan của xây dụng liên minh giữa giai cấp công nhần với giai cấp nông dẫn và các tầng lớp lao động khác trong cách mạng xã hội chủ nghĩa là công nghiệp và nông nghiệp là hai ngành có vai trò như thế nào?","options":["A. Sản xuất","B. Đảm bảo các nhu cầu xã hội","C. Đảm bảo cân đối cung-cầu","D. Sản xuất chính"],"answerLetter":"A","answerText":"A. Sản xuất","notes":""},{"id":416,"question":"Một nhóm sinh viên tranh luận về chân lý, hãy xác định ý kiến nào đúng nhất, chân lý là gì?","options":["A. Quan điễm được mọi người trong cuộc bò phiếu tán thành","B. Quan điểm được đa số ủng hộ","C. Một phán đoán đúng quy tắc logic","D. Một quan điểm được chứng minh trong thực tiễn là đúng"],"answerLetter":"D","answerText":"D. Một quan điểm được chứng minh trong thực tiễn là đúng","notes":""},{"id":417,"question":"Theo quan điểm duy vật lịch sử, sản xuất ra của cải vật chất giữ vai trò là:","options":["A. Nền tảng của xã hội","B. Nền tảng vật chất của xã hội","C. Nền tăng tinh thần của xã hội","D. Nền tảng kỹ thuật, công nghệ của xã hội"],"answerLetter":"B","answerText":"B. Nền tảng vật chất của xã hội","notes":""},{"id":418,"question":"Phép biện chứng chất phác thời cổ đại là","options":["A. Một hình thức của chủ nghĩa duy tâm","B. Một phần của chủ nghĩa duy vật","C. Tất cà đêu đúng","D. Một hình thức của phép biện chứng"],"answerLetter":"D","answerText":"D. Một hình thức của phép biện chứng","notes":""},{"id":419,"question":"Tổng hợp tất cả những mặt, những mối liên hệ tất nhiên, tương đối ổn định bên trong sự vật, quy định sự vận động và phát triển của sự vật gọi là gì?","options":["A. Bản chất","B. Hiện tượng","C. Nội dung","D. Hình thức"],"answerLetter":"A","answerText":"A. Bản chất","notes":""},{"id":420,"question":"Vấn đề cơ bản của Triết học là gì?","options":["A. Mối quan hệ giữa tự nhiên và bản thể","B. Mối quan hệ giữa tư duy và tồn tại","C. Mối quan hệ giữa cái chung và cái riêng","D. Con người và bản thể"],"answerLetter":"B","answerText":"B. Mối quan hệ giữa tư duy và tồn tại","notes":""},{"id":421,"question":"Chủ nghĩa duy vật biện chứng khẳng định rằng, nguyên nhân sinh ra kết quả phải có thêm yếu tố nào","options":["A. Tác động","B. Điều kiện","C. Nguyên cũ","D. Y chí"],"answerLetter":"B","answerText":"B. Điều kiện","notes":""},{"id":422,"question":"Theo quan điểm của chủ nghĩa duy vật thì những mối liên hệ tên tại ở mọi sự vật, hiện tượng của thế giới là mối liên hệ","options":["A. Chung","B. Quan trọng","C. Khá phổ biến","D. Phổ biến"],"answerLetter":"D","answerText":"D. Phổ biến","notes":""},{"id":423,"question":"Nguyên nhân và kết quả cái nào có trước?","options":["A. Nguyên nhân","B. Kết quả","C. Cả hai cùng xuất hiện trước","D. Không cái nào xuất hiện trước"],"answerLetter":"A","answerText":"A. Nguyên nhân","notes":"(Kiểu hỏi khác: Theo quan điểm của chủ nghĩa duy vật biện chứng thì những mối liên hệ tồn tại ở mọi sự vật, hiện tượng của thế giới là mối liên hệ như thế nào?)"},{"id":424,"question":"Mối liên hệ thống nhất và đầu tranh, chuyển hoá giữa các mặt đối lập của mỗi sự vật, hiện tượng hoặc giữa các sự vật, hiện tượng với nhau gọi là khái niệm gì?","options":["A. Chuyển hoá chất, lượng","B. Sự thống nhất","C. Quan hệ hài hòa.","D. Mâu thuẫn"],"answerLetter":"D","answerText":"D. Mâu thuẫn","notes":""},{"id":425,"question":"Ai là người khẳng định: \"lao động đã sáng tạo ra bản thân con người?","options":["A. Ph.Ăngghen","B. L.Phoiobác","C. Immanuel Kant","D. Béccdren"],"answerLetter":"A","answerText":"A. Ph.Ăngghen","notes":""},{"id":426,"question":"Theo quan niệm duy vật biện chứng về lịch sử thì đề giải thích đúng đắn các vấn đề của đời sống xã hội thì phải tim nguyên nhân cuối cùng từ thực trạng phát triển của năm sản xuất vật chất của xã hội đô, mà căn bản là từ trình độ phát triển của","options":["A. Phương thức sản xuất của nó","B. Quan hệ sản xuất của nó","C. Tư liệu sản xuất của nó","D. Cơ sở vật chất"],"answerLetter":"B","answerText":"B. Quan hệ sản xuất của nó","notes":""},{"id":427,"question":"Tinh thiên - Trời hửngSự vật vần xoay đà định sẵn,Hết mưa là nắng hừng lên thôi,Đất trời một thoáng thu màn ướt,Sông núi muôn trùng trải gấm phơi,Trời ẩm, hoa cười chào gió nhẹ,Cây cao, chim hót rộn cành tươi,Người cùng vạn vật đều phơi phới,Hết khổ là vui vốn lẽ đời.Trong bài thơ trên của Chủ tịch Hồ Chí Minh, cặp phạm trù nào được nhắc đến?","options":["A. Cái chung, cái riêng","B. Bản chất, hiện tượng","C. Tất nhiên, ngẫu nhiên","D. Nguyên nhân, kết quả"],"answerLetter":"C","answerText":"C. Tất nhiên, ngẫu nhiên","notes":""},{"id":428,"question":"Lơ xíp (khoảng 500 - 440 trước CN) được xem là?","options":["A. Nhà triết học Giáo hội Cổ đại","B. Nhà toán học Hi Lạp Cổ đại","C. Nhà triết học Hi Lạp Cổ đại","D. Nhà thần học Hi Lạp Cổ đại"],"answerLetter":"C","answerText":"C. Nhà triết học Hi Lạp Cổ đại","notes":""},{"id":429,"question":"Ai được xem là nhà triết học thiên tài vào thế kỷ XVIII - XIX?","options":["A. Hecralitus","B. Immanuel Kant","C. Socrates","D. Bruno Fesnades"],"answerLetter":"B","answerText":"B. Immanuel Kant","notes":""},{"id":430,"question":"Chủ nghĩa duy vật hình thành và phát triển với mấy hình thức cơ bản?","options":["A. 1","B. 2","C. 3","D. 4"],"answerLetter":"C","answerText":"C. 3","notes":""},{"id":431,"question":"Đâu là nhận định đúng về Triết học?","options":["A. Triết học là hạt nhân của tôn giáo","B. Triết học là hạt nhân của thế giới quan","C. Triết học là trung tâm của phương pháp luận","D. Triết học là hạt nhân của phương pháp luận"],"answerLetter":"B","answerText":"B. Triết học là hạt nhân của thế giới quan","notes":""},{"id":432,"question":"Ai là người tạo ra cơ sở tri thức cho sự phát triển của triết học trong thời kỳ Phục hưng?","options":["A. Adam Smith","B. Math Lurer","C. Xanhxi-mong","D. Copernicus"],"answerLetter":"D","answerText":"D. Copernicus","notes":""},{"id":433,"question":"Thời kỳ Phục hưng bắt đầu ở quốc gia nào?","options":["A. Pháp","B. Ý","C. Anh","D. Bồ Đào Nha"],"answerLetter":"B","answerText":"B. Ý","notes":""},{"id":434,"question":"Chủ nghĩa duy vật siêu hình ra đời gắn liền với thời kỳ nào?","options":["A. Thời kỳ Phục hưng","B. Thời kỳ Trung cổ","C. Thời kỳ Khải huyền","D. Thời kỳ cận đại"],"answerLetter":"D","answerText":"D. Thời kỳ cận đại","notes":""},{"id":435,"question":"Ngũ hành gồm những yếu tố nào?","options":["A. Nhân, lễ, nghĩa, trí, tín","B. Kim, mộc, thổ, thủy, không khí","C. Kim, mộc, thủy, hỏa, thổ","D. Kim, mộc, thủy, hỏa, lễ"],"answerLetter":"C","answerText":"C. Kim, mộc, thủy, hỏa, thổ","notes":""},{"id":436,"question":"Theo triết học Mác - Lênin, yếu tố nào đóng vai trò quyết định đối với tất cả các mặt của đời sống xã hội?","options":["A. Khoa học","B. Phương thức sản xuất","C. Chính trị","D. Văn hóa nghệ thuật"],"answerLetter":"B","answerText":"B. Phương thức sản xuất","notes":"(Kiểu hỏi khác: Trường phái triết học nào sau đây cho rằng vật chất bao gồm các yếu tố: kim, mộc, thủy, hòa, thố?)"},{"id":437,"question":"Sự ra đời của quan điểm duy vật về lịch sử do C. Mác sáng lập ra đã khắc phục được những sai lầm căn bản trong việc lý giải xã hội theo:","options":["A. Quan điểm tôn giáo và duy tâm","B. Quan điểm duy vật siêu hình và tôn giáo","C. Quan điểm duy tâm và siêu hình","D. Quan điểm duy vật tự nhiên và tầm thường"],"answerLetter":"C","answerText":"C. Quan điểm duy tâm và siêu hình","notes":""},{"id":438,"question":"Phạm trù nhằm chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau gây ra, gọi là gì?","options":["A. Nguyên nhân","B. Kết quả","C. Hiện thực","D. Khả năng"],"answerLetter":"B","answerText":"B. Kết quả","notes":""},{"id":439,"question":"Theo quan điểm của triết học Mác - Lênin, con người là thực thể thống nhất của các mặt nào?","options":["A. Sinh học và tâm lý","B. Sinh học và xã hội","C. Phẩm chất đạo đức và nhân cách","D. Tâm lý và năng lực nhận thức"],"answerLetter":"B","answerText":"B. Sinh học và xã hội","notes":""},{"id":440,"question":"Chủ nghĩa duy vật là trường phái triết học cho rằng:","options":["A. Bản chất thế giới là vật thể","B. Bản chất thế giới là vật chất","C. Vật chất là tính thứ hai","D. Vật chất tác động đến ý thức","E. Bản chất thế giới là vật chất và ý thức"],"answerLetter":"B","answerText":"B. Bản chất thế giới là vật chất","notes":""},{"id":441,"question":"Theo chủ nghĩa duy vật biện chứng, mối quan hệ giữa lực lượng sản xuất và quan hệ sản xuất?","options":["A. Biện chứng","B. Tương hỗ","C. Phụ thuộc","D. Quan điểm toàn diện và cụ thể"],"answerLetter":"A","answerText":"A. Biện chứng","notes":""},{"id":442,"question":"Ngày nay, trong nền sản xuất xã hội, tỷ trọng lao động trí tuệ có xu hướng như thế nào?","options":["A. Tăng dần","B. Giảm dần","C. Điều hòa","D. Ổn định"],"answerLetter":"A","answerText":"A. Tăng dần","notes":""},{"id":443,"question":"Sản xuất vật chất là hoạt động có tính chất gì?","options":["A. Tính khách quan, tính tất yếu, tính xã hội, tính văn hóa và tính mục đích","B. Tính tất yếu, tính tư duy, tính cộng đồng, tính văn hóa và tính mục đích","C. Tính khách quan, tính mục đích, tính xã hội, tính lịch sử và tính sáng tạo","D. Tính xã hội, tính lịch sử, tính sáng tạo, tính văn hóa và tính mục đích tự thân"],"answerLetter":"C","answerText":"C. Tính khách quan, tính mục đích, tính xã hội, tính lịch sử và tính sáng tạo","notes":""},{"id":444,"question":"Đâu là một trong những hình thức tồn tại của vật chất?","options":["A. Không gian, thời gian","B. Vật thế","C. Cái bàn, cái quạt","D. Không có phương án đúng"],"answerLetter":"A","answerText":"A. Không gian, thời gian","notes":""},{"id":445,"question":"Theo chủ nghĩa duy vật lịch sử, lực lượng sản xuất có quan hệ thế nào với quan hệ sản xuất?","options":["A. Quyết định","B. Tác động trở lại","C. Phụ thuộc","D. Không phụ thuộc"],"answerLetter":"A","answerText":"A. Quyết định","notes":""},{"id":446,"question":"Chủ nghĩa duy vật cho rằng đầu là bản nguyên của thế giới?","options":["A. Bản chất thế giới là vật chất","B. Bản nguyên thế giới là ý thức","C. Bản nguyên thế giới là lực lượng siêu nhiên","D. Bản nguyên thế giối là Thượng đẽ"],"answerLetter":"A","answerText":"A. Bản chất thế giới là vật chất","notes":""},{"id":447,"question":"Thừa nhận sự tồn tại của vật chất và tinh thần là bản nguyên có thể cùng quyết định nguồn gốc và sự vận động của thế giới là trường phái nào?","options":["A. Nhị nguyên luận","B. Biện chững","C. Biện chúng luận","D. Chủ nghĩa Mác - Lênin"],"answerLetter":"A","answerText":"A. Nhị nguyên luận","notes":""},{"id":448,"question":"Tại sao khi nhìn lên trời, mỗi người đều nhìn thấy đám mây với những hình thù khác nhau?","options":["A. Sự phản ánh năng động, sáng tạo của ý thức","B. Do ý muốn chủ quan của mỗi người","C. Thế giới khách quan đa dạng phong phú","D. Do đám mây hôm đó có hình thù như vật cụ thể nên mỗi người nhìn khác nhau"],"answerLetter":"A","answerText":"A. Sự phản ánh năng động, sáng tạo của ý thức","notes":""},{"id":449,"question":"Theo triết học Mác-xít thì siêu hình và biện chứng là hai phương pháp như thế nào?(073-356-8678)","options":["A. Đối lập nhau","B. Tương tác lần nhau","C. Bổ sung cho nhau","D. Có mối liên hệ với nhau"],"answerLetter":"A","answerText":"A. Đối lập nhau","notes":""},{"id":450,"question":"Cơ sở của sự tồn tại và phát triển xã hội có nguồn gốc trực tiếp từ đâu?","options":["A. Nên tảng xã hội","B. Sản xuất vật chất","C. Thế giới vật chất","D. Thế giới khách quan"],"answerLetter":"B","answerText":"B. Sản xuất vật chất","notes":""},{"id":451,"question":"Vấn đề cơ bản của triết học có hai mặt. Mặt thứ nhất phải trả lời cho hỏi cái nào có trước, cái nào có sau, cái nào quyết định cái nào. Đó là quan hệ giữa cái gì với cái gì?","options":["A. Tư duy với thực tế","B. Tư duy với xã hội","C. Ý thức vật chất","D. Ý thức và bộ não"],"answerLetter":"C","answerText":"C. Ý thức vật chất","notes":""},{"id":452,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, mỗi hình thái kinh tế - xã hội được cấu thành từ những nhân tố nào?","options":["A. Lực lượng sản xuất, kiến trúc thượng tầng","B. Quan hệ kinh tế, lực lượng sản xuất và kiến trúc thượng tầng","C. Quan hệ sản xuất và kiến trúc thượng tầng","D. Lực lượng sản xuất, quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội và kiến trúc thượng tầng"],"answerLetter":"D","answerText":"D. Lực lượng sản xuất, quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội và kiến trúc thượng tầng","notes":"(Kiểu hỏi khác: Mặt thứ nhất trong vấn đề cơ bản của triết học giải quyết mỗi quan hệ giữa các yếu tố nào sau đây?)"},{"id":453,"question":"Theo quan điểm của chủ nghĩa duy tâm khách quan, mối quan hệ giữa các sự vật do cái gì quyết định?","options":["A. Lực lượng siêu nhiên (thượng đế, ý niệm tuyệt đối)","B. Cảm giác, thói quen của con người","C. Bản chất của thế giới tự nhiên","D. Phức hợp của cảm giác"],"answerLetter":"A","answerText":"A. Lực lượng siêu nhiên (thượng đế, ý niệm tuyệt đối)","notes":""},{"id":454,"question":"Nguồn gốc tự nhiên của ý thức bao gồm yếu tố nào?","options":["A. Thế giới vật chất của con người","B. Thế giới khách quan","C. Não người","D. B và C"],"answerLetter":"D","answerText":"D. B và C","notes":""},{"id":455,"question":"Chọn phương án trả lời phù hợp nhất. \"Sự ra đời của Triết học Mác là một quá trình...\". Từ còn thiếu trong chỗ trống là gì?","options":["A. Tất yếu khách quan","B. Thiết yếu","C. \"nhiều hơn và đồ sộ hơn\"... \"thế hệ trước\"","D. Đấu tranh của giai cấp"],"answerLetter":"A","answerText":"A. Tất yếu khách quan","notes":""},{"id":456,"question":"Quan điểm nào thuộc chủ nghĩa duy tâm?","options":["A. Vật chất quyết định ý thức","B. Vật chất là tính thứ nhất, ý thức là tính thứ hai","C. Vật chất và ý thức song song tồn tại, không cái nào phụ thuộc cái nào","D. Ý thức có trước, vật chất có sau; ý thức quyết định vật chất"],"answerLetter":"D","answerText":"D. Ý thức có trước, vật chất có sau; ý thức quyết định vật chất","notes":""},{"id":457,"question":"Bộ phận nào của tư liệu lao động được coi là tiêu chí phản ánh đặc trưng phát triển của một thời đại kinh tế?","options":["A. Công cụ lao động","B. Kết cấu hạ tầng sản xuất","C. Nhà cửa, kho bãi để chứa đựng, bảo quản","D. Quan hệ sản xuất"],"answerLetter":"A","answerText":"A. Công cụ lao động","notes":"(Kiểu hỏi khác: Triết học duy tâm cho rằng điều nào là đúng sau đây? A. Vật chất quyết định ý thức B. Ý thức quyết định vật chất C. Con người quyết định tất cà)"},{"id":458,"question":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào là quy luật về khuynh hướng cơ bản, phổ biến của mọi sự vận động và phát triển diễn ra trong lĩnh vực tự nhiên, xã hội và tư duy?","options":["A. Vận động","B. Lượng đổi, chất đổi","C. Mâu thuẫn","D. Phủ định của phủ định"],"answerLetter":"D","answerText":"D. Phủ định của phủ định","notes":""},{"id":459,"question":"Đâu không phải là quan điểm của Chủ nghĩa Mác-Lênin về lãnh tụ?","options":["A. Những cá nhân kiệt xuất trong nhiều lĩnh vực","B. Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân","C. Những cá nhân kiệt xuất được quần chúng tín nhiệm","D. Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân dân"],"answerLetter":"A","answerText":"A. Những cá nhân kiệt xuất trong nhiều lĩnh vực","notes":""},{"id":460,"question":"Trong các yếu tố của lực lượng sản xuất, yếu tố nào là quan trọng nhất?","options":["A. Tư liệu sản xuất","B. Người lao động","C. Đối tượng lao động","D. Máy móc và công nghệ hiện đại"],"answerLetter":"B","answerText":"B. Người lao động","notes":""},{"id":461,"question":"Tiền đề xuất phát chủ nghĩa duy vật lịch sử là gì?","options":["A. Con người hiện thực","B. Con người trừu tượng","C. Con người hành động","D. Con người tư duy"],"answerLetter":"A","answerText":"A. Con người hiện thực","notes":""},{"id":462,"question":"Quan điểm lịch sử cụ thể được rút ra từ nghiên cứu nguyên lý triết học nào sau đây?","options":["A. Nguyên lý duy vật lịch sử","B. Nguyên lý về mối liên hệ phổ biến","C. Nguyên lý phát triển","D. Nguyên lý triết học thực hành"],"answerLetter":"B","answerText":"B. Nguyên lý về mối liên hệ phổ biến","notes":""},{"id":463,"question":"Theo quan điểm của triết học Mác - Lênin mối quan hệ giữa \"sự thống nhất và đấu tranh của các mặt đối lập\" là như thế nào?","options":["A. Sự thống nhất và đấu tranh của các mặt đối lập là thống nhất. Không có thống nhất của các mặt đối lập thì cũng không có đấu tranh của các mặt đối lập","B. Sự đấu tranh của các mặt đối lập vừa tương đối, vừa tuyệt đối","C. Không có sự thống nhất của các mặt đối lập\" thì vẫn có sự đấu tranh của các mặt đối lập\"","D. Không có sự đấu tranh của các mặt đối lập\" thì có thể trong một vài trường hợp sẽ có \"sự thống nhất của các mặt đối lập\""],"answerLetter":"A","answerText":"A. Sự thống nhất và đấu tranh của các mặt đối lập là thống nhất. Không có thống nhất của các mặt đối lập thì cũng không có đấu tranh của các mặt đối lập","notes":""},{"id":464,"question":"Ai là người định nghĩ","options":["A. \"Vật chất là cái phi vật chất đang vận động\"?A. E.Makho","B. Anhxtanh","C. Béc cơren","D. Henri Berson (Piecson)"],"answerLetter":"D","answerText":"D. Henri Berson (Piecson)","notes":""},{"id":465,"question":"Theo chủ nghĩa duy vật lịch sử thì những biến đổi từ đầu tạo ra nhu cầu khách quan phải có sự biến đổi tượng ứng trong kiến trúc thượng tầng?","options":["A. Cơ sở hạ tầng","B. Lực lượng sản xuất","C. Quan hệ sản xuất"],"answerLetter":"A","answerText":"A. Cơ sở hạ tầng","notes":""},{"id":466,"question":"Trong sự tác động trở lại của kiến trúc thượng tầng đến cơ sở hạ tầng, yếu tố nào có tác động lớn nhất?","options":["A. Nhà nước","B. Tôn giáo","C. Ý thức chính trị","D. Văn hóa"],"answerLetter":"A","answerText":"A. Nhà nước","notes":""},{"id":467,"question":"Chọn câu trả lời đúng nhất theo quan điêm duy vật lịch sử:Khẳng định tính lịch sử - tự nhiên của sự phát triển các hình thái kinh tế - xã hội, tức là khẳng định sự phát triên của xã hội:","options":["A. Hoàn toàn tuân theo quy luật khách quan của giới tự nhiên","B. Hoàn toàn tuân theo quy luật khách quan của xã hội","C. Hoàn toàn tuân theo quy luật khách quan của tự nhiên và xã hội","D. Tuân theo quy luật khách quan nhưng đồng thời chịu sự tác động của các nhân tố khác"],"answerLetter":"D","answerText":"D. Tuân theo quy luật khách quan nhưng đồng thời chịu sự tác động của các nhân tố khác","notes":""},{"id":468,"question":"Trong quan điểm của phép biện chững duy vật thì với hình thức, nội dung giữ vai trò:","options":["A. Quyết định","B. Phụ thuộc","C. Không phụ thuộc","D. Ít phụ thuộc"],"answerLetter":"A","answerText":"A. Quyết định","notes":""},{"id":469,"question":"Cơ sở chủ yếu nhất để hình thành nên khái niệm là gì?","options":["A. Thế giới tự nhiên","B. Thực tiễn","C. Cảm giác","D. Tri gác và biểu tượng"],"answerLetter":"B","answerText":"B. Thực tiễn","notes":""},{"id":470,"question":"Theo quan điểm của chủ nghĩa duy vật thì bất kỳ một sự vật, hiện tượng nào, ở bất kỳ không gian nào và ở bất kỳ thời gian nào cũng có mỗi liên hệ với những sự vật, hiện tượng khác là biểu hiện tính chất nào của mỗi liên hệ?","options":["A. Tính đa dạng","B. Tính khách quan","C. Tính phổ biến","D. Tính chung nhất"],"answerLetter":"C","answerText":"C. Tính phổ biến","notes":""},{"id":471,"question":"\"Phương pháp biện chứng của tôi không những khác phương pháp của Hêghen về cơ bản mà còn đối lập hẳn với phương pháp ấy nữa\" là luận điểm của ai?","options":["A. Phoiơbắc","B. Ph. Ăngghen","C. V.I. Lênin","D. C.Mác"],"answerLetter":"D","answerText":"D. C.Mác","notes":""},{"id":472,"question":"Yếu tố biện chứng trong triết học Phật giáo được thể hiện qua quan điểm về điều gì?","options":["A. Vô thường, nhân duyên","B. Bắt chính đạo","C. Bát khô","D. Vô thường, vô ngã, vô tạo giả"],"answerLetter":"D","answerText":"D. Vô thường, vô ngã, vô tạo giả","notes":""},{"id":473,"question":"Đấu tranh của hai mặt đối lập là:","options":["A. Sự tác động qua lại theo xu hướng bài trừ và phủ định lẫn nhau","B. Sự tác động lẫn nhau giữa hai mặt đối lập theo khuynh hướng biện chứng","C. Các phương án trả lời đều sai"],"answerLetter":"A","answerText":"A. Sự tác động qua lại theo xu hướng bài trừ và phủ định lẫn nhau","notes":""},{"id":474,"question":"Theo quan điểm triết học Mác - Lênin, nhà nước có mấy đặc trưng?","options":["A. Hai đặc trưng","B. Ba đặc trưng","C. Bốn đặc trưng","D. Năm đặc trưng"],"answerLetter":"D","answerText":"D. Năm đặc trưng","notes":""},{"id":475,"question":"Thông thường, trong kiến trúc thượng tầng các nhà nước tư bản hiện nay:","options":["A. Đều thực hiện chế độ nhất nguyên chính trị","B. Không thực hiện chế độ đa nguyên chính trị","C. Tùy từng nước mà có thể thực hiện chế độ đa nguyên chính trị hay không","D. Thực hiện chế độ đa đảng nhưng nhất nguyên chính trị"],"answerLetter":"D","answerText":"D. Thực hiện chế độ đa đảng nhưng nhất nguyên chính trị","notes":""},{"id":476,"question":"Theo quan điểm của phép biện chứng duy vật thì những thay đối về chất của sự vật lại tạo ra những thay đổi gì của sự vật trên các phương diện khác nhau?","options":["A. Biến đổi mới về lượng","B. Biến đổi của chất","C. Chất mới","D. Cái mới"],"answerLetter":"A","answerText":"A. Biến đổi mới về lượng","notes":""},{"id":477,"question":"Theo quan điểm của chủ nghĩa Mác-Lênin, Kiến trúc thượng tầng là gì?","options":["A. Toàn bộ thiết chế chính trị của xã hội","B. Toàn bộ thiết chế chính trị và pháp luật của xã hội","C. Toàn bộ thiết chế chính trị - xã hội","D. Toàn bộ hệ thống kết cấu các hình thái ý thức xã hội cùng với các thiết chế chính trị - xã hội tương ứng"],"answerLetter":"D","answerText":"D. Toàn bộ hệ thống kết cấu các hình thái ý thức xã hội cùng với các thiết chế chính trị - xã hội tương ứng","notes":""},{"id":478,"question":"Cơ sở để phần chia triết học thành các trường phái khác nhau là:","options":["A. Vấn đề cơ bản của nhận thức luận","B. Vấn đề cơ bản của phương pháp luận","C. Vấn đề cơ bản của triết học"],"answerLetter":"C","answerText":"C. Vấn đề cơ bản của triết học","notes":""},{"id":479,"question":"Thuộc tính cơ bàn nhất, phố biến nhất của mọi tồn tại vật chất được khái quát trong phạm trù vật chất của chủ nghĩa duy vật biện chứng là:","options":["A. Không gian và thời gian","B. Tồn tại khách quan","C. Tồn tại trong vận động","D. Vận động và đứng im"],"answerLetter":"B","answerText":"B. Tồn tại khách quan","notes":""},{"id":480,"question":"Luận điểm \"Bản chất là những thực thể tinh thần tồn tại khách quan, quyết định sự tồn tại của sự vật\" thuộc lập trường triết học nào?","options":["A. Chủ nghĩa duy tâm chủ quan","B. Chủ nghĩa duy tâm khách quan","C. Chủ nghĩa duy vật siêu hình","D. Tất cà các đáp án đều đúng"],"answerLetter":"B","answerText":"B. Chủ nghĩa duy tâm khách quan","notes":""},{"id":481,"question":"Sự thống nhất giữa lực lượng sản xuất với một trình độ nhất định và quan hệ sản xuất tương ứng tạo thành gì?","options":["A. Bản chất hàng hóa","B. Năng lực sáng tạo","C. Cách thức sản xuất","D. Phương thức sản xuất"],"answerLetter":"D","answerText":"D. Phương thức sản xuất","notes":""},{"id":482,"question":"Quan điểm phát triển đòi hỏi điều gì?","options":["A. Bảo vệ cái mới, ủng hộ cái mỗi, đấu tranh cho cái mổi nhưng không phủ định sạch trơn cái cũ","B. Bảo vệ cái cũ, đấu tranh cho cái cũ đồng thời tạo điều kiện để cái mới ra đời và thay thế cái cũ","C. Phát huy những mặt tích cực của cái cũ, tạo điều kiện cho nó phát triển","D. Tạo điều kiện tiền đề cho cái mới phát triển"],"answerLetter":"A","answerText":"A. Bảo vệ cái mới, ủng hộ cái mỗi, đấu tranh cho cái mổi nhưng không phủ định sạch trơn cái cũ","notes":""},{"id":483,"question":"Điều khẳng định nào sau đây là đúng?","options":["A. Thuyết không thế biết không thừa nhận chân lý khách quan.","B. Chủ nghĩa duy tâm chủ quan không thừa nhận chân lý khách quan.","C. Chủ nghĩa duy tâm khách quan thừa nhận chân lý chủ quan.","D. Chủ nghĩa duy vật biện chứng thừa nhận chân lý khách quan."],"answerLetter":"D","answerText":"D. Chủ nghĩa duy vật biện chứng thừa nhận chân lý khách quan.","notes":""},{"id":484,"question":"Theo chủ nghĩa duy vật lịch sử, cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu:","options":["A. Của xã hội","B. Kỹ thuật xã hội","C. Kinh tế của xã hội","D. Vật chất xã hội"],"answerLetter":"C","answerText":"C. Kinh tế của xã hội","notes":""},{"id":485,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, để giải thích đúng và triệt để các hiện tượng trong đời sống xã hội, cần phải xuất phát trừ:","options":["A. Nền sản xuất vật chất của xã hội","B. Quan điểm chính trị của giai cấp nắm quyền lực nhà nước","C. Truyền thống văn hóa xã hội","D. Ý trí của mọi thành viên trong cộng đồng xã hội"],"answerLetter":"A","answerText":"A. Nền sản xuất vật chất của xã hội","notes":""},{"id":486,"question":"Vì các mối liên hệ có tính đa dạng, phong phú nên trong hoạt động nhận thức và thực tiển khi thực hiện quan điểm toàn diện thì con người phải kết hợp với quan điểm:","options":["A. Lịch sử - cụ thể","B. Toàn diện","C. Biện chứng","D. Khách quan"],"answerLetter":"A","answerText":"A. Lịch sử - cụ thể","notes":""},{"id":487,"question":"Luận điểm sau đây thuộc quan điểm triết học nào: \"Phát triển là quá trình chuyễn hóa từ những thay đối về lượng thành sự thay đối về chất và ngược lại\"?","options":["A. Quan điểm chiết trung và ngụy biện","B. Tất cả đều đúng","C. Quan điểm biện chứng","D. Quan điểm siêu hình"],"answerLetter":"C","answerText":"C. Quan điểm biện chứng","notes":""},{"id":488,"question":"Trình độ phát triển của phương thức sản xuất ra của cải vật chất là nhân tố giữ vai trò quyết định:","options":["A. Đời sống tinh thần của xã hội","B. Đời sống văn hóa của xã hội","C. Đời sống chính trị, đạo đức của xã hội","D. Trình độ phát triễn của nên sản xuất xã hội"],"answerLetter":"D","answerText":"D. Trình độ phát triễn của nên sản xuất xã hội","notes":""},{"id":489,"question":"\"Mặt người da thú\" giúp anh/chị liên hệ tối cặp phạm trù nào trong triết học?","options":["A. Cái chung, cái riêng","B. Bản chất, hiện tượng","C. Tất nhiên, ngẩu nhiên","D. Nguyên nhân, kết quả"],"answerLetter":"B","answerText":"B. Bản chất, hiện tượng","notes":""},{"id":490,"question":"Cơ sở của sự tồn tại, phát triển là gì?","options":["A. Lao động của thễ giới","B. Sản xuất vật chất","C. Chủ nghĩa tư bản và chủ nghĩa xã hội","D. Tiêu dùng xã hội"],"answerLetter":"B","answerText":"B. Sản xuất vật chất","notes":""},{"id":491,"question":"Một trong những nội dung chi tính thống nhất vật chất của thế giới là gì?","options":["A. Chỉ có một thế giới duy nhất, thế giới thống nhất với nhau","B. Chỉ có một thế giối duy nhất, thế giới thống nhất ở tính vật chất","C. Thế giới này là do vụ nổ vũ trụ gây ra, tạo ra những hành tinh mang tính vật chất","D. A và B"],"answerLetter":"B","answerText":"B. Chỉ có một thế giối duy nhất, thế giới thống nhất ở tính vật chất","notes":""},{"id":492,"question":"Phép biện chứng nào được coi là khoa học về những quy luật phổ biến của sự vận động và sự phát triên của tự nhiên, xã hội và tư duy con người:","options":["A. Phép biện chứng cổ đại","B. Phép biện chứng cổ điển Đức","C. Phép biện chứng của chủ nghĩa Mác - Lênin","D. Phép biện chứng của G. W.Ph.Hêghen"],"answerLetter":"C","answerText":"C. Phép biện chứng của chủ nghĩa Mác - Lênin","notes":""},{"id":493,"question":"Ai là tác giả của Thuyết tương đối tổng quát?","options":["A. Albert Einstein (A.Anhxtanh)","B. Nicolai Copecnic","C. Jos. Bruno","D. Alex. Sancho"],"answerLetter":"A","answerText":"A. Albert Einstein (A.Anhxtanh)","notes":""},{"id":494,"question":"Theo chủ nghĩa duy vật biện chúng, vận động không chỉ là sự thay đổi vị trí trong không gian, mà còn là mọi sự thay đối và:","options":["A. Mọi di chuyển trong thực tế","B. Mọi quá trinh diễn ra trong vũ trụ","C. Mọi vận động trong tự nhiên, xã hội","D. Mọi vận động trong xã hội"],"answerLetter":"B","answerText":"B. Mọi quá trinh diễn ra trong vũ trụ","notes":""},{"id":495,"question":"Triết học ra đời vào thời gian nào?","options":["A. Thế kỷ II. TCN","B. Thế kỷ VIII - VI TCN","C. Thế kỷ II sau CN","D. Thế kỷ VII - VI TCN"],"answerLetter":"B","answerText":"B. Thế kỷ VIII - VI TCN","notes":""},{"id":496,"question":"Trước khi triết học Mác ra đời, triết học được \"suy tôn\" là gì?","options":["A. Khoa học nghiên cứu","B. Khoa học của các khoa học","C. Khoa học của toán học","D. Khoa học của tầng lớp quý tộc"],"answerLetter":"B","answerText":"B. Khoa học của các khoa học","notes":""},{"id":497,"question":"Đêmôcrit (khoảng 427 -374 trước CN) được xem là?","options":["A. Nhà triết học Giáo hội Cổ đại","B. Nhà toán học Hi Lạp Cổ đại","C. Nhà triết học Hi Lạp Cổ đại","D. Nhà thần học Hì Lạp Cổ đại"],"answerLetter":"C","answerText":"C. Nhà triết học Hi Lạp Cổ đại","notes":""},{"id":498,"question":"Ném một đồng xu có hai mặt đen và trắng lên trời, đồng xu rơi xuống đất và ngửa mắt đen liên trên. Hiện tượng trên gọi là","options":["A. Ngẫu nhiên","B. Tất nhiên","C. Vừa tất nhiên vừa ngẫu nhiên","D. Không phải tất nhiên và cũng không phải ngẫu nhiên"],"answerLetter":"C","answerText":"C. Vừa tất nhiên vừa ngẫu nhiên","notes":""},{"id":499,"question":"Triết học trở thành nữ tì của thần học trong giai đoạn nào?","options":["A. Ở Tây Âu thời trung cố","B. Ở Tây Âu thời cổ đại","C. Ở Tây Âu thời cận đại","D. Ở Châu Âu thời hiện đại"],"answerLetter":"A","answerText":"A. Ở Tây Âu thời trung cố","notes":""},{"id":500,"question":"Công ty sản xuất thuốc bảo vệ thực vật muốn bổ nhiệm anh Nguyễn Văn A và chị Trần Thị B làm trưởng phòng quản lý nhân sự. Trong quá trình xem xét, công ty đó đã căn cứ vào năng lực tích lũy trong quá trình làm việc, độ nhạy bén khi xử lý công việc, năng lực phán đoán của Anh A và Chị B... Căn cứ vào ví dụ trên, Anh (Chị) hãy cho biết công ty đó đã vận dụng nội dung nào sau đây để bổ nhiệm nhân sự?","options":["A. Nguyên lý về mối liên hệ phổ biến","B. Nguyên lý về sự phát triển","C. Quy luật phủ định của phủ định","D. Quy luật đấu tranh và thống nhất giữa các mặt đối lập"],"answerLetter":"B","answerText":"B. Nguyên lý về sự phát triển","notes":""},{"id":501,"question":"Dân chủ được hiểu là gì?","options":["A. Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại","B. Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp tư sản cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại","C. Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tố chức nhà nước của giai cấp thống trị cầm quyền; có quá trình ra đời, phát triên từ xã hội chiếm hữu nô lệ","D. Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp vô sản cầm quyền; có quá trình ra đời, phát triễn cùng với lịch sử xã hội nhân loại"],"answerLetter":"A","answerText":"A. Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại","notes":""},{"id":502,"question":"Toàn bộ những biểu tượng, tình cảm, tâm trạng của quần chúng về tín ngưỡng, tôn giáo tạo thành bộ phận nào sau đây?","options":["A. Tâm lý tôn giáo","B. Tổ chức tôn giáo","C. Hành vi tôn giáo","D. Hệ tư tưởng tôn giáo."],"answerLetter":"A","answerText":"A. Tâm lý tôn giáo","notes":""},{"id":503,"question":"Luận điểm cho rằng \"vật hay vật thể là những phức hợp cảm giác\" thuộc trường phái triết học nào?","options":["A. Chủ nghĩa duy tâm chủ quan.","B. Chủ nghĩa duy tâm khách quan.","C. Chủ nghĩa duy vật siêu hình.","D. Tất cả các đáp án đêu đúng."],"answerLetter":"A","answerText":"A. Chủ nghĩa duy tâm chủ quan.","notes":""},{"id":504,"question":"Nhận định nào sau đây là sai khi nói về vị trí, vai trò của Triết học Mác - Lênin trong đời sống xã hội và trong sự nghiệp đổi mới ở Việt Nam hiện nay?","options":["A. Là thế giới quan khoa học cho hoạt động thực tiễn","B. Là phương pháp luận biện chứng cho nhận thức khoa học","C. Là chìa khóa vạn năng để giải quyết mọi vấn đề","D. Là nền tảng tư tưởng, kim chỉ nam cho hành động"],"answerLetter":"C","answerText":"C. Là chìa khóa vạn năng để giải quyết mọi vấn đề","notes":""},{"id":505,"question":"Trả lời theo quan điểm duy vật lịch sử, ý kiến sau đây đúng hay sai? Vì sao?\"Nhà nước là hiện tượng vĩnh viễn của lịch sử\"","options":["A. Đúng. Vì bản chất của con người vốn là tham lam, vị kỷ nên xã hội luôn luôn cần đến quyền lực đặc biệt là nhà nước để điều tiết các quan hệ lợi ích","B. Đúng. Vì đã là một cộng đồng xã hội thì tất yếu phải có sự quản lý và điều tiết chung","C. Sai. Vì nguồn gốc ra đời của nhà nước là do mâu thuẫn giai cấp không thể điều hòa được mà giai cấp không phải là hiện tượng vĩnh viễn của lịch sử","D. Sai. Vì thực tế lịch sử thời nguyên thủy không có tổ chức nhà nước trong kiến trúc thượng tầng của xã hội, còn tương lai của xã hội loài người thế nào thì không thể dự báo chính xác được"],"answerLetter":"C","answerText":"C. Sai. Vì nguồn gốc ra đời của nhà nước là do mâu thuẫn giai cấp không thể điều hòa được mà giai cấp không phải là hiện tượng vĩnh viễn của lịch sử","notes":""},{"id":506,"question":"Hình thức sản xuất nào sau đây có vai trò quyết định sự tồn tại và phát triển của xã hội?","options":["A. Sản xuất vật chất","B. Sản xuất tinh thần","C. Sản xuất con người","D. Sản xuất xã hội"],"answerLetter":"A","answerText":"A. Sản xuất vật chất","notes":""},{"id":507,"question":"Ai là người khẳng định: \"Cần phải có sự phân biệt rõ ràng giữa vật chất với tính cách là một phạm trù của triết học\"?","options":["A. C.Mác","B. Ph.Ăngghen","C. L.Phoiơbắc","D. Immanuel Kant|"],"answerLetter":"B","answerText":"B. Ph.Ăngghen","notes":""},{"id":508,"question":"Nhu cầu ăn, mặc, ở, học tập của con người là:","options":["A. Là cái chung","B. Là cái tất yếu","C. Vừa là cái chung vừa là cái tất yếu"],"answerLetter":"C","answerText":"C. Vừa là cái chung vừa là cái tất yếu","notes":""},{"id":509,"question":"Triết học Mác - Lênin chi ra nguồn gốc của sự hình thành và phân chia giai cấp trong xã hội là do đầu?","options":["A. Trời định","B. Tài năng","C. Kinh tế","D. Chính quyên"],"answerLetter":"C","answerText":"C. Kinh tế","notes":""},{"id":510,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, điều kiện nào sau đây là tiên quyết, cần thiết và chủ yếu quyết định sự hình thành và phát triển của con người cả về phương diện sinh học và xã hội?","options":["A. Lao động","B. Ngôn ngũ","C. Văn hóa","D. Giao tiếp"],"answerLetter":"A","answerText":"A. Lao động","notes":""},{"id":511,"question":"Trường phái triết học nào sau đây cho rằng tinh thần khách quan có trước, tồn tại độc lập với giới tự nhiên và con người?","options":["A. Duy vật thô sơ","B. Duy ý chí","C. Duy tâm chủ quan","D. Duy tâm khách quan"],"answerLetter":"D","answerText":"D. Duy tâm khách quan","notes":""},{"id":512,"question":"Biện chứng là phương pháp xem xét thế giới trong trang thái nào?","options":["A. Bất động, bất biến","B. Luôn vận động, biến đối và phát triển không ngừng","C. Đứng im","D. Không ngừng thay đổi"],"answerLetter":"B","answerText":"B. Luôn vận động, biến đối và phát triển không ngừng","notes":""},{"id":513,"question":"Theo quan điểm duy vật lịch sử, phạm trù nào sau đây ra đời là kết quả của những mâu thuẫn giai cấp không thể điều hòa được?","options":["A. Tôn giáo","B. Đảng phái","C. Nhà nước","D. Nhóm xã hội"],"answerLetter":"C","answerText":"C. Nhà nước","notes":""},{"id":514,"question":"Một sinh viên tâm sự với bạn về hoàn cảnh gia đình mình trong 10 năm đổi mới như sau: gia đình trước đây rất khó khăn. Khi bố từ quân đội về hưu có ít tiền, gia đình đầu tư mua máy và thiết bị sản xuất đậu phụ và làm tương bán. May quá, mặt hàng làm ra có thị trường tiêu thụ ngày càng động. Gia đình còn tân dụng các sản phẩm phụ để nuôi heo. Thế là thu nhập của gia đình tăng dần. đến nay bố tôi đã trở thành một chủ xưởng sản xuất có 20 lao động thuê ngoài. mẹ mình làm trợ lý, mình làm kê toán giúp mẹ. Mặc dù cuộc sống có những lúc khó khăn nhưng gia đình mình đã nỗ lực vượtt qua để có cuộc sống sung túc. Nhà mình bây giờ khang trang, đủ tiện nghi sinh hoạt. Phân tích sự việc trên theo bình diện triết học thì vận dụng theo nguyên lý, quy luật nào là phù hợp?","options":["A. Quy luật phủ định của phủ định","B. Nguyên lý về mỗi liên hệ phổ biến","C. Quy luật mâu thuẫn","D. Quy luật lượng - chất"],"answerLetter":"D","answerText":"D. Quy luật lượng - chất","notes":""},{"id":515,"question":"Chủ nghĩa duy tâm khách quan có tư tưởng như thế nào?","options":["A. Cho rằng đầu óc con người quyết định tất cả hoạt động của con người","B. Cho rằng con người có thể biết được thế giới khi ở trong bốn bức tường trắng","C. Cho rằng ý thức con người chi phối hoạt động của bản thân họ","D. Cho rằng tinh thần khách quan chi phối hoạt động của con người"],"answerLetter":"D","answerText":"D. Cho rằng tinh thần khách quan chi phối hoạt động của con người","notes":""},{"id":516,"question":"Theo quan điểm của triết học Mác - Lênin, cấu trúc của một hình thái kinh tế - xã hội gồm các yếu tố cơ bản hợp thành nào?","options":["A. Lĩnh vực vật chất và lĩnh vực tinh thần","B. Cơ sở hạ tầng, kiến trúc thượng tầng, tồn tại xã hội và ý thức xã hội","C. Lực lượng sản xuất, quan hệ sản xuất và kiến trúc thượng tầng","D. Quan hệ sản xuất, cơ sở hạ tầng, cơ cầu kinh tế và kiến trức thượng tầng"],"answerLetter":"C","answerText":"C. Lực lượng sản xuất, quan hệ sản xuất và kiến trúc thượng tầng","notes":""},{"id":517,"question":"Theo chủ nghĩa duy vật biện chứng, giữa LLSX và QHSX có mối quan hệ như thế nào với nhau?","options":["A. Biện chứng","B. Một chiều","C. Độc lập","D. Tách rời"],"answerLetter":"A","answerText":"A. Biện chứng","notes":""},{"id":518,"question":"..là phương thức tồn tại và phát triển của sự vật, là hệ thống các mối liên hệ tương đối bên vững giữa các yếu tố của sự vật đó:","options":["A. Kết quả","B. Nguyên nhân","C. Nội dung","D. Hình thức"],"answerLetter":"D","answerText":"D. Hình thức","notes":""},{"id":519,"question":"Theo quan điểm của chủ nghĩa duy vật lịch sử, thì suy đến cùng, trình độ phát triển của nền sản xuất ra của cải vật chất của xã hội được quyết định bởi trình độ:","options":["A. Phát triển của phương thức sử dụng lao động","B. Phát triển của các nguồn lực sử dụng trong quá trình sản xuất","C. Phát triển của lực lượng sản xuất","D. Phát triển của quan hệ sản xuất"],"answerLetter":"C","answerText":"C. Phát triển của lực lượng sản xuất","notes":""},{"id":520,"question":"Trong hoạt động thực tiễn, cần khắc phục sự trì trệ, bảo thủ trong việc thực hiện bước nhảy là ý nghĩa phương pháp luận rút ra từ việc nghiên cứu quy luật nào?(073-356-8678)","options":["A. Quy luật mâu thuẫn","B. Quy luật lượng chất","C. Quy luật tự nhiên","D. Quy luật xã hội"],"answerLetter":"B","answerText":"B. Quy luật lượng chất","notes":""},{"id":521,"question":"Câu tục ngũ \"Tốt gỗ hơn tốt nước sơn\" thể hiện cặp phạm trù nào sau đây của Triết học Mác-Lênin?","options":["A. Cái chung, cái riêng","B. Tất nhiên, ngẫu nhiên","C. Nội dung, hình thức","D. Nguyên nhân, kết quả"],"answerLetter":"C","answerText":"C. Nội dung, hình thức","notes":""},{"id":522,"question":"Chủ nghĩa duy vật lịch sử cho rằng, trên cơ sở yếu tố nào làm phát sinh những mỗi quan hệ xã hội khác: chính tri, pháp luật, đạo đức, nghệ thuật, tôn giáo?","options":["A. Cơ sở vật chất","B. Lực lượng sản xuất","C. Quan hệ sản xuất","D. Quan hệ xã hội"],"answerLetter":"D","answerText":"D. Quan hệ xã hội","notes":""},{"id":523,"question":"Ý nghĩa phương pháp luận rút ra từ việc nghiên cứu cặp phạm trủ khả năng - hiện thực là trong thực tế, chúng ta phải dựa vào điều gì sau đây?","options":["A. Hiện thực và bỏ qua các khả năng","B. Mối quan hệ giữa khả năng và hiện thực","C. Hiện thực vì khả năng là cái chưa tồn tại","D. Khả năng vì khả năng có thể chữa hiện thực"],"answerLetter":"B","answerText":"B. Mối quan hệ giữa khả năng và hiện thực","notes":""},{"id":524,"question":"Ai là người đã phủ nhận tính hiện thực khách quan của điện tử?","options":["A. E.Makhơ","B. Piêcson","C. Anhxtanh","D. Béccoren"],"answerLetter":"A","answerText":"A. E.Makhơ","notes":""},{"id":525,"question":"Sự khác nhau căn bản của chủ nghĩa vật với chủ nghĩa duy tâm về sự thống nhất của thế giới là gì?","options":["A. Không thừa nhận tính tồn tại của thế giới","B. Thừa nhận tính tồn tại của thế giới","C. Tất cả đều sai","D. Thừa nhận vật chất và ý thức là bản nguyên cùa thế giới"],"answerLetter":"C","answerText":"C. Tất cả đều sai","notes":""},{"id":526,"question":"Khi V.I. Lênin phát triển chủ nghĩa Mác trong giai đoạn để quốc chủ nghĩa, ông đã bổ sung lý luận nào cho phù hợp với bối cảnh xã hội mới? Chọn 2 đáp án.","options":["A. Khả năng của cách mạng vô sản chỉ có thể xảy ra đồng thời trên toàn cầu","B. Khả năng cách mạng vô sản có thế xảy ra ô một hoặc một số nước có điều kiện thích hợp","C. Chủ nghĩa đế quốc là giai đoạn phát triên cao nhất và là giai đoạn suy tàn của chủ nghĩa tư bản","D. Chủ nghĩa đế quốc phát triển sẽ làm giảm cắng thẳng giữa các quốc gia tư bản, từ đó ổn định xã hội"],"answerLetter":"BC","answerText":"B. Khả năng cách mạng vô sản có thế xảy ra ô một hoặc một số nước có điều kiện thích hợp\nC. Chủ nghĩa đế quốc là giai đoạn phát triên cao nhất và là giai đoạn suy tàn của chủ nghĩa tư bản","notes":"(Giải thích: Thừa nhận tính vật chất của thế giới.)"},{"id":527,"question":"Loại hình hoạt động thực tiền nhằm mục đích cải biến các đối tượng của giối tự nhiên theo nhu cầu tồn tại và phát triển của con người và xã hội là gì?","options":["A. Khoa học","B. Sản xuất vật chất","C. Thực nghiệm khoa học","D. Nghiên cứu khoa học"],"answerLetter":"B","answerText":"B. Sản xuất vật chất","notes":""},{"id":528,"question":"Khái niệm quan hệ sản xuất được hiểu như thế nào?","options":["A. Mối quan hệ giữa con người với giới tự nhiên","B. Tổng hợp các quan hệ kinh tế giữa con người với con người trong quá trình sản xuất vật chất","C. Mối quan hệ giữa con người với con người trong quá trình lao động","D. Mối quan hệ kinh tế trong quá trình sản xuất và tái sản xuất của xã hội"],"answerLetter":"B","answerText":"B. Tổng hợp các quan hệ kinh tế giữa con người với con người trong quá trình sản xuất vật chất","notes":""},{"id":529,"question":"Điền vào dấu \"... tồn tại khách quan, độc lập với ý thức của con người\":","options":["A. Tất nhiên và ngẫu nhiên","B. Chỉ có tất nhiên","C. Chỉ có ngẫu nhiên","D. Tất nhiên và ngẫu nhiên đều không"],"answerLetter":"A","answerText":"A. Tất nhiên và ngẫu nhiên","notes":""},{"id":530,"question":"Theo định nghĩa chung nhất, tồn tại là phạm trù dùng để chỉ tính ... của thế giới xung quanh.... Từ thích hợp trong dấu \"...\" là gì?","options":["A. Có thực/ Con người","B. Có thực chính xác/con người","C. Tâm linh/ Trái đất","D. Chính xác/ Nhận thức"],"answerLetter":"A","answerText":"A. Có thực/ Con người","notes":""},{"id":531,"question":"Theo chủ nghĩa duy vật biện chứng, lao động và ngôn ngữ là sự kích thích chủ yếu dẫn đến các chuyển biến nào trong các chuyển biến sau đây?","options":["A. Sự chuyển biến dần bộ óc của loài vượn người thành bộ óc con người","B. Sự chuyển biến dần tâm lý động vật thành ý thức con người","C. Sự chuyển biến hay mã hóa các đối tượng tinh thần phi vật chất thành các ý tưởng vật chất","D. Sự chuyển biến mô hình từ tư duy đến hình ảnh tinh thần"],"answerLetter":"B","answerText":"B. Sự chuyển biến dần tâm lý động vật thành ý thức con người","notes":""},{"id":532,"question":"V.I.Lênin đã định nghĩa phạm trù vật chất với tư cách là một phạm trù triết học bằng cách đem đối lập với phạm trù nào sau đây?","options":["A. Phạm trù ý thức","B. Phạm trù thực tiễn","C. Phạm trù nhận thức","D. Phạm trù quy luật"],"answerLetter":"A","answerText":"A. Phạm trù ý thức","notes":""},{"id":533,"question":"Quy luật nào là quy luật cơ bản nhất, chi phối, quyết định toàn bộ quá trình vận dộng và phát triển của lịch sử xã hội loài người?","options":["A. Đấu tranh giai cấp","B. Phát triển khoa học và công nghệ","C. Phát triển kinh tế thị trường","D. Quan hệ sản xuất phụ thuộc vào trình độ phát triển của lực lượng sản xuất"],"answerLetter":"D","answerText":"D. Quan hệ sản xuất phụ thuộc vào trình độ phát triển của lực lượng sản xuất","notes":""},{"id":534,"question":"Khẳng định nào sau đây là đúng theo quan điểm của triết học Mác?","options":["A. Vận động là một thuộc tính bắt buộc để chúng ta phát triển","B. Vận động là một thuộc tính cố hữu và là phương thức tồn tại của vật chất","C. Vận động là một thuộc tính tồn tại của vật chất trong thế giới con người","D. Vận động là vận động tự thân nhưng cần sự giúp đỡ của con người"],"answerLetter":"B","answerText":"B. Vận động là một thuộc tính cố hữu và là phương thức tồn tại của vật chất","notes":""},{"id":535,"question":"Nền tảng quan hệ giữa cá nhân và xã hội là gì?","options":["A. Lợi ích","B. Pháp luật","C. Đạo đức","D. Tình cảm"],"answerLetter":"A","answerText":"A. Lợi ích","notes":""},{"id":536,"question":"Đâu là yếu tố vật chất \"trung gian\", \"truyền dẫn\" giữa người lao động và đối tượng lao động trong tiến hành sản xuất?","options":["A. Công cụ lao động","B. Cơ sở hạ tầng","C. Phương tiện sản xuất","D. Kỹ năng lao động"],"answerLetter":"A","answerText":"A. Công cụ lao động","notes":""},{"id":537,"question":"Hệ thống các quan điểm duy vật biện chứng về xã hội, làm rõ nguồn gốc, động lực và những quy luật chung của sự vận động, phát triển của xã hội loài người là gì?","options":["A. Chủ nghĩa duy vật lịch sử","B. Lịch sử xã hội","C. Quan điểm lịch sử hiện đại","D. Biện chứng của lịch sử"],"answerLetter":"A","answerText":"A. Chủ nghĩa duy vật lịch sử","notes":""},{"id":538,"question":"Đâu là một trong những trường phái triết học ở Trung Quốc thời cổ đại?","options":["A. Thuyết Ngũ hành","B. Thuyết Nguyên tử","C. Phái Vedanta","D. Phái Lokayata"],"answerLetter":"A","answerText":"A. Thuyết Ngũ hành","notes":""},{"id":539,"question":"Sự thay đổi về lượng đạt đến giới hạn nào thì sẽ dẫn đến sự thay đối về chất?","options":["A. Điểm nút","B. Khoảng độ","C. Bước nhày","D. Mâu thuẫn"],"answerLetter":"A","answerText":"A. Điểm nút","notes":""},{"id":540,"question":"Về hình thức cơ bản, loại chủ nghĩa nào khẳng định mọi sự vật, hiện tượng chỉ là phức hợp những cảm giác của cá nhân, của chủ thể?","options":["A. Duy vật siêu hình","B. Duy tâm khách quan","C. Duy tâm chủ quan","D. Duy vật máy móc"],"answerLetter":"C","answerText":"C. Duy tâm chủ quan","notes":""},{"id":541,"question":"\"Muốn xây dựng chủ nghĩa xã hội phải có những con người xã hội chủ nghĩa\", theo Hồ Chí Minh con người xã hội chủ nghĩa là vừ","options":["A. A. Vừa tài vừa trí.","B. Vừa hồng và vừa chuyên.","C. Vừa nhân, lễ nghĩa, trí, tín.","D. Cần, kiệm, liêm, chính, chí công vô tư."],"answerLetter":"B","answerText":"B. Vừa hồng và vừa chuyên.","notes":""},{"id":542,"question":"Theo V.I.Lênin, vật chất có mấy hình thức tồn tại?","options":["A. 1","B. 2","C. 3","D. 4"],"answerLetter":"B","answerText":"B. 2","notes":""},{"id":543,"question":"Chọn câu trả lời sai.Trong một hình thái kinh tế xã hội, lực lượng sản xuất có các vai trò sau đây:","options":["A. Là nền tàng vật chất- kỹ thuật của xã hội","B. Tiêu biểu cho bộ mặt xã hội ở mỗi giai đoạn phát triển","C. Là nhân tố, xét đến củng, quyết định sự hình thành và phát triển của mọi xã hội","D. Thể hiện năng lực chinh phục tự nhiên của con người"],"answerLetter":"B","answerText":"B. Tiêu biểu cho bộ mặt xã hội ở mỗi giai đoạn phát triển","notes":""},{"id":544,"question":"Từ phương diện chính trị và xã hội, nhà nước thực hiện mấy chức năng?","options":["A. 2","B. 3","C. 4","D. 5"],"answerLetter":"A","answerText":"A. 2","notes":""},{"id":545,"question":"Trong xã hội nào, với sự tồn tại của cộng đồng thị tộc, bộ lạc, chưa có nhà nước với tư cách là cơ quan quyền lực của giai cấp?","options":["A. Phong kiến.","B. Cộng sản nguyên thủy.","C. Chiếm hữu nô lệ.","D. Tư bàn chủ nghĩa."],"answerLetter":"B","answerText":"B. Cộng sản nguyên thủy.","notes":""},{"id":546,"question":"Nguyên nhân nào dẫn đến việc cộng đồng nhân loại chưa hình thành rõ nét và vẫn để nhân loại chưa được thực sự đặt ra trong xã hội cộng sản nguyên thủy?","options":["A. Vì trong xã hội này con người mới tách khỏi giới động vật","B. Vì trong xã hội này trình độ phát triển về mọi mặt còn rất lạc hậu","C. Vì trong xã hội này các cộng đông người tạo lập được các mỗi liên hệ rộng rãi","D. Vì trong xã hội này tồn tại chế độ đằng cấp cực đoan, chế độ phân biệt chủng tộc"],"answerLetter":"B","answerText":"B. Vì trong xã hội này trình độ phát triển về mọi mặt còn rất lạc hậu","notes":""},{"id":547,"question":"Theo quan điểm của Các Mác, học thuyết của các ông là một học thuyết có tính chất gì?","options":["A. Tuyệt đối đúng","B. Hoàn thiện","C. Đóng kín","D. Mở"],"answerLetter":"D","answerText":"D. Mở","notes":""},{"id":548,"question":"Lý luận nhận thức ra đời để trả lời câu hỏi nào dưới đây? (Lựa chọn phương án đúng nhất)","options":["A. Con người có phải do thần linh tạo nên hay không.","B. Con người có thể nhận thức được thế giới hay không.","C. Con người là thực thể xã hội - sinh học.","D. Bản nguyên của thế giới là vật chất hay ý thức."],"answerLetter":"B","answerText":"B. Con người có thể nhận thức được thế giới hay không.","notes":""},{"id":549,"question":"Khái niệm nào dùng để chi khoảng giới hạn trong đó sự thay đổi về lượng chưa dẫn đến sự thay đổi căn bản chất của sự vật ấy?","options":["A. Chất","B. Lượng","C. Độ","D. Điểm nút"],"answerLetter":"C","answerText":"C. Độ","notes":""},{"id":550,"question":"Phủ định siêu hình là sự phủ định như thế nào?","options":["A. Làm cho sự vật thay đổi hình thái","B. Làm xuất hiện sự vật mới","C. Tạo ra điều kiện, tiền đề cho sự phát triển","D. Thủ tiêu hoàn toàn sự vật cũ"],"answerLetter":"D","answerText":"D. Thủ tiêu hoàn toàn sự vật cũ","notes":""},{"id":551,"question":"Theo quan điêm của các nhà sảng lập chú nghĩa Mắc, hiện tượng tha hóa của con người là một hiện tượng lịch sử đặc thù, chỉ diễn ra trong những xã hội nào và nguyên nhân nào gây nên hiện tượng tha hóa? (lựa chọn hai đáp án)","options":["A. Xã hội có sự phân chia giai cấp","B. Xã hội có sự phân chia lãnh thổ và nhà nước","C. Chế độ tư hữu vềtư liệu sản xuất không còn","D. Chế độ tư hữu vẽ tư liệu sản xuất"],"answerLetter":"AD","answerText":"A. Xã hội có sự phân chia giai cấp\nD. Chế độ tư hữu vẽ tư liệu sản xuất","notes":""},{"id":552,"question":"Theo quan điễm của chủ nghĩa duy vật biện chững, luận điêm nào sau đây chưa đúng?","options":["A. Một nguyên nhân chi có thể đưa đến một kết quả","B. Nguyên nhân khác nhau cũng có thể đưa đến kết quả như nhau","C. Nguyên nhân giống nhau trong điều kiện giống nhau luôn luôn đưa đến kết quả như nhau","D. Nguyên nhân khác nhau thì đưa ra kết quả không giống nhau"],"answerLetter":"A","answerText":"A. Một nguyên nhân chi có thể đưa đến một kết quả","notes":""},{"id":553,"question":"Phép biện chứng duy vật có hai nguyên lý cơ bản là:","options":["A. Nguyên lý về mỗi liên hệ khách quan và nguyên lý về mỗi liên hệ chủ quan","B. Nguyên lý về mối liên hệ phố biến và nguyên lý vềsự phát triển","C. Nguyên lý về mối liên hệ vật chất và nguyên lý về mỗi liên hệ tinh thần."],"answerLetter":"B","answerText":"B. Nguyên lý về mối liên hệ phố biến và nguyên lý vềsự phát triển","notes":""},{"id":554,"question":"Theo V.I.Lênin, đễ có quan niệm đúng, vũng chắc vẽ sự phát triên của các hình thái kinh tế - xã hội là một quá trình lịch sử - tự nhiên thì cần phải:","options":["A. Quy những mối quan hệ xã hội vào những quan hệ sản xuất","B. Quy những quan hệ sản xuất vào các quan hệ chính tri, pháp luật","C. Quy những quan hệ xã hội vào những quan hệ sản xuất và quy những quan hệ sản xuất vào trình độ phát triển của kỹ thuật, công nghệ hiện thời","D. Quy những quan hệ xã hội vào những quan hệ sản xuất và quy những quan hệ sản xuất vào trình độ phát triển của lực lượng sản xuất"],"answerLetter":"D","answerText":"D. Quy những quan hệ xã hội vào những quan hệ sản xuất và quy những quan hệ sản xuất vào trình độ phát triển của lực lượng sản xuất","notes":""},{"id":555,"question":"Vì sao nói triết học là hạt nhân của thế giối quan? Lựa chon 3 đáp án đúng.","options":["A. Vì bản thân triết học chính là thê giới quan","B. Vì thế giới quan triết học như thế nào sẽ quy định các thế giới quan và các quan niệm khác như thế","C. Vì triết học bao giờ cũng là thành phần quan trọng, đóng vai trò là nhân tố cốt lõi trong các thế giới quan khác","D. Vì triết học luôn luôn ảnh hưỡng và chi phối một cách tự giác đối với các loại thế giới quan"],"answerLetter":"BCD","answerText":"B. Vì thế giới quan triết học như thế nào sẽ quy định các thế giới quan và các quan niệm khác như thế\nC. Vì triết học bao giờ cũng là thành phần quan trọng, đóng vai trò là nhân tố cốt lõi trong các thế giới quan khác\nD. Vì triết học luôn luôn ảnh hưỡng và chi phối một cách tự giác đối với các loại thế giới quan","notes":""},{"id":556,"question":"Đâu là biểu hiện thứ hai cùa hiện tượng tha hóa con người?","options":["A. Quan hệ giữa người với người dẫn mất đạo đức và nhân cách.","B. Quan hệ giữa người với người bị thay thế bởi quan hệ giữa người và vật.","C. Quan hệ giữa người với người bị thay thế bởi tiền với tiền.","D. Quan hệ giữa người với người ngày càng biến chất và vụ lợi."],"answerLetter":"B","answerText":"B. Quan hệ giữa người với người bị thay thế bởi quan hệ giữa người và vật.","notes":""},{"id":557,"question":"Vấn đề cơ bản của triết học trà lời câu hỏi lớn nào?","options":["A. Mặt thứ nhất: giữa vật chất và ý thức cái nào có trước, cái nào có sau, cái nào quyết định cái nào?","B. Mặt thứ hai: con người có khả năng nhận thức được thế giới hay không?","C. Mặt thứ nhất: Khi tim ra nguyên nhãn cuối cùng củasự vận động vật chất là cái quyết định là đúng hay sai?","D. Mặt thứ hai: Con người về cơ bản có thế nhận thức được toàn bộ các sự vật hiện tượng hay không?"],"answerLetter":"AB","answerText":"A. Mặt thứ nhất: giữa vật chất và ý thức cái nào có trước, cái nào có sau, cái nào quyết định cái nào?\nB. Mặt thứ hai: con người có khả năng nhận thức được thế giới hay không?","notes":""},{"id":558,"question":"Theo quan niệm duy vật biện chững vẽ lịch sử thì cơ sở hạ tăng và kiên trức thượng tăng là hai mặt cơ bản của đời sống xã hội. Cơ sở hạ tầng đóng vai trò gì đối với kiến trúc thượng tầng?","options":["A. Chi phối","B. Chủ đạo","C. Quyết định","D. Thống trị"],"answerLetter":"C","answerText":"C. Quyết định","notes":""},{"id":559,"question":"Lý luận hình thái kinh tế - xã hội là cơ sờ khoa học để:","options":["A. Giài thích đầy đủ mọi hiện tượng xã hội","B. Giải thích chính xác và đầy đủ mọi hiện tượng xã hội","C. Xác lập phương pháp luận khoa học chung nhất để giải thích các hiện tượng xã hội","D. Xác lập phương pháp luận chung nhất ở tầm \"duy nhất khoa học\" cho mọi quá trình nghiên cứu"],"answerLetter":"C","answerText":"C. Xác lập phương pháp luận khoa học chung nhất để giải thích các hiện tượng xã hội","notes":""},{"id":560,"question":"Điên vào chỗ trống: \"... là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con ngưởi trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh, và tồn tại không lệ thuộc vào cảm giác\"","options":["A. Vật chất","B. Ý thức","C. Năng lực","D. Thế giới"],"answerLetter":"A","answerText":"A. Vật chất","notes":""},{"id":561,"question":"\"Triết học\" là thuật ngữ được sử dụng lần đầu tiên trong trường phái nào?","options":["A. Socrates","B. Heraclitus","C. Thales","D. C. Mac"],"answerLetter":"A","answerText":"A. Socrates","notes":""},{"id":562,"question":"C.Mác và Ph.Ăngghen là người nước nào?","options":["A. Đức","B. Áo","C. Liên Xô","D. Tiệp Khắc"],"answerLetter":"A","answerText":"A. Đức","notes":""},{"id":563,"question":"Những phát minh nào của khoa học tự nhiên đã ảnh hưởng đến sự phát triển của chủ nghĩa duy vật biện chứng?","options":["A. Định luật bảo toàn và chuyển hóa năng lượng","B. Thuyết tế bào","C. Thuyết tiến hóa của Charles Darwin","D. Lý thuyết về tương đối của Albert Einstein"],"answerLetter":"ABC","answerText":"A. Định luật bảo toàn và chuyển hóa năng lượng\nB. Thuyết tế bào\nC. Thuyết tiến hóa của Charles Darwin","notes":""},{"id":564,"question":"Thế giới quan duy vật biện chứng bao gồm:","options":["A. Tri thức khoa học, niềm tin khoa học và lý tưởng cách mạng","B. Tri thức khoa học, tiềm tin khoa học và hệ giá trị cộng đồng","C. Tri thức khoa học, tình cảm khoa học và lý tưởng khoa học","D. Tri thức khoa học, niềm tin khoa học và lý tưởng khoa học"],"answerLetter":"A","answerText":"A. Tri thức khoa học, niềm tin khoa học và lý tưởng cách mạng","notes":""},{"id":565,"question":"Cái bàn cái ghế là vật chất. Đây là quan niệm của các nhà triết học thời kỳ nào?","options":["A. Duy vật chất phác thời cổ đại","B. Duy tâm chất phác thời cổ đại","C. Duy vật trung đại","D. Duy tâm trung đại"],"answerLetter":"A","answerText":"A. Duy vật chất phác thời cổ đại","notes":""},{"id":566,"question":"Phép biện chứng là phương pháp nghiên cứu, khái quát thế giới thành hệ thống các nguyên lý, quy luật là phép biện chứng gì?","options":["A. Biện chứng chủ quan","B. Biện chứng khách quan","C. Siêu hình học","D. Ý muốn con người"],"answerLetter":"A","answerText":"A. Biện chứng chủ quan","notes":""},{"id":567,"question":"Quan điểm toàn diện đặt ra yêu cầu phải xem xét tất cả các mối liên hệ của sự vật để làm gì?","options":["A. Chống quan điểm siêu hình","B. Chống quan điểm duy tâm","C. Chống quan điểm chủ nghĩa chiết trung và thuyết ngụy biện","D. Đề phòng cho chúng ta khỏi phạm sai lầm và sự cứng nhắc"],"answerLetter":"D","answerText":"D. Đề phòng cho chúng ta khỏi phạm sai lầm và sự cứng nhắc","notes":""},{"id":568,"question":"Theo quan điểm của triết học Mác - Lênin, trong ba mặt của quan hệ sản xuất thì mặt nào quyết định nhất?","options":["A. Quan hệ tổ chức, quản lý","B. Tất cả các quan hệ có vị trí ngang nhau","C. Quan hệ phân phối sản phẩm","D. Quan hệ sở hữu tư liệu sản xuất"],"answerLetter":"D","answerText":"D. Quan hệ sở hữu tư liệu sản xuất","notes":""},{"id":569,"question":"“Phát triển diễn ra theo còn đường tròn khép kín, là sự lặp lại đơn thuần cái cũ”. Luận điểm này thuộc lập trường triết học nào?","options":["A. Quan điểm duy vật biện chứng","B. Quan điểm siêu hình","C. Quan điểm biện chứng duy tâm","D. Quan điểm duy tâm khách quan"],"answerLetter":"B","answerText":"B. Quan điểm siêu hình","notes":""},{"id":570,"question":"Con chó, con mèo có ý thức không?","options":["A. Có. Vì nó được con người dạy","B. Không. Vì nó không được dạy","C. Có. Vì nó được rèn luyện qua quá trình tiếp xúc với con người","D. Không. Vì nó chỉ có bản năng"],"answerLetter":"D","answerText":"D. Không. Vì nó chỉ có bản năng","notes":""},{"id":571,"question":"Theo chủ nghĩa duy vật lịch sử, sự tác động trở lại đối với tồn tại xã hội của các hình thái ý thức xã hội mạnh hay yếu còn phụ thuộc vào yếu tố nào? Chọn 3 đáp án đúng.","options":["A. Những điều kiện lịch sử cụ thể","B. Vai trò lịch sử của giai cấp đại diện cho ngọn cờ tư tưởng đó","C. Trình độ phản ánh và sức lan tỏa của ý thức đối với các nhu cầu khác nhau của sự phát triển xã hội","D. Các quan hệ chính trị vốn là cơ sở hình thành các hình thái ý thức xã hội"],"answerLetter":"ABC","answerText":"A. Những điều kiện lịch sử cụ thể\nB. Vai trò lịch sử của giai cấp đại diện cho ngọn cờ tư tưởng đó\nC. Trình độ phản ánh và sức lan tỏa của ý thức đối với các nhu cầu khác nhau của sự phát triển xã hội","notes":""}],
    mln122: [{"id":1,"question":"Biểu hiện mới của sự phân chia thị trường giữa các liên minh độc quyền đó là(NHUNG HOÀNG)","options":["A. Hình thành các tổ chức đa quốc gia","B. Hình thành các tổ chức độc quyền trong nhà nước tư bản","C. Hình thành xu hướng khu vực hóa","D. Hình thành xu hướng toàn cầu hóa"],"answerLetter":"D","answerText":"D. Hình thành xu hướng toàn cầu hóa","notes":""},{"id":2,"question":"Nghiên cứu về cách mạng công nghiệp lần thứ nhất, C. Mác đã khái quát tính quy luật của cách mạng công nghiệp qua mấy giai đoạn phát triển?(NHUNG HOÀNG)","options":["A. Một giai đoạn","B. Hai giai đoạn","C. Ba giai đoạn","D. Bốn giai đoạn"],"answerLetter":"C","answerText":"C. Ba giai đoạn","notes":"(Kiểu hỏi khác: Khi nghiên cứu về cách mạng công nghiệp lần thứ nhất, C. Mác đã khái quát tính quy luật của các mạng công nghiệp qua các giai đoạn phát triển đó là: A. Hiệp tác đơn giản, lao động thủ công, lao động phức tạp B. Hiệp tác đơn giản, công trường thủ công, công nghiệp hóa C. Hiệp tác đơn giản, sản xuất thủ công, sản xuất hiện đại D. Hiệp tác đơn giản, công trường thủ công, đại công nghiệp)"},{"id":3,"question":"Chọn phương án sai vai trò của cách mạng công nghiệp đối với sự phát triển đó là (NHUNG HOÀNG)","options":["A. Thúc đẩy sự phát triển của lực lượng sản xuất","B. Thúc đẩy các quan hệ sản xuất mới ra đời","C. Thúc đẩy hoàn thiện quan hệ sản xuất","D. Thúc đẩy đổi mới phương thức quản trị phát triển"],"answerLetter":"B","answerText":"B. Thúc đẩy các quan hệ sản xuất mới ra đời","notes":""},{"id":4,"question":"Đâu không phải đặc trưng của chủ nghĩa tư bản?","options":["A. Quyền sở hữu tư liệu sản xuất thuộc về nhà nước","B. Tích lũy tư bản","C. Trao đổi tự nguyện","D. Một hệ thống giá cả và thị trường cạnh tranh"],"answerLetter":"A","answerText":"A. Quyền sở hữu tư liệu sản xuất thuộc về nhà nước","notes":""},{"id":5,"question":"Khi nghiên cứu tái sản xuất tư bản xã hội thì K. Marx chia nền kinh tế ra làm hai khu vực là","options":["A. KVI sản xuất hàng công nghiệp; KVII: sản xuất tư liệu tiêu dùng","B. KVI: sản xuất tư liệu sản xuất; KVII: sản xuất hàng nông nghiệp","C. KVI: sản xuất tư liệu sản xuất; KVII: sản xuất tư liệu tiêu dùng","D. KVI: sản xuất máy móc; KVII: sản xuất tư liệu tiêu dùng"],"answerLetter":"C","answerText":"C. KVI: sản xuất tư liệu sản xuất; KVII: sản xuất tư liệu tiêu dùng","notes":""},{"id":6,"question":"Địa tô chênh lệch II thu được trên(NHUNG HOÀNG)","options":["A. Ruộng đất đã thâm canh","B. Ruộng đất có độ màu mỡ trung bình","C. Ruộng đất có độ màu mỡ tốt"],"answerLetter":"A","answerText":"A. Ruộng đất đã thâm canh","notes":""},{"id":7,"question":"Nội dung công cuộc đại phân công lao động xã hội lần thứ nhất là","options":["A. Đại công nghiệp tách khỏi nông nghiệp","B. Trồng trọt tách khỏi chăn nuôi","C. Chăn nuôi tách khỏi trồng trọt","D. Thủ công nghiệp tách khỏi nông nghiệp"],"answerLetter":"C","answerText":"C. Chăn nuôi tách khỏi trồng trọt","notes":""},{"id":8,"question":"Chênh lệch Địa tô chính I thu được trên","options":["A. Ruộng đất có độ màu mỡ trung bình","B. Ruộng đất tốt","C. Đất ruộng ở vị trí thuận lợi","D. Cả ba"],"answerLetter":"D","answerText":"D. Cả ba","notes":""},{"id":9,"question":"Nội dung công cuộc đại phân công lao động xã hội lần thứ hai là:","options":["A. Đại công nghiệp tác khỏi nộng nghiệp.","B. Trồng trọt tách khỏi chăn nuôi.","C. Ngành thương nghiệp ra đời","D. Thủ công nghiệp tách khỏi nông nghiệp."],"answerLetter":"D","answerText":"D. Thủ công nghiệp tách khỏi nông nghiệp.","notes":""},{"id":10,"question":"Nội dung công cuộc đại phân công lao động xã hội lần thứ ba là:","options":["A. Trồng trọt tách khỏi chăn nuôi.","B. Ngành thương nghiệp ra đời","C. Công nghiệp tách khỏi nông nghiệp","D. Thủ công nghiệp tác khỏi nông nghiệp"],"answerLetter":"B","answerText":"B. Ngành thương nghiệp ra đời","notes":""},{"id":11,"question":"Kinh tế thị trường đã hình thành trong xã hội nào?(NHUNG HOÀNG)","options":["A. Phong kiến","B. Chiếm hữu nô lệ","C. Tư bản chủ nghĩa","D. Xã hội chủ nghĩa"],"answerLetter":"A","answerText":"A. Phong kiến","notes":""},{"id":12,"question":"Các tổ chức độc quyền sử dụng giá cả độc quyền để","options":["A. Củng cố vai trò tổ chức độc quyền","B. Chiếm đoạt giá trị thặng dư của người khác","C. Gây thiệt hại cho các đối thủ cạnh tranh"],"answerLetter":"B","answerText":"B. Chiếm đoạt giá trị thặng dư của người khác","notes":""},{"id":13,"question":"Cơ chế kinh tế của độc quyền nhà nước trong chủ nghĩa tư bản gồm:","options":["A. Cơ chế thị trưởng, độc quyền tư nhân và sự can thiệp của nhà nước","B. Cơ chế thị trường, các nhà tài phiệt và sự điều tiết của nhà nước","C. Cơ chế thị trường và độc quyền tư nhân"],"answerLetter":"A","answerText":"A. Cơ chế thị trưởng, độc quyền tư nhân và sự can thiệp của nhà nước","notes":""},{"id":14,"question":"Trong lịch sử phát triển nền sản xuất xã hội, tiền đề nào là quan trọng cho sự ra đời và phát triển của nền kinh tế thị trường?(NHUNG HOÀNG)","options":["A. Sản xuất","B. Trao đổi hàng hóa","C. Thị trường","D. Sản xuất và trao đổi hàng hóa"],"answerLetter":"D","answerText":"D. Sản xuất và trao đổi hàng hóa","notes":""},{"id":15,"question":"Vì sao trong chủ nghĩa tư bản độc quyền cạnh tranh không bị thủ tiêu?","options":["A. Vì cạnh tranh là quy luật khách quan của kinh tế hàng hoá","B. Vì tổ chức độc quyền cạnh tranh với các công ty ngoài độc quyền","C. Vì các xí nghiệp trong nội bộ tổ chức độc quyền cạnh tranh với nhau"],"answerLetter":"A","answerText":"A. Vì cạnh tranh là quy luật khách quan của kinh tế hàng hoá","notes":""},{"id":16,"question":"Cách mạng công nghiệp lần thứ hai diễn ra trong giai đoạn nào?","options":["A. Từ nửa cuối thế kỷ XIX đến đầu thế kỷ XX","B. Từ nửa đầu thế kỷ XIX đến cuối thế kỷ XIX","C. Từ nửa đầu thế kỷ XX đề nữa cuối thế kỷ XX","D. Từ nửa cuối thế kỷ XIX đến nửa cuối thế kỷ XX"],"answerLetter":"A","answerText":"A. Từ nửa cuối thế kỷ XIX đến đầu thế kỷ XX","notes":"(Kiểu hỏi khác: Cách mạng công nghiệp lần thứ hai diễn ra trong thời gian nào? A. Từ giữa thế kỷ XV đến giữa thế kỷ XIX B. Từ giữa thế kỷ XVI đến giữa thế kỷ XVII C. Từ giữa thế kỷ XVIII đến giữa thế kỷ XIX D. Từ giữa thế kỷ XIX đến giữa thế kỷ XX)"},{"id":17,"question":"Những đóng góp to lớn của kinh tế chính trị cổ điển Anh vào lý luận kinh tế chính trị của nhân loại đó là(NHUNG HOÀNG)","options":["A. Rút ra kết luận giá trị là do hao phí lao động tạo ra","B. Rút ra được bản chất bóc lột của chủ nghĩa tư bản","C. Khái quát đúng mục đích của chủ nghĩa tư bản là lợi nhuận","D. Luận giải về nhiều phạm trù kinh tế như giá trị, sản phẩm rồng, tư bản, tiền lương"],"answerLetter":"A","answerText":"A. Rút ra kết luận giá trị là do hao phí lao động tạo ra","notes":""},{"id":18,"question":"Công nghiệp hoá, hiện đại hoá đất nước phải bảo đảm","options":["A. Xây dựng nền kinh tế khép kín và hướng nội","B. Xây dựng nền kinh tế độc lập tự chủ","C. Xây dựng nền kinh tế phải dựa vào sự giúp đỡ và lệ thuộc vào các nước tư bản","D. Xây dựng nền kinh tế mở nhưng chỉ giao lưu hợp tác với các nước xã hội chủ nghĩa"],"answerLetter":"B","answerText":"B. Xây dựng nền kinh tế độc lập tự chủ","notes":""},{"id":19,"question":"Việt Nam gia nhập tổ chức ASEAN trong khu vực khi nào?","options":["A. 1995","B. 1996","C. 1993","D. 1997"],"answerLetter":"A","answerText":"A. 1995","notes":""},{"id":20,"question":"Để thực hiện hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam cần hoàn thành mấy nhiệm vụ chủ yếu?","options":["A. Ba nhiệm vụ","B. Năm nhiệm vụ","C. Sáu nhiệm vụ","D. Chín nhiệm vụ"],"answerLetter":"B","answerText":"B. Năm nhiệm vụ","notes":""},{"id":21,"question":"Quá trình công nghiệp hóa của các nước tư bản cổ điển diễn ra trong thời gian khoảng bao nhiêu năm?(NHUNG HOÀNG)","options":["A. Từ 60 - 80 năm","B. Từ 50 - 70 năm","C. Từ 60 - 90 năm","D. Từ 50 - 80 năm"],"answerLetter":"A","answerText":"A. Từ 60 - 80 năm","notes":""},{"id":22,"question":"Kinh tế chính trị Mác - Lênin có những chức nào?","options":["A. Chức năng nhận thức, chức năng thực tiễn, chức năng tư tưởng, chức năng khoa học","B. Chức năng nhận thức, chức năng thực tiễn, chức năng khoa học, chức năng phương pháp luận","C. Chức năng thực tiễn, chức năng tư tưởng, chức năng dự báo, chức năng phương pháp luận","D. Chức năng nhận thức, chức năng thực tiễn, chức năng tư tưởng, chức năng phương pháp luận"],"answerLetter":"D","answerText":"D. Chức năng nhận thức, chức năng thực tiễn, chức năng tư tưởng, chức năng phương pháp luận","notes":""},{"id":23,"question":"Độc quyền nhà nước trong chủ nghĩa tư bản, sở hữu nhà nước thực hiện chức năng nào?(NHUNG HOÀNG)","options":["A. Mở rộng sản xuất tư bản chủ nghĩa","B. Tạo điều kiện cho việc di chuyển tư bản của các tổ chức độc quyền vào các ngành sản xuất kinh doanh khác nhau","C. Làm chỗ dựa cho sự điều tiết kinh tế nhà nước","D. Tất cả phương án trên"],"answerLetter":"D","answerText":"D. Tất cả phương án trên","notes":""},{"id":24,"question":"Mệnh đề nào sau đây là ý không đúng về lao động phức tạp?","options":["A. Lao động phức tạp là lao động trí tuệ của người lao động có trình độ cao","B. Lao động phức tạp là lao động trải qua đào tạo, huấn luyện","C. Trong cùng một thời gian lao động, lao động phức tạp tạo ra nhiều giá trị hơn lao động giản đơn."],"answerLetter":"A","answerText":"A. Lao động phức tạp là lao động trí tuệ của người lao động có trình độ cao","notes":""},{"id":25,"question":"Ai là người đề xuất ra ba loại thương nghiệp (trao đổi tự nhiên, trao đổi tiền tệ, trao đổi thông qua mục đích làm giàu) và hai loại kinh doanh (kinh tế, sản xuất của cải)?","options":["A. Aristoteles","B. Platon","C. Xenophon","D. Karl Marx"],"answerLetter":"A","answerText":"A. Aristoteles","notes":""},{"id":26,"question":"Kinh tế thị trường được hiểu là","options":["A. Do chủ nghĩa tư bản sinh ra","B. Có cùng bản chất với kinh tế hàng hóa","C. Tồn tại chủ quan trong thời kỳ quá độ lên chủ nghĩa xã hội","D. Là sản phẩm riêng của chủ nghĩa tư bản"],"answerLetter":"B","answerText":"B. Có cùng bản chất với kinh tế hàng hóa","notes":"(Kiểu hỏi khác: Về vị trí lịch sử, kinh tế thị trường có đặc điểm gì?)"},{"id":27,"question":"Điều kiện để ra đời và tồn tại của sản xuất hàng hóa là","options":["A. Phân công lao động xã hội và sự tách biệt về kinh tế giữa các chủ thể sản xuất","B. Phân công lao động trong các gia đình xuất hiện","C. Chế độ tư hữu về tư liệu sản xuất","D. Nhu cầu trao đổi trong xã hội tăng lên"],"answerLetter":"A","answerText":"A. Phân công lao động xã hội và sự tách biệt về kinh tế giữa các chủ thể sản xuất","notes":""},{"id":28,"question":"Con đường công nghiệp hóa của Liên Xô thường ưu tiên lĩnh vực nào?","options":["A. Công nghiệp nặng","B. Công nghiệp nhẹ","C. Công nghiệp khai khoáng","D. Công nghiệp chế tạo"],"answerLetter":"A","answerText":"A. Công nghiệp nặng","notes":""},{"id":29,"question":"Sự tách biệt về mặt kinh tế giữa các chủ thể sản xuất xuất hiện dựa trên cơ sở nào?","options":["A. Sự tách biệt về tổ chức sản xuất","B. Sự tách biệt về phân phối sản phẩm","C. Sự tách biệt về quyền sở hữu","D. Sự tách biệt về vai trò sản xuất"],"answerLetter":"C","answerText":"C. Sự tách biệt về quyền sở hữu","notes":""},{"id":30,"question":"V - Tư bản khả biến là:","options":["A. Bộ phận trực tiếp để tạo ra giá trị sử dụng","B. Bộ phận trực tiếp để tạo ra giá trị thặng dư","C. Bộ phận trực tiếp để tạo ra sản phẩm thặng dư","D. Bộ phận gián tiếp để tạo ra giá trị thặng dư"],"answerLetter":"B","answerText":"B. Bộ phận trực tiếp để tạo ra giá trị thặng dư","notes":""},{"id":31,"question":"Bản chất khủng hoảng thửa trong nền kinh tế là.","options":["A. Khủng hoảng sản xuất \"thừa\" so với sức mua có hạn của xã hội.","B. Khủng hoảng sản xuất \"thừa\" so với nhu cầu xã hội.","C. Khủng hoảng sản xuất \"thiếu hụt\" so với sức mua."],"answerLetter":"A","answerText":"A. Khủng hoảng sản xuất \"thừa\" so với sức mua có hạn của xã hội.","notes":""},{"id":32,"question":"Có mấy nguyên nhân chính dẫn đến sự hình thành độc quyền nhà nước trong chủ nghĩa tư bản?","options":["A. Ba nguyên nhân","B. Bốn nguyên nhân","C. Năm nguyên nhân","D. Sáu nguyên nhân"],"answerLetter":"B","answerText":"B. Bốn nguyên nhân","notes":"(1. Tích tụ và tập trung tư bản 2. Phân công lao động xã hội 3. Mâu thuẫn giai cấp 4. Xu hướng quốc tế hóa và cạnh tranh quốc tế)"},{"id":33,"question":"Tiền công thực tế là(NHUNG HOÀNG)","options":["A. Tiền công được biểu hiện bằng số lượng hàng hóa tiêu dùng và dịch vụ mà công nhân mua được bằng tiền công danh nghĩa của mình","B. Tiền công được biểu hiện bằng số lượng hàng hóa tiêu dùng và dịch vụ mà công nhân mua được bằng tiền công thực tế của mình","C. Tiền công được biểu hiện bằng số tư liệu sản xuất và tiêu dùng và dịch vụ mà công nhân mua được bằng tiền công thực tế của mình"],"answerLetter":"A","answerText":"A. Tiền công được biểu hiện bằng số lượng hàng hóa tiêu dùng và dịch vụ mà công nhân mua được bằng tiền công danh nghĩa của mình","notes":""},{"id":34,"question":"Biểu hiện mới của tích tụ và tập trung tư bản trong giai đoạn hiện nay là","options":["A. Sự xuất hiện của các công ty độc quyền xuyên quốc gia","B. Sự bành trướng lãnh thổ","C. Sự tranh giành, xung đột lợi ích về kinh tế","D. Sự xung đột về chính trị"],"answerLetter":"A","answerText":"A. Sự xuất hiện của các công ty độc quyền xuyên quốc gia","notes":""},{"id":35,"question":"Những biểu hiện của độc quyền nhà nước trong chủ nghĩa tư bản là:","options":["A. Sự kết hợp nhân sự giữa tổ chức độc quyền cùng với nhà nước; sự hình thành, phát triển của sở hữu nhà nước","B. Sự kết hợp về nhân sự giữa tổ chức độc quyền cùng với nhà nước; sự hình thành, phát triển của sở hữu nhà nước, sự điều tiết kinh tế của nhà nước tư sản.","C. Sự kết hợp về nhân sự giữa tổ chức độc quyền cùng với nhà nước; sự hình thành, phát triển của sở hữu nhà nước, sự điều tiết kinh tế đối ngoại của nhà nước tư sản.","D. Sự kết hợp về nhân sự giữa tổ chức độc quyền với nhà nước; sự điều tiết kinh tế của nhà nước tư sản"],"answerLetter":"B","answerText":"B. Sự kết hợp về nhân sự giữa tổ chức độc quyền cùng với nhà nước; sự hình thành, phát triển của sở hữu nhà nước, sự điều tiết kinh tế của nhà nước tư sản.","notes":""},{"id":36,"question":"Nội dung về kinh tế chính trị của C. Mác và Ph. Ăngghen được trình bày nhiều nhất trong tác phẩm nào?","options":["A. Tư Bản","B. Hệ tư tưởng Đức","C. Tuyên ngôn của Đảng Cộng sản","D. Biện chứng của tự nhiên"],"answerLetter":"A","answerText":"A. Tư Bản","notes":""},{"id":37,"question":"Sản xuất hàng hóa ra đời dựa trên(NHUNG HOÀNG)","options":["A. Một điều kiện","B. Hai điều kiện","C. Ba điều kiện","D. Bốn điều kiện"],"answerLetter":"B","answerText":"B. Hai điều kiện","notes":""},{"id":38,"question":"Cách mạng công nghiệp lần thứ tư sẽ làm mất đi lợi thế của các nước đang phát triển về(NHUNG HOÀNG)","options":["A. Tài nguyên thiên nhiên, công nhân giá rẻ","B. Khoáng sản, sức lao động","C. Khoa học công nghệ, nhân công chất lượng cao"],"answerLetter":"A","answerText":"A. Tài nguyên thiên nhiên, công nhân giá rẻ","notes":""},{"id":39,"question":"Đại hội nào đã xác định kinh tế thị trường định hướng xã hội chủ nghĩa là \"một kiểu tổ chức kinh tế vừa tuân theo quy luật của kinh tế thị trường vừa dựa trên cơ sở và chịu sự dẫn dắt chi phối bởi các nguyên tắc và bản chất của chủ nghĩa xã hội?(NHUNG HOÀNG)","options":["A. Đại hội Đảng toàn quốc lần thứ VI","B. Đại hội Đảng toàn quốc lần thứ VII","C. Đại hội Đảng toàn quốc lần thứ VIII","D. Đại hội Đảng toàn quốc lần thứ IX"],"answerLetter":"D","answerText":"D. Đại hội Đảng toàn quốc lần thứ IX","notes":""},{"id":40,"question":"Lý thuyết bàn tay vô hình của Adam Smith được hiểu là: (chọn 3 phương án đúng)(NHUNG HOÀNG)","options":["A. Người bán và người mua, phân bố nguồn lực kinh tế đạt được hiệu quả xã hội lớn nhất mà không cần sự can thiệp của chính phủ","B. Mô tả khả năng của cơ chế thị trường trong việc điều chỉnh cung cầu trên thị trường.","C. Các cá nhân tham gia muốn tối đa hóa lợi nhuận cho mình","D. Mọi người đều bị bàn tay vô hình dẫn tới kết quả làm lợi cho chính mình"],"answerLetter":"ABC","answerText":"A. Người bán và người mua, phân bố nguồn lực kinh tế đạt được hiệu quả xã hội lớn nhất mà không cần sự can thiệp của chính phủ\nB. Mô tả khả năng của cơ chế thị trường trong việc điều chỉnh cung cầu trên thị trường.\nC. Các cá nhân tham gia muốn tối đa hóa lợi nhuận cho mình","notes":""},{"id":41,"question":"Chọn ý đúng về tăng cường độ lao động. Khi cường độ lao động tăng lên thì(NHUNG HOÀNG)","options":["A. Số lượng hàng hoá làm ra trong một đơn vị thời gian không đổi","B. Số lượng lao động hao phí trong thời gian đó không thay đổi","C. Giá trị 1 đơn vị hàng hoá giảm đi","D. Tổng số lượng hàng hóa làm ra của một người tăng lên"],"answerLetter":"D","answerText":"D. Tổng số lượng hàng hóa làm ra của một người tăng lên","notes":""},{"id":42,"question":"Trên giác độ kinh tế chính trị, lao động trừu tượng là","options":["A. Là phạm trù của mọi nền kinh tế hàng hoá","B. Là phạm trù riêng của kinh tế thị trường","C. Là phạm trù chung của mọi nền kinh tế"],"answerLetter":"A","answerText":"A. Là phạm trù của mọi nền kinh tế hàng hoá","notes":""},{"id":43,"question":"Xét về bản chất, thì lợi ích kinh tế được hiểu là:(NHUNG HOÀNG)","options":["A. Quan hệ kinh tế xã hội","B. Quan hệ xã hội, mang tính lịch sử","C. Quan hệ sản xuất","D. Quan hệ chính trị mang tính lợi ích"],"answerLetter":"C","answerText":"C. Quan hệ sản xuất","notes":"(Kiểu hỏi khác: Xét về bản chất, lợi ích kinh tế được hiều như thế nào?)"},{"id":44,"question":"Cách mạng công nghiệp lần thứ nhất diễn ra trong thời gian nào?","options":["A. Từ giữa thế kỷ XV đến giữa thế kỷ XIX","B. Từ giữa thế kỷ XVI đến giữa thế kỷ XVII","C. Từ giữa thế kỷ XVIII đến giữa thế kỷ XIX","D. Từ giữa thế kỷ XIX đến giữa thế kỷ XX"],"answerLetter":"C","answerText":"C. Từ giữa thế kỷ XVIII đến giữa thế kỷ XIX","notes":""},{"id":45,"question":"Yếu tố nào quyết định đến sự hình thành của cách mạng công nghiệp.","options":["A. Sự phát triển vượt bậc của quan hệ sản xuất","B. Phương thức sản xuất mới ra đời","C. Sự phát triển nhảy vọt về trình độ của tư liệu lao động","D. Các phát minh sáng chế của các nhà khoa học trên mọi lĩnh vực"],"answerLetter":"C","answerText":"C. Sự phát triển nhảy vọt về trình độ của tư liệu lao động","notes":""},{"id":46,"question":"Nguồn vốn để công nghiệp hóa ở các nước tư bản cổ điển lấy từ đâu?","options":["A. Cướp bóc thuộc địa","B. Khai thác lao động làm thuê","C. Làm phá sản những người sản xuất nhỏ trong nông nghiệp","D. Tất cả phương án trên"],"answerLetter":"D","answerText":"D. Tất cả phương án trên","notes":"(Kiểu hỏi khác: Nguồn gốc nào không đúng với nguồn vốn công nghiệp hóa ở các nước tư bàn cổ điển? A. Cướp bóc thuộc địa B. Khai thác lao động làm thuê C. Làm phá sản những người sản xuất nhỏ trong nông nghiệp D. Đi vay nhà nước)"},{"id":47,"question":"Sức lao động trở thành hàng hoá một cách phổ biến từ khi nào?","options":["A. Từ khi có chủ nghĩa tư bản","B. Từ khi có sản xuất hàng hoá","C. Từ khi có kinh tế thị trường","D. Từ khi lao động ra đời"],"answerLetter":"A","answerText":"A. Từ khi có chủ nghĩa tư bản","notes":""},{"id":48,"question":"Khi lạm phát phi mã xảy ra, hình thức sử dụng tiền nào có lợi nhất?","options":["A. Mua hàng hoá hoặc vàng cất giữ","B. Gửi ngân hàng","C. Đầu tư vào sản xuất kinh doanh","D. Mua USD"],"answerLetter":"A","answerText":"A. Mua hàng hoá hoặc vàng cất giữ","notes":""},{"id":49,"question":"Sự tuần hoàn của tư bản, nếu xét nó với tư cách là một quá trình định kỳ đổi mới và thường xuyên lặp đi lặp lại được gọi là(NHUNG HOÀNG)","options":["A. Chu chuyển tư bản","B. Lưu thông tự bản","C. Vận động tư bản","D. Tái sản xuất tư bản"],"answerLetter":"A","answerText":"A. Chu chuyển tư bản","notes":""},{"id":50,"question":"Phương pháp nghiên cứu kinh tế chính trị Mác - Lênin phù hợp nhất đó là:","options":["A. Trừu tượng hóa khoa học","B. Phân tích và tổng hợp","C. Quy nạp diễn dịch","D. Khảo sát, tổng kết thực tiễn"],"answerLetter":"A","answerText":"A. Trừu tượng hóa khoa học","notes":""},{"id":51,"question":"\"Tư bản tài chính là kết quả của sự hợp nhất giữa tư bản ngân hàng của một số ít ngân hàng độc quyền lớn nhất, với tư bản của những liên minh độc quyền các nhà công nghiệp.\" Câu nói trên của ai?","options":["A. C. Mác","B. Ph. Ăngghen","C. V. I Lênin","D. Hồ Chí Minh"],"answerLetter":"C","answerText":"C. V. I Lênin","notes":""},{"id":52,"question":"Tăng năng suất lao động sẽ dẫn đến(NHUNG HOÀNG)","options":["A. Giá trị một đơn vị hàng hóa tăng lên","B. Giá trị một đơn vị hàng hóa không đổi","C. Giá trị một đơn vị hàng hóa giảm đi","D. Giá trị một đơn vị sản phẩm giảm đi"],"answerLetter":"C","answerText":"C. Giá trị một đơn vị hàng hóa giảm đi","notes":""},{"id":53,"question":"Khi đồng thời tăng năng suất lao động và cường độ lao động lên 2 lần thì ý nào dưới đây là đúng?(NHUNG HOÀNG)","options":["A. Giá trị 1 hàng hoá giảm 2 lần, tổng số giá trị hàng hoá tăng 2 lần","B. Tổng số hàng hoả tăng lên 2 lần, giá trị 1 hàng hoá giảm 2 lần","C. Tổng số hàng hoá tăng lên 4 lần, tổng số giá trị hàng hoá tăng lên 4 lần"],"answerLetter":"A","answerText":"A. Giá trị 1 hàng hoá giảm 2 lần, tổng số giá trị hàng hoá tăng 2 lần","notes":""},{"id":54,"question":"Hãy chọn ý đúng khi nói về quan hệ giữa giá trị và giá cả?(NHUNG HOÀNG)","options":["A. Giá trị là cơ sở của giá cả, là yếu tố quyết định giá cả, giá cả là hình thức biểu hiện bằng tiền của giá trị","B. Giá cả thị trường còn chịu ảnh hưởng của cung - cầu, giá trị của tiền","C. Các phương án trả lời đều đúng"],"answerLetter":"C","answerText":"C. Các phương án trả lời đều đúng","notes":""},{"id":55,"question":"Quan điểm cho rằng lợi nhuận phần thu nhập thặng dư tính bằng hiệu quả giữa giá trị tổng doanh thu trừ đi tổng chi phí và là phần thưởng cho việc gánh chịu rủi ro và cho sự đổi mới là của ai?(NHUNG HOÀNG)","options":["A. Paul A.Samuelson","B. David Begg","C. Stanley Fischer","D. Rudiger Dornbusch"],"answerLetter":"A","answerText":"A. Paul A.Samuelson","notes":""},{"id":56,"question":"Kinh tế thị trường đã có mầm mống từ trong xã hội nào?","options":["A. Phong kiến","B. Chiếm hữu nô lệ","C. Tư bản chủ nghĩa","D. Xã hội chủ nghĩa"],"answerLetter":"B","answerText":"B. Chiếm hữu nô lệ","notes":""},{"id":57,"question":"Điển vào chỗ trống: Theo Karl Marx, kinh tế chính trị học tư sản cổ điển Anh bắt đầu từ... và kết thúc ở...","options":["A. William Petty... David Ricardo","B. William Petty...Adam Smith","C. Adam Smith... David Ricardo","D. Adam Smith... Thomas Malthus"],"answerLetter":"A","answerText":"A. William Petty... David Ricardo","notes":""},{"id":58,"question":"Thể chế được phân loại theo:","options":["A. Cách tiếp cận cấu trúc hệ thống, phương thức phát huy vai trò của chủ thể đối với quá trình phát triển, theo cấu thành các lĩnh vực cốt lõi của xã hội và theo cấu trúc các tổ chức tham gia vào xã hội","B. Cách tiếp cận cấu trúc hệ thống phương thức phát huy vai trò của doanh nghiệp với quá trình phát triển, theo cấu thành các lĩnh vực cốt lõi của xã hội và theo cấu trúc các tổ chức tham gia vào xã hội","C. Cách tiếp cận sự phân chia bên trong hay bên ngoài, phương thức phát huy vai trò của doanh nghiệp với quá trình phát triển, theo cấu thành các lĩnh vực cốt lõi của xã hội và theo cấu trúc các tổ chức tham gia vào xã hội"],"answerLetter":"A","answerText":"A. Cách tiếp cận cấu trúc hệ thống, phương thức phát huy vai trò của chủ thể đối với quá trình phát triển, theo cấu thành các lĩnh vực cốt lõi của xã hội và theo cấu trúc các tổ chức tham gia vào xã hội","notes":""},{"id":59,"question":"Tư tưởng kinh tế đầu tiên của giai cấp tư sản trong giai đoạn phương thức sản xuất phong kiến tan rã và chủ nghĩa tư bản ra đời đó là","options":["A. Chủ nghĩa trọng thương","B. Chủ nghĩa trọng nông","C. Kinh tế chính trị cổ điển Anh","D. Kinh tế chính trị của Karl Marx"],"answerLetter":"A","answerText":"A. Chủ nghĩa trọng thương","notes":""},{"id":60,"question":"Lao động sản xuất có đặc trưng cơ bản là:","options":["A. Hoạt động cơ bản nhất, là phẩm chất đặc biệt của con người","B. Là hoạt động có mục đích, có ý thức của con người","C. Là sự tiêu dùng sức lao động trong hiện thực","D. Các phương án trả lời đều đúng"],"answerLetter":"D","answerText":"D. Các phương án trả lời đều đúng","notes":"(Hoạt động nào của con người được coi là cơ bản nhất và là cơ sở của đời sống xã hội? A. Hoạt động chính trị. B. Hoạt động sản xuất của cải vật chất. C. Hoạt động nghệ thuật, thể thao. D. Hoạt động thực nghiệm khoa học.)"},{"id":61,"question":"Cách mạng công nghiệp lần thứ hai đã tạo ra những tiến bộ vượt bậc trong lĩnh vực nào?","options":["A. Giao thông vận tải và thông tin liên lạc","B. Kết cấu hạ tầng và viễn thông","C. Năng lượng điện và năng lượng hóa thạch","D. Tất cả phương án trên"],"answerLetter":"D","answerText":"D. Tất cả phương án trên","notes":""},{"id":62,"question":"Khi nào xuất hiện hình thái tiền tệ?(NHUNG HOÀNG)","options":["A. Khi sản xuất và trao đổi đã phát triển","B. Khi vật ngang giá chung được cố định ở vàng, bạc","C. Khi không còn quan hệ trao đổi trực tiếp, có một thứ hàng làm trung gian trong trao đổi","D. Khi nhu cầu trao đổi vượt quá phạm vi quốc gia"],"answerLetter":"B","answerText":"B. Khi vật ngang giá chung được cố định ở vàng, bạc","notes":""},{"id":63,"question":"Hoàn thiện hệ thống luật pháp, cơ chế, chính sách cho hoạt động và phát triển lành mạnh của thị trường chứng khoán, tăng tính minh bạch chống các giao dịch phi pháp, các hành vi rửa tiền là thuộc về","options":["A. Thống nhất nhận thức về nền kinh tế thị trường định hướng XHCN","B. Hoàn thiện thể chế về sở hữu và các thành phần kinh tế, loại hình doanh nghiệp và các tổ chức sản xuất kinh doanh","C. Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trường và phát triển đồng bộ các loại thị trường","D. Hoàn thiện thể chế và vai trò lãnh đạo của Đảng"],"answerLetter":"C","answerText":"C. Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trường và phát triển đồng bộ các loại thị trường","notes":""},{"id":64,"question":"Những đặc điểm kinh tế cơ bản nhất của chủ nghĩa tư bản độc quyền bao gồm:(NHUNG HOÀNG)","options":["A. Tập trung sản xuất cùng với các tổ chức độc quyền; tư bản tài chính; xuất khẩu tư bản; sự phân chia thế giới về lãnh thổ giữa các nước đế quốc","B. Tập trung sản xuất cùng với các tổ chức độc quyền, tư bản tài chính; sự phân chia thị trường thế giới giữa các tổ chức độc quyền, sự phân chia thế giới về lãnh thổ giữa các nước đế quốc","C. Tập trung sản xuất cùng với các tổ chức độc quyền; xuất khẩu tư bản; sự phân chia thị trường thế giới giữa các tổ chức độc quyền; sự phân chia thế giới về lãnh thổ giữa các nước đế quốc","D. Tập trung sản xuất cùng với các tổ chức độc quyền; tư bản tài chính; xuất khẩu tư bản; sự phân chia thị trường thế giới giữa các tổ chức độc quyền; sự phân chia thế giới về lãnh thổ giữa các nước đế quốc"],"answerLetter":"D","answerText":"D. Tập trung sản xuất cùng với các tổ chức độc quyền; tư bản tài chính; xuất khẩu tư bản; sự phân chia thị trường thế giới giữa các tổ chức độc quyền; sự phân chia thế giới về lãnh thổ giữa các nước đế quốc","notes":""},{"id":65,"question":"Phạm trù lợi nhuận chẳng qua chỉ là một hình thái thần bí hóa của giá trị thặng dư, nguyên nhân của việc này xuất phát từ: (chọn nhiều đáp án)","options":["A. Sự hình thành chi phí sản xuất tư bản chủ nghĩa đã xóa nhòa sự khác nhau giữa c (tư bản bất biến) và v (tư bản khả biến)","B. Do chi phí sản xuất tư bản chủ nghĩa luôn nhỏ hơn chi phí sản xuất thực tế","C. Sự hình thành của giá trị thặng dư và chi phí sản xuất tư bản chủ nghĩa","D. Chi phí sản xuất tư bản chủ nghĩa luôn luôn nhỏ hơn giá của của hàng hóa bán ra"],"answerLetter":"AC","answerText":"A. Sự hình thành chi phí sản xuất tư bản chủ nghĩa đã xóa nhòa sự khác nhau giữa c (tư bản bất biến) và v (tư bản khả biến)\nC. Sự hình thành của giá trị thặng dư và chi phí sản xuất tư bản chủ nghĩa","notes":""},{"id":66,"question":"Các luận điểm dưới đây, luận điểm nào sai?(NHUNG HOÀNG)","options":["A. Bóc lột sản phẩm thặng dư chỉ có ở chủ nghĩa tư bản","B. Các phương thức sản xuất trước chủ nghĩa tư bản bóc lột sản phẩm thặng dư trực tiếp","C. Sản xuất giá trị thặng dư tuyệt đối là hình thái chung nhất của sản xuất giá trị thặng dư"],"answerLetter":"A","answerText":"A. Bóc lột sản phẩm thặng dư chỉ có ở chủ nghĩa tư bản","notes":""},{"id":67,"question":"Xây dựng nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam nhằm thực hiện mục tiêu gì?","options":["A. Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","B. Dân giàu, nước mạnh, công bằng, dân chủ, văn minh","C. Dân giàu, nước mạnh, văn minh, công bằng, dân chủ","D. Dân giàu, nước mạnh, dân chủ, văn minh, công bằng"],"answerLetter":"A","answerText":"A. Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","notes":""},{"id":68,"question":"Hội nhập kinh tế quốc tế, mở rộng kinh tế đối ngoại nhằm:","options":["A. Thu hút vốn đầu tư nước ngoài, thu hút công nghệ hiện đại","B. Học hỏi kinh nghiệm quản lý tiên tiến của thế giới","C. Khai thác thị trường thế giới để tiêu thụ các sản phẩm mà nước ta có nhiều lợi thế và khả năng cạnh tranh cao","D. Tất cả các phương án trên"],"answerLetter":"D","answerText":"D. Tất cả các phương án trên","notes":"(Kiểu hỏi khác: Đâu không phải là mục đích của hội nhập kinh tế quốc tế? -> Đầu tư tư bản trực tiếp thu lợi nhuận ở nước ngoài)"},{"id":69,"question":"Quan điểm nào dưới đây không phải là đặc trưng chủ yếu của quá trình công nghiệp hóa, hiện đại hóa ở Việt Nam?","options":["A. Công nghiệp hóa, hiện đại hóa gắn liền với phát triển công nghiệp nặng","B. Công nghiệp hóa, hiện đại hóa trong điều kiện nền kinh tế thị trường, định hướng xã hội chủ nghĩa","C. Công nghiệp hóa, hiện đại hóa trong bối cảnh toàn cầu hóa kinh tế quốc tế","D. Công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa"],"answerLetter":"A","answerText":"A. Công nghiệp hóa, hiện đại hóa gắn liền với phát triển công nghiệp nặng","notes":""},{"id":70,"question":"Hệ thống lý luận kinh tế chính trị nào bước đầu nghiên cứu về nền sản xuất tư bản chủ nghĩa?(NHUNG HOÀNG)","options":["A. Chủ nghĩa trọng thương","B. Chủ nghĩa trọng nông","C. Chủ nghĩa tư bản","D. Chủ nghĩa xã hội"],"answerLetter":"A","answerText":"A. Chủ nghĩa trọng thương","notes":"(Kiểu hỏi khác: Hệ thống lý luận kinh tế chính trị đầu tiên nghiên cứu về sản xuất tư bản chủ nghĩa là)"},{"id":71,"question":"Vì sao ta cần phải hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa?","options":["A. Hệ thống thể chế chưa đầy đủ","B. Hệ thống thể chế tạm thời hiệu quả","C. Hệ thống thể chế có nhiều yếu tố thị trường và các loại thị trường","D. Thể chế kinh tế thị trường định hướng xã hội chủ nghĩa đồng bộ"],"answerLetter":"C","answerText":"C. Hệ thống thể chế có nhiều yếu tố thị trường và các loại thị trường","notes":""},{"id":72,"question":"Nguyên nhân nào đã dẫn đến sự sụp đổ của Liên Xô và hệ thống xã hội chủ nghĩa ở Đông Âu?","options":["A. Cơ chế kế hoạch hoá tập trung mệnh lệnh","B. Sự tiến bộ kỹ thuật không đồng bộ","C. Sản xuất không đi đối với tiêu dùng","D. Công nghiệp hoá nhanh"],"answerLetter":"A","answerText":"A. Cơ chế kế hoạch hoá tập trung mệnh lệnh","notes":"(Kiểu hỏi khác: Nguyên nhân nào quyết định nhất dẫn đến sự sụp đổ của Liên Xô và hệ thống XHCN ở Đông Âu?)"},{"id":73,"question":"Quan điểm về hoàn thiện thể chế thị trường định hướng xã hội chủ nghĩa là","options":["A. Đảm bảo tính đồng bộ giữa các bộ phận cấu thành của các thể chế kinh tế, giữa các yếu tố thị trường và các loại thị trường","B. Chủ động, tích cực các vấn đề lý luận và thực tiễn, đồng thời nâng cao năng lực lãnh đạo của Đảng, hiệu lực quản lý của Nhà nước","C. Kế thừa có chọn lọc thành tựu phát triển kinh tế thị trường của nhân loại và kinh nghiệm tổng kết từ thực tiễn đổi mới ở nước ta, nhận thức đầy đủ, tôn trọng và vận dụng đúng đắn các quy luật khách quan của kinh tế thị trường","D. Tất cả phương án trên"],"answerLetter":"D","answerText":"D. Tất cả phương án trên","notes":""},{"id":74,"question":"Lao động sản xuất có vai trò gì đối với con người?(NHUNG HOÀNG)","options":["A. Tạo ra của cải vật chất để nuôi sống con người","B. Phát triển, hoàn thiện con người cả về thể lực và trí lực","C. Giúp con người tích luỹ kinh nghiệm, chế tạo ra công cụ sản xuất ngày càng tinh vi","D. Các phương án trả lời đều đúng"],"answerLetter":"D","answerText":"D. Các phương án trả lời đều đúng","notes":""},{"id":75,"question":"Tính hai mặt của lao động sản xuất hàng hóa là(NHUNG HOÀNG)","options":["A. Lao động tư nhân, lao động xã hội","B. Lao động giản đơn, lao động phức tạp","C. Lao động cụ thể, lao động trừu tượng"],"answerLetter":"C","answerText":"C. Lao động cụ thể, lao động trừu tượng","notes":""},{"id":76,"question":"Kinh tế chính trị cổ điển Anh được hình thành và phát triển trong thời kỳ nào?(NHUNG HOÀNG)","options":["A. Từ cổ đại đến thế kỷ XVIII","B. Từ nửa cuối thế kỷ XVII đến nửa đầu thế kỷ XVIII","C. Từ cuối thế kỷ XVIII đến nửa đầu thế kỷ XIX","D. Từ nửa đầu thế kỷ XIX"],"answerLetter":"C","answerText":"C. Từ cuối thế kỷ XVIII đến nửa đầu thế kỷ XIX","notes":""},{"id":77,"question":"Giá cả ruộng đất phụ thuộc các nhân tố nào?(NHUNG HOÀNG)","options":["A. Mức địa tô của đất","B. Độ màu mỡ của đất","C. Vị trí của đất"],"answerLetter":"A","answerText":"A. Mức địa tô của đất","notes":""},{"id":78,"question":"Độc quyền nhà nước xuất hiện trong chủ nghĩa tư bản là sự liên minh giữa nhà nước tư bản với(073-356-8678)","options":["A. Các tổ chức nhà nước","B. Các tổ chức độc quyền","C. Các tổ chức kinh tế tư nhân"],"answerLetter":"B","answerText":"B. Các tổ chức độc quyền","notes":""},{"id":79,"question":"Ngoài giá trị thì giá cả của thị trưởng còn phụ thuộc vào","options":["A. Yếu tố cạnh tranh","B. Yếu tố cạnh tranh, sức mua của đồng tiền.","C. Yếu tố cạnh tranh, cung cầu, sức mua của đồng tiền.","D. Yếu tố cạnh tranh, cung cầu, sức mua của đồng tiền, giá trị"],"answerLetter":"C","answerText":"C. Yếu tố cạnh tranh, cung cầu, sức mua của đồng tiền.","notes":""},{"id":80,"question":"Cứ 100 công nhân thì tạo ra giá trị mới là 500.000 USD, tư bản khả biến cho mỗi công nhân là 1.000 USD/tháng. Để tạo ra được giá trị mới 1.200.000 USD thì cần lượng công nhân là bao nhiêu, biết rằng tiền lương cho mỗi công nhân không đổi và trình độ bóc lột tăng thêm 100%.","options":["A. Số công nhân là 200 người","B. Số công nhân là 100 người","C. Số công nhân là 500 người","D. Số công nhân là 50 người"],"answerLetter":"A","answerText":"A. Số công nhân là 200 người","notes":""},{"id":81,"question":"Đâu là giới hạn phát triển của chủ nghĩa tư bản?","options":["A. Mục đích của nền sản xuất tư bản chủ nghĩa vẫn tập trung chủ yếu vì lợi ích của thiểu số giai cấp tư sản","B. Thúc đẩy lực lượng sản xuất phát triển nhanh chống","C. Chuyển nền sản xuất nhỏ thành nền sản xuất lớn hiện đại","D. Thực hiện xã hội hoá sản xuất"],"answerLetter":"A","answerText":"A. Mục đích của nền sản xuất tư bản chủ nghĩa vẫn tập trung chủ yếu vì lợi ích của thiểu số giai cấp tư sản","notes":""},{"id":82,"question":"Trong nền kinh tế thị trường định hướng xã hội chủ nghĩa, thành phần kinh tế mới nào xuất hiện ở nước ta?(NHUNG HOÀNG)","options":["A. Thành phần kinh tế có vốn đầu tư nước ngoài","B. Không có thành phần kinh tế mới xuất hiện","C. Thành phần kinh tế tập thể","D. Thành phần kinh tế nhà nước"],"answerLetter":"A","answerText":"A. Thành phần kinh tế có vốn đầu tư nước ngoài","notes":""},{"id":83,"question":"Để sản xuất ra 1000 đối dép, công ty đầu tư 100000 USD cho nguyên liệu, vật liệu, 5000 USD cho hao mòn máy móc. Công ty đó trả 5000 USD cho công nhân, trình độ bốc lột đạt 200%. Tính giá trị (W) của 10000 đối dép công ty sản xuất ra?(NHUNG HOÀNG)","options":["A. W= 120000 USD","B. W110000 USD","C. W 115000 USD","D. W= 100000 USD"],"answerLetter":"A","answerText":"A. W= 120000 USD","notes":"W = c + v + mc = 100000 + 5000 = 105000v = 5000 m = m'.v = 2 x 5000 = 10000W = 105000 + 5000 + 10000 = 120000"},{"id":84,"question":"Nhận xét dưới đây về phương pháp sản xuất giá trị thặng dư tuyệt đối, nhận xét nào là không đúng?","options":["A. Chủ yếu áp dụng ở giai đoạn đầu của chủ nghĩa tư bản khi kỹ thuật còn thủ công lạc hậu","B. Giá trị sức lao động không thay đổi","C. Thời gian lao động tất yếu không thay đổi","D. Thời gian làm việc trong một ngày của công nhân được giữ nguyên"],"answerLetter":"D","answerText":"D. Thời gian làm việc trong một ngày của công nhân được giữ nguyên","notes":"(Kiểu hỏi khác: Những nhận xét dưới đây về phương pháp sản xuất giá trị thặng dư tuyệt đối, nhận xét nào là không đúng? A. Chủ yếu áp dụng ở giai đoạn đầu của chủ nghĩa tư bản khi kỹ thuật còn thủ công lạc hậu B. Giá trị sức lao động không thay đổi. C. Ngày lao động không thay đổi.)"},{"id":85,"question":"Mục đích hình thành độc quyền nhà nước trong chủ nghĩa tư bản đó là: (chọn nhiều phương án)","options":["A. Phục vụ lợi ích của các tổ chức độc quyền tư nhân","B. Phục vụ lợi ích của các nhà tư bản","C. Tiếp tục duy trì và phát triển chủ nghĩa tư bản","D. Lật đổ chủ nghĩa xã hội"],"answerLetter":"AC","answerText":"A. Phục vụ lợi ích của các tổ chức độc quyền tư nhân\nC. Tiếp tục duy trì và phát triển chủ nghĩa tư bản","notes":""},{"id":86,"question":"Chọn ý đúng về quan hệ cung - cầu đối với giá trị, giá cả?","options":["A. Có ảnh hưởng tới giá cả thị trường","B. Quyết định giá trị và giá cả hàng hoá","C. Chỉ quyết định đến giá cả và có ảnh hưởng đến giá trị"],"answerLetter":"A","answerText":"A. Có ảnh hưởng tới giá cả thị trường","notes":""},{"id":87,"question":"Địa tô tuyệt đối được hiểu là(NHUNG HOÀNG)","options":["A. Loại địa tô mà tất cả các nhà tư bản kinh doanh nông nghiệp đều phải nộp cho địa chủ, cho dù ruộng đất là tốt hay xấu","B. Phần giá trị thặng dư còn lại sau khi đã khấu trừ đi phần lợi nhuận binh quần mà các nhà tư bản kinh doanh nông nghiệp phải nộp cho địa chủ","C. Lợi nhuận siêu ngạch dôi ra ngoài lợi nhuận bình quân"],"answerLetter":"A","answerText":"A. Loại địa tô mà tất cả các nhà tư bản kinh doanh nông nghiệp đều phải nộp cho địa chủ, cho dù ruộng đất là tốt hay xấu","notes":""},{"id":88,"question":"Lý luận kinh tế chính trị của C. Mác và Ph. Ăngghen được cô đọng và tập trung trong tác phẩm nào?(NHUNG HOÀNG)","options":["A. Tư bản","B. Bản thảo kinh tế - triết học","C. Lược thảo phê phán khoa kinh tế chính trị","D. Tuyên ngôn của Đảng Cộng sản"],"answerLetter":"A","answerText":"A. Tư bản","notes":""},{"id":89,"question":"Cấu tạo giá trị của tư bản được hiểu là","options":["A. Tỷ lệ giữa số lượng tư liệu sản xuất và số lượng sức lao động sử dụng những tư liệu sản xuất đó trong quá trình sản xuất gọi","B. Tỷ lệ giữa số lượng giá trị của tư bản bất biến và số lượng giá trị của tư bản khả biến cần thiết để tiến hành sản xuất","C. Tỷ lệ giữa số lượng giá trị của tư bản bất biến và số lượng giá trị của tư bản tiêu dùng cần thiết để tiến hành sản xuất","D. Tỷ lệ giữa số lượng giá trị của tư bản cố định và số lượng giá trị của tư bản lưu động cần thiết để tiến hành sản xuất"],"answerLetter":"B","answerText":"B. Tỷ lệ giữa số lượng giá trị của tư bản bất biến và số lượng giá trị của tư bản khả biến cần thiết để tiến hành sản xuất","notes":""},{"id":90,"question":"Đặc trưng của cách mạng công nghiệp lần thứ hai đó là","options":["A. Sử dụng năng lượng điện và động cơ điện, để tạo ra dây chuyền sản xuất có tính chuyên môn hóa cao","B. Sử dụng năng lượng điện và máy hơi nước để cơ khí hóa sản xuất","C. Sử dụng năng lượng hơi nước, để cơ khí hóa sản xuất","D. Sử dụng công nghệ thông tin và máy tính để tự động hóa sản xuất"],"answerLetter":"A","answerText":"A. Sử dụng năng lượng điện và động cơ điện, để tạo ra dây chuyền sản xuất có tính chuyên môn hóa cao","notes":""},{"id":91,"question":"Việt Nam trở thành thành viên chính thức của tổ chức thương mại kinh tế thế giới WTO khi nào?","options":["A. 2007","B. 2006","C. 2005","D. 2008"],"answerLetter":"A","answerText":"A. 2007","notes":"Gia nhập năm 2006, trở thành thành viên năm 2007"},{"id":92,"question":"Kinh tế tri thức là","options":["A. Nền kinh tế trong đó có sự sản sinh ra, phổ cập và sử dụng tri thức giữ vai trò quyết định nhất đối với sự phát triển kinh tế, tạo ra của cải, nâng cao chất lượng cuộc sống","B. Nền kinh tế áp dụng khoa học kỹ thuật vào sản xuất","C. Nền kinh tế phát triển giáo dục đào tạo và xem đây là nền tảng, động lực cho công nghiệp hoá, hiện đại hoá","D. Nền kinh tế sử dụng tri thức trong sản xuất là phổ biến, vì thế cần đẩy mạnh đưa sinh viên đi du học ở các nước phát triển"],"answerLetter":"A","answerText":"A. Nền kinh tế trong đó có sự sản sinh ra, phổ cập và sử dụng tri thức giữ vai trò quyết định nhất đối với sự phát triển kinh tế, tạo ra của cải, nâng cao chất lượng cuộc sống","notes":""},{"id":93,"question":"Xu hướng hiện nay của các tổ chức độc quyền đó là:(NHUNG HOÀNG)","options":["A. Trở thành các công ty xuyên quốc gia và liên minh với nhà nước tư bản","B. Trở thành các công ty độc quyền và tài trợ cho các nước kém phát triển","C. Trở thành các công ty xuyên quốc gia và can thiệp và chế độ chính trị ở các nước đang phát triển","D. Trở thành các tập đoàn lớn"],"answerLetter":"A","answerText":"A. Trở thành các công ty xuyên quốc gia và liên minh với nhà nước tư bản","notes":""},{"id":94,"question":"Tư bản tài chính có nguồn gốc từ đâu?","options":["A. Quá trình độc quyền hàng hoá trong thương nghiệp và ngân hàng","B. Quá trình độc quyền hàng hoá trong công nghiệp và ngân hàng","C. Quá trình độc quyền hàng hoá trong thương nghiệp và công nghiệp","D. Quá trình độc quyền hàng hoá trong công - nông - thương"],"answerLetter":"B","answerText":"B. Quá trình độc quyền hàng hoá trong công nghiệp và ngân hàng","notes":""},{"id":95,"question":"Trong cơ cấu của độc quyền nhà nước trong chủ nghĩa tư bản, thì nhà nước đã trở thành.","options":["A. Tập thể tự bản khổng lồ","B. Bộ máy độc quyền phục vụ lợi ích nhà tư bản","C. Chủ sở hữu toàn bộ doanh nghiệp tư nhân","D. Một doanh nghiệp tư nhân"],"answerLetter":"A","answerText":"A. Tập thể tự bản khổng lồ","notes":""},{"id":96,"question":"Phương pháp tạo ra giá trị thặng dư tuyệt đối là gì?","options":["A. Kéo dài thời gian lao động thặng dư khi thời gian lao động tất yếu, năng suất lao động và giá trị sức lao động không đổi","B. Kéo dài thời gian lao động tất yếu khi thời gian lao động thặng dư, năng suất lao động và giá trị sức lao động không đổi","C. Rút ngắn thời gian lao động thặng dư khi thời gian lao động tất yếu, năng suất lao động và giá trị sức lao động không đổi","D. Rút ngắn thời gian lao động tất yếu khi thời gian lao động thặng dư, năng suất lao động và giá trị sức lao động không đổi"],"answerLetter":"A","answerText":"A. Kéo dài thời gian lao động thặng dư khi thời gian lao động tất yếu, năng suất lao động và giá trị sức lao động không đổi","notes":""},{"id":97,"question":"Bóc lột giá trị thặng dư tương đối là hình thức.(NHUNG HOÀNG)","options":["A. Tăng thời gian ngày lao động","B. Rút ngắn thời gian lao động cần thiết và thời gian lao động thặng dư","C. Rút ngắn thời gian lao động tất yếu","D. Tăng thời gian lao động tất yếu"],"answerLetter":"C","answerText":"C. Rút ngắn thời gian lao động tất yếu","notes":""},{"id":98,"question":"Mô hình công nghiệp hóa của Nhật Bản và các nước công nghiệp mới diễn ra trong khoảng bao nhiêu năm?(NHUNG HOÀNG)","options":["A. Từ 10 - 20 năm","B. Từ 15 - 25 năm","C. Từ 20 - 30 năm","D. Từ 25 - 35 năm"],"answerLetter":"C","answerText":"C. Từ 20 - 30 năm","notes":""},{"id":99,"question":"Đảng và Nhà nước quyết định xây dựng nền kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta từ Đại hội nào?(073-356-8678)","options":["A. Đại hội VI (1986)","B. Đại hội X (2006)","C. Đại hội XI (2011)","D. Đại hội V (1982)"],"answerLetter":"A","answerText":"A. Đại hội VI (1986)","notes":""},{"id":100,"question":"Giá cả độc quyền được hiểu là.","options":["A. Giá cả các tổ chức độc quyền áp đặt trong quá trình mua và bán","B. Giá cả do các tổ chức nhà nước áp đặt quy định trong quá trình mua và bán","C. Giá cả được các tổ chức doanh nghiệp chiếm thị phần lớn trên thị trường áp đặt và thông qua nhà nước đưa ra giá mua và bán"],"answerLetter":"A","answerText":"A. Giá cả các tổ chức độc quyền áp đặt trong quá trình mua và bán","notes":""},{"id":101,"question":"Ai là người đưa kinh tế chính trị trở thành môn khoa học có tính hệ thống với các phạm trù và khái niệm chuyên ngành?(NHUNG HOÀNG)","options":["A. Adam Smith","B. David Ricardo","C. Karl Marx","D. Willian Stafford"],"answerLetter":"A","answerText":"A. Adam Smith","notes":"(Kiểu hỏi khác: Kinh tế chính trị cổ điển Anh được hình thành và phát triển từ cuối thế ký XVIII đến nửa đầu thế kỷ XIX, mở đầu bằng các quan điểm lý luận của nhà kinh tế chính trị học nào sau đây? A. David Ricardo B. Adam Smith C. William Petty D. Thomas Mun )"},{"id":102,"question":"Tiền công trong chủ nghĩa tư bản có mấy hình thức?","options":["A. Hai hình thức","B. Ba hình thức","C. Bốn hình thức"],"answerLetter":"A","answerText":"A. Hai hình thức","notes":""},{"id":103,"question":"Thuật ngữ \"kinh tế chính trị\" được sử dụng lần đầu tiên vào năm nào?","options":["A. 1615","B. 1616","C. 1617","D. 1618"],"answerLetter":"A","answerText":"A. 1615","notes":""},{"id":104,"question":"Đại Hội X của Đảng chỉ rõ mục tiêu đầy mạnh công nghiệp hoá, hiện đại hoá cần","options":["A. Gắn với phát triển kinh tế tri thức; coi kinh tế tri thức là yếu tố quan trọng của nền kinh tế và của công nghiệp hóa, hiện đại hóa","B. Gắn với nền kinh tế thị trường định hướng tư bản chủ nghĩa","C. Gắn với nền kinh tế khép kín","D. Gắn với nền kinh tế thị trường, thực hiện chiến lược hàng xuất khẩu"],"answerLetter":"A","answerText":"A. Gắn với phát triển kinh tế tri thức; coi kinh tế tri thức là yếu tố quan trọng của nền kinh tế và của công nghiệp hóa, hiện đại hóa","notes":""},{"id":105,"question":"Người phát minh ra con thoi - một cải tiến của khung dệt và là một đóng góp quan trọng cho cách mạng cộng nghiệp lần thứ nhất là","options":["A. John Kay (1704 - 1779)","B. Richard Arkwright (1732-1792)","C. Edmund Cartwright (1743-1823)","D. James Watt (1736-1891)"],"answerLetter":"A","answerText":"A. John Kay (1704 - 1779)","notes":""},{"id":106,"question":"Xét về trình độ phát triển, kinh tế thị trường ở Việt Nam bao gồm nhiều cấp độ(NHUNG HOÀNG)","options":["A. Sản xuất hàng hóa nhỏ, kinh tế thị trường sơ khai, kinh tế thị trường hiện đại đan xen","B. Sản xuất hàng hóa lớn, kinh thế thị trường sơ khai, kinh tế thị trường đan xen","C. Sản xuất hàng hóa nhỏ, kinh tế thị trường hoàn thiện, kinh tế thị trường hiện đại","D. Sản xuất hàng hóa lớn, kinh tế thị trường hoàn thiện, kinh tế thị trường hiện đại đan xen"],"answerLetter":"A","answerText":"A. Sản xuất hàng hóa nhỏ, kinh tế thị trường sơ khai, kinh tế thị trường hiện đại đan xen","notes":""},{"id":107,"question":"Trong quá trình hội nhập kinh tế quốc tế, Việt Nam đã gia nhập những tổ chức nào sau đây ?","options":["A. ASEAN, AFTA, ASEM, APEC, WTO...","B. ASEAN, G20, ASEM, APEC, WTO...","C. ASEAN, AFTA, ASEM, APEC, EU...","D. ASEAN, ASEM, APEC, WTO, ECOWAS..."],"answerLetter":"A","answerText":"A. ASEAN, AFTA, ASEM, APEC, WTO...","notes":""},{"id":108,"question":"Công nghiệp hoá ở Anh (cuộc cách mạng công nghiệp lần thứ nhất) bắt nguồn từ ngành nào?","options":["A. Công nghiệp nhẹ","B. Công nghiệp nặng","C. Dịch vụ","D. Sản xuất vũ khí"],"answerLetter":"A","answerText":"A. Công nghiệp nhẹ","notes":""},{"id":109,"question":"Mức độ bóc lột của nhà tư bản được tính bằng","options":["A. Tỷ suất lợi nhuận","B. Tỷ suất giá trị thặng dư","C. Tỷ suất lợi nhuận bình quân"],"answerLetter":"B","answerText":"B. Tỷ suất giá trị thặng dư","notes":""},{"id":110,"question":"Hình thức độc quyền dưới dạng Cartel được phổ biến ở Châu âu vào thời gian nào?(NHUNG HOÀNG)","options":["A. Đầu thế kỷ XIX","B. Giữ thế kỷ XIX","C. Cuối thế kỷ XIX","D. Đầu thế kỷ XX"],"answerLetter":"C","answerText":"C. Cuối thế kỷ XIX","notes":""},{"id":111,"question":"Điểm khác biệt giữa dịch vụ và hàng hóa thông thường đó là?","options":["A. Dịch vụ không thể cất trữ","B. Dịch vụ phục vụ cho người khác","C. Dịch vụ nhằm đáp ứng nhu cầu của khách hàng","D. Dịch vụ có tính thời điểm"],"answerLetter":"A","answerText":"A. Dịch vụ không thể cất trữ","notes":""},{"id":112,"question":"Lượng giá trị của đơn vị hàng hoá thay đổi:","options":["A. Tỷ lệ nghịch với năng suất lao động, không phụ thuộc vào cường độ lao động","B. Tỷ lệ nghịch với cường độ lao động","C. Tỷ lệ thuận với năng suất lao động"],"answerLetter":"A","answerText":"A. Tỷ lệ nghịch với năng suất lao động, không phụ thuộc vào cường độ lao động","notes":""},{"id":113,"question":"Trong chủ nghĩa tư bản ngày nay, các trùm tài chính thống trị nền kinh tế thông qua","options":["A. Kết hợp \"chế độ tham dự\" với \"chế độ uỷ nhiệm\"","B. Chế độ tham dự","C. Chế độ uỷ nhiệm"],"answerLetter":"A","answerText":"A. Kết hợp \"chế độ tham dự\" với \"chế độ uỷ nhiệm\"","notes":""},{"id":114,"question":"\"Khoa học và công nghệ sẽ có bước tiến nhảy vọt. Kinh tế tri thức có vai trò ngày càng nổi bật trong quá trình phát triển lực lượng sản xuất\" được nhận định trong đại hội mấy của Đảng ?","options":["A. Đại hội XI","B. Đại hội X","C. Đại hội VIII","D. Đại hội IX"],"answerLetter":"D","answerText":"D. Đại hội IX","notes":"Đảng Cộng sản Việt Nam, Văn kiện Đại hội đại biểu toàn quốc lần thứ IX, NXB CTQG, H., 2001, tr 64 - 65"},{"id":115,"question":"Độc quyền được hiểu là:","options":["A. Liên minh giữa các doanh nghiệp lớn, có khả năng thâu tóm việc sản xuất và tiêu thụ một số loại hàng hóa, có khả năng định ra giá cả độc quyền, nhằm thu lợi nhuận độc quyền cao","B. Liên minh giữa các tổ chức cá nhân và nhà nước, có khả năng thâu tóm việc sản xuất và tiêu thụ một số loại hàng hóa, có khả năng định ra giá cả độc quyền, nhằm thu lợi nhuận độc quyền cao","C. Liên minh giữa các doanh nghiệp vừa và nhỏ, có khả năng thâu tóm việc sản xuất và tiêu thụ một số loại hàng hóa, có khả năng định ra giá cả độc quyền, nhằm thu lợi nhuận độc quyền cao"],"answerLetter":"A","answerText":"A. Liên minh giữa các doanh nghiệp lớn, có khả năng thâu tóm việc sản xuất và tiêu thụ một số loại hàng hóa, có khả năng định ra giá cả độc quyền, nhằm thu lợi nhuận độc quyền cao","notes":""},{"id":116,"question":"Quan điểm cho rằng, xã hội loài người phát triển dựa theo những quy luật tự nhiên thuộc về:","options":["A. Kinh tế chính trị của Karl Marx","B. Kinh tế chính trị cổ điển Anh","C. Chủ nghĩa trọng thương","D. Chủ nghĩa trọng nông"],"answerLetter":"B","answerText":"B. Kinh tế chính trị cổ điển Anh","notes":""},{"id":117,"question":"Chọn phương án sai: Lý do Việt Nam hoàn thiện thể chế kinh tế thị trường định hướng XHCN:(NHUNG HOÀNG)","options":["A. Do thể chế kinh tế thị trường định hướng xã hội chủ nghĩa chưa hoàn thiện","B. Do đảng cộng sản lãnh đạo","C. Hệ thống thể chế chưa đầy đủ","D. Hệ thống thể chế còn kém hiệu lực, hiệu quả, thiếu các yếu tố thị trường và các loại thị trường"],"answerLetter":"B","answerText":"B. Do đảng cộng sản lãnh đạo","notes":""},{"id":118,"question":"Chọn câu sai khi nói về kinh tế thị trường.","options":["A. Kinh tế thị trưởng phát triển mạnh nhất trong xã hội chủ nghĩa tư bản","B. Kinh tế thị trường đối lập với kinh tế tự nhiên","C. Kinh tế thị trưởng đối lập với các chế độ xã hội","D. Kinh tế thị trưởng Là thành tựu chung của nhân loại"],"answerLetter":"C","answerText":"C. Kinh tế thị trưởng đối lập với các chế độ xã hội","notes":""},{"id":119,"question":"Đảng ta khẳng định: \"Nền kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta là nền kinh tế nhiều thành phần, vận hành theo cơ chế thị trường, có sự quản lý của Nhà nước, dưới sự lãnh đạo của Đảng Cộng sản\" từ Đại hội nào?","options":["A. Đại hội V (1982)","B. Đại hội X (2006)","C. Đại hội VI (1986)","D. Đại hội XI (2011)"],"answerLetter":"D","answerText":"D. Đại hội XI (2011)","notes":""},{"id":120,"question":"Tích lũy tư bản dẫn đến","options":["A. Hình thành chủ nghĩa tư bản độc quyền","B. Hình thành chủ nghĩa tư bản","C. Hình thành độc quyền nhà nước giai đoạn tự do cạnh tranh"],"answerLetter":"A","answerText":"A. Hình thành chủ nghĩa tư bản độc quyền","notes":""},{"id":121,"question":"Đến nay thế giới trải qua bao nhiều cuộc cách mạng công nghiệp?","options":["A. Ba cuộc cách mạng công nghiệp","B. Bốn cuộc cách mạng công nghiệp","C. Năm cuộc cách mạng công nghiệp","D. Hai cuộc cách mạng công nghiệp"],"answerLetter":"B","answerText":"B. Bốn cuộc cách mạng công nghiệp","notes":""},{"id":122,"question":"Những yếu tố cốt lõi của kỹ thuật số trong cách mạng công nghiệp lần thứ 4 là: (chọn 3 phương án)","options":["A. Công nghệ 3D","B. Dữ liệu lớn (Big data)","C. Công nghệ sinh học","D. Vạn vật kết nối (loT)","E. Trí tuệ nhân tạo (AI)"],"answerLetter":"BDE","answerText":"B. Dữ liệu lớn (Big data)\nD. Vạn vật kết nối (loT)\nE. Trí tuệ nhân tạo (AI)","notes":""},{"id":123,"question":"Cách mạng công nghiệp lần thứ 3 còn được gọi là:","options":["A. Cách mạng vô tuyến","B. Cách mạng điện tử","C. Cách mạng sinh học","D. Cách mạng máy tính"],"answerLetter":"D","answerText":"D. Cách mạng máy tính","notes":""},{"id":124,"question":"Đối tượng nghiên cứu của kinh tế chính trị Mác - Lênin được hiểu là","options":["A. Những biểu hiện vật chất của lực lượng sản xuất","B. Các quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng","C. Các quan hệ giữa lực lượng sản xuất và quan hệ sản xuất","D. Các quan hệ xã hội của sản xuất và trao đổi"],"answerLetter":"D","answerText":"D. Các quan hệ xã hội của sản xuất và trao đổi","notes":"(Giải thích: Đối tượng nghiên cứu của kinh tế chính trị Mác – Lênin các quan hệ sản xuất và trao đổi trong mối quan hệ biện chứngvới lực lượng sản xuất và kiến trúc thượng tầng.)"},{"id":125,"question":"Đối tượng nghiên cứu của kinh tế chính trị Mác - Lênin là gì?","options":["A. Nghiên cứu các quan hệ sản xuất trong các khâu của quá trình tái sản xuất xã hội: sản xuất -phân phối - trao đối -tiêu dùng","B. Nghiên cứu các quan hệ sản xuất trong các khâu của quá trình tái sản xuất xã hội: sản xuất- trao đối - phân phối -tiêu dùng","C. Nghiên cứu các quan hệ sản xuất trong các khâu của quá trình sản xuất xã hội: sản xuất- trao đối- tiêu dùng","D. Nghiên cứu các quan hệ sản xuất trong các khâu của quá trình sản xuất xã hội: mua - bán"],"answerLetter":"A","answerText":"A. Nghiên cứu các quan hệ sản xuất trong các khâu của quá trình tái sản xuất xã hội: sản xuất -phân phối - trao đối -tiêu dùng","notes":""},{"id":126,"question":"Đâu KHÔNG phải là chức năng chính của kinh tế chính trị Mác - Lênin?","options":["A. Chức năng phương pháp luận","B. Chức năng tư tưởng","C. Chức năng nhận thức","D. Chức năng giáo dục"],"answerLetter":"D","answerText":"D. Chức năng giáo dục","notes":"(Kiểu trả lời khác: Chức năng khoa học)"},{"id":127,"question":"Việc đẩy mạnh ứng dụng khoa học - công nghệ ở nước ta hiện nay phải gắn liền với yếu tố nào sau đây","options":["A. Phát triển công nghiệp nặng","B. Phát triển sản xuất công nghệ cao","C. Phát triển kinh tế tri thức","D. Phát triển công nghiệp nhẹ"],"answerLetter":"C","answerText":"C. Phát triển kinh tế tri thức","notes":""},{"id":128,"question":"Chức năng tiền tệ là(NHUNG HOÀNG)","options":["A. Phương tiện lưu thông, phương tiện thanh toán; phương tiện mua bán; tiền tệ thế giới, thước đo giá trị","B. Phương tiện lưu thông, phương tiện thanh toán; phương tiện cất trữ; tiền tệ thế giới, thước đo giá trị","C. Phương tiện lưu thông, phương tiện trao đổi, phương tiện cất trữ; tiền tệ, thước đo giá trị","D. Phương tiện lưu thông, phương tiện thanh toán. phương tiện cất trữ, thước đo giá trị"],"answerLetter":"B","answerText":"B. Phương tiện lưu thông, phương tiện thanh toán; phương tiện cất trữ; tiền tệ thế giới, thước đo giá trị","notes":""},{"id":129,"question":"Ai là người được Mác coi là sáng lập ra kinh tế chính trị tư sản cổ điển?","options":["A. Thomas Mun","B. David Ricardo","C. Adam Smith","D. William Petty"],"answerLetter":"D","answerText":"D. William Petty","notes":""},{"id":130,"question":"Nền kinh tế hàng hoá có thể hình thành và phát triển khi có các điều kiện nào?(NHUNG HOÀNG)","options":["A. Phân công lao động xã hội và sự tách biệt về mặt kinh tế của các chủ thể sản xuất.","B. Sự tách biệt về mặt kinh tế của các chủ thể sản xuất","C. Của cải dư thừa","D. Khi có chế độ tư hữu xuất hiện"],"answerLetter":"A","answerText":"A. Phân công lao động xã hội và sự tách biệt về mặt kinh tế của các chủ thể sản xuất.","notes":""},{"id":131,"question":"Theo C. Mác, hàng hoá là sản phẩm lao động được sản xuất ra nhằm mục đích gì?","options":["A. Trao đổi và mua bán","B. Tiêu dùng","C. Kiếm lợi nhuận","D. Tặng và biểu"],"answerLetter":"A","answerText":"A. Trao đổi và mua bán","notes":""},{"id":132,"question":"Theo C.Mác, khối lượng giá trị thặng dư là gì?","options":["A. Giá trị của hàng hoá","B. Lượng giá trị thặng dư bằng tiền mà nhà tư bản thu được","C. Lượng giá trị mà trong toàn bộ quá trình lưu thông thu được","D. Giá trị sức lao động"],"answerLetter":"B","answerText":"B. Lượng giá trị thặng dư bằng tiền mà nhà tư bản thu được","notes":""},{"id":133,"question":"Để tiền biến thành tư bản cần?","options":["A. Phải tích lũy một lượng tiền lớn; tiền cần phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư","B. Phải tích lũy được một lượng hàng hóa lớn, hàng hóa cần phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư","C. Phải tích lũy một lượng tiền lớn","D. Phải tích lũy được một lượng máy móc lớn, máy móc cần phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư"],"answerLetter":"A","answerText":"A. Phải tích lũy một lượng tiền lớn; tiền cần phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư","notes":""},{"id":134,"question":"Vai trò của máy móc trong quá trình tạo ra giá trị thặng dư, chọn ý đúng.","options":["A. Máy móc là tiền đề vật chất cho việc tạo ra giá trị thặng dư","B. Máy móc và sức lao động đều tạo ra giá trị thặng dư","C. Máy móc là nguồn gốc của giá trị thặng dư"],"answerLetter":"A","answerText":"A. Máy móc là tiền đề vật chất cho việc tạo ra giá trị thặng dư","notes":""},{"id":135,"question":"Mỗi cuộc cách mạng công nghiệp xuất hiện đều có sự phát triển nhảy vọt về:(NHUNG HOÀNG)","options":["A. Tư liệu lao động","B. Các phát minh sáng chế","C. Tư liệu sinh hoạt","D. Tư liệu tiêu dùng"],"answerLetter":"A","answerText":"A. Tư liệu lao động","notes":""},{"id":136,"question":"Đại hội nào của Đảng Cộng sản Việt Nam đề cập đến sự cần thiết đổi mới cơ chế quản lý kinh tế","options":["A. Đại hội đảng VII","B. Đại hội đảng VI","C. Đại hội đảng VIII","D. Đại hội đảng V"],"answerLetter":"B","answerText":"B. Đại hội đảng VI","notes":""},{"id":137,"question":"Trong nền sản xuất hàng hóa, lạm phát là hiện tượng kinh tế tác động trực tiếp đến","options":["A. Tích tụ và tập trung tư bản","B. Tuần hoàn và chu chuyển tư bản","C. Sản xuất và tiêu dùng"],"answerLetter":"C","answerText":"C. Sản xuất và tiêu dùng","notes":""},{"id":138,"question":"Theo quan điểm của kinh tế chính trị, trong tư liệu lao động bộ phận nào quyết định đến năng suất lao động","options":["A. Các vật chứa đựng, bảo quản","B. Nguyên vật liệu cho sản xuất","C. Công cụ lao động","D. Kết cấu hạ tầng sản xuất"],"answerLetter":"C","answerText":"C. Công cụ lao động","notes":""},{"id":139,"question":"Trong nền kinh tế thị trường định hướng xã hội chủ nghĩa, thành phần kinh tế nào giữ vai trò (NHUNG HOÀNG)","options":["A. Thành phần kinh tế nhà nước","B. Thành phần kinh tế tư nhân","C. Thành phần kinh tế tập thể","D. Thành phần kinh tế có vốn đầu tư nước ngoài"],"answerLetter":"A","answerText":"A. Thành phần kinh tế nhà nước","notes":"đề chưa rõ, nếu “chủ đạo” thì là nhà nước, còn “động lực” thì là tư nhân"},{"id":140,"question":"Cạnh tranh kinh tế được hiểu là","options":["A. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành chi phí tối đa cho mình","B. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành lợi ích tối đa cho mình","C. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành thị phần tối đa cho mình","D. Sự đấu tranh ở giữa các chủ thể kinh tế"],"answerLetter":"B","answerText":"B. Sự đấu tranh ở giữa các chủ thể kinh tế, để giành lợi ích tối đa cho mình","notes":""},{"id":141,"question":"Đối tượng nghiên cứu của kinh tế- chính trị Mác-Lênin là","options":["A. Các quan hệ của sản xuất và trao đổi trong phương thức sản xuất mà các quan hệ đó hình thành và phát triển","B. Quá trình sản xuất, phân phối, trao đổi, tiêu dùng","C. Quan hệ xã hội giữa người với người","D. Quan hệ sản xuất trong mối quan hệ tác động qua lại giữa lực lượng sản xuất"],"answerLetter":"A","answerText":"A. Các quan hệ của sản xuất và trao đổi trong phương thức sản xuất mà các quan hệ đó hình thành và phát triển","notes":""},{"id":142,"question":"Quan hệ về tỷ lượng trong trao đổi giữa các hàng hóa với nhau do cái gì quy định?(073-356-8678)","options":["A. Do tính hữu ích của hàng hóa","B. Do giá trị nội tại của hàng hóa","C. Do quan hệ cung - cầu","D. Do ngẫu nhiên"],"answerLetter":"B","answerText":"B. Do giá trị nội tại của hàng hóa","notes":""},{"id":143,"question":"Cách mạng công nghiệp lần thứ tư được đề cập lần đầu tiên tại ở đâu và năm nào?","options":["A. Tại Đức năm 2011","B. Tại Pháp năm 2011","C. Tại Anh năm 2012","D. Tại Mỹ năm 2011"],"answerLetter":"A","answerText":"A. Tại Đức năm 2011","notes":""},{"id":144,"question":"Công nghiệp hóa ở nước Anh bắt nguồn từ ngành nào?","options":["A. Công nghiệp dệt","B. Công nghiệp cơ khí chế tạo","C. Công nghiệp khai khoảng","D. Công nghiệp đóng tàu"],"answerLetter":"A","answerText":"A. Công nghiệp dệt","notes":""},{"id":145,"question":"Phương hướng cơ bản, lâu dài để tăng sản phẩm xã hội là","options":["A. Tăng năng suất lao động","B. Tăng cường độ lao động","C. Kéo dài thời gian lao động","D. Mở rộng quy mô sản xuất, khai thác tài nguyên thiên nhiên"],"answerLetter":"A","answerText":"A. Tăng năng suất lao động","notes":""},{"id":146,"question":"Đâu là các nhân tố thúc đẩy sự tăng trưởng kinh tế?","options":["A. Kỹ thuật - công nghệ Cơ cấu kinh tế, Thể chế chính trị, Con người","B. Con người; Kỹ thuật công nghệ; Cơ cấu kinh tế; Thể chế chính trị, vốn","C. Con người; Cơ cấu kinh tế; Thể chế chính trị, vốn","D. Kỹ thuật - công nghệ; Cơ cấu kinh tế; Thể chế chính trị, vốn"],"answerLetter":"B","answerText":"B. Con người; Kỹ thuật công nghệ; Cơ cấu kinh tế; Thể chế chính trị, vốn","notes":""},{"id":147,"question":"Ở Việt Nam cũng như trên thế giới sử dụng thuật ngũ \"cách mạng công nghiệp lần thứ tư\" với hàm ý gì?(NHUNG HOÀNG)","options":["A. Sự thay đổi về lượng trong lực lượng sản xuất của nền kinh tế thế giới","B. Sự thay đổi về chất trong lực lượng sản xuất của nền kinh tế thế giới","C. Sự thay đổi về chất trong quan hệ sản xuất của nền kinh tế thế giới","D. Sự thay đổi căn bản, toàn diện trong đời sống, sản xuất của nền kinh tế thế giới"],"answerLetter":"B","answerText":"B. Sự thay đổi về chất trong lực lượng sản xuất của nền kinh tế thế giới","notes":""},{"id":148,"question":"Cách mạng công nghiệp lần thứ nhất khởi phát ở quốc gia nào?","options":["A. Anh","B. Pháp","C. Hy lap","D. Đức"],"answerLetter":"A","answerText":"A. Anh","notes":""},{"id":149,"question":"Cách mạng công nghiệp lần thứ hai khởi phát ở quốc gia nào?","options":["A. Anh","B. Pháp","C. Hy lap","D. Nga"],"answerLetter":"A","answerText":"A. Anh","notes":""},{"id":150,"question":"Mô hình công nghiệp hóa kiểu Liên Xô được bắt đầu trong thời gian nào?","options":["A. Từ đầu những năm 1920","B. Từ đầu những năm 1930","C. Từ đầu những năm 1940","D. Sau năm 1945"],"answerLetter":"B","answerText":"B. Từ đầu những năm 1930","notes":""},{"id":151,"question":"Chọn câu sai khi nói về đặc điểm của kinh tế thị trường.","options":["A. Kinh tế thị trường là kinh tế hàng hoá phát triển cao","B. Kinh tế thị trường lấy khoa học công nghệ hiện đại làm cơ sở","C. Kinh tế thị trường chỉ có thể phát triển mạnh ở xã hội phong kiến","D. Kinh tế thị trường đạt đến trình độ cao trong chủ nghĩa tư bản"],"answerLetter":"C","answerText":"C. Kinh tế thị trường chỉ có thể phát triển mạnh ở xã hội phong kiến","notes":"(Kiểu hỏi khác: Đặc điểm nào dưới đây không phải của kinh tế thị trường?)"},{"id":152,"question":"Chọn câu sai: Khuyết tật của kinh tế thị trường là","options":["A. Luôn run rủi ro ẩn chứa","B. Nhà nước không thể sửa chữa","C. Không tự phục hồi được sắc độ phân tích trong xã hội","D. Không thể tự phục hồi tài nguyên kiệt"],"answerLetter":"B","answerText":"B. Nhà nước không thể sửa chữa","notes":""},{"id":153,"question":"Cấu tạo hữu cơ của tư bản được kí hiệu là(NHUNG HOÀNG)","options":["A. c/v","B. T/T","C. m/v","D. CH/ch"],"answerLetter":"A","answerText":"A. c/v","notes":""},{"id":154,"question":"Yếu tố quyết định đến giá cả hàng hoá là(NHUNG HOÀNG)","options":["A. Giá trị của hàng hoá","B. Quan hệ cung cầu về hàng hoá","C. Giá trị sử dụng của hàng hoá"],"answerLetter":"A","answerText":"A. Giá trị của hàng hoá","notes":""},{"id":155,"question":"Trên giác độ kinh tế chính trị, mục tiêu cuối cùng của xuất khẩu tư bản là:","options":["A. Chiếm đoạt giá trị thặng dư và các nguồn lợi khác ở nước nhập khẩu tư bản","B. Thực hiện giá trị và chiếm các nguồn lợi khác của nước nhập khẩu tư bản","C. Giúp đỡ các nước nhập khẩu tư bản phát triển."],"answerLetter":"A","answerText":"A. Chiếm đoạt giá trị thặng dư và các nguồn lợi khác ở nước nhập khẩu tư bản","notes":""},{"id":156,"question":"Tốc độ chu chuyển tư bản được tính bằng công thức:","options":["A. n = CH/ch","B. N = ch/ CH","C. n=t/t100%","D. N=t/t100%"],"answerLetter":"A","answerText":"A. n = CH/ch","notes":""},{"id":157,"question":"Đâu không phải nằm trong tính tất yếu khách quan của công nghiệp hóa, hiện đại hóa ở Việt Nam ?","options":["A. Từ yêu cầu phải xây dựng cơ sở vật chất- kỹ thuật của chủ nghĩa xã hội","B. Từ yêu cầu phải rút ngắn khoảng cách tụt lùi về kinh tế, kĩ thuật, công nghệ giữa nước ta với các nước trong khu vực và quốc tế","C. Từ yêu cầu cần phải tạo ra năng suất lao động xã hội cao, bảo đảm cho sự tồn tại và phát triển của chủ nghĩa xã hội","D. Từ yêu cầu của thể chế chính trị của Việt Nam"],"answerLetter":"D","answerText":"D. Từ yêu cầu của thể chế chính trị của Việt Nam","notes":""},{"id":158,"question":"Một trong những tác động tích cực của độc quyền đối với nền kinh tế đó là(NHUNG HOÀNG)","options":["A. Tập trung các nguồn lực trong việc nghiên cứu phát triển và khai thác các tiến bộ của khoa học kỹ thuật","B. Tăng sức mua của người tiêu dùng, từ đó nâng cao năng lực cạnh tranh của các tổ chức độc quyền","C. Tạo ra sức mạnh về chính trị, quân sự cho các quốc gia phát triển","D. Bị chi phối bởi các nhóm lợi ích cục bộ từ đó làm gia tăng sự phân hóa giàu nghèo"],"answerLetter":"A","answerText":"A. Tập trung các nguồn lực trong việc nghiên cứu phát triển và khai thác các tiến bộ của khoa học kỹ thuật","notes":""},{"id":159,"question":"Trong nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam, vai trò của kinh tế nhà nước và kinh tế tư nhân đó là","options":["A. Kinh tế nhà nước giữ vai trò chủ đạo, kinh tế tư nhân giữ vai trò là một động lực quan trọng","B. Kinh tế nhà nước giữ vai trò quyết định, kinh tế tư nhân giữ vai trò là một động lực quan trọng","C. Kinh tế tư nhân giữ vai trò chủ đạo, kinh tế nhà nước giữ vai trò là một động lực quan trọng","D. Kinh tế tư nhân giữ vai trò then chốt, kinh tế nhà nước giữ vai trò quyết định"],"answerLetter":"A","answerText":"A. Kinh tế nhà nước giữ vai trò chủ đạo, kinh tế tư nhân giữ vai trò là một động lực quan trọng","notes":""},{"id":160,"question":"Cạnh tranh trong chủ nghĩa tư bản dẫn đến","options":["A. Tích lũy tư bản","B. Tích tụ tư bản","C. Độc quyền"],"answerLetter":"C","answerText":"C. Độc quyền","notes":""},{"id":161,"question":"Trong cơ chế của độc quyền nhà nước trong chủ nghĩa tư bản thì","options":["A. Nhà nước phụ thuộc vào tổ chức độc quyền","B. Nhà nước không phụ thuộc vào tổ chức độc quyền","C. Tổ chức độc quyền phụ thuộc vào nhà nước."],"answerLetter":"A","answerText":"A. Nhà nước phụ thuộc vào tổ chức độc quyền","notes":""},{"id":162,"question":"Vai trò tích cực của chủ nghĩa tư bản đó là: (chọn nhiều phương án)","options":["A. Thúc đẩy lực lượng sản xuất phát triển","B. Chuyển nền sản xuất nhỏ thành nền sản xuất hiện đại","C. Thực hiện xã hội hóa sản xuất","D. Phân công lao động, chuyên môn hóa sản xuất"],"answerLetter":"ABC","answerText":"A. Thúc đẩy lực lượng sản xuất phát triển\nB. Chuyển nền sản xuất nhỏ thành nền sản xuất hiện đại\nC. Thực hiện xã hội hóa sản xuất","notes":""},{"id":163,"question":"Mối quan hệ giữa quy luật kinh tế và chính sách kinh tế là","options":["A. Khác nhau","B. Khác nhau nhưng có quan hệ với nhau","C. Đồng nhất với nhau","D. Tất cả đáp án trên"],"answerLetter":"B","answerText":"B. Khác nhau nhưng có quan hệ với nhau","notes":""},{"id":164,"question":"Chủ nghĩa tư bản ra đời khi(NHUNG HOÀNG)","options":["A. Sản xuất hàng hoá đã phát triển cao","B. Phân công lao động đã phát triển cao","C. Tư liệu sản xuất tập trung vào một số ít người còn đa số người bị mất hết tư liệu sản xuất"],"answerLetter":"C","answerText":"C. Tư liệu sản xuất tập trung vào một số ít người còn đa số người bị mất hết tư liệu sản xuất","notes":""},{"id":165,"question":"Khi nào sức lao động trở thành hàng hoá một cách phổ biến?","options":["A. Trong nền sản xuất hàng hoá tư bản chủ nghĩa","B. Trong xã hội chiếm hữu nô lệ","C. Trong nền sản xuất lớn hiện đại"],"answerLetter":"A","answerText":"A. Trong nền sản xuất hàng hoá tư bản chủ nghĩa","notes":""},{"id":166,"question":"Phân chia theo tiêu chỉ cấu trúc của các tổ chức tham gia xã hội, thể chế được chia thành.(NHUNG HOÀNG)","options":["A. Thế chế công, thể chế tư","B. Thể chế nhà nước, thể chế tư bản tư nhân","C. Thể chế nước trong và ngoài nước","D. Thể chế chính trị và thể chế kinh tế"],"answerLetter":"A","answerText":"A. Thế chế công, thể chế tư","notes":""},{"id":167,"question":"Công cụ quản lý vĩ mô của nhà nước trong nền kinh tế thị trường định hướng xã hội chủ nghĩa là?","options":["A. Kế hoạch và thị trường, hệ thống pháp luật, các công cụ tài chính tiền tệ, công cụ điều tiết kinh tế đối ngoại","B. Kế hoạch và thị trường, kinh tế tư nhân, quản lý tiền tệ","C. Thuế, kinh tế tư nhân, kinh tế tập thể","D. Hệ thống các chính sách kinh tế và xã hội"],"answerLetter":"A","answerText":"A. Kế hoạch và thị trường, hệ thống pháp luật, các công cụ tài chính tiền tệ, công cụ điều tiết kinh tế đối ngoại","notes":""},{"id":168,"question":"Xuất khẩu tư bản được coi là đặc điểm của","options":["A. Phương thức sản xuất phong kiến","B. Phương thức sản xuất tư bản chủ nghĩa","C. Chủ nghĩa tư bản giai đoạn tự do cạnh tranh","D. Chủ nghĩa tư bản giai đoạn độc quyền"],"answerLetter":"D","answerText":"D. Chủ nghĩa tư bản giai đoạn độc quyền","notes":""},{"id":169,"question":"Tiền tệ có mấy chức năng?","options":["A. Ba chức năng","B. Năm chức năng","C. Sáu chức năng","D. Bảy chức năng"],"answerLetter":"B","answerText":"B. Năm chức năng","notes":""},{"id":170,"question":"Thể chế được hiểu là(NHUNG HOÀNG)","options":["A. Những quy tắc, pháp luật, bộ máy quản lí và cơ chế vận hành nhằm điều chỉnh các hoạt động của con người trong 1 chế độ xã hội","B. Luật chơi\" chính thức và phi chính thức được đặt ra đối với các chủ thể tham gia hoạt động trong nền kinh tế của một quốc gia trong một giai đoạn lịch sử nhất định","C. Được cấu thành bởi hệ thống các bộ phận khác nhau mà mỗi bộ phận cũng là một hệ thống phức tạp gồm nhiều yếu tố"],"answerLetter":"A","answerText":"A. Những quy tắc, pháp luật, bộ máy quản lí và cơ chế vận hành nhằm điều chỉnh các hoạt động của con người trong 1 chế độ xã hội","notes":""},{"id":171,"question":"Trong tuần hoàn tư bản, giai đoạn đầu tiên - giai đoạn lưu thông tư bản tồn tại dưới hình thái gì?","options":["A. Tư bản hàng hóa","B. Tư bản tiền tệ","C. Tư bản sản xuất","D. Tư bản tiêu dùng"],"answerLetter":"B","answerText":"B. Tư bản tiền tệ","notes":""},{"id":172,"question":"Trong tuần hoàn tư bản, giai đoạn thứ hai - giai đoạn lưu thông tư bản tồn tại dưới hình thái gì?","options":["A. Tư bản hàng hóa","B. Tư bản tiền tệ","C. Tư bản sản xuất","D. Tư bản tiêu dùng"],"answerLetter":"C","answerText":"C. Tư bản sản xuất","notes":""},{"id":173,"question":"Trong tuần hoàn tư bản, giai đoạn thứ ba - giai đoạn lưu thông tư bản tồn tại dưới hình thái gì?","options":["A. Tư bản hàng hóa","B. Tư bản tiền tệ","C. Tư bản sản xuất","D. Tư bản tiêu dùng"],"answerLetter":"A","answerText":"A. Tư bản hàng hóa","notes":""},{"id":174,"question":"Dựa vào căn cứ nào để chia tư bản ra thành tư bản cố định và tư bản lưu động?","options":["A. Phương thức chuyển giá trị của các bộ phận tư bản sang sản phẩm","B. Vai trò các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư","C. Sự thay đổi về lượng trong quá trình sản xuất"],"answerLetter":"A","answerText":"A. Phương thức chuyển giá trị của các bộ phận tư bản sang sản phẩm","notes":""},{"id":175,"question":"Cách mạng công nghiệp lần thứ ba diễn ra trong giai đoạn nào?","options":["A. Từ đầu thập niên 50 của thế kỷ XX đến cuối thế kỷ XX","B. Từ đầu thập niên 60 của thế kỷ XX đến cuối thế kỷ XX","C. Từ đầu thập niên 70 của thế kỷ XX đến cuối thế kỷ XX","D. Từ đầu thập niên 80 của thế kỷ XX đến cuối thế kỷ XX"],"answerLetter":"B","answerText":"B. Từ đầu thập niên 60 của thế kỷ XX đến cuối thế kỷ XX","notes":"(Kiểu hỏi khác: Cách mạng công nghiệp lần thứ ba diễn ra trong thời gian nào? A. Từ giữa thế kỷ XV đến giữa thế kỷ XIX B. Từ giữa thế kỷ XVI đến giữa thế kỷ XVII C. Từ giữa thế kỷ XVIII đến giữa thế kỷ XIX D. Từ đầu những năm 60 của XX đến cuối thế kỷ XX)"},{"id":176,"question":"Những nhân tố nào ảnh hưởng đến quy mô của tích lũy tư bản?","options":["A. Cường độ lao động; trình độ bóc lột sức lao động; sự chênh lệch ngày càng tăng giữa tư bản sử dụng và tư bản đã tiễu dùng, quy mô của tư bản ứng trước","B. Trình độ năng suất lao động; trình độ bóc lột sức lao động ; sự chênh lệch ngày càng tăng giữa tư bản sử dụng và tư bản đã tiêu dùng, quy mô của tư bản ứng trước","C. Sự chênh lệch ngày càng tăng giữa tư bản sử dụng và tư bản đã tiêu dùng; quy mô của tư bản ứng trước, trình độ bóc lột sức lao động","D. Trình độ năng suất lao động; trình độ bóc lột sức lao động; sự chênh lệch ngày càng tăng giữa tư bản sử dụng và tư bản đã tiêu dùng"],"answerLetter":"B","answerText":"B. Trình độ năng suất lao động; trình độ bóc lột sức lao động ; sự chênh lệch ngày càng tăng giữa tư bản sử dụng và tư bản đã tiêu dùng, quy mô của tư bản ứng trước","notes":""},{"id":177,"question":"Đảng Cộng sản Việt Nam luôn nhấn mạnh tầm quan trọng của việc xây dựng nền kinh tế.(NHUNG HOÀNG)","options":["A. Mở cửa","B. Độc lập, tự chủ","C. Hội nhập kinh tế quốc tế","D. Có tính cạnh tranh"],"answerLetter":"B","answerText":"B. Độc lập, tự chủ","notes":""},{"id":178,"question":"Tiền tệ ra đời là do nhu cầu.","options":["A. Nhu cầu sản xuất hàng hóa và trao đổi hàng hóa","B. Nhu cầu lưu thông hàng hóa","C. Nhu cầu lưu thông tiền tệ","D. Nhu cầu sản xuất giá trị"],"answerLetter":"A","answerText":"A. Nhu cầu sản xuất hàng hóa và trao đổi hàng hóa","notes":""},{"id":179,"question":"Liên kết các doanh nghiệp theo cùng một ngành là theo hình thức:","options":["A. Liên kết dọc","B. Liên kết ngang","C. Cả liên kết dọc và liên kết ngang","D. Một liên kết khác"],"answerLetter":"B","answerText":"B. Liên kết ngang","notes":""},{"id":180,"question":"Nguồn gốc của giá trị thặng dư từ đầu mà có?","options":["A. Mua hàng hóa thấp hơn giá trị thật","B. Mua hàng hóa cao hơn giá trị thật","C. Mua hàng hóa bằng giá trị thật","D. Mua được hàng hóa sức lao động"],"answerLetter":"D","answerText":"D. Mua được hàng hóa sức lao động","notes":""},{"id":181,"question":"Xuất khẩu hàng hoá là gì?","options":["A. Đặc điểm của giai đoạn chủ nghĩa tư bản tự do cạnh tranh","B. Đặc điểm của giai đoạn chủ nghĩa tư bản độc quyền tự do cạnh tranh","C. Đặc điểm của giai đoạn chủ nghĩa tư bản độc quyền nhà nước"],"answerLetter":"A","answerText":"A. Đặc điểm của giai đoạn chủ nghĩa tư bản tự do cạnh tranh","notes":"(Kiểu hỏi khác Xuất khẩu hàng hóa là một trong những đặc điểm của: A. Sản xuất hàng hóa giản đơn B. Phương thức sản xuất tư bản chủ nghĩa C. Giai đoạn chủ nghĩa tư bản tự do cạnh tranh D. Giai đoạn chủ nghĩa tư bản độc quyền)"},{"id":182,"question":"Nguồn gốc của tích lũy tư bản là","options":["A. Giá trị của hàng hóa","B. Giá trị thặng dư","C. Giá trị của hàng hóa sức lao động"],"answerLetter":"B","answerText":"B. Giá trị thặng dư","notes":""},{"id":183,"question":"Kinh tế- chính trị Mác - Lênin đã kế thừa và phát triển trực tiếp những thành tựu của(NHUNG HOÀNG)","options":["A. Kinh tế chính trị cổ điển Anh","B. Chủ nghĩa trọng thương","C. Chủ nghĩa trọng nông","D. Kinh tế chính trị tầm thường"],"answerLetter":"A","answerText":"A. Kinh tế chính trị cổ điển Anh","notes":""},{"id":184,"question":"Nguồn gốc chính của lợi nhuận độc quyền cao xuất phát từ đâu?","options":["A. Lao động không công của công nhân làm việc ở các xí nghiệp ngoài độc quyền","B. Giá trị thặng dư của các nhà tư bản vừa và nhỏ bị mất đi do thua thiệt về quá trình cạnh tranh","C. Lao động thặng dư và lao động tất yếu của người sản xuất vừa và nhỏ","D. Lao động của công nhân làm việc trong các xí nghiệp độc quyền"],"answerLetter":"D","answerText":"D. Lao động của công nhân làm việc trong các xí nghiệp độc quyền","notes":""},{"id":185,"question":"Công thức chung của tư bản là:","options":["A. H-T-H","B. T-H-T'","C. T-H-T"],"answerLetter":"B","answerText":"B. T-H-T'","notes":""},{"id":186,"question":"Lượng tỷ suất lợi nhuận là","options":["A. Luôn luôn nhỏ hơn giá trị thặng dư","B. Luôn luôn lớn hơn tỷ suất giá trị thặng dư","C. Luôn luôn bằng tỷ suất giá trị thặng dư","D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư"],"answerLetter":"D","answerText":"D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư","notes":""},{"id":187,"question":"Sự phát triển các hình thái giá trị bao gồm:","options":["A. Hình thái giá trị ngẫu nhiên, hình thái giá trị chung, hình thái tiền tệ","B. Hình thái giá trị ngẫu nhiên; hình thái giá trị thu hẹp; hình thái giá trị chung; hình thái tiền tệ","C. Hình thái giá trị ngẫu nhiên; hình thái giá trị mở rộng (đầy đủ); hình thái giá trị chung; hình thái tiền tệ","D. Hình thái giá trị mở rộng (đầy đủ); hình thái giá trị chung; hình thái tiền tệ"],"answerLetter":"C","answerText":"C. Hình thái giá trị ngẫu nhiên; hình thái giá trị mở rộng (đầy đủ); hình thái giá trị chung; hình thái tiền tệ","notes":""},{"id":188,"question":"Nội dung cơ bản của cách mạng công nghiệp lần thứ nhất đó là","options":["A. Chuyển từ lao động thủ công sang lao động máy móc","B. Chuyển từ lao động thủ công sang sử dụng động cơ điện","C. Chuyển từ lao động máy móc sang lao động sử dụng năng lượng điện và động cơ điện"],"answerLetter":"A","answerText":"A. Chuyển từ lao động thủ công sang lao động máy móc","notes":""},{"id":189,"question":"Một trong những đặc điểm chủ yếu của bất kỳ xã hội nào lấy thị trường làm phương tiện có tính cơ sở để phân phối các nguồn lực kinh tế là?","options":["A. Các chủ thể kinh tế có tính độc lập, nghĩa là có quyền tự chủ trong sản xuất, kinh doanh, lỗ lãi tự chịu","B. Các chủ thể kinh tế không có tính độc lập, nghĩ là không có quyền tự chủ trong sản xuất, kinh doanh, lỗ lãi tự chịu","C. Các chủ thể kinh tế có tính độc lập, nghĩa là có quyền quyết định lỗ lãi","D. Các chủ thể kinh tế có tính độc lập, nghĩa là có quyền làm bất cứ những gì họ muốn"],"answerLetter":"A","answerText":"A. Các chủ thể kinh tế có tính độc lập, nghĩa là có quyền tự chủ trong sản xuất, kinh doanh, lỗ lãi tự chịu","notes":"(Kiểu hỏi khác: Một trong những đặc điểm chủ yếu của bất kỳ xã hội nào lấy thị trường làm phương tiện có tính cơ sở để phân phối các nguồn lực kinh tế là A. Có hệ thống pháp quy kiện toàn và sự quản lý vĩ mô của Nhà nước B. Có hệ thống pháp quy kiện toàn và sự quản lý của Nhà nước C. Có hệ thống pháp quy kiện toàn và sự quản lý văn hóa xã hội của Nhà nước D. Có hệ thống pháp quy kiện toàn và sự quản lý kinh tế, giáo dục của Nhà nước)"},{"id":190,"question":"Loại tiền nào được hiểu là phương tiện thanh toán mà giá trị hay sức mua của nó với tư cách là tiền vượt xa chi phí sản xuất ra nó hay giá trị của nó khi dùng vào việc khác, chứ không dùng làm tiền?","options":["A. Tiền quy ước","B. Tiền tượng trưng","C. Tiền ghi nợ","D. Tiền vàng"],"answerLetter":"D","answerText":"D. Tiền vàng","notes":""},{"id":191,"question":"Phương pháp sản xuất giá trị thặng dư tuyệt đối và phương pháp sản xuất giá trị thặng dư tương đối có điểm nào giống nhau?","options":["A. Đều làm tăng tỷ suất giá trị thặng dư","B. Đều làm cho công nhân tổn sức lao động nhiều hơn","C. Đều làm giảm giá trị sức lao động của công nhân"],"answerLetter":"A","answerText":"A. Đều làm tăng tỷ suất giá trị thặng dư","notes":""},{"id":192,"question":"Những ngành nào sẽ được nhà nước tư sản đầu tư thay cho giai cấp tư sản tư nhân?","options":["A. Những ngành phải mất chi phí đầu tư lớn, thu hồi vốn nhanh nhưng lợi nhuận ít","B. Những ngành phải mất chi phí đầu tư lớn, thu hồi vốn chậm nhưng lợi nhuận cao","C. Những ngành phải mất chi phí đầu tư không lớn, tuy nhiên thu hồi vốn nhanh và lợi nhuận cao","D. Những ngành phải mất chi phí đầu tư lớn tuy nhiên thu hồi vốn chậm và lợi nhuận ít"],"answerLetter":"D","answerText":"D. Những ngành phải mất chi phí đầu tư lớn tuy nhiên thu hồi vốn chậm và lợi nhuận ít","notes":""},{"id":193,"question":"Khối lượng giá trị thặng dư được tính bằng công thức nào?","options":["A. M = m'x p'","B. M=m' x V","C. M=m'xt'"],"answerLetter":"B","answerText":"B. M=m' x V","notes":""},{"id":194,"question":"Sản xuất hàng hóa là(NHUNG HOÀNG)","options":["A. Kiểu tổ chức kinh tế mà sản phẩm làm ra được mang ra trao đổi, mua bán trên thị trường để thỏa mãn nhu cầu của xã hội","B. Kiểu tổ chức kinh tế mà sản phẩm làm ra phải tuân thủ các quy luật của thị trường nhằm thỏa mãn nhu cầu của xã hội","C. Kiểu tổ chức kinh tế do các quy luật sản xuất và lưu thông quyết định nhằm thỏa mãn nhu cầu của thị trường"],"answerLetter":"A","answerText":"A. Kiểu tổ chức kinh tế mà sản phẩm làm ra được mang ra trao đổi, mua bán trên thị trường để thỏa mãn nhu cầu của xã hội","notes":""},{"id":195,"question":"Tư duy của Đảng về kinh tế thị trường là(NHUNG HOÀNG)","options":["A. Có thể và cần thiết sử dụng kinh tế thị trường để xây dựng chủ nghĩa xã hội ở nước ta","B. Có thể và không cần thiết sử dụng kinh tế thị trường để xây dựng chủ nghĩa xã hội ở nước ta","C. Không thể và không cần thiết sử dụng kinh tế thị trường để xây dựng chủ nghĩa xã hội ở nước ta","D. Kinh tế thị trường là cái riêng có của chủ nghĩa tư bản"],"answerLetter":"A","answerText":"A. Có thể và cần thiết sử dụng kinh tế thị trường để xây dựng chủ nghĩa xã hội ở nước ta","notes":""},{"id":196,"question":"Tích lũy tư bản là:","options":["A. Tư bản hóa tư liệu tiêu dùng","B. Tư bản hóa giá trị thặng dư","C. Tư bản hóa sức lao động"],"answerLetter":"B","answerText":"B. Tư bản hóa giá trị thặng dư","notes":""},{"id":197,"question":"Quan điểm \"đổi mới phải luôn luôn quán triệt quan điểm \"dân là gốc\" vì lợi ích của nhân dân, dựa vào nhân dân, phát huy vai trò làm chủ, tinh thần trách nhiệm, sức sáng tạo và mọi nguồn lực của nhân dân; phát huy sức mạnh đại đoàn kết dân tộc\" được đưa ra trong đại hội nào?","options":["A. Đại hội đảng X","B. Đại hội đảng XI","C. Đại hội đảng XII","D. Đại hội đảng XIII"],"answerLetter":"C","answerText":"C. Đại hội đảng XII","notes":""},{"id":198,"question":"Thị trường giải quyết ba vấn đề kinh tế nào?","options":["A. Sản xuất cái gì? sản xuất như thế nào? sản xuất cho ai?","B. Sản xuất ở đâu? sản xuất bao lâu? giá thành sản xuất như thế nào?","C. Sản xuất với giá cả nào? sản xuất với hàng hóa gì? cung cầu ra sao?","D. Sản xuất cái gì? sản xuất ở đâu? giá thành sản xuất như thế nào?"],"answerLetter":"A","answerText":"A. Sản xuất cái gì? sản xuất như thế nào? sản xuất cho ai?","notes":""},{"id":199,"question":"Xuất khẩu tư bản là gì?","options":["A. Đặc điểm của chủ nghĩa tư bản tự do cạnh tranh","B. Mang tư bản đầu tư ở nước ngoài để sản xuất giá trị thặng dư tại nước ngoài sở tại","C. Mang hàng hóa ra nước ngoài để thực hiện giá trị của hàng hóa","D. Mang tư bản ra nước ngoài mua nguyên nhiên vật liệu sản xuất"],"answerLetter":"B","answerText":"B. Mang tư bản đầu tư ở nước ngoài để sản xuất giá trị thặng dư tại nước ngoài sở tại","notes":""},{"id":200,"question":"Chỉ có sản phẩm của những lao động tư nhân độc lập và không phụ thuộc vào nhau mới đối diện với nhau như(NHUNG HOÀNG)","options":["A. Những hàng hóa","B. Những sản vật trao đổi","C. Những sản phẩm trao đổi"],"answerLetter":"A","answerText":"A. Những hàng hóa","notes":""},{"id":201,"question":"Căn cứ vào đâu để chia ra thành tái sản xuất giản đơn và tái sản xuất mở rộng?","options":["A. Căn cứ vào phạm vi","B. Căn cứ vào nội dung","C. Căn cứ vào quy mô"],"answerLetter":"C","answerText":"C. Căn cứ vào quy mô","notes":""},{"id":202,"question":"Điền vào chỗ trống. C. Mác và Ph. Ăngghen đã nhận xét rằng:\"Giai cấp tư sản, trong quá trình thống trị giai cấp chưa đầy một thế kỉ, đã tạo ra những ... nhiều hơn và đồ sộ hơn ... của tất cả các thế hệ trước kia gộp lại\"","options":["A. Lực lượng sản xuất... lực lượng sản xuất","B. Quan hệ sản xuất. quan hệ sản xuất","C. Của cải của cải","D. Vật chất... vật chất"],"answerLetter":"A","answerText":"A. Lực lượng sản xuất... lực lượng sản xuất","notes":""},{"id":203,"question":"Trong kinh tế hàng hóa, cạnh tranh có tác dụng.","options":["A. Nó làm cho sản xuất thiếu tính nhân văn","B. Nó buộc người sản xuất phải thường xuyên năng động, nhạy bén.","C. Nó làm cho sản xuất mang tính nhân văn hơn"],"answerLetter":"B","answerText":"B. Nó buộc người sản xuất phải thường xuyên năng động, nhạy bén.","notes":""},{"id":204,"question":"Lượng lợi nhuận có thể là (NHUNG HOÀNG)","options":["A. Bằng hoặc thấp hơn lượng giá trị thặng dư","B. Cao hơn hoặc thấp hơn lượng giá trị thặng dư","C. Bằng, cao hơn hoặc thấp hơn lượng giá trị thặng dư","D. Bằng, hoặc cao hơn lượng giá trị thặng dư"],"answerLetter":"C","answerText":"C. Bằng, cao hơn hoặc thấp hơn lượng giá trị thặng dư","notes":""},{"id":205,"question":"Tăng năng suất lao động và tăng cường độ lao động giống nhau ở:","options":["A. Đều làm tăng số hàng hóa sản xuất ra trong một thời gian","B. Đều làm tăng lượng lao động hao phí trong 1 đơn vị thời gian","C. Đều làm giá trị đơn vị hàng hoá giảm"],"answerLetter":"A","answerText":"A. Đều làm tăng số hàng hóa sản xuất ra trong một thời gian","notes":""},{"id":206,"question":"Những hạn chế của chủ nghĩa tư bản bao gồm: (chọn nhiều phương án).","options":["A. Mục đích của nên sản xuất tư bản chủ nghĩa vẫn tập trung chủ yếu vì lợi ích của thiểu số giai cấp tư sản","B. Chủ nghĩa tư bản đã và đang tiếp tục gây ra chiến tranh và xung đột nhiều nơi trên thế giới.","C. Sự phân hóa giàu nghèo trong lòng các nước tư bản có xu hướng ngày càng sâu sắc.","D. Gây ra biến đối khí hậu và môi trường"],"answerLetter":"ABC","answerText":"A. Mục đích của nên sản xuất tư bản chủ nghĩa vẫn tập trung chủ yếu vì lợi ích của thiểu số giai cấp tư sản\nB. Chủ nghĩa tư bản đã và đang tiếp tục gây ra chiến tranh và xung đột nhiều nơi trên thế giới.\nC. Sự phân hóa giàu nghèo trong lòng các nước tư bản có xu hướng ngày càng sâu sắc.","notes":""},{"id":207,"question":"Chọn các ý không đúng về sản phẩm và hàng hoá.","options":["A. Mọi sản phẩm đều là hàng hoá","B. Mọi sản phẩm đều là kết quả của sản xuất","C. Không phải mọi sản phẩm đều là hàng hoá"],"answerLetter":"A","answerText":"A. Mọi sản phẩm đều là hàng hoá","notes":""},{"id":208,"question":"Chi phí thực tế của xã hội để sản xuất hàng hoá là","options":["A. Chi phí lao động sống và lao động quá khứ","B. Chi phí tư bản bất biến và tư bản khả biến","C. Chi phí sức lao động của toàn xã hội"],"answerLetter":"A","answerText":"A. Chi phí lao động sống và lao động quá khứ","notes":""},{"id":209,"question":"Quy luật chung của tích luỹ tư bản là gì? Ý nào sau đây không đúng.","options":["A. Giai cấp tư sản ngày càng giàu có, mâu thuẫn trong chủ nghĩa tư bản tăng lên","B. Cấu tạo hữu cơ của tư bản tăng lên","C. Quá trình bần cùng hoá giai cấp vô sản","D. Khoảng cách giàu nghèo ngày càng tăng, nạn thất nghiệp trở nên phổ biến"],"answerLetter":"A","answerText":"A. Giai cấp tư sản ngày càng giàu có, mâu thuẫn trong chủ nghĩa tư bản tăng lên","notes":"(Kiểu hỏi khác: Tích lũy tư bản là gì? A. Tư bản hóa tư liệu tiêu dùng B. Tư bản hóa giá trị thặng dư C. Tư bản hóa sức lao động D. Tư bản hóa giá trị sản xuất)"},{"id":210,"question":"Đâu không phải là đặc trưng chủ yếu của quá trình công nghiệp hóa, hiện đại hóa ở Việt Nam","options":["A. Công nghiệp hóa, hiện đại hóa gắn liền với phát triển công nghiệp nặng","B. Công nghiệp hóa, hiện đại hóa trong điều kiện nền kinh tế thị trường, định hướng xã hội chủ nghĩa","C. Công nghiệp hóa, hiện đại hóa trong bối cảnh toàn cầu hóa kinh tế quốc tế","D. Công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa"],"answerLetter":"A","answerText":"A. Công nghiệp hóa, hiện đại hóa gắn liền với phát triển công nghiệp nặng","notes":""},{"id":211,"question":"Giá trị cá biệt của hàng hoá do","options":["A. Hao phí lao động cá biệt của người sản xuất quyết định","B. Hao phí lao động cá biệt của người sản xuất nhiều hàng hoá quyết định","C. Hao phí lao động của ngành quyết định"],"answerLetter":"A","answerText":"A. Hao phí lao động cá biệt của người sản xuất quyết định","notes":""},{"id":212,"question":"Lưu thông hàng hoá dựa trên nguyên tắc ngang giá. Điều này được hiểu như thế nào là đúng?","options":["A. Giá cả của từng hàng hoá luôn luôn bằng giá trị của nó","B. Giá trị luôn luôn bằng giá cả","C. Giá cả có thể tách rời giá trị và xoay quanh giá trị của nó"],"answerLetter":"C","answerText":"C. Giá cả có thể tách rời giá trị và xoay quanh giá trị của nó","notes":""},{"id":213,"question":"Những thành tựu và hạn chế của chủ nghĩa tư bản bắt nguồn từ","options":["A. Mâu thuẫn giữa trình độ xã hội hóa cao của lực lượng sản xuất với quan hệ sở hữu tư nhân tư bản chủ nghĩa về tư liệu sản xuất.","B. Mâu thuẫn giữa giai cấp công nhân và giai cấp tư sản","C. Mâu thuẫn giữa người lao động làm thuê và giai cấp bóc lột","D. Mâu thuẫn giữa trình độ xã hội hóa của lực lượng sản xuất và quan hệ sản xuất"],"answerLetter":"A","answerText":"A. Mâu thuẫn giữa trình độ xã hội hóa cao của lực lượng sản xuất với quan hệ sở hữu tư nhân tư bản chủ nghĩa về tư liệu sản xuất.","notes":""},{"id":214,"question":"Nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam có tính chất","options":["A. Phổ biến và đặc thù","B. Phổ biến và cách mạng","C. Phổ biến và riêng biệt","D. Phổ biến và đại chúng"],"answerLetter":"A","answerText":"A. Phổ biến và đặc thù","notes":""},{"id":215,"question":"Khi phân chia thể chế theo các yếu tố cấu thành lĩnh vực cốt lõi của xã hội, thể chế được phần chia (nhiều phương án)","options":["A. Thể chế chính trị","B. Thể chế kinh tế","C. Thể chế văn hoá","D. Thể chế xã hội"],"answerLetter":"ABD","answerText":"A. Thể chế chính trị\nB. Thể chế kinh tế\nD. Thể chế xã hội","notes":""},{"id":216,"question":"Chi phí sản xuất tư bản chủ nghĩa","options":["A. Bằng giá trị hàng hóa","B. Lớn hơn giá trị hàng hóa","C. Nhỏ hơn giá trị hàng hóa","D. Không xác định"],"answerLetter":"C","answerText":"C. Nhỏ hơn giá trị hàng hóa","notes":""},{"id":217,"question":"Nhân tố nào là cơ bản thúc đẩy chủ nghĩa tư bản ra đời nhanh chóng?","options":["A. Tích luỹ nguyên thuỷ","B. Sự phát triển mạnh mẽ của phương tiện giao thông vận tải nhờ đó mở rộng giao lưu buôn bán quốc tế","C. Sự tác động của quy luật giá trị"],"answerLetter":"A","answerText":"A. Tích luỹ nguyên thuỷ","notes":""},{"id":218,"question":"Độc quyền nhà nước trong chủ nghĩa tư bản hình thành dựa trên","options":["A. Ba nguyên nhân","B. Bốn nguyên nhân","C. Hai nguyên nhân"],"answerLetter":"B","answerText":"B. Bốn nguyên nhân","notes":""},{"id":219,"question":"Công thức về giá trị hàng hóa G = c + (v+m). Trong đó (v+m) là bộ phận giá trị mới của hàng hoá, do hao phí lao động tạo ra. Vậy c là biểu hiện của giá trị nào?","options":["A. Là giá trị của những tư liệu sản xuất đã được tiêu dùng, là bộ phận lao động quá khứ đã được kết tinh trong máy móc, nguyên, nhiên, vật liệu","B. Là giá trị của những tư liệu lao động đã được tiêu hao, là bộ phận lao động quá khứ đã được kết tinh trong lao động sản xuất","C. Là tư bản khả biến điều kiện cần thiết để quá trình tạo ra giá trị thặng dư được diễn ra","D. Là tư bản ứng trước điều kiện cần để đầu tư và tái sản xuất và mở rộng quy mô sản xuất"],"answerLetter":"A","answerText":"A. Là giá trị của những tư liệu sản xuất đã được tiêu dùng, là bộ phận lao động quá khứ đã được kết tinh trong máy móc, nguyên, nhiên, vật liệu","notes":""},{"id":220,"question":"Nếu nhà tư bản trả đúng giá trị sức lao động của người công nhân, thì nhà tư bản có thu được giá trị thặng dư hay không?","options":["A. Có","B. Không","C. Bị lỗ vốn","D. Hòa vốn"],"answerLetter":"A","answerText":"A. Có","notes":""},{"id":221,"question":"Phương thức sản xuất tư bản chủ nghĩa được thiết lập và phát triển qua các giai đoạn nào sau đây:","options":["A. Chủ nghĩa tư bản độc quyền","B. Chủ nghĩa tư bản tự do cạnh tranh","C. Chủ nghĩa tư bản tự do cạnh tranh và chủ nghĩa tư bản độc quyền.","D. Chủ nghĩa tư bản hiện đại"],"answerLetter":"C","answerText":"C. Chủ nghĩa tư bản tự do cạnh tranh và chủ nghĩa tư bản độc quyền.","notes":""},{"id":222,"question":"Trong các nhà kinh điển của chủ nghĩa Mác - Lênin, ai là người khái quát về nguyên nhân ra đời của chủ nghĩa tư bản độc quyền bằng câu: \"tự do cạnh tranh đẻ ra tập trung sản xuất và sự tập trung sản xuất này, khi phát triển tới một mức độ nhất định lại dẫn tới độc quyền\".","options":["A. Ph. Ăngghen","B. C. Mác","C. Ph. Ăngghen và C. Mác","D. V.I.Lêinin."],"answerLetter":"D","answerText":"D. V.I.Lêinin.","notes":""},{"id":223,"question":"Mọi tư bản đều biểu hiện dưới dạng tiền, nhưng tiền không phải là tư bản. Vậy khi nào tiền trở thành tư bản?","options":["A. Tiền biến thành tư bản khi được dùng để mang lại giá trị thặng dư.","B. Tiền biến thành tư bản khi được dùng để mang lại địa vị làm chủ nhà tư bản.","C. Tiền biến thành tư bản khi được dùng để mang lại giá trị chung cho toàn xã hội.","D. Tiền biến thành tư bản khi được dùng với vai trò là một phương tiện thanh toán."],"answerLetter":"A","answerText":"A. Tiền biến thành tư bản khi được dùng để mang lại giá trị thặng dư.","notes":""},{"id":224,"question":"Sự khác biệt về mục tiêu giữa kinh tế thị trường định hướng xã hội chủ nghĩa với kinh tế thị trường tư bản chủ nghĩa là gì? (lựa chọn ba đáp án)","options":["A. Hướng tới phát triển lực lượng sản xuất.","B. Xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội.","C. Xây dựng chế độ sở hữu - công hữu mọi tư liệu sản xuất.","D. Nâng cao đời sống nhân dân, thực hiện \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\""],"answerLetter":"ABD","answerText":"A. Hướng tới phát triển lực lượng sản xuất.\nB. Xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội.\nD. Nâng cao đời sống nhân dân, thực hiện \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\"","notes":""},{"id":225,"question":"Mục đích trực tiếp của nền sản xuất tư bản chủ nghĩa là gì?","options":["A. Tạo ra ngày càng nhiều giá trị thặng dư","B. Làm cho lao động ngày càng lệ thuộc vào tư bản","C. Sản xuất ra ngày càng nhiều của cải vật chất","D. Tạo ra ngày càng nhiều giá trị sử dụng"],"answerLetter":"A","answerText":"A. Tạo ra ngày càng nhiều giá trị thặng dư","notes":""},{"id":226,"question":"Các hình thức cơ bản của địa tô tư bản chủ nghĩa","options":["A. Địa tô chênh lệch I; địa tô chênh lệch II","B. Địa tô tuyệt đối; địa tô độc quyền","C. Địa tô chênh lệch; địa tô tuyệt đối","D. Địa tô chênh lệch; địa tô độc quyền"],"answerLetter":"C","answerText":"C. Địa tô chênh lệch; địa tô tuyệt đối","notes":""},{"id":227,"question":"Sự ra đời của chủ nghĩa tư bản độc quyền nhà nước nhằm:","options":["A. Phục vụ lợi ích của nhân dân lao động","B. Phục vụ lợi ích của tổ chức độc quyền tư nhân","C. Phục vụ lợi ích của nhà nước tư sản","D. Phục vụ lợi ích của tổ chức độc quyền tư nhân và cứu nguy cho chủ nghĩa tư bản."],"answerLetter":"D","answerText":"D. Phục vụ lợi ích của tổ chức độc quyền tư nhân và cứu nguy cho chủ nghĩa tư bản.","notes":""},{"id":228,"question":"Trong lĩnh vực chính trị, các chính phụ nghị viện tự sản hiện đại được tổ chức giống với mô hình nào?","options":["A. Công ty cổ phần tư bản chủ nghĩa","B. Công ty trách nhiệm hữu hạn 1 thành viên","C. Công ty hợp doanh","D. Doanh nghiệp tư nhân"],"answerLetter":"A","answerText":"A. Công ty cổ phần tư bản chủ nghĩa","notes":""},{"id":229,"question":"Trong giai đoạn chủ nghĩa tư bản cạnh tranh tự do, quy luật giá trị thặng dư biểu hiện thành quy luật.","options":["A. Lợi nhuận độc quyền","B. Tỷ suất lợi nhuận bình quân","C. Lợi nhuận độc quyền cao","D. Tỷ suất giá trị thặng dư"],"answerLetter":"B","answerText":"B. Tỷ suất lợi nhuận bình quân","notes":""},{"id":230,"question":"Hai hình thức của tiền công cơ bản:","options":["A. Tiền công theo thời gian và tiền công theo lao động","B. Tiền công theo giờ và tiền công theo sản phẩm","C. Tiền công theo thời gian và tiền công theo sản phẩm","D. Tiền công theo tháng và tiền công theo sản phẩm"],"answerLetter":"C","answerText":"C. Tiền công theo thời gian và tiền công theo sản phẩm","notes":""},{"id":231,"question":"Có hai hình thức trả tiền công của nhà tư bản đó là","options":["A. Trả bằng tiền hay tư liệu sản xuất","B. Trả bằng tiền hay sản phẩm","C. Trả bằng tiền hay vàng"],"answerLetter":"B","answerText":"B. Trả bằng tiền hay sản phẩm","notes":""},{"id":232,"question":"Chọn ý đúng về tăng NSLĐ và tăng cường độ lao động:","options":["A. Tăng NSLĐ làm cho số sản phẩm làm ra trong một đơn vị thời gian tăng lên, còn giá trị 1 đơn vị hàng hoá thay đổi.","B. Tăng cường độ lao động làm cho số sản phẩm làm ra trong 1 đơn vị thời gian tăng lên, còn giá trị 1 đơn vị hàng hoá không thay đổi.","C. Tăng NSLĐ dựa trên cơ sở cải tiến kỹ thuật, nâng cao trình độ tay nghề người lao động, còn tăng cường độ lao động thuần tuý là tăng lượng lao động hao phí trong 1 đơn vị thời gian","D. Tất cả"],"answerLetter":"D","answerText":"D. Tất cả","notes":""},{"id":233,"question":"Công thức chung của tư bản phản ánh:(NHUNG HOÀNG)","options":["A. Mục đích của sản xuất, lưu thông là giá trị và giá trị thặng dư","B. Phương tiện của lưu thông tư bản là giá trị và giá trị thặng dư","C. Mục đích của sản xuất, lưu thông tư bản là giá trị và giá trị thặng dư","D. Mục đích của sản xuất, lưu thông tư bản là giá trị sử dụng và giá trị thặng dư"],"answerLetter":"C","answerText":"C. Mục đích của sản xuất, lưu thông tư bản là giá trị và giá trị thặng dư","notes":""},{"id":234,"question":"Tuần hoàn tư bản công nghiệp là sự thống nhất của ba hình thái tuần hoàn:(NHUNG HOÀNG)","options":["A. Tư bản lưu thông, tư bản sản xuất và tư bản hàng hóa","B. Tư bản tiền tệ, tư bản sủa xuất và tư bản cho vay","C. Tư bản tiền tệ, tư bản sản xuất và tư bản hàng hóa","D. Tư bản tiền tệ, tư bản trao đổi và tư bản hàng hóa"],"answerLetter":"C","answerText":"C. Tư bản tiền tệ, tư bản sản xuất và tư bản hàng hóa","notes":"(Kiểu hỏi khác: Ba giai đoạn vận động của tuần hoàn tư bản công nghiệp là: -> Lưu thông - sản xuất - lưu thông)"},{"id":235,"question":"Nguồn gốc chủ yếu của tích lũy tư bản là:(NHUNG HOÀNG)","options":["A. Lợi nhuận bình quân","B. Giá trị lao động","C. Giá trị thặng dư","D. Giá trị trao đổi"],"answerLetter":"C","answerText":"C. Giá trị thặng dư","notes":""},{"id":236,"question":"Tiền lương tính theo sản phẩm là:","options":["A. Tiền lương được trả căn cứ vào số lượng sản phẩm người công nhân làm ra","B. Tiền lương được trả căn cứ vào chất lượng sản phẩm mà người công nhân làm ra","C. Tiền lương được trả căn cứ vào số lượng và chất lượng sản phẩm mà người công nhân làm ra","D. Tiền lương được trả căn cứ vào sản phẩm mà người công nhân làm ra"],"answerLetter":"C","answerText":"C. Tiền lương được trả căn cứ vào số lượng và chất lượng sản phẩm mà người công nhân làm ra","notes":""},{"id":237,"question":"Mức độ giàu có của xã hội phụ thuộc chủ yếu vào:","options":["A. Trình độ khoa học công nghệ","B. Tài nguyên thiên nhiên","C. Khối lượng sản phẩm thặng dư"],"answerLetter":"A","answerText":"A. Trình độ khoa học công nghệ","notes":""},{"id":238,"question":"Tư bản bất biến (c) và tư bản khả biến (v) thuộc phạm trù tư bản nào?","options":["A. Tư bản tiền tệ.","B. Tư bản sản xuất.","C. Tư bản hàng hoá."],"answerLetter":"A","answerText":"A. Tư bản tiền tệ.","notes":""},{"id":239,"question":"Tiền công tư bản có hai hình thức đó là","options":["A. Tiền công cơ bản và tiền công phụ thêm","B. Tiền công thực tế và tiền công danh nghĩa","C. Tiền mặt và hàng hóa"],"answerLetter":"B","answerText":"B. Tiền công thực tế và tiền công danh nghĩa","notes":""},{"id":240,"question":"Chủ nghĩa tư bản độc quyền nhà nước hình thành rõ nét từ:","options":["A. Thế kỷ XIX","B. Cuối thể kỷ XIX - đầu thế kỷ XX","C. Giữa thế kỷ XX","D. Đầu thế kỷ XXI"],"answerLetter":"C","answerText":"C. Giữa thế kỷ XX","notes":""},{"id":241,"question":"Về lượng tỷ suất lợi nhuận (p') là:","options":["A. Luôn luôn nhỏ hơn giá trị thặng dư","B. Luôn luôn lớn hơn tỷ suất giá trị thặng dư","C. Luôn luôn bằng tỷ suất giá trị thặng dư","D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư"],"answerLetter":"D","answerText":"D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư","notes":""},{"id":242,"question":"Giá trị thặng dư tương đối có được do:","options":["A. Tăng sản lượng, làm rút ngắn thời gian lao động cần thiết","B. Tăng cường độ lao động, rút ngắn thời gian lao động cần thiết","C. Tăng năng suất lao động, làm rút ngắn thời gian lao động cần thiết","D. Tăng năng suất lao động, làm rút ngắn thời gian lao động cá biệt"],"answerLetter":"C","answerText":"C. Tăng năng suất lao động, làm rút ngắn thời gian lao động cần thiết","notes":""},{"id":243,"question":"Tập trung tư bản là:","options":["A. Quá trình liên kết, hợp nhất các tư bản xã hội trong xã hội thành một tư bản lớn hơn","B. Quá trình liên kết, hợp nhất các tư bản tiền tệ trong xã hội thành một tư bản lớn hơn","C. Quá trình liên kết, hợp nhất các tư bản cá biệt trong xã hội thành một tư bản lớn hơn","D. Quá trình liên kết, hợp nhất các tư bản thương nghiệp trong xã hội thành một tư bản lớn hơ"],"answerLetter":"C","answerText":"C. Quá trình liên kết, hợp nhất các tư bản cá biệt trong xã hội thành một tư bản lớn hơn","notes":""},{"id":244,"question":"Thế nào là lao động cụ thể?","options":["A. Là những lao động có thể quan sát được, nhìn thấy được","B. Là những lao động ngành nghề","C. Là hoạt động có mục đích của con người","D. Là những lao động ngành nghề cụ thể, có mục đích riêng, có đối tượng riêng, thao tác riêng và kết quả riêng"],"answerLetter":"D","answerText":"D. Là những lao động ngành nghề cụ thể, có mục đích riêng, có đối tượng riêng, thao tác riêng và kết quả riêng","notes":""},{"id":245,"question":"Xét về giá trị của hàng hóa, hàng hóa càng khan hiếm thì(NHUNG HOÀNG)","options":["A. Giá trị của nó càng cao","B. Giá cả của nó càng cao","C. Cả giá trị và giá cả của hàng hóa càng cao"],"answerLetter":"B","answerText":"B. Giá cả của nó càng cao","notes":""},{"id":246,"question":"Các phương thức sản xuất nối tiếp nhau trong lịch sử theo trình tự nào?","options":["A. Chiếm hữu nô lệ - phong kiến - tư bản - chủ nghĩa cộng sản.","B. Cộng sản nguyên thuỷ - phong kiến - chiếm hữu nô lệ - tư bản - chủ nghĩa cộng sản","C. Chiếm hữu nô lệ - cộng sản nguyên thuỷ - phong kiến - tư bản - chủ nghĩa cộng sản","D. Cộng sản nguyên thuỷ- chiếm hữu nô lệ - phong kiến - tư bản- chủ nghĩa cộng"],"answerLetter":"D","answerText":"D. Cộng sản nguyên thuỷ- chiếm hữu nô lệ - phong kiến - tư bản- chủ nghĩa cộng","notes":""},{"id":247,"question":"Sản xuất hàng hoá xuất hiện dựa trên:","options":["A. Phân công lao động xã hội và chế độ tư hữu hoặc những hình thức sở hữu khác nhau về TLSX.","B. Phân công lao động cá biệt và chế độ tư hữu về tư liệu sản xuất","C. Phân công lao động chung và chế độ sở hữu khác nhau về TLSX"],"answerLetter":"A","answerText":"A. Phân công lao động xã hội và chế độ tư hữu hoặc những hình thức sở hữu khác nhau về TLSX.","notes":""},{"id":248,"question":"Sức lao động là:","options":["A. Toàn bộ sức thể lực tồn tại trong mỗi con người","B. Toàn bộ sức thể lực và trí lực tồn tại trong mỗi con người","C. Toàn bộ sức trí lực tồn tại trong mỗi con người","D. Toàn bộ sức thể lực và trí lực tồn tại không có khả năng đem ra sử dụng"],"answerLetter":"B","answerText":"B. Toàn bộ sức thể lực và trí lực tồn tại trong mỗi con người","notes":""},{"id":249,"question":"Tư bản khả biến (V) là:","options":["A. Bộ phận trực tiếp tạo ra giá trị sử dung","B. Bộ phận trực tiếp tạo ra sản phẩm","C. Bộ phận trực tiếp tạo ra giá trị thặng dư","D. Bộ phận gián tiếp tạo ra giá trị thặng dư"],"answerLetter":"C","answerText":"C. Bộ phận trực tiếp tạo ra giá trị thặng dư","notes":""},{"id":250,"question":"Giá trị sức lao động được đo gián tiếp bằng:","options":["A. Giá trị của những tư liệu sản xuất để nuôi sống người lao động","B. Giá trị của những tư liệu tiêu dùng để nuôi sống người lao động","C. Giá cả của những tư liệu tiêu dùng để nuôi sống bản thân người lao động","D. Giá trị của những tư liệu tiêu dùng để nuôi sống nhà tư bản"],"answerLetter":"B","answerText":"B. Giá trị của những tư liệu tiêu dùng để nuôi sống người lao động","notes":""},{"id":251,"question":"Mâu thuẫn cơ bản của sản xuất hàng hóa là gì?(NHUNG HOÀNG)","options":["A. Là mâu thuẫn giữa lao động tư nhân và lao động xã hội","B. Là mâu thuẫn giữa lao động cụ thể và lao động trừu tượng","C. Là mâu thuẫn giữa giá trị sử dụng và giá trị","D. Là mâu thuẫn giữa giá trị và giá cả hàng hóa"],"answerLetter":"A","answerText":"A. Là mâu thuẫn giữa lao động tư nhân và lao động xã hội","notes":""},{"id":252,"question":"Hai hàng hoá trao đổi được với nhau vì:","options":["A. có lượng thời gian hao phí lao động xã hội cần thiết để sản xuất ra chúng bằng nhau.","B. Chúng cùng là sản phẩm của lao động.","C. Các phương án trả lời đều đúng"],"answerLetter":"C","answerText":"C. Các phương án trả lời đều đúng","notes":""},{"id":253,"question":"Khi nghiên cứu phương thức sản xuất TBCN, C.Mác bắt đầu từ","options":["A. Sản xuất hàng hoá giản đơn và hàng hoá","B. Lưu thông hàng hoá","C. Sản xuất giá trị thặng dư","D. Quy luật cung cầu"],"answerLetter":"A","answerText":"A. Sản xuất hàng hoá giản đơn và hàng hoá","notes":""},{"id":254,"question":"Trong những trường hợp nào sau đây của hao phí lao động cá biệt, trường hợp nào không đáp ứng yêu cầu của quy luật giá trị?","options":["A. Hao phí lao động cá biệt < hao phí lao động xã hội cần thiết","B. Hao phí lao động cá biệt = hao phí lao động xã hội cần thiết","C. Hao phí lao động cá biệt > hao phí lao động xã hội cần thiêt"],"answerLetter":"C","answerText":"C. Hao phí lao động cá biệt > hao phí lao động xã hội cần thiêt","notes":""},{"id":255,"question":"Giá trị sử dụng của hàng hóa sức lao động được coi là:","options":["A. Chìa khóa để giải quyết mâu thuẫn giữa tư bản và tư bản","B. Chìa khóa để giải quyết mâu thuẫn trong lưu thông hàng hóa","C. Chìa khóa để giải quyết mâu thuẫn giữa tư bản và lao động","D. Chìa khóa để giải quyết mâu thuẫn công thức chung của tư bản"],"answerLetter":"D","answerText":"D. Chìa khóa để giải quyết mâu thuẫn công thức chung của tư bản","notes":""},{"id":256,"question":"Phân công lao động xã hội được xác định là(NHUNG HOÀNG)","options":["A. Không dẫn đến sự hình thành tư bản độc quyền","B. Một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền","C. Nguyên nhân hình thành chủ nghĩa tư bản","D. Là một trong những nguyên nhân hình thành độc quyền nhà nước trong chủ nghĩa tư bản"],"answerLetter":"B","answerText":"B. Một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền","notes":""},{"id":257,"question":"Giá trị xã hội của hàng hoá công nghiệp và nông nghiệp giống nhau ở chỗ dựa trên:(NHUNG HOÀNG)","options":["A. Hao phí lao động xã hội cần thiết","B. Hao phí lao động xã hội trong điều kiện sản xuất trung bình","C. Hao phí lao động xã hội trong điều kiện sản xuất khó khăn nhất"],"answerLetter":"A","answerText":"A. Hao phí lao động xã hội cần thiết","notes":""},{"id":258,"question":"Trên giác độ KTCT, chi phí sản xuất tư bản được quan điểm là:","options":["A. Chi phí tư bản (c) và (v).","B. Tổng số tiền nhà tư bản ứng ra.","C. Số tiền nhà tư bản mua máy móc, nguyên vật liệu."],"answerLetter":"A","answerText":"A. Chi phí tư bản (c) và (v).","notes":""},{"id":259,"question":"Trong quan hệ với cường độ lao động, lượng giá trị của đơn vị hàng hoá(NHUNG HOÀNG)","options":["A. Không phụ thuộc vào cường độ lao động","B. Tỷ lệ thuận với cường độ lao động","C. Tỷ lệ nghịch với cường độ lao động"],"answerLetter":"A","answerText":"A. Không phụ thuộc vào cường độ lao động","notes":""},{"id":260,"question":"Quan hệ cung cầu thuộc khâu nào của quá trình tái sản xuất xã hội?","options":["A. Sản xuất và tiêu dùng","B. Phân phối và trao đổi","C. Tiêu dùng"],"answerLetter":"A","answerText":"A. Sản xuất và tiêu dùng","notes":""},{"id":261,"question":"Khi nào tiền tệ ra đời?","options":["A. Khi sản xuất và trao đổi đã phát triển","B. Khi vật ngang giá chung được cố định ở vàng, bạc","C. Khi không còn quan hệ trao đổi trực tiếp, có một thứ hàng làm trung gian trong trao đổi","D. Khi nhu cầu trao đổi vượt quá phạm vi quốc gia"],"answerLetter":"B","answerText":"B. Khi vật ngang giá chung được cố định ở vàng, bạc","notes":""},{"id":262,"question":"Chọn định nghĩa chính xác về tư bản:","options":["A. Tư bản là giá trị mang lại giá trị thặng dư.","B. Tư bản là tiền và TLSX của nhà tư bản để tạo ra giá trị thặng dư.","C. Tư bản là giá trị đem lại giá trị thặng dư bằng cách bóc lột lao động làm thuê."],"answerLetter":"C","answerText":"C. Tư bản là giá trị đem lại giá trị thặng dư bằng cách bóc lột lao động làm thuê.","notes":""},{"id":263,"question":"Vì sao hàng hóa có hai thuộc tính là giá trị và giá trị sử dụng?","options":["A. Vì lao động sản xuất hàng hóa có tính hai mặt là : lao động cụ thể và lao động trừu tượng","B. Vì có lao động giản đơn và lao động phức tạp","C. Vì có lao động quá khứ và lao động sống","D. Vì nhu cầu trong trao đổi hàng hóa"],"answerLetter":"A","answerText":"A. Vì lao động sản xuất hàng hóa có tính hai mặt là : lao động cụ thể và lao động trừu tượng","notes":""},{"id":264,"question":"Căn cứ vào đâu để phân chia tư bản cố định và tư bản lưu động?","options":["A. Căn cứ vào tính chất chuyển giá trị sử dụng của nó vào trong sản phẩm mới","B. Căn cứ vào tính chất chuyển giá trị của nó vào trong sản phẩm cũ","C. Căn cứ vào tính chất chuyển giá trị của nó vào trong sản phẩm mới","D. Căn cứ vào tính chất chuyển giá trị thặng dư của nó vào trong sản phẩm mới"],"answerLetter":"C","answerText":"C. Căn cứ vào tính chất chuyển giá trị của nó vào trong sản phẩm mới","notes":""},{"id":265,"question":"Thuật ngữ \"kinh tế- chính trị\" được sử dụng lần đầu tiên vào năm nào?","options":["A. 1615","B. 1616","C. 1617"],"answerLetter":"A","answerText":"A. 1615","notes":"(Kiểu hỏi khác: Ai là người đầu tiên đưa ra khái niệm \"kinh tế- chính trị\"? a. Francois Quesney b. Antoine Montchretiên c. William Petty)"},{"id":266,"question":"Để làm rõ vai trò của các bộ phận tư bản trong việc tạo ra giá trị thặng dư, tư bản được chia thành(NHUNG HOÀNG)","options":["A. Tư bản độc quyền và tư bản nhà nước","B. Tư bản bất biến và tư bản khả biến","C. Tư bản cố định và tư bản lưu động"],"answerLetter":"B","answerText":"B. Tư bản bất biến và tư bản khả biến","notes":""},{"id":267,"question":"Thế nào là sản xuất tự cung, tự cấp?(NHUNG HOÀNG)","options":["A. Quá trình sản xuất chỉ có hai khâu: sản xuất và tiên dùng","B. Sản xuất có tính chất khép kín","C. Là một kiểu tổ chức kinh tế trong đó những sản phẩm được sản xuất ra nhằm mục đích thỏa mãn nhu cầu tiêu dùng của bản thân người sản xuất","D. Sản xuất và tái sản xuất"],"answerLetter":"C","answerText":"C. Là một kiểu tổ chức kinh tế trong đó những sản phẩm được sản xuất ra nhằm mục đích thỏa mãn nhu cầu tiêu dùng của bản thân người sản xuất","notes":""},{"id":268,"question":"Thế nào là lao động phức tạp?","options":["A. Là lao động phải trải qua đào tạo, huấn luyện mới làm được","B. Là lao động tạo ra các sản phẩm chất lượng cao, tinh vi","C. Là lao động có nhiều thao tác phức tạp"],"answerLetter":"A","answerText":"A. Là lao động phải trải qua đào tạo, huấn luyện mới làm được","notes":""},{"id":269,"question":"Khi lạm phát phi mã xảy ra, hình thức sử dụng tiền nào có lợi nhất?","options":["A. Mua hàng hoá hoặc vàng cất giữ","B. Gửi ngân hàng","C. Đầu tư vào sản xuất kinh doanh"],"answerLetter":"A","answerText":"A. Mua hàng hoá hoặc vàng cất giữ","notes":""},{"id":270,"question":"Điều kiện để tiền biến thành tư bản là:","options":["A. Phải tích lũy được một lượng tiền lớn; tiền không được đưa vào kinh doanh với mục đích thu giá trị thặng dư","B. Phải tích lũy được một lượng tiền lớn; tiền phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư","C. Phải tích lũy được một lượng hàng hóa lớn; hàng hóa phải được đưa vào kinh doanh tư bản với mục"],"answerLetter":"B","answerText":"B. Phải tích lũy được một lượng tiền lớn; tiền phải được đưa vào kinh doanh tư bản với mục đích thu giá trị thặng dư","notes":""},{"id":271,"question":"Quy luật kinh tế cơ bản của chủ nghĩa tư bản là(NHUNG HOÀNG)","options":["A. Quy luật đấu tranh giai cấp","B. Quy luật giá trị","C. Quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất"],"answerLetter":"B","answerText":"B. Quy luật giá trị","notes":""},{"id":272,"question":"Cặp phạm trù nào là phát hiện riêng của C.Mác?","options":["A. Lao động cụ thể và lao động trừu tượng","B. Lao động giản đơn và lao động phức tạp","C. Lao động tư nhân và lao động xã hội"],"answerLetter":"A","answerText":"A. Lao động cụ thể và lao động trừu tượng","notes":""},{"id":273,"question":"Học thuyết kinh tế nào của C.Mác được coi là hòn đá tảng","options":["A. Lợi nhuận","B. Học thuyết tiền tệ","C. Học thuyết cung cầu","D. Học thuyết giá trị thặng dư"],"answerLetter":"D","answerText":"D. Học thuyết giá trị thặng dư","notes":""},{"id":274,"question":"Điều kiện để ra đời và tồn tại của sản xuất hàng hóa:(NHUNG HOÀNG)","options":["A. Số lượng hàng hoá làm ra trong một đơn vị thời gian tăng lên","B. Số lượng lao động hao phí trong thời gian đó không thay đổi","C. Giá trị 1 đơn vị hàng hoá giảm đi"],"answerLetter":"A","answerText":"A. Số lượng hàng hoá làm ra trong một đơn vị thời gian tăng lên","notes":""},{"id":275,"question":"Lượng giá trị của hàng hóa là yếu tố(NHUNG HOÀNG)","options":["A. Cố định","B. Luôn luôn thay đổi","C. Tùy thuộc vào nền sản xuất hàng hóa"],"answerLetter":"A","answerText":"A. Cố định","notes":""},{"id":276,"question":"Về bản chất lợi nhuận và giá trị thặng dư đều là:","options":["A. Lao động cụ thể của người công nhân","B. Lao động không công của người công nhân","C. Lao động trừu tượng của người công nhân","D. Lao động phức tạp của người công nhân"],"answerLetter":"B","answerText":"B. Lao động không công của người công nhân","notes":""},{"id":277,"question":"Điểm giống nhau giữa tăng năng suất lao động và tăng cường độ lao động?","options":["A. Đều làm giảm giá trị của một đơn vị hàng hóa","B. Đều làm tăng thêm sản lượng sản phẩm được sản xuất ra trong một đơn vị thời gian","C. Đều làm tăng lượng lao động hao phí trong một đơn vị thời gian","D. Đều gắn với tiến bộ kỹ thuật"],"answerLetter":"B","answerText":"B. Đều làm tăng thêm sản lượng sản phẩm được sản xuất ra trong một đơn vị thời gian","notes":""},{"id":278,"question":"Dựa vào căn cứ nào để chia tư bản thành tư bản bất biến và tư bản khả biến (c & v)","options":["A. Phương thức chuyển giá trị các bộ phận tư bản sang sản phẩm","B. Vai trò các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư","C. Tốc độ chu chuyển của tư bản"],"answerLetter":"B","answerText":"B. Vai trò các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư","notes":""},{"id":279,"question":"Tư bản bất biến(NHUNG HOÀNG)","options":["A. Là giá trị tư liệu sản xuất, giá trị của nó tăng lên sau quá trình sản xuất","B. Là giá trị tư liệu sản xuất, giá trị của nó giảm đi sau quá trình sản xuất","C. Là giá trị tư liệu sản xuất, giá trị của nó không thay đổi sau quá trình sản xuất","D. Là giá trị tư liệu sản xuất, giá trị sử dụng của nó được bảo tồn và chuyển vào sản phẩm"],"answerLetter":"C","answerText":"C. Là giá trị tư liệu sản xuất, giá trị của nó không thay đổi sau quá trình sản xuất","notes":""},{"id":280,"question":"Giá trị thặng dư là:","options":["A. Là phần lao động được trả công của công nhân","B. Là phần lao dộng không công của công nhân","C. Là toàn bộ lao động của công nhân","D. Là lao động sáng tạo của công nhân"],"answerLetter":"B","answerText":"B. Là phần lao dộng không công của công nhân","notes":""},{"id":281,"question":"Giá trị sử dụng của hàng hóa là khái niệm dùng để chỉ(NHUNG HOÀNG)","options":["A. Mức độ khan hiếm của hàng hóa","B. Giá trị trao đổi của hàng hóa","C. Công dụng của hàng hóa"],"answerLetter":"C","answerText":"C. Công dụng của hàng hóa","notes":""},{"id":282,"question":"Nguồn gốc của giá trị hàng hóa được tạo ra từ đầu?(NHUNG HOÀNG)","options":["A. Từ sản xuất","B. Từ lưu thông","C. Cà sản xuất và lưu thông","D. Từ những kết quả của sự phát minh"],"answerLetter":"A","answerText":"A. Từ sản xuất","notes":"(Kiểu hỏi khác: Trong các yếu tố sau đây, yếu tố nào là nguồn gốc của giá trị hàng hóa? -> Lao động con người)"},{"id":283,"question":"Chọn phương án đúng về quy luật kinh tế:","options":["A. Quy luật kinh tế là quy luật xã hội do con người đặt ra, là quy luật khách quan phát sinh tác dụng qua hoạt động kinh tế của con người.","B. Quy luật kinh tế có tính lịch sử","C. Các phương án trả lời đều đúng."],"answerLetter":"C","answerText":"C. Các phương án trả lời đều đúng.","notes":""},{"id":284,"question":"Trong các yếu tố sau đây, yếu tố nào được xác định là thực thể giá trị của hàng hóa?","options":["A. Lao động cụ thể","B. Lao động giản đơn","C. Lao động phức tạp","D. Lao động trừu tượng"],"answerLetter":"D","answerText":"D. Lao động trừu tượng","notes":""},{"id":285,"question":"Hao mòn hữu hình là:","options":["A. Hao mòn vật chất do quá trình sử dụng hoặc do tác động của con người","B. Hao mòn phi vật chất do quá trình sự dụng hoặc do sự tác động của tự nhiên","C. Hao mòn vật chất do quá trình sử dụng hoặc do tác động của tự nhiên","D. Hao mòn vô hình do quá trình sử dụng hoặc do tác động của tự nhiên"],"answerLetter":"C","answerText":"C. Hao mòn vật chất do quá trình sử dụng hoặc do tác động của tự nhiên","notes":""},{"id":286,"question":"Trong thời đại ngày nay, lực lượng sản xuất bao gồm các yếu tố nào?","options":["A. Người lao động","B. Tư liệu sản xuất","C. Khoa học công nghệ","D. Tất cả các phương án trả lời đều đúng."],"answerLetter":"D","answerText":"D. Tất cả các phương án trả lời đều đúng.","notes":""},{"id":287,"question":"Đảng cộng sản Việt Nam là đảng cầm quyền do yếu tố nào sau đây quy định?","options":["A. Lịch sử chủ quan","B. Chính trị chủ quan","C. Lịch sử khách quan","D. Do nhân dân lao động lựa chọn"],"answerLetter":"C","answerText":"C. Lịch sử khách quan","notes":""},{"id":288,"question":"Thông qua việc giải quyết các quan hệ nào để từ đó giúp cho các chủ thể trong xã hội vận dụng các quy luật kinh tế, tạo động lực để không ngừng sáng tạo, ển toàn diện?","options":["A. Quan hệ xã hội.","B. Quan hệ Pháp luật.","C. Quan hệ lợi ích.","D. Quan hệ quốc tế."],"answerLetter":"C","answerText":"C. Quan hệ lợi ích.","notes":""},{"id":289,"question":"Về lượng (hỏi về lượng) tỷ suất lợi nhuận (p') là:","options":["A. Luôn luôn nhỏ hơn giá trị thặng dư","B. Luôn luôn lớn hơn tỷ suất giá trị thặng dư","C. Luôn luôn bằng tỷ suất giá trị thặng dư","D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư."],"answerLetter":"D","answerText":"D. Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư.","notes":""},{"id":290,"question":"Quy luật căn bản của sản xuất và lưu thông hàng hóa là quy luật nào?","options":["A. Quy luật cạnh tranh","B. Quy luật cung - cầu","C. Quuy luật lưu thông tiền tệ","D. Quy luật giá trị."],"answerLetter":"D","answerText":"D. Quy luật giá trị.","notes":""},{"id":291,"question":"Tư liệu lao động gồm có:","options":["A. Công cụ lao động","B. Các vật để chứa đựng, bảo quản","C. Kết cấu hạ tầng sản xuất","D. Các phương án trả lới đều đúng."],"answerLetter":"D","answerText":"D. Các phương án trả lới đều đúng.","notes":""},{"id":292,"question":"Những chức năng nào của tiền tệ đòi hỏi phải có tiền vàng?","options":["A. Tất cả các chức năng của tiền tệ","B. Chỉ có chức năng thước đo giá trị","C. Chức năng thước đo giá trị, chức năng tích lũy và chức năng cất trữ","D. Chức năng thước đo giá trị; chức năng tích lũy, cất trữ và chức năng tiền tệ thế giới."],"answerLetter":"D","answerText":"D. Chức năng thước đo giá trị; chức năng tích lũy, cất trữ và chức năng tiền tệ thế giới.","notes":"(Theo kinh tế - chính trị Mác - Lênin, loại tiền nào có chức năng cất trữ? A. Tiên giấy B. Tiền điện tủ C. Tiền vàng D. Bitcoin)"},{"id":293,"question":"Mục tiêu của kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam là gì? Chọn hai đáp án.","options":["A. Xây dựng cơ sở vật chất cho chủ nghĩa xã hội và nâng cao đời sống nhân dân.","B. Tối đa hóa lợi nhuận cho các doanh nghiệp tư nhân.","C. Hướng tôi dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","D. Giảm thiểu vai trò của Nhà nước trong quản lý kinh tế."],"answerLetter":"AC","answerText":"A. Xây dựng cơ sở vật chất cho chủ nghĩa xã hội và nâng cao đời sống nhân dân.\nC. Hướng tôi dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","notes":""},{"id":294,"question":"Mục tiêu phát triển kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam bao gồm những giá trị nào?","options":["A. Tăng trưởng kinh tế không đi kèm với tiến bộ xã hội.","B. Đảm bảo dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","C. Phát triển kinh tế gắn với phân bổ nguồn lực hợp lý và tiết kiệm.","D. Tăng cường sự can thiệp của Nhà nước vào các hoạt động kinh tế."],"answerLetter":"B","answerText":"B. Đảm bảo dân giàu, nước mạnh, dân chủ, công bằng, văn minh.","notes":""},{"id":295,"question":"Thế nào là phân công lao động xã hội?(NHUNG HOÀNG)","options":["A. Là phân công của xã hội về lao động hình thành những nghành nghề, nghề sản xuất khác nhau. Là sự chuyên môn hóa nhất định đối với người sản xuất","B. Là phân công diễn ra trong đơn vị sản xuất","C. Là sự chuyên môn hóa nhất định đối với người sản xuất","D. Là chia nhỏ quá trình sản xuất, mỗi người chuyên đảm nhận một công đoạn"],"answerLetter":"A","answerText":"A. Là phân công của xã hội về lao động hình thành những nghành nghề, nghề sản xuất khác nhau. Là sự chuyên môn hóa nhất định đối với người sản xuất","notes":""},{"id":296,"question":"Tái sản xuất tư bản gồm có hai hình thức cơ bản đó là","options":["A. Tái sản xuất giản đơn và tái sản xuất mở rộng","B. Tái sản xuất theo chiều rộng và tái sản xuất theo chiều sâu","C. Tái sản xuất tư bản xã hội và tái sản xuất tư bản tư nhân"],"answerLetter":"A","answerText":"A. Tái sản xuất giản đơn và tái sản xuất mở rộng","notes":""},{"id":297,"question":"Giá trị sử dụng của hàng hóa phản ánh tính chất nào sau đây","options":["A. Tính chất tư nhân của hàng hóa","B. Tính chất xã hội của hàng hóa","C. Cả tính chất tư nhân và tính chất xã hội của hàng hóa"],"answerLetter":"B","answerText":"B. Tính chất xã hội của hàng hóa","notes":""},{"id":298,"question":"Quá trình sản xuất tư bản là quá trình sản xuất(NHUNG HOÀNG)","options":["A. Giá trị sử dụng","B. Giá trị thặng dư","C. Giá trị trao đổi"],"answerLetter":"B","answerText":"B. Giá trị thặng dư","notes":""},{"id":299,"question":"Trong kinh tế hàng hóa, lạm phát là hiện tượng kinh tế","options":["A. Bất bình thường","B. Bất ổn định","C. Bình thường"],"answerLetter":"C","answerText":"C. Bình thường","notes":""},{"id":300,"question":"Cơ sở chung của quan hệ trao đổi giữa các hàng hóa là gì?","options":["A. Là công dụng của hàng hóa","B. Là hao phí lao động kết tinh trong hàng hóa","C. Là nhu cầu của sự tiêu dùng","D. Là sự khan hiếm của hàng hóa"],"answerLetter":"B","answerText":"B. Là hao phí lao động kết tinh trong hàng hóa","notes":""},{"id":301,"question":"Chi phí sản xuất tư bản tính bằng công thức nào sau đây(NHUNG HOÀNG)","options":["A. K = c + p + m","B. K = c + v + m","C. K = c + t + m"],"answerLetter":"B","answerText":"B. K = c + v + m","notes":""},{"id":302,"question":"Tích lũy tư bản là xét về bản chất là(NHUNG HOÀNG)","options":["A. Tư bản hóa tư liệu tiêu dùng","B. Tư bản hóa giá trị thặng dư","C. Tư bản hóa sức lao động"],"answerLetter":"B","answerText":"B. Tư bản hóa giá trị thặng dư","notes":""},{"id":303,"question":"Trong sản xuất hàng hóa tồn tại song song bao nhiêu mặt","options":["A. Một mặt","B. Ba mặt","C. Hai mặt"],"answerLetter":"C","answerText":"C. Hai mặt","notes":""},{"id":304,"question":"Mục đích của sản xuất hàng hóa là thỏa mãn nhu cầu của","options":["A. Người sản xuất","B. Thị trường","C. Của người sản xuất và tiêu dùng"],"answerLetter":"B","answerText":"B. Thị trường","notes":""},{"id":305,"question":"Chủ nghĩa tư bản ra đời phải có mấy nguyên nhân(NHUNG HOÀNG)","options":["A. Bốn nguyên nhân cơ bản","B. Ba nguyên nhân cơ bản","C. Hai nguyên nhân cơ bản"],"answerLetter":"C","answerText":"C. Hai nguyên nhân cơ bản","notes":""},{"id":306,"question":"Vai trò của các bộ phận tư bản trong chu chuyển tư bản được xác định trong phạm trù nào sau đây","options":["A. Tư bản cố định và lưu thông tư bản","B. Tư bản cố định và tư bản lưu động","C. Tư bản tài chính và tư bản công nghiệp","D. Tư bản bất biến và tư bản lưu động"],"answerLetter":"B","answerText":"B. Tư bản cố định và tư bản lưu động","notes":""},{"id":307,"question":"Ai là người đầu tiên phát minh ra tính hai mặt của lao động sản xuất hàng hóa: lao động cụ thể và lao động trừu tượng?","options":["A. Đ. Ricacđô","B. C. Mác","C. Ph. Ăngghen","D. V.I. Lênin"],"answerLetter":"B","answerText":"B. C. Mác","notes":""},{"id":308,"question":"Theo quan điểm của KTCT Mác- Lênin, khủng hoảng kinh tế của chủ nghĩa tư bản mang tính(NHUNG HOÀNG)","options":["A. Chủ quan","B. Khách quan","C. Tạm thời"],"answerLetter":"B","answerText":"B. Khách quan","notes":""},{"id":309,"question":"Sản xuất hàng hóa có vai trò gì trong phân công lao động xã hội","options":["A. Là điều kiện của phân công lao động xã hội","B. Là nguồn gốc của phân công lao động xã hội","C. Các phương án trả lời đều sai"],"answerLetter":"C","answerText":"C. Các phương án trả lời đều sai","notes":""},{"id":310,"question":"Lượng giá trị hàng hóa nhiều hay ít, cao hay thấp, được xác định như thế nào?","options":["A. Xác định bằng thời gian lao động cá biệt","B. Xác định bằng thời gian lao động xã hội cần thiết","C. Xác định bằng thời gian lao động giản đơn, trung bình xã hội cần thiết"],"answerLetter":"B","answerText":"B. Xác định bằng thời gian lao động xã hội cần thiết","notes":""},{"id":311,"question":"Xét về thời gian, kinh tế hàng hóa ra đời sau","options":["A. Nền kinh tế xã hội","B. Nền kinh tế tự do","C. Nền kinh tế tự nhiên"],"answerLetter":"C","answerText":"C. Nền kinh tế tự nhiên","notes":""},{"id":312,"question":"Mâu thuẫn chung trong công thức chung của tư bản là:","options":["A. T' > T","B. T' < T","C. T' = T","D. T' > H'"],"answerLetter":"A","answerText":"A. T' > T","notes":""},{"id":313,"question":"Khối lượng giá trị thặng dư (M) được tính bằng công thức","options":["A. M = m'. K","B. M = m'. C","C. M= m'. V","D. M= m'. V'"],"answerLetter":"C","answerText":"C. M= m'. V","notes":""},{"id":314,"question":"Kinh tế thị trường định hưởng xã hội chủ nghĩa ở Việt Nam thành phần kinh tế nào giữ vai trò là một động lực quan trọng thúc đẩy phát triển kinh tế.","options":["A. Thành phần kinh tế tư nhân","B. Thành phần kinh tế nhà nước","C. Thành phần kinh tế tập thể","D. Thành phần kinh tế có vốn đầu tư nước ngoài"],"answerLetter":"A","answerText":"A. Thành phần kinh tế tư nhân","notes":""},{"id":315,"question":"Chi phí sản xuất tư bản xét về lượng luôn luôn (NHUNG HOÀNG)","options":["A. Lớn hơn chi phí sản xuất thực tế","B. Nhỏ hơn chi phí sản xuất thực tế","C. Bằng chi phí sản xuất thực tế"],"answerLetter":"B","answerText":"B. Nhỏ hơn chi phí sản xuất thực tế","notes":"(Kiểu hỏi khác: Chỉ phí sản xuất tư bản tương quan như thế nào với chi phí sản xuất thực tế? A. Lớn hơn chi phí sản xuất thực tế B. Nhỏ hơn chi phí sản xuất thực tế C. Bằng chi phí sản xuất thực tế D. Không liên quan đến chi phí sản xuất thực tế)"},{"id":316,"question":"Hàng hóa sức lao động ra đời phải dựa trên mấy điều kiện","options":["A. Ba điều kiện","B. Một điều kiện","C. Hai điều kiện"],"answerLetter":"C","answerText":"C. Hai điều kiện","notes":""},{"id":317,"question":"Trong kinh tế chính trị Mác-Lênin, cung là phạm trù kinh tế dùng để chỉ (073-356-8678)","options":["A. Mọi hàng hoá có khả năng đáp ứng nhu cầu thị trường","B. Mọi sản phẩm của lao động","C. Một số sản phẩm nhất định của thị trường"],"answerLetter":"A","answerText":"A. Mọi hàng hoá có khả năng đáp ứng nhu cầu thị trường","notes":""},{"id":318,"question":"Các nhân tố ảnh hưởng tối lượng giá trị hàng hóa: (NHUNG HOÀNG)","options":["A. Năng suất lao động; lao động phúc tạp","B. Năng suất lao động, lao động giản đơn và lao động phúc tạp","C. Lao động giản đơn; lao động phúc tạp","D. Năng suất lao động; cường độ lao động"],"answerLetter":"B","answerText":"B. Năng suất lao động, lao động giản đơn và lao động phúc tạp","notes":""},{"id":319,"question":"Tích tụ và tập trung tư bản giống nhau ở","options":["A. Đều là tăng quy mô tư bản cá biệt","B. Có nguồn gốc trực tiếp giống nhau","C. Đều là tăng quy mô tư bản xã hội"],"answerLetter":"A","answerText":"A. Đều là tăng quy mô tư bản cá biệt","notes":""},{"id":320,"question":"Giá trị thặng dư siêu ngạch là hình thức","options":["A. Biến tướng của giá trị thặng dư cố định","B. Biến tướng của giá trị thặng dư tương đối","C. Biến tưởng của giá trị thặng dư tuyệt đối"],"answerLetter":"B","answerText":"B. Biến tướng của giá trị thặng dư tương đối","notes":""},{"id":321,"question":"Phương thức sản xuất tư bản chủ nghĩa hình thành và thay thế cho phương thức sản sản xuất nào?","options":["A. Phương thức sản xuất phong kiến","B. Phương thức sản xuất chiếm hữu nô lệ","C. Phương thức sản xuất cộng sản nguyên thuỷ","D. Phương thức sản xuất cộng sản chủ nghĩa"],"answerLetter":"A","answerText":"A. Phương thức sản xuất phong kiến","notes":""},{"id":322,"question":"Điểm giống nhau giữa địa tô tuyệt đối và địa tô chênh lệch đó là","options":["A. Có nguồn gốc từ giá trị thặng dư, đều là kết quả của sự chiếm đoạt lao động thặng dư của công nhân nông nghiệp làm thuê","B. Có nguồn gốc từ lợi nhuận thu được, đều là kết quả của sự chiếm đoạt lao động thặng dư của công nhân nông nghiệp làm thuê","C. Có nguồn gốc từ giá trị thặng dư, đều là kết quả của sự chiếm đoạt lao động thặng dư của công nhân công nghiệp làm thuê","D. Có nguồn gốc từ lợi nhuận thu được, đều là kết quả của sự chiếm đoạt lao động thặng dư của công nhân công nghiệp làm thuê"],"answerLetter":"A","answerText":"A. Có nguồn gốc từ giá trị thặng dư, đều là kết quả của sự chiếm đoạt lao động thặng dư của công nhân nông nghiệp làm thuê","notes":""},{"id":323,"question":"Về mặt lịch sử, các hình thức tổ chức độc quyền cơ bản từ thấp đến cao đó là (NHUNG HOÀNG)","options":["A. Cartel - Syndicate - Trust - Consortium","B. Cartel - Trust - Syndicate - Consortium","C. Trust - Cartel - Syndicate - Consortium","D. Trust - Syndicate - Cartel - Consortium"],"answerLetter":"A","answerText":"A. Cartel - Syndicate - Trust - Consortium","notes":""},{"id":324,"question":"Nhận định nào sau đây là sai? (NHUNG HOÀNG)","options":["A. Consortium là hình thức độc quyền theo liên kết dọc","B. Các tổ chức độc quyền mở rộng ra nhiều ngành khác nhau là phát triển theo liên kết dọc.","C. Các nhà tư bản tham gia Cartel vẫn độc lập về sản xuất nhưng mất độc lập về lưu thông","D. Trust là tổ chức độc quyền cao hơn Syndicate."],"answerLetter":"C","answerText":"C. Các nhà tư bản tham gia Cartel vẫn độc lập về sản xuất nhưng mất độc lập về lưu thông","notes":""},{"id":325,"question":"Tổ chức Hợp tác và Phát triển kinh tế gọi tắt là gì?","options":["A. OECD","B. TNCS","C. GDP","D. FPT"],"answerLetter":"A","answerText":"A. OECD","notes":""},{"id":326,"question":"Sự phát triển của tư bản tài chính dẫn đến sự hình thành của","options":["A. Các nhà tài phiệt","B. Các tập đoàn tài chính","C. Các doanh nghiệp tư nhân","D. Các công ty mẹ"],"answerLetter":"A","answerText":"A. Các nhà tài phiệt","notes":""},{"id":327,"question":"Mục đích chủ yếu của các Conglomerate là thu lợi nhuận từ đâu?","options":["A. Kinh doanh chứng khoán","B. Cho vay","C. Đầu tư xuất khẩu tư bản","D. Quảng cáo"],"answerLetter":"A","answerText":"A. Kinh doanh chứng khoán","notes":""},{"id":328,"question":"Vai trò của các bộ phận tư bản trong tích lũy tư bản được xác định bằng phạm trù: (NHUNG HOÀNG)","options":["A. Cấu tạo kỹ thuật của tư bản","B. Cấu tạo hữu cơ của tư bản","C. Cấu tạo giá trị của tư bản"],"answerLetter":"C","answerText":"C. Cấu tạo giá trị của tư bản","notes":""},{"id":329,"question":"m'- Tỷ suất giá trị thặng dư là","options":["A. Tỷ lệ phần trăm giữa lượng giá trị thặng dư và tư bản bất biến.","B. Tỷ lệ phần trăm giữa lượng tư bản bất biến và tư bản khả biến.","C. Tỷ lệ phần trăm giữa lượng giá trị thặng dư và tư bản khả biến.","D. Tỷ lệ phần trăm giữa lượng sản phẩm thặng dư và tư bản khả biến."],"answerLetter":"C","answerText":"C. Tỷ lệ phần trăm giữa lượng giá trị thặng dư và tư bản khả biến.","notes":""},{"id":330,"question":"Yếu tố quyết định đến giá cả hàng hoá là","options":["A. Giá trị của hàng hoá","B. Quan hệ cung cầu về hàng hoá","C. Giá trị sử dụng của hàng hoá"],"answerLetter":"A","answerText":"A. Giá trị của hàng hoá","notes":""},{"id":331,"question":"Tăng tốc độ chu chuyển của tư bản sẽ dẫn tới? (chọn nhiêu đáp án)","options":["A. Tăng lượng tư bản lưu động được sử dụng trong năm","B. Tăng tỷ suất giá trị thặng dư","C. Tăng khối lượng giá trị thặng dư","D. Tăng trình độ bóc lột sức lao động"],"answerLetter":"ABC","answerText":"A. Tăng lượng tư bản lưu động được sử dụng trong năm\nB. Tăng tỷ suất giá trị thặng dư\nC. Tăng khối lượng giá trị thặng dư","notes":""},{"id":332,"question":"Chức năng nào của kinh tế chính trị Mác - Lênin thể hiện sự vận dụng đúng các quy luật kinh tế khách quan thông qua điều chỉnh hành vi cá nhân hoặc các chính sách kinh tế sẽ góp phần thúc đẩy kinh tế - xã hội phát triển theo hướng tiến bộ?","options":["A. Chức năng thực tiễn","B. Chức năng nhận thức","C. Chức năng tư tưởng","D. Chức năng phương pháp luận"],"answerLetter":"A","answerText":"A. Chức năng thực tiễn","notes":""},{"id":333,"question":"Tư bản cố định và tư bản lưu động thuộc phạm trù tư bản nào?","options":["A. Tư bản sản xuất","B. Tư bản tiền tệ","C. Tư bản bất biến","D. Tư bản ứng trước"],"answerLetter":"A","answerText":"A. Tư bản sản xuất","notes":""},{"id":334,"question":"Vê mặt lượng giữa p' và m' thì:","options":["A. p' luôn nhỏ hơn m'","B. p' luôn lớn hơn m'","C. p' bằng m'"],"answerLetter":"A","answerText":"A. p' luôn nhỏ hơn m'","notes":""},{"id":335,"question":"Các hình thức độc quyền nào thấp nhất trong các hình thức sau?","options":["A. Cartel","B. Syndicate","C. Trust","D. Consortium"],"answerLetter":"A","answerText":"A. Cartel","notes":""},{"id":336,"question":"Lĩnh vực nghiên cứu trọng tâm của chủ nghĩa trọng thương là gì?","options":["A. Lĩnh vực lưu thông","B. Lĩnh vực sản xuất","C. Lĩnh vực thuế","D. Lĩnh vực tiên lương"],"answerLetter":"A","answerText":"A. Lĩnh vực lưu thông","notes":""},{"id":337,"question":"Điền vào chỗ trống để hoàn thành câu sau: \"Chính trị kinh tế học tuyệt nhiên không nghiên cứu sự sản xuất, mà nghiên cứu những quan hệ xã hội giữa.. .trong sản xuất, nghiên cứu chế độ xã hội của sản xuất\"","options":["A. Người với người","B. Con người với tiên tệ","C. Con người với xã hội","D. Người với hàng hóa"],"answerLetter":"A","answerText":"A. Người với người","notes":""},{"id":338,"question":"Kinh tế hàng hóa là sự tiếp nỗi của:(NHUNG HOÀNG)","options":["A. Nên kinh tế xã hội","B. Nên kinh tế tự do","C. Nên kinh tế tự nhiên"],"answerLetter":"C","answerText":"C. Nên kinh tế tự nhiên","notes":""},{"id":339,"question":"Tiên tệ là bánh xe vĩ đại của lưu thông. Câu nói này là của ai và theo anh (chị) nó có đúng không?(NHUNG HOÀNG)","options":["A. A. Smith và là câu nói đúng","B. Đ. Ricacđô và là câu nói đúng","C. C. Mác và là câu nói đúng","D. Đ. Ricacđô và là câu nói sai"],"answerLetter":"A","answerText":"A. A. Smith và là câu nói đúng","notes":""},{"id":340,"question":"Sự khác nhau giữa địa tô tuyệt đối và địa tô chênh lệch đó là:","options":["A. Độc quyền kinh doanh ruộng đã theo kiểu tư bản chủ nghĩa là nguyên nhân sinh ra địa tô chênh lệch, còn độc quyền tư hữu về ruộng đất là nguyên nhân sinh ra địa tô tuyệt đối","B. Độc quyền sở hữu đất đã theo kiểu tư bản chủ nghĩa là nguyên nhân sinh ra địa tô chênh lệch, còn độc quyền tư hữu vẽ ruộng đất là nguyên nhân sinh ra địa tô tuyệt đối","C. Độc quyền kinh doanh ruộng đã theo kiểu tư bản chủ nghĩa là nguyên nhân sinh ra địa tô chênh lệch, còn độc quyền sử dụng về ruộng đất là nguyên nhân sinh ra địa tô tuyệt đối"],"answerLetter":"A","answerText":"A. Độc quyền kinh doanh ruộng đã theo kiểu tư bản chủ nghĩa là nguyên nhân sinh ra địa tô chênh lệch, còn độc quyền tư hữu về ruộng đất là nguyên nhân sinh ra địa tô tuyệt đối","notes":""},{"id":341,"question":"Đâu là công thức cấu thành lượng giá trị một đơn vị hàng hóa (G)?","options":["A. G= c + p + m","B. G= c + v + P","C. G= k + v + m","D. G= c + v + m"],"answerLetter":"D","answerText":"D. G= c + v + m","notes":"(Kiểu hỏi tương tự: Gọi W là giá trị hàng hóa, vậy công thức tính giá trị hàng hóa là gì? A. W= C + V+ M B. W= C+ V C. W= V+ M D. W= (C + V)/M)"},{"id":342,"question":"Cuộc khủng hoảng nào đã làm phá sản doanh nghiệp vừa và nhỏ, các doanh nghiệp lớn còn tồn tại dẫn tới hình thành các doanh nghiệp độc quyền đầu tiên?","options":["A. Khủng hoàng kinh tế năm 1873","B. Khủng hoàng kinh tế năm 1928","C. Khùng hoàng kinh tế năm 1973","D. Khủng hoàng kinh tế năm 2021"],"answerLetter":"A","answerText":"A. Khủng hoàng kinh tế năm 1873","notes":""},{"id":343,"question":"Nguyên nhân của bản chất khủng hoảng kinh tế chủ nghĩa tư bản là:","options":["A. Bắt nguồn từ mâu thuẫn của bản chất của chủ nghĩa tư bản","B. Do sản xuất không có kế hoạch","C. Do chạy theo lợi nhuận"],"answerLetter":"A","answerText":"A. Bắt nguồn từ mâu thuẫn của bản chất của chủ nghĩa tư bản","notes":""},{"id":344,"question":"Khi vàng trở thành vật ngang giá chung để trao đổi hàng hóa thì hình thái nào xuất hiện?","options":["A. Hình thái tiền","B. Hình thái đơn giản hay ngẫu nhiên","C. Hình thái đây đủ hay mở rộng","D. Hình thái chung của giá trị"],"answerLetter":"A","answerText":"A. Hình thái tiền","notes":""},{"id":345,"question":"Đâu KHÔNG phải là nhân tố ảnh hưởng đến quy mô tích luỹ tư bản?","options":["A. Lượng giá trị thặng dư","B. Sử dụng hiệu quả máy móc","C. Năng suất lao động xã hội","D. Trình độ khai thác sức lao động"],"answerLetter":"A","answerText":"A. Lượng giá trị thặng dư","notes":""},{"id":346,"question":"Yếu tố nào được điều chỉnh bởi quy luật kinh tế tác động vào các động cơ lợi ích và quan hệ lợi ích của con người?(NHUNG HOÀNG)","options":["A. Hành vi con người","B. Xu hướng tiêu dùng","C. Mặt hàng sản xuất","D. Linh vực nghiên cứu"],"answerLetter":"A","answerText":"A. Hành vi con người","notes":""},{"id":347,"question":"Tuần hoàn của tư bản công nghiệp trải qua mãy giai đoạn?","options":["A. Hai giai đoạn","B. Ba giai đoạn","C. Bốn giai đoạn","D. Năm giai đoạn"],"answerLetter":"B","answerText":"B. Ba giai đoạn","notes":"(Kiểu hỏi khác: Tuần hoàn tư bản là sự vận động của tư bản lần lượt trải qua ba giai đoạn dưới hình thái nào? =>tư bản tiền tệ, tư bản sản xuất và tư bản hàng hóa)"},{"id":348,"question":"Điền vào chỗ trống đẽ hoàn thành câu sau: \"...đẻ ra tập trung sản xuất và sự tập trung sản xuất này, khi phát triễn tới một mức độ nhất định, lại dẫn tôi độc quyền\"","options":["A. Tự do cạnh tranh","B. Độc quyền","C. Tư băn","D. Sự ra đời của nhà nước"],"answerLetter":"A","answerText":"A. Tự do cạnh tranh","notes":""},{"id":349,"question":"Công bằng trong phân phối có những quan niệm chính nào?","options":["A. Công bằng theo mức độ và công bằng theo chức năng","B. Công bằng theo hưởng thụ và công bằng theo cống hiến","C. Công bằng theo lao động và công bằng theo hưởng thụ","D. Công bằng theo mức độ và công bằng theo lao động"],"answerLetter":"A","answerText":"A. Công bằng theo mức độ và công bằng theo chức năng","notes":""},{"id":350,"question":"Số lượng tiền cần thiết trong lưu thông có mỗi quan hệ thế nào với tổng số giá cả hàng hóa được đưa ra thị trường và tốc độ lưu thông của tiền tệ?","options":["A. Ti lệ thuận với tổng giá cà hàng hóa đưa ra thị trưởng và tốc độ lưu thông tiên tệ","B. Ti lệ nghịch với tổng giá cả hàng hóa đưa ra thị trường và tốc độ lưu thông tiền tệ","C. Ti lệ thuận với tổng giá cả hàng hóa đưa ra thị trường và ti lệ nghịch với tốc độ lưu thông tiền tệ","D. Ti lệ nghịch với tổng giá hàng hóa cà đưa ra thị trường và ti lệ thuận với tốc độ lưu thông tiền tệ"],"answerLetter":"C","answerText":"C. Ti lệ thuận với tổng giá cả hàng hóa đưa ra thị trường và ti lệ nghịch với tốc độ lưu thông tiền tệ","notes":""},{"id":351,"question":"Nếu nhà tư bản trà công theo đúng giá trị sức lao động thì có còn bóc lột giá trị thặng dư không?","options":["A. Không còn","B. Tùy trường hợp cụ thể","C. Vẫn còn"],"answerLetter":"C","answerText":"C. Vẫn còn","notes":""},{"id":352,"question":"Thời gian lao động xã hội cần thiết có thế được đo bằng thời gian lao động cá biệt của nhà sản xuất:","options":["A. Cung ứng nhiêu loại hàng hóa khác nhau cho thị trường quyết định","B. Cung ứng một loại hàng hóa cho thị trường quyết định","C. Cung ứng đại bộ phận một loại hàng hóa cho thị trường quyết định","D. Cung ứng đại bộ phận một loại dịch vụ cho thị trường quyết định"],"answerLetter":"C","answerText":"C. Cung ứng đại bộ phận một loại hàng hóa cho thị trường quyết định","notes":""},{"id":353,"question":"Sở hữu chịu sự quy định trực tiếp của yếu tố nào?(NHUNG HOÀNG)","options":["A. Trình độ lực lượng sản xuất","B. Quan hệ sản xuất","C. Cơ sở hạ tầng","D. Kiến trúc thượng tầng"],"answerLetter":"A","answerText":"A. Trình độ lực lượng sản xuất","notes":""},{"id":354,"question":"Hàng hóa là gì:(NHUNG HOÀNG)","options":["A. Những vật để thoa mãn nhu cầu tiêu dùng của con người","B. Sản phẩm của lao động, có thể thoa mãn nhu cầu nào đó của con người thông qua trao đổi, mua bán","C. Những vật có giá trị sử dụng cao","D. Những vật mà trên thị trường luôn khan hiếm"],"answerLetter":"B","answerText":"B. Sản phẩm của lao động, có thể thoa mãn nhu cầu nào đó của con người thông qua trao đổi, mua bán","notes":"(Kiểu hỏi khác: Hàng hóa là gì? A. Là những vật để thỏa mãn nhu cầu tiêu dùng của con người B. Là hết thảy những vật, những thứ thỏa mãn nhu cầu tiêu dùng của con người và chúng được sản xuất ra để trao đổi, buôn bán C. Là những vật có giá trị sử dụng cao D. Là những vật mà trên thị trường luôn khan hiếm)"},{"id":355,"question":"M - khối lượng giá trị thặng dư phản ánh điều gì?","options":["A. Trình độ khai thác sức lao động làm thuê","B. Trình độ bóc lột sức lao động của nhà tư bản","C. Quy mô giá trị thặng dư mà nhà tư bản thu được","D. Quy mô bóc lột giá trị của nhà tư bản"],"answerLetter":"C","answerText":"C. Quy mô giá trị thặng dư mà nhà tư bản thu được","notes":""},{"id":356,"question":"Giá trị sử dụng của hàng hóa là giá trị sử dụng nhằm đáp ứng yêu cầu của ai?(NHUNG HOÀNG)","options":["A. Người mua","B. Người bán","C. Thương nhân","D. Bà bán tạp hoa"],"answerLetter":"A","answerText":"A. Người mua","notes":""},{"id":357,"question":"Chủ nghĩa trọng nông tập trung trọng tâm vào nghiên cứu lĩnh vực nào?","options":["A. Lĩnh vực sản xuất","B. Lĩnh vực lưu thông","C. Lĩnh vực quản lý","D. Lĩnh vực tiền tệ"],"answerLetter":"A","answerText":"A. Lĩnh vực sản xuất","notes":""},{"id":358,"question":"Kinh tế thị trường phải được điều tiết bởi yếu tố nào?","options":["A. Nhà nước","B. Pháp luật","C. Quy luật giá trị","D. Kinh tế thế giới"],"answerLetter":"A","answerText":"A. Nhà nước","notes":""},{"id":359,"question":"Các tố chức độc quyền hình thành trên cơ sở:(NHUNG HOÀNG)","options":["A. Liên kết dọc và liên kết ngang","B. Liên kết tự giác và liên kết tự phất","C. Liên kết bên ngoài và liên kết bên trong"],"answerLetter":"A","answerText":"A. Liên kết dọc và liên kết ngang","notes":""},{"id":360,"question":"Tỷ suất lợi nhuận được ký hiệu là p' được tính bằng công thức:","options":["A. p'= m/(c+v)*100%","B. p'= t/ (c+v)*100%","C. p'= m/(c+v +m)*100%","D. p'=p/(c+v)*100%"],"answerLetter":"D","answerText":"D. p'=p/(c+v)*100%","notes":""},{"id":361,"question":"Đâu là một trong những nguyên nhân dẫn đến độc quyền?","options":["A. Do cạnh tranh","B. Do việc bóc lột sức lao động","C. Do sự vận dụng từ các học thuyết kinh tế vào kinh doanh","D. Do sự ra đời của nhà nước"],"answerLetter":"A","answerText":"A. Do cạnh tranh","notes":""},{"id":362,"question":"Về kinh tế, xuất khấu tư bản nhà nước nhằm mục đích:","options":["A. Tạo môi trưởng thuận lợi cho xuất khẩu tư bản tư nhân.","B. Tạo điều kiện cho các nước nhập khấu tư bản phát triển","C. Khống chế kinh tế các nước nhập khấu tư bản."],"answerLetter":"A","answerText":"A. Tạo môi trưởng thuận lợi cho xuất khẩu tư bản tư nhân.","notes":"(Kiểu hỏi khác: Về kinh tế, xuất khẩu tư bản nhà nước thường hướng vào: A. Ngành kết cấu hạ tầng B. Ngành có vốn chu chuyển nhanh C. Ngành công nghệ môi)"},{"id":363,"question":"Cơ chế thị trường được Adam Smith ví như?(NHUNG HOÀNG)","options":["A. Bàn tay vô hình","B. Bóng ma vô hình","C. Con đĩa hai vòi","D. Nam châm hai cực"],"answerLetter":"A","answerText":"A. Bàn tay vô hình","notes":""},{"id":364,"question":"Sự xuất hiện của yếu tố nào làm cho quá trình quốc tế hóa, toàn cầu hóá kinh tế được đấy mạnh?","options":["A. Các công ty xuyên quốc gia (TNCs)","B. Sự xuất hiện của Conglomerate","C. Các công ty tài chính","D. Các tổ chức phi lợi nhuận"],"answerLetter":"A","answerText":"A. Các công ty xuyên quốc gia (TNCs)","notes":""},{"id":365,"question":"Lao động giản đơn với lao động phức tạp là:(NHUNG HOÀNG)","options":["A. Hai lao động giống nhau","B. Cùng một lao động","C. Hai lao động khác nhau","D. Hai công việc khác nhau"],"answerLetter":"C","answerText":"C. Hai lao động khác nhau","notes":""},{"id":366,"question":"Biểu hiện mới của xuất khẩu tư bản ngày nay đó là:","options":["A. Dòng đầu tư chảy qua lại giữa các nước tư bản phát triển với nhau","B. Vai trò của các công ty xuyên quốc gia trong xuất khấu tư bản - đặt biệt đầu tư trực tiếp nước ngoài (FDI) càng lớn","C. Hình thức xuất khẩu đa dạng","D. Dựa trên nguyên tắc cùng có lợi","E. Tất cả phương án trên"],"answerLetter":"E","answerText":"E. Tất cả phương án trên","notes":""},{"id":367,"question":"Dịch vụ là loại hàng hóa nào?","options":["A. Hàng hóa vô hình","B. Hàng hoa hữu hình","C. Hàng hóa đặc biệt","D. Không phải là hàng hoa"],"answerLetter":"A","answerText":"A. Hàng hóa vô hình","notes":""},{"id":368,"question":"Đối tượng lao động trong kinh tế chính trị được hiểu là:","options":["A. Các vật có trong tự nhiên","B. Những vật mà lao động của con người tác động vào nhằm thay đổi nó cho phù hợp với mục đích của con người","C. Những vật dùng để truyền dẫn sức lao động của con người","D. Các phương án trà lời đều đúng"],"answerLetter":"B","answerText":"B. Những vật mà lao động của con người tác động vào nhằm thay đổi nó cho phù hợp với mục đích của con người","notes":""},{"id":369,"question":"Lợi nhuận là:","options":["A. Hình thức biến tưởng của kết quả sản xuất","B. Hình thức biến tướng của giá trị thặng dư","C. Hình thức biến tưông của chi phí sản xuất","D. Hình thức biến tước của tư bản cố định"],"answerLetter":"B","answerText":"B. Hình thức biến tướng của giá trị thặng dư","notes":""},{"id":370,"question":"Giá trị của hàng hóa được tạo ra từ yếu tố nào?","options":["A. Lao động trừu tượng","B. Lao động cụ thể","C. Giá tiên cao thấp","D. Tuỳ vào công dụng của hàng hóa đó"],"answerLetter":"A","answerText":"A. Lao động trừu tượng","notes":""},{"id":371,"question":"Chi phí sản xuất tư bản chủ nghĩa (k) là:","options":["A. Bao gồm m và v (k = m+v)","B. Bao gồm c và m (k = c+m)","C. Bao gồm c và v (k = c+v)","D. Bao gồm c, v và m (k = c + v + m)"],"answerLetter":"C","answerText":"C. Bao gồm c và v (k = c+v)","notes":""},{"id":372,"question":"Mì ăn liền, khăn giấy, bim bim... là loại hàng hóa nào?","options":["A. Hàng hóa hữu hình","B. Hàng hóa vô hình","C. Hàng hoá đặc biệt","D. Không phải là hàng hóa"],"answerLetter":"A","answerText":"A. Hàng hóa hữu hình","notes":""},{"id":373,"question":"Khi nào tiên tệ biến thành tư bản?","options":["A. Sức lao động trở thành hàng hóa","B. Dùng tiên để buôn bán mua rẻ, bán đất","C. Có lượng tiền tệ đủ lớn","D. Tiền đưa vào dự trữ"],"answerLetter":"A","answerText":"A. Sức lao động trở thành hàng hóa","notes":""},{"id":374,"question":"Cuộc cách mạng công nghiệp lần thứ nhất diễn ra trên lĩnh vực nào?","options":["A. Năng lượng hơi nước","B. Năng lượng điện","C. Động cơ đốt trong","D. Chế tạo ôtô"],"answerLetter":"A","answerText":"A. Năng lượng hơi nước","notes":""},{"id":375,"question":"Hai phương pháp sản xuất giá trị thặng dư là","options":["A. Sản xuất giá trị thặng dư tương đối và siêu ngạch","B. Sản xuất giá trị thặng dư tuyệt đối và tương đối","C. Sản xuất giá trị thăng dư tuyệt đối và siêu nghạch","D. Sản xuất giá trị thặng dư trung bình"],"answerLetter":"B","answerText":"B. Sản xuất giá trị thặng dư tuyệt đối và tương đối","notes":""},{"id":376,"question":"Tăng trưởng kinh tế là:","options":["A. Tăng năng suất lao động","B. Tăng GDP và GNP trong một thời kỳ nhất định","C. Tăng hiệu quà của sản xuất","D. Tăng lãi suất ngân hàng"],"answerLetter":"B","answerText":"B. Tăng GDP và GNP trong một thời kỳ nhất định","notes":""},{"id":377,"question":"Cuộc cách mạng công nghiệp nào gắn liên với sự xuất hiện của trí tuệ nhân tạo, big data, 3D...?","options":["A. Cuộc cách mạng công nghiệp lần thứ tư","B. Cuộc cách mạng công nghiệp lần thứ năm","C. Cuộc cách mạng công nghiệp lần thứ ba","D. Cuộc cách mạng công nghiệp lần thứ hai"],"answerLetter":"A","answerText":"A. Cuộc cách mạng công nghiệp lần thứ tư","notes":""},{"id":378,"question":"Tính định hướng xã hội chủ nghĩa của nền kinh tế thị trường Việt Nam được thể hiện ở khía cạnh nào?","options":["A. Là nên kinh tế thị trường có sự quản lý của nhà nước xã hội chủ nghĩa, do Đảng Cộng sản Việt Nam lãnh","B. Thực hiện phân phối theo kết quả lao động","C. Là nền kinh tế mà trong đó việc xác lập thể chế sở hữu, phân phối, quản trị kinh doanh của các chủ thể cũng như quản lý nhà nước hưông tới xác lấp những giá trị cốt lõi về xã hội","D. Là nền kinh tế phát thuy được trí tuệ và nguồn lực của toàn dân","E. Tất cả phương án trên"],"answerLetter":"E","answerText":"E. Tất cả phương án trên","notes":""},{"id":379,"question":"Xuất khẩu giá trị ra nước ngoài nhằm mục đích thu được giá trị thặng dư và các nguồn lợi khác ô các nước mà mình đầu tư gọi là gì?","options":["A. Xuất khẩu tư bản","B. Nhập khẩu tư bản","C. Đầu tư thị trưởng","D. Đầu tư tiên tệ"],"answerLetter":"A","answerText":"A. Xuất khẩu tư bản","notes":""},{"id":380,"question":"Mục đích nghiên cứu ở cấp độ cao nhất của kinh tế chính trị Mác - Lênin là gì?","options":["A. Nhằm phát hiện ra các quy luật chi phối quan hệ giữa người và người trong sản xuất và trao đổi","B. Nhằm phát hiện ra các quy luật chi phối quan hệ giữa người và xã hội trong sản xuất và trao đổi","C. Nhằm phát hiện ra các quy luật chi phối quan hệ giữa người và người trong sản xuất và tiêu dùng","D. Nhằm phát hiện ra các quy luật chi phối quan hệ giữa người và hàng hóa trong sản xuất và tiêu dùng"],"answerLetter":"A","answerText":"A. Nhằm phát hiện ra các quy luật chi phối quan hệ giữa người và người trong sản xuất và trao đổi","notes":""},{"id":381,"question":"Hình thức độc quyền nào thống nhất việc sản xuất, tiêu thụ, tài vụ đều do một ban quản trị quản lý?(073-356-8678)","options":["A. Consortium","B. Syndicate","C. Cartel","D. Trust"],"answerLetter":"D","answerText":"D. Trust","notes":""},{"id":382,"question":"Cạnh tranh giữa các ngành xảy ra khi có sự khác nhau về:","options":["A. Giá trị thặng dư siêu ngạch","B. Tỷ suất lợi nhuận","C. Cung cầu các loại hàng hóa"],"answerLetter":"B","answerText":"B. Tỷ suất lợi nhuận","notes":""},{"id":383,"question":"Sản xuất giá trị thặng dư là quy luật kinh tế:","options":["A. Tuyệt đối của chủ nghĩa tư bản","B. Tuyệt đối của doanh nghiệp tư bản","C. Tuyệt đối của chủ nghĩa xã hội"],"answerLetter":"A","answerText":"A. Tuyệt đối của chủ nghĩa tư bản","notes":""},{"id":384,"question":"Nguyên nhân trực tiếp gây ra nạn thất nghiệp trong chủ nghĩa tư bản là?","options":["A. Lợi nhuận của các nhà tư bản","B. Khủng hoảng kinh tế","C. Quan hệ sản xuất tư bản chủ nghĩa","D. Cấu tạo hữu cơ của tư bản tăng lên trong quá trình tích lũy"],"answerLetter":"D","answerText":"D. Cấu tạo hữu cơ của tư bản tăng lên trong quá trình tích lũy","notes":""},{"id":385,"question":"Các nhân tố ảnh hưởng tới tỷ suất lợi nhuận đó là","options":["A. Tỷ suất giá trị thặng dư, tốc độ chu chuyển tư bản, cấu tạo hữu cơ của tư bản, tiết kiệm tư bản bất biến","B. Tỷ suất lợi tức, tốc độc chu chuyển tư bản, cấu tạo hữu cơ của tư bản, tiết kiệm tư bản bất biến","C. Khối lượng giá trị thặng dư, tỷ suất giá trị thặng dư, cấu tạo hữu cơ của tư bản, tiết kiệm tư bản bất biến","D. Khối lượng giá trị thặng dư, tỷ suất lợi tức, tỷ suất giá trị thặng dư, tốc độ chu chuyển của tư bản"],"answerLetter":"A","answerText":"A. Tỷ suất giá trị thặng dư, tốc độ chu chuyển tư bản, cấu tạo hữu cơ của tư bản, tiết kiệm tư bản bất biến","notes":""},{"id":386,"question":"Tư bản cố định có vai trò gì?","options":["A. Là nguồn gốc của giá trị thặng dư","B. Là điều kiện để tăng năng suất lao động","C. Các phương án trà lời đều đúng"],"answerLetter":"C","answerText":"C. Các phương án trà lời đều đúng","notes":""},{"id":387,"question":"Kinh tế thị trường xuất hiện lần đầu tiên ở xã hội nào?","options":["A. Phong kiến","B. Chiếm hữu nô lệ","C. Tư bản chủ nghĩa","D. Xã hội chủ nghĩa"],"answerLetter":"C","answerText":"C. Tư bản chủ nghĩa","notes":"(Giải thích: mầm mống → B hình thành → A)"},{"id":388,"question":"Hãy chọn phương án đúng về đặc điểm của quy luật kinh tế:","options":["A. Phát huy tác dụng thông qua hoạt động kinh tế của con người","B. Các phương án trả lời đêu đúng","C. Mang tính khách quan"],"answerLetter":"B","answerText":"B. Các phương án trả lời đêu đúng","notes":""},{"id":389,"question":"Mọi hình thức lạm phát đều làm tăng:","options":["A. Giá cả của hàng hóa","B. Giá trị của hàng hóa","C. Giá trị sử dụng của hàng hóa"],"answerLetter":"A","answerText":"A. Giá cả của hàng hóa","notes":""},{"id":390,"question":"Mô hình kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta lần đầu tiên được Đảng đưa ra tại Đại hội nào?","options":["A. Đại hội IX (2001)","B. Đại hội X (2006)","C. Đại hội XI (2011)","D. Đại hội V (1982)"],"answerLetter":"A","answerText":"A. Đại hội IX (2001)","notes":"(Mô hình kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta được chính thức nêu ra ở Đại hội nào của Đảng Cộng sản Việt Nam ? A. Đại hội VI B. Đại hội VIII C. Đại hội IX D. Đại hội X)"},{"id":391,"question":"Quan điểm về \"xây dựng nên kinh tế tự chủ phải dựa trên cơ sở làm chủ công nghệ và chủ động, tích cực hội nhập, đa dạng hóa thị trường, nâng cao khả năng thích ứng của nền kinh tế được đưa ra trong chiến lược phát triển kinh tế - xã hội ở giai đoạn nào?","options":["A. Chiến lược phát triển kinh tế - xã hội 2001 -2010","B. Chiến lược phát triển kinh tế - xã hội 2011 -2020","C. Chiến lược phát triển kinh tế - xã hội 2021 -2030","D. Chiến lược phát triển kinh tế - xã hội 2016-2021"],"answerLetter":"C","answerText":"C. Chiến lược phát triển kinh tế - xã hội 2021 -2030","notes":""},{"id":392,"question":"Bản chất tiền công trong chủ nghĩa tư bản là:","options":["A. Hình thức biểu hiện bằng tiền của giá trị sức lao động","B. Hình thức biểu hiện bằng tiền của giá cả sức lao động","C. Hình thức biểu hiện bằng tiên của giá trị lao động","D. Hình thức biểu hiện bằng tiên của giá cà của lao động"],"answerLetter":"B","answerText":"B. Hình thức biểu hiện bằng tiền của giá cả sức lao động","notes":""},{"id":393,"question":"Điểm giống nhau giữa p (lợi nhuận) và m (giá trị thặng dư) là:","options":["A. Có chung nguồn gốc là kết quả lao động không công của người công nhân","B. Có chung nguồn gốc là kết quả sự đầu tư có lãi của nhà tư bản","C. Phản ánh đúng bản chất và nguỡn gốc của sự chiếm đoạt lao động không công của nhà tư bản","D. Phản ánh sai lệnh bản chất bóc lột của nhà tư bản"],"answerLetter":"A","answerText":"A. Có chung nguồn gốc là kết quả lao động không công của người công nhân","notes":""},{"id":394,"question":"Tính chu kỳ của tuần hoàn tư bản gọi là:","options":["A. Chu chuyển hàng hóa","B. Chu chuyển tư bản","C. Chu chuyển sản xuất","D. Chu chuyễn sức lao động"],"answerLetter":"B","answerText":"B. Chu chuyển tư bản","notes":""},{"id":395,"question":"Hàng hóa sức lao động khác hàng hóa thông thường ở chỗ:","options":["A. Khi sử dụng nó sẽ tạo ra một lượng giá trị nhỏ hơn giá trị của bản thân nó","B. Khi sử dụng nó sẽ có khả năng tạo ra một lượng giá trị mới lớn hơn giá trị của bản thân nó","C. Các phương án trà lời đều sai"],"answerLetter":"B","answerText":"B. Khi sử dụng nó sẽ có khả năng tạo ra một lượng giá trị mới lớn hơn giá trị của bản thân nó","notes":""},{"id":396,"question":"Khẳng định nào đúng trong những khẳng định sau?","options":["A. Sản xuất hàng hóa chi là sản phẩm của chủ nghĩa tư bản","B. Sản xuất hàng hóa không có trong chủ nghĩa xã hội","C. Sản xuất hàng hóa ra đời trong chế độ chiếm hữu nô lệ"],"answerLetter":"C","answerText":"C. Sản xuất hàng hóa ra đời trong chế độ chiếm hữu nô lệ","notes":""},{"id":397,"question":"Sau những năm 50 của thế ký XX, chủ nghĩa tư bàn chuyển sang chính sách thực dân mới đó là: (chọn nhiều đáp án)","options":["A. Viện trợ kinh tế","B. Viện trợ quân sự","C. Viện trợ thuốc men","D. Viện trợ chính trị"],"answerLetter":"AB","answerText":"A. Viện trợ kinh tế\nB. Viện trợ quân sự","notes":""},{"id":398,"question":"Tiến hành công nghiệp hóa theo kiếu rút ngắn so với các nước đi trước đặc biệt chúng ta cần thực hiện yêu cầu nào?(NHUNG HOÀNG)","options":["A. Phát triển kinh tế và công nghiệp phải có sự nhày vọt và không cần thực hiện tuần tự","B. Coi trọng phát triển giáo dục và đào tạo, khoa học và công nghệ, xem đầy là nên tâng và động lực cho công nghiệp hóa, hiện đại hoa","C. Phát triển kinh tế trí thức được dời lại trong giai đoạn sau","D. Ưu tiên phát triển công nghiệp nặng một cách hợp lý trên cơ sở phát triển nông nghiệp và công nghiệp nhẹ"],"answerLetter":"B","answerText":"B. Coi trọng phát triển giáo dục và đào tạo, khoa học và công nghệ, xem đầy là nên tâng và động lực cho công nghiệp hóa, hiện đại hoa","notes":""},{"id":399,"question":"Tổng kết thực tiễn vai trò của độc quyền trong nên kinh tế các nước tư bản phát triển giai đoạn cuối thế kỳ XIX đầu thế kỳ XX, V. I. Lênin đã khái quất độc quyền tư bản chủ nghĩa thành:","options":["A. Bốn đặc điểm","B. Năm đặc điểm","C. Sáu đặc điểm","D. Bảy đặc điểm"],"answerLetter":"B","answerText":"B. Năm đặc điểm","notes":""},{"id":400,"question":"Chính sách thực dân trong thời đại chủ nghĩa đẽ quốc tư bản đã tạo ra những hình thức lệ thuộc mới có tính quá độ của các nước đó là:","options":["A. Độc lập về chính trị nhưng lệ thuộc về kinh tế và ngoại giao","B. Độc lập về kinh tế nhưng lệ thuộc về chính trị","C. Lệ thuộc về kinh tế, chính trị và ngoại giao","D. Độc lập về lãnh thổ, nhưng lệ thuộc về ngoại giao"],"answerLetter":"A","answerText":"A. Độc lập về chính trị nhưng lệ thuộc về kinh tế và ngoại giao","notes":""},{"id":401,"question":"Sỡ hữu độc quyền nhà nước là sự kết hợp của:","options":["A. Sở hữu nhà nước và sở hữu độc quyền tư nhân","B. Sở hữu của nhà nước tư sản","C. Sở hữu của nhiều nước tư bản"],"answerLetter":"A","answerText":"A. Sở hữu nhà nước và sở hữu độc quyền tư nhân","notes":""},{"id":402,"question":"Thế nào là lao động trừu tượng?","options":["A. Là hoạt động có mục đích, có ý thức của con người","B. Là những lao động ngành nghê tạo ra của cài","C. Là sự hao phí sức lao động nói chung của người sản xuất hàng hóa","D. Là lao động sản xuất nếu coi đó là sự hao phí sức lao động nói chung"],"answerLetter":"C","answerText":"C. Là sự hao phí sức lao động nói chung của người sản xuất hàng hóa","notes":""},{"id":403,"question":"Hàng hoá có bao nhiêu thuộc tính?","options":["A. Hai thuộc tỉnh","B. Ba thuộc tính","C. Bốn thuộc tỉnh","D. Rất nhiều thuộc tỉnh"],"answerLetter":"A","answerText":"A. Hai thuộc tỉnh","notes":""},{"id":404,"question":"Tỷ lệ giữa lao động phức tạp và lao động giản đơn tăng lên có ảnh hưởng như thế nào đến lượng giá trị được tạo ra trong một đơn vị thời gian?","options":["A. Tăng lên","B. Giữ nguyên không thay đổi","C. Giảm xuống","D. Tăng lên nhưng phải gắn với tiến bộ công nghệ"],"answerLetter":"A","answerText":"A. Tăng lên","notes":""},{"id":405,"question":"Nhận định nào sau đây là đúng?","options":["A. Xã hội loài người càng phát triển, sự tách biệt về sở hữu càng sâu sắc, hàng hoá được sản xuất ra càng phong phú.","B. Xã hội loài người càng phát triển, sự tách biệt về sở hữu càng sâu sắc, hàng hoá được sản xuất ra càng khan hiếm.","C. Xã hội loài người càng kém phát triển, sự tách biệt về sở hữu càng sâu sắc, hàng hoá được sản xuất ra càng kém phong phú.","D. Sản xuất càng phát triển, sự tách biệt về sở hữu càng sâu sắc, hàng hoá được sản xuất ra càng kém phong phú."],"answerLetter":"A","answerText":"A. Xã hội loài người càng phát triển, sự tách biệt về sở hữu càng sâu sắc, hàng hoá được sản xuất ra càng phong phú.","notes":""},{"id":406,"question":"Sự phân chia tư bản thành tư bản bất biến và tư bản khả biến là để biết:","options":["A. Đặc điểm chuyển giá trị của từng loại tư bản vào sản phẩm","B. Vai trò của lao động quá khứ và lao động sống trong việc tạo ra giá trị sử dụng","C. Nguồn gốc của giá trị thặng dư","D. Tính chất của lao động"],"answerLetter":"C","answerText":"C. Nguồn gốc của giá trị thặng dư","notes":""},{"id":407,"question":"Trên giác độ kinh tế chính trị, cầu được hiểu là","options":["A. Nhu cầu của xã hội về dịch vụ","B. Nhu cầu xã hội về hàng hóa","C. Nhu cầu có khả năng thanh toán của xã hội"],"answerLetter":"C","answerText":"C. Nhu cầu có khả năng thanh toán của xã hội","notes":""},{"id":408,"question":"Nguồn gốc của giá trị thặng dư có được từ đâu?","options":["A. Từ một loại hàng hoá đặc biệt mà giá trị của nó không những được bảo tồn mà còn tạo ra giá trị lớn hơn đó là hàng hoá sức lao động","B. Từ quá trình mua đi bán lại hàng hoá","C. Từ quá trình sản xuất hàng hoá","D. Từ quá trình đầu cơ, tích trữ chờ đợi tăng giá của các nhà tư bản"],"answerLetter":"A","answerText":"A. Từ một loại hàng hoá đặc biệt mà giá trị của nó không những được bảo tồn mà còn tạo ra giá trị lớn hơn đó là hàng hoá sức lao động","notes":""},{"id":409,"question":"Các công thức tính tỷ suất giá trị thặng dư dưới đây, công thức nào đúng?","options":["A. m' = giá trị thặng dư / tư bản khả biến* 100%","B. m' = thời gian lao động tất yếu/thời gian lao động cần thiết *100%","C. m' = thời gian lao động thặng dư/lao động cần thiết 100%","D. m' = giá trị sức lao động / giá trị thặng dư *100%"],"answerLetter":"A","answerText":"A. m' = giá trị thặng dư / tư bản khả biến* 100%","notes":""},{"id":410,"question":"Sức lao động là:","options":["A. Toàn bộ thể lực và trí lực trong một con người đang sống và được vận dụng để sản xuất ra giá trị sử dụng nào đó","B. Khả năng lao động, được tiêu dùng trong quá trình sản xuất","C. Các phương án trả lời đều đúng"],"answerLetter":"C","answerText":"C. Các phương án trả lời đều đúng","notes":""},{"id":411,"question":"Tư bản cố định là:","options":["A. Bộ phận tư bản sản xuất tồn tại dưới dạng máy móc, thiết bị, nhà xưởng... về hiện vật tham gia toàn bộ vào quá trình sản xuất, nhưng giá trị của nó bị khấu hao từng phần và được chuyển dần vào sản phẩm mới được sản xuất ra","B. Bộ phận tư bản sản xuất tồn tại dưới dạng nguyên liệu, nhiên liệu, vật liệu phụ, sức lao động giá trị của nó lưu thông toàn bộ cùng với sản phẩm và được hoàn lại toàn bộ cho các nhà tư bản sau mỗi quá trình sản xuất","C. Bộ phận tư bản tiêu dùng tồn tại dưới dạng máy móc, thiết bị, nhà xưởng... về hiện vật tham gia toàn bộ vào quá trình sản xuất, nhưng giá trị của nó bị khấu hao từng phần và được chuyển dần vào sản phẩm mới được sản xuất ra","D. Bộ phận tư bản tiêu dùng tồn tại dưới dạng nguyên liệu, nhiên liệu, vật liệu phụ, sức lao động... giá trị của nó lưu thông toàn bộ cùng với sản phẩm và được hoàn lại toàn bộ cho các nhà tư bản sau mỗi quá trình sản xuất"],"answerLetter":"A","answerText":"A. Bộ phận tư bản sản xuất tồn tại dưới dạng máy móc, thiết bị, nhà xưởng... về hiện vật tham gia toàn bộ vào quá trình sản xuất, nhưng giá trị của nó bị khấu hao từng phần và được chuyển dần vào sản phẩm mới được sản xuất ra","notes":""},{"id":412,"question":"Đặc trưng cơ bản của cách mạng công nghiệp lần thứ ba là gì?","options":["A. Sử dụng công nghệ thông tin và máy tính","B. Sử dụng năng lượng điện","C. Sử dụng động cơ hơi nước","D. Sử dụng động cơ điện"],"answerLetter":"A","answerText":"A. Sử dụng công nghệ thông tin và máy tính","notes":"(Kiểu hỏi khác: Đặc trưng cơ bản của cuộc cách mạng công nghiệp lần thứ ba là gì? A. Sự xuất hiện của máy móc, lao động thủ công B. Sự xuất hiện của công nghệ thông tin, thời gian làm việc tăng lên C. Sự xuất hiện của công nghệ thông tin, tự động hóa sản xuất D. Lao động chân tay, năng suất tăng)"},{"id":413,"question":"Hình thức tổ chức và cơ chế thống trị của tư bản tài chính trong chủ nghĩa tư bản ngày nay thay đổi là do:","options":["A. Lực lượng sản xuất phát triển, nhiều ngành mới xuất hiện","B. Mục đích thu lợi nhuận độc quyền","C. Sự điều tiết của nhà nước","D. Nhiều ngành mới ra đời với những quan hệ sản xuất mới"],"answerLetter":"A","answerText":"A. Lực lượng sản xuất phát triển, nhiều ngành mới xuất hiện","notes":""},{"id":414,"question":"Các hình thức độc quyền nào cao nhất trong các hình thức sau?","options":["A. Cartel","B. Syndicate","C. Trust","D. Consortium"],"answerLetter":"D","answerText":"D. Consortium","notes":""},{"id":415,"question":"Sự hình thành các tổ chức độc quyền dựa trên cơ sở nào?","options":["A. Tích tụ tập trung sản xuất và sự ra đời của các xí nghiệp quy mô lớn","B. Sự xuất hiện các thành tựu mối của khoa học","C. Sản xuất nhỏ phân tán","D. Nhiều doanh nghiệp vừa và nhỏ ra đời"],"answerLetter":"A","answerText":"A. Tích tụ tập trung sản xuất và sự ra đời của các xí nghiệp quy mô lớn","notes":""},{"id":416,"question":"Mua cổ phiếu, trái phiếu là hình thức đầu tư gì?","options":["A. Đầu tư gián tiếp","B. Đầu tư trực tiếp","C. Đầu tư thị trường","D. Đầu tư tiền tệ"],"answerLetter":"A","answerText":"A. Đầu tư gián tiếp","notes":""},{"id":417,"question":"Giá trị của hàng hoá được quyết định bởi:","options":["A. Lao động trừu tượng của người sản xuất kết tinh trong hàng hoá","B. Sự khan hiếm của hàng hoá","C. Sự hao phí sức lao động của con người","D. Sự hao phí lao động cá biệt"],"answerLetter":"A","answerText":"A. Lao động trừu tượng của người sản xuất kết tinh trong hàng hoá","notes":""},{"id":418,"question":"Lượng giá trị của hàng hóa được đo bằng đơn vị.","options":["A. Khối lượng","B. Năng suất","C. Thời gian lao động xã hội cần thiết","D. Mức độ khan hiếm của hàng hóa"],"answerLetter":"C","answerText":"C. Thời gian lao động xã hội cần thiết","notes":""},{"id":419,"question":"Nhận xét nào sau đây đúng về các nhân tố ảnh hưởng đến lượng giá trị hàng hoá?","options":["A. Lượng giá trị hàng hoá tỉ lệ nghịch với năng xuất lao động","B. Lượng giá trị hàng hoá tỉ lệ nghịch với cường độ lao động","C. Lượng giá trị hàng hoá bằng giá trị lao động giản đơn","D. Lao động phức tạp và lao động giản đơn tạo ra giá trị hàng hoá như nhau"],"answerLetter":"A","answerText":"A. Lượng giá trị hàng hoá tỉ lệ nghịch với năng xuất lao động","notes":""},{"id":420,"question":"Nhận định nào sau đây đúng về tư bản cho vay?","options":["A. Tư bản cho vay là hàng hoá đặc biệt","B. Tư bản cho vay là hình thái để thu lợi nhuận cao nhất của đầu tư","C. Quyền sử dụng đi liền với quyền sở hữu","D. Là một phần của giá trị hàng hoá"],"answerLetter":"A","answerText":"A. Tư bản cho vay là hàng hoá đặc biệt","notes":""},{"id":421,"question":"Biểu hiện quy luật giá trị thặng dư ở trong giai đoạn chủ nghĩa tư bản độc quyền là:","options":["A. Quy luật lợi nhuận bình quân","B. Quy luật lợi nhuận độc quyền","C. Quy luật lợi nhuận","D. Quy luật giá cả sản xuất"],"answerLetter":"B","answerText":"B. Quy luật lợi nhuận độc quyền","notes":""},{"id":422,"question":"Trong quá trình sản xuất tư bản chủ nghĩa, có hai loại hao mòn đó là:","options":["A. Hao mòn hữu hình và hao mòn vô hình","B. Hao mòn tự nhiên và hao mòn giá trị","C. Hao mòn máy móc và hao mòn sức lao động","D. Hao mòn máy móc và hao mòn nguyên liệu"],"answerLetter":"A","answerText":"A. Hao mòn hữu hình và hao mòn vô hình","notes":""},{"id":423,"question":"Mô hình công nghiệp hoá của Nhật Bản và các nước công nghiệp mới gọi tắt là gì?","options":["A. NICS","B. TNCs","C. OECD","D. FPT"],"answerLetter":"A","answerText":"A. NICS","notes":""},{"id":424,"question":"Bản chất của độc quyền nhà nước trong chủ nghĩa tư bản là:","options":["A. Sự kết hợp tổ chức độc quyền tư nhân và nhà nước tư sản","B. Nhà nước tư sản can thiệp vào kinh tế, chi phối độc quyền","C. Các tổ chức độc quyền phụ thuộc vào nhà nước","D. Nhằm duy trì lợi ích của nhà nước tư bản"],"answerLetter":"A","answerText":"A. Sự kết hợp tổ chức độc quyền tư nhân và nhà nước tư sản","notes":""},{"id":425,"question":"Từ yêu cầu của quy luật quan hệ sản xuất phải phù hợp với trình độ phát triển của lực lượng sản xuất, lý luận của chủ nghĩa Mác - Lênin khẳng định:","options":["A. Chủ nghĩa tư bản không tồn tại vĩnh viễn","B. Chủ nghĩa tư bản tiếp tục phát triển đến đỉnh cao","C. Chủ nghĩa tư bản sẽ diệt vong trong thời gian ngắn"],"answerLetter":"A","answerText":"A. Chủ nghĩa tư bản không tồn tại vĩnh viễn","notes":""},{"id":426,"question":"Cơ chế thị trường có sự điều tiết của nhà nước nhằm phục vụ lợi ích của ai?(NHUNG HOÀNG)","options":["A. Chủ nghĩa tư bản độc quyền","B. Nhà nước dân chủ","C. Các công ty tài chính","D. Nhân dân lao động"],"answerLetter":"A","answerText":"A. Chủ nghĩa tư bản độc quyền","notes":""},{"id":427,"question":"Khoa học kỹ thuật càng phát triển làm cho:(NHUNG HOÀNG)","options":["A. Giá trị sử dụng của hàng hóa ngày càng phong phú và đa dạng","B. Giá trị sử dụng của hàng hóa luôn thay đổi","C. Giá trị sử dụng của hàng hóa biến thiên theo thị trường","D. Giá trị của hàng hóa ngày càng phong phú và đa dạng với nhiều sản phẩm"],"answerLetter":"A","answerText":"A. Giá trị sử dụng của hàng hóa ngày càng phong phú và đa dạng","notes":""},{"id":428,"question":"Căn cứ vào đâu để phân chia thành tái sản xuất cá biệt và tái sản xuất xã hội?(NHUNG HOÀNG)","options":["A. Căn cứ vào phạm vi sản xuất","B. Căn cứ vào tốc độ sản xuất","C. Căn cứ vào tính chất sản xuất"],"answerLetter":"A","answerText":"A. Căn cứ vào phạm vi sản xuất","notes":""},{"id":429,"question":"Loại tái sản xuất nào làm tăng sản phẩm chủ yếu do tăng năng suất lao động và hiệu quả sử dụng các nguồn luc?(NHUNG HOÀNG)","options":["A. Tái sản xuất mở rộng theo chiều rộng","B. Tái sản xuất mở rộng","C. Tái sản xuất mở rộng theo chiều sâu"],"answerLetter":"C","answerText":"C. Tái sản xuất mở rộng theo chiều sâu","notes":""},{"id":430,"question":"Cổ phiếu có hai loại đó là(NHUNG HOÀNG)","options":["A. Cổ phiếu thường và cổ phiếu ưu đãi","B. Cổ phiếu thưởng và cổ phiếu ưu đãi","C. Cổ tức và cổ phiếu thường","D. Cổ phiếu thường và cổ phiếu thưởng"],"answerLetter":"A","answerText":"A. Cổ phiếu thường và cổ phiếu ưu đãi","notes":""},{"id":431,"question":"Khi sử dụng hàng hóa sức lao động sẽ tạo ra.","options":["A. Giá trị mới bằng giá trị bản thân nó","B. Giá trị mới lớn hơn giá trị bản thân nó","C. Giá trị mới nhỏ hơn giá trị bản thân nó","D. Giá trị sử dụng mới nhỏ hơn giá trị sử dụng bản thân nó"],"answerLetter":"B","answerText":"B. Giá trị mới lớn hơn giá trị bản thân nó","notes":""},{"id":432,"question":"Trong giai đoạn chủ nghĩa tư bản độc quyền, ngoài sự cạnh tranh giữa những người sản xuất nhỏ, giữa những nhà tư bản vừa và nhỏ như trong giai đoạn chủ nghĩa tư bản cạnh tranh tự do, mà còn có thêm các loại cạnh tranh sau: (chọn nhiều đáp án)(NHUNG HOÀNG)","options":["A. cạnh tranh giữa các tổ chức độc quyền với các xí nghiệp ngoài độc quyền","B. Cạnh tranh giữa các tổ chức độc quyền vối nhau","C. Cạnh tranh trong nội bộ các tổ chức độc quyền","D. Cạnh tranh giữa các tổ chức tư bản độc quyền nhà nước với nhau"],"answerLetter":"ABC","answerText":"A. cạnh tranh giữa các tổ chức độc quyền với các xí nghiệp ngoài độc quyền\nB. Cạnh tranh giữa các tổ chức độc quyền vối nhau\nC. Cạnh tranh trong nội bộ các tổ chức độc quyền","notes":""},{"id":433,"question":"Thế nào là tư bản cho vay?(NHUNG HOÀNG)","options":["A. Là tư bản hàng hóa mà người chủ của nó nhường cho người khác sử dụng ở trong một thời gian nhất định để thu lợi tức","B. Là tư bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng ở trong một thời gian nhất định để thu lợi tức","C. Là tư bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng ở trong một thời gian nhất định để thu lợi nhuận","D. Là tư bản sản xuất mà người chủ của nó nhường cho người khác sử dụng ở trong một thời gian nhất định để thu lợi tức"],"answerLetter":"B","answerText":"B. Là tư bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng ở trong một thời gian nhất định để thu lợi tức","notes":""},{"id":434,"question":"Đâu là nội dung cơ bản của tái sản xuất xã hội?","options":["A. Tái sản xuất của cải vật chất; tái sản xuất ra quan hệ sản xuất và tái sản xuất môi trường","B. Tái sản xuất của cải vật chất; tái sản xuất sức lao động và tái sản xuất môi trưởng","C. Tái sản xuất của cải vật chất; tái sản xuất sức lao động; tái sản xuất ra lực lượng sản xuất và tái sản xuất môi trường","D. Tái sản xuất của cải vật chất; tái sản xuất sức lao động; tái sản xuất ra quan hệ sản xuất và tái sản xuất môi trường"],"answerLetter":"D","answerText":"D. Tái sản xuất của cải vật chất; tái sản xuất sức lao động; tái sản xuất ra quan hệ sản xuất và tái sản xuất môi trường","notes":""},{"id":435,"question":"Thời gian chu chuyển của tư bản được hiểu:(NHUNG HOÀNG)","options":["A. Thời gian sản xuất + thời gian bán hàng","B. Thời gian sản xuất + thời gian lưu thông","C. Thời gian dự trữ sản xuất + thời gian lưu thông","D. Thời gian sản xuất + thời gian tiếp thị"],"answerLetter":"B","answerText":"B. Thời gian sản xuất + thời gian lưu thông","notes":""},{"id":436,"question":"Căn cứ vào đối tượng trao đổi, mua bán cụ thể có các loại thị trường nào?(NHUNG HOÀNG)","options":["A. Thị trường hàng hóa và thị trường dịch vụ","B. Thị trường hàng hóa, thị trường dịch vụ, thị trường trong nưỡc và thị trường quốc tế","C. Thị trường hàng hóa, thị trường dịch vụ, thị trường trong nước, thị trưởng quốc tế, thị trường tư liệu tiều dùng và thị trường tư liệu sản xuất","D. Thị trường hàng hóa, thị trường dịch vụ và thị trường mua bán"],"answerLetter":"A","answerText":"A. Thị trường hàng hóa và thị trường dịch vụ","notes":""},{"id":437,"question":"Khủng hoàng kinh tế chủ nghĩa tư bản là:(NHUNG HOÀNG)","options":["A. Chủ quan","B. Tất yếu khách quan","C. Nhất thời","D. Có tính thời điểm"],"answerLetter":"B","answerText":"B. Tất yếu khách quan","notes":""},{"id":438,"question":"Những nhân tố ảnh hưởng đến tỷ suất lợi nhuận đó là:(NHUNG HOÀNG)","options":["A. Tỷ suất giá trị thặng dư; tốc độ chu chuyển của tư bản; tiết kiệm tư bản bất biến.","B. Cấu tạo hữu cơ của tư bản; tốc độ chu chuyển của tư bản; tiết kiệm tư bản bất biến.","C. Tỷ suất giá trị thặng dư; cấu tạo hữu cơ của tư bản; tốc độ chu chuyển của tư bản; tiết kiệm tư bản bất biến.","D. Tỷ suất giá trị thặng dư; cấu tạo hữu cơ của tư bản; tốc độ chu chuyển của tư bản; tiết kiệm giá trị thặng dư."],"answerLetter":"C","answerText":"C. Tỷ suất giá trị thặng dư; cấu tạo hữu cơ của tư bản; tốc độ chu chuyển của tư bản; tiết kiệm tư bản bất biến.","notes":""},{"id":439,"question":"Sự hình thành độc quyền dựa trên các nguyên nhân nào sau đây?","options":["A. Sự phát triển của lực lượng sản xuất thúc đẩy các tổ chức độc quyền; cạnh tranh; khủng hoảng sự phát triển của hệ thống tín dụng","B. Sự phát triển của quan hệ sản xuất thúc đấy các tổ chức độc quyền, cạnh tranh; khủng hoảng sự phát triển của hệ thống tín dụng","C. Sự phát triển của phương thức sản xuất tư bản chủ nghĩa thúc đẩy các tổ chức độc quyền; cạnh tranh; khủng hoàng sự phát triển của hệ thống tín dụng","D. Sự phát triển của lực lượng sản xuất thúc đẩy các tổ chức độc quyền; cạnh tranh; khúng hoảng trong sự phát triển của một quốc gia"],"answerLetter":"A","answerText":"A. Sự phát triển của lực lượng sản xuất thúc đẩy các tổ chức độc quyền; cạnh tranh; khủng hoảng sự phát triển của hệ thống tín dụng","notes":""},{"id":440,"question":"Xu hướng chung của sản xuất tư bàn chủ nghĩa là:(NHUNG HOÀNG)","options":["A. Nâng cao mức tiền công","B. Hạ thấp mức tiền công","C. Giữ nguyên mức tiền công"],"answerLetter":"B","answerText":"B. Hạ thấp mức tiền công","notes":""},{"id":441,"question":"Điều gì xảy ra nếu cung thấp hơn cầu?(NHUNG HOÀNG)","options":["A. Giá cả cao hơn giá trị","B. Giá cả thấp hơn giá trị","C. Hàng hóa tạo ra được tăng cao giá bán","D. Hàng hóa phong phú"],"answerLetter":"A","answerText":"A. Giá cả cao hơn giá trị","notes":"(Điều gì xảy ra nếu cung lớn hơn cầu? ->B)"},{"id":442,"question":"Thế nào là thời gian lao động xã hội cần thiết?","options":["A. Là khoảng thời gian sản xuất của tuyệt đại bộ phận hàng hóa","B. Là khoảng thời gian cần thiết để sản xuất ra một loại hàng hóa nhất định trong điều kiện trình độ kỹ thuật trung bình, trình độ khéo léo trung bình và cường độ lao động trung bình","C. Là khoảng thời gian do người có trình độ chuyên môn cao quyết định","D. Là khoảng thời gian cần thiết để sản xuất ra một loại hàng hóa nhất định trong điều kiện trình khoa học trung bình, trình độ khéo léo trung bình và cường độ lao động trung bình"],"answerLetter":"B","answerText":"B. Là khoảng thời gian cần thiết để sản xuất ra một loại hàng hóa nhất định trong điều kiện trình độ kỹ thuật trung bình, trình độ khéo léo trung bình và cường độ lao động trung bình","notes":""},{"id":443,"question":"Nguyên nhân dẫn tới hình thành các tổ chức độc quyền đa ngành đó là:","options":["A. Cạnh tranh gay gắt và đối phó với luật chống độc quyền","B. Cạnh tranh giữa các ngành và cạnh tranh đa quốc gia","C. Thu lợi nhuận kinh doanh từ chúng khoán","D. Đối phó với luật chống độc quyền ở các quốc gia"],"answerLetter":"A","answerText":"A. Cạnh tranh gay gắt và đối phó với luật chống độc quyền","notes":""},{"id":444,"question":"Quốc gia nào thuộc nhóm các nước công nghiệp mới (NICS)?(NHUNG HOÀNG)","options":["A. Hoa Kỳ","B. Singapore","C. Việt Nam","D. Trung Quốc"],"answerLetter":"B","answerText":"B. Singapore","notes":""},{"id":445,"question":"Cho ví dụ: nhà tư bản đầu tư 50 USD để mua nguyên vật liệu dệt vải, tốn 5 USD cho hao mòn máy móc để dệt được 10 mét vải từ nguyên liệu trên, 15 USD đề trả công cho công nhân làm việc trong 8 giờ theo thoả thuận, nhưng sau 4 giờ thì công nhân đã làm xong 10 mét vải. Để tăng giá trị thặng dư được tạo ra 15 USD, nhà tư bản cần làm gì?","options":["A. Nhà tư bản cần bắt công nhân tăng ca 4 giờ nữa bên cạnh 8 giờ thỏa thuận","B. Nhà tư bản không cần làm gì cả chỉ ngồi không thì giá trị thặng dư cũng tạo ra","C. Đầu tư thêm 50 USD cho nguyên liệu, 5 USD cho hao mòn máy móc và bắt công nhân làm thêm 4 giờ nữa như thỏa thuận","D. Ngay từ thời điểm làm xong 4 giờ thì giá trị thặng dư đã được tạo ra rồi"],"answerLetter":"C","answerText":"C. Đầu tư thêm 50 USD cho nguyên liệu, 5 USD cho hao mòn máy móc và bắt công nhân làm thêm 4 giờ nữa như thỏa thuận","notes":""},{"id":446,"question":"Nền kinh tế tri thức có bản chất là gì?","options":["A. Một phương thức sản xuất mới","B. Một hình thái kinh tế - xã hội mới","C. Một nấc thang phát triển của lực lượng sản xuất","D. Một giai đoạn phát triển cao của nên kinh tế công nghiệp"],"answerLetter":"C","answerText":"C. Một nấc thang phát triển của lực lượng sản xuất","notes":""},{"id":447,"question":"Thị trường được hiểu là gì?(NHUNG HOÀNG)","options":["A. Tổng hòa những quan hệ kinh tế","B. Tổng hòa những quan hệ xã hội","C. Tổng hòa những quan hệ lợi ích","D. Tổng hòa các quan hệ trao đổi"],"answerLetter":"A","answerText":"A. Tổng hòa những quan hệ kinh tế","notes":""},{"id":448,"question":"Đối với hao phí lao động cá biệt, quy luật giá trị yêu cầu điều gì?","options":["A. Hao phí lao động cá biệt < hao phí lao động xã hội cần thiết","B. Hao phí lao động cá biệt = hao phí lao động xã hội cn thiết","C. Hao phí lao động cá biệt ≥ hao phí lao động xã hội cần thiết","D. Hao phái lao động cá biệt phải vận động cùng với hao phí lao động xã hội cần thiết"],"answerLetter":"B","answerText":"B. Hao phí lao động cá biệt = hao phí lao động xã hội cn thiết","notes":""},{"id":449,"question":"Cạnh tranh trong nội bộ ngành dẫn đến hình thành điều gì?(NHUNG HOÀNG)","options":["A. Giá cả sản xuất","B. Giá trị thị trường","C. Giá cà hàng hóa","D. Giá trị thặng dư"],"answerLetter":"B","answerText":"B. Giá trị thị trường","notes":""},{"id":450,"question":"Trong nền sản xuất hàng hóa ngày nay, hình thành những hàng hóa có yếu tố khác với hàng hóa thông thường. Đặc trưng của chúng là","options":["A. Có giá trị sử dụng, có giá cả, có thể trao đổi, mua bán nhưng không do hao phí lao động trực tiếp tạo ra","B. Có giá trị, có giá cả, có thể trao đổi, mua bán nhưng không do hao phí lao động trực tiếp tạo ra","C. Có giá trị sử dụng, có giá trị, có thể trao đổi, mua bán nhưng không do hao phí lao động trực tiếp tạo ra","D. Có giá trị, có thể trao đổi, mua bán nhưng không do hao phí lao động trực tiếp tạo ra"],"answerLetter":"C","answerText":"C. Có giá trị sử dụng, có giá trị, có thể trao đổi, mua bán nhưng không do hao phí lao động trực tiếp tạo ra","notes":""},{"id":451,"question":"Trên phương diện kinh tế chính trị, tái sản xuất là(NHUNG HOÀNG)","options":["A. Là quá trình sản xuất được lặp đi lặp lại và phục hồi không ngừng","B. Là quá trình sản xuất liên tục","C. Là sự khôi phục lại sản xuất"],"answerLetter":"A","answerText":"A. Là quá trình sản xuất được lặp đi lặp lại và phục hồi không ngừng","notes":""},{"id":452,"question":"Theo nghĩa trửu tượng, thị trưởng được hiểu như thế nào?","options":["A. Là nơi diễn ra hành vi trao đổi, mua bán hàng hóá giữa các chủ thế kinh tế với nhau","B. Là tổng thể các yếu tố kinh tế vận động theo quy luật của thị trường","C. Là nơi người bán quyết định giá cà, người mua chi được quyền lựa chọn","D. Là tổng hòà các mỗi quan hệ liên quan đến trao đổi, mua bán hàng hóá, dịch vụ trong xã hội"],"answerLetter":"D","answerText":"D. Là tổng hòà các mỗi quan hệ liên quan đến trao đổi, mua bán hàng hóá, dịch vụ trong xã hội","notes":""},{"id":453,"question":"Tư bản khả biến tồn tại dưới hình thức nào?(NHUNG HOÀNG)","options":["A. Tiền lương phải trả cho người lao động","B. Nguyên liệu, vật liệu, máy móc, sức lao động","C. Hàng hóa, sức lao động","D. Vật liệu, máy móc, tiên công trả cho công nhân"],"answerLetter":"A","answerText":"A. Tiền lương phải trả cho người lao động","notes":""},{"id":454,"question":"Cấu tạo kỹ thuật của tư bản được hiểu là(NHUNG HOÀNG)","options":["A. Tỷ lệ giữa số lượng tư liệu sản xuất và số lượng sức lao động sử dụng những tư liệu sản xuất đó trong quá trình sản xuất","B. Tỷ lệ giữa số lượng nguyên liệu tiêu hao trong quá trình sản xuất và số lượng sức lao động sử dụng những tư liệu sản xuất đó trong quá trình sản xuất","C. Tỷ lệ giữa số lượng sức lao động sử dụng trong quá trình sản xuất và tư liệu sản xuất trong quá trình sản xuất","D. Tỷ lệ giữa số lượng giá trị của tư bản bất biến và số lượng giá trị của tư bản khả biến cần thiết để tiến hành sản xuất"],"answerLetter":"A","answerText":"A. Tỷ lệ giữa số lượng tư liệu sản xuất và số lượng sức lao động sử dụng những tư liệu sản xuất đó trong quá trình sản xuất","notes":""},{"id":455,"question":"Địa tô tư bản chủ nghĩa được hiểu là gì?(NHUNG HOÀNG)","options":["A. Phần giá trị thặng dư còn lại sau khi đã khấu trừ đi phần lợi nhuận bình quân mà các nhà tư bản kinh doanh nông nghiệp phải nộp cho địa chủ","B. Phần giá trị thặng dư còn lại sau khi đã khấu trừ đi phần thu nhập bình quân mà các nhà tư bản kinh doanh nông nghiệp phải nộp cho địa chủ","C. Phần giá trị còn lại sau khi đã khấu trừ đi phần lợi nhuận bình quân mà các nhà tư bản kinh doanh đất phải nộp cho địa chủ","D. Phần giá trị còn lại sau khi đã khấu trừ đi phần lợi nhuận thu được mà các nhà tư bản kinh doanh nông nghiệp phải nộp cho địa chủ"],"answerLetter":"A","answerText":"A. Phần giá trị thặng dư còn lại sau khi đã khấu trừ đi phần lợi nhuận bình quân mà các nhà tư bản kinh doanh nông nghiệp phải nộp cho địa chủ","notes":""},{"id":456,"question":"Trong chủ nghĩa tư bản, người công nhân bán:(073-356-8678)","options":["A. Sức lao động cho nhà tư bản","B. Lao động cho nhà tư bản","C. Hàng hóa cho nhà tư bản"],"answerLetter":"A","answerText":"A. Sức lao động cho nhà tư bản","notes":""},{"id":457,"question":"Trong nền kinh tế thị trưởng thì thị trường có vai trò gì?","options":["A. Điều tiết sản xuất","B. Phân bổ lao động","C. Là công cụ phân bổ các nguồn lực kinh tế","D. Phân bổ tư liệu sàn xuất"],"answerLetter":"C","answerText":"C. Là công cụ phân bổ các nguồn lực kinh tế","notes":""},{"id":458,"question":"Trong xuất khẩu tư bản, có hai hình thức đầu tư đó là:(NHUNG HOÀNG)","options":["A. Đầu tư trực tiếp và đầu tư gián tiếp","B. Đầu tư trực tiếp và đầu tư ủy nhiệm","C. Đầu tư trực tiếp và đầu tư nhà nước","D. Đầu tư tư bản tư nhân và đầu tư tư bản nhà nước"],"answerLetter":"A","answerText":"A. Đầu tư trực tiếp và đầu tư gián tiếp","notes":""},{"id":459,"question":"Khi các xí nghiệp tham gia chỉ mất độc quyền về lưu thông là hình thức độc quyền nào?(NHUNG HOÀNG)","options":["A. Cartel","B. Syndicate","C. Trust","D. Consortium"],"answerLetter":"B","answerText":"B. Syndicate","notes":""},{"id":460,"question":"Chủ nghĩa tư bản độc quyền được xem là:(NHUNG HOÀNG)","options":["A. Một phương thức sản xuất","B. Một giai đoạn phát triển của phương thức sản xuất tư bản chủ nghĩa","C. Một hình thái kinh tế xã hội","D. Thời kỳ quá độ đi lên chủ nghĩa xã hội"],"answerLetter":"B","answerText":"B. Một giai đoạn phát triển của phương thức sản xuất tư bản chủ nghĩa","notes":""},{"id":461,"question":"Lao động trừu tượng tạo ra","options":["A. Giá trị của hàng hoá","B. Giá trị sử dụng của hàng hóa","C. Tiền lương","D. Lợi nhuận cho tư bản"],"answerLetter":"A","answerText":"A. Giá trị của hàng hoá","notes":""},{"id":462,"question":"Quy luật giá trị có tác dụng:(NHUNG HOÀNG)","options":["A. Điều tiết sản xuất và lưu thông hàng hóa.","B. Cải tiến kỹ thuật, tăng năng suất lao động","C. Phân hóá những người sản xuất","D. Các phương án trả lời đêu đúng"],"answerLetter":"D","answerText":"D. Các phương án trả lời đêu đúng","notes":""},{"id":463,"question":"Tính chất của tư bản bất biến (c) là:(NHUNG HOÀNG)","options":["A. Giá trị của nó không thay đổi vẽ lượng và được chuyển nguyên vẹn sang sản phẩm","B. Giá trị của nó không thay đổi và được chuyển ngay sang sản phẩm sau một chu kỳ sản xuất","C. Giá trị của nó chuyển dân vào sản phẩm qua khấu hao"],"answerLetter":"A","answerText":"A. Giá trị của nó không thay đổi vẽ lượng và được chuyển nguyên vẹn sang sản phẩm","notes":""},{"id":464,"question":"Một trong những tác động tích cực của quy luật giá trị là gì?","options":["A. Người sản xuất có thể sản xuất nhiều loại hàng hóá","B. Người tiêu dùng mua được hàng hóá rẻ","C. Người sản xuất ngày càng giàu có","D. Kích thích lực lượng sản xuất, năng suất lao động tăng"],"answerLetter":"D","answerText":"D. Kích thích lực lượng sản xuất, năng suất lao động tăng","notes":""},{"id":465,"question":"Thế nào là lao động giản đơn?(NHUNG HOÀNG)","options":["A. Là lao động không cần trài qua đào tạo cũng có thể làm được","B. Là lao động làm công việc đơn gian","C. Là lao động chi làm một công đoạn của quá trình tạo ra hàng hóá","D. Lao động của người dưới tuối thành niên"],"answerLetter":"A","answerText":"A. Là lao động không cần trài qua đào tạo cũng có thể làm được","notes":""},{"id":466,"question":"Sự phát triển của các tổ chức độc quyền trong ngân hàng đã làm thay đổi quan hệ giữa ngân hàng và các doanh nghiệp công nghiệp đó là:","options":["A. Từ trung gian thanh toán trở thành khống chế mọi hoạt động kinh tế - xã hội","B. Từ trung gian thanh toán trở thành cổ đông của các doanh nghiệp nhà nước","C. Từ hoạt động cho vay trở thành hoạt động khống chế doanh tư nhân","D. Từ hoạt động cho vay trở thành chi phối các doanh nghiệp"],"answerLetter":"A","answerText":"A. Từ trung gian thanh toán trở thành khống chế mọi hoạt động kinh tế - xã hội","notes":""},{"id":467,"question":"Theo công thức chung của tư bản thì T' được tính như thế nào?","options":["A. T'= T + t (t>0)","B. T'= T +t (t<0)","C. T'= T + t t(t>=0)","D. T'= T +t +t(t<=0)"],"answerLetter":"A","answerText":"A. T'= T + t (t>0)","notes":""},{"id":468,"question":"Quá trình lưu thông tư bản là: (NHUNG HOÀNG)","options":["A. Tuần hoàn và chu chuyển giá trị hàng hóa","B. Tuần hoàn và chu chuyển tư bản","C. Tuần hoàn và chu chuyển hàng hóa","D. Tuần hoàn và tích lũy tư bản"],"answerLetter":"B","answerText":"B. Tuần hoàn và chu chuyển tư bản","notes":""},{"id":469,"question":"Trong nền kinh tế thị trường, thị trường KHÔNG thực hiện vai trò nào sau đây? (NHUNG HOÀNG)","options":["A. Thực hiện giá trị hàng hóa","B. Phân bổ tư liệu sản xuất","C. Điều tiết nguồn lực cho sản xuất","D. Hoạch định chính sách kinh tế"],"answerLetter":"D","answerText":"D. Hoạch định chính sách kinh tế","notes":""},{"id":470,"question":"Tại sao việc phát triển kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam là tất yếu khách quan? Chọn 2 đáp án. (NHUNG HOÀNG)","options":["A. Kinh tế thị trường có thế tự hình thành khi có các điều kiện khách quan.","B. Kinh tế thị trường tư bản chủ nghĩa là mô hình tối ưu nhất cho mọi quốc gia.","C. Kinh tế thị trường là động lực thúc đấy lực lượng sản xuất phát triến nhanh và hiệu quả.","D. Kinh tế thị trường giúp Việt Nam độc lập hoàn toàn khỏi các quy luật của thị trường toàn cầu."],"answerLetter":"AC","answerText":"A. Kinh tế thị trường có thế tự hình thành khi có các điều kiện khách quan.\nC. Kinh tế thị trường là động lực thúc đấy lực lượng sản xuất phát triến nhanh và hiệu quả.","notes":""},{"id":471,"question":"Lựa chọn đáp án đúng nhất: Mong muốn dân giàu, nước mạnh, dân chủ, công bằng, văn minh là mong muốn chung của ai?(NHUNG HOÀNG)","options":["A. Chỉ các quốc gia phát triển","B. Chỉ các quốc gia đang phát triễn","C. Các nước xã hội chủ nghĩa mới giảnh được chủ quyền dân tộc","D. Tất cả các quốc gia trên thế giới"],"answerLetter":"D","answerText":"D. Tất cả các quốc gia trên thế giới","notes":""},{"id":472,"question":"Theo C.Mác có một loại hàng hóa đặc biệt mà khi sử dụng nó thì giá trị của nó không những được bảo tồn mà còn tạo ra những giá trị mới lớn hơn giá trị bản thân nó. Hàng hóa đó là gì?","options":["A. Hàng hóa sức lao động","B. Thức ăn","C. Dịch vụ chăm sóc sức khoẻ","D. Nước uống"],"answerLetter":"A","answerText":"A. Hàng hóa sức lao động","notes":""},{"id":473,"question":"Sự tác động giữa cung và cầu sẽ hình thành:","options":["A. Giá trị cân bằng (hay giá trị thị trường)","B. Giá cả cân bằng ( hay giá cả thị trường)","C. Giá cả hàng hóa","D. Giá trị hàng hóa"],"answerLetter":"B","answerText":"B. Giá cả cân bằng ( hay giá cả thị trường)","notes":""},{"id":474,"question":"Yếu tố cấu thành thể chế kinh tế thị trường định hướng xã hội chủ nghĩa là:(NHUNG HOÀNG)","options":["A. Các bộ quy tắc, chế định, luật pháp","B. Các chủ thể tham gia kinh tế thị trường định hướng xã hội chủ nghĩa","C. Cơ chế vận hành kinh tế thị trường định hướng xã hội chủ nghĩa","D. Các yếu tố thị trường và các thị trường","E. Tất cả phương án trên"],"answerLetter":"E","answerText":"E. Tất cả phương án trên","notes":""},{"id":475,"question":"Sự vận động của tiền trong nền sản xuất hàng hóa giản đơn (H-T-H), sự vận động của tiền trong nền sản xuất hàng hóa tư bản (T-H-T'). Hãy chỉ ra điểm chung của hai hình thức vận động này? (lựa chọn hai đáp án)","options":["A. Đều có hai thực thể vật chất là tiền và hàng.","B. Đều bắt đầu bằng hành vi bán.","C. Đều có hai hành vi đối lập nhau - mua và bán.","D. Đều kết thúc bằng hành vi mua."],"answerLetter":"AC","answerText":"A. Đều có hai thực thể vật chất là tiền và hàng.\nC. Đều có hai hành vi đối lập nhau - mua và bán.","notes":""},{"id":476,"question":"Các nhân tố nào sau đây ảnh hưởng đến năng suất lao động?","options":["A. Trình độ khéo léo trung bình của người lao động; Mức độ phát triển của khoa học và trình độ áp dụng khoa học vào quy trình công nghệ; Sự kết hợp xã hội của quá trình sản xuất; Quy mô và hiệu suất của tư liệu sản xuất; Các điều kiện tự nhiên","B. Các chính sách quy định từ nhà nước; Phương pháp và quy định giờ làm việc và đãi ngộ; Sự hợp tác của quá trình làm việc nhóm hiệu quả; Sự phát triển và đào tạo liên tục; Khả năng sáng tạo và đổi mới và thay đổi tư duy","C. Trình độ và kỹ năng của người lao động ngày càng được nâng cao; Môi trường làm việc phù hợp phát huy hết khả năng cá nhân; Quản lý và tổ chức công việc có sự phân công rõ ràng; Sức khỏe và tình trạng thể chất của người lao động được đảm bảo; Các chuẩn mực quy tắc và thái độ của người lao động trong lao động sản xuất"],"answerLetter":"A","answerText":"A. Trình độ khéo léo trung bình của người lao động; Mức độ phát triển của khoa học và trình độ áp dụng khoa học vào quy trình công nghệ; Sự kết hợp xã hội của quá trình sản xuất; Quy mô và hiệu suất của tư liệu sản xuất; Các điều kiện tự nhiên","notes":""},{"id":477,"question":"Mục tiêu mà nền kinh tế thị trường định hướng xã hội chủ nghĩa của Việt Nam hướng tôi bao gồm những gì? Chọn hai đáp án.","options":["A. Xã hội \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\".","B. Kinh tế chỉ vận hành dựa trên nguyên tắc thị trường tự do.","C. Cân bằng lợi ích giữa các thành phần kinh tế.","D. Hoàn toàn không cần sự quản lý của Nhà nước."],"answerLetter":"AC","answerText":"A. Xã hội \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\".\nC. Cân bằng lợi ích giữa các thành phần kinh tế.","notes":""},{"id":478,"question":"Hiện nay, do sự phát triển của lực lượng sản xuất và khoa học công nghệ đã hình thành các tổ chức độc quyền mới đó là:(NHUNG HOÀNG)","options":["A. Concern và Conglomerate","B. Concern và Syndicate","C. Concern và Trust","D. Concern, Conglomerate và consortium"],"answerLetter":"A","answerText":"A. Concern và Conglomerate","notes":""},{"id":479,"question":"Trong cùng một thời gian lao động khi số lượng sản phẩm tăng lên còn giá trị một đơn vị hàng hóa và các điều khác không thay đối thì đó là kết quả của:","options":["A. Tăng cường độ lao động","B. Tăng năng suất lao động và tăng cường độ lao động","C. Tăng năng suất lao động","D. Các phương án trên đều sai"],"answerLetter":"A","answerText":"A. Tăng cường độ lao động","notes":""},{"id":480,"question":"Lựa chọn đáp án đúng nhất: Trong nền kinh tế thị trường, hoạt động kinh tế được biểu hiện như thể nào?","options":["A. Vô cùng phong phú","B. Phong phú","C. Trao đối mua bán","D. Sản xuất và trao đối hàng hóa"],"answerLetter":"A","answerText":"A. Vô cùng phong phú","notes":""},{"id":481,"question":"Lao động xã hội của người sản xuất hàng hoá kết tinh trong hàng hoá được gọi là gì?(NHUNG HOÀNG)","options":["A. Giá trị của hàng hoá","B. Giá trị sử dụng của hàng hoá","C. Giá cả hàng hoá","D. Tiền lương lao động"],"answerLetter":"A","answerText":"A. Giá trị của hàng hoá","notes":""},{"id":482,"question":"Điều gì sẽ xảy ra nếu xuất hiện độc quyền trong nền kinh tế thị trường?","options":["A. Tạo ra khả năng và động lực to lớn cho việc nghiên cứu khoa học - kỹ thuật","B. Làm giảm năng xuất lao động và tăng nhu cầu lao động lành nghề","C. Độc quyền làm giảm quy mô kinh tế của quốc gia","D. Làm lành mạnh hơn sự cạnh tranh trong nền kinh tế"],"answerLetter":"A","answerText":"A. Tạo ra khả năng và động lực to lớn cho việc nghiên cứu khoa học - kỹ thuật","notes":""},{"id":483,"question":"Kinh tế thị trường định hướng xã hội chủ nghĩa là mô hình kinh tế như thế nào của thời quá độ lên chủ nghĩa xã hội ở nước ta?","options":["A. Mô hình kinh tế tổng quát","B. Mô hình kinh tế tập trung tổng quát","C. Mô hình kinh tế Nhà nước","D. Mô hình kinh tế tập trung"],"answerLetter":"A","answerText":"A. Mô hình kinh tế tổng quát","notes":""},{"id":484,"question":"Những quan hệ kinh tế của một xã hội nhất định được biểu hiện trước hết dưới hình thức nào sau đây?","options":["A. Quyền lực","B. Văn hóa","C. Lợi ích","D. Chính trị"],"answerLetter":"C","answerText":"C. Lợi ích","notes":""},{"id":485,"question":"Để nhận biết được thuộc tính giá trị của hàng hóa chúng ta xét chúng trong mối quan hệ","options":["A. Trao đổi","B. Mua bán","C. Kinh doanh","D. Tích trữ"],"answerLetter":"A","answerText":"A. Trao đổi","notes":""},{"id":486,"question":"Lao động cụ thể có vai trò gì?(NHUNG HOÀNG)","options":["A. Tạo ra giá trị sử dụng của hàng hóa","B. Tạo ra giá trị trao đổi của hàng hóa","C. Tạo ra giá trị của hàng hóa","D. Tạo ra lao động trừu tượng"],"answerLetter":"A","answerText":"A. Tạo ra giá trị sử dụng của hàng hóa","notes":""},{"id":487,"question":"Xét trên phương diện lịch sủ, các hình thức tổ chức độc quyền phát triển từ thấp đến cao bao gồm:","options":["A. Trust, Cartel, Syndicate, Consortium","B. Cortium, Cartel, Syndicate, Trust","C. Syndicate, Cartel, Trust, Consortium","D. Cartel, Syndicate, Trust, Consortium"],"answerLetter":"D","answerText":"D. Cartel, Syndicate, Trust, Consortium","notes":""},{"id":488,"question":"Phát triển kinh tế thị trường định hướng xã hội chủ nghĩa sẽ phá vỡ tính chất nào sau đây của nền kinh tế?","options":["A. Tự cấp, tự túc, lạc hậu.","B. Tự do cạnh tranh.","C. Khủng hoàng kinh tế.","D. Khoảng cách giàu nghèo, đạo đức xã hội."],"answerLetter":"A","answerText":"A. Tự cấp, tự túc, lạc hậu.","notes":""},{"id":489,"question":"Việt Nam tham gia sáng lập diễn đàn hợp tác Á -Âu (ASEM) năm nào?","options":["A. 1996","B. 1997","C. 1998","D. 1999"],"answerLetter":"A","answerText":"A. 1996","notes":""},{"id":490,"question":"Trọng trạng thái độc quyền, cạnh tranh trong nội bộ các tổ chức độc quyền nhằm mục đích gì? (lựa chọn 3 đáp án)","options":["A. Giành lợi thế trong hệ thống","B. Chiếm tỷ lệ cổ phần khống chế","C. Phân chia lợi ích có lợi hơn","D. Để xác định địa vị độc quyền"],"answerLetter":"ABC","answerText":"A. Giành lợi thế trong hệ thống\nB. Chiếm tỷ lệ cổ phần khống chế\nC. Phân chia lợi ích có lợi hơn","notes":""},{"id":491,"question":"Khi sản xuất và trao đối hàng hóa phát triên đòi hỏi phải có một vật ngang giá chung xuất hiện ở hình thái nào?","options":["A. Hình thái giá trị giản đơn hay ngẫu nhiên","B. Hình thái mở rộng của giá trị","C. Hình thái chung của giá trị","D. Hình thái tiên tệ"],"answerLetter":"C","answerText":"C. Hình thái chung của giá trị","notes":""},{"id":492,"question":"Hàng hóa cá nhân được hiểu là:","options":["A. Một loại hàng hóa nếu được tiêu dùng rồi thì người khác không thể tiêu dùng được nữa","B. Một loại hàng hóa nếu được tiêu dùng rồi thì người khác vẫn có thể tái sử dụng lại","C. Một loại hàng hóa khi được tiêu dùng và bán đi thì sẽ giảm đi giá trị","D. Một loại hàng hóa nếu được sử dụng và tái sử dụng tốt giá trị sẽ tăng lên"],"answerLetter":"A","answerText":"A. Một loại hàng hóa nếu được tiêu dùng rồi thì người khác không thể tiêu dùng được nữa","notes":""},{"id":493,"question":"Đâu KHÔNG phải là hình thức biểu hiện của giá trị thặng dư trong nền kinh tế thị trường?","options":["A. Thuế khoá","B. Lợi nhuận","C. Lợi tức","D. Địa tô tư bản chủ nghĩa"],"answerLetter":"A","answerText":"A. Thuế khoá","notes":""},{"id":494,"question":"Quá trình sản xuất giá trị thặng dư là sự thống nhất giữa các yếu tố nào sau đây? (Chọn 2 đáp án đúng)","options":["A. Quá trình tạo ra giá trị mới","B. Làm tăng giá trị","C. Quá trình tiêu thụ sản phẩm","D. Quá trình vận chuyển"],"answerLetter":"AB","answerText":"A. Quá trình tạo ra giá trị mới\nB. Làm tăng giá trị","notes":""},{"id":495,"question":"Thể chế kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam chưa đồng bộ là do?(NHUNG HOÀNG)","options":["A. Mới được hình thành và phát triển, cho nên, việc tiếp tục hoàn thiện thể chế là yêu cầu mang tính khách quan","B. Xuất phát từ yêu cầu nâng cao năng lực quản lý của nhà nước trong nên kinh tế thị trường định hướng xã hội chú nghĩa","C. Trong nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam còn nhiều khuyết điểm, hệ thống vừa chưa đủ mạnh vừa chưa mang tính hiệu quả cao","D. Tất cả phương án trên"],"answerLetter":"D","answerText":"D. Tất cả phương án trên","notes":""},{"id":496,"question":"Khi tích tụ và tập trung sản xuất phát triển đến một mức độ nào đó sẽ dẫn đến vẫn đề gì trong nên sản xuất tư bản?","options":["A. Độc quyền","B. Tự do cạnh tranh","C. Khủng hoáng kinh tế","D. Sản xuất thừa"],"answerLetter":"A","answerText":"A. Độc quyền","notes":""},{"id":497,"question":"Để hoàn thiện thể chế về sở hữu trong nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam cần thực hiện những nội dung nào?","options":["A. Thể chế hóa đầy đủ quyền tài sản của nhà nước, tổ chức và cá nhân","B. Tiếp tục hoàn thiện pháp luật về đất đai để huy động và sử dụng hiệu quà đất đai, khắc phục tình trạng sử dụng đất lãng phí","C. Hoàn thiện pháp luật về quản lý, khai thác và sử dụng tài nguyên thiên nhiên","D. Hoàn thiện thiết chế cho sự phát các thành phần kinh tế, các loại hình doanh nghiệp"],"answerLetter":"ABC","answerText":"A. Thể chế hóa đầy đủ quyền tài sản của nhà nước, tổ chức và cá nhân\nB. Tiếp tục hoàn thiện pháp luật về đất đai để huy động và sử dụng hiệu quà đất đai, khắc phục tình trạng sử dụng đất lãng phí\nC. Hoàn thiện pháp luật về quản lý, khai thác và sử dụng tài nguyên thiên nhiên","notes":""},{"id":498,"question":"Hàng hóa được trao đối với nhau dựa trên yếu tố nào?","options":["A. Đều là sản phẩm của lao động","B. Một lượng lao động bằng nhau để tạo ra số lượng giá trị tương đương","C. Đều là sản phần của quá trình trao đổi","D. Có những công dụng như nhau"],"answerLetter":"AB","answerText":"A. Đều là sản phẩm của lao động\nB. Một lượng lao động bằng nhau để tạo ra số lượng giá trị tương đương","notes":""},{"id":499,"question":"Cum từ nào thích hợp để điên vào dấu (...) sau: \"Kinh tế thị trường định hướng... là nền kinh tế vận hành theo các quy luật của...\".?","options":["A. Xã hội chủ nghĩa/ Thị trường.","B. Xã hội chủ nghĩa/Sản xuất hàng hóa.","C. Thị trường/ Xã hội.","D. Xã hội chủ nghĩa/cạnh tranh hàng hóa."],"answerLetter":"A","answerText":"A. Xã hội chủ nghĩa/ Thị trường.","notes":""},{"id":500,"question":"Tư bản bất biến tồn tại dưới hình thức nào?","options":["A. Nguyên liệu, nhiên liệu, vật liệu, máy móc","B. Nguyên liệu, vật liệu, máy móc, sức lao động","C. Máy móc, sức lao động","D. Vật liệu, máy móc, tiền công trả cho công nhân"],"answerLetter":"A","answerText":"A. Nguyên liệu, nhiên liệu, vật liệu, máy móc","notes":""},{"id":501,"question":"Đối tượng nghiên cứu của Kinh tế chính trị được hiểu là:","options":["A. Một thể thống nhất các quan hệ giữa người với người trong quá trình sản xuất và trao đổi","B. Các quan hệ trong mỗi khâu","C. Các quan hệ giữa các khâu của quá trình tái sản xuất xã hội","D. Các quan hệ giữa các quốc gia trong quá trình sản xuất ra sản phẩm"],"answerLetter":"ABC","answerText":"A. Một thể thống nhất các quan hệ giữa người với người trong quá trình sản xuất và trao đổi\nB. Các quan hệ trong mỗi khâu\nC. Các quan hệ giữa các khâu của quá trình tái sản xuất xã hội","notes":""},{"id":502,"question":"Quy luật kinh tế tồn tại mang tính chất:","options":["A. Chủ quan","B. Khách quan","C. Vừa chủ quan vừa khách quan","D. Không có đáp án đúng"],"answerLetter":"B","answerText":"B. Khách quan","notes":""},{"id":503,"question":"Quy luật giá trị yêu cầu sản xuất và trao đối hàng hóa phải tiến hành trên cơ sở nào?(NHUNG HOÀNG)","options":["A. Hao phí lao động xã hội cần thiết","B. Hao phí lao động cá biệt","C. Hao phí lao động tư nhân","D. Hao phí lao động cụ thế"],"answerLetter":"A","answerText":"A. Hao phí lao động xã hội cần thiết","notes":""},{"id":504,"question":"Lợi ích kinh tế là gì?","options":["A. Là lợi ích vật chất","B. Là lợi ích vật chất và các dịch vụ tương ứng đi kèm","C. Là lợi ích vật chất và lợi ích thu được khi thực hiện các hoạt động kinh tế của con người","D. Là lợi ích vật chất và lợi ích dịch vụ thu được khi thực hiện các hoạt động kinh tế của con người"],"answerLetter":"C","answerText":"C. Là lợi ích vật chất và lợi ích thu được khi thực hiện các hoạt động kinh tế của con người","notes":""},{"id":505,"question":"Để sức lao động trở thành hàng hóa thì cần những điều kiện nào? (Chọn 2 đáp án)","options":["A. Người lao động được tư do về thân thế","B. Người lao động không có đủ tư liệu sản xuất","C. Người lao động có tư liệu sản xuất","D. Người lao động đang làm nô lệ cho một cá nhân trong xã hội"],"answerLetter":"AB","answerText":"A. Người lao động được tư do về thân thế\nB. Người lao động không có đủ tư liệu sản xuất","notes":""},{"id":506,"question":"Tiền trong nền sản xuất hàng hóa giản đơn vận động trong quan hệ nào sau đây?","options":["A. H-T-H","B. T-H-T","C. H-T'-H","D. T-H-T'"],"answerLetter":"A","answerText":"A. H-T-H","notes":""},{"id":507,"question":"Những hạn chế của chủ nghĩa tư bản bắt nguồn từ mâu thuẫn cơ bản của chủ nghĩa tư bản, đó là mâu thuẫn nào?","options":["A. Mâu thuẫn giữa trình độ xã hội hóa ngày càng cao của lực lượng sản xuất với quan hệ sản xuất dựa trên quan hệ chiếm hữu tư nhân tư bản chủ nghĩa về tư liệu tiêu dùng","B. Mâu thuẫn giữa trình độ xã hội hóa ngày càng cao của lực lượng sản xuất với quan hệ sản xuất dựa trên quan hệ chiêm hữu tư nhân tư bản chủ nghĩa về tư liệu sản xuất","C. Mâu thuẫn giữa trình độ công nghiệp hóa ngày càng cao của lực lượng sản xuất với quan hệ sản xuất dựa trên quan hệ chiếm hữu tư nhân tư bản chủ nghĩa vẽ tư liệu sản xuất.","D. Mâu thuẫn giữa trình độ trí tuệ hóa ngày càng cao của lực lượng sản xuất với quan hệ sản xuất dựa trên quan hệ chiếm hữu tư nhân tư bàn chủ nghĩa về tư liệu tiêu dùng."],"answerLetter":"B","answerText":"B. Mâu thuẫn giữa trình độ xã hội hóa ngày càng cao của lực lượng sản xuất với quan hệ sản xuất dựa trên quan hệ chiêm hữu tư nhân tư bản chủ nghĩa về tư liệu sản xuất","notes":""},{"id":508,"question":"Hãy chỉ ra đặc điểm cơ bản của tổ chức độc quyền Syndicate?","options":["A. Giữ độc lập về sản xuất, chi mãt độc lập về lưu thông hàng hóa","B. Giữ độc lập vẽ lưu thông, chi mất độc lập về sản xuất hàng hóa","C. Giữ độc lập về lưu thông, Giữ độc lập về sản xuất hàng hóa","D. Giữ độc lập vê sản xuất, chi mãt một phần nhỏ tính độc lập về lưu thông hàng hóa"],"answerLetter":"A","answerText":"A. Giữ độc lập về sản xuất, chi mãt độc lập về lưu thông hàng hóa","notes":""},{"id":509,"question":"Trong quan hệ giữa các lợi ích kinh tế chung tồn tại dưới dạng:","options":["A. Vừa thống nhất vửa mâu thuẫn","B. Thống nhất","C. Mâu thuẫn","D. Không có đáp án đúng"],"answerLetter":"A","answerText":"A. Vừa thống nhất vửa mâu thuẫn","notes":""},{"id":510,"question":"Có bao nhiêu mô hình công nghiệp hóa tiêu biểu trên thế giới?(NHUNG HOÀNG)","options":["A. 3","B. 4","C. 5","D. 6"],"answerLetter":"A","answerText":"A. 3","notes":""},{"id":511,"question":"Đâu là thuộc tính của hàng hóa sức lao động? (Chọn 2 đáp án)","options":["A. Giá trị","B. Tự do","C. Giá trị sử dụng","D. Sức khỏe của người lao động"],"answerLetter":"AC","answerText":"A. Giá trị\nC. Giá trị sử dụng","notes":""},{"id":512,"question":"Dựa vào căn cứ nào để phân chia thị trường hàng hóa và thị trường dịch vụ?","options":["A. Đối tượng hàng hóa đưa ra trao đối, mua bán","B. Căn cứ vào tính chuyên biệt của thị trường","C. Đầu vào, đầu ra của quá trình sản xuất","D. Tính chất và cơ chế vận hành của thị trường"],"answerLetter":"A","answerText":"A. Đối tượng hàng hóa đưa ra trao đối, mua bán","notes":""},{"id":513,"question":"Theo A. Smith kinh tế chính trị là một ngành khoa học gắn với chính khách hay nhà lập pháp gắn với những mục tiêu nào?","options":["A. Tạo ra nguồn thu nhập dồi dào và sinh kế phong phú cho người dân","B. Tạo ra khả năng có được nguồn ngẫn sách đãy đủ cho nhà nước để thực hiện nhiệm vụ công","C. Tạo ra những giá trị kinh tế mới giúp tăng trưởng kinh tế và tiẽn bộ công bằng xã hội","D. Tạo ra khả năng có được ai cũng có đầy đủ những phúc lợi xã hội cần thiết"],"answerLetter":"AB","answerText":"A. Tạo ra nguồn thu nhập dồi dào và sinh kế phong phú cho người dân\nB. Tạo ra khả năng có được nguồn ngẫn sách đãy đủ cho nhà nước để thực hiện nhiệm vụ công","notes":""},{"id":514,"question":"Một hệ giá trị toàn diện gồm cà dân giàu, nước mạnh, dân chủ, công bằng, văn minh là hệ giá trị của xã hội nào mà loài người phải phấn đấu?","options":["A. Hiện tại.","B. Quá khứ.","C. Tương lai.","D. Tư bản chủ nghĩa."],"answerLetter":"C","answerText":"C. Tương lai.","notes":""},{"id":515,"question":"Quá trình sản xuất là sự kết hợp của các yếu tố nào?","options":["A. Sức lao động với đối tượng lao động và tư liệu lao động","B. Lao động với đối tượng lao động và tư liệu lao động","C. Sức lao động với công cụ lao động","D. Lao động với sự điều tiết, quản lý của nhà tư bản"],"answerLetter":"A","answerText":"A. Sức lao động với đối tượng lao động và tư liệu lao động","notes":""},{"id":516,"question":"Nội dung nào không phải là tác động tích cực của hội nhập kinh tế quốc tế?","options":["A. Hội nhập kinh tế quốc tế làm gia tăng sự cạnh tranh","B. Tạo điều kiện mở rộng thị trường, tiếp thu khoa học công nghệ, vốn, chuyển dịch cơ cấu kinh tế trong nước","C. Tạo cơ hội để nâng cao chất lượng nguồn nhân lực","D. Tạo điều kiện thúc đẩy hội nhập các linh vực văn hóa, chính trị, củng cố an ninh - quốc phòng"],"answerLetter":"A","answerText":"A. Hội nhập kinh tế quốc tế làm gia tăng sự cạnh tranh","notes":""},{"id":517,"question":"Đâu là các đại diện tiêu biểu của trường phái kinh tế chính trị cổ điến Anh?","options":["A. William Petty, A. Smith, David Ricardo","B. Pierr Boisguillebrt, Francois Quesney, Jacques Turgot","C. Willian Stafford, Thomas Mun, Gasparo Scaruffi","D. Antonso Serra, A. Montchrétien, Francois Quesney"],"answerLetter":"A","answerText":"A. William Petty, A. Smith, David Ricardo","notes":""},{"id":518,"question":"Đặc trưng phổ biến của nền kinh tế thị trường là gì?","options":["A. Có sự đa dạng của các chủ thể kinh tế, nhiều hình thức sở hữu, thị trường đóng vai trò quyết định trong việc phân bổ các nguồn lực xã hội; giá cả được hình thành theo nguyên tắc thị trường; là nền kinh tế mở","B. Có sự đa dạng của các chủ thể kinh tế, nhiều hình thức sở hữu, thị trường đóng vai trò quyết định trong việc phân bố các nguồn lực xã hội, giá cả được hình thành theo nguyên tắc thị trường; là nền kinh tế đóng","C. Có sự đa dạng của các chủ thể kinh tế, nhiều hình thức sở hữu; nhà nước đóng vai trò quyết định trong việc phân bổ các nguồn lực xã hội, giá cả được hình thành theo nguyên tắc thị trường, là nền kinh tế đóng","D. Có sự đa dạng của các chủ thể kinh tế, nhiều hình thức sở hữu; thị trường đóng vai trò quyết định trong việc phân bổ các nguồn lực xã hội; giá cà được hình thành theo quy luật cung - cầu; là nền kinh tế mở"],"answerLetter":"A","answerText":"A. Có sự đa dạng của các chủ thể kinh tế, nhiều hình thức sở hữu, thị trường đóng vai trò quyết định trong việc phân bổ các nguồn lực xã hội; giá cả được hình thành theo nguyên tắc thị trường; là nền kinh tế mở","notes":""},{"id":519,"question":"Tư bản thương nghiệp của chủ nghĩa tư bản là:(NHUNG HOÀNG)","options":["A. Là một bộ phận của tư bản nông nghiệp tách ra phục vụ quá trình lưu thông hàng hóa","B. Là một bộ phận của tư bản công nghiệp tách ra phục vụ quá trình lưu thông hàng hóa","C. Là một bộ phận của tư bản cho vay tách ra phục vụ quá trình lưu thông hàng hóa","D. Là một bộ phận của tư bản thương nghiệp tách ra phục vụ quá trình lưu thông hàng hóa"],"answerLetter":"B","answerText":"B. Là một bộ phận của tư bản công nghiệp tách ra phục vụ quá trình lưu thông hàng hóa","notes":""},{"id":520,"question":"Phương pháp sản xuất giá trị thặng dư tuyệt đối được nhà tư bản tạo ra bằng cách nào?","options":["A. Kéo dài thời gian lao động trong ngày","B. Tăng cường độ lao động","C. Rút ngắn thời gian lao động tất yếu","D. Tăng quy mô võn của chủ nghĩa tư bản"],"answerLetter":"AB","answerText":"A. Kéo dài thời gian lao động trong ngày\nB. Tăng cường độ lao động","notes":""},{"id":521,"question":"Xét về bản chất lợi ích kinh tế phản ảnh điều gì?","options":["A. Phản ánh mục đích và động cơ của các quan hệ giữa các chủ thể trong nền sản xuất xã hội","B. Gắn các chủ thể kinh tế khác nhau là những lợi ích tương ứng","C. Phản ánh động lực về lâu dài của các chủ thể tham gia kinh tế","D. Tất cả phương án trên"],"answerLetter":"A","answerText":"A. Phản ánh mục đích và động cơ của các quan hệ giữa các chủ thể trong nền sản xuất xã hội","notes":""},{"id":522,"question":"Hoàn thiện thể chế đảm bảo gắn tăng trưởng kinh tế với đảm bảo tiến bộ và công bằng xã hội bao, Việt Nam cần thực hiện những nhiệm vụ nào?","options":["A. Tiếp tục rà soát, bổ sung, điều chỉnh hệ thống pháp luật và các thể chế liên quan đáp ứng yêu cầu thực hiện các cam kết quốc tế của Việt Nam","B. Thực hiện nhất quán chủ trương đa phương hóa, đa dạng hóa trong hợp tác kinh tế quốc tế, không để bị lệ thuộc và một số loại thị trường","C. Xây dựng các thiết chế phù hợp với thông lệ quốc tế để phản ứng nhanh nhạy trước các diễn biến bất lợi của thế giới","D. Xây dựng hệ thống thể chế kết hợp chặt chẽ phát triển kinh tế nhanh và bền vững"],"answerLetter":"D","answerText":"D. Xây dựng hệ thống thể chế kết hợp chặt chẽ phát triển kinh tế nhanh và bền vững","notes":""},{"id":523,"question":"Trong các thế mạnh sau đây, đâu là thế mạnh của các doanh nghiệp vừa và nhỏ?","options":["A. Nhạy cảm với những thay đổi trong sản xuất","B. Linh hoạt ứng phó với sự biến động của thị trường","C. Mạnh dạn đầu tư vào những ngành mới đòi hỏi sự mạo hiểm","D. Nguồn lực tài chính lớn dẫn đến dễ dàng sản xuất ra sản phẩm có chất lượng cao"],"answerLetter":"B","answerText":"B. Linh hoạt ứng phó với sự biến động của thị trường","notes":""},{"id":524,"question":"Cơ sở sâu xa cho sự hình thành sở hữu hiện thực trước hết xuất phát từ những quá trình nào?","options":["A. Từ quá trình sản xuất và tái sản xuất xã hội","B. Từ quá trình lưu thông và sản xuất","C. Từ quá trình phân phối và tái sản xuất xã hội","D. Từ quá trình quản lý và tãi sản xuất xã hội"],"answerLetter":"A","answerText":"A. Từ quá trình sản xuất và tái sản xuất xã hội","notes":""},{"id":525,"question":"Hãy chỉ ra biểu hiện mới của độc quyền ở phương diện tích tụ và tập trung tư bản?","options":["A. Vai trò to lớn của tư bản tài chính trong các tập đoàn độc quyền","B. Sự xuất hiện các công ty độc quyền xuyên quốc gia bên cạnh sự phát triển của các xí nghiệp vừa và nhỏ","C. Quốc tế hóa, toàn câu hóa và khu vực hóa kinh tễ","D. Hợp tác, chuyển giao công nghệ cốt lõi"],"answerLetter":"B","answerText":"B. Sự xuất hiện các công ty độc quyền xuyên quốc gia bên cạnh sự phát triển của các xí nghiệp vừa và nhỏ","notes":""},{"id":526,"question":"Nguyên nhân hình thành độc quyền trong nên kinh tế thị trường ở các nước tư bản chủ nghĩa là gì?","options":["A. Do sự phát triển của lực lượng sản xuất","B. Do cạnh tranh","C. Do khủng hoảng và sự phát triển của hệ thống tín dụng","D. Do các doanh nghiệp giảm quy mô tích tụ và tập trung sản xuất"],"answerLetter":"ABC","answerText":"A. Do sự phát triển của lực lượng sản xuất\nB. Do cạnh tranh\nC. Do khủng hoảng và sự phát triển của hệ thống tín dụng","notes":""}],
    hcm202: [{"id":1,"question":"Theo Hồ Chí Minh, \"Muốn xây dựng chủ nghĩa xã hội, trước hết cần có","options":["A. con người xã hội chủ nghĩa\"","B. khoa học xã hội tiên tiến\"","C. công nông nghiệp hiện đại\"","D. nền kinh tế phát triển\""],"answerLetter":"A","answerText":"A. con người xã hội chủ nghĩa\"","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, muốn xây dựng chủ nghĩa xã hội trước hết cần có cái gì?\n=>Con người xã hội chủ nghĩa)\n(Kiểu hỏi khác: Theo Hồ Chí Minh muốn xây dựng chủ nghĩa xã hội, trước hết cần có:\n=> Con người xã hội chủ nghĩa.)"},{"id":2,"question":"Theo Hồ Chí Minh, biện pháp nào quan trọng nhất trong xây dựng chủ nghĩa xã hội?","options":["A. Tranh thủ tối đa sự giúp đỡ, viện trợ quốc tế","B. Kết hợp cải tạo xã hội cũ và xây dựng xã hội mới","C. Huy động các nguồn lực sẵn có trong dân","D. Kết hợp xây dựng và bảo vệ đất nước"],"answerLetter":"C","answerText":"C. Huy động các nguồn lực sẵn có trong dân","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, cách làm trong xây dựng xã hội mới là:\nA. Tranh thủ tối đa sự giúp đỡ, viện trợ quốc tế\nB. Đem của dân, tài dân, sức dân làm lợi cho dân C. Kết hợp cải tạo xã hội cũ với xây dựng xã hội mới\nD. Kết hợp xây dựng và bảo vệ đất nước)"},{"id":3,"question":"Theo Hồ Chí Minh, biện pháp cơ bản nhất để xây dựng chủ nghĩa xã hội là:","options":["A. Đem của dân, tài dân, sức dân làm lợi cho dân","B. Nhà nước phải ban phát từ trên xuống","C. Phải dựa vào sự giúp đỡ của các nước xã hội chủ nghĩa","D. Phải tự lực cánh sinh, dựa vào sức mình là chính"],"answerLetter":"A","answerText":"A. Đem của dân, tài dân, sức dân làm lợi cho dân","notes":""},{"id":4,"question":"Nói về đạo đức cách mạng Hồ Chí Minh chi rõ: \"Vì muốn giải phóng cho dân tộc, giải phóng cho loài người là một công việc to tát, mà tự mình không có đạo đức, không có căn bản, tự mình đã hủ hóa, xấu xa thì còn làm nổi việc gì?\". Câu nói trên của Hồ Chí Minh đề cập đến vấn đề gì sau đây ?","options":["A. Vai trò và sức mạnh của đạo đức","B. Chuẩn mực và nguyên tắc xây dựng đạo đức mới","C. Nguyên tắc xây dựng đạo đức mới","D. Các phẩm chất đạo đức mới"],"answerLetter":"A","answerText":"A. Vai trò và sức mạnh của đạo đức","notes":""},{"id":5,"question":"Lực lượng đoàn kết quốc tế theo hồ chí minh cần phải đoàn kết với","options":["A. Giai cấp công nhân, lực lượng xhcn, phong trào cộng sản và công nhân quốc tế,với các dân tộc thuộc địa bị áp bức và các lực lượng tiến bộ trên thế giới.","B. Giai cấp nông dân, lực lượng xhcn, phong trào cộng sản và công nhân quốc tế,với các dân tộc thuộc địa bị áp bức và các lực lượng tiến bộ trên thế giới.","C. Giai cấp lao động, lực lượng xhcn, phong trào cộng sản và công nhân quốc tế,với các dân tộc thuộc địa bị áp bức và các lực lượng tiến bộ trên thế giới."],"answerLetter":"A","answerText":"A. Giai cấp công nhân, lực lượng xhcn, phong trào cộng sản và công nhân quốc tế,với các dân tộc thuộc địa bị áp bức và các lực lượng tiến bộ trên thế giới.","notes":""},{"id":6,"question":"Theo Hồ Chí Minh, căn bệnh nào là một thứ vi trùng rất độc, đẻ ra hàng trăm thứ bệnh nguy hiểm?","options":["A. Chủ nghĩa tư bản","B. Chủ nghĩa cá nhân","C. Sự lười biếng","D. Thói quen và truyền thống lạc hậu"],"answerLetter":"B","answerText":"B. Chủ nghĩa cá nhân","notes":""},{"id":7,"question":"Nguyên tắc cơ bản nào sau đây cần phải quán triệt trong nghiên cứu tư tưởng hồ chí minh?","options":["A. quan điểm kế thừa và phát triển","B. quan điểm kế thừa và toàn diện","C. quan điểm cách mạng và cụ thể","D. quan điểm toàn diện và cụ thể"],"answerLetter":"A","answerText":"A. quan điểm kế thừa và phát triển","notes":""},{"id":8,"question":"Chọn câu trả lời đúng nhất với tư tưởng Hồ Chí Minh về vai trò của đại đoàn kết dân tộc:","options":["A. Đại đoàn kết dân tộc là vấn đề chiến lược","B. Đại đoàn kết dân tộc là vấn đề sách lược","C. Đại đoàn kết dân tộc là thủ đoạn chính trị","D. Đại đoàn kết dân tộc là phương pháp chính trị"],"answerLetter":"A","answerText":"A. Đại đoàn kết dân tộc là vấn đề chiến lược","notes":""},{"id":9,"question":"Phạm vi vận dụng tư tưởng Hồ Chí Minh:","options":["A. Đối với cách mạng Việt Nam","B. Đối với các dân tộc đang bị xâm lược và áp bức trên toàn thế giới","C. Đối với mọi quốc gia, dân tộc","D. Đối với cách mạng giải phóng dân tộc ở Việt Nam"],"answerLetter":"B","answerText":"B. Đối với các dân tộc đang bị xâm lược và áp bức trên toàn thế giới","notes":"(Kiểu hỏi khác: Phạm vi vận dụng tư tưởng Hồ Chí Minh là đối tượng nào?\nA. Đối với cách mạng Việt Nam\nB. Đối với các nước tư sản\nC. Đối với mọi quốc gia, dân tộc\nD. Đối với cách mạng giải phóng dân tộc ở Việt Nam)"},{"id":10,"question":"Hồ Chí Minh ví chính sách đối với Pháp sau khi giành độc lập như chính sách","options":["A. Tạm hòa","B. Câu tiễn","C. Tạm thời"],"answerLetter":"B","answerText":"B. Câu tiễn","notes":"(Kiểu hỏi khác: Năm 1946 Hồ Chí Minh ví chính sách đối với Pháp sau khi giành độc lập như chính sách gì?A. Tạm hòaB. Câu TiễnC. Tạm thờiD. Thân thiện và hoà bình)"},{"id":11,"question":"Nguyên tắc chung của Mặt trận dân tộc thống nhất được Hồ Chí Minh xác định cụ thể phù hợp là","options":["A. Độc lập, tự do","B. Tất cả các phương án","C. Đoàn kết chặt chẽ, lâu dài, thật sự, chân thành"],"answerLetter":"C","answerText":"C. Đoàn kết chặt chẽ, lâu dài, thật sự, chân thành","notes":""},{"id":12,"question":"Cách diễn đạt nào dưới đây là của Hồ Chí Minh?","options":["A. Lý luận mà không liên hệ với thực tiễn là lý luận mù quáng","B. Lý luận mà không liên hệ với thực tiễn là lý luận suông","C. Lý luận mà không liên hệ với thực tiễn là lý luận giáo điều","D. Lý luận mà không liên hệ với thực tiễn là lý luận trống rỗng"],"answerLetter":"B","answerText":"B. Lý luận mà không liên hệ với thực tiễn là lý luận suông","notes":""},{"id":13,"question":"Điền từ còn thiếu vào chỗ trống để hoàn thành luận điểm của Hồ Chí Minh khi đề cập đến nguyên tắc phương pháp luận \"Thống nhất lý luận và thực tiễn\" trong nghiên cứu môn học Tư tưởng Hồ Chí Minh: \"Thực tiễn không có lý luận hướng dẫn thì thành thực tiễn mù quáng, dễ mắc bệnh...; lý luận mà không liên hệ với thực tiễn là lý luận suông\".","options":["A. Quan liêu","B. Tham ô","C. Chủ quan","D. Lãng phí"],"answerLetter":"C","answerText":"C. Chủ quan","notes":""},{"id":14,"question":"Một trong những giá trị của văn hoá phương Tây được Hồ Chí Minh tiếp thu để hình thành tư tưởng của mình là:","options":["A. Tư tưởng văn hoá dân chủ và cách mạng của cách mạng Pháp và cách mạng Mỹ","B. Những mặt tích cực của Nho Giáo","C. Triết học cổ điển Đức","D. Kinh tế chính trị cổ điển Anh"],"answerLetter":"A","answerText":"A. Tư tưởng văn hoá dân chủ và cách mạng của cách mạng Pháp và cách mạng Mỹ","notes":""},{"id":15,"question":"Một trong những giá trị nào dưới đây dẫn đến hình thành tư tưởng Hồ Chí Minh?","options":["A. Chủ nghĩa yêu nước","B. Chủ nghĩa xã hội","C. Chủ nghĩa nhân đạo","D. Chủ nghĩa nhân văn"],"answerLetter":"A","answerText":"A. Chủ nghĩa yêu nước","notes":""},{"id":16,"question":"Hồ Chí Minh vạch ra mục tiêu của cách mạng giải phóng dân tộc thuộc địa là gì?","options":["A. Đánh đổ ách thống trị của chủ nghĩa thực dân, giành độc lập dân tộc và thiết lập chính quyền của nhân dân","B. Đánh đổ ách thống trị của chủ nghĩa thực dân, giành độc lập dân tộc và thiết lập chính quyền về tay người lao động","C. Đánh đổ ách thống trị của chủ nghĩa thực dân, giành độc lập dân tộc và thiết lập chính quyền về tay lực lượng cách mạng","D. Đánh đổ ách thống trị của chủ nghĩa thực dân, giành độc lập dân tộc và thiết lập chính quyền của công nông"],"answerLetter":"A","answerText":"A. Đánh đổ ách thống trị của chủ nghĩa thực dân, giành độc lập dân tộc và thiết lập chính quyền của nhân dân","notes":""},{"id":17,"question":"Theo Hồ Chí Minh, tính chất và nhiệm vụ hàng đầu của cách mạng ở thuộc địa là gì?","options":["A. Giải phóng nhân loại","B. Giải phóng thế giới","C. Giải phóng giai cấp","D. Giải phóng dân tộc"],"answerLetter":"D","answerText":"D. Giải phóng dân tộc","notes":"(Kiểu hỏi khác: Hồ Chí Minh vạch ra nhiệm vụ hàng đầu của cách mạng ở thuộc địa là)"},{"id":18,"question":"Theo Hồ Chí Minh, muốn phát huy tinh thần đoàn kết Đảng phải","options":["A. Có chính sách mặt trận dân tộc đúng đắn","B. Có chính sách đúng đắn thu hút quần chúng nhân dân","C. Có chính sách dân chủ đúng đắn"],"answerLetter":"A","answerText":"A. Có chính sách mặt trận dân tộc đúng đắn","notes":""},{"id":19,"question":"Tư tưởng Hồ Chí Minh hình thành trên cơ sở","options":["A. Vận dụng và phát triển sáng tạo chủ nghĩa Mác- Lênin","B. Tiếp thu toàn bộ chủ nghĩa Mác-Lênin","C. Tiếp thu một bộ phận của chủ nghĩa Mác-Lênin","D. Vận dụng hoàn toàn chủ nghĩa Mác - Lênin vào hoàn cảnh của Việt Nam"],"answerLetter":"A","answerText":"A. Vận dụng và phát triển sáng tạo chủ nghĩa Mác- Lênin","notes":""},{"id":20,"question":"Chọn phương án trả lời không đúng với tư tưởng Hồ Chí Minh về nhà nước vì dân?","options":["A. Phục vụ nhân dân","B. Chăm lo mọi mặt đời sống nhân dân","C. Do dân làm chủ, tổ chức nên","D. Đem lại lợi ích cho dân"],"answerLetter":"C","answerText":"C. Do dân làm chủ, tổ chức nên","notes":""},{"id":21,"question":"Hồ Chí Minh đã nêu quan điểm về xây dựng một nền văn hóa mới là","options":["A. Xây dựng tâm lý, xây dựng luân lý","B. Xây dựng tâm lý, xây dựng luân lý, xây dựng xã hội","C. Xây dựng tâm lý, xây dựng luân lý, xây dựng xã hội, xây dựng chính trị","D. Xây dựng tâm lý, xây dựng luân lý, xây dựng xã hội, xây dựng chính trị, xây dựng kinh tế"],"answerLetter":"D","answerText":"D. Xây dựng tâm lý, xây dựng luân lý, xây dựng xã hội, xây dựng chính trị, xây dựng kinh tế","notes":""},{"id":22,"question":"Con người trong quan điểm củ","options":["A. Hồ Chí Minh được nhìn nhận như một:a. Chỉnh thể","B. Tế bào","C. Xã hội","D. Cộng đồng"],"answerLetter":"A","answerText":"A. Hồ Chí Minh được nhìn nhận như một:a. Chỉnh thể","notes":"(Kiểu hỏi khác: Hồ Chí Minh nhìn nhận con người như điều gì?\nA. Chỉnh thể\nB. Tế bào\nC. Xã hội\nD. Cộng đồng)"},{"id":23,"question":"Luận điểm: \"Cách mệnh trước hết phải có cái gì? Trước hết phải có đảng cách mệnh, để trong thì vận động và tổ chức dân chúng, ngoài thì liên lạc với dân tộc bị áp bức và vô sản giai cấp ở mọi nơi. Đảng có vững thì cách mạng mới thành công, cũng như người cầm lái có vững thuyền mới chạy\" được trích từ tác phẩm nào của Hồ Chí Minh?","options":["A. Bản án chế độ thực dân Pháp","B. Đường kách mệnh","C. Bản án chế độ thực dân Pháp","D. Thường thức chính trị"],"answerLetter":"B","answerText":"B. Đường kách mệnh","notes":""},{"id":24,"question":"Luận điểm: \"Cách mệnh An Nam cũng là một bộ phận trong cách mệng thế giới. Ai làm cách mệnh trong thế giới đều là đồng chí của dân An Nam cả\" được trích từ tác phẩm nào của Hồ Chí Minh?","options":["A. Đông Dương (1923-1924)","B. Bản án chế dộ thực dân Pháp","C. Đường Kách mệnh","D. Tuyên ngôn Độc lập"],"answerLetter":"C","answerText":"C. Đường Kách mệnh","notes":""},{"id":25,"question":"Chọn phương án trả lời đúng nhất?","options":["A. Chủ nghĩa Mác - Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng","B. Tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng","C. Cùng với chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh là nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng ta"],"answerLetter":"C","answerText":"C. Cùng với chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh là nền tảng tư tưởng và kim chỉ nam cho hành động của Đảng ta","notes":""},{"id":26,"question":"Theo Tư tưởng Hồ Chí Minh, văn hoá có mấy chức năng chủ yếu?","options":["A. Hai","B. Ba","C. Bốn","D. Năm"],"answerLetter":"B","answerText":"B. Ba","notes":"(Kiểu hỏi khác:\nTheo tư tưởng Hồ Chí Minh, văn hoá có chức năng:\na. Bồi dưỡng tư tưởng đúng đắn và tình cảm cao đẹp cho con người.\nb. Nâng cao dân trí.\nc. Bồi dưỡng những phẩm chính tốt đẹp, những phong cách, lối sống lành mạnh, luôn hướng con người vươn tới cái chân, cái thiện, cái mỹ, không ngừng hoàn thiện bản thân mình.\nd. Tất cả các phương án.)"},{"id":27,"question":"Theo Hồ Chí Minh, để đánh bại các thế lực đế quốc thực dân chỉ có tinh thần yêu nước là chưa đủ, cách mạng muốn đến nơi, phải tập hợp được tất cả mọi lực lượng có thể tập hợp, xây dựng được.","options":["A. Chính sách dân tộc phù hợp","B. Khối đại đoàn kết dân tộc bền vững","C. Chương trình tập hợp lực lượng đoàn kết rộng rãi"],"answerLetter":"B","answerText":"B. Khối đại đoàn kết dân tộc bền vững","notes":""},{"id":28,"question":"Theo Hồ Chí Minh, mục đích của chủ nghĩa xã hội là.","options":["A. Xây dựng nền kinh tế hiện đại, có sức tăng trưởng cao.","B. Không ngừng nâng cao đời sống vật chất và tinh thần của nhân dân","C. Phát triển mạnh mẽ khoa học - kỹ thuật","D. Bảo đảm quyền làm chủ của nhân dân lao động"],"answerLetter":"B","answerText":"B. Không ngừng nâng cao đời sống vật chất và tinh thần của nhân dân","notes":""},{"id":29,"question":"Theo Hồ Chí Minh, mục tiêu tổng quát của chủ nghĩa xã hội là gì?","options":["A. Một nền kinh tế hiện đại, khoa học kỹ thuật tiên tiến","B. Không ngừng cải thiện và nâng cao đời sống của nhân dân lao động","C. Phát triển mạnh mẽ khoa học - kỹ thuật, tư tưởng văn hóa tiến bộ","D. Bảo đảm quyền làm chủ của nhân dân lao động"],"answerLetter":"B","answerText":"B. Không ngừng cải thiện và nâng cao đời sống của nhân dân lao động","notes":""},{"id":30,"question":"Theo Hồ Chí Minh, đánh giá cán bộ phải:","options":["A. Tiến hành thường xuyên","B. Khách quan, trung thực","C. Phải tự biết mình, biết người","D. Phải đủ trong sạch"],"answerLetter":"B","answerText":"B. Khách quan, trung thực","notes":"( Đánh giá cán bộ phải khách quan, toàn diện, công tâm, minh bạch )"},{"id":31,"question":"Hãy chọn phương án trả lời đúng nhất: Lòng khoan dung độ lượng ở Hồ Chí Minh không phải là một sách lược, một thủ đoạn chính trị mà là sự nối tiếp và phát triển của :","options":["A. Chủ nghĩa yêu nước","B. Chủ nghĩa dân tộc chân chính","C. Truyền thống nhân ái, bao dung của dân tộc","D. Mục tiêu cách mạng"],"answerLetter":"C","answerText":"C. Truyền thống nhân ái, bao dung của dân tộc","notes":""},{"id":32,"question":"Trong quan hệ quốc tế, Hồ Chí Minh nhấn mạnh: phải có thực lực, thực lực là cái (...), ngoại giao là cái tiếng, (....) có to tiếng mới lớn.","options":["A. Chiêng","B. Trống","C. Kèn","D. Đàn"],"answerLetter":"A","answerText":"A. Chiêng","notes":""},{"id":33,"question":"Hồ Chí Minh nhấn mạnh mục đích của Đảng Lao động Việt Nam là","options":["A. Liên kết toàn dân, chống giặc ngoại xâm","B. Đoàn kết đoàn kết đại đoàn kết","C. Đoàn kết toàn dân, phụng sự tổ quốc","D. Đoàn kết dân tộc, phụng sự tổ quốc"],"answerLetter":"C","answerText":"C. Đoàn kết toàn dân, phụng sự tổ quốc","notes":""},{"id":34,"question":"Đâu là nguyên tắc xây dựng đạo đức mới trong tư tưởng hồ chí minh","options":["A. phải tu dưỡng đạo đức suốt đời","B. phải tu dưỡng đạo đức thường xuyên","C. phải tu dưỡng đạo đức hằng ngày"],"answerLetter":"A","answerText":"A. phải tu dưỡng đạo đức suốt đời","notes":""},{"id":35,"question":"Đâu là nguyên tắc xây dựng đạo đức mới trong tư tưởng hồ chí minh","options":["A. nói đi đôi với làm, phải nêu gương về đạo đức","B. nói đi đôi với làm, phải nêu gương về lối sống","C. nói đi đôi với làm, phải nêu gương về học tập"],"answerLetter":"A","answerText":"A. nói đi đôi với làm, phải nêu gương về đạo đức","notes":""},{"id":36,"question":"Đâu là nguyên tắc xây dựng đạo đức mới trong tư tưởng hồ chí minh","options":["A. xây đi đôi với chống","B. xây đi đôi với bảo vệ","C. xây đi đôi với gia cố"],"answerLetter":"A","answerText":"A. xây đi đôi với chống","notes":""},{"id":37,"question":"Trong tư tưởng Hồ Chí Minh, Mặt trận dân tộc thống nhất càng rộng rãi, sức mạnh của khối liên minh công nông trí thức càng:","options":["A. Suy yếu và ngược lại.","B. Được tăng cường và ngược lại.","C. Gắn kết và ngược lại","D. Thu hẹp và ngược lại"],"answerLetter":"B","answerText":"B. Được tăng cường và ngược lại.","notes":""},{"id":38,"question":"Thực chất của giải phóng giai cấp theo tư tưởng Hồ Chí Minh là gì?","options":["A. Xóa bỏ các giai cấp bóc lột với tính cách là giai cấp thống trị xã hội","B. Tiêu diệt cá nhân những con người thuộc các giai cấp bóc lột","C. Không chủ trương thủ tiêu giai cấp bóc lột thống trị xã hội","D. Xóa bỏ triệt tiêu các giai cấp thuộc về xã hội cũ"],"answerLetter":"A","answerText":"A. Xóa bỏ các giai cấp bóc lột với tính cách là giai cấp thống trị xã hội","notes":""},{"id":39,"question":"Tư tưởng Hồ Chí Minh về cách mạng Việt Nam được hình thành về cơ bản trong thời kỳ nào?","options":["A. Từ 1911 den 1920","B. Từ 1920 đến 1930","C. Từ 1921 đến 1930","D. Từ 1930 đến 1945"],"answerLetter":"C","answerText":"C. Từ 1921 đến 1930","notes":""},{"id":40,"question":"Trong tác phẩm \"Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân\" viết trên báo 1969, Hồ Chí Minh ví chủ nghĩa cá nhân như:","options":["A. Bệnh mẹ","B. Bệnh nguy hiểm","C. Giặc ngoại xâm","D. Bệnh cần loại bỏ"],"answerLetter":"A","answerText":"A. Bệnh mẹ","notes":""},{"id":41,"question":"Hồ Chí Minh cho rằng giai cấp địa chủ ở Việt Nam","options":["A. Là giai cấp phản động","B. Là giai cấp tiên tiến","C. Là giai cấp không hoàn toàn phản động"],"answerLetter":"C","answerText":"C. Là giai cấp không hoàn toàn phản động","notes":""},{"id":42,"question":"Hồ chí minh cho rằng giai cấp địa chủ ở việt nam","options":["A. Là giai Cấp phản động","B. Là giai cấp tiên tiến","C. Có thể lợi dụng","D. Cần phải loại bỏ"],"answerLetter":"C","answerText":"C. Có thể lợi dụng","notes":""},{"id":43,"question":"Vấn đề dân tộc trong tư tưởng Hồ Chí Minh là sự kết hợp nhuần nhuyễn:","options":["A. Dân tộc với giai cấp.","B. Độc lập dân tộc và chủ nghĩa xã hội.","C. Chủ nghĩa yêu nước với chủ nghĩa quốc tế.","D. Tất cả các phương án."],"answerLetter":"D","answerText":"D. Tất cả các phương án.","notes":""},{"id":44,"question":"Theo hồ chí minh, ngoài lợi ích của giai cấp, của nhân dân và toàn thể dân tộc việt nam, đảng:","options":["A. không còn lợi ích nào khác","B. còn vì lợi ích của mình","C. còn vì lợi ích của nhà nước","D. Còn vì lợi ích của cá nhân"],"answerLetter":"A","answerText":"A. không còn lợi ích nào khác","notes":""},{"id":45,"question":"Hồ Chí Minh ví tuổi trẻ như:","options":["A. Mùa xuân của xã hội","B. Mùa xuân của đất nước","C. Mùa xuân của Đảng","D. Mùa xuân của Nhà nước"],"answerLetter":"A","answerText":"A. Mùa xuân của xã hội","notes":""},{"id":46,"question":"Hồ Chí Minh lần đầu tiên đã đưa ra một định nghĩa về văn hoá trong tác phẩm nào?","options":["A. Bản án chế độ thực dân Pháp\"","B. Đường Kách mệnh\"","C. Nhật ký trong tù\"","D. Sửa đổi lối làm việc\""],"answerLetter":"C","answerText":"C. Nhật ký trong tù\"","notes":"(Hồ Chí Minh lần đầu tiên đưa ra định nghĩa văn hóa vào lúc nào?\nA. Vào thời gian Bác ở Pháp\nB. Vào thời điểm thành lập Đảng\nC. Vào thời gian đang ở nhà tủ của Tưởng Giối Thạch\nD. Vào thời điểm đọc Tuyên Ngôn Độc lập)"},{"id":47,"question":"Các bài giảng của Nguyễn Ái Quốc tại các lớp huấn luyện cán bộ tuyên truyền của hội Liên hiệp các dân tộc bị áp bức bóc lột lập hợp lại và xuất bản thành tác phẩm gì?","options":["A. Bản án chế độ thực dân Pháp","B. Lênin và Phương Đông","C. Con Rồng tre","D. Đường Kách mệnh"],"answerLetter":"D","answerText":"D. Đường Kách mệnh","notes":""},{"id":48,"question":"Trong quan điểm của hồ chí minh về bản chất của nhà nước có sự thống nhất giữa bản chất giai cấp công nhân với:","options":["A. tính nhân dân và tính dân tộc","B. tính xã hội chủ nghĩa và tính dân tộc","C. tính nhân dân và tính xã hội chủ nghĩa"],"answerLetter":"A","answerText":"A. tính nhân dân và tính dân tộc","notes":""},{"id":49,"question":"Theo Hồ Chí Minh, Đại đoàn kết dân tộc là nhiệm vụ hàng đầu củ","options":["A. Đảng, đồng thời cũng là nhiệm vụ hàng đầu của:a. Mọi giai đoạn cách mạng.","B. Toàn quân.","C. Toàn dân."],"answerLetter":"C","answerText":"C. Toàn dân.","notes":"(Kiểu hỏi khác: Theo tư tưởng Hồ Chí Minh thì đoàn kết trước hết là phải đoàn kết như thế nào?\nA. Toàn dân\nB. Toàn quân\nC. Toàn Đảng\nD. Toàn giai cấp)"},{"id":50,"question":"Trong các luận điểm sau đây về văn hóa, luận điểm nào Hồ Chí Minh nói về tính chất của nền văn hóa?","options":["A. Phải nâng cao trình độ văn hóa của nhân dân","B. Phải xây dựng một nền văn hóa dân tộc, khoa học và đại chúng","C. Văn hóa cũng là một mặt trận","D. Xây dựng chính trị dân quyền"],"answerLetter":"B","answerText":"B. Phải xây dựng một nền văn hóa dân tộc, khoa học và đại chúng","notes":"(Kiểu hỏi khác:\nHồ Chí Minh cho rằng văn hóa có tính:\nA. Dân tộc, khoa học và đại chúng\nB. Dân tộc, khoa học và nhân dân\nC. Dân tộc, khoa học và nhân bản)"},{"id":51,"question":"Chọn phương án trả lời đúng với một trong những giai đoạn hình thành và phát triển tư tưởng hồ chí minh?","options":["A. Từ năm 1890 - 1911: thời kỳ nghiên cứu, khảo sát thực tế, đến với chủ nghĩa mác - lênin.","B. Từ năm 1921 - 1930: thời kỳ hình thành cơ bản tư tưởng về con đường cách mạng việt nam.","C. Từ năm 1911 - 1920: thời kỳ hình thành tư tưởng yêu nước, chí hướng cứu nước","D. Từ năm 1890 - 1911: Thời kỳ vượt qua thứ thách, kiên trì giữ vững lập trường cách mạng"],"answerLetter":"B","answerText":"B. Từ năm 1921 - 1930: thời kỳ hình thành cơ bản tư tưởng về con đường cách mạng việt nam.","notes":""},{"id":52,"question":"Quy luật ra đời của đảng được Hồ Chí Minh vạch ra","options":["A. Là sự phát triển chủ nghĩa Mác- Lênin trong điều kiện Việt Nam","B. Là sự phát triển chủ nghĩa Mác- Lênin trong điều kiện thay đổi","C. Là sự phát triển chủ nghĩa Mác- Lênin trong điều kiện mới"],"answerLetter":"A","answerText":"A. Là sự phát triển chủ nghĩa Mác- Lênin trong điều kiện Việt Nam","notes":""},{"id":53,"question":"Quy luật r","options":["A. đời của Đảng được Hồ Chí Minh vạch raa. Không phù hợp với tinh thần của chủ nghĩa Mác- Lênin","B. Trái với tinh thần của chủ nghĩa Mác- Lênin","C. Không trái với tinh thần của chủ nghĩa Mác- Lênin"],"answerLetter":"C","answerText":"C. Không trái với tinh thần của chủ nghĩa Mác- Lênin","notes":""},{"id":54,"question":"Quy luật r","options":["A. đời của Đảng được Hồ Chí Minh vạch raa. Dựa trên thế giới quan và phương pháp luận của chủ nghĩa Mác-Lênin","B. Dựa trên thế giới quan và phương pháp luận của chủ nghĩa Tam dân","C. Dựa trên thế giới quan và phương pháp luận của chủ nghĩa dân tộc"],"answerLetter":"A","answerText":"A. đời của Đảng được Hồ Chí Minh vạch raa. Dựa trên thế giới quan và phương pháp luận của chủ nghĩa Mác-Lênin","notes":""},{"id":55,"question":"Quy luật r","options":["A. đời của Đảng được Hồ Chí Minh vạch raa. Không khác với chủ nghĩa Mác-Lênin","B. Khác với chủ nghĩa Mác-Lênin","C. Không liên quan đến chủ nghĩa Mác-Lênin"],"answerLetter":"A","answerText":"A. đời của Đảng được Hồ Chí Minh vạch raa. Không khác với chủ nghĩa Mác-Lênin","notes":""},{"id":56,"question":"Theo quan điểm của Chủ tịch Hồ Chí Minh, nhà nước của dân là gì.","options":["A. Quyền lực nhà nước thuộc về giai cấp nông dân","B. Quyền lực nhà nước thuộc về nhân dân lao động","C. Tất cả quyền lực của Nhà nước và trong xã hội đều thuộc về nhân dân","D. Quyền lực nhà nước thuộc về giai cấp công nhân"],"answerLetter":"C","answerText":"C. Tất cả quyền lực của Nhà nước và trong xã hội đều thuộc về nhân dân","notes":""},{"id":57,"question":"Theo Hồ Chí Minh, để thực hiện được đoàn kết, cần xoá bỏ hết mọi thành kiến, cần phải (....) và giúp đỡ lẫn nhau cùng tiến bộ.","options":["A. Nghiêm túc hợp tác","B. Thật thà hợp tác","C. Sẵn sàng hợp tác","D. Tích cực hợp tác"],"answerLetter":"B","answerText":"B. Thật thà hợp tác","notes":""},{"id":58,"question":"Hồ Chí Minh cho rằng khuyết điểm của thanh niên là","options":["A. Chuộng hình thức","B. Chuộng tự do","C. Chuộng lợi","D. Chuộng bề ngoài"],"answerLetter":"A","answerText":"A. Chuộng hình thức","notes":""},{"id":59,"question":"Tư tưởng Hồ Chí Minh Về cách mạng Việt Nam được xem là:","options":["A. Hệ thống các quan điểm cụ thể Về cách mạng Việt Nam","B. Một nhóm các quan điểm cụ thể Về cách mạng Việt Nam","C. Một hệ thống các học thuyết Về cách mạng Việt Nam"],"answerLetter":"A","answerText":"A. Hệ thống các quan điểm cụ thể Về cách mạng Việt Nam","notes":""},{"id":60,"question":"Theo Hồ Chí Minh, cuộc cách mạng nào đầu thế kỷ XX đã làm \"thức tỉnh các dân tộc châu Á\"","options":["A. Cách mạng Trung Quốc","B. Cách mạng Ấn Độ","C. Cách mạng tháng Mười Nga","D. Cách mạng Pháp"],"answerLetter":"C","answerText":"C. Cách mạng tháng Mười Nga","notes":""},{"id":61,"question":"Quá độ lên chủ nghĩa xã hội theo hồ chí minh là","options":["A. Xóa bỏ toàn bộ những thành tựu của xã hội cũ","B. Kế thừa toàn bộ những gì xã hội cũ để lại","C. Kế thừa những giá trị của xã hội cũ"],"answerLetter":"C","answerText":"C. Kế thừa những giá trị của xã hội cũ","notes":""},{"id":62,"question":"Mục đích của văn hóa theo Hồ Chí Minh đó là","options":["A. Vì cuộc sống sinh tồn của loài người","B. Vì cuộc sống sinh tồn của nhân dân","C. Vì cuộc sống sinh tồn của cộng đồng"],"answerLetter":"A","answerText":"A. Vì cuộc sống sinh tồn của loài người","notes":""},{"id":63,"question":"Mục đích của văn hóa theo Hồ Chí Minh đó là","options":["A. Vì lẽ sinh tồn và mục đích của cuộc sống","B. Vì cuộc sống sinh tồn của nhân dân","C. Vì cuộc sống sinh tồn của cộng đồng","D. Để nâng cao chất lượng giáo dục"],"answerLetter":"A","answerText":"A. Vì lẽ sinh tồn và mục đích của cuộc sống","notes":"(Câu hỏi khác: Khi nói về nghĩa rộng của văn hóa, Hồ Chí Minh đã đề cập vì lí do gì mà con người sáng tạo ra các giá trị của văn hóa?)"},{"id":64,"question":"Đối với Hồ Chí Minh, dân ta tài năng, trí tuệ và sáng tạo, họ biết \"giải quyết nhiều vấn đề một cách giản đơn, mau chóng, đầy đủ, mà những người tài giỏi, những đoàn thể to lớn,....","options":["A. nghĩ mãi không ra\".","B. nghĩ mãi mới ra\".","C. làm mãi không được\".","D. làm mãi mới được\"."],"answerLetter":"A","answerText":"A. nghĩ mãi không ra\".","notes":""},{"id":65,"question":"Hồ Chí Minh cho rằng:","options":["A. Văn hoá tham gia vào nhiệm vụ các hoạt động kinh tế, chính trị, xã hội và trong hoạt động của kinh tế, chính trị, xã hội cũng phải có văn hoá","B. Văn hoá tham gia vào nhiệm vụ các hoạt động kinh tế, chính trị, xã hội và trong hoạt động của kinh tế, chính trị, xã hội cũng phải có đạo đức","C. Văn hoá tham gia vào nhiệm vụ các hoạt động kinh tế, chính trị, xã hội và trong hoạt động của kinh tế, chính trị, xã hội cũng phải có tinh thần cách mạng","D. Văn hóa tham gia vào nhiệm vụ các hoạt động kinh tế, xã hội và trong hoạt động của kinh tế, chính trị, xã hội cũng phải có tinh thần quốc tế"],"answerLetter":"A","answerText":"A. Văn hoá tham gia vào nhiệm vụ các hoạt động kinh tế, chính trị, xã hội và trong hoạt động của kinh tế, chính trị, xã hội cũng phải có văn hoá","notes":"(Đâu là phương án chính xác nhất và đầy đủ nhất theo quan điểm Hồ Chí Minh về văn hóa?)"},{"id":66,"question":"Hồ Chí Minh được coi là linh hồn của cuộc kháng chiến chống Pháp trong giai đoạn nào?","options":["A. 1946-1954","B. 1945-1954","C. 1930-1945","D. 1939-1945"],"answerLetter":"A","answerText":"A. 1946-1954","notes":""},{"id":67,"question":"Nội dung quá độ lên chủ nghĩa xã hội theo Hồ Chí Minh phải tiến hành","options":["A. Chủ yếu là lĩnh vực kinh tế","B. Chủ yếu là lĩnh vực văn hóa","C. Trên mọi mặt của xã hội"],"answerLetter":"C","answerText":"C. Trên mọi mặt của xã hội","notes":""},{"id":68,"question":"Trong giai đoạn 1923 - 1924, Quảng Châu Trung Quốc được mệnh danh là?","options":["A. Moskva của Phương Đông","B. Trung cách mạng vô sản","C. Thủ Phủ cộng sản","D. Căn cứ quốc tế vô sản"],"answerLetter":"A","answerText":"A. Moskva của Phương Đông","notes":""},{"id":69,"question":"Quan điểm nào sau đây thuộc vấn đề tiêu chuẩn cán bộ theo tư tưởng Hồ Chí Minh","options":["A. Đạo đức cán bộ","B. Đạo đức cách mạng","C. Đạo đức lãnh đạo"],"answerLetter":"B","answerText":"B. Đạo đức cách mạng","notes":""},{"id":70,"question":"Quan điểm nào sau đây thuộc vấn đề tiêu chuẩn cán bộ theo tư tưởng Hồ Chí Minh","options":["A. Trung thành với Đảng","B. Trung thành với nhân dân","C. Trung thành với nhà nước"],"answerLetter":"A","answerText":"A. Trung thành với Đảng","notes":""},{"id":71,"question":"Quan điểm nào sau đây thuộc vấn đề tiêu chuẩn cán bộ theo tư tưởng Hồ Chí Minh","options":["A. Có năng lực tổ chức thực tiễn","B. Có năng lực tổ chức lãnh đạo","C. Có năng lực tổ chức chỉ huy"],"answerLetter":"A","answerText":"A. Có năng lực tổ chức thực tiễn","notes":""},{"id":72,"question":"Quan điểm nào sau đây thuộc vấn đề tiêu chuẩn cán bộ theo tư tưởng Hồ Chí Minh","options":["A. Liên hệ mật thiết với Đảng","B. Liên hệ mật thiết với nhân dân","C. Liên hệ mật thiết với mọi người"],"answerLetter":"B","answerText":"B. Liên hệ mật thiết với nhân dân","notes":""},{"id":73,"question":"Quan điểm nào sau đây thuộc vấn đề tiêu chuẩn cán bộ theo tư tưởng Hồ Chí Minh","options":["A. Phẩm chất công tác tốt","B. Phẩm chất tư duy tốt","C. Phẩm chất năng lực tốt"],"answerLetter":"A","answerText":"A. Phẩm chất công tác tốt","notes":""},{"id":74,"question":"Hồ Chí Minh chỉ rõ: \"Ở nước ta chính quyền là của nhân dân, do nhân dân làm chủ. Nhân dân là (....) nắm chính quyền. Nhân dân bầu r","options":["A. đại biểu thay mặt mình thi hành chính quyền ấy. Thế là dân chủ\".a. Ông chủ","B. Người đại diện","C. Công bộc"],"answerLetter":"A","answerText":"A. đại biểu thay mặt mình thi hành chính quyền ấy. Thế là dân chủ\".a. Ông chủ","notes":"(Kiểu hỏi khác: Theo quan điểm Hồ Chí Minh, khái quát dân chủ có ý nghĩa là gì?\nA. Dân là chủ và dân làm chủ\nB. Dân là người chủ\nC. Dân làm quản lý\nD. Dân làm người chủ)"},{"id":75,"question":"Trong tư tưởng Hồ Chí Minh, Mặt trận dân tộc thống nhất là nơi quy tụ mọi tổ chức và cá nhân yêu nước người Việt Nam, bao gồm cả những người:","options":["A. Định cư ở nước ngoài","B. Đang sống ở các nước cùng Châu lục","C. Định cư ở các nước theo con đường xã hội chủ nghĩa","D. Các cá nhân thuộc tổ chức phi chính phủ"],"answerLetter":"A","answerText":"A. Định cư ở nước ngoài","notes":""},{"id":76,"question":"Cách mạng giải phóng dân tộc muốn giành được thắng lợi cần phải:","options":["A. Tiến hành chủ động và sáng tạo","B. Dựa vào sự thắng lợi của cách mạng ở các nước thuộc địa khác.","C. Dựa vào thắng lợi của cách mạng vô sản ở chính quốc.","D. Tiến hành song hành với cách mạng vô sản ở chính quốc ."],"answerLetter":"A","answerText":"A. Tiến hành chủ động và sáng tạo","notes":""},{"id":77,"question":"Hồ Chí Minh cho rằng: \"Người cách mạng phải có (....) làm nền tảng, mới hoàn thành được nhiệm vụ cách mạng vẻ vang\".","options":["A. Trí tuệ","B. Phương pháp cách mạng","C. Đạo đức cách mạng","D. Ý chí cách mạng"],"answerLetter":"C","answerText":"C. Đạo đức cách mạng","notes":""},{"id":78,"question":"Hồ Chí Minh cho rằng giải phóng dân tộc phải gắn liền với","options":["A. Độc lập, tự do và hạnh phúc","B. Dân quyền và tự do","C. Nhân sinh và hạnh phúc"],"answerLetter":"A","answerText":"A. Độc lập, tự do và hạnh phúc","notes":""},{"id":79,"question":"Hồ Chí Minh lưu ý","options":["A. Đảng cầm quyền, Đảng lãnh đạo để cho dân làm chủ","B. Đảng cầm quyền, Đảng lãnh đạo để cho dân quản lý","C. Đảng cầm quyền, Đảng lãnh đạo để cho dân giám sát"],"answerLetter":"A","answerText":"A. Đảng cầm quyền, Đảng lãnh đạo để cho dân làm chủ","notes":""},{"id":80,"question":"Mặt trận Liên Việt được thành lập vào thời gian nào?","options":["A. 1941","B. 1945","C. 1951","D. 1960"],"answerLetter":"C","answerText":"C. 1951","notes":""},{"id":81,"question":"Theo Hồ Chí Minh, đặc điểm của cách mạng tư sản là:","options":["A. Độc lập dân tộc","B. Đấu tranh giải phóng dân tộc thuộ","C. địac. Không đến nơi","D. Xây dựng nhà nước công nông"],"answerLetter":"C","answerText":"C. địac. Không đến nơi","notes":""},{"id":82,"question":"Quan điểm nào dưới đây thuộc về bản chất của CNXH trong tư tưởng Hồ Chí Minh:","options":["A. Là chế độ không còn người bóc lột người","B. Là chế độ còn một ít người bóc lột","C. Là chế độ người bóc lột bị khinh rẻ","D. Là chế độ người bóc lột được thừa nhận"],"answerLetter":"A","answerText":"A. Là chế độ không còn người bóc lột người","notes":""},{"id":83,"question":"Chủ trương \"Ỳ Pháp cầu tiến bộ\", \"khai dân trí chấn dân khí, hậu dân sinh\" là đường lối của nhà yêu nước nào?","options":["A. Phan Châu Trinh","B. Phan Bội Châu","C. Hoàng Hoa Thám","D. Hồ Chí Minh"],"answerLetter":"A","answerText":"A. Phan Châu Trinh","notes":""},{"id":84,"question":"Hồ Chí Minh cho rằng cán bộ muốn hướng dẫn nhân dân phải như thế nào?","options":["A. Làm mực thước cho nhân dân bắt chước","B. Làm gương cho nhân dân","C. Làm mô hình cho dân theo","D. Làm quan cách mạng"],"answerLetter":"A","answerText":"A. Làm mực thước cho nhân dân bắt chước","notes":""},{"id":85,"question":"Theo Hồ Chí Minh, trình độ văn hóa của nhân dân nâng cao sẽ giúp cho chúng ta đẩy mạnh công cuộc gì? Chọn phương án chính xác nhất","options":["A. Khôi phục kinh tế","B. Khôi phục kinh tế, phát triển dân chủ","C. Phát triển dân chủ","D. Khôi phục văn hóa"],"answerLetter":"B","answerText":"B. Khôi phục kinh tế, phát triển dân chủ","notes":""},{"id":86,"question":"Năm 1919, Nguyễn Ái Quốc gửi tới hội nghị Vecxay - Pháp bản yêu sách của nhân dân An Nam với hai nội dung chính đó là :","options":["A. Đòi quyền bình đẳng về pháp lý và đòi quyền tự do, dân chủ","B. Đòi quyền dân tộc cơ bản và quyền tự quyết của dân tộc","C. Đòi quyền cơ bản của con người và quyền tự quyết dân tộc","D. Thể hiện tiếng nói của dân tộc và sự tôn trọng các nền văn hóa"],"answerLetter":"A","answerText":"A. Đòi quyền bình đẳng về pháp lý và đòi quyền tự do, dân chủ","notes":""},{"id":87,"question":"Hồ Chí Minh viết","options":["A. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng hỏng","B. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng cần phải xóa bỏ","C. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng cần phải thay thế"],"answerLetter":"A","answerText":"A. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng hỏng","notes":"(Kiểu hỏi khác: Đâu là đáp án chính xác nhất về Đảng theo tư tưởng Hồ Chí Minh?A. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng hỏngB. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng cần phải xóa bỏC. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng cần phải thay thếD. Một Đảng mà giấu giếm khuyết điểm của mình là một đảng cần phải thay đổi)"},{"id":88,"question":"Trong thời gian ở nước ngoài, Nguyễn Tất Thành đã làm những công việc gì?","options":["A. Đốt lò, bán báo","B. Thợ ảnh, làm bánh","C. Phụ bếp, cào tuyết","D. Tất cả các công việc"],"answerLetter":"D","answerText":"D. Tất cả các công việc","notes":""},{"id":89,"question":"Theo văn kiện Đại hội XI của Đảng Cộng sản Việt Nam (2011), Tư tưởng Hồ Chí Minh là tư tưởng về:","options":["A. Những vấn đề cơ bản của cách mạng Việt Nam","B. Những vấn đề cơ bản của cách mạng thế giới","C. Những vấn đề cơ bản của dân tộc","D. Những vấn đề cơ bản của nhân loại"],"answerLetter":"A","answerText":"A. Những vấn đề cơ bản của cách mạng Việt Nam","notes":""},{"id":90,"question":"Quan điểm: \"Đảng Cộng sản Việt Nam lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động\" được nêu lần đầu tiên trong văn kiện của Đại hội đại biểu toàn quốc lần thứ mấy của Đảng?","options":["A. Đại hội đại biểu toàn quốc lần thứ VI","B. Đại hội đại biểu toàn quốc lần thứ VII","C. Đại hội đại biểu toàn quốc lần thứ IX","D. Đại hội đại biểu toàn quốc lần thứ XI"],"answerLetter":"B","answerText":"B. Đại hội đại biểu toàn quốc lần thứ VII","notes":""},{"id":91,"question":"Nguyên tắc cơ bản trong nghiên cứu tư tưởng Hồ Chí Minh là:","options":["A. Thống nhất giữa lí luận gắn liền và thực tiễn","B. Thống nhất giữa tính Đảng và tính thực tiễn","C. Thống nhất giữa tính khoa học và thực tiễn","D. Quan điểm gắn liền với thực tiễn"],"answerLetter":"A","answerText":"A. Thống nhất giữa lí luận gắn liền và thực tiễn","notes":""},{"id":92,"question":"Đâu là chuẩn mực đạo đức cách mạng trong tư tưởng Hồ Chí Minh","options":["A. Trung với nước, hiếu với dân.","B. Trung với nước, hiếu với đồng bào.","C. Trung với nước, hiếu với cách mạng."],"answerLetter":"A","answerText":"A. Trung với nước, hiếu với dân.","notes":"(Kiểu hỏi khác:\nTheo quan điểm của Hồ Chí Minh, phẩm chất đạo đúc nào là quan trọng nhất, bao trùm nhất, chi phối các phẩm chất khác?\nTrong các mệnh đề về đạo đức của mình, theo Hồ Chí Minh, đâu là cái đức lớn nhất\nĐầu là một trong những chuẩn mực đạo đức cách mạng trong tư tưỡng Hồ Chí Minh?)"},{"id":93,"question":"Đâu là chuẩn mực đạo đức cách mạng trong tư tưởng Hồ Chí Minh","options":["A. Cần, kiệm, liêm, chính, chí công vô tư.","B. Cần, kiệm, liêm, chính, sáng suốt.","C. Cần, kiệm, liêm, chính, tự do."],"answerLetter":"A","answerText":"A. Cần, kiệm, liêm, chính, chí công vô tư.","notes":"(Kiểu hỏi khác: Đoạn viết dưới đây ghi tóm tắt lời giải thích của Hồ Chí Minh về cần, kiệm, liêm, chính. Hỏi: Điểm tóm tắt nào đã bị ghi nhầm nội dung?\nA. Cần là lao động cần cù, siêng năng, lao động có kế hoạch, sáng tạo và có năng suất lao động cao...\nB. Kiệm là không xa xỉ, không hoang phí, không bừa bãi...\nC. Liêm là luôn tôn trọng của công và của dân, không tham tiền của, địa vị, danh tiếng.\nD. Chính là trong sạch, không tham lam đồng xu, hạt thóc của nhà nước, của dân.)"},{"id":94,"question":"Đâu là chuẩn mực đạo đức cách mạng trong tư tưởng Hồ Chí Minh","options":["A. Thương yêu con người, sống có tình nghĩa","B. Thương yêu con người, sống có lý","C. Thương yêu con người, sống có trách nhiệm"],"answerLetter":"A","answerText":"A. Thương yêu con người, sống có tình nghĩa","notes":""},{"id":95,"question":"Đâu là chuẩn mực đạo đức cách mạng trong tư tưởng Hồ Chí Minh","options":["A. Có tinh thần quốc tế trong sáng","B. Có tinh thần quốc tế cao đẹp","C. Có tinh thần quốc tế chân chính"],"answerLetter":"A","answerText":"A. Có tinh thần quốc tế trong sáng","notes":""},{"id":96,"question":"Cụ Hoàng Thị Loan đã có đức tính gì ảnh hưởng tới Hồ Chí Minh?","options":["A. Lòng nhân hậu và mẫn cảm","B. Sự yêu thương và vị tha","C. Tần tào và đảm đang","D. Từ bi và vị tha"],"answerLetter":"A","answerText":"A. Lòng nhân hậu và mẫn cảm","notes":""},{"id":97,"question":"Đối với Hồ Chí Minh, toàn dân tộc chỉ trở thành lực lượng to lớn, có sức mạnh vô địch khi được tập hợp, tổ chức lại thành một khối vững chắc, được giác ngộ về mục tiêu chiến đấu chung và hoạt động theo:","options":["A. Một Đảng chính trị đúng đắn","B. Một đường lối chính trị đúng đắn.","C. Một tổ chức chính trị đúng đắn"],"answerLetter":"B","answerText":"B. Một đường lối chính trị đúng đắn.","notes":""},{"id":98,"question":"Theo Hồ Chí Minh, chế độ xã hội chủ nghĩa là chế độ do dân làm chủ, thì mỗi con người được coi là","options":["A. Bộ phận của tập thể","B. Một tế bào của xã hội","C. Đều là một cá thể trong xã hội","D. Một phần của tập thể"],"answerLetter":"B","answerText":"B. Một tế bào của xã hội","notes":""},{"id":99,"question":"Hồ Chí Minh cho rằng xây dựng con người mới xã hội chủ nghĩa trước hết phải:","options":["A. Diệt trừ chủ nghĩa cá nhân","B. Diệt trừ văn hóa phong kiến","C. Diệt trừ văn hóa tư sản"],"answerLetter":"A","answerText":"A. Diệt trừ chủ nghĩa cá nhân","notes":""},{"id":100,"question":"Phẩm chất nào dưới đây không có trong nhân tố chủ quan dẫn đến hình thành tư tưởng Hồ Chí Minh?","options":["A. Một trái tim yêu nước thương dân, sẵn sàng chịu đựng hy sinh","B. Tư duy độc lập, tự chủ, sáng tạo, đầu óc phê phán tình tường, sáng suốt","C. Bản lĩnh kiên định, luôn tin vào nhân dân, khiêm tốn, bình dị, ham học hỏi","D. Ham công danh, phú quý"],"answerLetter":"D","answerText":"D. Ham công danh, phú quý","notes":""},{"id":101,"question":"Lực lượng làm nền tảng cho khối đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh là","options":["A. Công nhân","B. Công nhân, nông dân","C. Học trò, nhà buôn","D. Công nhân, nông dân, lao động trí óc"],"answerLetter":"D","answerText":"D. Công nhân, nông dân, lao động trí óc","notes":""},{"id":102,"question":"Theo Hồ Chí Minh, Đảng cộng sản Việt Nam là Đảng","options":["A. Cầm quyền","B. Quản lý","C. Phân quyền","D. Lãnh đạo"],"answerLetter":"A","answerText":"A. Cầm quyền","notes":""},{"id":103,"question":"Theo Hồ Chí Minh, Đảng cộng sản Việt Nam là đảng","options":["A. Của xã hội","B. Của nhân dân lao động và của dân tộc","C. Của dân, do dân và vì dân"],"answerLetter":"B","answerText":"B. Của nhân dân lao động và của dân tộc","notes":""},{"id":104,"question":"\"Tinh thần yêu nước chân chính khác hẳn với tinh thần \"vị quốc\" của bọn đế quốc phản động. Nó là một bộ phận của tỉnh thần quốc tế\" là câu nói được Hồ Chí Minh khẳng định trong Báo cáo chính trị của Đại hội đại biểu toàn quốc lần thứ mấy","options":["A. Lần thứ I","B. Lần thứ II","C. Lần thứ III","D. Lần thứ IV"],"answerLetter":"B","answerText":"B. Lần thứ II","notes":"( tháng 2 năm 1951)"},{"id":105,"question":"Khi nói về mặt trận, Hồ Chí Minh cho rằng","options":["A. Mặt trận phải được xây dựng trên nền tảng khối liên minh công - nông - trí thức, đặt dưới sự lãnh đạo của Đảng","B. Mặt trận phải được xây dựng trên nền tảng khối liên minh công - nông - trí thức, đặt dưới sự lãnh đạo của mặt trân phản đế","C. Mặt trận phải được xây dựng trên nền tảng khối liên minh công - nông - trí thức, đặt dưới sự lãnh đạo của giai cấp công nhân"],"answerLetter":"A","answerText":"A. Mặt trận phải được xây dựng trên nền tảng khối liên minh công - nông - trí thức, đặt dưới sự lãnh đạo của Đảng","notes":""},{"id":106,"question":"Nguyên tắc quan trọng bậc nhất trong xây dựng một nền đạo đức mới theo tư tưởng Hồ Chí Minh là:","options":["A. Nói đi đôi với làm","B. Nêu gương về đạo đức","C. Xây đi đôi với chống","D. Tu dưỡng đạo đức suốt đời"],"answerLetter":"A","answerText":"A. Nói đi đôi với làm","notes":""},{"id":107,"question":"Hồ Chí Minh chỉ ra căn bệnh nguy hiểm nhất đối với cán bộ nhà nước là gì?","options":["A. Chủ nghĩa cá nhân","B. Tham ô, lãng phí","C. Kéo bè kéo cánh","D. Lợi ích cá nhân"],"answerLetter":"A","answerText":"A. Chủ nghĩa cá nhân","notes":""},{"id":108,"question":"Để có thể tận dụng thời cơ, vượt qua thách thức, trên cơ sở nhận thức và vận dụng sáng tạo tư tưởng Hồ Chí Minh, cần tập trung vào vấn đề nào?","options":["A. Kiên định phương pháp cách mạng","B. Kiên định cách mạng","C. Kiên định theo chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh","D. Kiên định con đường xây dựng đất nước"],"answerLetter":"C","answerText":"C. Kiên định theo chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh","notes":""},{"id":109,"question":"Hồ Chí Minh cho rằng","options":["A. Văn hoá là tổng hợp của mọi phương thức sinh hoạt cùng với biểu hiện của nó mà loài người đã sản sinh ra nhằm thích ứng những nhu cầu đời sống và đòi hỏi của sự sinh tồn","B. Văn hoá là tổng hợp của mọi phương thức sinh hoạt cùng với biểu hiện của nó mà loài người đã sản sinh ra nhằm thích ứng những nhu cầu đời sống và đòi hỏi của sự sống còn","C. Văn hoá là tổng hợp của mọi phương thức sinh hoạt cùng với biểu hiện của nó mà loài người đã sản sinh ra nhằm thích ứng những nhu cầu đời sống và đòi hỏi của sự trường tồn"],"answerLetter":"A","answerText":"A. Văn hoá là tổng hợp của mọi phương thức sinh hoạt cùng với biểu hiện của nó mà loài người đã sản sinh ra nhằm thích ứng những nhu cầu đời sống và đòi hỏi của sự sinh tồn","notes":""},{"id":110,"question":"Nguyễn Tất Thành ở Anh vào thời gian nào?","options":["A. 1911-1912","B. 1912-1913","C. 1914-1917","D. 1911-1915"],"answerLetter":"C","answerText":"C. 1914-1917","notes":""},{"id":111,"question":"Hồ Chí Minh dạy học ở trường Dục Thanh - Phan Thiết trong khoảng thời gian nào?","options":["A. Năm 1909 - 1910","B. Năm 1909 - 1911","C. Năm 1908 - 1909","D. Năm 1910 - 1911"],"answerLetter":"D","answerText":"D. Năm 1910 - 1911","notes":""},{"id":112,"question":"Theo quan điểm của Đảng Cộng sản Việt Nam, Nhà nước pháp quyền là gì","options":["A. Nhà nước tạo ra sự ổn định về chính trị","B. Tuyển dụng cán bộ nhà nước phải thông qua thi tuyển chặt chẽ","C. Nhà nước quản lý xã hội bằng pháp luật và làm cho pháp luật có hiệu quả trong thực tế","D. Khuyến khích nhân dân tham gia vào các công việc của Nhà nước"],"answerLetter":"C","answerText":"C. Nhà nước quản lý xã hội bằng pháp luật và làm cho pháp luật có hiệu quả trong thực tế","notes":""},{"id":113,"question":"Theo Hồ Chí Minh, những tiêu cực của đội ngũ cán bộ trong hoạt động của bộ máy nhà nước là:","options":["A. Đặc quyền, đặc lợi.","B. Tham ô, lãng phí, quan liêu.","C. Tư túng, chia rẽ, kiêu ngạo.","D. Tất cả các phương án."],"answerLetter":"D","answerText":"D. Tất cả các phương án.","notes":""},{"id":114,"question":"Câu nói của Hồ Chí Minh \"Đoàn kết, đoàn kết, đại đoàn kết. Thành công, thành công đại thành cũng\" đó là cần phải đoàn kết ở đâu?","options":["A. Đoàn kết trong đảng, đoàn kết dân tộc và đoàn kết quốc tế","B. Đoàn kết trong đảng, đoàn kết quân đội và đoàn kết dân tộc","C. Đoàn kết dân tộc, đoàn kết tôn giáo tín ngưỡng và đồng bào ngoài nước"],"answerLetter":"A","answerText":"A. Đoàn kết trong đảng, đoàn kết dân tộc và đoàn kết quốc tế","notes":""},{"id":115,"question":"Một nhà nước pháp quyền có hiệu lực pháp lý mạnh mẽ theo tư tưởng Hồ Chí Minh phải là:","options":["A. Một nhà nước hợp hiến.","B. Một nhà nước thống nhất, có chủ quyền quốc gia.","C. Một nhà nước của dân, do dân, vì dân.","D. Một nhà nước không có tiêu cực, không có đặc quyền đặc lợi."],"answerLetter":"A","answerText":"A. Một nhà nước hợp hiến.","notes":""},{"id":116,"question":"Theo Hồ Chí Minh, không phải mọi con người đêu trở thành động lực, mà phải là những con người như thế nào?","options":["A. Được giác ngộ và tổ chức","B. Có đạo đức","C. Có năng lực","D. Có trình độ và hiểu biết"],"answerLetter":"A","answerText":"A. Được giác ngộ và tổ chức","notes":""},{"id":117,"question":"Hồ Chí Minh cho rằng thầy cô giáo trong chế độ ta cần phải góp phần vào:","options":["A. Công cuộc xây dựng XHCN","B. Công cuộc kháng chiến chống mỹ cứu nước","C. Công cuộc xây dựng xã hội mới"],"answerLetter":"A","answerText":"A. Công cuộc xây dựng XHCN","notes":""},{"id":118,"question":"Theo Hồ Chí Minh, chí công vô tư là nêu cao chủ nghĩa tập thể, trừ bỏ:","options":["A. chủ nghĩa cá nhân.","B. chủ nghĩa tư nhân.","C. chủ nghĩa tư bản.","D. chủ nghĩa vị kỷ."],"answerLetter":"A","answerText":"A. chủ nghĩa cá nhân.","notes":""},{"id":119,"question":"Điểm giống trong tư tưởng về xây dựng nhà nước của Hồ Chí Minh và các bậc tiền nhân trong lịch sử là:","options":["A. Dựa vào dân","B. Dựa vào bạo lực vũ trang","C. Dựa vào đạo đức cách mạng","D. Dựa vào tài năng, trí tuệ, phán đoán"],"answerLetter":"A","answerText":"A. Dựa vào dân","notes":""},{"id":120,"question":"Nguyễn Ái Quốc đến Liên Xô lần đầu tiên học tại trường nào?","options":["A. Trường quốc tế Lênin","B. Đại học Phương Đông","C. Viện nghiên cứu các vấn đề dân tộc và thuộc địa","D. Đại học Liên Xô"],"answerLetter":"B","answerText":"B. Đại học Phương Đông","notes":""},{"id":121,"question":"Trong tư tưởng Hồ Chí Minh, Quản lý nhà nước là quản lý bằng bộ máy, bằng pháp luật và bằng nhiều biện pháp khác nhau trong đó quan trọng bậc nhất là:","options":["A. Hiến pháp","B. Quyền lực","C. Mệnh lệnh","D. Hình phạt"],"answerLetter":"A","answerText":"A. Hiến pháp","notes":""},{"id":122,"question":"Luận điểm: \"Bồi dưỡng thế hệ cách mạng cho đời sau là một việc rất quan trọng và rất cần thiết\" được trích từ bài viết/ bài nói nào của Hồ Chí Minh?","options":["A. Đường Kách mệnh","B. Cần kiệm liêm chính","C. Di chúc","D. Bài nói chuyện tại Lớp bồi dưỡng cán bộ về công tác mặt trận"],"answerLetter":"C","answerText":"C. Di chúc","notes":""},{"id":123,"question":"Trong tư tưởng Hồ Chí Minh, đại đoàn kết dân tộc phải biến thành sức mạnh vật chất, trở thành lực lượng vật chất có tổ chức. Tổ chức đó chính là:","options":["A. Đoàn thể chính trị quần chúng.","B. Đảng Cộng sản Việt Nam.","C. Mặt trận dân tộc thống nhất.","D. Đoàn thanh niên Cộng sản."],"answerLetter":"C","answerText":"C. Mặt trận dân tộc thống nhất.","notes":""},{"id":124,"question":"Trong tư tưởng Hồ Chí Minh, đại đoàn kết dân tộc:","options":["A. Là vấn đề cơ bản quyết định thành công của cách mạng.","B. Là vấn đề có ý nghĩa sách lược, quyết định thành công của cách mạng.","C. Là vấn đề cơ bản có ý nghĩa chiến lược, quyết định thành công của cách mạng."],"answerLetter":"C","answerText":"C. Là vấn đề cơ bản có ý nghĩa chiến lược, quyết định thành công của cách mạng.","notes":"(Hồ Chí Minh đã khẳng định vị trí, vai trò của đại đoàn kết toàn dân tộc như thế nào?\nA. Đại đoàn kết toàn dân tộc là vấn đề có ý nghĩa chiến lược, quyết định thành công của cách mạng\nB. Đại đoàn kết toàn dân tộc là vấn đề có ý nghĩa sống còn, quyết định thành công cách mạng\nC. Đại đoàn kết toàn dân tộc là vấn đề có ý nghĩa lịch sử, quyết định thành công của cách mạng\nD. Đại đoàn kết toàn dân tộc là vấn đề có ý nghĩa đặc biệt quan trọng, quyết định thành công của cách)"},{"id":125,"question":"Trong tư tưởng Hồ Chí Minh, đại đoàn kết dân tộc là:","options":["A. Đoàn kết công-nông.","B. Đoàn kết công-nông-lao động trí ó","C. c. Đoàn kết công-nông và các tầng lớp xã hội khác.","D. Đại đoàn kết toàn dân."],"answerLetter":"D","answerText":"D. Đại đoàn kết toàn dân.","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, thực hiện đại đoàn kết dân tộc phải đoàn kết được với ai?\nA. Đại đoàn kết toàn dân\nB. Đại đoàn kết toàn kết giai cấp\nC. Đại đoàn kết rộng rãi\nD. Đoàn kết với công nông)"},{"id":126,"question":"Văn kiện nào của Đảng Lao động Việt Nam đã khẳng định: \"Dân tộc ta, nhân dân ta, non sông đất nước ta đã sinh ra Hồ Chủ Tịch, người anh hùng dân tộc vĩ đại, và chính Người đã làm rạng rỡ dân tộc ta, nhân dân ta và non sông đất nước ta\"?","options":["A. Báo cáo chính trị tại Đại hội đại biểu toàn quốc lần thứ II của Đảng","B. Điếu văn của Ban Chấp hành Trung ương Đảng Lao động Việt Nam tại Lễ Truy điệu Chủ tịch Hồ Chí Minh","C. Báo cáo chính trị tại Đại hội đại biểu toàn quốc lần thứ VI của Đảng","D. Báo cáo chính trị tại Đại hội đại biểu toàn quốc lần thứ VII của Đảng"],"answerLetter":"B","answerText":"B. Điếu văn của Ban Chấp hành Trung ương Đảng Lao động Việt Nam tại Lễ Truy điệu Chủ tịch Hồ Chí Minh","notes":""},{"id":127,"question":"Theo quan điểm của Đảng Cộng sản Việt Nam tại Đại hội đại biểu toàn quốc lần thứ XI, Tư tưởng Hồ Chí Minh là kết quả của sự vận dụng kế thừa giá trị nào?","options":["A. Sự phát triển chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta","B. Sự vận dụng và phát triển sáng tạo chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta","C. Sự vận dụng sáng tạo và phát triển chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta","D. Sự vận dụng sáng tạo chủ nghĩa Mác - Lênin trong điều kiện cụ thể của nước ta"],"answerLetter":"B","answerText":"B. Sự vận dụng và phát triển sáng tạo chủ nghĩa Mác - Lênin vào điều kiện cụ thể của nước ta","notes":""},{"id":128,"question":"Khẩu hiệu Tự do - Bình đẳng - Bác Ái r","options":["A. đời ở đâu?a. Đại cách mạng Pháp","B. Cách mạng Tân Hợi của Tôn Trung Sơn","C. Cải cách Minh Trị - Nhật Bản","D. Phong trào Duy Tân của Phan Châu Trinh"],"answerLetter":"A","answerText":"A. đời ở đâu?a. Đại cách mạng Pháp","notes":""},{"id":129,"question":"Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam mang bản chất gì?","options":["A. Mang bản chất giai cấp công nhân, dân tộc","B. Mang bản chất giai cấp công nhân, nhân dân lao động và dân tộc","C. Mang bản chất giai cấp công nhân, con người","D. Mang bản chất giai cấp công nhân"],"answerLetter":"D","answerText":"D. Mang bản chất giai cấp công nhân","notes":""},{"id":130,"question":"Tìm phương án sai Khái niệm tư tưởng Hồ Chí Minh mà Đại hội IX (2001) nêu lên bao gồm:","options":["A. Bản chất cách mạng và khoa học của tư tưởng Hồ Chí Minh","B. Nguồn gốc tư tưởng, lý luận của tư tưởng Hồ Chí Minh","C. Nội dung tư tưởng Hồ Chí Minh","D. Kết cấu tư tưởng Hồ Chí Minh"],"answerLetter":"D","answerText":"D. Kết cấu tư tưởng Hồ Chí Minh","notes":""},{"id":131,"question":"Theo Hồ Chí Minh, xây dựng khối đại đoàn kết toàn dân để tập hợp lực lượng, không được phép bỏ sót một lực lượng nào miễn không là Việt gian, không phản bội lại quyền lợi của dân chúng phải:","options":["A. Đứng vững trên lập trường nhân dân lao động, giải quyết hài hoà mối quan hệ giai cấp - dân tộc.","B. Đứng vững trên lập trường giai cấp nông dân, giải quyết hài hoà mối quan hệ giai cấp - dân tộc.","C. Đứng vững trên lập trường giai cấp công nhân, giải quyết hài hoà mối quan hệ giai cấp - dân tộc."],"answerLetter":"C","answerText":"C. Đứng vững trên lập trường giai cấp công nhân, giải quyết hài hoà mối quan hệ giai cấp - dân tộc.","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, xãy dựng khối đại đoàn kết toàn dẫn phải đũng vũng trên lập trường nào?\nA. Lập trường giai cấp công nhân, giải quyết hài hòa mỗi quan hệ giai cấp - dân tộc\nB. Lập trường giai cấp tư sản, ứu tiên đấu tranh giai cấp\nC. Lập trường giai cấp nông dân, ưu tiên đấu tranh ruộng đất\nD. Lập trường trí thức, ưu tiên phát triển khoa học công nghệ)"},{"id":132,"question":"Trong các luận điểm sau, luận điểm nào là của Hồ Chí Minh?","options":["A. Vô sản tất cả các nước, đoàn kết lại","B. Vô sản tất cả các nước và các dân tộc bị áp bức đoàn kết lại","C. Vô sản tất cả các nước liên hiệp lại","D. Lao động tất cả các nước, đoàn kết lại"],"answerLetter":"D","answerText":"D. Lao động tất cả các nước, đoàn kết lại","notes":""},{"id":133,"question":"Phương thức tiếp cận về chủ nghĩa xã hội của Hồ Chí Minh thiên về hướng nào dưới đây?","options":["A. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện kinh tế là chủ yếu","B. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện văn hóa là chủ yếu","C. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ nhiều góc độ khác nhau","D. Hồ Chí Minh tiếp cận Chủ nghĩa xã hội từ phương diện chính trị là chủ yếu"],"answerLetter":"C","answerText":"C. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ nhiều góc độ khác nhau","notes":""},{"id":134,"question":"Vận dụng tư tưởng Hồ Chí Minh cần phải nắm vững nguyên tắc:","options":["A. Quan điểm lịch sử thế giới","B. Quan điểm lịch sử Việt Nam","C. Quan điểm lịch sử cụ thể","D. Quan điểm lịch sử toàn diện"],"answerLetter":"C","answerText":"C. Quan điểm lịch sử cụ thể","notes":""},{"id":135,"question":"Để tăng cường tính nghiêm minh của pháp luật đi đôi với đẩy mạnh giáo dục đạo đức cách mạng, Hồ Chí Minh đã kết kết hợp nhuần nhuyễn giữ","options":["A. a. \"đức trị\" và \"pháp trị\".","B. nhân trị\" và \"pháp trị\".","C. pháp trị\" và \"tiền lệ\".","D. đức trị\" và \"tiền lệ\"."],"answerLetter":"A","answerText":"A. a. \"đức trị\" và \"pháp trị\".","notes":""},{"id":136,"question":"Câu nói \"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi được Bắc trong tác phẩm nào?","options":["A. Thư gửi đồng bảo Nam Bộ","B. Nam kỳ tự trị","C. Bức thư gửi đồng chí Lê Duẩn","D. Thành đồng tổ quốc"],"answerLetter":"A","answerText":"A. Thư gửi đồng bảo Nam Bộ","notes":""},{"id":137,"question":"Hồ Chí Minh mất bao nhiêu năm bôn ba nước ngoài để tìm đường cứu nước?","options":["A. 10 năm","B. 25 năm","C. 30 năm","D. 35 năm"],"answerLetter":"C","answerText":"C. 30 năm","notes":""},{"id":138,"question":"Hồ Chí Minh yêu cầu: \"phải phát huy hết ..., phải lột cho hết tinh thần dân tộc, để cổ vũ cho đồng bào ta, để giáo dục cho con cháu ta\"","options":["A. Cốt cách dân tộc","B. Hồn cốt dân tộc","C. Văn hóa dân tộc","D. Truyền thống dân tộc"],"answerLetter":"A","answerText":"A. Cốt cách dân tộc","notes":""},{"id":139,"question":"Hồ Chí Minh có lần chỉ rõ: \"Nói chung thì các dân tộc phương Đông đều giàu tình cảm và đối với họ một (.....) còn có giá trị hơn một trăm bài diễn văn tuyên truyền\"","options":["A. Quyển sách","B. Tấm gương sống","C. Tác phẩm lý luận","D. Câu chuyện ngụ ngôn"],"answerLetter":"B","answerText":"B. Tấm gương sống","notes":""},{"id":140,"question":"Theo Hồ Chí Minh, ưu điểm lớn nhất của chủ nghĩa Mác là gì?","options":["A. Bản chất cách mạng","B. Chủ nghĩa nhân đạo triệt để","C. Phương pháp làm việc biện chứng","D. Bản chất khoa học"],"answerLetter":"C","answerText":"C. Phương pháp làm việc biện chứng","notes":""},{"id":141,"question":"Theo Hồ Chí Minh, đạo đức là nhân tố tạo nên:","options":["A. sức mạnh, sức hấp dẫn của chủ nghĩa xã hội.","B. sức mạnh, sức hấp dẫn của chủ nghĩa Mác-Lênin.","C. sức mạnh, sức hấp dẫn của tư tưởng Hồ Chí Minh."],"answerLetter":"A","answerText":"A. sức mạnh, sức hấp dẫn của chủ nghĩa xã hội.","notes":""},{"id":142,"question":"Luận điểm sáng tạo của Hồ Chí Minh về cách mạng thuộc địa dựa trên cơ sở nào?","options":["A. Tinh thần đấu tranh cách mạng của các dân tộc ở các nước thuộc địa","B. Tinh thần đấu tranh của giai cấp vô sản ở chính quốc","C. Sự thức tỉnh của các dân tộc thuộc địa","D. Thuộc địa là khâu yếu nhất trong sợi dây xích của chủ nghĩa đế quốc"],"answerLetter":"A","answerText":"A. Tinh thần đấu tranh cách mạng của các dân tộc ở các nước thuộc địa","notes":""},{"id":143,"question":"Hồ Chí Minh cho rằng bản chất của Pháp và Nhật:","options":["A. Chẳng khác gì nhau","B. Khác nhau","C. Rất đặc biệt"],"answerLetter":"A","answerText":"A. Chẳng khác gì nhau","notes":"(Khi so sánh vẽ bản chất của Nhật và Pháp, Hồ chí Minh nhận định như thế nào?A. Chẳng khác gì nhauB. Khác nhauC. Rất đặc biệtD. Giống nhau)"},{"id":144,"question":"Nguyễn Ái Quốc gửi bản \"Bản yêu sách của nhân dân An Nam\" tới Hội nghị Vécxây, đòi chính phủ Pháp thừa nhận các quyền tự do, dân chủ và bình đẳng của nhân dân Việt Nam vào thời gian nào?","options":["A. 6/1917","B. 6/1918","C. 6/1919","D. 6/1920"],"answerLetter":"C","answerText":"C. 6/1919","notes":""},{"id":145,"question":"Theo Hồ Chí Minh, trong Nhà nước vì dân, từ Chủ tịch nước đến công chức bình thường đều phải làm công bộc, làm đầy tớ cho nhân dân chứ không phải làm:","options":["A. Tướng","B. Quan","C. Quan cách mạng","D. Trâu, ngựa"],"answerLetter":"C","answerText":"C. Quan cách mạng","notes":""},{"id":146,"question":"Theo Hồ Chí Minh, chủ nghĩa xã hội phải do :","options":["A. Nhân dân lao động làm chủ","B. Giai cấp công nhân làm chủ","C. Giai cấp nông dân làm chủ"],"answerLetter":"A","answerText":"A. Nhân dân lao động làm chủ","notes":""},{"id":147,"question":"Theo tư tưởng Hồ Chí Minh, con người Việt Nam trong thời đại mới phải có:","options":["A. 3 phẩm chất cơ bản","B. 4 phẩm chất cơ bản","C. 5 phẩm chất cơ bản","D. 6 phẩm chất cơ bản"],"answerLetter":"B","answerText":"B. 4 phẩm chất cơ bản","notes":""},{"id":148,"question":"Theo Hồ Chí Minh, tại sao phải đoàn kết quốc tế? (Chọn 2)","options":["A. Nhằm kết hợp sức mạnh dân tộc và sức mạnh thời đại, tạo sức mạnh tổng hợp cho cách mạng","B. Góp phần cùng nhân dân thế giới thực hiện các mục tiêu cách mạng","C. Vì đây là mục tiêu, nhiệm vụ hàng đầu của cách mạng Việt Nam","D. Nhằm kế thừa truyền thống yêu nước, nhân nghĩa, đoàn kết của dân tộc"],"answerLetter":"AB","answerText":"A. Nhằm kết hợp sức mạnh dân tộc và sức mạnh thời đại... & B. Góp phần cùng nhân dân thế giới thực hiện các mục tiêu cách mạng","notes":"AB\nNguyễn Tất Thành ở Mỹ vào thời gian nào?A. 1911-1912B. 1912-1913C. 1914-1917D. 1911-1915"},{"id":149,"question":"Theo Hồ Chí Minh, lực lượng của cách mạng giải phóng dân tộc là:","options":["A. Toàn dân tộc.","B. Công nhân và nông dân.","C. Trí thức, tiểu tư sản, tư sản dân tộc, địa chủ vừa và nhỏ.","D. Công nhân, nông dân và trí thức"],"answerLetter":"A","answerText":"A. Toàn dân tộc.","notes":""},{"id":150,"question":"Hồ Chí Minh quân tâm mối quan hệ với Trung Quốc trên tinh thần.","options":["A. Vừa là đồng chí, vừa là đồng đội\"","B. Vừa là đồng đội, vừa là đồng chí\".","C. Vừa là đồng chí, vừa là anh em\"."],"answerLetter":"C","answerText":"C. Vừa là đồng chí, vừa là anh em\".","notes":""},{"id":151,"question":"So với các nền dân chủ trước đây, dân chủ XHCN có điểm gì khác biệt cơ bản?","options":["A. Là nền dân chủ phi lịch sử","B. Là nền dân chủ dân túy","C. Không còn mang tính giai cấp","D. Là nền dân chủ rộng rãi cho giai cấp công nhân và nhân dân lao động"],"answerLetter":"D","answerText":"D. Là nền dân chủ rộng rãi cho giai cấp công nhân và nhân dân lao động","notes":""},{"id":152,"question":"Theo Hồ Chí Minh, nhà nước do dân thể hiện ở chỗ","options":["A. Do nhân dân lập nên","B. Do nhân dân làm chủ","C. Do nhân dân ủng hộ","D. Tất cả các phương án"],"answerLetter":"D","answerText":"D. Tất cả các phương án","notes":""},{"id":153,"question":"Theo Hồ Chí Minh, nhà nước do dân thể hiện ở chỗ:","options":["A. Do nhân dân quyết định","B. Do nhân dân chi phối","C. Do nhân dân áp đặt","D. Do nhân dân kiểm soát"],"answerLetter":"D","answerText":"D. Do nhân dân kiểm soát","notes":""},{"id":154,"question":"Theo Hồ Chí Minh, xây dựng đạo đức mới, trước hết là thực hành đạo đức cách mạng, thực hành.....","options":["A. Chí công vô tư","B. Cần kiệm liêm chính","C. Trung với nước, hiếu với dân","D. Cần, kiệm, liêm, chính, chí công vô tư"],"answerLetter":"D","answerText":"D. Cần, kiệm, liêm, chính, chí công vô tư","notes":""},{"id":155,"question":"Hồ Chí Minh cho rằng, \"Vì ... loài người mới sáng tạo và phát minh ra ngôn ngữ, chữ viết, đạo đức, pháp luật, khoa học, tôn giáo, văn học, nghệ thuật, những công cụ cho sinh hoạt hằng ngày về mặc, ăn, ở và các phương thức sử dụng\"\".Chọn phương án đúng điền vào chỗ trống.","options":["A. lễ sinh tồn cũng như mục đích của cuộc sống","B. nhu cầu đời sống và tinh thần","C. mục đích phát triển và sinh tồn","D. cuộc sống"],"answerLetter":"A","answerText":"A. lễ sinh tồn cũng như mục đích của cuộc sống","notes":""},{"id":156,"question":"Trong mục tiêu về chủ nghĩa xã hội, theo Hồ Chí Minh, mục tiêu kinh tế phải gắn bó với:","options":["A. mục tiêu văn hóa","B. mục tiêu giáo dục","C. mục tiêu chính trị","D. mục tiêu xã hội"],"answerLetter":"C","answerText":"C. mục tiêu chính trị","notes":""},{"id":157,"question":"Hồ Chí Minh lưu ý xây dựng nhà nước có hiệu lực pháp lý mạnh mẽ phải","options":["A. Xây dựng đội ngũ cán bộ, công chức đủ đức, tài","B. Xây dựng đội ngũ cán bộ, công chức đủ phẩm chất.","C. Xây dựng đội ngũ cán bộ, công chức đủ tài đức."],"answerLetter":"A","answerText":"A. Xây dựng đội ngũ cán bộ, công chức đủ đức, tài","notes":"(Kiểu hỏi khác: Một trong những nội dung về xây dựng nhà nước có hiệu lực pháp lý mạnh mẽ theo tư tưởng Hồ Chí Minh là)"},{"id":158,"question":"Nội dung nào không đúng về giá trị lý luận và thực tiễn của Tư tưởng Hồ Chí Minh về vấn đề dân tộc và cách mạng giải phóng dân tộc:","options":["A. Làm phong phú học thuyết Mác-Lênin về cách mạng thuộc địa.","B. Soi đường thắng lợi cho cách mạng giải phóng dân tộc ở Việt Nam","C. Nền tảng tư tưởng và kim chỉ nam cho hành động của cách mạng Việt Nam","D. Là tiền đề cho thắng lợi của Cách mạng tháng 8"],"answerLetter":"D","answerText":"D. Là tiền đề cho thắng lợi của Cách mạng tháng 8","notes":""},{"id":159,"question":"Theo Hồ Chí Minh, mục tiêu của chủ nghĩa xã hội gồm những nội dung nào sau đây?","options":["A. Chính trị, kinh tế, văn hóa xã hội và dân chủ","B. Chính trị, dân chủ, kinh tế, tiến bộ","C. Chính trị, kinh tế, văn hóa xã hội, con người","D. Chính trị, kinh tế, văn hóa, tiến bộ"],"answerLetter":"C","answerText":"C. Chính trị, kinh tế, văn hóa xã hội, con người","notes":""},{"id":160,"question":"Hồ Chí Minh xem đạo đức cách mạng là gì?","options":["A. Đạo đức cách mạng là hòa mình với quần chúng thành một khối, tin quần chúng, hiểu quần chúng, lắng nghe ý kiến của quần chúng","B. Đạo đức cách mạng là tin quần chúng, hiểu quần chúng, lắng nghe ý kiến của quần chúng","C. Đạo đức cách mạng là hòa mình cộng đồng, lắng nghe ý kiến của cộng đồng"],"answerLetter":"A","answerText":"A. Đạo đức cách mạng là hòa mình với quần chúng thành một khối, tin quần chúng, hiểu quần chúng, lắng nghe ý kiến của quần chúng","notes":""},{"id":161,"question":"Theo Hồ Chí Minh, ưu điểm lớn nhất của chủ nghĩa Tam dân của Tôn Trung Sơn là gì?","options":["A. Chống phong kiến.","B. Đấu tranh vì tự do, dân chủ.","C. Phù hợp với điều kiện thực tế nước ta."],"answerLetter":"C","answerText":"C. Phù hợp với điều kiện thực tế nước ta.","notes":"(Kiểu hỏi khác: \"Chủ nghĩa ... có ưu điểm là chính sách của nó phù hợp với điều kiện nước ta\". Hồ Chí Minh đang nói đến chủ nghĩa nào?\n=> Tôn Dật Tiên)"},{"id":162,"question":"Lối sống ích kỷ, chỉ biết có riêng mình, thu vén cho riêng mình, chỉ thấy công lao của mình mà quên công lao của người khác. Theo Hồ Chí Minh là gì?","options":["A. Chủ nghĩa cá nhân","B. Chủ nghĩa vị kỷ","C. Chủ nghĩa tư bản","D. Phong cách tiểu tư sản"],"answerLetter":"A","answerText":"A. Chủ nghĩa cá nhân","notes":""},{"id":163,"question":"Theo tư tưởng Hồ Chí Minh, luận điểm Đảng Cộng sản là nhân tố quyết định hàng đầu để đưa cách mạng Việt Nam đi đến thắng lợi là:","options":["A. Xác định vị thế cầm quyền của Đảng.","B. Xá","C. định vai trò lãnh đạo của Đảng.c. Xác định mục đích của Đảng.","D. Xác định nhiệm vụ của Đảng."],"answerLetter":"B","answerText":"B. Xá","notes":""},{"id":164,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh?","options":["A. Bồi dưỡng tư tưởng đúng đắn và tình cảm cao đẹp cho con người","B. Bồi dưỡng tư tưởng đúng đắn và tình cảm cao đẹp cho xã hội","C. Bồi dưỡng tư tưởng đúng đắn và tình cảm cao đẹp cho nhân loại"],"answerLetter":"A","answerText":"A. Bồi dưỡng tư tưởng đúng đắn và tình cảm cao đẹp cho con người","notes":""},{"id":165,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh","options":["A. Nâng cao dân trí","B. Nâng cao nhân lực","C. Nâng cao dân tài"],"answerLetter":"A","answerText":"A. Nâng cao dân trí","notes":""},{"id":166,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh","options":["A. Bồi dưỡng những phẩm chất tốt đẹp và phong cách lành mạnh cho con người","B. Bồi dưỡng những phẩm chất tốt đẹp và phong cách lành mạnh cho xã hội","C. Bồi dưỡng những phẩm chất tốt đẹp và phong cách lành mạnh cho nhân dân"],"answerLetter":"A","answerText":"A. Bồi dưỡng những phẩm chất tốt đẹp và phong cách lành mạnh cho con người","notes":""},{"id":167,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh","options":["A. Cải tạo xã hội","B. Cải tạo thế giới","C. Cải tạo cộng đồng"],"answerLetter":"A","answerText":"A. Cải tạo xã hội","notes":""},{"id":168,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh?","options":["A. mở rộng hiểu biết, nâng cao dân trí.","B. mở rộng hiểu biết, nâng cao quan trí.","C. mở rộng hiểu biết, nâng cao trình độ."],"answerLetter":"A","answerText":"A. mở rộng hiểu biết, nâng cao dân trí.","notes":""},{"id":169,"question":"Đâu là chức năng của văn hóa theo tư tưởng Hồ Chí Minh?","options":["A. Bồi dưỡng những phẩm chất, phong cách và lối sống tốt đẹp, lành mạnh; hướng con người đến chân, thiện, mỹ để hoàn thiện xã hội.","B. Bồi dưỡng những phẩm chất, phong cách và lối sống tốt đẹp, lành mạnh; hướng con người đến chân, thiện, mỹ để hoàn thiện bản thân.","C. Bồi dưỡng những phẩm chất, phong cách và lối sống tốt đẹp, lành mạnh; hướng con người đến chân, thiện, mỹ để hoàn thiện con người."],"answerLetter":"B","answerText":"B. Bồi dưỡng những phẩm chất, phong cách và lối sống tốt đẹp, lành mạnh; hướng con người đến chân, thiện, mỹ để hoàn thiện bản thân.","notes":""},{"id":170,"question":"Đại đoàn kết quốc tế trong tư tưởng Hồ Chí Minh được xác định là:","options":["A. Một nhân tố thường xuyên và hết sức quan trọng giúp cho cách mạng Việt Nam đi đến thắng lợi hoàn toàn.","B. Có ý nghĩa sống còn đối với cách mạng Việt Nam.","C. Vấn đề cơ bản của cách mạng việt Nam.","D. Sức mạnh giúp cho dân tộc ta vượt qua mọi thử thách, khó khăn trong dựng nước và giữ nước."],"answerLetter":"A","answerText":"A. Một nhân tố thường xuyên và hết sức quan trọng giúp cho cách mạng Việt Nam đi đến thắng lợi hoàn toàn.","notes":""},{"id":171,"question":"Luận điểm \"Đoàn kết, đoàn kết, đại đoàn kết; Thành công, thành công, đại thành công\" của Hồ Chí Minh được trích từ tác phẩm:","options":["A. Bài nói chuyện tại trong buổi Bế mạc Đại hội thành lập Mặt trận Tổ Quốc Việt Nam","B. Bài nói chuyện tại Hội nghị mở rộng Ủy ban Mặt trận Tổ quốc Việt Nam","C. Bài nói chuyện tại Đại hội đại biểu Mặt trận Tổ Quốc Việt Nam lần thứ II","D. Buổi nói chuyện với cán bộ, chiến sĩ Đại đoàn Quân Tiên Phong"],"answerLetter":"C","answerText":"C. Bài nói chuyện tại Đại hội đại biểu Mặt trận Tổ Quốc Việt Nam lần thứ II","notes":""},{"id":172,"question":"Mặt trận dân tộc thống nhất trong tư tưởng Hồ Chí Minh được xây dựng như thế nào?","options":["A. Là nơi tập hợp mọi người dân ở trong nước Việt Nam","B. Là tổ chức tập hợp ngẫu nhiên quần chúng nhân dân","C. Là khối đại đoàn kết chặt chẽ có tổ chức trên nền tảng khối liên minh công - nông - trí thức do Đảng Cộng sản lãnh đạo","D. Là nơi quy tụ mọi người Việt Nam định cư ở nước ngoài, dù ở bất cứ phương trời nào"],"answerLetter":"C","answerText":"C. Là khối đại đoàn kết chặt chẽ có tổ chức trên nền tảng khối liên minh công - nông - trí thức do Đảng Cộng sản lãnh đạo","notes":""},{"id":173,"question":"Trong Mặt trận dân tộc thống nhất, Đảng Cộng sản đóng vai trò là gì?","options":["A. Thành viên của Mặt trận dân tộc thống nhất","B. Lực lượng lãnh đạo Mặt trận dân tộc thống nhất","C. Vừa là thành viên, vừa là lực lượng lãnh đạo Mặt trận dân tộc thông nhất","D. Đại biểu của giai cấp công nhân trong Mặt trận dân tộc thống nhất"],"answerLetter":"C","answerText":"C. Vừa là thành viên, vừa là lực lượng lãnh đạo Mặt trận dân tộc thông nhất","notes":""},{"id":174,"question":"Hồ Chí Minh nhấn mạnh vấn đề nào sau đây trong quan hệ giữa cán bộ nhà nước với nhân dân","options":["A. Kinh trọng nhân dân","B. Tự tôn dân tộc","C. Nghiêm khắc","D. Phục tùng"],"answerLetter":"A","answerText":"A. Kinh trọng nhân dân","notes":""},{"id":175,"question":"Theo Hồ Chí Minh, Đảng cộng sản Việt Nam ra đời trên cơ sở của những yếu tố nào?","options":["A. Chủ nghĩa Mác - Lênin, phong trào công nhân, phong trào cách mạng thế giới.","B. Chủ nghĩa Mác - Lênin, phong trào yêu nước Việt Nam.","C. Phong trào công nhân, phong trào yêu nước Việt Nam, phong trào cách mạng thế giới.","D. Chủ nghĩa Mác - Lênin, phong trào công nhân, phong trào yêu nước Việt Nam."],"answerLetter":"D","answerText":"D. Chủ nghĩa Mác - Lênin, phong trào công nhân, phong trào yêu nước Việt Nam.","notes":""},{"id":176,"question":"Theo tư tưởng Hồ Chí Minh, Đảng Cộng sản Việt Nam vừa là người lãnh đạo, vừa là người đầy tớ trung thành của nhân dân, Đảng phải chăm lo mối quan hệ giữ","options":["A. Đảng với dân là nhằm:a. Xác định vị thế cầm quyền của Đảng.","B. Xá","C. định phương thức cầm quyền của Đảng.c. Xác định năng lực cầm quyền của Đảng.","D. Xác định tính chất cầm quyền của Đảng."],"answerLetter":"A","answerText":"A. Đảng với dân là nhằm:a. Xác định vị thế cầm quyền của Đảng.","notes":"(Nếu chọn 3 thì chọn abc)"},{"id":177,"question":"Theo Hồ Chí Minh, nguyên tắc hiệp thương dân chủ đòi hỏi tất cả mọi vấn đề của Mặt trận đều phải được đem ra cho tất cả các thành viên cùng nhau bàn bạc công khai, để đi đến nhất trí, loại trừ mọi sự áp đặt hay còn vấn đề nào khác nữa?","options":["A. Dân chủ hình thức","B. Dân chủ tự nguyện","C. Chuyên quyền độc đoán","D. Không dân chủ"],"answerLetter":"A","answerText":"A. Dân chủ hình thức","notes":""},{"id":178,"question":"Hồ Chí Minh cho rằng xây dựng nhà nước trong sạch vững mạnh cần phải làm gì?","options":["A. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức cách mạng","B. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức cán bộ","C. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức quần chúng","D. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức công - nông"],"answerLetter":"A","answerText":"A. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức cách mạng","notes":""},{"id":179,"question":"Luận điểm \"Công cuộc giải phóng anh em chỉ có thể thực hiện được bằng sự nỗ lực của bản thân anh em\" là của:","options":["A. C. Mắc","B. Ph. Ăngghen","C. VILênin","D. Hồ Chí Minh"],"answerLetter":"D","answerText":"D. Hồ Chí Minh","notes":""},{"id":180,"question":"Trong những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ cộng hòa, khi nói về vấn đề thứ hai - nạn dốt, Hồ Chí Minh đã đề nghị mở một chiến dịch gì? Chọn phương án chính xác nhất","options":["A. Một chiến dịch xây dựng đời sống mới","B. Một chiến dịch để chống nạn mù chữ","C. Một chiến dịch tuyên truyền nền giáo dục mỗi","D. Một chiến dịch xây dựng nền văn hóa mới"],"answerLetter":"B","answerText":"B. Một chiến dịch để chống nạn mù chữ","notes":""},{"id":181,"question":"Theo Hồ Chí Minh độc lập, tự do là:","options":["A. Quyền lợi của tất cả các quốc gia","B. Quyền thiêng liêng và bất khả xâm phạm của tất cả các dân tộc","C. Đặc quyền của mỗi một dân tộc","D. Quyền thiêng liêng của tất cả các dân tộc"],"answerLetter":"B","answerText":"B. Quyền thiêng liêng và bất khả xâm phạm của tất cả các dân tộc","notes":""},{"id":182,"question":"Hồ Chí Minh cho rằng","options":["A. Đạo đức là gốc của người cách mạng","B. Đạo đức là gốc của người xã hội","C. Đạo đức là gốc của người công chúng"],"answerLetter":"A","answerText":"A. Đạo đức là gốc của người cách mạng","notes":"(Kiểu hỏi khác: Đâu là quan điểm đúng với tư tưởng Hồ Chí Minh về người cách mạng)"},{"id":183,"question":"Hồ Chính Minh nhấn mạnh khuyết điểm của thanh niên là","options":["A. Bệnh anh hùng","B. Tự cao","C. Tự đại"],"answerLetter":"A","answerText":"A. Bệnh anh hùng","notes":""},{"id":184,"question":"Hồ Chí Minh cho rằng:","options":["A. Đạo đức nhân văn xã hội chủ nghĩa là sức cuốn hút của chủ nghĩa cộng sản","B. Đạo đức nhân văn xã hội chủ nghĩa là sức cuốn hút của chủ nghĩa xã hội","C. Đạo đức nhân văn xã hội chủ nghĩa là sức cuốn hút của chủ nghĩa dân chủ"],"answerLetter":"B","answerText":"B. Đạo đức nhân văn xã hội chủ nghĩa là sức cuốn hút của chủ nghĩa xã hội","notes":""},{"id":185,"question":"Theo Hồ Chí Minh, bọn đế quốc thực dân tuyên truyền khẩu hiệu \"độc lập tự do\" thực chất là che đậy bản chất:","options":["A. ăn cướp\" và \"giết người\"","B. ăn cắp\" và \"hại dân\"","C. bóc lột\" và \"đàn áp\"","D. cướp bóc\" và \"đàn áp\""],"answerLetter":"A","answerText":"A. ăn cướp\" và \"giết người\"","notes":""},{"id":186,"question":"Hồ Chí Minh tìm thấy con đường cứu nước giải phóng dân tộc trong thời kì nào?","options":["A. Từ 1911 đến 1920","B. Từ 1921 đến 1930","C. Từ 1890 đến 1911","D. Từ 1930 đến 1945"],"answerLetter":"A","answerText":"A. Từ 1911 đến 1920","notes":"(Kiểu hỏi khác: Giai đoạn nào sau đây hình thành cơ bản tư tưởng Hồ Chí Minh trong việc tìm thấy con đường cứu nước, giải phóng dân tộc ?\nA. 1911 đến 1930\nB. 1911 đến 1920\nC. 1911 đến 1935\nD. 1908 đến 1911)"},{"id":187,"question":"Khi nói về Hồ Chí Minh, báo Uruguay viết:","options":["A. Ông có một trái tim bao la như vũ trụ và tình yêu trẻ thơ vô bờ bến","B. Ông người có tình cảm bao la như vũ trụ và tình yêu trẻ thơ vô bờ bến","C. Ông có một trái tim như vũ trụ và tình yêu trẻ thơ vô bờ bến"],"answerLetter":"A","answerText":"A. Ông có một trái tim bao la như vũ trụ và tình yêu trẻ thơ vô bờ bến","notes":""},{"id":188,"question":"Nội dung nào không phải là thực chất vấn đề dân tộc thuộc địa trong tư tưởng Hồ Chí Minh:","options":["A. Đấu tranh chống chủ nghĩa thực dân, giải phóng dân tộc.","B. Lựa chọn con đường phát triển của dân tộc là CNXH.","C. Đòi quyền tự do dân chủ tối thiểu cho nhân dân."],"answerLetter":"C","answerText":"C. Đòi quyền tự do dân chủ tối thiểu cho nhân dân.","notes":""},{"id":189,"question":"Đâu là luận điểm sáng tạo của Hồ Chí Minh về vấn đề lãnh đạo của Đảng","options":["A. Lý luận về Đảng Cộng sản cầm quyền","B. Tư duy của Đảng Cộng sản","C. Đường lối của Đảng Cộng sản"],"answerLetter":"A","answerText":"A. Lý luận về Đảng Cộng sản cầm quyền","notes":""},{"id":190,"question":"Tư tưởng văn hoá phương Tây nào sau đây ảnh hưởng đến sự hình thành tư tưởng dân chủ Hồ Chí Minh trước khi người ra đi tìm đường cứu nước?","options":["A. Truyền thống văn hoá dân chủ, tiến bộ của Đức","B. Truyền thống văn hoá dân chủ, tiến bộ của Pháp","C. Chủ nghĩa thực chứng Hoa Kỳ","D. Triết học phương Tây"],"answerLetter":"B","answerText":"B. Truyền thống văn hoá dân chủ, tiến bộ của Pháp","notes":""},{"id":191,"question":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc muốn thắng lợi:","options":["A. Phải đi theo con đường cách mạng vô sản.","B. Phải đi theo con đường cách mạng Pháp, Mỹ.","C. Phải đi theo con đường cách mạng tháng Mười Nga","D. Phải đi theo con đường cách mạng của các bậc tiền bối Việt Nam."],"answerLetter":"A","answerText":"A. Phải đi theo con đường cách mạng vô sản.","notes":""},{"id":192,"question":"Theo Hồ Chí Minh, muốn tăng cường đoàn kết quốc tế trong cuộc đấu tranh vì mục tiêu chung, các Đảng Cộng sản phải tiến hành có hiệu quả việc giáo dục chủ nghĩa yêu nước chân chính kết hợp với:","options":["A. Chủ nghĩa vô sản.","B. Chủ nghĩa xã hội.","C. Chủ nghĩa quốc tế.","D. Chủ nghĩa Mác - Lênin."],"answerLetter":"A","answerText":"A. Chủ nghĩa vô sản.","notes":""},{"id":193,"question":"Theo Hồ Chí Minh, người cách mạng phải có đạo đức, không có đạo đức thì","options":["A. Dù tài giỏi mấy cũng bỏ đi","B. Dù tài giỏi mấy cũng không đáng dùng","C. Dù tài giỏi mấy cũng không lãnh đạo được nhân dân","D. Dù tài giỏi mấy cũng không xứng đáng là người cách mạng"],"answerLetter":"C","answerText":"C. Dù tài giỏi mấy cũng không lãnh đạo được nhân dân","notes":""},{"id":194,"question":"Theo Hồ Chí Minh, nhà nước vì dân là","options":["A. Do nhân dân lập nên","B. Quyền lực của nhà nước và xã hội thuộc về nhân dân","C. Tất cả các phương án","D. Nhà nước lấy lợi ích chính đáng của nhân dân làm mục tiêu"],"answerLetter":"C","answerText":"C. Tất cả các phương án","notes":""},{"id":195,"question":"Nguyễn Ái Quốc là người Việt Nam thứ mấy tham gia vào Đảng Cộng sản Pháp?","options":["A. Thứ nhất","B. Thứ hai","C. Thứ ba","D. Thứ tư"],"answerLetter":"A","answerText":"A. Thứ nhất","notes":""},{"id":196,"question":"Hồ Chí Minh cho rằng, phong trào cộng sản công nhân quốc tế trở thành lực lượng quyết định vẫn mệnh của loài người không chỉ do chiến lược và sách lược thiên tài của cách mạng vô sản, mà còn do","options":["A. Những phẩm chất đạo đức cao quý làm cho chủ nghĩa cộng sản trở thành một sức mạnh vô địch","B. Vũ khí, đạn dược hiện đại làm cho chủ nghĩa cộng sản trở thành một sức mạnh vô địch","C. Khoa học, kỹ thuật tiên tiến làm cho chủ nghĩa cộng sản trở thành một sức mạnh vô địch"],"answerLetter":"A","answerText":"A. Những phẩm chất đạo đức cao quý làm cho chủ nghĩa cộng sản trở thành một sức mạnh vô địch","notes":""},{"id":197,"question":"Theo Hồ Chí Minh \" Tất cả.. trong nước là của toàn thể nhân dân Việt Nam\".","options":["A. Quyền hành","B. Quyền lực","C. Quyền bính","D. Quyền binh"],"answerLetter":"C","answerText":"C. Quyền bính","notes":""},{"id":198,"question":"Khi nói về vấn đề độc lập dân tộc và giai cấp, Hồ Chí Minh cho rằng:","options":["A. Phải kết hợp nhuần nhuyễn dân tộc với giai cấp, độc lập dân tộc và chủ nghĩa xã hội, chủ nghĩa yêu nước với chủ nghĩa nhân văn","B. Phải kết hợp nhuần nhuyễn dân tộc với giai cấp, độc lập dân tộc và chủ nghĩa xã hội, chủ nghĩa yêu nước với chủ nghĩa nhân đạo","C. Phải kết hợp nhuần nhuyễn dân tộc với giai cấp, độc lập dân tộc và chủ nghĩa xã hội, chủ nghĩa yêu nước với chủ nghĩa quốc tế","D. Phải kết hợp nhuẫn nhuyễn giữa giai cấp với dần tộc, chủ nghĩa xã hội và độc lập dần tộc, chủ nghĩa yêu nước và chủ nghĩa quốc tế đại đồng"],"answerLetter":"C","answerText":"C. Phải kết hợp nhuần nhuyễn dân tộc với giai cấp, độc lập dân tộc và chủ nghĩa xã hội, chủ nghĩa yêu nước với chủ nghĩa quốc tế","notes":""},{"id":199,"question":"Hồ Chí Minh đã đề ra Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa vào thời điểm nào?","options":["A. Năm 1947","B. Năm 1946","C. Năm 1945","D. Năm 1944"],"answerLetter":"C","answerText":"C. Năm 1945","notes":""},{"id":200,"question":"Theo Hồ Chí Minh, mỗi cán bộ, đảng viên \"đều là công bộc của dân, nghĩa là để gánh việc chung cho dân, chứ không phải để:","options":["A. Đè đầu dân.","B. Hạch sách dân","C. Làm khó cho dân"],"answerLetter":"A","answerText":"A. Đè đầu dân.","notes":""},{"id":201,"question":"Theo Hồ Chí Minh, Nhà nước Việt Nam được xây dựng phải là:","options":["A. Nhà nước hợp pháp, hợp hiến","B. Nhà nước quốc gia dân tộc","C. Nhà nước tự lập, tự tôn","D. Nhà nước bảo hộ cho phép"],"answerLetter":"A","answerText":"A. Nhà nước hợp pháp, hợp hiến","notes":""},{"id":202,"question":"Hồ Chí Minh cho rằng xây dựng văn hóa mới trước hết cần phải làm gì?","options":["A. Tư tưởng phải được tự do","B. Tư tưởng phải được nuôi dưỡng","C. Phải xây dựng xã hội dân chủ"],"answerLetter":"C","answerText":"C. Phải xây dựng xã hội dân chủ","notes":""},{"id":203,"question":"Điền vào chỗ trống. Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam đưa ra định nghĩa:\"Tư tưởng Hồ Chí Minh là... toàn diện sâu sắc về những vẫn vấn đề cơ bản của cách mạng Việt Nam\"","options":["A. Hệ thống các vấn đề","B. Hệ thống các tư tưởng","C. Hệ thống các luận điểm","D. Hệ thống các quan điểm"],"answerLetter":"D","answerText":"D. Hệ thống các quan điểm","notes":""},{"id":204,"question":"Hồ Chí Minh cho rằng đoàn kết quốc tế phải.","options":["A. Nêu cao ngọn cờ hoà bình, công lý","B. Nêu cao ngọn cờ hoà bình, tự do","C. Nêu cao ngọn cờ hoà bình, bình đẳng"],"answerLetter":"A","answerText":"A. Nêu cao ngọn cờ hoà bình, công lý","notes":""},{"id":205,"question":"Đâu là quan điểm củ","options":["A. Hồ Chí Minh về xây dựng con ngườia. Con người cụ thể, lịch sử","B. Con người cụ thể, văn hóa","C. Con người cụ thể, xã hội","D. Con người lịch sử, văn hóa"],"answerLetter":"A","answerText":"A. Hồ Chí Minh về xây dựng con ngườia. Con người cụ thể, lịch sử","notes":""},{"id":206,"question":"Đâu là quan điểm của Hồ Chí Minh về xây dựng con người","options":["A. Bản chất con người mang tính xã hội","B. Bản chất con người mang tính nhân dân","C. Bản chất con người mang tính dân chủ","D. Bản chất con người mang tính kế thừa"],"answerLetter":"A","answerText":"A. Bản chất con người mang tính xã hội","notes":"(Kiểu hỏi khác:\n- Đâu là quan điểm của Hồ Chí Minh về bản chất con người?\n- Theo Hồ Chí Minh: Con người có tính xã hội, là con người xã hội, thành viên của một cộng đồng xã hội. Được hiểu là? -> Quan điểm của Hồ Chí Minh về xây dựng con người.)"},{"id":207,"question":"Đâu là quan điểm củ","options":["A. Hồ Chí Minh về xây dựng con người mớia. Con người là mục tiêu, là động lực","B. Con người là mục tiêu, là phương châm","C. Con người là mục tiêu, là chiến lược"],"answerLetter":"A","answerText":"A. Hồ Chí Minh về xây dựng con người mớia. Con người là mục tiêu, là động lực","notes":""},{"id":208,"question":"Ngoại ngữ nào sau đây được Hồ Chí Minh sử dụng trong thời gian học tập ở trường Quốc học Huế?","options":["A. Tiếng Anh","B. Tiếng Pháp","C. Tiếng Trung","D. Tiếng Nga"],"answerLetter":"B","answerText":"B. Tiếng Pháp","notes":""},{"id":209,"question":"Theo Hồ Chí Minh, chỉ có ..... mới giải phóng được các dân tộc bị áp bức và giai cấp công nhân toàn thế giới.","options":["A. Chủ nghĩa xã hội và chủ nghĩa cộng sản.","B. Giai cấp công nhân và giai cấp nông dân","C. Giai cấp công nhân và nhân dân lao động","D. Đảng Cộng sản và giai cấp công nhân"],"answerLetter":"A","answerText":"A. Chủ nghĩa xã hội và chủ nghĩa cộng sản.","notes":""},{"id":210,"question":"Hòa bình là phương pháp cách mạng","options":["A. Không hiệu quả","B. Rất nhân văn","C. Không cần thiết","D. Mang tính chất giáo điều"],"answerLetter":"B","answerText":"B. Rất nhân văn","notes":""},{"id":211,"question":"Thực hành đạo đức cách mạng trong xã hội hiện nay , theo Hồ Chí Minh là:","options":["A. Làm đúng quyền hạn và bổn phận","B. Làm đúng theo trách nhiệm và quyền hạn","C. Luôn nghĩ về nhân dân , xuất phát từ dân mà làm , không phạm pháp luật","D. Luôn luôn làm theo tư tưởng Hồ Chí Minh"],"answerLetter":"C","answerText":"C. Luôn nghĩ về nhân dân , xuất phát từ dân mà làm , không phạm pháp luật","notes":""},{"id":212,"question":"Theo Hồ Chí Minh, con đường quá độ lên CNXH ở Việt Nam là:","options":["A. Quá độ lên chủ nghĩa xã hội không qua giai đoạn phát triển tư bản chủ nghĩa.","B. Quá độ lên chủ nghĩa xã hội không qua giai đoạn phát triển xã hội phong kiến.","C. Quá độ lên chủ nghĩa xã hội không qua giai đoạn phát triển xã hội dân chủ.","D. Quá độ lên chủ nghĩa xã hội không qua giai đoạn phát triển cộng sản chủ nghĩa."],"answerLetter":"A","answerText":"A. Quá độ lên chủ nghĩa xã hội không qua giai đoạn phát triển tư bản chủ nghĩa.","notes":""},{"id":213,"question":"Trong quá trình xây dựng khối đại đoàn kết toàn dân tộc phải đứng vững trên lập trường của giai cấp nào?","options":["A. Giai cấp nông dân","B. Tầng lớp trí thức","C. Giai cấp công nhân","D. Tư sản dân tộc"],"answerLetter":"C","answerText":"C. Giai cấp công nhân","notes":""},{"id":214,"question":"Quan điểm nào sau đây thuộc vấn đề công tác cán bộ theo tư tưởng Hồ Chí Minh ?","options":["A. Gần dân, học hỏi nhân dân, lắng nghe ý kiến ngoài đảng","B. Gần dân, học hỏi nhân dân, lắng nghe ý kiến của mọi tầng lớp","C. Gần dân, học hỏi nhân dân, lắng nghe ý kiến mọi người","D. Gần dân, học hỏi nhân dân, lắng nghe ý kiến nhân dân"],"answerLetter":"D","answerText":"D. Gần dân, học hỏi nhân dân, lắng nghe ý kiến nhân dân","notes":""},{"id":215,"question":"Trong Di chúc, khi nói về những người nạn nhân của chế độ xã hội cũ, như trộm cắp, gái điếm, cờ bạc, buôn lậu, v.v., Hồ Chí Minh đã căn dặn Nhà nước phải dùng biện pháp gì để cải tạo, giúp họ trở nên những người lao động lương thiện","options":["A. Giáo dục, pháp luật","B. Nhắc nhở, trừng phạt","C. Răn đe, pháp luật","D. Giáo dục, đạo đức"],"answerLetter":"A","answerText":"A. Giáo dục, pháp luật","notes":""},{"id":216,"question":"Trong mối quan hệ giữa văn hóa, kinh tế, chính trị, theo Hồ Chí Minh chế độ chính trị và nền kinh tế được coi là","options":["A. Nền tảng và quyết định tính chất của văn hóa","B. Cơ sở và quyết định đến bản chất của văn hóa","C. Cái quyết định đến văn hóa","D. Cơ sở phát triển văn hóa"],"answerLetter":"A","answerText":"A. Nền tảng và quyết định tính chất của văn hóa","notes":""},{"id":217,"question":"Tiền đề tư tưởng, lí luận dẫn đến sự hình thành tư tưởng Hồ Chí Minh là","options":["A. Giá trị truyền thống Việt Nam","B. Giá trị truyền thống văn hóa Việt Nam","C. Giá trị tư tưởng Việt Nam"],"answerLetter":"B","answerText":"B. Giá trị truyền thống văn hóa Việt Nam","notes":""},{"id":218,"question":"Truyền thống nào của dân tộc Việt Nam là nguồn gốc hình thành tư tưởng Hồ Chí Minh ?","options":["A. Truyền thống yêu nước, lạc quan, yêu đời; có niềm tin vào chính nghĩa, tin vào sức mạnh của bản thân và dân tộc","B. Truyền thống lạc quan, yêu đời; có niềm tin vào chính nghĩa, tin vào sức mạnh của bản thân và dân tộc","C. Truyền thống nhân nghĩa, thủy chung, lạc quan, yêu đời, có niềm tin vào chính nghĩa, tin vào sức mạnh của bản thân và dân tộc","D. Truyền thống đoàn kết, lạc quan, yêu đời, có niềm tin vào chính nghĩa, tin vào sức mạnh của bản thân và dân tộc"],"answerLetter":"A","answerText":"A. Truyền thống yêu nước, lạc quan, yêu đời; có niềm tin vào chính nghĩa, tin vào sức mạnh của bản thân và dân tộc","notes":""},{"id":219,"question":"Tính chất nhân văn trong bao lực cách mạng của Hồ Chí Minh là:","options":["A. Con đường bạo lực cách mạng gắn bó hữu cơ nhân đạo, tự do","B. Con đường cách mạng bạo lực gắn bó hữu cơ với nhân văn, hòa bình","C. Con đường cách mạng bạo lực gắn bó hữu cơ với tự do, hòa bình","D. Con đường cách mạng bạo lực gắn bó hữu cơ với nhân đạo, hòa bình"],"answerLetter":"D","answerText":"D. Con đường cách mạng bạo lực gắn bó hữu cơ với nhân đạo, hòa bình","notes":""},{"id":220,"question":"Đâu là quan điểm củ","options":["A. Hồ Chí Minh về chiến lược trồng người?a. \"Trồng người\" là trung tâm của phát triển xã hội","B. Trồng người\" là trung tâm phát triển của nhân loại","C. Trồng người\" là trung tâm phát triển thế giới"],"answerLetter":"A","answerText":"A. Hồ Chí Minh về chiến lược trồng người?a. \"Trồng người\" là trung tâm của phát triển xã hội","notes":""},{"id":221,"question":"Theo Hồ Chí Minh, \"dân là chủ\" để đề cập đến điều gì?","options":["A. Đề cập tới vị trí của dân","B. Đề cập tới trách nhiệm của dân","C. Đề cập tới vị thế của dân","D. Đề cập tới năng lực của dân"],"answerLetter":"C","answerText":"C. Đề cập tới vị thế của dân","notes":""},{"id":222,"question":"Một trong những yêu cầu cơ bản trong nghiên cứu tư tưởng Hồ Chí Minh là:","options":["A. Đảm bảo thống nhất nguyên tắc tính Đảng và tính khoa học","B. Đảm bảo thống nhất nguyên tắc tính Nhà nước và tính khoa học","C. Đảm bảo thống nhất nguyên tắc tính Đảng và tính Nhà nước","D. Đảm bảo thống nhất nguyên tắc tính triết học và tính khoa học"],"answerLetter":"A","answerText":"A. Đảm bảo thống nhất nguyên tắc tính Đảng và tính khoa học","notes":"(Kiểu hỏi khác: Một trong những yêu cầu cơ bản trong nghiên cứu tư tưởng Hồ Chí Minh là:A. Đảm bảo thống nhất giữ nguyên tắc tính đảng và tính khoa họcB. Đảm bảo thống nhất tính thực chứng và duy lýC. Đảm bảo thống nhất giữa khoa học và thực tiễnD. Đảm bảo tỉnh thực chứng và khoa học)"},{"id":223,"question":"Ngoại ngữ nào sau đây được Hồ Chí Minh học đầu tiên?","options":["A. Tiếng Anh","B. Tiếng Pháp","C. Tiếng Trung","D. Tiếng Nga"],"answerLetter":"B","answerText":"B. Tiếng Pháp","notes":"(Tiếng Pháp là ngoại ngữ mà Bác Hồ được học đầu tiên, trên cả hai phương diện học chữ và học nói, còn tiếng Trung khi nhỏ tuổi thì Bác chỉ được học chữ chứ không được học nói.)"},{"id":224,"question":"Chủ nghĩa nào sau đây ảnh hưởng đến sự hình thành tư tưởng Hồ Chí Minh?","options":["A. Chủ nghĩa dân tộc của Grady.","B. Chủ nghĩa dân chủ của Kenedy.","C. Chủ nghĩa tam dân của Tôn Trung Sơn."],"answerLetter":"C","answerText":"C. Chủ nghĩa tam dân của Tôn Trung Sơn.","notes":""},{"id":225,"question":"Trong những câu nói sau đây, câu nào không phải là của Hồ Chí Minh?","options":["A. Muốn được dân yêu, muốn được lòng dân, trước hết phải yêu dân, phải đặt quyền lợi của dân trên hết thảy, phải có một tinh thần chí công vô tư\".","B. Chúng ta đã xây dựng nên nước Việt Nam Dân chủ Cộng hòa. Nhưng nếu nước độc lập mà dân không được hưởng hạnh phúc tự do, thì độc lập cũng chẳng có nghĩa lý gì\".","C. Chính phủ nhân dân bao giờ cũng phải đặt quyền lợi của dân lên trên hết thảy. Việc gì có lợi cho dân thì phải hết sức làm. Việc gì hại đến dẫn thì phải hết sức tránh\".","D. Khoan thư sức dân làm kế sâu rễ bền gốc\"."],"answerLetter":"D","answerText":"D. Khoan thư sức dân làm kế sâu rễ bền gốc\".","notes":""},{"id":226,"question":"Theo Hồ Chí Minh, vấn đề cốt lõi của cách mạng giải phóng dân tộc thuộc địa là","options":["A. Vấn đề tự do dân chủ","B. Vấn đề độc lập dân tộc","C. Vấn đề ruộng đất"],"answerLetter":"B","answerText":"B. Vấn đề độc lập dân tộc","notes":""},{"id":227,"question":"Câu nói \"Đảng là đạo đức, đảng là văn minh\" được chủ tịch Hồ Chí minh đưa ra ở:","options":["A. Di chúc - 1969","B. Diễn văn kỷ niệm 30 năm thành lập Đảng 1960","C. Diễn văn khai mạc đại hội đại biểu toàn quốc lần thứ II tháng 2 - 1962","D. Diễn văn khai mạc đại hội đại biểu toàn quốc lần thứ III của Đảng năm 1960"],"answerLetter":"B","answerText":"B. Diễn văn kỷ niệm 30 năm thành lập Đảng 1960","notes":""},{"id":228,"question":"Theo Hồ Chí Minh, mâu thuẫn chủ yếu ở thuộc địa, không thể điều hòa được là gì.","options":["A. Mâu thuẫn giữa dân tộc thuộc địa với thực dân, đế quốc","B. Mâu thuẫn giữa giai cấp công nhân với chủ nghĩa thực dân","C. Mâu thuẫn giữa giai cấp nông dân với giai cấp địa chủ bản xứ","D. Tất cả các phương án trên"],"answerLetter":"A","answerText":"A. Mâu thuẫn giữa dân tộc thuộc địa với thực dân, đế quốc","notes":""},{"id":229,"question":"Theo Hồ Chí Minh, mối quan hệ giữa văn hóa với kinh tế và chính trị như thế nào?","options":["A. Văn hóa đứng ngoài kinh tế","B. Văn hóa đứng người chính trị","C. Văn hóa không thể đứng ngoài mà phải ở trong kinh tế và chính trị","D. Văn hóa đứng ngoài kinh tế và chính trị"],"answerLetter":"C","answerText":"C. Văn hóa không thể đứng ngoài mà phải ở trong kinh tế và chính trị","notes":""},{"id":230,"question":"Chọn đáp án đúng nhất: Phải kết hợp nhuần nhuyễn dân tộc với giai cấp, độc lập dân tộc và chủ nghĩa xã hội, chủ nghĩa yêu nước với chủ nghĩa quốc tế là nội dung gì trong tư tưởng Hồ Chí Minh:","options":["A. Tư tưởng Hồ Chí Minh về vấn đề dân tộc","B. Tư tưởng Hồ Chí Minh về vấn đề giai cấp","C. Tư tưởng Hồ Chí Minh về đoàn kết quốc tế","D. Tư tưởng Hồ Chí Minh về chủ nghĩa xã hội"],"answerLetter":"A","answerText":"A. Tư tưởng Hồ Chí Minh về vấn đề dân tộc","notes":""},{"id":231,"question":"Trong bản Yêu sách của nhân dân An Nam, Hồ Chí Minh nhấn mạnh quốc gia cần phải có một:","options":["A. Chế độ dân chủ","B. Chế độ ra các đạo luật","C. Chế độ công bằng","D. Chế độ ra sắc lệnh"],"answerLetter":"B","answerText":"B. Chế độ ra các đạo luật","notes":""},{"id":232,"question":"Hãy chọn phương án đúng nhất. Theo Hồ Chí Minh, mục đích cơ bản của đoàn kết quốc tế là","options":["A. Tạo sức mạnh tổng hợp cho cách mạng Việt Nam và góp phần cùng với nhân dẫn thế giới thực hiện thắng lợi các mục tiêu cách mạng","B. Hợp tác giáo dục và giao lưu văn hóa","C. Tranh thủ sự viện trợ của các nước bên ngoài","D. Học hỏi và trao đổi kinh nghiệm sản xuất"],"answerLetter":"A","answerText":"A. Tạo sức mạnh tổng hợp cho cách mạng Việt Nam và góp phần cùng với nhân dẫn thế giới thực hiện thắng lợi các mục tiêu cách mạng","notes":""},{"id":233,"question":"Tác phẩm Đời sống mới được Hồ Chí Minh công bố năm nào?","options":["A. 1930","B. 1947","C. 1951","D. 1945"],"answerLetter":"B","answerText":"B. 1947","notes":""},{"id":234,"question":"Theo Hồ Chí Minh, chủ nghĩa nào có \"những điều thích hợp với điều kiện của nước ta\"?","options":["A. Chủ nghĩa Găngđi","B. Chủ nghĩa Mác","C. Chủ nghĩa Tôn Dật Tiên","D. Chủ nghĩa Lênin"],"answerLetter":"C","answerText":"C. Chủ nghĩa Tôn Dật Tiên","notes":""},{"id":235,"question":"Đâu là quan điểm của Hồ Chí Minh trong các quan điểm sau?","options":["A. Trong giai đoạn thuộc địa, giải phóng chính trị- Xã hội là trước hết, mỡ đường để giải phóng văn hóa","B. Trong giai đoạn thuộc địa, giải phóng chính trị - xã hội là trước hết, mở đường để giải phóng nhân loạ","C. Trong giai đoạn thuộc địa, giài phóng chính trị- xã hội là trước hết, mở đường để giải phóng dân tộc","D. Trong giai đoạn thuộc địa, giải phóng chính trị - xã hội là trước hết, mở đường để giải phóng các dân tộc anh em"],"answerLetter":"A","answerText":"A. Trong giai đoạn thuộc địa, giải phóng chính trị- Xã hội là trước hết, mỡ đường để giải phóng văn hóa","notes":""},{"id":236,"question":"Hồ Chí Minh lưu ý trong công tác xây dựng mặt trận như sau.","options":["A. Khối đoàn kết trong Mặt trận phải xuất phát từ mục tiêu cụ thể","B. Khối đoàn kết trong Mặt trận phải xuất phát từ mục tiêu cơ bản","C. Khối đoàn kết trong Mặt trận phải xuất phát từ mục tiêu chung"],"answerLetter":"C","answerText":"C. Khối đoàn kết trong Mặt trận phải xuất phát từ mục tiêu chung","notes":""},{"id":237,"question":"Hồ Chí Minh cho rằng đoàn kết toàn dân để:","options":["A. Phụng sự nhân dân","B. Phụng sự cách mạng","C. Phụng sự tổ quốc"],"answerLetter":"C","answerText":"C. Phụng sự tổ quốc","notes":""},{"id":238,"question":"Theo Hồ Chí Minh, lực lượng nào sau đây được coi \"là gốc cách mệnh\"?","options":["A. Công nông trí","B. Công nhân","C. Công nông","D. Nông dân"],"answerLetter":"C","answerText":"C. Công nông","notes":""},{"id":239,"question":"Theo quan điểm của Đảng Cộng sản Việt Nam tại Đại hội đại biểu toàn quốc lần thứ VII, Tư tưởng Hồ Chí Minh là:","options":["A. Tài sản tinh thần to lớn của Đảng và dân tộc ta","B. Tài sản tinh thần quý báu của Đảng và của cả dân tộc","C. Tài sản tinh thần vô cùng to lớn và quý giá của Đảng và dân tộc ta","D. Tài sản tinh thần to lớn và vô cùng quý giá của Đảng và dân tộc ta"],"answerLetter":"B","answerText":"B. Tài sản tinh thần quý báu của Đảng và của cả dân tộc","notes":""},{"id":240,"question":"Tư tưởng tôn giáo nào sau đây ảnh hưởng đến sự hình thành tư tưởng Hồ Chí Minh?","options":["A. Tư duy, hành động, ứng xử của Phật giáo","B. Tư duy, hành động, ứng xử của Hồi giáo","C. Tư duy, hành động, ứng xử của Ấn độ giáo"],"answerLetter":"A","answerText":"A. Tư duy, hành động, ứng xử của Phật giáo","notes":""},{"id":241,"question":"Hồ Chí Minh nhấn mạnh xây dựng nhà nước trong sạch vững mạnh cần phải","options":["A. Kết hợp giáo dục pháp luật và đạo đức, hình thành pháp quyền nhân nghĩa","B. Kết hợp giáo dục pháp luật và nghề nghiệp, hình thành pháp quyền nhân nghĩa","C. Kết hợp giáo dục pháp luật và nhân cách, hình thành pháp quyền nhân nghĩa"],"answerLetter":"A","answerText":"A. Kết hợp giáo dục pháp luật và đạo đức, hình thành pháp quyền nhân nghĩa","notes":""},{"id":242,"question":"Theo Hồ Chí Minh, Liêm là luôn tôn trọng của công và của dân. Phải:","options":["A. trong sạch, không tham lam\" tiền của, địa vị, danh tiếng.","B. trong sáng, không tham lam\" tiền của, địa vị, danh tiếng.","C. trong sạch, không ham muốn\" tiền của, địa vị, danh tiếng.","D. trong sạch, không đòi hỏi\" tiền của, địa vị, danh tiếng."],"answerLetter":"A","answerText":"A. trong sạch, không tham lam\" tiền của, địa vị, danh tiếng.","notes":""},{"id":243,"question":"Theo tư tưởng Hồ Chí Minh, con người mới xã hội chủ nghĩa là con người.","options":["A. Kế thừa những giá trị tốt đẹp của con người truyền thống","B. Phá bỏ những truyền thống cũ","C. Hình thành những phẩm chất mới xã hội chủ nghĩa","D. Kế thừa những giá trị tốt đẹp của con người truyền thống hình thành những phẩm chất mới xã hội chủ nghĩa"],"answerLetter":"D","answerText":"D. Kế thừa những giá trị tốt đẹp của con người truyền thống hình thành những phẩm chất mới xã hội chủ nghĩa","notes":""},{"id":244,"question":"Hồ Chí Minh tiếp thu tư tưởng về đạo đức của Nho giáo trong việc xây dựng, đổi mới, phát triển, đạo đức trong công tác gì?","options":["A. Xây dựng con người mới","B. Xây dựng Đảng về đạo đức","C. Xây dựng văn hóa mới","D. Xây dựng xã hội mới"],"answerLetter":"B","answerText":"B. Xây dựng Đảng về đạo đức","notes":""},{"id":245,"question":"Theo Hồ Chí Minh, là người đày tớ của dân không có nghĩa là \"tôi tớ, tôi đòi hay theo đuôi quần chúng\" mà là:","options":["A. Hiểu và đánh giá đúng nhân dân nhằm đem lại các quyền và lợi ích cho nhân dân.","B. Tận tâm, tận lực phụng sự nhân dân nhằm đem lại các quyền và lợi ích cho nhân dân.","C. Tất cả các phương án"],"answerLetter":"B","answerText":"B. Tận tâm, tận lực phụng sự nhân dân nhằm đem lại các quyền và lợi ích cho nhân dân.","notes":""},{"id":246,"question":"Chọn câu trả lời đúng và đầy đủ nhất theo tư tưởng Hồ Chí Minh :","options":["A. Đảng Cộng sản Việt Nam vừa là thành viên, vừa là lực lượng lãnh đạo Mặt trận","B. Đảng Cộng sản Việt Nam là một thành viên của Mặt trận dân tộc thống nhất","C. Đảng Cộng sản Việt Nam không là thành viên của Mặt trận dân tộc thống nhất","D. Đảng Cộng sản Việt Nam là lực lượng lãnh đạo Mặt trận"],"answerLetter":"A","answerText":"A. Đảng Cộng sản Việt Nam vừa là thành viên, vừa là lực lượng lãnh đạo Mặt trận","notes":""},{"id":247,"question":"Nguyễn Ái Quốc vào Đảng Xã hội Pháp năm nào?","options":["A. 1917","B. 1918","C. 1919","D. 1920"],"answerLetter":"C","answerText":"C. 1919","notes":""},{"id":248,"question":"Khi nói về điều kiện hình thành tư tưởng Hồ Chí Minh, điều kiện nào bị viết sai?","options":["A. Ngay từ khi còn nhỏ ở trong trưởng. Hồ Chí Minh đã nhận thức được đặc điểm thời đại","B. Quê hương Hồ Chí Minh là mảnh đất giàu truyền thống yêu nước, chống giặc ngoại xâm","C. Nhu cầu khách quan và bức thiết do cách mạng Việt Nam đặt ra là muốn cứu nước, phải tìm một con đường cách mạng mới","D. Hồ Chí Minh sinh ra trong một gia đình nhà Nho yêu nước. gần gũi nhân dân, cụ thân sinh có tư tưởng thương dân, chủ trương lấy dân làm hậu thuẫn cho mọi cải cách chính trị"],"answerLetter":"A","answerText":"A. Ngay từ khi còn nhỏ ở trong trưởng. Hồ Chí Minh đã nhận thức được đặc điểm thời đại","notes":""},{"id":249,"question":"Theo Hồ Chí Minh, đạo đức mới chỉ có thể được xây dựng trên cơ sở sự tự giác tu dưỡng đạo đức của mỗi người thông qua hoạt động thực tiễn, phải kiên trì rèn luyện như:","options":["A. việc rửa mặt hàng ngày.","B. việ","C. đánh răng hàng ngày.c. việc ăn uống hàng ngày","D. việc hít thở hàng ngày"],"answerLetter":"A","answerText":"A. việc rửa mặt hàng ngày.","notes":""},{"id":250,"question":"Hồ Chí Minh cho rằng, nhà nước của dân, do dân và vì dân phải","options":["A. Là nhà nước hợp hiến","B. Là nhà nước dân chủ","C. Là nhà nước dân quyền"],"answerLetter":"B","answerText":"B. Là nhà nước dân chủ","notes":""},{"id":251,"question":"Hồ Chí Minh cho rằng, nhà nước của dân, do dân và vì dân phải","options":["A. Do ĐCS lãnh đạo và nhân dân làm chủ","B. Do nhân dân quản lý và nhân dân làm chủ","C. Do giai cấp công nhân lãnh đạo và nhân dân làm chủ"],"answerLetter":"A","answerText":"A. Do ĐCS lãnh đạo và nhân dân làm chủ","notes":""},{"id":252,"question":"Hồ Chí Minh cho rằng, nhà nước của dân, do dân và vì dân phải","options":["A. Có hiệu lực pháp lý mạnh mẽ","B. Có hiệu lực pháp lý toàn diện","C. Có hiệu lực pháp lý chân chính"],"answerLetter":"A","answerText":"A. Có hiệu lực pháp lý mạnh mẽ","notes":""},{"id":253,"question":"Hồ Chí Minh cho rằng, nhà nước của dân, do dân và vì dân phải mang bản chất","options":["A. Giai cấp công nhân và mang bản chất dân tộc","B. Giai cấp công nhân và mang bản chất nhân văn","C. Giai cấp công nhân và mang bản chất nhân đạo"],"answerLetter":"A","answerText":"A. Giai cấp công nhân và mang bản chất dân tộc","notes":""},{"id":254,"question":"Nội dung nào không đúng với tư tưởng Hồ Chí Minh trong việc thực thi Hiến pháp và pháp luật?","options":["A. Pháp luật phải đúng và phải đủ","B. Tăng cường tuyên truyền, giáo dục pháp luật cho người cao tuổi","C. Người thực thi luật pháp phải thật sự công tâm và nghiêm minh","D. Bất kỳ ai vi phạm pháp luật cũng đều bị trừng trị nghiêm khắc, đúng người, đúng tội."],"answerLetter":"B","answerText":"B. Tăng cường tuyên truyền, giáo dục pháp luật cho người cao tuổi","notes":""},{"id":255,"question":"Đâu không phải là nguyên tắc xây dựng chủ nghĩa xã hội trong thời kỳ quá độ theo tư tưởng hồ chí minh?","options":["A. Mọi tư tưởng hành động phải tuân thủ tuyệt đối theo chủ nghĩa Mác - Lênin","B. Phải giữ vững được độc lập dân tộc","C. Phải đoàn kết, học tập kinh nghiệm từ thực tiễn","D. Xây đi đôi với chống"],"answerLetter":"A","answerText":"A. Mọi tư tưởng hành động phải tuân thủ tuyệt đối theo chủ nghĩa Mác - Lênin","notes":""},{"id":256,"question":"Luận điểm nào là củ","options":["A. Hồ Chí Minh?a. Hãy xóa bỏ tình trạng người bóc lột người thì tình trạng dân tộc này bóc lột dân tộc khác sẽ bị xóa bỏ.","B. Khi mà sự đối kháng giữa các giai cấp trong nội bộ dân tộc không còn nữa thì sự thù địch giữa các dân tộc cũng đồng thời mất theo.","C. Giải phóng giai cấp là nhiệm vụ trung tâm, là điều kiện để giải phóng dân tộc.","D. Trong điều kiện các nước thuộc địa thì giải phóng dân tộc là cơ sở để giải phóng giai cấp, giải phóng con người."],"answerLetter":"D","answerText":"D. Trong điều kiện các nước thuộc địa thì giải phóng dân tộc là cơ sở để giải phóng giai cấp, giải phóng con người.","notes":"(Kiểu hỏi khác: Đâu là luận điểm của Hồ Chí Minh?\nA. Hãy xóa bỏ tình trạng người bóc lột người thì tình trạng dẫn tộc này bóc lột dẫn tộc khác sẽ bị xóa\nB. Khi mà sự đối kháng giữa các giai cấp trong nội bộ dân tộc không còn nữa thì sự thù địch giữa các dân tộc cũng đồng thời mất theo.\nC. Giải phóng dân tộc gắn với giải phóng giai cấp, trong đó giải phóng dân tộc là trước hết, trên hết\nD. Giải phóng giai cấp là nhiệm vụ hàng đầu, là điêu kiện tiên quyết trong giãi phóng dẫn tộc.)"},{"id":257,"question":"Trong các quan điểm dưới đây, đâu là quan điểm của Hồ Chí Minh?","options":["A. Văn hóa ngang hàng với các lĩnh vực khác, có mỗi quan hệ với các lĩnh vực khác","B. Văn hóá không như lĩnh vực khác, có mỗi quan hệ với các lĩnh vực khác","C. Văn hoa là mọi lĩnh vực có môi quan hệ ngang hàng","D. Văn hóa ngang hàng với các lĩnh vực khác, không có mỗi quan hệ với các lĩnh vực khác"],"answerLetter":"A","answerText":"A. Văn hóa ngang hàng với các lĩnh vực khác, có mỗi quan hệ với các lĩnh vực khác","notes":""},{"id":258,"question":"Hồ Chí Minh cho rằng đoàn kết là","options":["A. Sức mạnh","B. Sáng tạo","C. Khôn ngoan"],"answerLetter":"A","answerText":"A. Sức mạnh","notes":""},{"id":259,"question":"Tác phẩm \"Cần Kiêm Liêm Chính\" của Hồ Chí Minh được xuất bản vào thời gian nào?","options":["A. Năm 1950","B. Năm 1947","C. Năm 1949","D. Năm 1948"],"answerLetter":"C","answerText":"C. Năm 1949","notes":""},{"id":260,"question":"Theo Hồ Chí Minh, nhà nước vì dân là","options":["A. Nhà nước phải phụng sự nhân dân","B. Nhà nước phải phụng sự Đảng Cộng sản","C. Nhà nước phải phụng sự giai cấp cầm quyền"],"answerLetter":"A","answerText":"A. Nhà nước phải phụng sự nhân dân","notes":""},{"id":261,"question":"Hồ Chí Minh lưu ý Đảng về vấn đề đại đoàn kết dân tộc thông qua luận điểm","options":["A. Đoàn kết không chỉ nằm ở chủ trương, đường lối, chính sách mà phải biến thành sức mạnh","B. Đoàn kết không chỉ nằm ở chủ trương, đường lối, chính sách mà phải biến thành tư tưởng","C. Đoàn kết không chỉ nằm ở chủ trương, đường lối, chính sách mà phải biến thành đường lối"],"answerLetter":"A","answerText":"A. Đoàn kết không chỉ nằm ở chủ trương, đường lối, chính sách mà phải biến thành sức mạnh","notes":""},{"id":262,"question":"Chế độ xã hội dưới sự lãnh đạo của Đảng Cộng sản và giai cấp công nhân, đánh đổ đế quốc và phong kiến,trên nền tảng công nông liên minh, nhân dân lao động làm chủ, nhân dân dân chủ chuyền chính theo tư tưởngMác - Lênin, theo Hồ Chí Minh đó là:","options":["A. Chế độ chuyên chính vô sản","B. Chế độ dân chủ nhân dân","C. Chế độ dân chủ xã hội chủ nghĩa","D. Chế độ dân chủ mới"],"answerLetter":"C","answerText":"C. Chế độ dân chủ xã hội chủ nghĩa","notes":""},{"id":263,"question":"Giai đoạn nào sau đây tư tưởng Hồ Chí Minh tiếp tục phát triển, hoàn thiện?","options":["A. 1945 đến 1960","B. 1930 đến 1969","C. 1945 đến 1969","D. 1930 đến 1945"],"answerLetter":"C","answerText":"C. 1945 đến 1969","notes":"(Kiểu hỏi khác: Giai đoạn nào sau đây Hồ Chí Minh bổ sung và hoàn thiện tư tưởng của mình?A. 1911 đến 1920B. 1930 đến 1969C. 1941 đến 1969D. 1921 đến 1930)"},{"id":264,"question":"Giai đoạn nào sau đây hình thành tư tưởng yêu nước và ý chí cứu nước củ","options":["A. Hồ Chí Minh?a. 1911 đến 1920","B. 1921 đến 1930","C. 1930 đến 1945","D. 1890 đến 1911"],"answerLetter":"D","answerText":"D. 1890 đến 1911","notes":""},{"id":265,"question":"Giai đoạn nào sau đây Hồ Chí Minh vượt qua thử thách, kiên trì giữ vững lập trường cách mạng?","options":["A. 1911 đến 1920","B. 1921 đến 1930","C. 1930 đến 1945","D. 1890 đến 1911"],"answerLetter":"C","answerText":"C. 1930 đến 1945","notes":""},{"id":266,"question":"Giai đoạn nào sau đây hình thành cơ bản tư tưởng Hồ Chí Minh về cách mạng Việt Nam?","options":["A. 1945 đến 1969","B. 1930 đến 1945","C. 1921 đến 1930","D. 1911 đến 1920"],"answerLetter":"C","answerText":"C. 1921 đến 1930","notes":""},{"id":267,"question":"Theo tư tưởng Hồ Chí Minh, độc lập, tự do được hiểu là","options":["A. Quyền bất khả xâm phạm của tất cả các dân tộc","B. Quyền thiêng liêng và bất khả xâm phạm của tất cả các dân tộc","C. Quyền thiêng liêng của tất cả các dân tộc","D. Đặc quyền của mỗi một dân tộc"],"answerLetter":"B","answerText":"B. Quyền thiêng liêng và bất khả xâm phạm của tất cả các dân tộc","notes":""},{"id":268,"question":"Chọn phương án đúng nhất. Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam là","options":["A. Đảng của giai cấp công nhân, đồng thời là đảng của dân tộc Việt Nam","B. Đông của giai cấp công nhân và nông dân Việt Nam","C. Đảng của giai cấp công nhân Đông Dương","D. Đảng của giai cấp công nhân Việt Nam"],"answerLetter":"A","answerText":"A. Đảng của giai cấp công nhân, đồng thời là đảng của dân tộc Việt Nam","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, Đảng Lao động Việt Nam là Đảng của ai?)"},{"id":269,"question":"Trong tư tưởng Hồ Chí Minh, lực lượng nào là chủ thể của khối đại đoàn kết dân tộc?","options":["A. Công nhân","B. Toàn thể nhân dân","C. Nhân dân","D. Không xác định lực lượng chủ thể"],"answerLetter":"B","answerText":"B. Toàn thể nhân dân","notes":"(Kiểu hỏi khác: Trong tư tưởng Hồ Chí Minh, lực lượng nào là chủ thể của khối đại đoàn kết dân tộc?\nA. Công nhân\nB. Công - nông\nC. Nhân dân\nD. Không xác định lực lượng chủ thể)"},{"id":270,"question":"Theo Hồ Chí Minh, đoàn kết là","options":["A. Truyền thống quý báu của dân tộc ta","B. Sức mạnh vô địch của dân tộc ta","C. Ý chí tự lực, tự cường của dân tộc ta"],"answerLetter":"A","answerText":"A. Truyền thống quý báu của dân tộc ta","notes":""},{"id":271,"question":"Hồ Chí Minh cho rằng giải phóng dân tộc là sự nghiệp của","options":["A. Toàn dân","B. Toàn quân","C. Toàn Đảng","D. Giai cấp công nhân"],"answerLetter":"A","answerText":"A. Toàn dân","notes":""},{"id":272,"question":"Hồ Chí Minh cho rằng giải phóng dân tộc là nhiệm vụ của cách mạng nào sau đây","options":["A. Cách mạng nhân sinh tự do","B. Cách mạng dân chủ tư sản","C. Cách mạng XHCN"],"answerLetter":"C","answerText":"C. Cách mạng XHCN","notes":""},{"id":273,"question":"\"Đại đoàn kết tức là trước hết phải đoàn kết đại đa số nhân dân, mà đại đa số nhân dân ta là công nhân, nông dân và các tầng lớp nhân dân lao động khác. Đó là nền, gốc của đại đoàn kết. Đây là câu nói của Hồ Chí Minh trong bài Nói chuyện tại Hội nghị đại biểu Mặt trận Liên - Việt toàn quốc vào tháng, năm nào?","options":["A. Tháng 3-1951","B. Tháng 9-1945","C. Tháng 2, 1960","D. Tháng 1-1955"],"answerLetter":"D","answerText":"D. Tháng 1-1955","notes":""},{"id":274,"question":"Tư tưởng, văn hóa phương Tây lấy.","options":["A. Cảm tính và khoa học làm tiêu chuẩn","B. Lý tính và khoa học là tiêu chuẩn","C. Tư duy và sự phản biện làm tiêu chuẩn","D. Sự phản biện và lý tính làm tiêu chuẩn"],"answerLetter":"B","answerText":"B. Lý tính và khoa học là tiêu chuẩn","notes":""},{"id":275,"question":"Hồ Chí Minh nhấn mạnh tầm quan trọng của mặt trận như sau","options":["A. Mặt trận là khối đoàn kết chặt chẽ, lâu dài, thật sự, chân thành","B. Mặt trận là khối đoàn kết chặt chẽ, lâu dài, thật sự, chân chính","C. Mặt trận là khối đoàn kết chặt chẽ, lâu dài, thật sự, chân thực"],"answerLetter":"A","answerText":"A. Mặt trận là khối đoàn kết chặt chẽ, lâu dài, thật sự, chân thành","notes":""},{"id":276,"question":"Theo tư tưởng Hồ Chí Minh, luận điểm Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp giữa chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước là:","options":["A. Xác định nhiệm vụ của Đảng.","B. Xác định bản chất của Đảng.","C. Xác định nguồn gốc ra đời của Đảng.","D. Xác định năng lực của Đảng."],"answerLetter":"C","answerText":"C. Xác định nguồn gốc ra đời của Đảng.","notes":""},{"id":277,"question":"Hồ Chí Minh ví tham nhũng như giặc","options":["A. Ngoại xâm","B. Mỹ","C. Nội xâm"],"answerLetter":"C","answerText":"C. Nội xâm","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, tham ô, lãng phí được ví như giặc gì?\nA. Ngoại xâm\nB. Nội xâm\nC. Mỹ\nD. Giặc dốt)"},{"id":278,"question":"Theo Hồ Chí Minh, cách mạng XHCN phải tiến hành đồng thời với cách mạng nào?","options":["A. Cách mạng tư sản","B. Cách mạng dân tộc dân chủ nhân dân","C. Cách mạng văn hóa","D. Cách mạng giai cấp"],"answerLetter":"B","answerText":"B. Cách mạng dân tộc dân chủ nhân dân","notes":""},{"id":279,"question":"Hồ Chính Minh cho rằng cứ viết lên trán hai chữ cộng sản là","options":["A. Dân yêu dân mến","B. Dân khâm phục","C. Dân tin"],"answerLetter":"A","answerText":"A. Dân yêu dân mến","notes":""},{"id":280,"question":"Yếu tố nào sau đây ảnh hưởng đến sự hình thành tư tưởng Hồ Chí Minh:","options":["A. Lý luận và kinh nghiệm các cuộc cách mạng điển hình phương Tây","B. Kinh nghiệm các cuộc cách mạng điển hình ở phương Đông","C. Lý luận và thực tiễn các cuộc cách mạng điển hình trên thế giới","D. Bài học xương máu của cách mạng Việt Nam"],"answerLetter":"C","answerText":"C. Lý luận và thực tiễn các cuộc cách mạng điển hình trên thế giới","notes":""},{"id":281,"question":"Hồ Chí Minh nhắc cán bộ nhà nước phải biết","options":["A. Học tập từ nhân dân","B. Tự tôn dân tộc trước nhân dân","C. Quan cách trước nhân dân"],"answerLetter":"A","answerText":"A. Học tập từ nhân dân","notes":""},{"id":282,"question":"Hồ Chí Minh nhắc cán bộ nhà nước phải:","options":["A. Có mối liên hệ mật thiết với đại diện của nhân dân","B. Có mối liên hệ mật thiết với giai cấp mình","C. Có mối liên hệ mật thiết với chính quyền","D. Có mối liên hệ mật thiết với nhân dân"],"answerLetter":"D","answerText":"D. Có mối liên hệ mật thiết với nhân dân","notes":""},{"id":283,"question":"Hồ chí minh nhắc cán bộ nhà nước phải biết làm điều gì?","options":["A. làm lợi cho dân","B. lao động vì dân","C. phấn đấu vì dân","D. làm quan cách mạng"],"answerLetter":"A","answerText":"A. làm lợi cho dân","notes":""},{"id":284,"question":"Theo Hồ Chí Minh, quyền lãnh đạo Mặt trận của Đảng không phải do Đảng tự phong cho mình, mà phải được:","options":["A. Nhân dân bỏ phiếu.","B. Trưng cầu dân ý.","C. Nhân dân thừa nhận.","D. Chính quyền cho phép."],"answerLetter":"C","answerText":"C. Nhân dân thừa nhận.","notes":""},{"id":285,"question":"Đoạn viết dưới đây ghi tóm tắt lời giải thích của hồ chí minh về cần, kiệm, liêm, chính. hỏi: điểm tóm tắt nào đã bị ghi nhầm nội dung?","options":["A. Cần là lao động cần cù, siêng năng, lao động có kế hoạch, sáng tạo và có năng suất lao động cao...","B. Kiệm là không xa xỉ, không hoang phí, không bừa bãi...","C. Liêm là luôn tôn trọng của công và của dân, không tham tiền của, địa vị, danh tiếng.","D. Chính là trong sạch, không tham lam đồng xu, hạt thóc của nhà nước, của dân."],"answerLetter":"D","answerText":"D. Chính là trong sạch, không tham lam đồng xu, hạt thóc của nhà nước, của dân.","notes":""},{"id":286,"question":"Hãy chọn phương án trả lời đúng nhất. Theo Hồ Chí Minh, để tập hợp được mọi lực lượng vào khối đại đoàn kết toàn dân, cần phải:","options":["A. Có chính sách đúng đắn","B. Có phương pháp phù hợp với từng đối tượng","C. Vừa có chính sách đúng đắn, vừa có phương pháp phù hợp với từng đối tượng","D. Chăm lo đời sống vật chất và tinh thần cho nhân dân"],"answerLetter":"C","answerText":"C. Vừa có chính sách đúng đắn, vừa có phương pháp phù hợp với từng đối tượng","notes":""},{"id":287,"question":"Quan điểm nào sau đây là nguyên tắc đoàn kết quốc tế củ","options":["A. Hồ Chí Minha. Dựa vào sức mình là chính, ủng hộ sự giúp đỡ quốc tế, có nghĩa vụ quốc tế.","B. Dựa vào sức mình là chính, ủng hộ sự giúp đỡ quốc tế, có nghĩa của chính mình","C. Dựa vào sức mình là chính, ủng hộ sự giúp đỡ quốc tế, có nghĩa vụ chính quốc."],"answerLetter":"A","answerText":"A. Hồ Chí Minha. Dựa vào sức mình là chính, ủng hộ sự giúp đỡ quốc tế, có nghĩa vụ quốc tế.","notes":""},{"id":288,"question":"Mối quan hệ giữa vấn đề dân tộc và vấn đề giai cấp trong tư tưởng Hồ Chí Minh là:","options":["A. Dân tộc với giai cấp có quan hệ chặt chẽ với nhau.","B. Độc lập dân tộc gắn liền chủ nghĩa xã hội.","C. Giải phóng dân tộc là tiền đề để giải phóng giai cấp.","D. Tất cả các phương án"],"answerLetter":"D","answerText":"D. Tất cả các phương án","notes":""},{"id":289,"question":"Điền vào chỗ trống. \"Đại đoàn kết dân tộc là....của cách mạng\".","options":["A. Mục tiêu, nhiệm vụ","B. Chìa khóa, con đường","C. Chìa khóa","D. Biện pháp, phương hướng"],"answerLetter":"A","answerText":"A. Mục tiêu, nhiệm vụ","notes":"(Kiểu hỏi khác: Chọn phương án chính xác nhất điền vào chỗ trống. Đại đoàn kết dân tộc là một ...... hàng đầu của cách mạng Việt Nam\")"},{"id":290,"question":"Báo Le Paria (Người Cùng khổ) do Nguyễn Ái Quốc đồng sáng lập, ra số đầu tiên khi nào?","options":["A. 30/12/1920","B. 1/4/1921","C. 1/4/1922","D. 1/4/1923"],"answerLetter":"C","answerText":"C. 1/4/1922","notes":""},{"id":291,"question":"Hồ Chí Minh cho rằng:","options":["A. Đại đoàn kết dân tộc là vấn đề có ý nghĩa chiến lược, quyết định sự thành công của cách mạng","B. Đoàn kết dân tộc là vấn đề có ý nghĩa chiến lược tá","C. động trực tiếp đến sự thành công của cách mạngc. Đại đoàn kết toàn dân là vấn đề có ý nghĩa chiến lược, quyết định sự trưởng thành của cách mạng"],"answerLetter":"A","answerText":"A. Đại đoàn kết dân tộc là vấn đề có ý nghĩa chiến lược, quyết định sự thành công của cách mạng","notes":""},{"id":292,"question":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc cần tiến hành bằng:","options":["A. Con đường cách mạng bất bạo động","B. Con đường cách mạng bạo lực","C. Con đường cách mạng ôn hòa","D. Con đường cách mạng cải lương"],"answerLetter":"B","answerText":"B. Con đường cách mạng bạo lực","notes":""},{"id":293,"question":"Hồ Chí Minh chủ trương tiến hành:","options":["A. Cách mạng tư sản dân quyền trước cách mạng thổ địa","B. Cách mạng thổ địa trước cách mạng tư sản dân quyền","C. Tiến hành động thời cách mạng tư sản dân quyền với cách mạng xã hội chủ nghĩa"],"answerLetter":"A","answerText":"A. Cách mạng tư sản dân quyền trước cách mạng thổ địa","notes":""},{"id":294,"question":"Theo Hồ Chí Minh, về bước đi trong thời kỳ quá độ, chúng ta phải:","options":["A. Trải qua nhiều bước","B. Làm thật mau và rầm rộ","C. Làm nhanh và rầm rộ qua nhiều bước"],"answerLetter":"A","answerText":"A. Trải qua nhiều bước","notes":""},{"id":295,"question":"Theo Hồ Chí Minh, về bước đi trong thời kỳ quá độ, chúng ta phải:","options":["A. Theo bước đi của các nước xã hội chủ nghĩa.","B. Căn cứ vào đặc điểm lịch sử cụ thể của nước ta từ đó có bước đi phù hợp.","C. Căn cứ vào đặc điểm lịch sử cụ thể của nước ta từ đó có bước đi phù hợp, đi bước nào vững chắc bước ấy.","D. Bước đi chậm, mạnh, vững chắc."],"answerLetter":"C","answerText":"C. Căn cứ vào đặc điểm lịch sử cụ thể của nước ta từ đó có bước đi phù hợp, đi bước nào vững chắc bước ấy.","notes":""},{"id":296,"question":"Theo Hồ Chí Minh, nhân dân là","options":["A. Chủ thể của quyền lực","B. Khách thể của quyền lực","C. Nguồn gốc của quyền lực","D. Sức mạnh của quyền lựcb"],"answerLetter":"A","answerText":"A. Chủ thể của quyền lực","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, vai trò của nhân dân là gì?)"},{"id":297,"question":"Theo Hồ Chí Minh, trong những ngành kinh tế chủ yếu: công - nông - thương nghiệp, những ngành nào được coi là \"hai cái chân của nền kinh tế nước nhà\" ?","options":["A. Nông nghiệp và thương nghiệp","B. Nông nghiệp và công nghiệp nhẹ","C. Công nghiệp nặng và nông nghiệp","D. Công nghiệp và nông nghiệp"],"answerLetter":"D","answerText":"D. Công nghiệp và nông nghiệp","notes":""},{"id":298,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Nền kinh tế mà chúng ta xây dựng cần phải phát triển toàn diện các ngành, với những ngành chủ yếu là: công-nông-thương nghiệp; trong đó, (...........) là hai cái chân của nền kinh tế nước nhà\".","options":["A. Nông nghiệp và thương nghiệp","B. Nông nghiệp và công nghiệp nhẹ","C. Công nghiệp nặng và nông nghiệp","D. Công nghiệp và nông nghiệp"],"answerLetter":"D","answerText":"D. Công nghiệp và nông nghiệp","notes":""},{"id":299,"question":"Lực lượng nào vừa là thành viên của Mặt trận dân tộc thống nhất vừa là lực lượng lãnh đạo Mặt trận?","options":["A. Các tổ chức chính trị xã hội","B. Đảng cộng sản Việt Nam","C. Nhà nước cộng hòa xã hội chủ nghĩa Việt Nam","D. Quần chúng nhân dân"],"answerLetter":"B","answerText":"B. Đảng cộng sản Việt Nam","notes":""},{"id":300,"question":"Theo Hồ Chí Minh, nhân dân lao động làm chủ Nhà nước thì dẫn đến một hệ quả là nhân dân có quyền:","options":["A. Không chịu sự kiểm soát của Nhà nước","B. Kiểm soát Nhà nước","C. Không phải đóng thuế cho Nhà nước","D. Không phải tuân theo pháp luật"],"answerLetter":"B","answerText":"B. Kiểm soát Nhà nước","notes":""},{"id":301,"question":"Theo Hồ Chí Minh, một trong những đặc điểm của Nhà nước pháp quyền là","options":["A. Nguyên tắc cơ bản của Nhà nước là hiệp thương dân chủ","B. Nhà nước lãnh đạo nhân dân thực hiện các nhiệm vụ cách mạng","C. Sự lãnh đạo của Đảng đối với Nhà nước","D. Nhà nước hợp hiến, hợp pháp"],"answerLetter":"D","answerText":"D. Nhà nước hợp hiến, hợp pháp","notes":""},{"id":302,"question":"Hồ Chí Minh cho rằng:","options":["A. Chủ nghĩa dân tộc là động lực lớn của đất nước.","B. Chủ nghĩa dân tộc là khát khao lớn của đất nước.","C. Chủ nghĩa dân tộc là mục tiêu lớn của đất nước.","D. Chủ nghĩa dân tộc là chiến lược hàng đầu của cách mạng."],"answerLetter":"A","answerText":"A. Chủ nghĩa dân tộc là động lực lớn của đất nước.","notes":""},{"id":303,"question":"Hãy chọn phương án đúng nhất Hồ Chí Minh luôn nhấn mạnh việc thực hành dân chủ, mà trước hết là dân chủ:","options":["A. Trong nhân dân","B. Trong nội bộ Đảng","C. Trong Nhà nước","D. Trong giai cấp công nhân"],"answerLetter":"B","answerText":"B. Trong nội bộ Đảng","notes":""},{"id":304,"question":"Trong di chúc Hồ Chí Minh viết rằng","options":["A. Đảng phải có kế hoạch tốt để phát triển kinh tế, văn hóa","B. Đảng phải có kế hoạch tốt để phát triển kinh tế, chính trị","C. Đảng phải có kế hoạch tốt để phát triển kinh tế, xã hội","D. Đảng phải có lộ trình để phát triển các vấn đề xã hội cần thiết"],"answerLetter":"A","answerText":"A. Đảng phải có kế hoạch tốt để phát triển kinh tế, văn hóa","notes":"(Kiểu hỏi khác: Đầu là câu trà lời chính xác nhất trong tác phẩm Di Chúc của Chủ tịch Hồ Chí Minh?)"},{"id":305,"question":"Theo tư tưởng Hồ Chí Minh, Đảng Cộng Sản Việt Nam là Đảng cầm quyền, vì vậy, mỗi cán bộ đảng viên cần phải:","options":["A. Hết lòng phục vụ giai cấp công nhân","B. Ra sức học tập, trau dồi chuyên môn, trình độ","C. Thực hiện thấm nhuần đạo đức cách mạng, cần, kiệm, liêm, chính, chí công vô tư","D. Xây dựng khối đại đoàn kết dân tộc"],"answerLetter":"C","answerText":"C. Thực hiện thấm nhuần đạo đức cách mạng, cần, kiệm, liêm, chính, chí công vô tư","notes":"(Kiểu hỏi khác; Trong Di chúc, Người viết: \"Đảng ta là một Đàng cầm quyền. Mỗi đàng viên và cán bộ phải thật sự thấm nhuần.., thật sự cần kiệm liêm chính, chí công vô tư. Hãy điền từ còn thiếu vào dầu ...?\nA. Tư tường cách mạng\nB. Cách thức cách mạng\nC. Đạo đức cách mạng\nD. Phương pháp cách mạng)"},{"id":306,"question":"Điểm khác nhau trong tư tưởng và xây dựng nhà nước của Hồ Chí Minh và tiền nhân trong lịch sử","options":["A. Con đường cứu nước","B. Phương pháp cứu nước","C. Tinh thần yêu nước.","D. Tất cả phương án tiến"],"answerLetter":"A","answerText":"A. Con đường cứu nước","notes":""},{"id":307,"question":"Theo Hồ Chí Minh, đoàn kết là điểm nào sau đây?","options":["A. Điểm mẹ","B. Điểm quyết định","C. Điểm thắng lợi","D. Điểm ăn tiền"],"answerLetter":"A","answerText":"A. Điểm mẹ","notes":""},{"id":308,"question":"Chọn phương án đúng nhất theo tư tưởng Hồ Chí Minh. Chủ nghĩa thực dân là kẻ thù của","options":["A. Các dân tộc thuộc địa","B. Giai cấp công nhân","C. Giai cấp nông dân","D. Các dân tộc thuộc địa, giai cấp công nhân và nhân dân lao động toàn thế giới"],"answerLetter":"D","answerText":"D. Các dân tộc thuộc địa, giai cấp công nhân và nhân dân lao động toàn thế giới","notes":""},{"id":309,"question":"Theo Hồ Chí Minh, đại đoàn kết dân tộc phải luôn được nhận thức là vấn đề sống còn, quyết định:","options":["A. Lực lượng của cách mạng.","B. Thắng lợi của cách mạng.","C. Thành bại của cách mạng.","D. Đích đến của cách mạng"],"answerLetter":"C","answerText":"C. Thành bại của cách mạng.","notes":""},{"id":310,"question":"Theo Hồ Chí Minh, động lực chủ yếu để phát triển đất nước là gì?","options":["A. Sức mạnh đoàn kết của cả cộng đồng dân tộc","B. Sức mạnh của cá nhân con người","C. Sức mạnh thời đại","D. Vai trò lãnh đạo của Đảng"],"answerLetter":"A","answerText":"A. Sức mạnh đoàn kết của cả cộng đồng dân tộc","notes":""},{"id":311,"question":"Điền vào chỗ trống để hoàn thiện câu nói sau củ","options":["A. Hồ Chí Minh:\"Đối với nông dân, nông dân thật sự nắm (.........), nông dân phải được giải phóng.a. Ruộng đất","B. Xí nghiệp, hầm mỏ","C. Chính quyền","D. Đảng"],"answerLetter":"C","answerText":"C. Chính quyền","notes":""},{"id":312,"question":"Theo Hồ Chí Minh, việc gì có hại cho dân dù nhỏ mấy cũng cố gắng:","options":["A. Làm","B. Tránh","C. Học","D. Khắc phục"],"answerLetter":"B","answerText":"B. Tránh","notes":""},{"id":313,"question":"Hiến pháp năm 1959 đã tiếp tục khẳng định quan điểm gì trong tư tưởng Hồ Chí Minh?","options":["A. Bảo đảm dân quyền trong việc xác lập quyền lực của nhân dân.","B. Bảo đảm dân chủ trong việc xác lập quyền lực của nhân dân.","C. Bảo đảm dân chủ trong việc xác lập quyền lực của nhà nước.","D. Bảo đảm dân quyền trong việc xác lập quyền lực của chính quyền."],"answerLetter":"B","answerText":"B. Bảo đảm dân chủ trong việc xác lập quyền lực của nhân dân.","notes":""},{"id":314,"question":"Điền vào chỗ trống để hoàn thiện câu nói sau củ","options":["A. Hồ Chí Minh:\"Nước Việt Nam là một nước dân chủ cộng hoà, tất cả quyền bính trong nước là của toàn thể nhân dân Việt Nam, không phân biệt nòi giống, gái trai, giàu nghèo, giai cấp, tôn giáo; những việc quan hệ đến vận mệnh quốc gia sẽ đưa ra toàn (............) phúc quyết\"a. Quốc","B. Đảng","C. Dân","D. Quốc hội"],"answerLetter":"C","answerText":"C. Dân","notes":""},{"id":315,"question":"Theo Hồ Chí Minh, ưu điểm lớn nhất của học thuyết Khổng Tử là gì?","options":["A. Tinh thần hiếu học.","B. Quản lý xã hội bằng đạo đức.","C. Sự tu dưỡng đạo đức cá nhân."],"answerLetter":"C","answerText":"C. Sự tu dưỡng đạo đức cá nhân.","notes":""},{"id":316,"question":"Cách mạng giải phóng dân tộc muốn thắng lợi phải:","options":["A. Có tổ chức đoàn thể lãnh đạo.","B. Có Đảng của giai cấp công nhân lãnh đạo.","C. Có một cá nhân xuất sắc lãnh đạo.","D. Có một giai cấp lãnh đạo."],"answerLetter":"B","answerText":"B. Có Đảng của giai cấp công nhân lãnh đạo.","notes":""},{"id":317,"question":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc muốn thắng lợi phải do ai lãnh đạo?","options":["A. Đảng Cộng sản","B. Giai cấp công nhân","C. Giai cấp vô sản","D. Đảng của giai cấp tư sản"],"answerLetter":"A","answerText":"A. Đảng Cộng sản","notes":""},{"id":318,"question":"Theo Hồ Chí Minh, phải kiên quyết khắc phục kịp thời các phản động lực trong con người và tổ chức. Đó là:","options":["A. Chủ nghĩa cá nhân.","B. Chủ nghĩa vị kỷ","C. Phong cách tiểu tư sản","D. Phong cách tư sản"],"answerLetter":"A","answerText":"A. Chủ nghĩa cá nhân.","notes":""},{"id":319,"question":"Đâu là sự sáng tạo củ","options":["A. Hồ Chí Minh về chủ nghĩa xã hội ở Việt Nama. Sáng tạo trong cách thức đi lên xây dựng chủ nghĩa xã hội","B. Phương pháp bạo lực cách mạng","C. Lựa chọn con đường đi lên xây dựng chủ nghĩa xã hội","D. Phân tích đúng tình hình nước ta"],"answerLetter":"A","answerText":"A. Hồ Chí Minh về chủ nghĩa xã hội ở Việt Nama. Sáng tạo trong cách thức đi lên xây dựng chủ nghĩa xã hội","notes":""},{"id":320,"question":"Theo Hồ Chí Minh, để lãnh đạo Mặt trận, Đảng phải đi đúng đường lối quần chúng, không được:","options":["A. Vận động, giáo dục, thuyết phục, nêu gương, lấy lòng chân thành để đối xử, cảm hóa, khơi gợi tinh thần tự giác, tự nguyện.","B. Quan liêu, mệnh lệnh và gò ép.","C. Lấy quyền uy để thuyết phục mọi người đi theo."],"answerLetter":"B","answerText":"B. Quan liêu, mệnh lệnh và gò ép.","notes":""},{"id":321,"question":"Hồ Chí Minh vạch ra mâu thuẫn cơ bản của cách mạng dân tộc thuộc địa là","options":["A. Nhân dân với thực dân, phong kiến","B. Nhân dân với thực dân, địa chủ","C. Nhân dân với thực dân, đế quốc"],"answerLetter":"C","answerText":"C. Nhân dân với thực dân, đế quốc","notes":""},{"id":322,"question":"Nguyễn Tất Thành lấy tên là Nguyễn Ái Quốc vào thời gian nào?","options":["A. Khi Bác lên tàu từ bến Nhà Rồng năm 1911.","B. Khi Bác tham gia sáng lập Đảng cộng sản Pháp tại Đại hội Tua 12/1920.","C. Tại hội nghị Vécxay (Pháp) ngày 18/6/1919.","D. Khi Bác sang Liên Xô làm việc ở Ban phương Đông của Quốc tế Cộng sản tháng 6/1923."],"answerLetter":"C","answerText":"C. Tại hội nghị Vécxay (Pháp) ngày 18/6/1919.","notes":""},{"id":323,"question":"Quy luật ra đời của Đảng Cộng sản Việt Nam được Hồ Chí Minh vạch ra:","options":["A. Không khác với chủ nghĩa Mác-Lênin.","B. Trái ngược với chủ nghĩa Mác-Lênin.","C. Không liên quan đến chủ nghĩa Mác-Lênin.","D. Bổ sung vào kho tàng lý luận của chủ nghĩa Mác - Lênin."],"answerLetter":"D","answerText":"D. Bổ sung vào kho tàng lý luận của chủ nghĩa Mác - Lênin.","notes":""},{"id":324,"question":"Nguyễn Ái Quốc đọc \"Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc đị","options":["A. của Lênin vào thời gian nào?a. 7/1917","B. 7/1918","C. 7/1919","D. 7/1920"],"answerLetter":"D","answerText":"D. 7/1920","notes":""},{"id":325,"question":"Tư tưởng Hồ Chí Minh được hình thành và phát triển qua mấy giai đoạn?","options":["A. 3","B. 4","C. 5","D. 6"],"answerLetter":"C","answerText":"C. 5","notes":""},{"id":326,"question":"Để chuẩn bị thành lập Đảng Cộng sản Việt Nam, Nguyễn Ái Quốc đã từ Liên Xô về Trung Quốc năm nào?","options":["A. 1925","B. 1927","C. 1923","D. 1924"],"answerLetter":"D","answerText":"D. 1924","notes":""},{"id":327,"question":"\"Luận cương của V.I. Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao. Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta\" Nguyễn Ái Quốc nói câu ấy khi đang ở đâu?","options":["A. Anh","B. Trung Quốc","C. Pháp"],"answerLetter":"C","answerText":"C. Pháp","notes":""},{"id":328,"question":"Giá trị đạo đức nào sau đây ảnh hưởng chủ yếu đến sự hình thành tư tưởng Hồ Chí Minh?","options":["A. Đạo đức Thiên chúa giáo","B. Đạo đứ","C. Phật giáoc. Đạo đức Nho giáo"],"answerLetter":"C","answerText":"C. Phật giáoc. Đạo đức Nho giáo","notes":""},{"id":329,"question":"Nguyễn Ái Quốc đến Liên Xô lần đầu khi nào?","options":["A. 1921","B. 1922","C. 1923","D. 1924"],"answerLetter":"C","answerText":"C. 1923","notes":""},{"id":330,"question":"Hồ Chí Minh không thừa nhận bản thân mình là:","options":["A. Nhà khoa học","B. Nhà thơ","C. Nhà soạn nhac","D. Nhà chính trị chuyên nghiệp"],"answerLetter":"B","answerText":"B. Nhà thơ","notes":""},{"id":331,"question":"Nguyễn Tất Thành tham dự cuộc biểu tình chống thuế của nông dân tỉnh Thừ","options":["A. Thiên vào thời gian nào?a. 5/1905","B. 5/1906","C. 5/1908","D. 6/1911"],"answerLetter":"C","answerText":"C. 5/1908","notes":""},{"id":332,"question":"Nguồn gốc nào sau đây quyết định tư tưởng Hồ Chí Minh:","options":["A. Tư tưởng Tam dân của Tôn Trung Sơn","B. Tư tưởng của Khổng tử","C. Tư tưởng của chủ nghĩa Mác-Lênin","D. Tư tưởng của Giêsu"],"answerLetter":"C","answerText":"C. Tư tưởng của chủ nghĩa Mác-Lênin","notes":""},{"id":333,"question":"Người thầy giáo đầu tiên của Hồ Chí Minh là ai?","options":["A. Vương Thúc Quý","B. Phan Bội Châu","C. Nguyễn Sinh Sắc","D. Phan Châu Trình"],"answerLetter":"C","answerText":"C. Nguyễn Sinh Sắc","notes":""},{"id":334,"question":"Nguyễn Ái Quốc tham dự Đại hội Tua, tán thành Quốc tế 3, tham gia thành lập Đảng Cộng sản Pháp thời gian nào?","options":["A. 12/1921","B. 12/1918","C. 12/1919","D. 12/1920"],"answerLetter":"D","answerText":"D. 12/1920","notes":""},{"id":335,"question":"Theo Hồ Chí Minh, học chủ nghĩ","options":["A. Mác - Lênin nghĩa là gì?a. Học thuộc các luận điểm lý luận.","B. Để sống với nhau có tình, có nghĩa.","C. Để chứng tỏ trình độ lý luận.","D. Tất cả các phương án."],"answerLetter":"B","answerText":"B. Để sống với nhau có tình, có nghĩa.","notes":""},{"id":336,"question":"Tư tưởng Hồ Chí Minh được hình thành trong bối cảnh nào?","options":["A. Chủ nghĩa tư bản đang trong giai đoạn tự do cạnh tranh.","B. Chủ nghĩa tư bản từ giai đoạn tự do cạnh tranh sang giai đoạn độc quyền.","C. Chủ nghĩa tư bản đang trong giai đoạn hình thành.","D. Chủ nghĩa xã hội đang trong giai đoạn phát triển."],"answerLetter":"B","answerText":"B. Chủ nghĩa tư bản từ giai đoạn tự do cạnh tranh sang giai đoạn độc quyền.","notes":""},{"id":337,"question":"Một trong những quan điểm cơ bản nghiên cứu tư tưởng Hồ Chí Minh là:","options":["A. Quan điểm đồng nhất","B. Quan điểm lịch sử cụ thể","C. Quan điểm cách mạng","D. Quan điểm phát triển"],"answerLetter":"B","answerText":"B. Quan điểm lịch sử cụ thể","notes":""},{"id":338,"question":"Tư tưởng nào sau đây ảnh hưởng chủ yếu đến sự hình thành tư tưởng Hồ Chí Minh?","options":["A. Đức hy sinh của Hồi giáo","B. Đức hy sinh của Nho giáo","C. Đức hy sinh của Ấn độ giáo","D. Đức hy sinh của Thiên chúa giáo"],"answerLetter":"D","answerText":"D. Đức hy sinh của Thiên chúa giáo","notes":""},{"id":339,"question":"Quan điểm nào sau đây thuộc về một trong những cơ sở phương pháp luận khi nghiên cứu tư tưởng Hồ Chí Minh?","options":["A. Quan điểm toàn diện và hệ thống","B. Quan điểm khách quan và cụ thể","C. Quan điểm cách mạng và khoa học","D. Quan điểm toàn diện và cụ thể"],"answerLetter":"A","answerText":"A. Quan điểm toàn diện và hệ thống","notes":""},{"id":340,"question":"Nguyễn Tất Thành r","options":["A. đi tìm đường cứu nước tại bến cảng Nhà Rồng - Sài Gòn vào thời gian nào?a. 5/6/1911","B. 6/5/1911","C. 5/6/1910","D. 6/5/1912"],"answerLetter":"A","answerText":"A. đi tìm đường cứu nước tại bến cảng Nhà Rồng - Sài Gòn vào thời gian nào?a. 5/6/1911","notes":""},{"id":341,"question":"Một trong những tiền đề tư tưởng, lí luận dẫn đến sự hình thành tư tưởng Hồ Chí Minh là:","options":["A. Giá trị truyền thống dân tộc Việt Nam","B. Giá trị văn hiến dân tộ","C. Việt Namc. Giá trị tư tưởng dân tộc Việt Nam","D. Giá trị văn minh dân tộcViệt Nam"],"answerLetter":"A","answerText":"A. Giá trị truyền thống dân tộc Việt Nam","notes":""},{"id":342,"question":"Một trong những nguyên tắc phương pháp luận khi nghiên cứu tư tưởng Hồ Chí Minh là:","options":["A. Kết hợp nghiên cứu các tác phẩm với thực tiễn chỉ đạo cách mạng của Hồ Chí Minh.","B. Kết hợp nghiên cứu các tác phẩm với thực tiễn cách mạng thế giới.","C. Kết hợp nghiên cứu các tác phẩm với thực tiễn cách mạng Việt Nam.","D. Kết hợp thực tiễn cách mạng Việt Nam và cách mạng thế giới."],"answerLetter":"A","answerText":"A. Kết hợp nghiên cứu các tác phẩm với thực tiễn chỉ đạo cách mạng của Hồ Chí Minh.","notes":""},{"id":343,"question":"Một trong những truyền thống tốt đẹp của tư tưởng và văn hoá Việt Nam được Hồ Chí Minh tiếp thu để hình thành tư tưởng của mình là:","options":["A. Chủ nghĩa yêu nước Việt Nam.","B. Những mặt tích cực của Nho Giáo","C. Tư tưởng vị tha của Phật giáo","D. Tư tưởng bác ái của Thiên Chúa Giáo."],"answerLetter":"A","answerText":"A. Chủ nghĩa yêu nước Việt Nam.","notes":""},{"id":344,"question":"Tháng 7 năm 1920, Hồ Chí Minh đọc ... củ","options":["A. V.I.Lênin?a. Tác phẩm Làm gì.","B. Sơ thảo lần thứ nhất Luận cương về các vấn đề dân tộ","C. c. Sơ thảo lần thứ nhất những Luận cương về các vấn đề dân tộc và vấn đề thuộc địa","D. Tác phẩm Tuyên ngôn của Đảng Cộng sản"],"answerLetter":"C","answerText":"C. c. Sơ thảo lần thứ nhất những Luận cương về các vấn đề dân tộc và vấn đề thuộc địa","notes":""},{"id":345,"question":"Vấn đề dân tộc trong tư tưởng Hồ Chí Minh trong thời đại cách mạng vô sản là vấn đề:","options":["A. Vấn đề dân tộc chủ nghĩa","B. Vấn đề dân tộc thuộ","C. địac. Vấn đề dân tộc phương Đông","D. Vấn đề dân tộc nói chung"],"answerLetter":"B","answerText":"B. Vấn đề dân tộc thuộ","notes":""},{"id":346,"question":"Khi ở Pháp Hồ Chí Minh đã sử dụng vật dụng nào để sưởi ấm?","options":["A. Viên gạch","B. Hòn đá","C. Gối","D. Lò sưởi"],"answerLetter":"A","answerText":"A. Viên gạch","notes":""},{"id":347,"question":"Mục đích chính để Hồ Chí Minh muốn ra nước ngoài là gì?","options":["A. Xem nước Pháp và các nước khác làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","B. Xem nước Pháp và các nước khác học như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","C. Xem nước Pháp và các nước khác văn minh như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","D. Xem nước Pháp và các nước khác tiến bộ như thế"],"answerLetter":"A","answerText":"A. Xem nước Pháp và các nước khác làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","notes":""},{"id":348,"question":"Theo Hồ Chí Minh đối tượng cơ bản của cách mạng thuộc địa là ai?","options":["A. Thực dân, tay sai phản động","B. Thực dân, đế quốc","C. Thực dân, tư sản","D. Thực dân, phong kiến"],"answerLetter":"A","answerText":"A. Thực dân, tay sai phản động","notes":""},{"id":349,"question":"Theo Hồ Chí Minh, giải quyết vấn đề dân tộc luôn gắn với vấn đề :","options":["A. Xã hội","B. Người lao động","C. Giai cấp","D. Nông dân"],"answerLetter":"C","answerText":"C. Giai cấp","notes":""},{"id":350,"question":"Các luận điểm sau đây đều thể hiện tư tưởng dựa vào sức mình là chính. Luận điểm nào không phải của Hồ Chí Minh?","options":["A. Sự nghiệp giải phóng của giai cấp công nhân phải do bản thân giai cấp công nhân tự làm lấy.","B. Công cuộc giải phóng các dân tộc thuộc địa chỉ có thể thực hiện được bằng sự nỗ lực của bản thân các dân tộc đó.","C. Đem sức ta mà tự giải phóng cho ta."],"answerLetter":"A","answerText":"A. Sự nghiệp giải phóng của giai cấp công nhân phải do bản thân giai cấp công nhân tự làm lấy.","notes":""},{"id":351,"question":"Nguyễn Ái Quốc có tên là Hồ Chí Minh vào năm nào?","options":["A. Năm 1942","B. Năm 1941","C. Năm 1943","D. Năm 1940"],"answerLetter":"A","answerText":"A. Năm 1942","notes":""},{"id":352,"question":"Hồ Chí Minh bị quân Tưởng Giới Thạch bắt năm nào?","options":["A. Năm 1944","B. Năm 1942","C. Năm 1941"],"answerLetter":"B","answerText":"B. Năm 1942","notes":""},{"id":353,"question":"Thực chất vấn đề dân tộc thuộc địa trong tư tưởng Hồ Chí Minh là:","options":["A. Thực hiện quyền tự quyết đối với tất cả các dân tộc.","B. Đòi quyền tự do dân chủ tối thiểu cho nhân dân.","C. Đấu tranh giải phóng các dân tộc thuộc địa khỏi sự áp bức, thống trị của nước ngoài, giành độc lập dân tộc, thành lập nhà nước dân tộc độc lập và đưa đất nước phát triển theo xu thế của t"],"answerLetter":"C","answerText":"C. Đấu tranh giải phóng các dân tộc thuộc địa khỏi sự áp bức, thống trị của nước ngoài, giành độc lập dân tộc, thành lập nhà nước dân tộc độc lập và đưa đất nước phát triển theo xu thế của t","notes":""},{"id":354,"question":"Hồ Chí Minh hoạt động tại Thái Lan vào thời gian nào?","options":["A. 1933-1937","B. 1930-1931","C. 1932-1933","D. 1928-1929"],"answerLetter":"D","answerText":"D. 1928-1929","notes":""},{"id":355,"question":"Một trong những nội dung cơ bản của bản Yêu sách gồm tám điểm của Nguyễn Ái Quốc gửi đến Hội nghị Vecxay (Pháp) là:","options":["A. Đòi quyền tự do dân chủ tối thiểu cho nhân dân.","B. Đòi quyền tự trị của dân tộc.","C. Đòi quyền độc lập dân tộc.","D. Đòi quyền bình đẳng."],"answerLetter":"A","answerText":"A. Đòi quyền tự do dân chủ tối thiểu cho nhân dân.","notes":""},{"id":356,"question":"Hồ Chí Minh là người đấu tranh đòi quyền độc lập cho:","options":["A. Dân tộc Việt Nam .","B. Các dân tộc thuộc địa ở phương Đông.","C. Dân tộc Việt Nam và tất cả các dân tộc bị áp bức trên thế giới.","D. Dân tộc thuộc địa ở Đông Dương."],"answerLetter":"C","answerText":"C. Dân tộc Việt Nam và tất cả các dân tộc bị áp bức trên thế giới.","notes":""},{"id":357,"question":"Đâu là câu nói nổi tiếng của Hồ Chí Minh","options":["A. Không có gì quý hơn độc lập tự do","B. Hạnh phúc là đấu tranh","C. Cách mạng là bạo lực"],"answerLetter":"A","answerText":"A. Không có gì quý hơn độc lập tự do","notes":""},{"id":358,"question":"Theo Hồ Chí Minh","options":["A. Giữ vững độc lập của dân tộc mình đồng thời tôn trọng độc lập của các dân tộc khác","B. Giữ vững độc lập của dân tộc mình đồng thời kính trọng độc lập của các dân tộc khác","C. Giữ vững độc lập của dân tộc mình đồng thời tôn trọng tự do của các dân tộc khác","D. Giữ vững độc lập của dân tộc mình đồng thời giữ vững độc lập của các dân tộc khác"],"answerLetter":"A","answerText":"A. Giữ vững độc lập của dân tộc mình đồng thời tôn trọng độc lập của các dân tộc khác","notes":""},{"id":359,"question":"Giải phóng dân tộc theo tư tưởng Hồ Chí Minh, xét về thực chất là:","options":["A. Đánh đổ ách áp bức, thống trị của đế quốc, thực dân giành độc lập dân tộc.","B. Giành độc lập dân tộc, hình thành nhà nước dân tộc độc lập.","C. Tự do lựa chọn con đường phát triển của dân tộc phù hợp với xu thế phát triển của thời đại.","D. Giành được ruộng đất cho dân nghèo, đảm bảo đời sống nông dân ấm no"],"answerLetter":"A","answerText":"A. Đánh đổ ách áp bức, thống trị của đế quốc, thực dân giành độc lập dân tộc.","notes":"(Chọn đáp án chọn tất cả nếu có)(Nếu hỏi: Đâu không phải là một ý nghĩa của giải phóng dân tộc theo Hồ Chí Minh? => D)"},{"id":360,"question":"Hồ Chí Minh đến Nga lần đầu tiên vào năm nào?","options":["A. Năm 1923","B. Năm 1924","C. Năm 1928","D. Năm 1920"],"answerLetter":"A","answerText":"A. Năm 1923","notes":""},{"id":361,"question":"Theo Hồ Chí Minh","options":["A. Giải phóng dân tộc tạo tiền đề để giải phóng giai cấp","B. Giải phóng dân tộc tạo tiền đề để giải phóng nhân loại","C. Giải phóng dân tộc tạo tiền đề để giải phóng người lao động","D. Giải phóng dân tộc tạo tiền đề để giải phóng xã hội"],"answerLetter":"A","answerText":"A. Giải phóng dân tộc tạo tiền đề để giải phóng giai cấp","notes":""},{"id":362,"question":"Bạo lực cách mạng theo tư tưởng Hồ Chí Minh là:","options":["A. Đấu tranh chính trị.","B. Đấu tranh vũ trang.","C. Kết hợp đấu tranh chính trị với đấu tranh vũ trang.","D. Đấu tranh ngoại giao."],"answerLetter":"C","answerText":"C. Kết hợp đấu tranh chính trị với đấu tranh vũ trang.","notes":""},{"id":363,"question":"Hồ Chí Minh về nước lần đầu tiên vào năm nào?","options":["A. Cuối năm 1941","B. Cuối năm 1942","C. Cuối năm 1944","D. Cuối năm 1911"],"answerLetter":"A","answerText":"A. Cuối năm 1941","notes":""},{"id":364,"question":"Hồ Chí Minh cho rằng:","options":["A. Độc lập, tự do là quyền thiêng liêng, bất khả xâm phạm của tất cả các dân tộc.","B. Độc lập, tự do là tất yếu đối với các dân tộ","C. c. Độc lập, tự do là khát vọng thiêng liêng của mọi dân tộc.","D. Độc lập, tự do là quyền thiêng liêng, bất khả xâm phạm của riêng dân tộc Việt Nam."],"answerLetter":"A","answerText":"A. Độc lập, tự do là quyền thiêng liêng, bất khả xâm phạm của tất cả các dân tộc.","notes":""},{"id":365,"question":"Các lực lượng thực hiện giải phóng dân tộc, giải phóng giai cấp, giải phóng con người theo tư tưởng Hồ Chí Minh là:","options":["A. Đảng cộng sản.","B. Khối đại đoàn kết dân tộc, đoàn kết toàn dân mà nòng cốt là liên minh công-nông-trí thứ","C. c. Các lực lượng cách mạng thế giới.","D. Tất cả các phương án."],"answerLetter":"D","answerText":"D. Tất cả các phương án.","notes":""},{"id":366,"question":"Tư tưởng bạo lực cách mạng của Hồ Chí Minh gắn bó hữu cơ với:","options":["A. Nhân văn, hòa bình","B. Nhân đạo, hòa bình","C. Tự do, hòa bình","D. Dân chủ, hòa bình"],"answerLetter":"B","answerText":"B. Nhân đạo, hòa bình","notes":""},{"id":367,"question":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc cần được tiến hành:","options":["A. Chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc","B. Chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng vô sản thế giới","C. Chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng thuộc địa","D. Chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng tư sản ở chính quốc"],"answerLetter":"A","answerText":"A. Chủ động, sáng tạo và có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc","notes":""},{"id":368,"question":"Hồ Chí Minh ví trẻ em như","options":["A. Hoa trên cành","B. Búp trên cành","C. Lá non trên cành"],"answerLetter":"B","answerText":"B. Búp trên cành","notes":""},{"id":369,"question":"Hồ Chí Minh trực tiếp chỉ huy chiến dịch nào sau đây trong kháng chiến chống Pháp?","options":["A. Chiến dịch Đông Xuân","B. Chiến dịch Điện Biên Phủ","C. Chiến dịch Biên giới"],"answerLetter":"C","answerText":"C. Chiến dịch Biên giới","notes":""},{"id":370,"question":"Trong tư tưởng Hồ Chí Minh, nhiệm vụ hàng đầu, trên hết, trước hết của cách mạng Việt Nam là :","options":["A. Giải phóng dân tộc.","B. Giải phóng giai cấp.","C. Giải phóng con người.","D. Tất cả các phương án"],"answerLetter":"A","answerText":"A. Giải phóng dân tộc.","notes":""},{"id":371,"question":"Giải phóng con người theo tư tưởng Hồ Chí Minh là:","options":["A. Giải phóng con người với tư cách từng cá nhân","B. Giải phóng con người với tư cách là cả loài người.","C. Giải phóng con người với tư cách từng cá nhân và cả loài người.","D. Giải phóng những người bị bóc lột."],"answerLetter":"C","answerText":"C. Giải phóng con người với tư cách từng cá nhân và cả loài người.","notes":""},{"id":372,"question":"Theo Hồ Chí Minh, nội dung cốt lõi của vấn đề dân tộc thuộc địa là gì?","options":["A. Tự do, dân chủ","B. Độc lập, tự do","C. Người cày có ruộng","D. Quyền con người"],"answerLetter":"B","answerText":"B. Độc lập, tự do","notes":""},{"id":373,"question":"Cách mạng giải phóng dân tộc là sự nghiệp đoàn kết củ","options":["A. a. Giai cấp công nhân.","B. Giai cấp công nhân và nông dân","C. Toàn dân, trên cơ sở liên minh công-nông.","D. Công - nông - trí thức"],"answerLetter":"C","answerText":"C. Toàn dân, trên cơ sở liên minh công-nông.","notes":""},{"id":374,"question":"Nội dung cốt lõi của vấn đề dân tộc thuộc đị","options":["A. được Hồ Chí Minh tiếp cận từ:a. Tự do dân chủ","B. Quyền con người","C. Khát vọng giải phóng dân tộc","D. Chủ quyền dân tộc"],"answerLetter":"B","answerText":"B. Quyền con người","notes":""},{"id":375,"question":"Ai là người đầu tiên được Hồ Chí Minh phong hàm đại tướng?","options":["A. Võ Nguyên Giáp","B. Nguyễn Sơn","C. Nguyễn Chí Thanh"],"answerLetter":"A","answerText":"A. Võ Nguyên Giáp","notes":""},{"id":376,"question":"Theo Hồ Chí Minh, nhiệm vụ lịch sử của thời kỳ quá độ ở nước ta là phải:","options":["A. Xây dựng nền tảng vật chất và kỹ thuật của chủ nghĩa xã hội.","B. Cải tạo nền kinh tế cũ và xây dựng nền kinh tế mới.","C. Tất cả các phương án."],"answerLetter":"C","answerText":"C. Tất cả các phương án.","notes":""},{"id":377,"question":"Theo Hồ Chí Minh:","options":["A. Sự ra đời của CNXH ở Việt Nam là sản phẩm tất yếu của quá trình phát triển lịch sử, quá trình cách mạng Việt Nam.","B. Sự ra đời của CNXH ở Việt Nam là sản phẩm tất yếu của quá trình phát triển lịch sử, quá trình cách mạng thế giới","C. Sự ra đời của CNXH ở Việt Nam là sản phẩm tất yếu của quá trình phát triển lịch sử, quá trình cách mạng Đông Nam Á."],"answerLetter":"A","answerText":"A. Sự ra đời của CNXH ở Việt Nam là sản phẩm tất yếu của quá trình phát triển lịch sử, quá trình cách mạng Việt Nam.","notes":"(Kiểu hỏi khác: Hồ Chí Minh cho rằng:\nA. Sự ra đời của CNXH trên phạm vi quốc tế là quy luật phát triển của lịch sữ xã hội\nB. Sự ra đời của CNXH trên phạm vi quốc tế là quy luật phát triển của nhân loại\nC. Sự ra đời của CNXH trên phạm vi quốc tế là quy luật phát triển của lịch sử thế giới)"},{"id":378,"question":"Trong xây dựng chủ nghĩa xã hội, Hồ Chí Minh chủ trương đối xử với giai cấp tư sản dân tộc như thế nào?","options":["A. Xóa bỏ quyền sở hữu về tư liệu sản xuất của họ","B. Không xóa bỏ quyền sở hữu tư liệu sản xuất của họ","C. Đánh đổ họ với tư cách là giai cấp bóc lột","D. Phát triển giai cấp này cả về số lượng và chất lượng"],"answerLetter":"B","answerText":"B. Không xóa bỏ quyền sở hữu tư liệu sản xuất của họ","notes":""},{"id":379,"question":"Quan điểm nào dưới đây thuộc về bản chất củ","options":["A. CNXH trong tư tưởng Hồ Chí Minh?a. Có đạo đức, con người phát triển cao","B. Có văn hóa, con người phát triển cao","C. Có văn hóa, đạo đức phát triển cao"],"answerLetter":"C","answerText":"C. Có văn hóa, đạo đức phát triển cao","notes":""},{"id":380,"question":"Theo Hồ Chí Minh, nền kinh tế mà chúng ta xây dựng phải được tạo lập trên cơ sở:","options":["A. Nền nông nghiệp hiện đại.","B. Nền công nghiệp hiện đại.","C. Khoa học kỹ thuật tiên tiến.","D. Chế độ công hữu về tư liệu sản xuất."],"answerLetter":"D","answerText":"D. Chế độ công hữu về tư liệu sản xuất.","notes":""},{"id":381,"question":"Theo Hồ Chí Minh, trong thời kỳ quá độ còn tồn tại hình thức:","options":["A. Sở hữu của nhà nước và sở hữu của hợp tác xã.","B. Sở hữu của người lao động riêng lẻ và sở hữu của nhà tư bản.","C. Tất cả các phương án."],"answerLetter":"C","answerText":"C. Tất cả các phương án.","notes":""},{"id":382,"question":"Con đường quá độ lên chủ nghĩa xã hội ở nước ta đươc Hồ Chí Minh vạch ra dựa trên:","options":["A. Chủ nghĩa Mác-Lênin.","B. Chủ nghĩa dân chủ.","C. Sự kết hợp giữa chủ nghĩa Mác-lênin với thực tế Việt Nam.","D. Kết hợp giữa chủ nghĩa Tam dân và thực tế Việt Nam."],"answerLetter":"C","answerText":"C. Sự kết hợp giữa chủ nghĩa Mác-lênin với thực tế Việt Nam.","notes":""},{"id":383,"question":"Theo Hồ Chí Minh, CNXH phải do:","options":["A. Nhân dân lao động làm chủ","B. Giai cấp công nhân làm chủ","C. Giai cấp nông dân làm chủ","D. Công nhân - nông dân - trí thức làm chủ"],"answerLetter":"A","answerText":"A. Nhân dân lao động làm chủ","notes":""},{"id":384,"question":"Theo Hồ Chí Minh, con đường quá độ lên CNXH ở Việt Nam là:","options":["A. Quá độ trực tiếp.","B. Quá độ gián tiếp.","C. Quá độ kết hợp nhiều hình thức.","D. Quá độ gián tiếp cụ thể."],"answerLetter":"D","answerText":"D. Quá độ gián tiếp cụ thể.","notes":""},{"id":385,"question":"Nội dung nào không đúng với tư tưởng Hồ Chí Minh, để xác định bước đi và tìm cách làm của chủ nghĩa xã hội phù hợp với Việt Nam cần phải:","options":["A. Theo bước đi của các nước xã hội chủ nghĩa, vừa làm vừa tìm kiếm mô hình phù hợp.","B. Quán triệt các nguyên lý cơ bản của chủ nghĩa Mác-Lênin về xây dựng chế độ mới, có thể tham khảo, học tập kinh nghiệm của các nước anh em."],"answerLetter":"A","answerText":"A. Theo bước đi của các nước xã hội chủ nghĩa, vừa làm vừa tìm kiếm mô hình phù hợp.","notes":""},{"id":386,"question":"Quan điểm nào dưới đây thuộc về bản chất của CNXH trong tư tưởng Hồ Chí Minh?","options":["A. Chế độ chính trị do nhân dân làm chủ.","B. Chế độ chính trị do nhân dân sáng tạo.","C. Chế độ chính trị do nhà nước làm chủ.","D. Chế độ chính trị do Đảng làm chủ."],"answerLetter":"A","answerText":"A. Chế độ chính trị do nhân dân làm chủ.","notes":""},{"id":387,"question":"Theo Hồ Chí Minh, nội dung nào không đúng để phát huy động lực con người?","options":["A. Phát huy sức mạnh đoàn kết của cả cộng đồng dân tộc","B. Phát huy sức mạnh của cá nhân con người","C. Phát huy các yếu tố chính trị, tinh thần","D. Phát huy trí lực, tài lực và nhân lực của nhân dân"],"answerLetter":"B","answerText":"B. Phát huy sức mạnh của cá nhân con người","notes":""},{"id":388,"question":"Quan điểm củ","options":["A. Hồ Chí Minh là:a. Tiến lên chủ nghĩa xã hội là bước phát triển tất yếu đối với các nước phương Đông.","B. Tiến lên chủ nghĩa xã hội là bước phát triển tất yếu của các nướ","C. đang phát triển.c. Tiến lên chủ nghĩa xã hội là bước phát triển tất yếu của các nước trên thế giới.","D. Tiến lên chủ nghĩa xã hội là bước phát triển tất yếu ở Việt Nam sau khi nước nhà giành được độc lập theo con đường cách mạng vô sản."],"answerLetter":"D","answerText":"D. Tiến lên chủ nghĩa xã hội là bước phát triển tất yếu ở Việt Nam sau khi nước nhà giành được độc lập theo con đường cách mạng vô sản.","notes":""},{"id":389,"question":"Ham muốn tột bậc củ","options":["A. Hồ Chí Minh là gì?a. Nước được độc lập","B. Dân được tự do","C. Đồng bào ai cũng có cơm ăn, áo mặc, được học hành","D. Tất cả các phương án"],"answerLetter":"D","answerText":"D. Tất cả các phương án","notes":""},{"id":390,"question":"Trong bản di chúc, Hồ Chí Minh có viết điều mong muốn cuối cùng là:","options":["A. Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh và góp phần xứng đáng vào sự nghiệp cách mạng thế giới.","B. Xây dựng một nướ","C. Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh và góp phần xứng đáng vào sự nghiệp cách mạng khu vực.c. Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh và góp phần xứng đáng vào sự nghiệp cách mạng chung."],"answerLetter":"A","answerText":"A. Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh và góp phần xứng đáng vào sự nghiệp cách mạng thế giới.","notes":""},{"id":391,"question":"Đâu là bản chất củ","options":["A. CNXH trong tư tưởng Hồ Chí Minh?a. Có xã hội dân sự","B. Có xã hội dân quyền","C. Có nền chính trị dân chủ"],"answerLetter":"C","answerText":"C. Có nền chính trị dân chủ","notes":""},{"id":392,"question":"Hồ Chí Minh cho rằng quá độ lên chủ nghĩa xã hội ở Việt Nam phải tiến hành:","options":["A. Dần dần, từng bước một","B. Nhanh chóng, chính xác","C. Cận thận, không chủ quan","D. Tiến nhanh, tiến mạnh"],"answerLetter":"A","answerText":"A. Dần dần, từng bước một","notes":""},{"id":393,"question":"Theo Hồ Chí Minh, động lực củ","options":["A. CNXH gồm:a. Động lực tinh thần và bên ngoài.","B. Động lực vật chất và bên trong.","C. Động lực vật chất và tinh thần, nội sinh và ngoại sinh.","D. Động lực tinh thần và nội sinh."],"answerLetter":"C","answerText":"C. Động lực vật chất và tinh thần, nội sinh và ngoại sinh.","notes":""},{"id":394,"question":"Theo Hồ Chí Minh, nhân tố nào sau đây quyết định thành công của thời kỳ quá độ lên CNXH:","options":["A. Con người","B. Văn hóa","C. Xã hội","D. Chính trị"],"answerLetter":"A","answerText":"A. Con người","notes":""},{"id":395,"question":"Hồ Chí Minh cho rằng chủ nghĩa xã hội","options":["A. Phù hợp với các dân tộc phương Đông","B. Phù hợp với các dân tộc phương Tây","C. Phù hợp với các nước thuộc địa hơn các nước chính quốc"],"answerLetter":"A","answerText":"A. Phù hợp với các dân tộc phương Đông","notes":""},{"id":396,"question":"Theo quan điểm của Hồ Chí Minh, đặc điểm của thời kỳ quá độ ở Việt Nam là gì?","options":["A. Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không qua giai đoạn phát triển tư bản chủ nghĩa","B. Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không qua giai đoạn phát triển xã hội dân chủ","C. Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không qua giai đoạn phát triển xã hội","D. Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, thông qua giai đoạn phát triển tư bản chủ nghĩa"],"answerLetter":"A","answerText":"A. Từ một nước nông nghiệp lạc hậu tiến thẳng lên chủ nghĩa xã hội, không qua giai đoạn phát triển tư bản chủ nghĩa","notes":"phong kiến"},{"id":397,"question":"Theo Hồ Chí Minh, trong thời kỳ quá độ, nền kinh tế phải ưu tiên là:","options":["A. Kinh tế hợp tác xã.","B. Kinh tế tư bản tư nhân.","C. Kinh tế thủ công và lao động riêng lẻ.","D. Kinh tế quốc doanh."],"answerLetter":"D","answerText":"D. Kinh tế quốc doanh.","notes":""},{"id":398,"question":"Theo Hồ Chí Minh, cách mạng XHCN do:","options":["A. Đảng lãnh đạo","B. Giai cấp công nhân lãnh đạo","C. Tầng lớp trí thức lãnh đạo","D. Công - nông - trí lãnh đạo"],"answerLetter":"A","answerText":"A. Đảng lãnh đạo","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh, cách mạng xã hội chủ nghĩa phải tiến hành do ai lãnh đạo?\nA. Giai cấp nông dân và công nhân lãnh đạo\nB. Giai cấp công nhân lãnh đạo\nC. Tầng lớp trí thức lãnh đạo\nD. Giai cấp nông dân lãnh đạo)"},{"id":399,"question":"Nội dung nào không có trong cách tiếp cận củ","options":["A. Hồ Chí Minh về chủ nghĩa xã hội:a. Hồ Chí Minh tiếp cận chủ nghĩa xã hội trên phương diện kinh tế.","B. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ khát vọng giải phóng dân tộ","C. Việt Nam.c. Hồ Chí Minh tiếp cận chủ nghĩa xã hội trên phương diện đạo đức.","D. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ văn hóa."],"answerLetter":"A","answerText":"A. Hồ Chí Minh về chủ nghĩa xã hội:a. Hồ Chí Minh tiếp cận chủ nghĩa xã hội trên phương diện kinh tế.","notes":""},{"id":400,"question":"Theo Hồ Chí Minh, Đảng phải triệt để thực hành dân chủ, mà trước hết dân chủ trong:","options":["A. Nội bộ Đảng.","B. Chính quyền.","C. Nhân dân."],"answerLetter":"A","answerText":"A. Nội bộ Đảng.","notes":""},{"id":401,"question":"Quan điểm nào sau đây là tư cách Đảng viên theo tư tưởng Hồ Chí Minh?","options":["A. Đặt lợi ích của Đảng, của con người lên trên hết","B. Đặt lợi ích của Đảng, của nhân dân lên trên hết","C. Đặt lợi ích của Đảng, của đất nước lên trước hết"],"answerLetter":"B","answerText":"B. Đặt lợi ích của Đảng, của nhân dân lên trên hết","notes":""},{"id":402,"question":"Theo Hồ Chí Minh, tập trung trong Đảng có nghĩa là thiểu số phục tùng đa số, cấp dưới phục tùng cấp trên, tất cả đảng viên chấp hành:","options":["A. Vô điều kiện nghị quyết của Tổng bí thư.","B. Vô điều kiện nghị quyết của Chủ tịch nước.","C. Vô điều kiện nghị quyết của Đảng.","D. Vô điều kiện nghị quyết của Quốc hội."],"answerLetter":"C","answerText":"C. Vô điều kiện nghị quyết của Đảng.","notes":""},{"id":403,"question":"Theo Hồ Chí Minh, trong quá trình hoạt động, Đảng ta phải chủ ý học tập, kế thừa những kinh nghiệm tốt của các đảng cộng sản khác, đồng thời Đảng ta phải tổng kết kinh nghiệm của mình để:","options":["A. Bổ sung lý luận về Đảng Cộng sản cầm quyền","B. Bổ sung tư duy của Đảng Cộng sản","C. Bổ sung đường lối của Đảng Cộng sản","D. Bổ sung chủ nghĩa Mác - Lênin."],"answerLetter":"A","answerText":"A. Bổ sung lý luận về Đảng Cộng sản cầm quyền","notes":""},{"id":404,"question":"Theo Hồ Chí Minh, một Đảng chân chính cách mạng phải có (...). (...) tạo nên uy tín, sức mạnh củ","options":["A. Đảng, giúp Đảng đủ tư cách lãnh đạo, hướng dẫn quần chúng nhân dân.a. Đạo đức","B. Lý luận","C. Năng lực","D. Tài năng"],"answerLetter":"A","answerText":"A. Đảng, giúp Đảng đủ tư cách lãnh đạo, hướng dẫn quần chúng nhân dân.a. Đạo đức","notes":""},{"id":405,"question":"Bản chất giai cấp công nhân củ","options":["A. Đảng Cộng sản Việt Nam thể hiện ở:a. Số lượng Đảng viên trong Đảng.","B. Trình độ Đảng viên trong Đảng.","C. Nền tảng lý luận, mục tiêu, đường lối, nguyên tắc tổ chức của Đảng.","D. Tất cả các phương án."],"answerLetter":"C","answerText":"C. Nền tảng lý luận, mục tiêu, đường lối, nguyên tắc tổ chức của Đảng.","notes":""},{"id":406,"question":"Theo tư tưởng Hồ Chí Minh, Đảng phải thường xuyên tự đổi mới, tự chỉnh đốn về mặt:","options":["A. Chính trị, tư tưởng.","B. Tư tưởng, tổ chứ","C. c. Tổ chức, chính trị.","D. Chính trị, tổ chức, tư tưởng."],"answerLetter":"D","answerText":"D. Chính trị, tổ chức, tư tưởng.","notes":""},{"id":407,"question":"Theo Hồ Chí Minh, người cán bộ phải có đủ đức và tài, phẩm chất và năng lực, trong đó:","options":["A. Đức là phẩm chất gốc.","B. Tài là phẩm chất gố","C. c. Năng lực là phẩm chất gốc."],"answerLetter":"A","answerText":"A. Đức là phẩm chất gốc.","notes":""},{"id":408,"question":"Theo Hồ Chí Minh, việc vận dụng chủ nghĩ","options":["A. Mác - Lênin phải:a. Luôn phù hợp với từng đối tượng.","B. Luôn luôn phù hợp với từng hoàn cảnh.","C. Tất cả các phương án."],"answerLetter":"B","answerText":"B. Luôn luôn phù hợp với từng hoàn cảnh.","notes":""},{"id":409,"question":"Hồ Chí Minh gọi đồng bào Miền nam với cái tên thân thương và trìu mến đó là","options":["A. Thành đồng tổ quốc","B. Anh hùng bất khuất","C. Anh dũng kiên cường","D. Giai cấp cách mệnh"],"answerLetter":"A","answerText":"A. Thành đồng tổ quốc","notes":""},{"id":410,"question":"Theo Hồ Chí Minh, Muốn lãnh đạo được nhân dân lao động, trước hết Đảng phải có:","options":["A. Tư cách, phẩm chất, năng lực cần thiết.","B. Quyền lực chính trị.","C. Tiềm lực kinh tế.","D. Chính quyền."],"answerLetter":"A","answerText":"A. Tư cách, phẩm chất, năng lực cần thiết.","notes":""},{"id":411,"question":"Hồ Chí Minh cho rằng cán bộ, đảng viên không được:","options":["A. Theo đuôi quần chúng","B. Làm theo quần chúng","C. Đi trước quần chúng","D. Làm gương cho quần chúng"],"answerLetter":"A","answerText":"A. Theo đuôi quần chúng","notes":""},{"id":412,"question":"\"Đường cách mệnh\" là tác phẩm chính trị được Hồ Chí Minh viết tại nước nào sau đây:","options":["A. Pháp","B. Trung Quốc","C. Anh","D. Liên Xô"],"answerLetter":"B","answerText":"B. Trung Quốc","notes":""},{"id":413,"question":"Theo Hồ Chí Minh, công tác cán bộ là:","options":["A. Công tác gốc của chính quyền.","B. Công tác của Đảng.","C. Công tác gốc của Đảng.","D. Công tác của chính quyền."],"answerLetter":"C","answerText":"C. Công tác gốc của Đảng.","notes":""},{"id":414,"question":"Một trong những nguyên tắc xây dựng Đảng củ","options":["A. Hồ Chí Minh là:a. Tập thể lãnh đạo, quần chúng phụ trách.","B. Tập thể lãnh đạo, cá nhân phụ trách.","C. Tập thể lãnh đạo, đảng viên phụ trách.","D. Cá nhân lãnh đạo, tập thể phụ trách."],"answerLetter":"B","answerText":"B. Tập thể lãnh đạo, cá nhân phụ trách.","notes":""},{"id":415,"question":"\"Lực lượng của giai cấp công nhân và nhân dân lao động là rất to lớn, là vô cùng vô tận. Nhưng lực lượng ấy cần có (....) mới chắc chắn thắng lợi\"","options":["A. Chính quyền tổ chức","B. Đảng lãnh đạo","C. Nhà nước quản lý","D. Đoàn thể lãnh đạo"],"answerLetter":"B","answerText":"B. Đảng lãnh đạo","notes":""},{"id":416,"question":"Theo Hồ Chí Minh, quyền lực thuộc về nhân dân là bản chất, là nguyên tắc của chế độ mới, một khi xa rời nguyên tắc này, Đảng sẽ trở thành:","options":["A. Đối lập với nhà nước.","B. Đối lập với nhân dân.","C. Đối lập với chế độ."],"answerLetter":"B","answerText":"B. Đối lập với nhân dân.","notes":""},{"id":417,"question":"Hồ Chí Minh cho rằng Cán bộ, Đảng viên phải lưu ý cái gì có hại cho dân dù nhỏ đến máy cũng phải","options":["A. Tránh","B. Đề phòng","C. Vượt qua"],"answerLetter":"A","answerText":"A. Tránh","notes":""},{"id":418,"question":"Hồ Chí Minh cho rằng:","options":["A. Do lời nói và việc làm, đảng viên, đoàn viên và cán bộ làm cho dân tin, dân phục, dân yêu","B. Do hành động của đảng viên, đoàn viên và cán bộ làm cho dân tin, dân phục, dân yêu","C. Do lời nói và việc làm, đảng viên, đoàn viên và cán bộ làm cho dân ấm no, hạnh phúc"],"answerLetter":"A","answerText":"A. Do lời nói và việc làm, đảng viên, đoàn viên và cán bộ làm cho dân tin, dân phục, dân yêu","notes":""},{"id":419,"question":"Trong hệ thống các quan điểm của Hồ Chí Minh về Đảng Cộng sản, quan điểm nào không phải thật sự là sự sáng tạo riêng của Người góp phần cụ thể hóa và phát triển lý luận Mác - Lênin về Đảng Cộng sản?","options":["A. Mối quan hệ biện chứng giữa tính phổ biến và tính đặc thù của quy luật hình thành Đảng vô sản kiểu mới trong điều kiện từng nước.","B. Quan điểm về sự thống nhất biện chứng giữa bản chất giai cấp công nhân với tính dân tộc và tính nhân dân của Đảng.","C. Quan niệm về Đảng Cộng sản cầm quyền và các yếu tố bảo đảm vai trò cầm quyền của Đảng.","D. Quan điểm về những vấn đề có tính nguyên tắc trong xây dựng Đảng Cộng sản Việt Nam trong sạch, vững mạnh."],"answerLetter":"D","answerText":"D. Quan điểm về những vấn đề có tính nguyên tắc trong xây dựng Đảng Cộng sản Việt Nam trong sạch, vững mạnh.","notes":""},{"id":420,"question":"Đối với Hồ Chí Minh, Đảng là \"Đầy tớ trung thành\" là để nhắc nhở và chỉ rõ vai trò, trách nhiệm của mỗi cán bộ, đảng viên trong mọi hoạt động của mình đều phải:","options":["A. Quan tâm thực sự đến sức khỏe của nhân dân.","B. Quan tâm thực sự đến lợi ích của nhân dân.","C. Quan tâm thực sự đến tinh thần của nhân dân.","D. Quan tâm thực sự đến vật chất của nhân dân."],"answerLetter":"B","answerText":"B. Quan tâm thực sự đến lợi ích của nhân dân.","notes":""},{"id":421,"question":"Hồ Chí Minh sử dụng bộ phận nào trong cơ thể con người để chỉ tầm quan trọng củ","options":["A. đoàn kết trong đảnga. Con ngươi","B. Bàn tay","C. Trái tim","D. Khối óc"],"answerLetter":"A","answerText":"A. đoàn kết trong đảnga. Con ngươi","notes":""},{"id":422,"question":"Theo Hồ Chí Minh, đường lối chính trị là:","options":["A. Một vấn đề cốt tử trong tồn tại và phát triển của Đảng.","B. Một vấn đề không quan trọng trong tồn tại và phát triển của Đảng.","C. Một vấn đề thứ yếu trong tồn tại và phát triển của Đảng."],"answerLetter":"A","answerText":"A. Một vấn đề cốt tử trong tồn tại và phát triển của Đảng.","notes":""},{"id":423,"question":"Quy luật ra đời của Đảng Cộng sản Việt Nam được Hồ Chí Minh vạch ra:","options":["A. Không phù hợp với tinh thần của chủ nghĩa Mác- Lênin","B. Trái với tinh thần của chủ nghĩa Mác- Lênin","C. Không trái với tinh thần của chủ nghĩa Mác- Lênin"],"answerLetter":"C","answerText":"C. Không trái với tinh thần của chủ nghĩa Mác- Lênin","notes":""},{"id":424,"question":"Một trong những nguyên tắc xây dựng Đảng củ","options":["A. Hồ Chí Minh là:a. Tập thể phê bình và tự phê bình","B. Phê bình và tự phê bình","C. Phê bình và tập thể phê bình","D. Tự phê bình và cùng phê bình"],"answerLetter":"B","answerText":"B. Phê bình và tự phê bình","notes":""},{"id":425,"question":"Theo Hồ Chí Minh, dân chủ là tư tưởng phải được tự do. Tự do là đối với mọi vấn đề, mọi người tự do bày tỏ ý kiến của mình, góp phần tìm r","options":["A. a. Chân lý.","B. Thực tiễn.","C. Lý lẽ.","D. Nguyên tắc."],"answerLetter":"A","answerText":"A. a. Chân lý.","notes":""},{"id":426,"question":"Hồ Chí Minh ví công việc phê bình và tự phê bình như:","options":["A. Rửa mặt hằng ngày","B. Ăn cơm hàng ngày","C. Học tập hàng ngày","D. Uống nước hàng ngày"],"answerLetter":"A","answerText":"A. Rửa mặt hằng ngày","notes":""},{"id":427,"question":"Một trong những nguyên tắc xây dựng Đảng củ","options":["A. Hồ Chí Minh là:a. Tập trung hợp tác","B. Tập trung dân chủ","C. Tập trung thống nhất","D. Hợp tác dân chủ"],"answerLetter":"B","answerText":"B. Tập trung dân chủ","notes":""},{"id":428,"question":"Hồ Chí Minh nhận thức cán bộ là cái dây chuyền của bộ máy, là mắt khâu trung gian nối liền giữa:","options":["A. Nhà nước với nhân dân.","B. Đảng với dân.","C. Đảng, Nhà nước với nhân dân.","D. Đảng với Nhà nước."],"answerLetter":"C","answerText":"C. Đảng, Nhà nước với nhân dân.","notes":""},{"id":429,"question":"Theo tư tưởng Hồ Chí Minh, nhân tố quyết định hàng đầu để đưa cách mạng Việt Nam đến thắng lợi là:","options":["A. Đoàn kết dân tộc","B. Đoàn kết giai cấp","C. Kết hợp sức mạnh dân tộc với sức mạnh thời đại","D. Phải có Đảng Cộng sản"],"answerLetter":"D","answerText":"D. Phải có Đảng Cộng sản","notes":""},{"id":430,"question":"\"Muốn khỏi đi lạc phương hướng, (....) phải có Đảng lãnh đạo để nhận rõ tình hình, đường lối và định phương châm cho đúng\"","options":["A. Quần chúng","B. Nhân dân","C. Dân tộc"],"answerLetter":"A","answerText":"A. Quần chúng","notes":""},{"id":431,"question":"Đại đoàn kết dân tộc được xác định là nhiệm vụ nào trong những nhiệm vụ dưới đây củ","options":["A. Đảng và của toàn dân tộc ta?a. Cơ bản của Đảng và của dân tộc","B. Hàng đầu của Đảng và của dân tộc","C. Quan trọng của Đảng và của dân tộc ta","D. Thiết yếu"],"answerLetter":"B","answerText":"B. Hàng đầu của Đảng và của dân tộc","notes":""},{"id":432,"question":"Nguyên tắc tối cao để đoàn kết rộng rãi trong quần chúng nhân dân là:","options":["A. Yêu dân, tin dân, dựa vào dân, vì hạnh phúc của nhân dân","B. Đoàn kết trên cơ sở độc lập tự chủ","C. Đoàn kết chặt chẽ, chân thành","D. Đoàn kết trên cơ sở tự nguyện"],"answerLetter":"A","answerText":"A. Yêu dân, tin dân, dựa vào dân, vì hạnh phúc của nhân dân","notes":""},{"id":433,"question":"Theo Hồ Chí Minh, \"Ai có tài, có đức, có sức, có lòng phụng sự Tổ quốc và phục vụ nhân dân thì ta (....) với họ\".","options":["A. Hợp tác","B. Đoàn kết","C. Bắt tay","D. Chia sẻ"],"answerLetter":"B","answerText":"B. Đoàn kết","notes":""},{"id":434,"question":"Trong tư tưởng Hồ Chí Minh, mối quan hệ giữa Đảng và Mặt trận được xác định là mối quan hệ:","options":["A. Song song","B. Máu thịt","C. Biện chứng","D. Độc lập"],"answerLetter":"B","answerText":"B. Máu thịt","notes":""},{"id":435,"question":"Theo Hồ Chí Minh, để thực hiện đoàn kết quốc tế thì đoàn kết (....) \"là điều kiện quan trọng nhất để bảo đảm cho phong trào cộng sản và công nhân toàn thắng\"","options":["A. Giữa các Đảng","B. Giữa các chính phủ","C. Giữa các dân tộc","D. Tất cả các phương án"],"answerLetter":"A","answerText":"A. Giữa các Đảng","notes":""},{"id":436,"question":"Hồ Chí Minh minh cho rằng \"đoàn kết phải gắn với (....), (....) để tăng cường đoàn kết\".","options":["A. Đấu tranh","B. Lợi ích","C. Tự do","D. Dân chủ"],"answerLetter":"A","answerText":"A. Đấu tranh","notes":""},{"id":437,"question":"Trong tư tưởng Hồ Chí Minh, nền tảng của khối đại đoàn kết dân tộc là:","options":["A. Liên minh công-nông","B. Liên minh công-nông, lao động trí óc.","C. Liên minh công-nông và các tầng lớp lao động khác.","D. Liên minh công-nông và các lực lượng yêu nước khác."],"answerLetter":"B","answerText":"B. Liên minh công-nông, lao động trí óc.","notes":""},{"id":438,"question":"Hồ Chí Minh chỉ ra nguyên tắc xây dựng mặt trận:","options":["A. Mặt trận phải hoạt động theo nguyên tắc hiệp thương dân chủ","B. Mặt trận phải hoạt động theo nguyên tắc hiệp thương dân quyền","C. Mặt trận phải hoạt động theo nguyên tắc hiệp thương quần chúng"],"answerLetter":"A","answerText":"A. Mặt trận phải hoạt động theo nguyên tắc hiệp thương dân chủ","notes":""},{"id":439,"question":"Đâu là nguyên tắc đoàn kết quốc tế trong tư tưởng Hồ Chí Minh?","options":["A. Đoàn kết trên cơ sở thống nhất mục tiêu và lợi ích, có lý, có tình.","B. Đoàn kết trên cơ sở thống nhất mục tiêu độc lập của dân tộc mình và mục tiêu của nhân loại","C. Đoàn kết trên cơ sở thống nhất mục tiêu và mục đích, có lý, có tình."],"answerLetter":"A","answerText":"A. Đoàn kết trên cơ sở thống nhất mục tiêu và lợi ích, có lý, có tình.","notes":"(Kiểu hỏi khác: Nội dung lớn trong xây dựng nguyên tắc đoàn kết quốc tế của Hồ Chí Minh là gì?A. Đoàn kết trên cơ sở thống nhất mục tiêu, và lợi ích có lý, có tìnhB. Đoàn kết trên cơ sở dân chủC. Hợp tác quốc tế trên cơ sở giữ vững toàn vẹn lãnh thổD. Kết hợp sức mạnh dân tộc và sức mạnh thời đại)"},{"id":440,"question":"Khẩu hiệu chiến lược: \"Giai cấp vô sản tất cả các nước và các dân tộc bị áp bức, đoàn kết lại\" là của:","options":["A. C. Mác","B. Ph. Ăngghen","C. V.I.Lênin","D. Hồ Chí Minh"],"answerLetter":"C","answerText":"C. V.I.Lênin","notes":"(Kiểu hỏi khác: Khẩu hiệu chiến lược: \"Vô sản toàn thế giới và các dân tộc bị áp bức, đoàn kết lại\" là của ai?)"},{"id":441,"question":"Theo Hồ Chí Minh, xây dựng nhà nước trong sạch vững mạnh cần phải:","options":["A. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức cách mạng","B. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dụ","C. đạo đức cán bộc. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức quần chúng"],"answerLetter":"A","answerText":"A. Tăng cường tính nghiêm minh của pháp luật đi đôi với giáo dục đạo đức cách mạng","notes":""},{"id":442,"question":"Đâu là quan điểm của Hồ Chí Minh về xây dựng nhà nước có hiệu lực pháp lý mạnh mẽ?","options":["A. Hoạt động quản lý nhà nước bằng Hiến pháp và pháp luật, chú trọng đưa pháp luật vào cuộc sống.","B. Hoạt động quản lý nhà nước bằng quy định và đạo luật, chú trọng đưa quy định vào cuộc sống.","C. Hoạt động quản lý nhà nước bằng Hiến pháp và sắc lệnh, chú trọng đưa sắc lệnh"],"answerLetter":"A","answerText":"A. Hoạt động quản lý nhà nước bằng Hiến pháp và pháp luật, chú trọng đưa pháp luật vào cuộc sống.","notes":"(Kiểu hỏi khác: Trong Tư tường Hồ Chí Minh nhà nước thượng tôn pháp luật quản lý đất nước bằng:\n-> Hiến pháp và Pháp luật)"},{"id":443,"question":"Theo Hồ Chí Minh, nhà nước của dân là:","options":["A. Do nhân dân lập ra","B. Do nhân dân lãnh đạo","C. Do nhân dân quản lý","D. Quyền lực của nhà nước và xã hội thuộc về nhân dân"],"answerLetter":"D","answerText":"D. Quyền lực của nhà nước và xã hội thuộc về nhân dân","notes":""},{"id":444,"question":"Chọn phương án trả lời đúng nhất theo tư tưởng Hồ Chí Minh về bản chất của nhà nước Việt Nam?","options":["A. Mang bản chất giai cấp công nhân.","B. Có tính dân tộc, tính nhân dân sâu sắ","C. c. Có sự thống nhất bản chất giai cấp công nhân với tính nhân dân và tính dân tộc.","D. Mang tính dân tộc."],"answerLetter":"C","answerText":"C. c. Có sự thống nhất bản chất giai cấp công nhân với tính nhân dân và tính dân tộc.","notes":""},{"id":445,"question":"Theo Hồ Chí Minh, mọi người phải hiểu và tuyệt đối chấp hành pháp luật, bất kể người đó giữ cương vị nào. Vì thần linh pháp quyền là:","options":["A. Sức mạnh do thần linh và vì con người.","B. Sức mạnh do con người và vì con người.","C. Sức mạnh do con người và vì thần linh."],"answerLetter":"B","answerText":"B. Sức mạnh do con người và vì con người.","notes":""},{"id":446,"question":"Quan điểm nào sau đây được xem là đánh giá củ","options":["A. Hồ Chí Minh về giá trị của dân chủ:a. Dân chủ là của quý báu nhất của nhân dân","B. Dân chủ là tài sản quý báu nhất của dân quyền","C. Dân chủ là tài sản của mọi chế độ xã hội","D. Dân chủ là tài sản vô giá của mọi xã hội không có sự phân chia giai cấp"],"answerLetter":"A","answerText":"A. Hồ Chí Minh về giá trị của dân chủ:a. Dân chủ là của quý báu nhất của nhân dân","notes":""},{"id":447,"question":"Theo Hồ Chí Minh, dân làm chủ nghĩa là:","options":["A. Đề cập tới năng lực của dân","B. Đề cập tới trách nhiệm của dân","C. Tất cả các phương án"],"answerLetter":"C","answerText":"C. Tất cả các phương án","notes":""},{"id":448,"question":"Theo Hồ Chí Minh, kỷ cương, phép nước thời nào cũng luôn được đề cao và phải được áp dụng cho tất cả mọi người. Từ đó Người đưa ra yêu cầu:","options":["A. Pháp luật phải thẳng tay trừng trị những kẻ bất liêm, bất kỳ kẻ ấy ở địa vị nào, làm nghề nghiệp gì.","B. Phải cảm hoá những người có lỗi lầm, kéo họ đi với cách mạng, giáo dục những người mắc khuyết điểm để họ tránh phạm pháp.","C. Tất cả các phương án."],"answerLetter":"C","answerText":"C. Tất cả các phương án.","notes":""},{"id":449,"question":"Hồ Chí Minh cho rằng đạo đức cách mạng phải:","options":["A. Tự mình tu dưỡng mà thành","B. Tự mình phấn đấu mà thành","C. Tự mình học tập mà thành"],"answerLetter":"A","answerText":"A. Tự mình tu dưỡng mà thành","notes":""},{"id":450,"question":"Hồ Chí Minh nói: \"Đạo đức cũ như người đầu ngược xuống đất chân chổng lên trời. Đạo đức mới như người hai chân đứng vững được dưới đất, đầu:","options":["A. ngửng lên trời\".","B. ngửa lên trời\".","C. chổng lên trời\"."],"answerLetter":"A","answerText":"A. ngửng lên trời\".","notes":""},{"id":451,"question":"Trong tư tưởng Hồ Chí Minh: đức là gốc của tài hồng là gốc của chuyên phẩm chất là gốc của năng lực. Tài là thể hiện cụ thể củ","options":["A. a. Đức trong hiệu quả hành động.","B. Năng lực trong hiệu quả hành động.","C. Kỹ năng trong hiệu quả hành động."],"answerLetter":"A","answerText":"A. a. Đức trong hiệu quả hành động.","notes":""},{"id":452,"question":"Hồ Chí Minh đưa ra mấy điểm lớn định hướng cho việc xây dựng nền văn hóa dân tộc?","options":["A. Bốn","B. Năm","C. Sáu","D. Ba"],"answerLetter":"B","answerText":"B. Năm","notes":""},{"id":453,"question":"Trong tư tưởng Hồ Chí Minh, nhân dân được xác định vị trí như thế nào của cách mạng?","options":["A. Là mục tiêu của cách mạng","B. Là động lực của cách mạng","C. Vừa là mực tiêu vừa là động lực của cách mạng","D. Là người bạn đường của cách mạng"],"answerLetter":"C","answerText":"C. Vừa là mực tiêu vừa là động lực của cách mạng","notes":""},{"id":454,"question":"Theo Hồ Chí Minh, văn nghệ (bao gồm văn học và nghệ thuật) là biểu hiện tập trung nhất của nền văn hóa, là đỉnh cao củ","options":["A. đời sống tinh thần, là hình ảnh của:a. Trí tuệ dân tộc.","B. Vật chất dân tộc .","C. Tâm hồn dân tộc."],"answerLetter":"C","answerText":"C. Tâm hồn dân tộc.","notes":""},{"id":455,"question":"Theo Hồ Chí Minh: Trung với nước là tuyệt đối trung thành với sự nghiệp dựng nước và giữ nước, trung thành với con đường đi lên của đất nước là suốt đời phấn đấu cho:","options":["A. Đảng, cho cách mạng.","B. Nhà nước, cho cách mạng.","C. Dân tộc, cho cách mạng.","D. Cách mạng, quần chúng"],"answerLetter":"A","answerText":"A. Đảng, cho cách mạng.","notes":""},{"id":456,"question":"Theo Hồ Chí Minh, tính khoa học của nền văn hoá mới thể hiện ở tính hiện đại, tiên tiến, thuận với:","options":["A. Trào lưu tiến hoá của dân tộc.","B. Trào lưu tiến hoá của thời đại.","C. Trào lưu tiến hoá của khoa học kỹ thuật."],"answerLetter":"B","answerText":"B. Trào lưu tiến hoá của thời đại.","notes":""},{"id":457,"question":"Theo Hồ Chí Minh, Cần là siêng năng, chăm chỉ lao động có kế hoạch, có hiệu quả, có năng suất cao với tinh thần:","options":["A. Tự lực cánh sinh.","B. Chịu khó.","C. Cầu thị.","D. Nỗ lực."],"answerLetter":"A","answerText":"A. Tự lực cánh sinh.","notes":""},{"id":458,"question":"Theo Hồ Chí Minh, con người luôn có xu hướng vươn lên cái Chân - Thiện - Mỹ, mặc dù:","options":["A. có thế này, có thế khác\".","B. có giàu, có nghèo\".","C. « có thiện, có ác ».","D. « có sang, có hèn »"],"answerLetter":"A","answerText":"A. có thế này, có thế khác\".","notes":""},{"id":459,"question":"Theo Hồ Chí Minh, Hiếu với dân thể hiện ở chỗ thương dân, tin dân, phục vụ nhân dân hết lòng. Vì thế, phải gần dân, kính trọng và học tập nhân dân, phải dựa vào dân và lấy:","options":["A. dân làm gốc.","B. dân làm chỗ dựa.","C. dân làm điểm tựa."],"answerLetter":"A","answerText":"A. dân làm gốc.","notes":""},{"id":460,"question":"Theo Hồ Chí Minh: \"Trong bầu trời không gì quý bằng nhân dân, trong thế giới không gì mạnh bằng:","options":["A. lực lượng đoàn kết của nhân dân\".","B. lực lượng đoàn kết của nông dân\".","C. lực lượng đoàn kết của công nhân\"."],"answerLetter":"A","answerText":"A. lực lượng đoàn kết của nhân dân\".","notes":""},{"id":461,"question":"Hồ Chí Minh cho rằng: \"Học để làm việc, (....) , làm cán bộ\"","options":["A. Làm thầy","B. Làm cách mạng","C. Làm người","D. Làm đầy tớ"],"answerLetter":"C","answerText":"C. Làm người","notes":""},{"id":462,"question":"Nội dung nào đúng về năm điểm lớn định hướng cho việc xây dựng nền văn hóa dân tộc theo tư tưởng Hồ Chí Minh?","options":["A. Xây dựng luân lý, tâm lý, xã hội, chính trị, kinh tế","B. Xây dựng luân lý, tâm lý, xã hội, chính trị, luật pháp","C. Xây dựng luân lý, tâm lý, xã hội, chính trị, khoa học"],"answerLetter":"A","answerText":"A. Xây dựng luân lý, tâm lý, xã hội, chính trị, kinh tế","notes":""},{"id":463,"question":"Đạo đức được Hồ chí Minh coi là gì của người cách mạng?","options":["A. Là sức mạnh của người cách mạng","B. Là cái gốc của người cách mạng","C. Là văn hóa của người cách mạng","D. Tất cả các phương án"],"answerLetter":"B","answerText":"B. Là cái gốc của người cách mạng","notes":""},{"id":464,"question":"Hồ Chí Minh xác định trong thế giới không có gì mạnh bằng:","options":["A. Giai cấp công nhân","B. Liên minh công - nông","C. Lực lượng đoàn kết của nhân dân","D. Sức mạnh đoàn kết quốc tế"],"answerLetter":"C","answerText":"C. Lực lượng đoàn kết của nhân dân","notes":""},{"id":465,"question":"Theo Hồ Chí Minh, để thực hiện chiến lược \"trồng người\", cần có nhiều biện pháp, nhưng biện pháp quan trọng bậc nhất là:","options":["A. Giáo dục - đào tạo","B. Thuyết phục - nêu gương","C. Cảm hóa - động viên","D. Ép buộc - cưỡng chế"],"answerLetter":"A","answerText":"A. Giáo dục - đào tạo","notes":""},{"id":466,"question":"Đâu là nguyên tắc đoàn kết quốc tế trong tư tưởng Hồ Chí Minh?","options":["A. Đoàn kết trên cơ sở độc lập, tự chủ, tự lực, tự cường.","B. Đoàn kết trên cơ sở dựa vào sức mình là chính, nhận sự giúp đỡ quốc tế.","C. Đoàn kết trên cơ sở nhận sự giúp đỡ quốc tế và có nghĩa vụ quốc tế.","D. Đoàn kết trên cơ sở kêu gọi sự giúp đỡ của các lực lượng tiến bộ trên thế giới"],"answerLetter":"A","answerText":"A. Đoàn kết trên cơ sở độc lập, tự chủ, tự lực, tự cường.","notes":""},{"id":467,"question":"Theo Hồ Chí Minh, để quy tụ được mọi lực lượng vào khối đại đoàn kết toàn dân, cần phải có:","options":["A. Chính sách và phương pháp phù hợp.","B. Lòng khoan dung rộng lớn.","C. Tinh thần thương yêu con người."],"answerLetter":"A","answerText":"A. Chính sách và phương pháp phù hợp.","notes":""},{"id":468,"question":"Lực lượng chủ yếu của khối đại đoàn kết dân tộc theo tư tưởng Hồ Chí Minh là:","options":["A. Công nhân","B. Công nhân, nông dân","C. Học trò, nhà buôn","D. Công nhân, nông dân, lao động trí óc."],"answerLetter":"D","answerText":"D. Công nhân, nông dân, lao động trí óc.","notes":""},{"id":469,"question":"Hồ Chí Minh cho rằng","options":["A. Đại đoàn kết là vấn đề chiến lược","B. Đại đoàn kết là vấn đề sách lược","C. Đại đoàn kết là vấn đề thời đại"],"answerLetter":"A","answerText":"A. Đại đoàn kết là vấn đề chiến lược","notes":""},{"id":470,"question":"Theo Hồ Chí Minh, để thực hành đoàn kết rộng rãi, cần có niềm tin vào (....).","options":["A. Dân","B. Đảng","C. Chính quyền"],"answerLetter":"A","answerText":"A. Dân","notes":""},{"id":471,"question":"Theo Hồ Chí Minh, để lãnh đạo mặt trận, Đảng phải:","options":["A. Có chính sách mặt trận đúng đắn","B. Có chính sách đoàn kết đúng đắn","C. Có chính sách tập hợp đúng đắn"],"answerLetter":"A","answerText":"A. Có chính sách mặt trận đúng đắn","notes":""},{"id":472,"question":"Mục đích chung củ","options":["A. Mặt trận dân tộc thống nhất được Hồ Chí Minh xác định cụ thể phù hợp là:a. Đoàn kết chặt chẽ, lâu dài, thật sự, chân thành.","B. Tất cả các phương án.","C. Độc lập, tự do."],"answerLetter":"C","answerText":"C. Độc lập, tự do.","notes":""},{"id":473,"question":"Theo Hồ Chí Minh, \"Đoàn kết là (.....). Điểm này mà thực hiện tốt thì đẻ ra con cháu đều tốt\".","options":["A. Điểm mẹ","B. Điểm quyết định","C. Điểm thắng lợi","D. Điểm bố"],"answerLetter":"A","answerText":"A. Điểm mẹ","notes":""},{"id":474,"question":"Luận điểm \"Lao động tất cả các nước đoàn kết lại\" là củ","options":["A. a. C. Mác","B. Ph. Ăngghen","C. V.I.Lênin","D. Hồ Chí Minh"],"answerLetter":"D","answerText":"D. Hồ Chí Minh","notes":""},{"id":475,"question":"Đối với phong trào cộng sản và công nhân, quốc tế, Hồ Chí Minh giương cao ngọn cờ độc lập dân tộc gắn liền với chủ nghĩa xã hội, thực hiện đoàn kết thống nhất trên nền tảng của chủ nghĩ","options":["A. Mác-Lênin và:a. Chủ nghĩa Mác - Lênin, có lý, có tình.","B. Chủ nghĩa quốc tế vô sản, có tình, có nghĩa.","C. Chủ nghĩa quốc tế vô sản, có lý, có tình.","D. Chủ nghĩa yêu nước, có tình, có nghĩa"],"answerLetter":"C","answerText":"C. Chủ nghĩa quốc tế vô sản, có lý, có tình.","notes":""},{"id":476,"question":"Theo Hồ Chí Minh, thực hiện đại đoàn kết dân tộc phải gắn liền với đoàn kết quốc tế đại đoàn kết dân tộc phải là:","options":["A. Cơ sở cho việc thực hiện đoàn kết quốc tế.","B. Chỗ dựa cho việc thực hiện đoàn kết quốc tế.","C. Chỗ đứng cho việc thực hiện đoàn kết quốc tế"],"answerLetter":"A","answerText":"A. Cơ sở cho việc thực hiện đoàn kết quốc tế.","notes":"(Kiểu hỏi khác: Theo Hồ Chí Minh thực hiện đại đoàn kết dân tộc phải gắn liền với đoàn kết quốc tế nhằm mục đích gì?\nA. Giữ gìn sức mạnh dân tộc\nB. Giữ gìn sức mạnh thời đại\nC. Tăng cường sức mạnh thời đại\nD. Tạo sức mạnh tổng hợp cho cách mạng chiến thắng kẻ thù)"},{"id":477,"question":"Theo Hồ Chí Minh, Mặt trận dân tộc thống nhất phải được xây dựng trên nền tảng khối liên minh công - nông - trí thức, đặt dưới:","options":["A. Sự lãnh đạo của Đảng.","B. Sự lãnh đạo của tổ chức","C. Sự lãnh đạo của chính quyền"],"answerLetter":"A","answerText":"A. Sự lãnh đạo của Đảng.","notes":""},{"id":478,"question":"Đối với Hồ Chí Minh, phải biết \"dễ (1....) lần không dân cũng chịu, khó (2....) lần dân liệu cũng xong\".","options":["A. 1.vạn 2.trăm","B. 1.trăm 2.vạn","C. 1.nghìn 2.triệu","D. 1.triệu 2.nghìn"],"answerLetter":"B","answerText":"B. 1.trăm 2.vạn","notes":""},{"id":479,"question":"Sức mạnh dân tộc trong tư tưởng Hồ Chí Minh bao gồm:","options":["A. Chủ nghĩa yêu nước và văn hóa truyền thống Việt Nam.","B. Tinh thần đoàn kết, ý thức đấu tranh cho độc lập, tự do.","C. Ý thức tự lực, tự cường.","D. Tất cả các phương án"],"answerLetter":"D","answerText":"D. Tất cả các phương án","notes":""},{"id":480,"question":"Theo Hồ Chí Minh hình thức tổ chức của khối đại đoàn kết dân tộc là:","options":["A. Mặt trận dân tộc thống nhất","B. Cá","C. đoàn thể quần chúng nhân dânc. Đảng Cộng sản","D. Chính quyền"],"answerLetter":"A","answerText":"A. Mặt trận dân tộc thống nhất","notes":""},{"id":481,"question":"Hồ Chí Minh khái quát dân chủ có nghĩa là gì?","options":["A. Dân là chủ và dân làm chủ","B. Dân là người chủ","C. Dân làm quản lý","D. Dân làm người chủ"],"answerLetter":"A","answerText":"A. Dân là chủ và dân làm chủ","notes":""},{"id":482,"question":"Theo Hồ Chí Minh, Nhà nước vì dân là một Nhà nước lấy lợi ích chính đáng của nhân dân làm mục tiêu, tất cả đều vì lợi ích của nhân dân, ngoài r","options":["A. a. Không có bất cứ một lợi ích nào khác.","B. Chỉ có lợi ích tự thân của Nhà nướ","C. c. Không có bất cứ lợi ích không chính đáng nào khác."],"answerLetter":"A","answerText":"A. a. Không có bất cứ một lợi ích nào khác.","notes":""},{"id":483,"question":"Trong tư tưởng Hồ Chí Minh, Đảng lãnh đạo nhà nước bằng:","options":["A. Đường lối, quan điểm, chủ trương","B. Pháp luật, chính sách, kế hoạch","C. Tất cả các phương án"],"answerLetter":"A","answerText":"A. Đường lối, quan điểm, chủ trương","notes":""},{"id":484,"question":"Theo Hồ Chí Minh, Đảng lãnh đạo Nhà nước bằng phương thức nào?","options":["A. Đường lối, chủ trương, chính sách.","B. Qua các tổ chứ","C. Đảng, đảng viên trong bộ máy nhà nước.c. Bằng công tác kiểm tra.","D. Tất cả các phương án."],"answerLetter":"D","answerText":"D. Tất cả các phương án.","notes":""},{"id":485,"question":"Hồ Chí Minh là đã trực tiếp chỉ đạo biên soạn Hiến pháp nào của nước ta?","options":["A. Hiến pháp năm 1946.","B. Hiến pháp năm 1959.","C. Tất cả các phương án"],"answerLetter":"C","answerText":"C. Tất cả các phương án","notes":""},{"id":486,"question":"Theo Hồ Chí Minh, dân là chủ nghĩa là:","options":["A. Đề cập tới vị trí của dân.","B. Đề cập tới vị thế của dân.","C. Đề cập tới trách nhiệm của dân.","D. Đề cập tới năng lực của dân"],"answerLetter":"B","answerText":"B. Đề cập tới vị thế của dân.","notes":""},{"id":487,"question":"Điểm đặc sắc nhất trong tư tưởng Hồ Chí Minh về Nhà nước pháp quyền là:","options":["A. Coi trọng luật pháp trong quản lý xã hội.","B. Đề cao đạo đức trong quản lý xã hội.","C. Đảm bảo tính nghiêm minh và hiệu lực của pháp luật.","D. Kết hợp nhuần nhuyễn cả pháp luật và đạo đức trong quản lý xã hội."],"answerLetter":"D","answerText":"D. Kết hợp nhuần nhuyễn cả pháp luật và đạo đức trong quản lý xã hội.","notes":""},{"id":488,"question":"Tìm ra nội dung không đúng trong tư tưởng Hồ Chí Minh về Dân chủ trong các lĩnh vực củ","options":["A. đời sống xã hội:a. Việc bảo đảm quyền con người, quyền công dân.","B. Phương thức tổ chức xã hội.","C. Kết hợp nhuần nhuyễn cả pháp luật và đạo đức trong quản lý xã hội."],"answerLetter":"C","answerText":"C. Kết hợp nhuần nhuyễn cả pháp luật và đạo đức trong quản lý xã hội.","notes":""},{"id":489,"question":"Nội dung nào không đúng với bản chất giai cấp công nhân của nhà nước theo tư tưởng Hồ Chí Minh?","options":["A. Nhà nước do Đảng Cộng sản lãnh đạo.","B. Tính định hướng xã hội chủ nghĩa của sự phát triển đất nước.","C. Nguyên tắc tổ chức và hoạt động cơ bản của nó là nguyên tắc tập trung dân chủ.","D. Nhà nước dưới sự lãnh đạo của Quốc hội."],"answerLetter":"D","answerText":"D. Nhà nước dưới sự lãnh đạo của Quốc hội.","notes":""},{"id":490,"question":"Trong một cách thể hiện khác về vấn đề \"Đảng của ai\", theo Hồ Chí Minh, Đảng là củ","options":["A. a. Giai cấp","B. Dân tộc","C. Nhân loại","D. Nhân dân"],"answerLetter":"B","answerText":"B. Dân tộc","notes":""},{"id":491,"question":"Trong các yếu tố hình thành Đảng Cộng sản Việt Nam, đâu là yếu tố sáng tạo củ","options":["A. Hồ Chí Minh?a. Chủ nghĩa Mác - Lênin","B. Phong trào công nhân","C. Tư tưởng yêu nước truyền thống","D. Phong trào yêu nước"],"answerLetter":"C","answerText":"C. Tư tưởng yêu nước truyền thống","notes":""},{"id":492,"question":"Tìm phương án giải thích sai trong luận điểm củ","options":["A. Hồ Chí Minh \"Đảng cầm quyền vừa là người lãnh đạo, vừa là người đầy tớ trung thành của nhân dân\".a. Người lãnh đạo là xác định quyền lãnh đạo duy nhất của Đảng đối với toàn bộ xã hội và khi có chính quyền, Đảng lãnh đạo chính quyền nhà nước.","B. Lãnh đạo phải bằng giáo dục, thuyết phục, nghĩa là Đảng phải làm cho dân tin, dân phụ","C. để dân theo.c. Là người lãnh đạo Đảng phải sâu sát, gắn bó mật thiết với nhân dân, lắng nghe ý kiến của dân, khiêm tốn học hỏi nhân dân và phải kiểm soát nhân dân.","D. đầy tớ\" có nghĩa là tận tâm, tận lực phụng sự nhân dân nhằm đem lại quyền lợi và lợi ích cho nhân dân."],"answerLetter":"C","answerText":"C. để dân theo.c. Là người lãnh đạo Đảng phải sâu sát, gắn bó mật thiết với nhân dân, lắng nghe ý kiến của dân, khiêm tốn học hỏi nhân dân và phải kiểm soát nhân dân.","notes":""},{"id":493,"question":"Hồ Chí Minh cho rằng: \"Một dân tộc, một đảng và mỗi con người, ngày hôm qua là vĩ đại, có sức hấp dẫn lớn, không nhất định hôm nay và ngày mai vẫn được mọi người yêu mến và ca ngợi, nếu lòng dạ không trong sáng nữa, nếu ....\".","options":["A. Sa vào tham ô, lãnh phí.","B. Sa vào chủ nghĩa cá nhân.","C. Thoái hóa biến chất."],"answerLetter":"B","answerText":"B. Sa vào chủ nghĩa cá nhân.","notes":""},{"id":494,"question":"Theo Hồ Chí Minh:","options":["A. Làm cách mạng để cải tạo xã hội cũ thành xã hội mới là một sự nghiệp vẻ vang","B. Làm cách mạng để cải tạo xã hội cũ thành xã hội mới là một công việc vẻ vang","C. Làm cách mạng để cải tạo xã hội cũ thành xã hội mới là một nghề nghiệp vẻ vang"],"answerLetter":"A","answerText":"A. Làm cách mạng để cải tạo xã hội cũ thành xã hội mới là một sự nghiệp vẻ vang","notes":""},{"id":495,"question":"Theo Hồ Chí Minh, Đảng phải thường xuyên tự đổi mới và chỉnh đốn về những mặt nào?","options":["A. Chính trị","B. Tư tưởng","C. Tổ chức","D. Tất cả các phương án"],"answerLetter":"D","answerText":"D. Tất cả các phương án","notes":""},{"id":496,"question":"Theo Hồ Chí Minh, Đảng cầm quyền vừa là người lãnh đạo, vừa là:","options":["A. người thầy trung thành của nhân dân.","B. người hầu trung thành của nhân dân.","C. người đầy tớ trung thành của nhân dân.","D. người lính trung thành của nhân dân."],"answerLetter":"C","answerText":"C. người đầy tớ trung thành của nhân dân.","notes":""},{"id":497,"question":"Theo Hồ Chí Minh, nền tảng tư tưởng củ","options":["A. Đảng Cộng sản Việt Nam là gì?a. Chủ nghĩa xã hội","B. Chủ nghĩa Mác-Lênin","C. Chủ nghĩa xã hội dân chủ","D. Chủ nghĩa Tam dân"],"answerLetter":"B","answerText":"B. Chủ nghĩa Mác-Lênin","notes":""},{"id":498,"question":"Trong hệ thống tổ chức đảng, Hồ Chí Minh rất coi trọng vai trò củ","options":["A. a. Đảng bộ.","B. Chi ủy.","C. Chi bộ."],"answerLetter":"C","answerText":"C. Chi bộ.","notes":""},{"id":499,"question":"Theo tư tưởng Hồ Chí Minh, nền tảng tư tưởng củ","options":["A. Đảng phải dựa trên:a. Chủ nghĩa Mác-Lênin.","B. Nguyên tắc tập trung dân chủ.","C. Nguyên tắc phê bình và tự phê bình.","D. Chủ nghĩa xã hội khoa học."],"answerLetter":"A","answerText":"A. Đảng phải dựa trên:a. Chủ nghĩa Mác-Lênin.","notes":""},{"id":500,"question":"Tìm ra luận điểm sai trong tư tưởng Hồ Chí Minh khi Người lưu ý tiếp nhận và vận dụng chủ nghĩa Mác - Lênin:","options":["A. Một là, việc học tập, nghiên cứu, tuyên truyền chủ nghĩa Mác - Lênin phải luôn phù hợp với từng đối tượng.","B. Hai là, việc vận dụng chủ nghĩa Mác - Lênin phải luôn luôn kiên định trong mọi hoàn cảnh.","C. Ba là, trong quá trình hoạt động, Đảng ta phải chú ý học tập, kế thừa những kinh nghiệm tốt của các đảng cộng sản khác, đồng thời Đảng ta phải tổng kết kinh nghiệm của mình để bổ sung chủ nghĩa Mác - Lênin.","D. Bốn là, Đảng ta phải tăng cường đấu tranh để bảo vệ sự trong sáng của chủ nghĩa Mác - Lênin."],"answerLetter":"B","answerText":"B. Hai là, việc vận dụng chủ nghĩa Mác - Lênin phải luôn luôn kiên định trong mọi hoàn cảnh.","notes":""},{"id":501,"question":"Theo Hồ Chí Minh, Đảng cầm quyền là Đảng tiếp tục lãnh đạo sự nghiệp cách mạng trong điều kiện Đảng lãnh đạo quần chúng nhân dân giành được quyền lực nhà nước và:","options":["A. Đảng gương mẫu lãnh đạo bộ máy nhà nước đó.","B. Đảng trực tiếp lãnh đạo bộ máy nhà nước đó.","C. Đảng khiêm nhường lãnh đạo bộ máy nhà nước đó.","D. Đảng gián tiếp lãnh đạo bộ máy nhà nước đó."],"answerLetter":"B","answerText":"B. Đảng trực tiếp lãnh đạo bộ máy nhà nước đó.","notes":""},{"id":502,"question":"Nội dung nào không đúng với tư tưởng Hồ Chí Minh về Thái độ, phương pháp tự phê bình và phê bình:","options":["A. Phải tiến hành thuờng xuyên như người ta rửa mặt hằng ngày.","B. Phải thẳng thắn, chân thành, trung thực, không nể nang, không giấu giếm và cũng không thêm bớt khuyết điểm.","C. Phải có tình đồng chí thương yêu lẫn nhau\".","D. Phải khôn khéo biến hóa cho phù hợp."],"answerLetter":"D","answerText":"D. Phải khôn khéo biến hóa cho phù hợp.","notes":""},{"id":503,"question":"Theo Hồ Chí Minh, bản chất củ","options":["A. Đảng:a. Không thay đổi khi có chính quyền trong tay.","B. Luôn thay đổi khi có chính quyền trong tay.","C. Đôi khi thay đổi khi có chính quyền trong tay.","D. Đã thay đổi khi có chính quyền trong tay."],"answerLetter":"A","answerText":"A. Đảng:a. Không thay đổi khi có chính quyền trong tay.","notes":""},{"id":504,"question":"Đối với Hồ Chí Minh, muôn việc thành công hay thất bại là do:","options":["A. Cán bộ giỏi hay dốt","B. Cán bộ tốt hay kém.","C. Công việc dễ hay khó"],"answerLetter":"B","answerText":"B. Cán bộ tốt hay kém.","notes":""},{"id":505,"question":"Theo tư tưởng Hồ Chí Minh, Đảng cộng sản Việt Nam là sản phẩm của sự kết hợp giữ","options":["A. a. Chủ nghĩa Mác-Lênin với phong trào công nhân.","B. Phong trào công nhân với phong trào yêu nướ","C. c. Chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước.","D. Chủ nghĩa Mác - Lênin với phong trào yêu nước."],"answerLetter":"C","answerText":"C. c. Chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước.","notes":""},{"id":506,"question":"\"Việc gì đã được đông người bàn bạc kỹ lưỡng rồi, kế hoạch định rõ ràng rồi, thì cần phải giao cho một người hoặc một nhóm ít người phụ trách theo kế hoạch đó mà thi hành. Như thế mới có chuyên trách, công việc mới chạy.Nếu không có ..... thì sẽ sinh cái tệ người này ủy cho người kia, người ki","options":["A. ủy cho người nọ, kết quả là không ai thi hành. Như thế thì việc gì cũng không xong\"a. Tập thể lãnh đạo","B. Cá nhân phụ trách","C. Cá nhân lãnh đạo","D. Tập thể phụ trách"],"answerLetter":"B","answerText":"B. Cá nhân phụ trách","notes":""},{"id":507,"question":"Theo Hồ Chí Minh, Đảng lãnh đạo phải bằng:","options":["A. Mệnh lệnh, đòi hỏi, yêu cầu dân chúng.","B. Dạy dỗ, chỉ bảo dân chúng.","C. Giáo dục, thuyết phục, tuyên truyền, giác ngộ dân chúng.","D. Pháp luật, kỷ luật đối với dân chúng."],"answerLetter":"C","answerText":"C. Giáo dục, thuyết phục, tuyên truyền, giác ngộ dân chúng.","notes":""},{"id":508,"question":"Theo tư tưởng Hồ Chí Minh, Đảng Cộng sản Việt Nam là Đảng củ","options":["A. a. Giai cấp công nhân.","B. Giai cấp công nhân, nhân dân lao động và của dân tộ","C. Việt Nam.c. Nhân dân lao động","D. Giai cấp công nhân, nhân dân lao động"],"answerLetter":"B","answerText":"B. Giai cấp công nhân, nhân dân lao động và của dân tộ","notes":""},{"id":509,"question":"Theo Hồ Chí Minh, Đảng không phải là một tổ chức tự thân, mà có tổ chức chặt chẽ và vì vậy, mục đích, tôn chỉ củ","options":["A. Đảng là \"tận tâm\", \"tận lực\", \"phụng sự\" và \"trung thành\" với:a. Lợi ích của dân tộc Việt Nam","B. Lợi ích của Đảng","C. Lợi ích của giai cấp công nhân"],"answerLetter":"A","answerText":"A. Đảng là \"tận tâm\", \"tận lực\", \"phụng sự\" và \"trung thành\" với:a. Lợi ích của dân tộc Việt Nam","notes":""},{"id":510,"question":"Trong tác phẩm \"Đường cách mệnh\" Hồ Chí Minh ví Đảng như:","options":["A. Kim chỉ nam","B. Người cầm lái","C. Người chỉ huy"],"answerLetter":"B","answerText":"B. Người cầm lái","notes":""},{"id":511,"question":"Theo tư tưởng Hồ Chí Minh, luận điểm Đảng Cộng sản Việt Nam là \"Đảng của giai cấp công nhân, đồng thời là Đảng của dân tộc Việt Nam\" nhằm:","options":["A. Xác định vị thế cầm quyền của Đảng.","B. Xá","C. định bản chất giai cấp của Đảng.c. Xác định chức năng của Đảng.","D. Xác định vai trò lãnh đạo của Đảng."],"answerLetter":"B","answerText":"B. Xá","notes":""},{"id":512,"question":"\"(....) có vững cách mạng mới thành công cũng như người cầm lái có vững thuyền mới chạy\"","options":["A. Đảng","B. Chính quyền","C. Lực lượng","D. Đoàn thể"],"answerLetter":"A","answerText":"A. Đảng","notes":""},{"id":513,"question":"Hồ Chí Minh dạy Cán bộ, Đảng viên phải biết:","options":["A. Làm tốt hơn nhân dân","B. Làm lợi hơn cho nhân dân","C. Học tập từ nhân dân"],"answerLetter":"B","answerText":"B. Làm lợi hơn cho nhân dân","notes":""},{"id":514,"question":"Trong di chúc của mình, Hồ Chí Minh trước tiên nói về:","options":["A. Thiếu niên, nhi đồng","B. Đảng","C. Thanh niên"],"answerLetter":"B","answerText":"B. Đảng","notes":""},{"id":515,"question":"Theo Hồ Chí Minh, việc học tập, nghiên cứu, tuyên truyền chủ nghĩ","options":["A. Mác - Lênin phải:a. Luôn phù hợp với từng đối tượng.","B. Luôn phù hợp với từng hoàn cảnh.","C. Tất cả các phương án."],"answerLetter":"A","answerText":"A. Mác - Lênin phải:a. Luôn phù hợp với từng đối tượng.","notes":""},{"id":516,"question":"Hồ Chí Minh luôn nhấn mạnh thái độ nào sau đây của Đảng viên:","options":["A. Nêu gương","B. Dũng cảm","C. Đoàn kết","D. Chí công vô tư"],"answerLetter":"A","answerText":"A. Nêu gương","notes":""},{"id":517,"question":"Theo Hồ Chí Minh, Trong xây dựng đường lối chính trị, phải học tập kinh nghiệm của các đảng cộng sản anh em, nhưng phải tính đến những điều kiện cụ thể của đất nước và của:","options":["A. Loài người.","B. Thời đại.","C. Dân tộc."],"answerLetter":"B","answerText":"B. Thời đại.","notes":""},{"id":518,"question":"Hồ Chí Minh cho rằng cán bộ, đảng viên phải lưu ý cái gì có lợi cho dân dù nhỏ đến mấy cũng phải:","options":["A. Cố mà làm","B. Phấn đấu","C. Cố gắng"],"answerLetter":"A","answerText":"A. Cố mà làm","notes":""},{"id":519,"question":"Hồ Chí Minh khẳng định sức mạnh củ","options":["A. Đảng bắt nguồn từ:a. Con người.","B. Tổ chứ","C. c. Dân tộc."],"answerLetter":"B","answerText":"B. Tổ chứ","notes":""},{"id":520,"question":"Trong tác phẩm \"Đường cách mệnh\", theo Hồ Chí Minh cách mạng trước hết phải có:","options":["A. Đảng cách mạng","B. Quần chúng cách mạng","C. Lực lượng cách mạng","D. Vũ trang cách mạng"],"answerLetter":"A","answerText":"A. Đảng cách mạng","notes":""},{"id":521,"question":"Trong các nội dung sau đâu là nội dung không đúng?","options":["A. Phong trào yêu nước có vị trí, vai trò cực kỳ to lớn trong quá trình phát triển của dân tộc Việt Nam.","B. Phong trào công nhân kết hợp được với phong trào yêu nước bởi vì hai phong trào đó đều có mục tiêu chung.","C. Phong trào yêu nước của trí thức Việt Nam là nhân tố quan trọng thúc đẩy sự kết hợp các yếu tố cho sự ra đời của Đảng Cộng sản Việt Nam.","D. Phong trào nông dân không kết hợp được với phong trào công nhân."],"answerLetter":"D","answerText":"D. Phong trào nông dân không kết hợp được với phong trào công nhân.","notes":""},{"id":522,"question":"Theo Hồ Chí Minh, nội dung quy định bản chất giai cấp công nhân là:","options":["A. Số lượng đảng viên xuất thân từ giai cấp công nhân.","B. Nền tảng lý luận và tư tưởng của Đảng là chủ nghĩa Mác - Lênin.","C. Tất cả các phương án"],"answerLetter":"B","answerText":"B. Nền tảng lý luận và tư tưởng của Đảng là chủ nghĩa Mác - Lênin.","notes":""},{"id":523,"question":"Theo Hồ Chí Minh, Là người lãnh đạo, nhưng Đảng phải sâu sát, gắn bó mật thiết với nhân dân, lắng nghe ý kiến của nhân dân, khiêm tốn học hỏi nhân dân và:","options":["A. Phải không được kiểm soát nhân dân.","B. Phải kiểm soát được nhân dân.","C. Phải chịu sự kiểm soát của nhân dân."],"answerLetter":"C","answerText":"C. Phải chịu sự kiểm soát của nhân dân.","notes":""},{"id":524,"question":"Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam phải lấy chủ nghĩ","options":["A. Mác-Lênin \"làm cốt\" nghĩa là:a. Đảng Cộng sản Việt Nam phải lấy chủ nghĩa Mác-Lênin làm nền tảng tư tưởng.","B. Đảng Cộng sản Việt Nam phải lấy chủ nghĩa Mác-Lênin làm chủ trương, đường lối.","C. Đảng Cộng sản Việt Nam phải lấy chủ nghĩa Mác-Lênin làm học thuyết của Đảng.","D. Tất cả các phương án."],"answerLetter":"A","answerText":"A. Mác-Lênin \"làm cốt\" nghĩa là:a. Đảng Cộng sản Việt Nam phải lấy chủ nghĩa Mác-Lênin làm nền tảng tư tưởng.","notes":""},{"id":525,"question":"Hồ Chí Minh chỉ ra nguyên tắc quan hệ giữ","options":["A. Đảng với dân là:a. Đảng viên, cán bộ vừa là người lãnh đạo, vừa là người đầy tớ thật trung thành của nhân dân","B. Đảng viên, cán bộ vừa là người lãnh đạo, vừa là người đầy tớ thật trung thành của người lao động.","C. Đảng viên, cán bộ vừa là người lãnh đạo, vừa là người đầy tớ thật trung thành của mọi người."],"answerLetter":"A","answerText":"A. Đảng với dân là:a. Đảng viên, cán bộ vừa là người lãnh đạo, vừa là người đầy tớ thật trung thành của nhân dân","notes":""},{"id":526,"question":"Theo Hồ Chí Minh, Mục đích phê bình là:","options":["A. Cốt để giúp nhau sửa chữa, giúp nhau tiến bộ.","B. Cốt để đổi cách làm việc cho tốt hơn, đúng hơn.","C. Cốt để đoàn kết và thống nhất nội bộ.","D. Tất cả các phương án."],"answerLetter":"D","answerText":"D. Tất cả các phương án.","notes":""},{"id":527,"question":"Trong việc tiếp nhận và vận dụng chủ nghĩ","options":["A. Mác-Lênin, Hồ Chí Minh lưu ý Đảng ta phải tăng cường đấu tranh để:a. Bảo vệ sự trong sáng của chủ nghĩa Mác - Lênin.","B. Bảo vệ sự trong sáng của Đảng Cộng sản Việt Nam.","C. Bảo vệ chính quyền.","D. Bảo vệ nhân dân."],"answerLetter":"A","answerText":"A. Mác-Lênin, Hồ Chí Minh lưu ý Đảng ta phải tăng cường đấu tranh để:a. Bảo vệ sự trong sáng của chủ nghĩa Mác - Lênin.","notes":""},{"id":528,"question":"Theo Hồ Chí Minh, chức năng lãnh đạo và sự lãnh đạo củ","options":["A. Đảng phải:a. Bảo đảm trên tất cả các mặt, các lĩnh vực, phải quan tâm chăm lo đến đời sống nhân dân ở những việc nhỏ.","B. Bảo đảm trên tất cả các mặt, các lĩnh vực, phải quan tâm chăm lo đến đời sống nhân dân từ việc nhỏ đến việc lớn.","C. Bảo đảm trên tất cả các mặt, các lĩnh vực, phải quan tâm chăm lo đến đời sống nhân dân ở những việc lớn."],"answerLetter":"B","answerText":"B. Bảo đảm trên tất cả các mặt, các lĩnh vực, phải quan tâm chăm lo đến đời sống nhân dân từ việc nhỏ đến việc lớn.","notes":""},{"id":529,"question":"Hồ Chí Minh đã dùng từ nào sau đây để chỉ tính nghiêm minh của pháp luật","options":["A. Thần linh pháp quyền","B. Tinh thần pháp luật","C. Nhà nước pháp quyền","D. Nhà nước hợp hiến"],"answerLetter":"A","answerText":"A. Thần linh pháp quyền","notes":""},{"id":530,"question":"Theo Hồ Chí Minh, văn hoá không thể đứng ngoài mà phải ở trong kinh tế và chính trị, phải:","options":["A. phục vụ nhiệm vụ kinh tế và thúc đẩy sự phát triển của chính trị.","B. phục vụ nhiệm vụ chính trị và thú","C. đẩy sự phát triển của kinh tế.c. phục vụ nhiệm vụ văn hóa và thúc đẩy sự phát triển của kinh tế, chính trị."],"answerLetter":"B","answerText":"B. phục vụ nhiệm vụ chính trị và thú","notes":""},{"id":531,"question":"Trong tư tưởng đạo đức Hồ Chí Minh, đức và tài, hồng và chuyên, phẩm chất và năng lực thống nhất làm một. Đó là đạo đức trong hành động, lấy:","options":["A. Số lượng công việc làm thước đo.","B. Hiệu quả thực tế làm thướ","C. đo.c. Chất lượng công việc làm thước đo.","D. Trình độ chuyên môn nghiệp vụ làm thước đo."],"answerLetter":"B","answerText":"B. Hiệu quả thực tế làm thướ","notes":""},{"id":532,"question":"Theo Hồ Chí Minh, tính dân tộc của nền văn hoá là đặc tính dân tộc, cốt cách dân tộc, chiều sâu bản chất rất đặc trưng của văn hoá dân tộc, không nhầm lẫn với:","options":["A. Văn hoá của các dân tộc khác.","B. Tinh hoa của các dân tộc khác.","C. Văn minh của các dân tộc khác."],"answerLetter":"A","answerText":"A. Văn hoá của các dân tộc khác.","notes":""},{"id":533,"question":"Đối với một quốc gia: cần, kiệm, liêm, chính là thước đo sự giàu có về vật chất, vững mạnh về tinh thần, thể hiện:","options":["A. Sự văn minh tiến bộ.","B. Văn hóa cao","C. Truyền thống tốt đẹp","D. Văn hiến lâu đời"],"answerLetter":"A","answerText":"A. Sự văn minh tiến bộ.","notes":"(Kiểu hỏi khác: Theo quan điểm của Hồ Chí Minh đối với một quốc gia, cần, kiệm, liêm, chính là thước đo sự giàu có về vật chất, vững mạnh về tinh thần. Quan điểm đó thể hiện điều gì?)"},{"id":534,"question":"Câu nói nào sau đây là của Hồ Chí Minh?","options":["A. Học không biết chán, dạy không biết mỏi","B. Học, học nữa, học mãi","C. Việc học không bao giờ cùng, còn sống còn phải học"],"answerLetter":"C","answerText":"C. Việc học không bao giờ cùng, còn sống còn phải học","notes":""},{"id":535,"question":"Theo Hồ Chí Minh phải chú trọng \"đạo làm gương\". Đối với Người \"một tấm gương sống còn có giá trị hơn:","options":["A. một trăm bài diễn văn tuyên truyền\",","B. một trăm hòm vàng\",","C. một trăm tủ sách\","],"answerLetter":"A","answerText":"A. một trăm bài diễn văn tuyên truyền\",","notes":""},{"id":536,"question":"Theo Hồ Chí Minh, văn hóa là đời sống tinh thần của xã hội, thuộc:","options":["A. Kiến trúc thượng tầng","B. Cơ sở hạ tầng","C. Tất cả các phương án"],"answerLetter":"A","answerText":"A. Kiến trúc thượng tầng","notes":""},{"id":537,"question":"Chiến lược trồng người được Hồ Chí Minh xác định ở vị trí nào trong sự phát triển kinh tế xã hội?","options":["A. Cơ bản","B. Trọng tâm","C. Quan trọng","D. Cần thiết"],"answerLetter":"A","answerText":"A. Cơ bản","notes":""},{"id":538,"question":"Yêu thương con người được Hồ Chí Minh xác định là một trong những phẩm chất đạo đức cao đẹp nhất. Người nói, người cách mạng là người giàu tình cảm, có tình cảm cách mạng:","options":["A. mới đi làm cách mạng.","B. mới yêu thương con người.","C. mới là người cách mạng."],"answerLetter":"A","answerText":"A. mới đi làm cách mạng.","notes":""},{"id":539,"question":"Theo Hồ Chí Minh, tính đại chúng của nền văn hoá là phải phục vụ nhân dân và do:","options":["A. Nhà nước xây dựng nên.","B. Nhân dân xây dựng thêm.","C. Nhân dân xây dựng nên.","D. Nhà nước xây dựng thêm."],"answerLetter":"C","answerText":"C. Nhân dân xây dựng nên.","notes":""},{"id":540,"question":"Tính khoa học của văn hoá đòi hỏi phải đấu tranh chống lại chủ nghĩa duy tâm, thần bí, mê tín dị đoan, phải biết gạn đục, khơi trong, là sự kế thừa truyền thống tốt đẹp của dân tộc và tiếp thu:","options":["A. Tinh hoa văn hoá nhân loại.","B. Bản sắc văn hoá nhân loại.","C. Truyền thống văn hoá nhân loại.","D. Tính dân tộc của văn hóa nhân loại."],"answerLetter":"A","answerText":"A. Tinh hoa văn hoá nhân loại.","notes":""},{"id":541,"question":"Khái niệm con người trong tư tưởng Hồ Chí Minh để chỉ:","options":["A. Một con người cụ thể.","B. Một cộng đồng người.","C. Con người cụ thể gắn với hoàn cảnh lịch sử cụ thể.","D. Tất cả các phương án."],"answerLetter":"C","answerText":"C. Con người cụ thể gắn với hoàn cảnh lịch sử cụ thể.","notes":""},{"id":542,"question":"Hồ Chí Minh xem xét con người trong sự thống nhất của hai mặt đối lập: thiện và ác, hay và dở, tốt và xấu, hiền và dữ,... nhưng:","options":["A. dù là xấu, tốt, văn minh hay dã man đều có lý\".","B. dù là xấu, tốt, văn minh hay dã man đều có tình\".","C. dù là xấu, tốt, văn minh hay dã man đều có đức\".","D. dù là xấu, tốt, văn minh hay dã man đều có học\"."],"answerLetter":"B","answerText":"B. dù là xấu, tốt, văn minh hay dã man đều có tình\".","notes":""},{"id":543,"question":"Loại giặc nào được Hồ Chí Minh đề cập đầu tiên?","options":["A. Giặc dốt","B. Giặ","C. đóic. Giặc ngoại xâm"],"answerLetter":"B","answerText":"B. Giặ","notes":""},{"id":544,"question":"Hồ Chí Minh coi chủ nghĩa dân tộc là:","options":["A. Mùa xuân của xã hội","B. Động lực lớn của đất nước","C. Nền tảng tư tưởng của Đảng"],"answerLetter":"B","answerText":"B. Động lực lớn của đất nước","notes":""},{"id":545,"question":"Hồ Chí Minh dạy: \"Hiểu chủ nghĩ","options":["A. Mác - Lênin là phải sống với nhau có tình, có nghĩa. Nếu thuộc bao nhiêu sách mà sống không có tình có nghĩa thì sao gọi là:a. Hiểu chủ nghĩa Mác - Lênin được\".","B. Học chủ nghĩa Mác - Lênin đượ","C. c. Theo chủ nghĩa Mác - Lênin được\"."],"answerLetter":"A","answerText":"A. Mác - Lênin là phải sống với nhau có tình, có nghĩa. Nếu thuộc bao nhiêu sách mà sống không có tình có nghĩa thì sao gọi là:a. Hiểu chủ nghĩa Mác - Lênin được\".","notes":""},{"id":546,"question":"Trong tác phẩm sử","options":["A. đổi lối làm việc, tháng 10-1947, Hồ Chí Minh viết: \"cũng giống như sông có nguồn mới có nước, không có nguồn thì sông cạn. Cây phải có gốc, không có gốc thì cây héo. Người cách mạng thì phải có ...., không có... thì tài giỏi đến mấy cũng không lãnh đạo được nhân dân\".a. trí tuệ","B. đạo đức","C. trình độ","D. chuyên môn"],"answerLetter":"B","answerText":"B. đạo đức","notes":""},{"id":547,"question":"Theo Hồ Chí Minh, toàn bộ những sáng tạo và phát minh của con người nhằm thích ứng nhu cầu đời sống và sinh tồn tức là:","options":["A. văn hoá.","B. truyền thống.","C. văn minh."],"answerLetter":"A","answerText":"A. văn hoá.","notes":""},{"id":548,"question":"Hồ Chí Minh cho rằng con người mới XHCN phải có:","options":["A. Đạo đức cách mạng","B. Đạo đức quần chúng","C. Đạo đức nhân dân"],"answerLetter":"A","answerText":"A. Đạo đức cách mạng","notes":""},{"id":549,"question":"Lần đầu tiên Hồ Chí Minh đưa r","options":["A. định nghĩa về văn hóa là vào thời gian nào?a. Tháng 8-1943","B. Tháng 8-1945","C. Tháng 8-1946"],"answerLetter":"A","answerText":"A. định nghĩa về văn hóa là vào thời gian nào?a. Tháng 8-1943","notes":""},{"id":550,"question":"Nguyên tắc xây dựng đạo đức mới theo tư tưởng Hồ Chí Minh gồm:","options":["A. 2 nguyên tắc.","B. 3 nguyên tắ","C. c. 4 nguyên tắc.","D. 5 nguyên tắc."],"answerLetter":"B","answerText":"B. 3 nguyên tắ","notes":""},{"id":551,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Nền văn hoá XHCN là một nền văn hoá lấy (.............) của đồng bào làm cơ sở\".","options":["A. Tự do","B. Ấm no","C. Hạnh phúc","D. Tất cả các phương án trả lời đều đúng"],"answerLetter":"C","answerText":"C. Hạnh phúc","notes":""},{"id":552,"question":"Theo Hồ Chí Minh, CNXH là một xã hội phát triển cao về:","options":["A. Văn hóa, giáo dục","B. Giáo dục, chính trị","C. Văn hóa, đạo đức","D. Chính trị, đạo đức"],"answerLetter":"C","answerText":"C. Văn hóa, đạo đức","notes":""},{"id":553,"question":"Hồ Chí Minh quan niệm mục tiêu cao nhất của chủ nghĩa xã hội là:","options":["A. Nâng cao đời sống nhân dân.","B. Nâng cao đời sống tinh thần cho nhân dân.","C. Nâng cao đời sống vật chất cho nhân dân."],"answerLetter":"A","answerText":"A. Nâng cao đời sống nhân dân.","notes":""},{"id":554,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"CNXH là một chế độ xã hội có nền kinh tế phát triển cao, dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về các tư liệu sản xuất chủ yếu, nhằm không ngừng nâng cao đời sống vật chất và tinh thần cho nhân dân, trước hết là cho (........)\"","options":["A. Con người","B. Dân tộc","C. Giai cấp công nhân","D. Nhân dân lao động"],"answerLetter":"D","answerText":"D. Nhân dân lao động","notes":""},{"id":555,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Tiến lên CNXH là bước phát triển tất yếu ở Việt Nam sau khi nước nhà đã giành được (.........) theo con đường cách mạng vô sản.","options":["A. Tự do","B. Bình đẳng","C. Độc lập","D. Tất cả các phương án trả lời đều đúng trả lời đều đúng"],"answerLetter":"C","answerText":"C. Độc lập","notes":""},{"id":556,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh: \"Kẻ thù muốn đè bẹp ta về kinh tế thay bằng (...........), vì vậy ta phải phát triển kinh tế\".","options":["A. Chính trị","B. Quân sự","C. Ngoại giao","D. Văn hóa"],"answerLetter":"B","answerText":"B. Quân sự","notes":""},{"id":557,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh: \"Chỉ có chủ nghĩa cộng sản mới cứu (........), đem lại cho mọi người không phân biệt chủng tộc và nguồn gốc sự tự do, bình đẳng, bác ái, đoàn kết, ấm no trên quả đất, việc làm cho mọi người và vì mọi người, niềm vui, hòa bình, hạnh phúc...\"","options":["A. Con người","B. Loài người","C. Nhân dân","D. Nhân loại"],"answerLetter":"D","answerText":"D. Nhân loại","notes":""},{"id":558,"question":"Mục tiêu giải phóng dân tộc theo con đường cách mạng vô sản mà Hồ Chí Minh đã lựa chọn cho dân tộc Việt Nam là:","options":["A. Nước nhà độc lập.","B. Nhân dân được hưởng cuộc sống ấm no, tự do, hạnh phú","C. c. Tất cả các phương án trả lời đều đúng"],"answerLetter":"C","answerText":"C. c. Tất cả các phương án trả lời đều đúng","notes":""},{"id":559,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"CNXH là công trình tập thể của (...........), do nhân dân tự xây dựng lấy dưới sự lãnh đạo củ","options":["A. Đảng\".a. Nhà nước","B. Nhân dân","C. Chính quyền","D. Cộng đồng"],"answerLetter":"B","answerText":"B. Nhân dân","notes":""},{"id":560,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"CNXH là một xã hội (..........) làm nhiều hưởng nhiều, làm ít hưởng ít, không làm thì không được hưởng các dân tộc đều bình đẳng, miền núi được giúp đỡ để tiến kịp miền xuôi\".","options":["A. Công bằng, dân chủ","B. Công bằng, bình đẳng","C. Công bằng, hợp lý","D. Công bằng, đạo đức"],"answerLetter":"C","answerText":"C. Công bằng, hợp lý","notes":""},{"id":561,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Động lực văn hoá, khoa học, giáo dục là động lực (......) không thể thiếu của chủ nghĩa xã hội\".","options":["A. Quyết định","B. Vật chất","C. Tinh thần","D. Vật chất và tinh thần"],"answerLetter":"C","answerText":"C. Tinh thần","notes":""},{"id":562,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Trong sự nghiệp xây dựng CNXH, chúng ta chưa có kinh nghiệm, nhất là về lĩnh vực (...........). Nó là công việc hết sức mới mẻ nên ta phải vừa làm, vừa học và có thể có vấp váp, thiếu sót\".","options":["A. Chính trị","B. Quân sự","C. Kinh tế","D. Văn hóa"],"answerLetter":"C","answerText":"C. Kinh tế","notes":""},{"id":563,"question":"Điền vào chỗ trống theo tư tưởng Hồ Chí Minh:\"Dân là chủ thì Chính phủ phải là (............ ). Nếu Chính phủ làm hại dân thì dân có quyền đuổi Chính phủ\".","options":["A. Tôi tớ","B. Đầy tớ","C. Người lãnh đạo","D. Người hầu"],"answerLetter":"B","answerText":"B. Đầy tớ","notes":""},{"id":564,"question":"Hồ Chí Minh khẳng định: \"Nếu không có nhân dân thì Chính phủ không đủ lực lượng. Nếu không có Chính phủ, thì nhân dân không ai:","options":["A. Đầy tớ","B. Ủng hộ","C. Dẫn đường","D. Phục vụ"],"answerLetter":"C","answerText":"C. Dẫn đường","notes":""},{"id":565,"question":"Theo Hồ Chí Minh, dân làm chủ, nghĩa là đề cập đến:","options":["A. Vị thế của dân","B. Năng lực và trách nhiệm của dân","C. Cả a và b"],"answerLetter":"B","answerText":"B. Năng lực và trách nhiệm của dân","notes":""},{"id":566,"question":"Bảo đảm dân chủ trong việc xác lập quyền lực của nhân dân.","options":["A. Phải làm cho dân có ăn","B. Phải làm cho dân có mặc","C. Phải làm cho dân có chỗ ở","D. Phải làm cho dân được học hànhe. Tất cả các phương án"],"answerLetter":"A","answerText":"A. Phải làm cho dân có ăn","notes":"e\nTheo Hồ Chí Minh, có bảo đảm và phát huy ......... ở trong Đảng thì mới bảo đảm được dân chủ của toàn xã hội.a. Dân chủb. Bình đẳngc. Tự dod. Bác ái"},{"id":567,"question":"Theo Hồ Chí Minh, giải phóng phụ nữ để .......... với nam giới, thực sự tham gia tích cực vào các công việc xã hội.","options":["A. Tự do","B. Công bằng","C. Bình đẳng","D. Dân chủ"],"answerLetter":"C","answerText":"C. Bình đẳng","notes":""},{"id":568,"question":"Điền vào chỗ trống để hoàn thiện câu nói sau củ","options":["A. Hồ Chí Minh:\"Nước ta là nước (..........) , địa vị cao nhất là dân, vì dân là chủ\".a. Tự do","B. Tự chủ","C. Dân chủ","D. Bình đẳng"],"answerLetter":"C","answerText":"C. Dân chủ","notes":""},{"id":569,"question":"Theo Hồ Chí Minh, tất cả các cơ quan Nhà nước phải dựa vào nhân dân, liên hệ chặt chẽ với nhân dân, lắng nghe ý kiến và chịu sự:","options":["A. Kìm kẹp của nhân dân","B. Giáo dục của nhân dân","C. Kiểm soát của Đảng","D. Kiểm soát của nhân dân"],"answerLetter":"D","answerText":"D. Kiểm soát của nhân dân","notes":""},{"id":570,"question":"Hồ Chí Minh cho rằng:Muốn khẳng định là một nước dân chủ thì phải có cấu tạo quyền lực xã hội mà ở đó người dân, cả trực tiếp, cả gián tiếp qua dân chủ đại diện, một hệ thống chính trị do:","options":["A. Đảng cử ra\" và \"do Đảng tổ chức nên\"\"","B. Nhà nước cử ra\" và \"do Nhà nước tổ chức nên\"\"","C. Mặt trận Tổ quốc cử ra\" và \"do Mặt trận Tổ quốc tổ chức nên\"\"","D. dân cử ra"],"answerLetter":"D","answerText":"D. dân cử ra","notes":""},{"id":571,"question":"Theo Hồ Chí Minh, dân chủ thể hiện trên lĩnh vực nào là quan trọng nhất, nổi bật nhất ?","options":["A. Chính trị","B. Kinh tế","C. Văn Hóa","D. Xã hội"],"answerLetter":"A","answerText":"A. Chính trị","notes":""},{"id":572,"question":"Theo Hồ Chí Minh, Nhà nước do dân tạo ra và nhân dân tham gia quản lý là ở chỗ: toàn bộ công dân bầu ra .........., cơ quan quyền lực cao nhất củ","options":["A. Nhà nước, cơ quan duy nhất có quyền lập pháp.a. Đảng","B. Nhà nước","C. Quốc hội","D. Chủ tịch nước"],"answerLetter":"C","answerText":"C. Quốc hội","notes":""},{"id":573,"question":"Theo Hồ Chí Minh, dân chủ thể hiện ở việc bảo đảm quyền:","options":["A. Con người, quyền giai cấp","B. Con người, quyền nhân dân","C. Con người, quyền dân tộc","D. Con người, quyền công dân"],"answerLetter":"D","answerText":"D. Con người, quyền công dân","notes":""},{"id":574,"question":"Trong luận điểm về cách mạng giải phóng dân tộc, chỉ ra luận điểm sai về con đường, biện pháp , lực lượng và phương pháp cách mạng của Hồ Chí Minh ?","options":["A. Cách mạng giải phóng dân tộc muốn thắng lợi phải đi theo con đường cách mạng vô sản","B. Cách mạng giải phóng dân tộc, trong điều kiện của Việt Nam, muốn thắng lợi phải do Đảng Cộng sản lãnh đạo","C. Cách mạng giải phóng dân tộc phải dựa trên lực lượng đại đoàn kết dân tộc, lấy liên minh công - nông- trí làm nền tảng","D. Cách mạng giải phóng dân tộc cần chủ động, sáng tạo, có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc"],"answerLetter":"B","answerText":"B. Cách mạng giải phóng dân tộc, trong điều kiện của Việt Nam, muốn thắng lợi phải do Đảng Cộng sản lãnh đạo","notes":""},{"id":575,"question":"Hồ Chí Minh cho rằng:","options":["A. Vấn đề dân tộc và vấn đề giai cấp là quan hệ chính trị","B. Vấn đề dân tộc và vấn đề giai cấp là quan hệ kinh tề","C. Vấn đề dân tộc và vấn đề giai cấp là quan hệ thể hiện trong mọi mặt của xã hội"],"answerLetter":"C","answerText":"C. Vấn đề dân tộc và vấn đề giai cấp là quan hệ thể hiện trong mọi mặt của xã hội","notes":""},{"id":576,"question":"Khái niệm \"Đảng cầm quyền\" được Hồ Chí Minh sử dụng trong tác phẩm nào?","options":["A. Chánh cương vắn tắt của Đảng","B. Tuyên ngôn Độc lập","C. Sữa đổi lối làm việc","D. Di chúc"],"answerLetter":"D","answerText":"D. Di chúc","notes":""},{"id":577,"question":"Theo Hồ Chí Minh:","options":["A. Đại đoàn kết dẫn tộc là truyền thống quý báu của dân tộc ta","B. Đoàn kết dẫn tộc là cốt lỗi của truyền thống dẫn tộc","C. Đại đoàn toàn dân là cốt lỡi của chủ nghĩa yêu nước"],"answerLetter":"A","answerText":"A. Đại đoàn kết dẫn tộc là truyền thống quý báu của dân tộc ta","notes":""},{"id":578,"question":"Một trong những nội dung chính trong thực hiện cách mạng nước ta hiện nay là:","options":["A. Độc lập dân tộc gắn liên với bảo vệ chủ quyền","B. Độc lập dân tộc gắn liên chủ nghĩa xã hội","C. Dân tộc giải phóng, cách mạng thành công","D. Dân tộc và giai cấp"],"answerLetter":"B","answerText":"B. Độc lập dân tộc gắn liên chủ nghĩa xã hội","notes":""},{"id":579,"question":"Theo Hồ Chí Minh, \"kẻ thù hung ác của chủ nghĩa xã hội\" là:","options":["A. Chủ nghĩa dân tộc","B. Chủ nghĩa đế quốc","C. Chủ nghĩa cá nhân","D. Chủ nghĩa tư bàn"],"answerLetter":"C","answerText":"C. Chủ nghĩa cá nhân","notes":""},{"id":580,"question":"Hoàn thành luận điểm sau: Hồ Chí Minh luôn đứng trên lập trưởng của... để giải quyết vẫn đề dân tộc.","options":["A. Đảng cộng sản","B. Giai cấp","C. Liên minh giai cấp","D. Người yêu nước"],"answerLetter":"B","answerText":"B. Giai cấp","notes":""},{"id":581,"question":"Nguyễn Sinh Cung theo cha lần đầu tiên đến Huế vào thời gian nào?","options":["A. Từ năm 1895 đến năm 1901","B. Từ năm 1896 đến năm 1906","C. Từ năm 1896 đến năm 1901","D. Từ năm 1895 đến năm 1905"],"answerLetter":"A","answerText":"A. Từ năm 1895 đến năm 1901","notes":""},{"id":582,"question":"Luật cải cách ruộng đất quy định nội dung nào?","options":["A. Nghiêm cấm việc tiến hành bắt giữ và giết hại nhân dân, nghiêm cấm đánh đập, tra tấn hoặc dùng mọi thứ nhục hình khác","B. Nghiêm cấm việc tiến hành bắt giữ và giết hại trái phép, nghiêm cấm đánh đập, tra tẫn hoặc dùng mọi thứ nhục hình khác","C. Phân chia ruộng đất cho dẫn cày, dân nghèo, không can thiệp vào sản xuất","D. Từ hình toàn bộ bọn Việt gian, phần động, cường hào gian ác và những kẻ chống lại hoặc phá hoại cải cách ruộng đất"],"answerLetter":"B","answerText":"B. Nghiêm cấm việc tiến hành bắt giữ và giết hại trái phép, nghiêm cấm đánh đập, tra tẫn hoặc dùng mọi thứ nhục hình khác","notes":""},{"id":583,"question":"Đâu là nguyên tắc đoàn kết quốc tế trong tư tưởng Hồ Chí Minh","options":["A. Đảm bảo mục tiêu độc lập của dân tộc mình và mục tiêu thời đại.","B. Đảm bảo mục tiêu độc lập của dân tộc mình và mục tiêu của nhân loại","C. Đảm bảo mục tiêu độc lập của dân tộc mình và mục tiêu đại chúng."],"answerLetter":"A","answerText":"A. Đảm bảo mục tiêu độc lập của dân tộc mình và mục tiêu thời đại.","notes":""},{"id":584,"question":"Trong nghiên cứu tư tưởng Hồ Chí Minh, cần quán triệt quan điểm nào dưới đây?","options":["A. Quan điểm bộ phận","B. Quan điểm chinh thể","C. Quan điểm toàn diện","D. Quan điểm toàn cục"],"answerLetter":"C","answerText":"C. Quan điểm toàn diện","notes":""},{"id":585,"question":"Để bảo đảm thực hiện thắng lợi chủ nghĩa xã hội ở Việt Nam trong thời kỳ quá độ, theo Hồ Chí Minh phải:","options":["A. Giữ vững và tăng cường vai trò lãnh đạo của Đảng; nâng cao vai trò quản lý của nhà nước.","B. Phát huy tính tích cực, chủ động của các tổ chức chính trị-xã hội; xây dựng đội ngũ cán bộ đủ đức và tài.","C. Phát huy tính tích cực, chủ động của đội ngũ cán bộ, quản lý, kế cà các cá nhân đang định cư ở nước ngoài","D. Phát huy vai trò làm chủ của Đảng, nâng cao vai trò quản lý của nhà nước"],"answerLetter":"A","answerText":"A. Giữ vững và tăng cường vai trò lãnh đạo của Đảng; nâng cao vai trò quản lý của nhà nước.","notes":""},{"id":586,"question":"Theo Hồ Chí Minh, nguyên tắc phân phối chủ yếu trong chủ nghĩa xã hội là gì?","options":["A. Làm theo năng lực, hưởng theo nhu cầu","B. Làm nhiêu hưởng nhiều, làm ít hưởng ít, không làm không hưởng","C. Phân phối bình quân cho tất cả mọi người","D. Phân phối theo thoa thuận"],"answerLetter":"B","answerText":"B. Làm nhiêu hưởng nhiều, làm ít hưởng ít, không làm không hưởng","notes":""},{"id":587,"question":"Hồ Chí Minh khẳng định: \"Chính vì Đảng Lao động Việt Nam là Đảng của giai cấp công nhân động, cho nên nó phải là Đảng của dân tộc Việt Nam\". Luận điểm này được trích trong tác phẩm nào?","options":["A. Tuyên ngôn độc lập","B. Lời kêu gọi toàn quốc kháng chiến","C. Báo cáo chính trị tại Đại hội Đại biểu toàn quốc lần thứ II của Đảng","D. Đường Cách mệnh"],"answerLetter":"C","answerText":"C. Báo cáo chính trị tại Đại hội Đại biểu toàn quốc lần thứ II của Đảng","notes":""},{"id":588,"question":"Theo Hồ Chí Minh, đầu là lực lương lãnh đạo Mặt trân dân tộc thống nhất?","options":["A. Nhà nước","B. Đảng Cộng sản","C. Chính phù","D. Quốc hội"],"answerLetter":"B","answerText":"B. Đảng Cộng sản","notes":""},{"id":589,"question":"Nội dung lớn trong nguyên tắc xây dựng các mối quan hệ quốc tế đó của Hồ Chí Minh đó là","options":["A. Làm bạn với tất cả mọi nước dân chủ và không gây thù oán với một ai","B. Xây dựng mối quan hệ hòa bình, hữu nghị, hợp tác với nhân dân lao động các nước trên","C. Hợp tác quốc tế trên cơ sở giữ vững toàn vẹn lãnh thổ","D. Liên kết phong trào đấu tranh của nhân dân Việt Nam với phong trào đấu tranh của nhân toàn thế giới"],"answerLetter":"A","answerText":"A. Làm bạn với tất cả mọi nước dân chủ và không gây thù oán với một ai","notes":""},{"id":590,"question":"Theo Hồ Chí Minh, chủ nghĩa cá nhân, lợi mình hại người, tự do vô tổ chức, vô kỷ luật và những tính xấu khác được coi là:","options":["A. Kẻ địch nguy hiểm của chủ nghĩa xã hội\"","B. Đối lập với chủ nghĩa xã hội\"","C. Cần loại bò trong chủ nghĩa xã hội\"","D. Không thuộc vẽ chủ nghĩa xã hội\""],"answerLetter":"A","answerText":"A. Kẻ địch nguy hiểm của chủ nghĩa xã hội\"","notes":""},{"id":591,"question":"Quan điểm nào dưới đây thuộc về bản chất của chủ nghĩa xã hội trong tư tưởng Hồ Chí Minh như thế nào?","options":["A. Có nền kinh tế, văn hóa, xã hội, đạo đức phát triến","B. Có nền kinh tế, văn hóa, và con người phát triển","C. Có nền kinh tế, văn hóa phát triển","D. Có nền kinh tế và đạo đức phát triển"],"answerLetter":"A","answerText":"A. Có nền kinh tế, văn hóa, xã hội, đạo đức phát triến","notes":""},{"id":592,"question":"Theo hồ chí minh, để kiểm soát quyền lực nhà nước trước tiên cần phải làm gì?","options":["A. Phát huy vai trò giám sát của dân chúng","B. Phát huy vai trò, trách nhiệm của Đảng Cộng Sản","C. Tăng cường vai trò giám sát của hội động nhân dân","D. Tăng cường trách nhiệm của mặt trận tổ quốc"],"answerLetter":"A","answerText":"A. Phát huy vai trò giám sát của dân chúng","notes":""},{"id":593,"question":"Hồ Chí Minh công tác tại Viện nghiên cứu các vấn đề dân tộc và thuộc địa (ở số nhà 25 đại lộ Tvéckaia, Liên Xô) vào thời gian:","options":["A. 1923","B. 1932","C. 1934","D. 1936"],"answerLetter":"D","answerText":"D. 1936","notes":""},{"id":594,"question":"Hồ Chí Minh cho rằng","options":["A. Văn hoá vừa là mục tiêu, vừa là động lực của cách mạng => chăm lo đời sống vật chất và tinh thần của nhân dân","B. Văn hoá vừa là cơ sở, vừa là động lực của cách mạng => chăm lo đời sống vật chất và tinh thần của nhân dân","C. Văn hoá vừa là mục tiêu, vừa là nhân tố quyết định của cách mạng => chăm lo đời sống vật chất và tinh thần của nhân dân"],"answerLetter":"A","answerText":"A. Văn hoá vừa là mục tiêu, vừa là động lực của cách mạng => chăm lo đời sống vật chất và tinh thần của nhân dân","notes":""},{"id":595,"question":"Pháp quyền nhân nghĩa được hiểu là:","options":["A. Nhà nước phải tôn trọng, đảm bảo thực hiện đây đủ quyền con người, chăm lo đến lợi ích của mọi người","B. Nhà nước phải tôn trọng nhũng quyền tự do cá nhân, vì lợi ích của con người","C. Nhà nước phải đàm bảo tính nhân văn trong pháp luật, quan tâm đến lợi ích mỗi người","D. Nhà nước phải tôn trọng những quyền tự do cá nhân vì mục đích nhân văn cao cả"],"answerLetter":"A","answerText":"A. Nhà nước phải tôn trọng, đảm bảo thực hiện đây đủ quyền con người, chăm lo đến lợi ích của mọi người","notes":""},{"id":596,"question":"Hồ Chí Minh xác định huy hiệu của thanh niên là:","options":["A. Tay cầm cờ đỏ sao vàng tiến lên","B. Tây cầm súng tiến lên","C. Tay cầm khẩu hiệu tiến lên"],"answerLetter":"A","answerText":"A. Tay cầm cờ đỏ sao vàng tiến lên","notes":""},{"id":597,"question":"Trong xã hội hiện nay, vận dụng tư tưởng HCM về đạo đức cán bộ có còn phù hợp không?","options":["A. Có. Vì tư tưởng của Người vẫn mang tính thời sự","B. Không. Vì tư tưởng của Người đã không còn phù hợp","C. Có. Vì tư tưởng của Người luôn mang tính thời sự vì vậy phải áp dụng phù hợp với từng nước.","D. Không. Vì cán bộ hiện nay đều được rèn luyện đạo đức cách mạng trước khi thực hiện đặc biệt và thấm nhuần chủ nghĩa Mác-Lênin"],"answerLetter":"C","answerText":"C. Có. Vì tư tưởng của Người luôn mang tính thời sự vì vậy phải áp dụng phù hợp với từng nước.","notes":""},{"id":598,"question":"Theo Hồ Chí Minh, nhiệm vụ lịch sử của thời kỳ quá độ ở nước ta là phải:","options":["A. Xóa bỏ những tàn tích của chế độ xã hội cũ, xây dựng các giá trị mới phù hợp trên tất cà các lĩnh vực đời sống xã hội","B. Củng cố và phát triển các giá trị của xã hội cũ vẫn còn phù hợp để xây dựng chủ nghĩa xã hội","C. Đấu tranh cải tạo, xóa bỏ tàn tích của chế độ xã hội cũ, xây dựng các yếu tố mỗi phù hợp với quy luật tiến lên chủ nghĩa xã hội trên tất cả các lĩnh vực đời sống","D. Cải cách xã hội, kiên quyết đấu tranh bải trữ các giá trị của xã hội cũ để xây dựng chủ nghĩa xã hội trên tất cả các lĩnh vực đời sống"],"answerLetter":"C","answerText":"C. Đấu tranh cải tạo, xóa bỏ tàn tích của chế độ xã hội cũ, xây dựng các yếu tố mỗi phù hợp với quy luật tiến lên chủ nghĩa xã hội trên tất cả các lĩnh vực đời sống","notes":""},{"id":599,"question":"Vận dụng tư tưởng Hồ Chí Minh trong chiến lược đoàn kết quốc tế thì bộ phận nào là hạt nhân đoàn kết dân tộc và đoàn kết quốc tế?","options":["A. Đảng Cộng sản Việt Nam","B. Nhà nước","C. Đoàn thanh niên","D. Mặt trận tổ quốc"],"answerLetter":"A","answerText":"A. Đảng Cộng sản Việt Nam","notes":""},{"id":600,"question":"Điền vào chỗ trống: Theo Nguyễn Ái Quốc \"Công nông là gốc cách mạng, còn học trò, địa chủ nhỏ, nhà buôn nhỏ là... của cách mạng\"?","options":["A. Liên minh","B. Bầu bạn","C. Đồng minh","D. Bạn bè"],"answerLetter":"B","answerText":"B. Bầu bạn","notes":""},{"id":601,"question":"Hồ Chí Minh khẳng định: \"Văn hoá phải soi đường cho quốc dân đi\" là nói đến vấn đề gì?","options":["A. Văn hoá là tiêu chỉ để đánh giá trình độ dân tộc","B. Văn hoá chính trị là một trong những động lực cho sự phát triển","C. Văn hoá là bản sắc dân tộc","D. Văn hoá là niềm tin của quần chúng"],"answerLetter":"B","answerText":"B. Văn hoá chính trị là một trong những động lực cho sự phát triển","notes":""},{"id":602,"question":"Khi bàn về vấn đề đại đoàn kết toàn dân tộc, Hồ Chí Minh đi đến kết luận có tính tổng kết: \"Đoàn kết, đoàn kết, đại đoàn kết. Thành công, thành công, đại thành công\". Ý nghĩa của tổng kết này là gì?","options":["A. Nói về mục tiêu của đại đoàn kết toàn dân tộc","B. Nói về hình thức của đại đoàn kết toàn dân tộc","C. Nói về bản chất của đại đoàn kết toàn dân tộc","D. Nói về vai trò của đai đoàn kết toàn dân tôc"],"answerLetter":"D","answerText":"D. Nói về vai trò của đai đoàn kết toàn dân tôc","notes":""},{"id":603,"question":"Theo Hồ Chí Minh, đoàn kết phải căn cứ vào điều gì?","options":["A. Tự do","B. Phê bình","C. Đầu tranh","D. Lợi ích chung"],"answerLetter":"D","answerText":"D. Lợi ích chung","notes":""},{"id":604,"question":"Theo quan điểm của Hồ Chí Minh, nội dung xây dựng con người cần quan tâm xây dựng con người toàn diện như thế nào?","options":["A. Vừa \"hồng\" vừa \"chuyên\"","B. Vừa \"cần\" vừa \"kiệm\"","C. Vừa \"kiệm\" vừa \"liêm\"","D. Vừa \"chuyên\" vửa \"cần\""],"answerLetter":"A","answerText":"A. Vừa \"hồng\" vừa \"chuyên\"","notes":""},{"id":605,"question":"Hồ Chí Minh cho rằng phát triển giáo dục để làm gì?","options":["A. Nâng cao dân trí","B. Phát triển lâu dài","C. Chuẩn bị nhân tài","D. Mục tiêu bên vũng"],"answerLetter":"A","answerText":"A. Nâng cao dân trí","notes":""},{"id":606,"question":"Hồ Chí Minh vạch ra lực lượng cách mạng giải phóng dân tộc:","options":["A. Cách mạng là sự nghiệp của quần chúng bị áp bức","B. Cách mạng là sự nghiệp của công nông","C. Cách mạng là sự nghiệp của mọi người dân"],"answerLetter":"A","answerText":"A. Cách mạng là sự nghiệp của quần chúng bị áp bức","notes":""},{"id":607,"question":"Theo quan điểm của Hồ Chí Minh, tố chức nào sau đây có nhiệm vụ thực hiện sự khối đại đoàn kết toàn dân tộc?","options":["A. Mặt trận dân tộc thống nhất","B. Mặt trận dân chủ","C. Mặt trận nhãn dẫn","D. Mặt trận Việt Minh"],"answerLetter":"A","answerText":"A. Mặt trận dân tộc thống nhất","notes":""},{"id":608,"question":"Chủ trương cầu ngoại viện, dùng bạo lực để khôi phục độc lập dân tộc là đường lối của nhà yêu nước nào?","options":["A. Phan Bội Châu","B. Phan Chu Trinh","C. Hồ Chí Minh","D. Hoàng Hoa Thám"],"answerLetter":"A","answerText":"A. Phan Bội Châu","notes":""},{"id":609,"question":"Đối tượng chủ yếu của tư tưởng Hồ Chí Minh là:","options":["A. Cách mạng xã hội chủ nghĩa","B. Cách mạng Việt Nam","C. Cách mạng Đông Dương","D. Cách mạng dân tộc dân chủ nhân dân"],"answerLetter":"B","answerText":"B. Cách mạng Việt Nam","notes":""},{"id":610,"question":"Nội dung nào sau đây thuộc luận điểm sáng tạo của Hồ Chí Minh về vấn đề Đảng cộng sản?","options":["A. Về quy luật ra đời của Đảng Cộng sản Việt Nam","B. Về vấn đề tổ chức của Đảng Cộng sản Việt Nam","C. Về nguyên tắc xây dựng Đảng Cộng sản Việt Nam"],"answerLetter":"C","answerText":"C. Về nguyên tắc xây dựng Đảng Cộng sản Việt Nam","notes":""},{"id":611,"question":"Theo Hồ Chí Minh, vi trùng rất độc này đẻ ra... không dám đổi mới sáng tạo. Người đang đề cập đến vấn đề gì?","options":["A. Chủ nghĩa cá nhân","B. Đế quốc","C. Chủ nghĩa tư bản","D. Giặc đói"],"answerLetter":"A","answerText":"A. Chủ nghĩa cá nhân","notes":""},{"id":612,"question":"Luận điểm \"Không có sự đồng tình ủng hộ của đại đa số nhân dân lao động đối với đội tiền phong của mình tức là đối với giai cấp vô sản, thì cách mạng vô sản không thể thực hiện được\" là của ai?","options":["A. C. Mác","B. Ph. Ångghen","C. VI Lênin","D. Hồ Chí Minh"],"answerLetter":"C","answerText":"C. VI Lênin","notes":""},{"id":613,"question":"Đâu không phải là điểm giống nhau giữa chủ nghĩa xã hội và chủ nghĩa cộng sản theo Hồ Chí Minh?","options":["A. Sức sản xuất phát triển dựa trên chế độ tư hữu","B. Tư liệu sản xuất là của chung","C. Không còn giai cấp áp bức bóc lột","D. Năng suất lao động phát triển"],"answerLetter":"A","answerText":"A. Sức sản xuất phát triển dựa trên chế độ tư hữu","notes":""},{"id":614,"question":"Hồ Chí Minh cho rằng đoàn kết có ý nghĩa thế nào?","options":["A. Đoàn kết là yêu nước","B. Đoàn kết là sáng tạo","C. Đoàn kết là sức mạnh","D. Đoàn kết là khôn ngoan"],"answerLetter":"C","answerText":"C. Đoàn kết là sức mạnh","notes":""},{"id":615,"question":"Sức mạnh dân tộc trong tư tưởng Hồ Chí Minh bao gồm những thành tố nào?","options":["A. Chủ nghĩa yêu nước và văn hóa truyền thống Việt Nam Chủ nghĩa yêu nước và truyền thống văn hóa Việt Nam; tinh thần đoàn kết, ý thức đấu tranh cho độc lập, tự do; và tĩnh thần quốc tế vô sản","B. Tinh thần đoàn kết, ý thức đấu tranh cho độc lập, tự do","C. Ý chí tự lực, tự cường và tinh thần quốc tế vô sản","D. Chủ nghĩa yêu nước và truyền thống văn hóa Việt Nam; tinh thần đoàn kết, ý thức đấu tranh cho độc lập, tự do; và ý chí tự lực, tự cường"],"answerLetter":"D","answerText":"D. Chủ nghĩa yêu nước và truyền thống văn hóa Việt Nam; tinh thần đoàn kết, ý thức đấu tranh cho độc lập, tự do; và ý chí tự lực, tự cường","notes":""},{"id":616,"question":"Việt Nam Độc lập Đồng minh được thành lập vào thời gian nào?","options":["A. 19/5/1941","B. 19/5/1930","C. 26/3/1941","D. 3/9/1945"],"answerLetter":"A","answerText":"A. 19/5/1941","notes":""},{"id":617,"question":"Theo Hồ Chí Minh cho rằng đạo đức cách mạng không phải là điều gì?","options":["A. Từ trên trời sa xuống","B. Phẩm chất vốn có","C. Tự nhiên mà có","D. Có sẵn trong tự nhiên"],"answerLetter":"A","answerText":"A. Từ trên trời sa xuống","notes":""},{"id":618,"question":"Theo Hồ Chí Minh, đường lối của nhà yêu nước nào còn \"nặng cốt cách phong kiến\"?","options":["A. Phan Châu Trinh","B. Phan Bội Châu","C. Hoàng Hoa Thám","D. Nguyễn Thái Học"],"answerLetter":"C","answerText":"C. Hoàng Hoa Thám","notes":""},{"id":619,"question":"Hồ Chí Minh cho rằng công tác cán bộ cần chú ý.","options":["A. Hiểu và đánh giá đúng đảng viên","B. Hiểu và đánh giá đúng cán bộ","C. Hiểu và đánh giá đúng quần chúng"],"answerLetter":"B","answerText":"B. Hiểu và đánh giá đúng cán bộ","notes":""},{"id":620,"question":"Nội dung cốt lõi của tư tưởng Hồ Chí Minh về mối quan hệ giữa độc lập dân tộc và chủ nghĩa xã hội là gì?","options":["A. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội, chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","B. Hồ Chí Minh đã chỉ ra độc lập dân tộc là bao gồm cả nội dung dân tộc và dân chủ","C. Độc lập dân tộc mà dân vẫn không có cơm ăn, áo mặc, không được học hành thì độc lập đó không có ý nghĩa gì","D. Cuộc cách mạng giải phóng dân tộc ở Việt Nam ngay từ đầu đã được Hồ Chí Minh xác định đi theo con đường cách mạng vô sản"],"answerLetter":"A","answerText":"A. Độc lập dân tộc là cơ sở, tiền đề để tiến lên chủ nghĩa xã hội, chủ nghĩa xã hội là điều kiện để bảo đảm nền độc lập dân tộc vững chắc","notes":""},{"id":621,"question":"Điều kiện thực hiện khối đại đoàn kết tư tưởng Hồ Chí Minh về khối đại đoàn kết dân tộc?","options":["A. Truyền thống yêu thiên nhiên","B. Truyền thống yêu con người","C. Truyền thống yêu nước, nhân ái, tinh thần cố kết cộng đồng","D. Truyền thống yêu hoà bình"],"answerLetter":"C","answerText":"C. Truyền thống yêu nước, nhân ái, tinh thần cố kết cộng đồng","notes":""},{"id":622,"question":"Con người xã hội chủ nghĩa theo Hồ Chí Minh đó là","options":["A. Có tư tưởng và tác phong xã hội chủ nghĩa\"","B. Những người nằm trong xã hội chủ nghĩa\"","C. Có ý thức xây dựng đất nước\"","D. Chăm lao động\""],"answerLetter":"B","answerText":"B. Những người nằm trong xã hội chủ nghĩa\"","notes":""},{"id":623,"question":"Theo quan điểm của Hồ Chí Minh, đại đoàn kết dân tộc là một mục tiêu, nhiệm vụ hàng đầu của cách mạng Việt Nam và đồng thời cách mạng là sự nghiệp của ai?","options":["A. Của quần chúng, do quần chúng và vì quần chúng","B. Của dân, do dân và vì dân","C. Của người lao động nói chung","D. Của công - nông - trí"],"answerLetter":"A","answerText":"A. Của quần chúng, do quần chúng và vì quần chúng","notes":""},{"id":624,"question":"Vì sao Hồ Chí Minh lại khẳng định: đại đoàn kết toàn dân tộc phải được xác định là nhiệm vụ hàng đầu của Đảng?","options":["A. Vì đại đoàn kết toàn dân tộc không chi là khẩu hiệu chiến lược, mà còn là mục đích của cách mạng cần phải được quán triệt trong tất cả mọi lĩnh vực, từ đường lối, chủ trương, chính sách tới hoạt động thực tiễn của Đảng","B. Vì Đảng là lực lượng vận động, thuyết phục và hướng dẫn quần chúng nhân dân","C. Vì Đảng là lực lượng lãnh đạo cách mạng Việt Nam","D. Vì Đảng là lực lượng giáo dục, giác ngộ quần chúng nhân dân và liên lạc với vô sản các nước"],"answerLetter":"A","answerText":"A. Vì đại đoàn kết toàn dân tộc không chi là khẩu hiệu chiến lược, mà còn là mục đích của cách mạng cần phải được quán triệt trong tất cả mọi lĩnh vực, từ đường lối, chủ trương, chính sách tới hoạt động thực tiễn của Đảng","notes":""},{"id":625,"question":"Tóm tắt nội dung chữ \"Cần\" theo tư tưởng Hồ Chí Minh là gì?","options":["A. Cần tức là lao động cần cù, siêng năng; lao động có kế hoạch, sáng tạo, có năng suất cao","B. Cần tức là siêng năng, chịu khó, cố gắng hoàn thành công việc","C. Cần tức là làm việc cần mẫn, giành nhiều thời gian cho công việc","D. Cần tức là siêng năng, cố gắng, tích cực trong công tác"],"answerLetter":"A","answerText":"A. Cần tức là lao động cần cù, siêng năng; lao động có kế hoạch, sáng tạo, có năng suất cao","notes":""},{"id":626,"question":"Điểm khác biệt giữa tinh thần nhân ái của Hồ Chí Minh và Khổng Từ ở chỗ","options":["A. Không chỉ tình thương cho dân tộc mình, mà còn cho các dân tộc khác","B. Không chỉ tình thương cho con người, mà còn cho cả giai cấp","C. Không chỉ tình thương cho đồng bào, mà còn cho cả nhân loại","D. Không chỉ thình thương giai cấp minh, mà còn cho các giai cấp khác"],"answerLetter":"C","answerText":"C. Không chỉ tình thương cho đồng bào, mà còn cho cả nhân loại","notes":""},{"id":627,"question":"Nhận định nào sau đây đúng với khải niệm con người trong tư tưởng Hồ Chí Minh?","options":["A. Dùng để chỉ con người chung chung","B. Dùng đẽ chỉ một cộng đông người","C. Dùng để chỉ con người cụ thế gắn với hoàn cảnh lịch sử cụ thế","D. Dùng để chỉ con người trừu tượng"],"answerLetter":"C","answerText":"C. Dùng để chỉ con người cụ thế gắn với hoàn cảnh lịch sử cụ thế","notes":""},{"id":628,"question":"Hồ Chí Minh cho rằng thầy giáo, cô giáo trong chế độ ta cần phải góp phần vào:","options":["A. Công cuộc xây dựng CNXH","B. Công cuộc kháng chiến chống Mỹ cứu nước","C. Công cuộc xây dựng xã hội mới"],"answerLetter":"A","answerText":"A. Công cuộc xây dựng CNXH","notes":""},{"id":629,"question":"Đâu là quan điểm của Hồ Chí Minh về văn hóa?","options":["A. Theo Hồ Chí Minh, văn hóa không thụ động, ngồi chờ cho kinh tế phát triển. Phát triển văn hóa tạo điều kiện thúc đẩy phát triển kinh tế","B. Theo Hồ Chí Minh, văn hóa không thụ động, ngồi chờ cho kinh tế phát triển. Phát triển văn hóa tạo điều kiện thúc đẩy phát triển xã hội","C. Theo Hồ Chí Minh, văn hóa không thụ động, ngồi chờ cho kinh tế phát triển. Phát triển văn hóá tạo điều kiện thúc đẩy phát triển chính trị","D. Theo Hồ Chí Minh, văn hóa không thụ động, ngồi chờ cho kinh tế phát triển. Phát triển văn hóá tạo điều kiện thúc đẩy phát triển thiết chế pháp luật"],"answerLetter":"A","answerText":"A. Theo Hồ Chí Minh, văn hóa không thụ động, ngồi chờ cho kinh tế phát triển. Phát triển văn hóa tạo điều kiện thúc đẩy phát triển kinh tế","notes":""},{"id":630,"question":"Đề cập đến vấn đề dân tộc thuộc địa, khác với Mác và Lênin, Hồ Chí Minh bàn nhiều về cuộc đấu tranh nào:","options":["A. Chống chủ nghĩa phát xít, giải phóng giai cấp","B. Chống địa chủ phong kiến, giải phóng cho nông dân","C. Chống chủ nghĩa thực dân, đầu tranh giải phóng dân tộc ở thuộc địa","D. Chống chủ nghĩa tư bản, giải phóng cho giai cấp"],"answerLetter":"C","answerText":"C. Chống chủ nghĩa thực dân, đầu tranh giải phóng dân tộc ở thuộc địa","notes":""},{"id":631,"question":"Quan điểm nào dưới đây là phương thức tiếp cận về chủ nghĩa xã hội của Hồ Chí Minh?","options":["A. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện đạo đức. Chủ nghĩa xã hội là đối lập với chủ nghĩa cá nhân.","B. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện đạo đức. Chủ nghĩa xã hội là đối lập với chủ nghĩa nhân văn.","C. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện đạo đức. Chủ nghĩa xã hội là đối lập với chủ nghĩa vị lợi.","D. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện đạo đức. Chủ nghĩa xã hội là đối lập với chủ nghĩa vị kỷ."],"answerLetter":"A","answerText":"A. Hồ Chí Minh tiếp cận chủ nghĩa xã hội từ phương diện đạo đức. Chủ nghĩa xã hội là đối lập với chủ nghĩa cá nhân.","notes":""},{"id":632,"question":"Người cho rằng: \"Trước mặt quần chúng, không phải ta cứ viết lên trán chữ \"cộng sản\" mà ta được họ yêu mến. Quần chúng chi quý mến những người có...\". Từ nào còn thiếu trong câu trên?","options":["A. tư cách, đạo đức","B. tư cách, học thức","C. đạo đức, học thức","D. uy quyền, đạo đức"],"answerLetter":"A","answerText":"A. tư cách, đạo đức","notes":""},{"id":633,"question":"\"Đến ngày thắng lợi, nhân dân ta sẽ xây dựng lại đất nước ta đàng hoàng hơn, to đẹp hơn!”. Điều khẳng định trên được Hồ Chí Minh nêu ra tại văn kiện nào sau đây?","options":["A. Lời kêu gọi toàn quốc kháng chiến","B. Bài phát biểu tại lễ kỷ niệm 30 năm thành lập Đảng","C. Lời kêu gọi đồng bào và chiến sĩ cả nước","D. Di chúc"],"answerLetter":"C","answerText":"C. Lời kêu gọi đồng bào và chiến sĩ cả nước","notes":""},{"id":634,"question":"Để có thể biến sức mạnh tinh thần đoàn kết thành sức mạnh vật chất, theo Hồ Chí Minh cần xây dựng tổ chúc nào?","options":["A. Đàng Cộng sản","B. Quân đội","C. Nhà nước","D. Mặt trận dân tộc thống nhất"],"answerLetter":"D","answerText":"D. Mặt trận dân tộc thống nhất","notes":""},{"id":635,"question":"\"Đạo đức cách mạng không phải trên trời sa xuống. Nó do đấu tranh, rèn luyện bền bỉ hàng ngày mà phát triển và củng cố. Cũng như ngọc càng mài càng sáng, vàng càng luyện càng trong\". Luận điểm trên đây diễn đạt nội dung nào trong tư tưởng Hồ Chí Minh về đạo đức?","options":["A. Vai trò của đạo đức cách mạng","B. Nguyên tắc xây dựng đạo đức mới","C. Nội dung của đạo đức cách mạng","D. Tất cả các phương án"],"answerLetter":"B","answerText":"B. Nguyên tắc xây dựng đạo đức mới","notes":""},{"id":636,"question":"Chủ tịch Hồ Chí Minh là hiện thân cho tinh thần dân tộc ta, Người đã nói rằng: Cái mà tôi cần nhất trên đời là đồng bào tôi được tự do, \"...\". Chọn đáp án đúng nhất điền vào dấu \"...\" là?","options":["A. Tổ quốc tôi được độc lập.","B. Đất nước tôi được thống nhất.","C. Tổ quốc tôi được bình đẳng.","D. Đất nước tôi được phát triển"],"answerLetter":"A","answerText":"A. Tổ quốc tôi được độc lập.","notes":""},{"id":637,"question":"\"Nếu nước độc lập mà dân không hưởng hạnh phúc tự do, thì độc lập cũng chẳng có nghĩa lý gì\". Trích dẫn trên đề cập đến nội dung gì trong tư tưởng Hồ Chí Minh?","options":["A. Độc lập dân tộc gắn liền với chủ nghĩa xã hội","B. Về sức mạnh của nhân dân, của khối đại đoàn kết dân tộc","C. Tư tưởng về phát triển kinh tế và văn hoá","D. Tu dưỡng, rèn luyện đạo đức suốt đời"],"answerLetter":"A","answerText":"A. Độc lập dân tộc gắn liền với chủ nghĩa xã hội","notes":"(Kiểu hỏi khác:\n- Con đường cứu nước của Hồ Chí Minh là:\n- Nội dung cốt lõi của tư tưởng Hồ Chí Minh là: )"},{"id":638,"question":"Kiểm soát quyền lực Nhà nước và phòng, chống tiêu cực trong Nhà nước, được xác định là nội dung nào trong tư tưởng Hồ Chí Minh về Nhà nước của nhân dân, do nhân dân, vì nhân dân?","options":["A. Nhà nước dân chủ","B. Nhà nước pháp quyền","C. Nhà nước trong sạch, vững mạnh","D. Xây dựng nhà nước"],"answerLetter":"C","answerText":"C. Nhà nước trong sạch, vững mạnh","notes":""},{"id":639,"question":"Lựa chọn cụm từ đúng điền vào chỗ trống: \"Hồ Chí Minh cho rằng, đối với các dân tộc phương Đông vốn . . . . , việc tu dưỡng đạo đức của mỗi cá nhân, mỗi con người có vai trò vô cùng . . . .\" [Giáo trình Tư tưởng Hồ Chí Minh (Dành cho bậc đại học không chuyển lý luận chính trị), Nxb. CTQG Sự thật, H, 2021. Tr 136]","options":["A. Giàu tình cảm, trọng đạo lý; quan trọng","B. Giàu tình cảm, trong tình nghĩa, quan trọng","C. Giàu tình cảm, trong tình nghĩa, ý nghĩa","D. Giàu cảm xúc, trong tình nghĩa, ý nghĩa"],"answerLetter":"A","answerText":"A. Giàu tình cảm, trọng đạo lý; quan trọng","notes":""},{"id":640,"question":"Trong Chánh cương vắn tắt của Đảng năm 1930, Hồ Chí Minh cũng đã xác định mục tiêu chính trị của Đảng là?","options":["A. Đánh đổ để quốc chủ nghĩa Pháp\"","B. Làm cho nước Nam được hoàn toàn độc lâp\"","C. Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến\"","D. Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến. Làm cho nước Nam được hoàn toàn độc lập\""],"answerLetter":"D","answerText":"D. Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến. Làm cho nước Nam được hoàn toàn độc lập\"","notes":""},{"id":641,"question":"Theo Hồ Chí Minh, văn hoá phải sữa đổi được những thói xấu nào?","options":["A. Tham nhũng","B. Lưới biếng","C. Phù hoa, xa xi","D. Tâm lý tiểu nông"],"answerLetter":"ABC","answerText":"A. Tham nhũng, B. Lười biếng, C. Phù hoa, xa xỉ","notes":"ABC\nTrong tư tưởng Hồ Chí Minh, quan điểm nào về mối quan hệ giữa Đảng Cộng sản và nhân dẫn được thế hiện rõ nhất?(NHUNG HOÀNG)\nA. Nhân dân là nguồn gốc và động lực của Đảng\nB. Đảng phải lãnh đạo nhân dân trong mọi lĩnh vực\nC. Đảng phụ thuộc hoàn toàn vào ý kiến nhân dân\nD. Nhân dân chỉ là đối tượng phục vụ của Đảng"},{"id":642,"question":"Trong tư tưởng Hồ Chí Minh đã tiếp thu về hành động, tư tưởng nhập thế, hành động, giúp đời; ước vọng về một xã hội bình trị, hoà mực, hoà đồng; triết lý nhân sinh; tu thân dưỡng tính; đề cao văn hoá lễ giáo, tạo ra truyền thống hiếu học từ triết lý nào?","options":["A. Phật giáo","B. Nho giáo","C. Chủ nghĩa Tam dân","D. Công giáo"],"answerLetter":"B","answerText":"B. Nho giáo","notes":""},{"id":643,"question":"Hồ Chí Minh bắt đầu quan tâm đến khẩu hiệu \"Tự do - Bình đẳng - Bác ái\" của Đại Cách mạng Pháp từ khi nào?","options":["A. Học sinh tiểu học","B. Học sinh trường Quốc học Huế","C. Thầy giáo dạy học ở trường Dục Thanh","D. Khi đặt chân đến nước Pháp"],"answerLetter":"A","answerText":"A. Học sinh tiểu học","notes":""},{"id":644,"question":"Chọn phương án chính xác nhất: Trong Bài nói tại Đại hội sinh viên Việt Nam lần thứ hai (7-5-1958), Hồ Chí Minh đã xác định những phẩm chất cho thanh niên, sinh viên Việt Nam là","options":["A. Yêu Tổ quốc, yêu nhân dân","B. Yêu Tổ quốc, yêu nhân dân, yêu chủ nghĩa xã hội","C. Yêu Tổ quốc, yêu nhân dân, yêu chủ nghĩa xã hội, yêu lao động","D. Yêu Tổ quốc, yêu nhân dân, yêu chủ nghĩa xã hội, yêu lao động, yêu khoa học và kỷ luật"],"answerLetter":"D","answerText":"D. Yêu Tổ quốc, yêu nhân dân, yêu chủ nghĩa xã hội, yêu lao động, yêu khoa học và kỷ luật","notes":""},{"id":645,"question":"Theo Hồ Chí Minh, sau khi hoàn thành bình định Việt Nam về mặt quân sự và bắt tay vào khai thác thuộc địa, thực dân Pháp đã biến nước ta từ một nước phong kiến thành nước như thế nào?","options":["A. Thuộc địa và phong kiến","B. Phong kiến nửa thuộc địa","C. Phong kiến tập quyền","D. Phong kiến phân quyền"],"answerLetter":"A","answerText":"A. Thuộc địa và phong kiến","notes":""},{"id":646,"question":"Theo Hồ Chí Minh: Đây là thời kỳ cải biến sâu sắc nhất nhưng phức tạp, lâu dài, khó khăn, gian khổ. Quan điểm này nói về nội dung nào?","options":["A. Tính chất, đặc điểm của thời kỳ quá độ.","B. Đặc điểm của thời kỳ quá độ","C. Nhiệm vụ của thời kỳ quá độ.","D. Tính chất của thời kỳ quá độ"],"answerLetter":"D","answerText":"D. Tính chất của thời kỳ quá độ","notes":""},{"id":647,"question":"Theo giáo trình Tư tưong Hồ Chí Minh, cống hiến lý luận lớn đầu tiên của Người vào kho tàng lý luận chủ nghĩa Mác - Lênin là về vấn đề nào?","options":["A. Cách mạng giải phóng dân tộc","B. Cách mạng xã hội chủ nghĩa","C. Cách mạng tư sản dân quyền","D. Cách mạng ruộng đất"],"answerLetter":"A","answerText":"A. Cách mạng giải phóng dân tộc","notes":""},{"id":648,"question":"Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến vào thời gian nào?","options":["A. 2/9/1945","B. 19/12/1946","C. 12/9/1946","D. 12/1/1945"],"answerLetter":"B","answerText":"B. 19/12/1946","notes":""},{"id":649,"question":"Tác phẩm nào của Hồ Chí Minh được coi là sự chuẩn bị mọi mặt về chính trị, tư tưởng, tổ chức cho sự ra đời của Đàng Cộng sản Việt Nam?","options":["A. Yêu sách của nhân dân An Nam","B. Đảng Cộng sản và vấn đề thuộc địa","C. Bản án chế độ thực dân Pháp","D. Đường Cách mệnh"],"answerLetter":"D","answerText":"D. Đường Cách mệnh","notes":""},{"id":650,"question":"Hồ Chí Minh đẫ tìm thấy và xác định rõ phương hướng đấu tranh giải phóng dân tộc Việt Nam theo con đuờng cách mạng vô sản thông qua sự kiện nào sau đây?","options":["A. Tham gia hoạt động trong Đảng Xã hội Pháp","B. Gửi Yêu sách của nhân dân An Nam tới Hội nghị Vecxay","C. Đọc Sơ thào lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa","D. Tham gia Đại hội Tua, sáng lập Đang Cộng sản Pháp, trở thành người cộng sản Việt Nam đầu tiên"],"answerLetter":"C","answerText":"C. Đọc Sơ thào lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa","notes":""},{"id":651,"question":"Thực dân Pháp bắt đầu tiến hành xâm lược Việt Nam từ năm nào?","options":["A. 1858","B. 1958","C. 1854","D. 1945"],"answerLetter":"A","answerText":"A. 1858","notes":""},{"id":652,"question":"Hồ Chí Minh đã nhận định điều gì về mối liên hệ giữa văn hóa và chính trị?","options":["A. Văn hóa là nền tàng tư tưởng cho chính trị","B. Văn hóa là tách biệt với chính trị","C. Văn hóa không ành hưởng đến chính trị","D. Chính trị quyết định mọi hoạt động văn hóa"],"answerLetter":"A","answerText":"A. Văn hóa là nền tàng tư tưởng cho chính trị","notes":""},{"id":653,"question":"Hồ Chí Minh khẳng định \"Không có gì quý hơn độc lập, tự do\" khi đất nước đang tiến hành chiến tranh chống thế lực nào?","options":["A. Thực dân Pháp","B. Phát xít Nhật","C. Đế quốc Mỹ","D. Phong kiến"],"answerLetter":"C","answerText":"C. Đế quốc Mỹ","notes":""}]
  };
})();
